using HonkSharp.Fluency;
using static AngouriMath.Entity;
using System.Linq;
using System.Collections.Generic;
using PeterO.Numbers;

namespace AngouriMath.Functions.Algebra
{
    internal static class IndefiniteIntegralSolver
    {
        internal static Entity? SolveBySplittingSum(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // The terms as written first, and expanded only if one of those fails: expanding
            // `(1 + 1/x)/(x + ln(x))^(3/2)` writes it as two terms, neither of which is the
            // substitution `u = x + ln(x)` the unexpanded one is, and Bronstein's
            // `1/x + (1 + 1/x)/(x + ln(x))^(3/2)` was declined for that while each of its two
            // terms alone was answered.
            // And a sum over a denominator likewise, each written term over it with a factor
            // written on both sides cancelled: `(ln(x^2 + 1) (x^2 + 1) - x^2)/(2 (x^2 + 1))` is
            // what parts leaves from `x ln(1 + x^2) arctan(x)`, and expanded its first term is
            // `x^2 ln(x^2 + 1)/(2 (x^2 + 1))` and its second `ln(x^2 + 1)/(2 (x^2 + 1))`, neither
            // elementary, where as written it is `ln(x^2 + 1)/2`.
            var (writtenSum, over) = expr is Divf(var writtenNumerator, var writtenDenominator) && writtenNumerator is Sumf or Minusf && writtenDenominator.ContainsNode(x)
                ? (writtenNumerator, writtenDenominator) : (expr, Number.Integer.One as Entity);
            if (writtenSum is Sumf or Minusf)
            {
                // In the order the expanding gather uses -- the terms in the variable, then
                // what is free of it as one term -- so that the answer reads the same either way.
                // And only for terms of modest size: a partial-fraction term whose coefficient
                // is a page of unsimplified symbols took sixty seconds of every rule
                // simplifying the page for itself, where the expanding gather below tidies
                // its terms as it goes and takes half a second on the same sum.
                var inTheVariable = Sumf.LinearChildren(writtenSum).Where(term => term.ContainsNode(x)).ToList();
                var free = Sumf.LinearChildren(writtenSum).Where(term => !term.ContainsNode(x)).ToList();
                var asWritten = new List<Entity>(inTheVariable);
                if (free.Count > 0)
                    asWritten.Add(free.Aggregate((l, r) => l + r));
                if (over != Number.Integer.One)
                    asWritten = asWritten.Select(term => CancelCommonFactors(term, over)).ToList();
                if (asWritten.Count >= 2 && asWritten.All(term => term.Complexity <= LargestTermTakenAsWritten)
                    && Integrated(asWritten) is { } termByTerm)
                    return termByTerm;
            }
            // A sum above the bar that is the derivative of a factor below it is not expanded:
            // `(e^x + e^-x)/(e^x - e^-x)^4` -- `cosh/sinh^4` as the library writes it -- is
            // `f'/f^4`, one substitution, and expanded it is two terms whose antiderivatives
            // carry logarithms that cancel only together. Beside another factor the pair is
            // what parts reads: Timofeev's `arccot(cosh x) cosh x/sinh^4 x` was expanded into
            // two products first, each of them a step of parts with a logarithm-laden `v` and
            // a remainder that took thirty seconds to decline.
            if (IsADerivativeOfAFactorBelowTheBar(expr, x))
                return null;
            // A logarithm or an inverse trigonometric function times a rational function of x
            // goes to parts against the whole rational function before the rational function
            // is expanded into terms: each term's antiderivative keeps a logarithm the whole's
            // does not, and a step of parts against a term is a remainder with that logarithm
            // beside the derivative of the other function, a dilogarithm's shape that every
            // rule below spends itself declining. Timofeev's `arccot(cosh x) cosh x/sinh^4 x`
            // under `u = e^x` is `8 arccot((u + 1/u)/2) (u^4 + u^2)/(u^2 - 1)^4`, answered by one
            // step of parts against the rational function and ten seconds of declines on its
            // two terms first. The same stance as the polynomial times a rational function of
            // an exponential, at the top of the chain. Where parts is allowed at all: a step
            // of parts hands its own integral down with parts switched off, and Timofeev's
            // `arcsin(sinh x) sech^4 x` -- `arcsin((u - 1/u)/2) u^3/(u^2 + 1)^4` -- has a first
            // pairing that differentiates `u^3` and is meant to decline in a moment, where
            // parts on what it hands down was a two-minute search.
            if (integrateByParts && IsAnInverseFunctionTimesARationalFunction(expr, x) && SolveIntegratingByParts(expr, x) is { } byParts)
                return byParts;
            var splitted = TreeAnalyzer.GatherLinearChildrenOverSumAndExpand(expr, e => e.ContainsNode(x));
            if (splitted is null || splitted.Count < 2) return null; // nothing to do, let other solvers do the work
            // Each expanded term with a factor written on both sides of its bar cancelled:
            // `x sqrt(1 - x^2)/(sqrt(1 - x^2)(2 + 2x sqrt(1 - x^2)))` is what the expansion makes
            // of one term of the by-parts remainder of `arctan(x + sqrt(1 - x^2))`, and the
            // chain's own normalisation collects that root over itself into `(1 - x^2)^0`, a
            // factor no rule that reads a root of a quadratic sees through.
            var cancelledTerms = splitted.Select(term =>
            {
                var (above, below) = Functions.SingleQuotient.Of(term);
                return below == Number.Integer.One ? term : CancelCommonFactors(above, below);
            }).ToList();
            if (Integrated(cancelledTerms) is { } termByExpandedTerm)
                return termByExpandedTerm;
            // The expanded terms gathered again by what is not polynomial in them, and each
            // group asked as one term: Hearn's
            // `(-2 sqrt(1 + x^3) + 5x^4 sqrt(1 + x^3) - 3x^2 sqrt(1 - 2x + x^5))/(2 sqrt(1 + x^3) sqrt(1 - 2x + x^5))`
            // expands to `-1/sqrt(P)`, `5x^4/(2 sqrt(P))` and `-3x^2/(2 sqrt(1 + x^3))`, of which
            // the first two are not elementary apart and are `P'/(2 sqrt(P))` together. Only
            // where the gathering joins something and separates something: with every term
            // in a group of its own this is the split above, which has just failed, and with
            // every term in one group it is the integrand. And asked, not volunteered: each
            // group is a search of its own, and one level down the sums are what by parts
            // and the substitutions hand on, where the groups cost sixteen seconds of the
            // corpus for nothing.
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // What is polynomial in a term is what has no root of the variable in it: a
            // logarithm or an exponential of x is an indeterminate as far as gathering and
            // cancelling go. Bronstein's
            // `(x^2 + 2x ln(x) + ln(x)^2 + (1 + x) sqrt(x + ln(x)))/(x^3 + 2x^2 ln(x) + x ln(x)^2)`
            // expands to three terms with no root and one with, and the three are `1/x`
            // together -- `(x + L)^2` over `x (x + L)^2` with `L` for the logarithm -- and
            // nothing apart.
            var groups = new List<(Entity Radicals, Entity Below, Entity Polynomial)>();
            foreach (var term in splitted)
            {
                var (above, below) = Functions.SingleQuotient.Of(term);
                Entity polynomial = Number.Integer.One;
                Entity radicals = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(above))
                    if (!factor.ContainsNode(x) || !HasARadicalOf(factor, x))
                        polynomial = polynomial * factor;
                    else
                        radicals = radicals * factor;
                var index = groups.FindIndex(group => group.Radicals == radicals && group.Below == below);
                if (index < 0)
                    groups.Add((radicals, below, polynomial));
                else
                    groups[index] = (radicals, below, groups[index].Polynomial + polynomial);
            }
            // Two groups at least: one group is the integrand gathered back into itself, and
            // that has been asked.
            if (groups.Count >= splitted.Count || groups.Count < 2)
                return null;
            return Integrated(groups.Select(group =>
            {
                // Each group's quotient cancelled with the functions of x as indeterminates,
                // and its denominator written in square-free factors the same way, so that
                // `x (x + ln(x))^2` is seen as the factors it is.
                var (top, bottom) = CancelledWithFunctionsAsIndeterminates(group.Polynomial.InnerSimplified, group.Below, x, expr);
                return ((top * group.Radicals).InnerSimplified / bottom).InnerSimplified;
            }).ToList());

            Entity? Integrated(List<Entity> terms)
                => terms.Select(e => Integration.ComputeAsAQuestionOfItsOwn(e, x, integrateByParts)).Aggregate((e1, e2) => (e1, e2) switch {
                    (null, _) or (_, null) => null,
                    (var int1, var int2) => int1 + int2
                });
        }

        /// <summary>The largest term a sum is split over as written, before the expanding gather.</summary>
        private const int LargestTermTakenAsWritten = 60;

        /// <summary>
        /// Whether the integrand is one logarithm or inverse trigonometric function of
        /// <paramref name="x"/>, or a whole power of one, times a rational function of
        /// <paramref name="x"/> that is not a polynomial.
        /// </summary>
        private static bool IsAnInverseFunctionTimesARationalFunction(Entity expr, Entity.Variable x)
        {
            var (above, below) = Functions.SingleQuotient.Of(expr);
            if (!below.ContainsNode(x))
                return false;
            var inverse = 0;
            foreach (var factor in Mulf.LinearChildren(above).Concat(Mulf.LinearChildren(below)))
            {
                if (!factor.ContainsNode(x))
                    continue;
                var @base = factor is Powf(var inner, Number.Integer) ? inner : factor;
                if (@base is Logf or Arcsinf or Arccosf or Arctanf or Arccotanf or Arcsecantf or Arccosecantf)
                    inverse++;
                else if (!IsRationalIn(factor, x))
                    return false;
            }
            return inverse == 1;
        }

        /// <summary>
        /// An integrand that is a constant multiple of <c>D'/D</c> for a sum <c>D</c> below the
        /// bar holding a root, decided at sampled points and answered as that multiple of
        /// <c>ln(D)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Hearn's <c>x((x^2 - 1) sqrt(x^2 - 4) + (x^2 - 4) sqrt(x^2 - 1))/((x^2 - 1)(x^2 - 4)(1 + sqrt(x^2 - 4) + sqrt(x^2 - 1)))</c>
        /// is <c>(x/sqrt(x^2 - 4) + x/sqrt(x^2 - 1))/(1 + sqrt(x^2 - 4) + sqrt(x^2 - 1))</c>, the
        /// derivative of its denominator over it, and the substitution that reads
        /// <c>u = D</c> was declined for the quotient by <c>D'</c> it could not simplify --
        /// <c>(x^2 - 1) sqrt(x^2 - 4)/((x^2 - 1)(x^2 - 4))</c> is <c>1/sqrt(x^2 - 4)</c> only
        /// with the root's square read as the radicand -- and the search around it ran past
        /// the budget. The quotient <c>f D/D'</c> is evaluated at points instead: where it is
        /// the same rational number at each, <c>f</c> is that number times <c>D'/D</c>, and the
        /// answer is checked against the integrand at sampled points before it is returned,
        /// as the ansätze check theirs.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveALogarithmicDerivativeOfARadicalSum(Entity expr, Entity.Variable x)
        {
            var (_, below) = Functions.SingleQuotient.Of(expr);
            if (below == Number.Integer.One)
                return null;
            foreach (var factor in Mulf.LinearChildren(below))
            {
                if (factor is not (Sumf or Minusf) || !factor.ContainsNode(x) || !HasARadicalOf(factor, x))
                    continue;
                var derivative = factor.Differentiate(x).InnerSimplified;
                if (derivative is Providedf(var bare, _))
                    derivative = bare;
                var quotient = expr * factor / derivative;
                Number? constant = null;
                var agreed = 0;
                foreach (var at in new[] { "2.29", "3.43", "5.71", "0.37", "-2.61", "-4.13" })
                {
                    if (quotient.Substitute(x, Number.Real.Create(EDecimal.FromString(at))).Evaled is not Number.Real real || !real.EDecimal.IsFinite)
                        continue;
                    if (constant is null)
                    {
                        // The number as a rational, where it is one within the evaluation's
                        // precision; otherwise this is not the shape.
                        if (Number.Real.Create(real.EDecimal) is not Number.Rational rational)
                            break;
                        constant = rational;
                        agreed = 1;
                        continue;
                    }
                    if ((real - constant).Evaled is not Number.Real realDifference || constant.Evaled is not Number.Real realConstant
                        || realDifference.EDecimal.Abs().CompareTo(EDecimal.FromString("1e-20").Multiply(EDecimal.Max(EDecimal.One, realConstant.EDecimal.Abs()))) > 0)
                    {
                        agreed = 0;
                        break;
                    }
                    agreed++;
                }
                if (constant is null || agreed < 3 || TreeAnalyzer.IsZero(constant))
                    continue;
                Entity answer = constant == Number.Integer.One ? MathS.Ln(factor) : constant * MathS.Ln(factor);
                if (Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                    return answer;
            }
            return null;
        }

        /// <summary>
        /// The signs and moduli of one real-valued argument among the factors of a product
        /// gathered into a power of the argument and at most one sign: <c>|a|^k</c> is
        /// <c>sgn(a)^k a^k</c> for a real <c>a</c>, so <c>sgn(a)^m |a|^k</c> is
        /// <c>sgn(a)^((m + k) mod 2) a^k</c>, and <c>sgn(a)^2</c> is <c>1</c> -- away from
        /// <c>a = 0</c>, which is the generic case every rule answers in.
        /// </summary>
        /// <remarks>
        /// The secant substitution answers <c>1/(x^2 (x^2 - 1)^(5/2))</c> in <c>|x|</c> and
        /// <c>sgn(x)</c>, and a step of parts against it -- Timofeev's
        /// <c>arccsc(x)/(x^2 (x^2 - 1)^(5/2))</c> -- leaves a remainder with <c>|x|^4</c>,
        /// <c>|x|^2</c> and <c>sgn(x)/|x|</c> in it that no rule reads, where it is
        /// <c>x^4</c>, <c>x^2</c> and <c>1/x</c>. Applied with the gathering of powers on every
        /// entry to the chain, for the same reason: the shape is the integrator's own.
        /// </remarks>
        internal static Entity GatherSignsAndModuli(Entity node, Entity.Variable x)
        {
            if (node is not (Mulf or Divf))
                return node;
            var signs = new Dictionary<Entity, EInteger>();
            var moduli = new Dictionary<Entity, EInteger>();
            var rest = new List<Entity>();
            foreach (var factor in Mulf.LinearChildren(node))
            {
                var (@base, exponent) = factor is Powf(var inner, Number.Integer whole) ? (inner, whole.EInteger) : (factor, EInteger.One);
                if (@base is Signumf(var signed) && signed.ContainsNode(x))
                    signs[signed] = signs.TryGetValue(signed, out var m) ? m.Add(exponent) : exponent;
                else if (@base is Absf(var measured) && measured.ContainsNode(x))
                    moduli[measured] = moduli.TryGetValue(measured, out var k) ? k.Add(exponent) : exponent;
                else
                    rest.Add(factor);
            }
            // Something to gather: a modulus beside a sign of the same argument, or a power
            // of either beyond the first.
            var arguments = signs.Keys.Concat(moduli.Keys).Distinct().ToList();
            if (!arguments.Any(argument =>
                    signs.TryGetValue(argument, out var m) && moduli.ContainsKey(argument)
                    || signs.TryGetValue(argument, out m) && m.Abs().CompareTo(EInteger.One) > 0
                    || moduli.TryGetValue(argument, out var k) && k.Abs().CompareTo(EInteger.One) > 0))
                return node;
            Entity? rebuilt = null;
            void Multiply(Entity factor) => rebuilt = rebuilt is null ? factor : rebuilt * factor;
            foreach (var argument in arguments)
            {
                signs.TryGetValue(argument, out var m);
                moduli.TryGetValue(argument, out var k);
                m ??= EInteger.Zero;
                k ??= EInteger.Zero;
                if (!TreeAnalyzer.IsRealValued(argument, x))
                {
                    // Not gathered: |a| is sgn(a) a only for a real a.
                    if (!m.IsZero) Multiply(m.Equals(EInteger.One) ? MathS.Signum(argument) : MathS.Pow(MathS.Signum(argument), Number.Integer.Create(m)));
                    if (!k.IsZero) Multiply(k.Equals(EInteger.One) ? MathS.Abs(argument) : MathS.Pow(MathS.Abs(argument), Number.Integer.Create(k)));
                    continue;
                }
                if (!m.Add(k).IsEven)
                    Multiply(MathS.Signum(argument));
                if (!k.IsZero)
                    Multiply(k.Equals(EInteger.One) ? argument : MathS.Pow(argument, Number.Integer.Create(k)));
            }
            foreach (var factor in rest)
                Multiply(factor);
            return rebuilt ?? Number.Integer.One;
        }

        /// <summary>
        /// Whether a sum among the factors above the bar is a constant multiple of the
        /// derivative of a factor below it that is not a polynomial in <paramref name="x"/>.
        /// </summary>
        private static bool IsADerivativeOfAFactorBelowTheBar(Entity expr, Entity.Variable x)
        {
            var (above, below) = Functions.SingleQuotient.Of(expr);
            if (below == Number.Integer.One)
                return false;
            var sums = Mulf.LinearChildren(above).Where(factor => factor is Sumf or Minusf && factor.ContainsNode(x)).ToList();
            if (sums.Count == 0)
                return false;
            foreach (var factor in Mulf.LinearChildren(below))
            {
                var @base = factor is Powf(var inner, Number.Integer) ? inner : factor;
                if (!@base.ContainsNode(x) || TreeAnalyzer.TryGetPolynomial(@base, x, out _))
                    continue;
                var derivative = @base.Differentiate(x).InnerSimplified;
                if (derivative is Providedf(var bare, _))
                    derivative = bare;
                foreach (var sum in sums)
                {
                    var ratio = (sum / derivative).InnerSimplified;
                    if (ratio.ContainsNode(x) && ratio.Complexity <= LargestTermTakenAsWritten)
                        ratio = ratio.Simplify();
                    if (ratio is Providedf(var bareRatio, _))
                        ratio = bareRatio;
                    if (!ratio.ContainsNode(x))
                        return true;
                }
            }
            return false;
        }

        /// <summary>
        /// A quotient whose numerator and denominator are polynomials in <paramref name="x"/>
        /// and in the functions of <paramref name="x"/> in them, cancelled by their greatest
        /// common divisor with those functions taken for indeterminates, and the denominator
        /// written in its square-free factors the same way; the quotient so written is asked.
        /// </summary>
        /// <remarks>
        /// <c>(x^2 + 2x sin(x) + sin(x)^2)/(x + sin(x))^2</c> is <c>1</c>, and no rule saw that:
        /// split, its three terms are not elementary apart, and as it stands nothing reads a
        /// quotient of polynomials in a sine. With <c>S</c> for the sine it is
        /// <c>(x + S)^2/(x + S)^2</c>. Exact in the generic case, as everywhere in this
        /// integrator: the cancelled factor is taken nonzero. Only where the writing changes
        /// something, so that it cannot ask what it was asked.
        /// </remarks>
        internal static Entity? SolveByCancellingWithFunctionsAsIndeterminates(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator) || !denominator.ContainsNode(x)
                || !denominator.Nodes.Any(node => node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf or Powf(_, Number.Integer))))
                return null;
            var (top, bottom) = CancelledWithFunctionsAsIndeterminates(numerator, denominator, x, expr);
            if (top == numerator && bottom == denominator)
                return null;
            var written = Functions.PartialFractions.Bare(top / bottom);
            if (written == expr)
                return null;
            // The same question: the quotient cancelled is the quotient, and a rule scoped to
            // the question asked or one below it -- the power of a quotient written apart --
            // is owed the remainder by parts leaves once it is cancelled, which is where
            // `asech(a + b x)/x^2` needed it.
            return Integration.ComputeAsTheSameQuestion(written, x, integrateByParts);
        }

        /// <summary>Whether <paramref name="expr"/> holds a fractional power of something in <paramref name="x"/>.</summary>
        private static bool HasARadicalOf(Entity expr, Entity.Variable x)
            => expr.Nodes.Any(node => node is Powf(var @base, Number.Rational power) && power is not Number.Integer && @base.ContainsNode(x));

        /// <summary>
        /// <paramref name="numerator"/> over <paramref name="denominator"/> with every function
        /// of <paramref name="x"/> that is not a polynomial in it -- a logarithm, an
        /// exponential, a trigonometric function -- taken for an indeterminate: the two
        /// cancelled by their greatest common divisor as polynomials in <paramref name="x"/>
        /// and those, and the denominator written as its square-free factorisation, each
        /// factor to its multiplicity, each sum written in the order <paramref name="writtenIn"/>
        /// writes it where it writes it at all. Unchanged where either is not such a
        /// polynomial, or where nothing cancels and nothing factors.
        /// </summary>
        /// <remarks>
        /// The generic case, as everywhere in this integrator: the cancelled factor is taken
        /// nonzero, and the identity <c>ln(x) = L</c> is not used -- a cancellation valid for
        /// every value of <c>L</c> is valid for that one.
        /// </remarks>
        private static (Entity Numerator, Entity Denominator) CancelledWithFunctionsAsIndeterminates(Entity numerator, Entity denominator, Entity.Variable x, Entity writtenIn)
        {
            if (!denominator.ContainsNode(x))
                return (numerator, denominator);
            // One radicand written in two orders is one radicand: `(1/L^2 - 1)^(-1/2)` above
            // and `sqrt(-1 + 1/L^2)` below, which is how the derivative of `asech(a + b x)`
            // arrives by parts beside the integrand's own root, were two atoms and cancelled
            // against nothing. Written in one order where the radicand stands to a negative
            // power and to a positive one, which is what the joining below needs, and only
            // there: `(1 - x^2)^(1/4) sqrt(1 + -x^2)` gathered to `(1 - x^2)^(3/4)` sent
            // Timofeev's 314 down a path whose answer could not be checked, where the two
            // roots apart are split over `(1 - x)(1 + x)` and answered.
            string Spelling(Entity radicand) => string.Join(" + ", Sumf.LinearChildren(radicand).Select(term => term.ToString()).OrderBy(term => term, System.StringComparer.Ordinal));
            // Where the radicand stands in two places that differ in the sign of the power as
            // written or in the side of the bar -- `q^(-1/2)` above beside `sqrt(q)` below,
            // which the joining below reads as one atom, or `sqrt(A)` above beside `sqrt(A)`
            // below, which cancel -- and only there.
            var placesOfSpelling = new Dictionary<string, (HashSet<(bool Negative, bool Underneath)> Places, Entity First)>();
            foreach (var (node, underneath) in numerator.Nodes.Select(n => (n, false)).Concat(denominator.Nodes.Select(n => (n, true))))
                if (node is Powf(var radicand, Number.Rational r) && r is not Number.Integer && radicand.ContainsNode(x) && radicand is Sumf or Minusf)
                {
                    var key = Spelling(radicand);
                    if (!placesOfSpelling.TryGetValue(key, out var seen))
                        placesOfSpelling[key] = seen = (new HashSet<(bool, bool)>(), radicand);
                    seen.Places.Add((r.ERational.IsNegative, underneath));
                }
            Entity OneSpelling(Entity side) => side.Replace(node =>
                node is Powf(var radicand, Number.Rational r) && r is not Number.Integer && radicand.ContainsNode(x) && radicand is Sumf or Minusf
                && placesOfSpelling.TryGetValue(Spelling(radicand), out var seen) && seen.Places.Count > 1 && seen.First != radicand
                    ? MathS.Pow(seen.First, r)
                    : node);
            numerator = OneSpelling(numerator);
            denominator = OneSpelling(denominator);
            // A negative fractional power is the reciprocal of the positive one, and goes
            // below the bar so that `q^(-1/2)` above and `sqrt(q)` below are one atom and not
            // two: the derivative of `ln(1/(c x) + sqrt(q))` by parts is such a quotient.
            // Only where it joins two spellings of one root: a reciprocal root on its own is
            // left where it is, since moving every one of them multiplied the other quotients
            // through and fed a search -- Rubi's `x^5 atanh(x sqrt(p)/sqrt(d + p x^2))` went
            // from a decline in 4 s to none. Where the two spellings do occur the joining is
            // what lets the remainder be read, and the same row still runs out its budget: the
            // remainder, read, is `x^6/sqrt(d + p x^2)` up to a constant, and that search is
            // the cost of the capability rather than of this step.
            var both = numerator.Nodes.Concat(denominator.Nodes)
                .Where(node => node is Powf(var radicand, Number.Rational r) && r is not Number.Integer && radicand.ContainsNode(x))
                .Select(node => (Radicand: ((Powf)node).Base, Negative: ((Number.Rational)((Powf)node).Exponent).ERational.IsNegative))
                .GroupBy(pair => pair.Radicand)
                .Where(group => group.Any(pair => pair.Negative) && group.Any(pair => !pair.Negative))
                .Select(group => group.Key)
                .ToList();
            Entity ReciprocalsBelow(Entity side) => side.Replace(node =>
                node is Powf(var radicand, Number.Rational r) && r is not Number.Integer && r.ERational.IsNegative && both.Contains(radicand)
                    ? 1 / MathS.Pow(radicand, -r)
                    : node);
            if (both.Count > 0)
            {
                var (aboveOfTop, belowOfTop) = Functions.SingleQuotient.Of(ReciprocalsBelow(numerator));
                var (aboveOfBottom, belowOfBottom) = Functions.SingleQuotient.Of(ReciprocalsBelow(denominator));
                if (belowOfTop != Number.Integer.One || belowOfBottom != Number.Integer.One)
                {
                    numerator = aboveOfTop * belowOfBottom;
                    denominator = belowOfTop * aboveOfBottom;
                }
            }
            var atoms = new Dictionary<Entity, Entity.Variable>();
            // Each name unique against the expression and against the atoms named before it.
            var named = numerator + denominator;
            Entity WithAtoms(Entity expr) => expr.Replace(node =>
            {
                if (!node.ContainsNode(x) || node is Variable or Sumf or Minusf or Mulf or Divf
                    || node is Powf(_, Number.Integer { IsNegative: false }))
                    return node;
                if (!atoms.TryGetValue(node, out var atom))
                {
                    atom = Variable.CreateUnique(named, "atom");
                    named = named + atom;
                    atoms[node] = atom;
                }
                return atom;
            });
            var top = WithAtoms(numerator);
            var bottom = WithAtoms(denominator);
            if (top.Nodes.Any(node => node is Powf(_, Number.Rational r) && r is not Number.Integer)
                || bottom.Nodes.Any(node => node is Powf(_, Number.Rational r) && r is not Number.Integer))
                return (numerator, denominator);
            var variables = top.Vars.Concat(bottom.Vars).Distinct().OrderBy(v => v.Name, System.StringComparer.Ordinal).ToList();
            if (variables.Count == 0 || variables.Count > MultivariatePolynomial.MaxVariables)
                return (numerator, denominator);
            var indices = new Dictionary<Variable, int>();
            for (var i = 0; i < variables.Count; i++)
                indices[variables[i]] = i;
            if (MultivariatePolynomial.TryParse(top, indices) is not { } above || MultivariatePolynomial.TryParse(bottom, indices) is not { } below
                || below.IsConstant)
                return (numerator, denominator);
            var order = Enumerable.Range(0, variables.Count).ToList();
            var cancelled = false;
            if (Functions.PolynomialGcd.Gcd(above, below, order, 0) is { IsConstant: false } divisor
                && above.DivideExact(divisor) is { } reducedAbove && below.DivideExact(divisor) is { } reducedBelow)
            {
                above = reducedAbove;
                below = reducedBelow;
                cancelled = true;
            }
            // The square-free factorisation of the denominator in x: Yun's, with the gcds
            // this file already has.
            var factors = new List<(MultivariatePolynomial Factor, int Multiplicity)>();
            var xIndex = indices.TryGetValue(x, out var xi) ? xi : -1;
            if (xIndex >= 0 && Functions.PolynomialGcd.Gcd(below, below.DerivativeIn(xIndex), order, 0) is { IsConstant: false } repeated
                && below.DivideExact(repeated) is { } squareFree)
            {
                var c = repeated;
                var w = squareFree;
                var multiplicity = 1;
                while (!w.IsConstant && multiplicity < 16)
                {
                    if (Functions.PolynomialGcd.Gcd(w, c, order, 0) is not { } y || w.DivideExact(y) is not { } z || c.DivideExact(y) is not { } nextC)
                    {
                        factors.Clear();
                        break;
                    }
                    if (!z.IsConstant)
                        factors.Add((z, multiplicity));
                    w = y;
                    c = nextC;
                    multiplicity++;
                }
                // What is left is a constant in x -- a number, or the atoms and parameters
                // beside the polynomial, which the derivative in x leaves in every gcd: the
                // root `S` in `S x (a + b x)^2` stood in the last `c` and the factorisation
                // was thrown away for it, and the remainder by parts leaves from
                // `asech(a + b x)/x^2` went on as `1/(a^2 S x + 2 a b S x^2 + b^2 S x^3)`.
                if (factors.Count > 0 && c.DegreeIn(xIndex) > 0)
                    factors.Clear();
            }
            // Written back, and a sum that the integrand already writes in some order is
            // written in that order: the factor `ln(x) + x` beside the root of `x + ln(x)` is
            // not the substitution the root is, and the same sum is.
            var writtenSums = writtenIn.Nodes.Where(node => node is Sumf or Minusf)
                .Select(node => (Node: node, Terms: new HashSet<Entity>(Sumf.LinearChildren(node)))).ToList();
            // Nothing cancelled and nothing factored: the quotient as it was, and not the
            // same quotient respelled, which a rule asking whether anything changed would take
            // for a change.
            // ...or the denominator collapsed to one term as a polynomial in the atoms where
            // it was written as a sum: `cosh(x) + sinh(x)` is `(A + B)/2 + (A - B)/2` for the
            // exponentials `A` and `B`, which is `A`, and Timofeev's `e^(m x)/(cosh(x) + sinh(x))`
            // was declined as a quotient by a sum.
            var collapsed = denominator is Sumf or Minusf && below.Terms.Count() == 1;
            var factored = factors.Count >= 2 || factors.Any(pair => pair.Multiplicity > 1);
            if (!cancelled && !factored && !collapsed)
                return (numerator, denominator);
            // Written back outermost first: an atom holds the atoms inside it by name.
            Entity Back(Entity mapped)
            {
                foreach (var pair in atoms.Reverse())
                    mapped = mapped.Substitute(pair.Value, pair.Key);
                return mapped.Replace(node =>
                {
                    if (node is not (Sumf or Minusf))
                        return node;
                    var terms = new HashSet<Entity>(Sumf.LinearChildren(node));
                    foreach (var (written, writtenTerms) in writtenSums)
                        if (writtenTerms.SetEquals(terms))
                            return written;
                    return node;
                });
            }
            Entity factoredBelow;
            if (factors.Count > 0)
            {
                // The content -- the rational the factors were normalised by -- goes in front.
                MultivariatePolynomial? product = MultivariatePolynomial.One(variables.Count);
                foreach (var (factor, multiplicity) in factors)
                    for (var i = 0; i < multiplicity && product is not null; i++)
                        product = product.Multiply(factor);
                if (product is null || below.DivideExact(product) is not { } content || content.DegreeIn(xIndex) > 0)
                    factoredBelow = Back(below.ToEntity(variables));
                else
                {
                    factoredBelow = Back(content.ToEntity(variables));
                    foreach (var (factor, multiplicity) in factors)
                    {
                        var written = Back(factor.ToEntity(variables));
                        factoredBelow = factoredBelow == Number.Integer.One ? (multiplicity == 1 ? written : MathS.Pow(written, multiplicity))
                            : factoredBelow * (multiplicity == 1 ? written : MathS.Pow(written, multiplicity));
                    }
                }
            }
            else
                factoredBelow = Back(below.ToEntity(variables));
            // The numerator as it was written where nothing cancelled in it: rebuilt from its
            // monomials it is expanded, and `(1 + x) sqrt(x + ln(x))` expanded is two terms
            // neither of which is the substitution the product is.
            return (cancelled ? Back(above.ToEntity(variables)) : numerator, factoredBelow);
        }

        /// <summary>
        /// A quotient of polynomials, split into two smaller quotients and integrated in two
        /// parts — at a rational root of the denominator where it has one, and otherwise at a
        /// coprime pair of its irreducible factors.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The rules for a linear or a quadratic denominator answer those in one piece, so
        /// what is left over are the denominators of degree three and up, which nothing
        /// read at all: 1/(x^3 + 1) had no antiderivative. Splitting at the root -1 leaves
        /// (1/3)/(x + 1) and (2 - x)/(3(x^2 - x + 1)), and both of those are already
        /// integrable, the second by the rule for a linear numerator over a quadratic.
        /// Each step takes a degree off the denominator, so this ends.
        /// </para>
        /// <para>
        /// The split at a root reaches a denominator only where it has a rational one, which
        /// left 1/(x^4 + 3x^2 + 2) unevaluated although it is (x^2 + 1)(x^2 + 2) and both of
        /// those are integrated by the rule above. <see cref="Functions.PartialFractions"/>
        /// splits those, and is tried when the split at a root either does not apply or
        /// applies and leaves something that will not integrate — it takes the denominator
        /// apart differently, so a failure of the one is no evidence about the other.
        /// </para>
        /// <para>
        /// Both of those factor over the rationals and stop where the rationals do, which left
        /// x^2/(x^4 + 1) unevaluated: x^4 + 1 is irreducible over Q, and over the reals it is
        /// (x^2 - sqrt(2)x + 1)(x^2 + sqrt(2)x + 1). The third step
        /// (<see cref="Functions.PartialFractions.TrySplitBiquadraticOverTheReals"/>) reads a
        /// biquadratic denominator that way. It is last because it is the only one that
        /// introduces a radical, and a denominator that factors over Q should be taken apart in
        /// exact arithmetic by one of the two above.
        /// </para>
        /// <para>
        /// <b>All three of those want a proper fraction</b>, and each declines an improper one
        /// rather than dividing it out — so <c>x^2/(x + 1)</c> had no antiderivative although
        /// it is <c>x - 1 + 1/(x + 1)</c> and every piece of that is read. The division is the
        /// first step here for that reason, and it is not new code:
        /// <see cref="TreeAnalyzer.PolynomialLongDivision"/> has done it all along for the
        /// simplifier's own rule set, and the integrator simply never asked it.
        /// </para>
        /// </remarks>
        internal static Entity? SolveByPartialFractions(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;

            // A quotient with x below a bar inside it, `1/(a + b/x)`, written over one bar: every
            // rule below reads the numerator and the denominator as polynomials, and `a + b/x` is
            // not one, where `x/(a x + b)` is read at once. Once: what one bar gives has none.
            // What the bars were cleared with is a power of x on both sides, `x^3/(x^2 Q L^2)` for
            // `1/((a + b/x + c/x^2) x L^2)`, and it is cancelled: the rules below read a numerator
            // and a denominator with a common factor as coprime, and answered that one wrongly.
            // Only where both sides are then polynomials in x, which is what the rules below read:
            // anything else, written over one bar, would be the whole question asked again a level
            // down, from inside every search that passes through here.
            if ((HasTheVariableBelowABar(numerator, x) || HasTheVariableBelowABar(denominator, x))
                && Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr)) is var (top, bottom)
                && !HasTheVariableBelowABar(top, x) && !HasTheVariableBelowABar(bottom, x)
                && bottom.ContainsNode(x)
                && TreeAnalyzer.TryGetPolynomial(top, x, out _) && TreeAnalyzer.TryGetPolynomial(bottom, x, out _)
                && WithoutACommonPowerOfX(top, bottom, x) is var (reducedTop, reducedBottom))
                return SolveByPartialFractions(reducedTop / reducedBottom, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(reducedTop / reducedBottom, x, integrateByParts);

            // A polynomial over a power of one linear with a symbol in it, in powers of the linear at
            // its root, before the division: see SolveByReducingThePolynomialOverALinearFactor.
            if (SolveByReducingThePolynomialOverALinearFactor(expr, x, integrateByParts, alone: true) is { } overThePowersOfTheLinear)
                return overThePowersOfTheLinear;

            // The helper answers null for a fraction that is already proper, so this cannot
            // fire on one and recurse into the problem it started from. The check on the
            // quotient is the second half of that guarantee: a division that came back with
            // nothing taken out would hand the same fraction on and not terminate.
            // And only for a fraction that is improper by its degrees: asked to divide `x^2`
            // by `(a + b x)(c + d x)(f/g + x)^2`, the division read the divisor through its
            // other spelling and came back with a quotient of the first degree carrying a
            // condition, and the two halves integrated to a page of piecewise.
            if (!IsProperByDegree(numerator, denominator, x)
                && TreeAnalyzer.PolynomialLongDivision(numerator, denominator, genericCase: true, inTermsOf: x) is var (quotient, properPart)
                && quotient.Evaled != Entity.Number.Integer.Create(0)
                && Integration.ComputeIndefiniteIntegral(quotient, x, integrateByParts) is { } wholePart
                && Integration.ComputeIndefiniteIntegral(properPart, x, integrateByParts) is { } fractionPart)
                return wholePart + fractionPart;

            // A numerator that is a constant multiple of the denominator's derivative is the
            // logarithm of the denominator, whatever the denominator is: Welz's
            // `(3 - 3x + 30x^2 + 160x^3)/(9 + 24x - 12x^2 + 80x^3 + 320x^4)` is `ln(D)/8`, and
            // the substitution rule found it as `u = D` while sums were still its candidates.
            if (denominator.ContainsNode(x)
                && TreeAnalyzer.PolynomialLongDivision(numerator, denominator.Differentiate(x).InnerSimplified, genericCase: true, inTermsOf: x)
                    is var (multiple, leftover)
                && !multiple.ContainsNode(x)
                && (leftover is Divf(var leftoverTop, _) ? leftoverTop : leftover).InnerSimplified.Evaled is Number.Complex { IsZero: true })
                return (multiple * MathS.Ln(denominator)).InnerSimplified;

            // A written sum with a symbol among its coefficients that they all share is that
            // symbol times a polynomial over the rationals, and is written so first: `(a u + a)`
            // beside `1 - u^2` shares a root with it, which the symbolic split declines, and a
            // symbolic sextic is nothing the refactoring below reads, where `a` times a rational
            // one is. Before the symbolic split: `a (1 + u^2) + 2 a u` is `a (1 + u)^2`, a
            // repeated linear over the rationals, and read as a quadratic with `a` in it the
            // split computed its digits modulo `(1 + u^2)^6` with `a` in every coefficient, for
            // an answer twice the length. Once: a primitive factor has no content to take out.
            if (WithTheContentOutOfEachSumFactor(denominator, x) is { } primitive
                && (SolveByPartialFractions(numerator / primitive, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(numerator / primitive, x, integrateByParts)) is { } overPrimitives)
                return overPrimitives;

            // Written factors with a symbol in them that share a factor, or repeat one inside,
            // written over what they share: `(d + e x)(a d e + (c d^2 + a e^2) x + c d e x^2)^2`
            // is `(d + e x)^3 (a e + c d x)^2`, and `a^2 + 2 a b x + b^2 x^2` beside `a + b x`
            // is a third power of it. The splits below read the written factors as coprime and
            // squarefree, and the refactoring after them reads rational coefficients only:
            // Rubi's 1.2.1.2 `1/((d + e x)(a d e + (c d^2 + a e^2) x + c d e x^2)^2)` was declined
            // after four seconds, where written so it is answered in a tenth of one. Once: what
            // this writes is coprime and squarefree already.
            if (OverSymbolicFactorsWrittenApart(numerator, denominator, x) is var (above, below)
                && (SolveByPartialFractions(above / below, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(above / below, x, integrateByParts)) is { } overWhatTheyShare)
                return overWhatTheyShare;

            // And a linear with a root off the real line that a quadratic beside it shares, which
            // the divisors over the rationals above cannot see: `1 + i u` beside `1 + u^2`, which is
            // `(1 + i u)(1 - i u)`, what the tangent substitution makes of Rubi's 4.3.2.1
            // `1/((a + i a tan(x)) (c + d tan(x)))`. The quadratic is written over the linears of
            // its roots and the shared one taken as one power, coprime and squarefree for the
            // splits below.
            if (OverAComplexRootSharedWithAQuadratic(denominator, x) is { } overTheSharedRoot
                && (SolveByPartialFractions(numerator / overTheSharedRoot, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(numerator / overTheSharedRoot, x, integrateByParts)) is { } overTheComplexRoot)
                return overTheComplexRoot;

            // Written linear factors with symbols in their coefficients, two or more, one of
            // them to a power: decomposed over the written factors, the coefficients read
            // off derivatives at the roots and each a line. First, before the respellings
            // below and the Hermite reduction, whose solve hands back its coefficients as
            // quotients of determinants -- `1/((a + b x)(f + g x)^3)` came out twenty
            // kilobytes long that way -- and before a respelling sends the quotient round
            // the chain, where the substitution search answers `x^2/((a + b x)(c + d x)(f + g x)^2)`
            // as a page of piecewise.
            // A rational factor that splits, written in its linear factors where a symbolic one
            // stands beside it, so that the split below finds them.
            var withItsLinearsWritten = WithRationalFactorsSplitBesideASymbolicOne(denominator, x) ?? denominator;
            if (Mulf.LinearChildren(withItsLinearsWritten).Any(f => f.ContainsNode(x) && f is Powf(_, Number.Integer { EInteger.Sign: > 0 } e) && e != Number.Integer.One)
                && IsAProductOfSymbolicLinearFactors(withItsLinearsWritten, x, aLinearAmongThem: !HoldsARepeatedSymbolicFactor(withItsLinearsWritten, x))
                && Functions.PartialFractions.TrySplitOverWrittenFactors(numerator, withItsLinearsWritten, x, out var overSymbolicLinears)
                && IntegratedTermByTerm(overSymbolicLinears, x, integrateByParts) is { } overTheLinears)
                return overTheLinears;

            // Every rule below reads the denominator **as written**: the Hermite reduction wants
            // its repeated factor written as a power, the coprime split wants two written blocks.
            // A denominator whose written factors hide either -- `(1 + t^2)(1 - 2t - 2t^3 - t^4)`
            // is `(1 + t^2)^2 (1 - 2t - t^2)`, and Euler's substitution produces exactly that --
            // is written in its irreducible factors over the rationals first, equal ones
            // gathered into one power, and asked again in that spelling -- of this rule, not of
            // the chain: the substitution rule in front of it simplifies the integrand once per
            // candidate subtree, and a denominator written as five factors is five candidates
            // more than one written out, each a rational function for the simplifier to
            // factor. `1/(x^6 - 1)` did not return in thirty seconds through the chain and is
            // under a second this way, with the chain behind it for a spelling this rule does
            // not answer on its own -- one irreducible factor to the first power is the table's.
            // Once: the spelling this produces refactors to itself.
            if (TryWriteInIrreducibleFactors(denominator, x) is { } refactored
                && (SolveByPartialFractions(numerator / refactored, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(numerator / refactored, x, integrateByParts)) is { } overIrreducibles)
                return overIrreducibles;

            // And a written base that is a polynomial with rational coefficients spelled some
            // other way -- `2 + (u^2 - 3)^2 - (u^2 - 3)`, which is what the linear-radical
            // substitution makes of `1 + x + 2x^2` under `u = sqrt(3 - 2x)` -- is written as its
            // polynomial, once: the splits below read the bases as written, and Welz's
            // `1/((3 - 2x)^(11/2) (1 + x + 2x^2)^5)` was answered as `1/(u^10 (u^4 - 7u^2 + 14)^5)`
            // and declined as it came. For a polynomial numerator only, since the respelling
            // is asked of the whole chain and a numerator with a root in it is not this
            // rule's to begin with.
            if (Functions.PolynomialFactoring.TryGetRationalCoefficients(numerator, x, 1, 0, 64, out _)
                && TryWriteBasesAsPolynomials(denominator, x) is { } respelled
                && (SolveByPartialFractions(numerator / respelled, x, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(numerator / respelled, x, integrateByParts)) is { } overPolynomials)
                return overPolynomials;

            // A polynomial below the bar that is a binomial, or a quartic even in its variable, once
            // written in `y = x + s` with `s = a_(n-1)/(n a_n)`: `c^2 x^3 + 3 b c x^2 + 3 b^2 x + 3 a b`
            // is `((c x + b)^3 + 3 a b c - b^3)/c`, and `a + 8 x - 8 x^2 + 4 x^3 - x^4` is
            // `a + 3 - 2 y^2 - y^4` in `y = x - 1`. Nothing above factors a polynomial with a symbol
            // in it, and the rules for a binomial and for an even quartic read it in y at once.
            // Once: in y the term that s takes away is gone.
            if (InTheVariableThatDepressesIt(numerator, denominator, x) is var (inY, y, shift)
                && (SolveByPartialFractions(inY, y, integrateByParts)
                    ?? Integration.ComputeIndefiniteIntegral(inY, y, integrateByParts)) is { } inTheShiftedVariable)
                return inTheShiftedVariable.Substitute(y, (x + shift).InnerSimplified);

            // A denominator with a written repeated factor takes the Hermite reduction first:
            // the rational part of the answer in one linear solve, and what is left is a proper
            // fraction over a squarefree denominator for the splits below. `(1 + x^2)/(x (1 + x^3)^2)`
            // reached the same answer through them after seventeen seconds of peeling and
            // re-factoring; this way it is under a second.
            if (Mulf.LinearChildren(denominator).Any(f => f.ContainsNode(x) && f is Powf(_, Number.Integer { EInteger.Sign: > 0 } e) && e != Number.Integer.One)
                && IntegrateByAnsatz(null, numerator / denominator, x) is { } byHermite)
                return byHermite;

            // A power of a binomial past what the Hermite reduction's system takes with symbols in
            // it, `(c + d x)/(a + b x^4)^4`: the classical recurrence, a power at a time, down to
            // the binomial itself.
            if (IntegrateAPolynomialOverAPowerOfABinomial(numerator, denominator, x, integrateByParts) is { } downThePowers)
                return downThePowers;

            // And of a trinomial in x^n, `x^4/(a + b x^2 + c x^4)^3`: its recurrence, a power at a
            // time, down to the trinomial itself.
            if (IntegrateAPolynomialOverAPowerOfATrinomial(numerator, denominator, x, integrateByParts) is { } downTheTrinomialsPowers)
                return downTheTrinomialsPowers;

            // Splitting into coprime blocks comes before peeling one root off, and the order is
            // load-bearing rather than a preference.
            //
            // Both succeed on a denominator with two repeated factors, so whichever runs first
            // decides, and the one that was first is the expensive one. It takes a single root
            // out and hands the remainder on **expanded** — for 1/((1+x)^3 * (2+x)^4) that is a
            // degree-6 denominator written out — so every level of the recursion re-factorises
            // what the level above had already factored, and the whole cost is in there.
            // Measured, integrating the pieces each splitter produces for that integrand:
            //
            //     peel one root, then the remainder        33,318 ms
            //     split into coprime blocks, both halves       39 ms
            //
            // Neither splitter is slow in itself: both return in under 16 ms. It is what they
            // hand on that differs, and the coprime split hands on two smaller problems whose
            // denominators are each a single repeated factor, where peeling hands on one problem
            // barely smaller than the original.
            // https://github.com/asc-community/AngouriMath/issues/1235
            if (Functions.PartialFractions.TrySplitIntoCoprimeParts(
                    numerator, denominator, x, out var left, out var right)
                && Integration.ComputeIndefiniteIntegral(left, x, integrateByParts) is { } overOne
                && Integration.ComputeIndefiniteIntegral(right, x, integrateByParts) is { } overOther)
                return overOne + overOther;

            // Still needed, and not only as a fallback: the coprime split declines a denominator
            // that is a single repeated factor, or that has no second coprime block to split off,
            // and those are exactly what the recursion above descends into.
            if (Functions.PolynomialFactoring.TrySplitOffRationalRoot(
                    numerator, denominator, x, out var simple, out var restNumerator, out var restDenominator)
                && Integration.ComputeIndefiniteIntegral(simple, x, integrateByParts) is { } first
                && Integration.ComputeIndefiniteIntegral(restNumerator / restDenominator, x, integrateByParts) is { } rest)
                return first + rest;

            if (Functions.PartialFractions.TrySplitBiquadraticOverTheReals(
                    numerator, denominator, x, out var overOneReal, out var overOtherReal)
                && Integration.ComputeIndefiniteIntegral(overOneReal, x, integrateByParts) is { } realFirst
                && Integration.ComputeIndefiniteIntegral(overOtherReal, x, integrateByParts) is { } realRest)
                return realFirst + realRest;

            // The two splits above stop where exact rational arithmetic does, and a symbol is
            // not a rational. A polynomial over a power of a linear with a symbol in it --
            // `(c + d x)/(a + b x)^2` -- is one substitution from a sum of powers.
            if (IntegrateAPolynomialOverAPowerOfALinear(numerator, denominator, x) is { } overALinearPower)
                return overALinearPower;

            // And a denominator *written* as a product of distinct linear and quadratic
            // factors -- `(x + a)(x^2 + b)` -- is decomposed by undetermined coefficients,
            // checked, and each piece is a shape the rules here read.
            if (Functions.PartialFractions.TrySplitOverWrittenFactors(numerator, denominator, x, out var overWrittenFactors)
                && IntegratedTermByTerm(overWrittenFactors, x, integrateByParts) is { } termByTerm)
            {
                // Checked: the decomposition's terms integrate through the rules below and,
                // with coefficients that are pages of symbols, one such sum came back wrong
                // with every term right on its own.
                // https://github.com/asc-community/AngouriMath/issues/1369
                if (!overWrittenFactors.Vars.Any(symbol => symbol != x)
                    || Functions.PartialFractions.DerivativeHoldsAtSampledPoints(termByTerm, overWrittenFactors, x))
                    return termByTerm;
            }

            // A power of x beside a block with a symbol in it that x does not divide:
            // `1/(x (x^3 + c))`, which the written-factor split above declines for a block past
            // the second degree. Split at the power of x, each part goes to a rule that reads it.
            if (IntegrateOverAPowerOfXBesideABlock(numerator, denominator, x, integrateByParts) is { } besideABlock)
                return besideABlock;
            // And a power of another linear beside such a block, split at its root the same way:
            // `1/((u - c)(a + b u^3))`, which writing `1/(x (a + b (c + d x)^3))` in `c + d x` makes.
            if (IntegrateOverAPowerOfALinearBesideABlock(numerator, denominator, x, integrateByParts) is { } besideABlockAtARoot)
                return besideABlockAtARoot;

            // Blocks that are each a polynomial in one power of x past the second,
            // `1/((a + b x^3)(c + d x^3))`: split in `u = x^n`, where they are linear or quadratic,
            // and each fraction back in x is over one block, which the rule for a binomial reads.
            if (IntegrateOverBlocksInAPowerOfX(numerator, denominator, x, integrateByParts) is { } overBlocksInAPower)
                return overBlocksInAPower;

            // Last, because everything above answers in exact arithmetic where it can: a
            // binomial denominator the splits above could not take apart -- `x^3 + 2`, `x^5 + 1`,
            // `a x^3 - b` -- decomposed at its roots of unity in closed form.
            if (IntegrateAPolynomialOverABinomial(numerator, denominator, x) is { } atTheRootsOfUnity)
                return atTheRootsOfUnity;

            return null;
        }

        /// <summary>
        /// <paramref name="numerator"/> over <paramref name="denominator"/> written in <c>y = x + s</c>,
        /// where the denominator is a constant times a power of one polynomial in x of the third to
        /// the sixth degree, written as a sum of its monomials, that in y is a binomial or, of the
        /// fourth degree, even; <c>s = a_(n-1)/(n a_n)</c> is what takes its term of degree
        /// <c>n - 1</c> away. Null otherwise, and where that term is not there to take away.
        /// </summary>
        private static (Entity InY, Entity.Variable Y, Entity Shift)? InTheVariableThatDepressesIt(Entity numerator, Entity denominator, Entity.Variable x)
        {
            Entity? polynomial = null;
            var power = 0;
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant *= factor;
                    continue;
                }
                if (polynomial is not null)
                    return null;
                (polynomial, power) = factor is Powf(var raised, Number.Integer { EInteger.Sign: > 0 } exponent) && exponent.EInteger.CanFitInInt32()
                    ? (raised, exponent.EInteger.ToInt32Unchecked()) : (factor, 1);
            }
            // With a symbol among its coefficients, since a polynomial over the rationals is split
            // over its factors above; and written out, since one written in a linear,
            // `a + (b + c x)^3`, is read as it stands.
            if (polynomial is null || !polynomial.Vars.Any(symbol => symbol != x)
                || polynomial.Nodes.Any(node => node is Powf(Sumf or Minusf, _) && node.ContainsNode(x))
                || !TreeAnalyzer.TryGetPolynomial(polynomial, x, out var terms)
                || terms.Any(term => term.Key.Sign < 0 || !term.Key.CanFitInInt32() || term.Value.ContainsNode(x)))
                return null;
            if (numerator.ContainsNode(x)
                && (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above) || above.Any(term => term.Key.Sign < 0 || term.Value.ContainsNode(x))))
                return null;
            var degree = terms.Keys.Max()!.ToInt32Unchecked();
            if (degree < 3 || degree > 6)
                return null;
            Entity Coefficient(int k) => terms.TryGetValue(EInteger.FromInt32(k), out var coefficient) ? coefficient : Number.Integer.Zero;
            if (VanishesIdentically(Coefficient(degree)) || VanishesIdentically(Coefficient(degree - 1)))
                return null;
            var shift = Functions.PartialFractions.InLowestTermsOverTheSymbols(Coefficient(degree - 1) / (degree * Coefficient(degree)));
            // P(y - s) has at y^i the sum over m >= i of a_m C(m, i) (-s)^(m - i).
            var inY = new Entity[degree + 1];
            for (var i = 0; i <= degree; i++)
            {
                Entity sum = Number.Integer.Zero;
                var choose = EInteger.One;
                for (var m = i; m <= degree; m++)
                {
                    if (m > i)
                        choose = choose.Multiply(EInteger.FromInt32(m)).Divide(EInteger.FromInt32(m - i));
                    sum += Coefficient(m) * Number.Integer.Create(choose) * (m == i ? Number.Integer.One : MathS.Pow(-shift, m - i));
                }
                inY[i] = Functions.PartialFractions.InLowestTermsOverTheSymbols(sum);
            }
            var vanishing = inY.Select(VanishesIdentically).ToArray();
            var aBinomial = Enumerable.Range(1, degree - 1).All(i => vanishing[i]);
            var anEvenQuartic = degree == 4 && vanishing[1] && vanishing[3];
            if (!aBinomial && !anEvenQuartic)
                return null;
            var y = Variable.CreateUnique(numerator + denominator, "y_shift");
            Entity depressed = Number.Integer.Zero;
            for (var i = degree; i >= 0; i--)
                if (!vanishing[i])
                {
                    var monomial = i == 0 ? inY[i] : inY[i] * (i == 1 ? y : MathS.Pow(y, i));
                    depressed = depressed == Number.Integer.Zero ? monomial : depressed + monomial;
                }
            var below = power == 1 ? depressed : MathS.Pow(depressed, power);
            return (numerator.Substitute(x, y - shift) / (constant == Number.Integer.One ? below : constant * below), y, shift);
        }

        /// <summary>
        /// A polynomial over a power of a linear, <c>P(x)/(a + b x)^k</c> with <c>k >= 2</c>,
        /// under <c>t = a + b x</c>: <c>P((t - a)/b) t^(-k) / b</c> is a sum of powers of
        /// <c>t</c>, each a power rule or a logarithm.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>(c + d x)/(3 + 5 x)^2</c> came out and <c>(c + d x)/(a + b x)^2</c> did not: the
        /// first has a rational root to split at, the second has none, and no other rule read
        /// the shape. <c>1/(a + b x)^2</c> was answered by the quadratic rule, as a piecewise on
        /// a discriminant that is identically zero. This is what the symbolic partial-fraction
        /// split hands on for a repeated linear factor, and it was declined there for want of
        /// this.
        /// </para>
        /// <para>
        /// After the splits over the rationals, so that a numeric coefficient keeps the answer
        /// it had. <c>b</c> is divided by, in the generic case as everywhere here; a decidably
        /// zero <c>b</c> is not a linear at all and is declined.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? IntegrateAPolynomialOverAPowerOfALinear(Entity numerator, Entity denominator, Entity.Variable x)
        {
            if (denominator is not Powf(var linear, Number.Integer exponent)
                || !exponent.EInteger.CanFitInInt32() || exponent.EInteger.ToInt32Unchecked() is var k && k < 2)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var b, out var a)
                || b.Evaled is Number.Complex { IsZero: true })
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above))
                return null;
            foreach (var term in above)
                if (term.Key.Sign < 0 || term.Value.ContainsNode(x))
                    return null;

            var t = Variable.CreateUnique(numerator + denominator, "t");
            var inT = numerator.Substitute(x, (t - a) / b).Expand();
            if (!TreeAnalyzer.TryGetPolynomial(inT, t, out var powersOfT))
                return null;

            Entity total = 0;
            foreach (var term in powersOfT)
            {
                if (!term.Key.CanFitInInt32())
                    return null;
                var power = term.Key.ToInt32Unchecked() - k;
                total += power == -1
                    ? term.Value * IntegralPatterns.AntiderivativeLog(t)
                    : term.Value * MathS.Pow(t, power + 1) / (power + 1);
            }
            return (total / b).Substitute(t, linear).InnerSimplified;
        }

        /// <summary>
        /// <c>N/(x^k B)</c>, where the block <c>B</c> has a symbol in it and a constant term that
        /// is not zero, split at the power of x. <c>N/B</c> has a power series at 0, and its first
        /// <c>k</c> terms <c>P</c> are the part over <c>x^k</c>: <c>N/(x^k B) = P/x^k + R/B</c>, with
        /// <c>R = (N - P B)/x^k</c> exactly.
        /// </summary>
        /// <remarks>
        /// <c>1/(x (x^3 + 2))</c> had an antiderivative and <c>1/(x (x^3 + c))</c> did not: the
        /// first is split over the rationals, and the split over written factors takes linear
        /// and quadratic blocks only. Rubi writes <c>x^m (a + b x^n)^p</c> by the hundred, and a
        /// root of a square in it, <c>1/(x sqrt((a + b x^3)^2))</c>, is this once its modulus is
        /// taken. The constant term is divided by, in the generic case as everywhere here.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? IntegrateOverAPowerOfXBesideABlock(Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            // For the question asked, or one substitution below it, as the blocks in a power of x
            // are: the rest over the block is integrated again.
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            var k = 0;
            Entity block = Number.Integer.One;
            // Whether a factor of the block, or the base of a power of one, is past the second
            // degree: linear and quadratic ones, and their powers, are the written-factor split's.
            var pastTheSecondDegree = false;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (factor == x)
                    k++;
                else if (factor is Powf(var @base, Number.Integer e) && @base == x && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32())
                    k += e.EInteger.ToInt32Unchecked();
                else
                {
                    block = block == Number.Integer.One ? factor : block * factor;
                    var written = factor is Powf(var raised, Number.Integer { EInteger.Sign: > 0 }) ? raised : factor;
                    pastTheSecondDegree |= TreeAnalyzer.TryGetPolynomial(written, x, out var terms) && terms.Keys.Any(power => power.CompareTo(EInteger.FromInt32(2)) > 0);
                }
            }
            if (k == 0 || k > MaximumPowerOfXBesideABlock || !pastTheSecondDegree || !block.ContainsNode(x) || !block.Vars.Any(symbol => symbol != x))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(block, x, out var below) || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var above))
                return null;
            foreach (var term in below.Concat(above))
                if (term.Key.Sign < 0 || !term.Key.CanFitInInt32() || term.Value.ContainsNode(x))
                    return null;
            // In lowest terms in x: where x divides the numerator as well, the part over x^k is
            // nothing, and the rest is the whole question asked again a level down, out of reach
            // of the rules that answer only the question asked. `(A x^3 + B x^4 + C x^5)/(x (a +
            // b x^2 + c x^4)^2)` is answered at the top once the x is cancelled.
            if (!above.TryGetValue(EInteger.Zero, out var numeratorConstant) || VanishesIdentically(numeratorConstant))
                return null;
            var degreeBelow = below.Keys.Max()!.ToInt32Unchecked();
            var degreeAbove = above.Count == 0 ? 0 : above.Keys.Max()!.ToInt32Unchecked();
            if (degreeBelow > MaximumPowerOfXBesideABlock || !below.TryGetValue(EInteger.Zero, out var constant) || VanishesIdentically(constant))
                return null;
            Entity Coefficient(Dictionary<EInteger, Entity> polynomial, int power)
                => polynomial.TryGetValue(EInteger.FromInt32(power), out var coefficient) ? coefficient : Number.Integer.Zero;

            // P: the first k terms of the power series of N/B at 0.
            var series = new Entity[k];
            for (var j = 0; j < k; j++)
            {
                var sum = Coefficient(above, j);
                for (var i = 1; i <= j; i++)
                    sum -= Coefficient(below, i) * series[j - i];
                series[j] = Functions.PartialFractions.InLowestTermsOverTheSymbols(sum / constant);
            }

            // R = (N - P B)/x^k, whose coefficient of x^(m - k) is that of x^m in N - P B.
            Entity remainder = Number.Integer.Zero;
            for (var m = k; m <= System.Math.Max(degreeAbove, degreeBelow + k - 1); m++)
            {
                var coefficient = Coefficient(above, m);
                for (var j = System.Math.Max(0, m - degreeBelow); j <= System.Math.Min(k - 1, m); j++)
                    coefficient -= series[j] * Coefficient(below, m - j);
                coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficient);
                if (!VanishesIdentically(coefficient))
                    remainder += m == k ? coefficient : coefficient * MathS.Pow(x, m - k);
            }

            // The part over x^k term by term, and the rest over the block as it is written.
            Entity overX = Number.Integer.Zero;
            for (var j = 0; j < k; j++)
                if (!VanishesIdentically(series[j]))
                    overX += j == k - 1
                        ? series[j] * IntegralPatterns.AntiderivativeLog(x)
                        : series[j] * MathS.Pow(x, j - k + 1) / (j - k + 1);
            if (remainder == Number.Integer.Zero)
                return overX;
            return Integration.ComputeIndefiniteIntegral(remainder / block, x, integrateByParts) is { } overTheBlock
                ? overX + overTheBlock
                : null;
        }

        /// <summary>
        /// <c>N/(L^k B)</c> for a linear <c>L = g + h x</c> other than x, beside a block <c>B</c>
        /// with a symbol in it, past the second degree, that does not vanish at the root of L:
        /// split there as <see cref="IntegrateOverAPowerOfXBesideABlock"/> splits at 0. With
        /// <c>s = x - r</c>, <c>r = -g/h</c>, <c>N/B</c> has a power series in <c>s</c>, and its first
        /// <c>k</c> terms <c>P</c> are the part over <c>s^k</c>: <c>N/(s^k B) = P/s^k + R/B</c>, with
        /// <c>R = (N - P B)/s^k</c> exactly.
        /// </summary>
        /// <remarks>
        /// <c>1/(x (a + b (c + d x)^3))</c> is <c>1/((u - c)(a + b u^3))</c> in <c>u = c + d x</c>: a
        /// linear beside a binomial, which nothing took apart, since the split over written
        /// factors takes linear and quadratic blocks only. The coefficients of N and B at the
        /// root are read by Taylor's formula, and the block is left as it is written, for the
        /// rules that read it. Rubi's 1.3.1.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? IntegrateOverAPowerOfALinearBesideABlock(Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            // For the question asked, or one substitution below it: the rest over the block is
            // integrated again.
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            Entity? linear = null;
            var k = 0;
            Entity block = Number.Integer.One;
            var pastTheSecondDegree = false;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                var (@base, power) = factor is Powf(var raised, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (raised, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                if (@base != x && @base.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(@base, x, out var slope, out var offset)
                    && !slope.ContainsNode(x) && !offset.ContainsNode(x))
                {
                    if (linear is { } && linear != @base)
                        return null;
                    linear = @base;
                    k += power;
                }
                else
                {
                    block = block == Number.Integer.One ? factor : block * factor;
                    pastTheSecondDegree |= TreeAnalyzer.TryGetPolynomial(@base, x, out var terms) && terms.Keys.Any(degree => degree.CompareTo(EInteger.FromInt32(2)) > 0);
                }
            }
            if (linear is null || k > MaximumPowerOfXBesideABlock || !pastTheSecondDegree || !block.ContainsNode(x) || !block.Vars.Any(symbol => symbol != x)
                || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var h, out var g) || VanishesIdentically(h)
                || !TreeAnalyzer.TryGetPolynomial(block, x, out var below) || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var above))
                return null;
            foreach (var term in below.Concat(above))
                if (term.Key.Sign < 0 || !term.Key.CanFitInInt32() || term.Value.ContainsNode(x))
                    return null;
            var degreeBelow = below.Keys.Max()!.ToInt32Unchecked();
            var degreeAbove = above.Count == 0 ? 0 : above.Keys.Max()!.ToInt32Unchecked();
            if (degreeBelow > MaximumPowerOfXBesideABlock || degreeAbove > MaximumPowerOfXBesideABlock)
                return null;
            var root = Functions.PartialFractions.InLowestTermsOverTheSymbols(-g / h);
            // N and B in s = x - r, by Taylor's formula.
            Entity[] InS(Dictionary<EInteger, Entity> polynomial, int degree)
            {
                var shifted = new Entity[degree + 1];
                for (var i = 0; i <= degree; i++)
                {
                    Entity sum = Number.Integer.Zero;
                    for (var m = i; m <= degree; m++)
                        if (polynomial.TryGetValue(EInteger.FromInt32(m), out var coefficient))
                            sum += coefficient * Binomial(m, i) * (m == i ? Number.Integer.One : MathS.Pow(root, m - i));
                    shifted[i] = Functions.PartialFractions.InLowestTermsOverTheSymbols(sum);
                }
                return shifted;
            }
            // Where s divides B, the block shares the root.
            var b = InS(below, degreeBelow);
            if (VanishesIdentically(b[0]))
                return null;
            // A block that is a polynomial in a power of the linear, `a + b (c + d x)^3`, makes the
            // whole a function of the linear, which the substitution of it reads. Split here, the
            // rest goes back over that block written in x, which the rules over x search long for:
            // 20 s for `1/((c + d x)^2 (a + b (c + d x)^3)^2)`.
            static int Gcd(int p, int q) => q == 0 ? p : Gcd(q, p % q);
            var stride = 0;
            for (var i = 1; i < b.Length; i++)
                if (!VanishesIdentically(b[i]))
                    stride = Gcd(stride, i);
            if (stride > 1)
                return null;
            // Where s divides N, the part over s^k is nothing and the rest is the question asked
            // again.
            var n = InS(above, degreeAbove);
            if (VanishesIdentically(n[0]))
                return null;
            Entity At(Entity[] polynomial, int power) => power < polynomial.Length ? polynomial[power] : Number.Integer.Zero;

            // P: the first k terms of the power series of N/B at r.
            var series = new Entity[k];
            for (var j = 0; j < k; j++)
            {
                var sum = At(n, j);
                for (var i = 1; i <= j; i++)
                    sum -= At(b, i) * series[j - i];
                series[j] = Functions.PartialFractions.InLowestTermsOverTheSymbols(sum / b[0]);
            }

            // R = (N - P B)/s^k in s, and then in x.
            var top = System.Math.Max(degreeAbove, degreeBelow + k - 1);
            var inS = new Entity[System.Math.Max(top - k + 1, 0)];
            for (var m = k; m <= top; m++)
            {
                var coefficient = At(n, m);
                for (var j = System.Math.Max(0, m - degreeBelow); j <= System.Math.Min(k - 1, m); j++)
                    coefficient -= series[j] * At(b, m - j);
                inS[m - k] = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficient);
            }
            Entity remainder = Number.Integer.Zero;
            for (var j = 0; j < inS.Length; j++)
            {
                Entity sum = Number.Integer.Zero;
                for (var m = j; m < inS.Length; m++)
                    if (!VanishesIdentically(inS[m]))
                        sum += inS[m] * Binomial(m, j) * (m == j ? Number.Integer.One : MathS.Pow(-root, m - j));
                var coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(sum);
                if (!VanishesIdentically(coefficient))
                    remainder += j == 0 ? coefficient : coefficient * (j == 1 ? x : MathS.Pow(x, j));
            }

            // L^k is h^k s^k, and s is L/h: the part over L^k term by term, and the rest over the
            // block as it is written.
            Entity overTheLinear = Number.Integer.Zero;
            for (var j = 0; j < k; j++)
                if (!VanishesIdentically(series[j]))
                    overTheLinear += j == k - 1
                        ? series[j] * IntegralPatterns.AntiderivativeLog(linear)
                        : series[j] * MathS.Pow(h, k - 1 - j) * MathS.Pow(linear, j - k + 1) / (j - k + 1);
            var scale = k == 1 ? h : MathS.Pow(h, k);
            if (remainder == Number.Integer.Zero)
                return overTheLinear / scale;
            return Integration.ComputeIndefiniteIntegral(remainder / block, x, integrateByParts) is { } overTheBlock
                ? (overTheLinear + overTheBlock) / scale
                : null;

            static Entity Binomial(int n, int k)
            {
                var result = EInteger.One;
                for (var i = 1; i <= k; i++)
                    result = result.Multiply(EInteger.FromInt32(n - k + i)).Divide(EInteger.FromInt32(i));
                return Number.Integer.Create(result);
            }
        }

        /// <summary>
        /// <c>N/(B_1 ... B_m)</c> where every block <c>B_i</c> is a polynomial in <c>x^n</c> for one
        /// <c>n >= 2</c>, linear or quadratic in it, with a symbol among them: split in
        /// <c>u = x^n</c> by <see cref="Functions.PartialFractions.TrySplitOverWrittenFactors"/>,
        /// one residue of the numerator's powers modulo <c>n</c> at a time, each fraction then
        /// over one block in x.
        /// </summary>
        /// <remarks>
        /// <c>1/((a + b x^3)(c + d x^3))</c> was declined: over the rationals it does not factor,
        /// and the split over written factors reads a block of the third degree as nothing. In
        /// <c>u = x^3</c> it is <c>1/((a + b u)(c + d u))</c>, two linear factors. A numerator
        /// term <c>x^r M(x^n)</c> keeps its <c>x^r</c> outside the split, which is exact since
        /// the blocks are polynomials in <c>x^n</c> alone.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? IntegrateOverBlocksInAPowerOfX(Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts, bool oneBlockAtItsRoots = false)
        {
            var blocks = new List<(Dictionary<EInteger, Entity> Polynomial, int Power)>();
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant == Number.Integer.One ? factor : constant * factor;
                    continue;
                }
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (b, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var polynomial) || polynomial.Count < 2)
                    return null;
                foreach (var term in polynomial)
                    if (term.Key.Sign < 0 || !term.Key.CanFitInInt32() || term.Value.ContainsNode(x))
                        return null;
                // A block x divides is the content's to take apart, not one to split at roots:
                // `b x^4 + c x^8`, read as quadratic in x^4 with no constant term, has
                // `(-b ± sqrt(b^2))/(2 c)` for roots, one of them a zero that is not recognised.
                if (!polynomial.TryGetValue(EInteger.Zero, out var blockConstant) || VanishesIdentically(blockConstant))
                    return null;
                blocks.Add((polynomial, power));
            }
            if (blocks.Count == 0 || !(numerator + denominator).Vars.Any(symbol => symbol != x))
                return null;
            // n, the greatest common divisor of every power the blocks hold.
            var n = EInteger.Zero;
            foreach (var (polynomial, _) in blocks)
                foreach (var power in polynomial.Keys)
                    n = n.Gcd(power);
            // In x^2 for two blocks or more only: one quadratic in x^2 is the biquadratic rule's.
            if (n.CompareTo(EInteger.FromInt32(2)) < 0 || n.Equals(EInteger.FromInt32(2)) && blocks.Count < 2
                || n.CompareTo(EInteger.FromInt32(MaximumPowerOfXBesideABlock)) > 0)
                return null;
            var step = n.ToInt32Unchecked();
            foreach (var (polynomial, _) in blocks)
                if (polynomial.Keys.Max()!.ToInt32Unchecked() / step > 2)
                    return null;
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above))
                return null;
            foreach (var term in above)
                if (term.Key.Sign < 0 || !term.Key.CanFitInInt32() || term.Value.ContainsNode(x))
                    return null;

            var u = Entity.Variable.CreateUnique(numerator + denominator, "u");
            Entity InU(Dictionary<EInteger, Entity> polynomial)
            {
                Entity sum = Number.Integer.Zero;
                foreach (var entry in polynomial.OrderBy(term => term.Key))
                {
                    var (power, coefficient) = (entry.Key, entry.Value);
                    var degree = power.ToInt32Unchecked() / step;
                    var term = degree == 0 ? coefficient : coefficient * (degree == 1 ? u : MathS.Pow(u, degree));
                    sum = sum == Number.Integer.Zero ? term : sum + term;
                }
                return sum;
            }
            var inUBlocks = blocks.Select(pair => (Block: InU(pair.Polynomial), pair.Power)).ToList();
            // One block, quadratic in u, is two at its roots: `a + b u + c u^2` is
            // `c (u - r_1)(u - r_2)` with `r = (-b ± sqrt(b^2 - 4 a c))/(2 c)`, exact wherever the
            // two differ, which is the generic case; a discriminant that is zero as written declines.
            if (inUBlocks.Count == 1)
            {
                // Last, from SolveByOneBlockInAPowerOfXAtItsRoots: the roots are complex where
                // b^2 < 4ac, and a rule after the split that branches on the sign of one has no
                // branch for it. `x (a + b x^4)/(c + d x^4 + e x^8)` comes to `x/(x^4 - r)`, and the
                // table's piecewise on the sign of `r` has no value anywhere for a complex `r`,
                // where the substitution `v = x^2` answers the block whole.
                if (!oneBlockAtItsRoots)
                    return null;
                var (polynomial, power) = blocks[0];
                if (polynomial.Keys.Max()!.ToInt32Unchecked() != 2 * step)
                    return null;
                Entity At(int degree) => polynomial.TryGetValue(EInteger.FromInt32(degree * step), out var coefficient) ? coefficient : Number.Integer.Zero;
                var (a, b, c) = (At(0), At(1), At(2));
                var discriminant = b * b - 4 * a * c;
                if (VanishesIdentically(discriminant))
                    return null;
                var root = MathS.Sqrt(discriminant);
                var first = Functions.PartialFractions.InLowestTermsOverTheSymbols((-b + root) / (2 * c));
                var second = Functions.PartialFractions.InLowestTermsOverTheSymbols((-b - root) / (2 * c));
                constant = constant == Number.Integer.One ? (power == 1 ? c : MathS.Pow(c, power)) : constant * (power == 1 ? c : MathS.Pow(c, power));
                inUBlocks = new List<(Entity Block, int Power)> { (u - first, power), (u - second, power) };
            }
            Entity below = constant;
            foreach (var (block, power) in inUBlocks)
                below = below == Number.Integer.One ? (power == 1 ? block : MathS.Pow(block, power)) : below * (power == 1 ? block : MathS.Pow(block, power));

            Entity total = Number.Integer.Zero;
            foreach (var residue in above.GroupBy(term => term.Key.ToInt32Unchecked() % step))
            {
                Entity inU = Number.Integer.Zero;
                foreach (var entry in residue)
                {
                    var (power, coefficient) = (entry.Key, entry.Value);
                    var degree = power.ToInt32Unchecked() / step;
                    inU += degree == 0 ? coefficient : coefficient * MathS.Pow(u, degree);
                }
                if (!Functions.PartialFractions.TrySplitOverWrittenFactors(inU, below, u, out var decomposition))
                    return null;
                var outside = residue.Key == 0 ? (Entity)Number.Integer.One : residue.Key == 1 ? x : MathS.Pow(x, residue.Key);
                foreach (var fraction in Sumf.LinearChildren(decomposition))
                {
                    var inX = outside * fraction.Substitute(u, MathS.Pow(x, step));
                    if (Integration.ComputeIndefiniteIntegral(inX, x, integrateByParts) is not { } integrated)
                        return null;
                    total += integrated;
                }
            }
            return total;
        }

        /// <summary>
        /// The largest power of x, and the largest degree of the block beside it, that
        /// <see cref="IntegrateOverAPowerOfXBesideABlock"/> takes: Rubi's suite goes to twelve.
        /// </summary>
        private const int MaximumPowerOfXBesideABlock = 12;

        /// <summary>
        /// A polynomial over a power of a binomial, <c>P(x)/(a + b x^n)^k</c> with <c>n &gt;= 3</c>
        /// and <c>k &gt;= 2</c>, a power at a time down to <c>P'(x)/(a + b x^n)</c>, which
        /// <see cref="IntegrateAPolynomialOverABinomial"/> answers at the roots of unity.
        /// </summary>
        /// <remarks>
        /// <para>
        /// For a monomial, with <c>B = a + b x^n</c>,
        /// <code>
        /// int x^m/B^j = x^(m+1)/(a n (j - 1) B^(j-1)) - (m + 1 - n (j - 1))/(a n (j - 1)) int x^m/B^(j-1)
        /// </code>
        /// since the derivative of <c>x^(m+1)/B^(j-1)</c> is <c>(m + 1) x^m/B^(j-1) - (j - 1) n b x^(m+n)/B^j</c>
        /// and <c>b x^(m+n) = x^m B - a x^m</c>. Each monomial of <c>P</c> goes down the powers on
        /// its own, and what reaches the first power is gathered into one polynomial over
        /// <c>B</c>, integrated once.
        /// </para>
        /// <para>
        /// After the Hermite reduction, which answers the square and the cube of a binomial with
        /// symbols in it in one linear solve and keeps those answers. Its system grows with
        /// <c>n k</c>: <c>1/(a + b x^4)^3</c> is answered and <c>1/(a + b x^4)^4</c> was declined.
        /// The constant term is divided by, which is the generic case, as everywhere in the
        /// integrator.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        private static Entity? IntegrateAPolynomialOverAPowerOfABinomial(Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            Entity constant = Number.Integer.One;
            Entity? binomial = null;
            var power = 0;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                    constant = constant == Number.Integer.One ? factor : constant * factor;
                else if (binomial is null && factor is Powf(var @base, Number.Integer { EInteger: var e }) && e.CompareTo(EInteger.FromInt32(2)) >= 0 && e.CanFitInInt32())
                {
                    binomial = @base;
                    power = e.ToInt32Unchecked();
                }
                else
                    return null;
            }
            if (binomial is null || power > MaximumPowerOfABinomial
                || !TreeAnalyzer.TryGetPolynomial(binomial, x, out var below) || below.Count != 2
                || !below.TryGetValue(EInteger.Zero, out var a) || IsZeroAsAValue(a)
                || below.Keys.Max() is not { } top || top.CompareTo(EInteger.FromInt32(3)) < 0 || !top.CanFitInInt32()
                || IsZeroAsAValue(below[top])
                || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var above)
                || above.Keys.Any(degree => degree.Sign < 0 || !degree.CanFitInInt32())
                || above.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var n = top.ToInt32Unchecked();

            // Each monomial down the powers: the algebraic part over B^(j - 1) gathered by j, and
            // what is left at the first power gathered by the monomial's degree.
            var overPowers = new Dictionary<int, Entity>();
            var atTheFirst = new Dictionary<int, Entity>();
            foreach (var pair in above)
            {
                var m = pair.Key.ToInt32Unchecked();
                var coefficient = pair.Value;
                for (var j = power; j >= 2 && coefficient != Number.Integer.Zero; j--)
                {
                    var over = a * n * (j - 1);
                    var term = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficient / over) * MathS.Pow(x, m + 1);
                    overPowers[j - 1] = overPowers.TryGetValue(j - 1, out var so) ? so + term : term;
                    coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(-coefficient * (m + 1 - n * (j - 1)) / over);
                }
                if (coefficient != Number.Integer.Zero)
                    atTheFirst[m] = atTheFirst.TryGetValue(m, out var so) ? so + coefficient : coefficient;
            }

            Entity answer = Number.Integer.Zero;
            foreach (var pair in overPowers.OrderByDescending(pair => pair.Key))
                answer = answer + pair.Value / (pair.Key == 1 ? binomial : MathS.Pow(binomial, pair.Key));
            if (atTheFirst.Count > 0)
            {
                Entity rest = Number.Integer.Zero;
                foreach (var pair in atTheFirst.OrderBy(pair => pair.Key))
                    rest = rest + pair.Value * (pair.Key == 0 ? Number.Integer.One : pair.Key == 1 ? x : MathS.Pow(x, pair.Key));
                if (Integration.ComputeIndefiniteIntegral(rest / binomial, x, integrateByParts) is not { } overTheBinomial)
                    return null;
                answer = answer + overTheBinomial;
            }
            return (constant == Number.Integer.One ? answer : answer / constant).InnerSimplified;

            static bool IsZeroAsAValue(Entity e) => e.Evaled is Number.Complex { IsZero: true };
        }

        /// <summary>
        /// The largest power of a binomial <see cref="IntegrateAPolynomialOverAPowerOfABinomial"/>
        /// takes down, one algebraic term a monomial a power.
        /// </summary>
        private const int MaximumPowerOfABinomial = 12;

        /// <summary>
        /// A polynomial over a power of a trinomial in <c>x^n</c>,
        /// <c>P(x)/(a + b x^n + c x^(2n))^k</c> with <c>n &gt;= 2</c> and <c>k &gt;= 2</c>, a power at
        /// a time down to a polynomial over the trinomial itself.
        /// </summary>
        /// <remarks>
        /// <para>
        /// For a monomial, with <c>w = x^n</c>, <c>T = a + b w + c w^2</c> and <c>D = 4 a c - b^2</c>,
        /// the derivative of <c>x^(m+1) (beta0 + beta1 w) T^(p+1)</c> is
        /// <c>x^m T^p + delta0 x^m T^(p+1) + delta1 x^(m+n) T^(p+1)</c>, where
        /// <code>
        /// beta0  = (b^2 - 2 a c)/(a n (p + 1) D),       beta1 = b c/(a n (p + 1) D),
        /// delta0 = -((2 a c - b^2)(m + 1) + n (p + 1) D)/(a n (p + 1) D),
        /// delta1 = b c (m + 2 n p + 3 n + 1)/(a n (p + 1) D),
        /// </code>
        /// which is what matching the powers of <c>w</c> in
        /// <c>(m + 1)(beta0 + beta1 w) T + n beta1 w T + (p + 1) n w (b + 2 c w)(beta0 + beta1 w)</c>
        /// against <c>1 + (delta0 + delta1 w) T</c> gives. So <c>int x^m T^p</c> is that algebraic
        /// term, less <c>delta0 int x^m T^(p+1)</c> and <c>delta1 int x^(m+n) T^(p+1)</c>: two
        /// monomials a power up. What reaches the first power is gathered into one polynomial
        /// over <c>T</c> and integrated once.
        /// </para>
        /// <para>
        /// After the Hermite reduction, which answers the square with symbols in it in one linear
        /// solve and keeps those answers; its system grows with the degree, and
        /// <c>x^4/(a + b x^2 + c x^4)^3</c> was declined. Rubi's 1.2.2.2 and 1.2.2.4 have these by the
        /// dozen. <c>a</c> and <c>D</c> are divided by, which is the generic case, as everywhere in
        /// the integrator: <c>D = 0</c> is a square, which the rules for one take.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        private static Entity? IntegrateAPolynomialOverAPowerOfATrinomial(Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            Entity constant = Number.Integer.One;
            Entity? trinomial = null;
            var power = 0;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                    constant = constant == Number.Integer.One ? factor : constant * factor;
                else if (trinomial is null && factor is Powf(var @base, Number.Integer { EInteger: var e }) && e.CompareTo(EInteger.FromInt32(2)) >= 0 && e.CanFitInInt32())
                {
                    trinomial = @base;
                    power = e.ToInt32Unchecked();
                }
                else
                    return null;
            }
            if (trinomial is null || power > MaximumPowerOfABinomial
                || !TreeAnalyzer.TryGetPolynomial(trinomial, x, out var below) || below.Count != 3
                || below.Keys.Any(degree => !degree.CanFitInInt32()) || below.Values.Any(coefficient => coefficient.ContainsNode(x))
                || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var above)
                || above.Keys.Any(degree => degree.Sign < 0 || !degree.CanFitInInt32())
                || above.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degrees = below.Keys.Select(degree => degree.ToInt32Unchecked()).OrderBy(degree => degree).ToArray();
            var n = degrees[1];
            if (degrees[0] != 0 || n < 2 || degrees[2] != 2 * n)
                return null;
            var (a, b, c) = (below[EInteger.Zero], below[EInteger.FromInt32(n)], below[EInteger.FromInt32(2 * n)]);
            var discriminant = 4 * a * c - b * b;
            if (VanishesIdentically(a) || VanishesIdentically(c) || VanishesIdentically(b) || VanishesIdentically(discriminant))
                return null;

            // Each monomial down the powers: the algebraic part over T^(j - 1) gathered by j, and
            // what is left at the first power gathered by the monomial's degree.
            var overPowers = new Dictionary<int, Entity>();
            var atThisPower = new Dictionary<int, Entity>();
            foreach (var pair in above)
                atThisPower[pair.Key.ToInt32Unchecked()] = pair.Value;
            for (var j = power; j >= 2; j--)
            {
                var p = -j;
                var over = a * n * (p + 1) * discriminant;
                var beta0 = Functions.PartialFractions.InLowestTermsOverTheSymbols((b * b - 2 * a * c) / over);
                var beta1 = Functions.PartialFractions.InLowestTermsOverTheSymbols(b * c / over);
                var atTheNext = new Dictionary<int, Entity>();
                foreach (var pair in atThisPower)
                {
                    var (m, coefficient) = (pair.Key, pair.Value);
                    if (VanishesIdentically(coefficient))
                        continue;
                    var term = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficient * beta0) * MathS.Pow(x, m + 1)
                        + Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficient * beta1) * MathS.Pow(x, m + 1 + n);
                    overPowers[j - 1] = overPowers.TryGetValue(j - 1, out var so) ? so + term : term;
                    var delta0 = -((2 * a * c - b * b) * (m + 1) + n * (p + 1) * discriminant) / over;
                    var delta1 = b * c * (m + 2 * n * p + 3 * n + 1) / over;
                    foreach (var (degree, times) in new[] { (m, delta0), (m + n, delta1) })
                    {
                        var next = Functions.PartialFractions.InLowestTermsOverTheSymbols(-coefficient * times);
                        atTheNext[degree] = atTheNext.TryGetValue(degree, out var already)
                            ? Functions.PartialFractions.InLowestTermsOverTheSymbols(already + next) : next;
                    }
                }
                atThisPower = atTheNext;
            }

            Entity answer = Number.Integer.Zero;
            foreach (var pair in overPowers.OrderByDescending(pair => pair.Key))
                answer = answer + pair.Value / (pair.Key == 1 ? trinomial : MathS.Pow(trinomial, pair.Key));
            Entity rest = Number.Integer.Zero;
            foreach (var pair in atThisPower.OrderBy(pair => pair.Key))
                if (!VanishesIdentically(pair.Value))
                    rest = rest + pair.Value * (pair.Key == 0 ? Number.Integer.One : pair.Key == 1 ? x : MathS.Pow(x, pair.Key));
            if (rest != Number.Integer.Zero)
            {
                if (Integration.ComputeIndefiniteIntegral(rest / trinomial, x, integrateByParts) is not { } overTheTrinomial)
                    return null;
                answer = answer + overTheTrinomial;
            }
            return (constant == Number.Integer.One ? answer : answer / constant).InnerSimplified;
        }

        /// <summary>
        /// A polynomial over a binomial <c>a x^n + b</c>, <c>n >= 3</c>, decomposed at the
        /// <c>n</c>-th roots of <c>-b/a</c> and integrated term by term in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(x^3 + 1)</c> had an antiderivative and <c>1/(x^3 + 2)</c> did not: the first
        /// factors over the rationals and the coprime split takes it apart, the second does not
        /// and nothing further was tried. The same for <c>1/(x^5 + 1)</c>, <c>1/(x^6 + 2)</c> and
        /// every <c>1/(a x^n + b)</c> with a symbol in it, which no split over the rationals can
        /// reach at all. Rubi's test suite has these by the dozen.
        /// </para>
        /// <para>
        /// <b>The decomposition is a formula, not a computation.</b> Writing the denominator as
        /// <c>a (x^n - c)</c> with <c>c = -b/a</c> and <c>rho^n = c</c>, the roots are
        /// <c>rho e^(i theta_k)</c> and the residue of <c>x^m/(x^n - c)</c> at one of them is
        /// <c>rho^(m+1-n) e^(i (m+1-n) theta_k) / n</c>. A root on the real line gives
        /// <c>rho^(m+1-n) cos((m+1-n) theta) / n</c> over <c>x - rho cos(theta)</c>; a conjugate
        /// pair gives, over <c>x^2 - 2 rho cos(theta) x + rho^2</c>,
        /// </para>
        /// <code>
        ///     (2 rho^(m+1-n) / n) (cos((m+1-n) theta) x - rho cos((m-n) theta))
        /// </code>
        /// <para>
        /// and each of those is a logarithm plus an arctangent, written out here rather than
        /// handed back to the integrator: the quadratic is <c>(x - h)^2 + k^2</c> with
        /// <c>h = rho cos(theta)</c> and <c>k = rho sin(theta)</c>, and
        /// <c>int (P x + Q) / ((x - h)^2 + k^2) dx</c> is
        /// <c>(P/2) ln((x - h)^2 + k^2) + ((Q + P h)/k) arctan((x - h)/k)</c>. Handing the pieces
        /// back would have the quadratic rule decide the sign of a discriminant that is
        /// <c>-4 rho^2 sin^2(theta)</c> and cannot be read as negative once <c>rho</c> is a
        /// symbol, and answer with a piecewise for what is one branch.
        /// </para>
        /// <para>
        /// <b>Which roots, by the sign of <c>c</c>.</b> For <c>c &gt; 0</c> the real
        /// <c>rho = c^(1/n)</c> puts the roots at <c>2 pi k / n</c>; for <c>c &lt; 0</c> it is
        /// <c>rho = (-c)^(1/n)</c> and they sit at <c>pi (2k + 1) / n</c>, so that every
        /// <c>rho</c> and every angle is real and the answer is real on the real line. A symbol
        /// has no sign to read, and takes the first form with <c>rho = c^(1/n)</c>: the
        /// factorisation <c>x^n - c = prod (x - rho zeta_k)</c> is an identity for any
        /// <c>rho</c> with <c>rho^n = c</c>, so the antiderivative is correct for every
        /// <c>c</c> and happens to be written through a complex <c>rho</c> where <c>c</c> is
        /// negative -- which is what Rubi's own answer for <c>1/(a + b x^3)</c> does with its
        /// <c>(a/b)^(1/3)</c>, and is the generic case this integrator gives elsewhere.
        /// </para>
        /// <para>
        /// After every split over the rationals, so that a denominator which factors exactly
        /// keeps the exact answer it had. A proper fraction only; an improper one has been
        /// divided out above.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? IntegrateAPolynomialOverABinomial(Entity numerator, Entity denominator, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(denominator, x, out var below) || below.Count != 2
                || !below.TryGetValue(EInteger.Zero, out var b))
                return null;
            var degree = below.Keys.First(power => !power.IsZero);
            if (!degree.CanFitInInt32() || degree.ToInt32Unchecked() is var n && (n < 3 || n > MaximumBinomialDegree))
                return null;
            var a = below[degree];
            if (a.ContainsNode(x) || b.ContainsNode(x)
                || a.Evaled is Number.Complex { IsZero: true } || b.Evaled is Number.Complex { IsZero: true })
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above))
                return null;
            foreach (var term in above)
                if (term.Key.Sign < 0 || term.Key.CompareTo(degree) >= 0 || term.Value.ContainsNode(x))
                    return null;

            // a x^n + b = a (x^n - c). The roots are rho e^(i pi t), for t = (2k + offset)/n.
            var c = (-b / a).InnerSimplified;
            var offset = 0;
            Entity rho;
            // A symbol has no sign to read, but it has a spelling: `x^3 + a` arrives as
            // `c = -a`, and taking `rho = a^(1/3)` with the roots at the odd multiples is the
            // real answer for the sign the integrand was evidently written for, where
            // `(-a)^(1/3)` would be a complex one for it. Either is correct; this one is the
            // one a reader expects.
            if (c.Evaled is Number.Real { IsFinite: true } sign && sign < 0
                || c is Mulf(var leading, _) && leading.Evaled is Number.Real { IsFinite: true } negative && negative < 0)
            {
                rho = MathS.Pow(-c, Number.Rational.Create(1, n));
                offset = 1;
            }
            else
                rho = MathS.Pow(c, Number.Rational.Create(1, n));
            rho = rho.InnerSimplified;

            Entity total = 0;
            for (var k = 0; k < n; k++)
            {
                var twiceKPlusOffset = 2 * k + offset;
                // Past pi the roots are the conjugates of the ones before it, and each pair is
                // taken once, at its representative below pi.
                if (twiceKPlusOffset > n)
                    break;
                var theta = MathS.pi * Number.Rational.Create(twiceKPlusOffset, n);
                foreach (var term in above)
                {
                    var m = term.Key.ToInt32Unchecked();
                    var coefficient = term.Value;
                    // rho^(m+1-n) / n, the modulus of the residue at every root.
                    var modulus = (coefficient * MathS.Pow(rho, m + 1 - n) / n).InnerSimplified;
                    if (twiceKPlusOffset == 0)
                        total += modulus * IntegralPatterns.AntiderivativeLog(x - rho);
                    else if (twiceKPlusOffset == n)
                        total += modulus * ((m + 1 - n) % 2 == 0 ? 1 : -1) * IntegralPatterns.AntiderivativeLog(x + rho);
                    else
                    {
                        var p = (2 * modulus * MathS.Cos((m + 1 - n) * theta)).InnerSimplified;
                        var q = (-2 * modulus * rho * MathS.Cos((m - n) * theta)).InnerSimplified;
                        var h = (rho * MathS.Cos(theta)).InnerSimplified;
                        var kappa = (rho * MathS.Sin(theta)).InnerSimplified;
                        var quadratic = MathS.Sqr(x) - 2 * h * x + MathS.Sqr(rho);
                        total += p / 2 * MathS.Ln(quadratic) + (q + p * h) / kappa * MathS.Arctan((x - h) / kappa);
                    }
                }
            }
            return (total / a).InnerSimplified;
        }

        /// <summary>
        /// The largest binomial degree <see cref="IntegrateAPolynomialOverABinomial"/> takes on.
        /// Every root past the first two is a logarithm and an arctangent, so the answer's size
        /// is linear in the degree; the cap keeps a stray <c>x^1000 + 1</c> from being answered
        /// with five hundred of each. Rubi's suite goes to twelve.
        /// </summary>
        private const int MaximumBinomialDegree = 24;

        /// <summary>
        /// <c>N/(c g(x))</c> integrated as <c>(1/c) * N/g(x)</c>, where <c>c</c> is whatever part
        /// of the denominator is free of the variable.
        /// </summary>
        /// <remarks>
        /// The constant is a constant wherever it stands, and the two branches above take it out
        /// only when it is the *whole* of one side — so <c>a * (1/(1 + x^3))</c> was answered and
        /// <c>1/(a*(1 + x^3))</c>, the same number, was not. Everything downstream reads the
        /// denominator as a polynomial over the rationals, and a symbolic factor stops it being
        /// one, so leaving the factor in place is not a neutral choice.
        ///
        /// It terminates because the denominator handed on has strictly fewer factors, and
        /// declines at once where there is no constant factor to take.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? TakeConstantFactorOutOfDenominator(
            Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            Entity? constantPart = null;
            Entity? variablePart = null;
            foreach (var factor in Entity.Mulf.LinearChildren(denominator))
                if (!factor.ContainsNode(x))
                    constantPart = constantPart is null ? factor : constantPart * factor;
                // A whole power of a polynomial with a symbolic leading coefficient is that
                // coefficient's power times the power of the monic polynomial: `t^2/(b - d t^2)^3`
                // is `1/(-d)^3` times `t^2/(t^2 - b/d)^3`, and the rational rules with a symbol
                // in the leading place answer the first power and not the third -- the
                // quotient of two linear radicals hands on exactly this for Hearn's
                // `sqrt(a + b x) sqrt(c + d x)`. The first power is left as written, its table
                // rules reading the coefficient where it is. Built without a stray `1 *`, since
                // the table rules read the shape as written. And not where the polynomial
                // stands under a root elsewhere in the integrand as well -- in
                // `1/(x (a + b x)^2 sqrt(1/(a + b x)^2 - 1))`, which by parts leaves from
                // `asech(a + b x)/x^2` -- since `(a/b + x)^2` beside `sqrt(1/(a + b x)^2 - 1)`
                // is two spellings of one linear, and the power written apart from the root
                // cancels against the one and not the other. Under a root only: Hearn's
                // `sqrt(a + b x) sqrt(c + d x)` hands on the polynomial as a plain factor
                // above the bar too, and the monic power is what answers it there.
                else if (factor is Powf(var polynomial, Number.Integer power) && power.EInteger.CompareTo(EInteger.FromInt32(2)) >= 0
                         && TreeAnalyzer.TryGetPolynomial(polynomial, x, out var read) && read.Count > 1
                         && read.Keys.Max() is { } top && read[top] is var leading && !leading.ContainsNode(x) && leading.Evaled is not Number
                         && !numerator.Nodes.Concat(denominator.Nodes).Any(node =>
                                node is Powf(var radicand, Number.Rational r) && r is not Number.Integer && radicand.Nodes.Contains(polynomial)))
                {
                    var leadingPower = MathS.Pow(leading, power);
                    constantPart = constantPart is null ? leadingPower : constantPart * leadingPower;
                    Entity? monic = null;
                    foreach (var pair in read.OrderBy(pair => pair.Key))
                    {
                        // In lowest terms over the symbols: the coefficient is read as `a` and the
                        // leading one as `1 * a * 1^2`, and the quotient of the two spellings is
                        // `a/a`, which the simplifier keeps -- it is `a^0` by the time the chain reads
                        // it, and `a^0 + 2 b/a x + x^2`, the monic form of `a x^2 + 2 b x + a`, was a
                        // quadratic the split over linear factors could not read.
                        Entity coefficient = pair.Key.Equals(top) ? Number.Integer.One
                            : Functions.PartialFractions.InLowestTermsOverTheSymbols(pair.Value / leading);
                        var degree = pair.Key.ToInt32Checked();
                        Entity term = degree == 0 ? coefficient
                            : coefficient == Number.Integer.One ? (degree == 1 ? x : MathS.Pow(x, degree))
                            : coefficient * (degree == 1 ? x : MathS.Pow(x, degree));
                        monic = monic is null ? term : monic + term;
                    }
                    var monicPower = MathS.Pow(monic!, power);
                    variablePart = variablePart is null ? monicPower : variablePart * monicPower;
                }
                else
                    variablePart = variablePart is null ? factor : variablePart * factor;

            // Only where the denominator genuinely mixes the two. A denominator that is entirely
            // constant, or entirely in the variable, is one of the branches below's to answer,
            // and taking this one would hand on `N/1` and go round again.
            if (constantPart is null || variablePart is null)
                return null;

            return Integration.ComputeAsTheSameQuestion(numerator / variablePart, x, integrateByParts)
                ?.Pipe(i => i / constantPart);
        }

        /// <summary>
        /// The same for a numerator that is a product with a constant factor in it:
        /// <c>sqrt(2) sqrt(1 - t^2)/(t^2 + 1)</c> is <c>sqrt(2)</c> times a quotient Euler's
        /// substitution answers, and with the root of two inside the quotient -- a radical
        /// beside the radical -- it and the rules beside it declined. The tangent
        /// substitution hands on exactly that for Timofeev's <c>sqrt(cot(2x)/cot(x))</c>.
        /// </summary>
        private static Entity? TakeConstantFactorOutOfNumerator(
            Entity numerator, Entity denominator, Entity.Variable x, bool integrateByParts)
        {
            // Neither started from a 1: `1 * f` is a shape, and it was handed on as one.
            Entity? constantPart = null;
            Entity? variablePart = null;
            foreach (var factor in Entity.Mulf.LinearChildren(numerator))
                if (factor.ContainsNode(x))
                    variablePart = variablePart is null ? factor : variablePart * factor;
                else
                    constantPart = constantPart is null ? factor : constantPart * factor;
            if (constantPart is null || variablePart is null)
                return null;
            // A rational constant is read by every rule that reads the quotient, and is left
            // where it is: taken out, the `-1` in front of what the tangent substitution makes
            // of Timofeev's 568 sent the quotient down a search that did not return, where the
            // rule for combining radicals answers it with the sign in place in three seconds.
            if (constantPart.Evaled is Number.Rational)
                return null;
            // As the same question: the quotient without its constant is the question asked,
            // strictly smaller and no continuation of any search, and one level down the
            // rules scoped to the top or to one below it would not see it.
            return Integration.ComputeAsTheSameQuestion(variablePart / denominator, x, integrateByParts)
                ?.Pipe(i => constantPart * i);
        }

        /// <summary>
        /// Reads <paramref name="expr"/> as a numerator over a denominator, in either of the two
        /// spellings a quotient has here.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(1 + x^3)</c> is a <c>Divf</c> and <c>(1 + x^3)^(-1)</c> is a <c>Powf</c>, and
        /// they are the same integrand. <see cref="SolveByPartialFractions"/> matched the first
        /// and declined the second, so which of them was asked decided whether the integral came
        /// back — and the second is not an exotic way to write it: it is what
        /// <see cref="SolveAsPolynomialTerm"/> builds whenever it takes a factor out of a
        /// quotient. That is why <c>a/(1 + x^3)</c> had no antiderivative while
        /// <c>1/(1 + x^3)</c> and <c>a * (1/(1 + x^3))</c> both did.
        /// </para>
        /// <para>
        /// <b>And the third spelling, a product with a negative power in it.</b>
        /// <c>3 u (4 - u^3)^(-1)</c> is what <c>Simplify</c> makes of <c>3u/(4 - u^3)</c>, and it
        /// is neither a <c>Divf</c> nor a bare <c>Powf</c>, so it was declined here -- and then
        /// taken by integration by parts with <c>v' = (4 - u^3)^(-1)</c>, which integrates to a
        /// hundred-node sum of logarithms and arctangents that the search then spent thirty
        /// seconds failing to integrate against <c>3u</c>. Read as the quotient it is, the same
        /// integrand is answered in a fifth of a second. The factors are gathered and one quotient
        /// rebuilt from them, which is what makes the verdict independent of how the product
        /// happens to be associated.
        /// </para>
        /// <para>
        /// <b>Only a negative whole power.</b> A positive one is not a quotient; a fractional or
        /// symbolic exponent is not one either, and <c>(a/b)^(1/2)</c> is not <c>sqrt(a)/sqrt(b)</c>
        /// on the branch cut. Nothing here rewrites a quotient back into a power, so this cannot
        /// re-enter the mutual recursion <see cref="Integration.Normalized"/> records.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        /// <summary>
        /// A rational function with rational coefficients whose denominator the splits above
        /// could not take apart -- irreducible over the rationals past degree two, or with
        /// real factors that carry the roots of something worse -- integrated by the Hermite
        /// reduction and the Rothstein–Trager resultant, in real terms. See
        /// <see cref="RothsteinTrager"/>. After <see cref="SolveByPartialFractions"/>, so that
        /// everything that answers keeps the form it gives.
        /// </summary>
        internal static Entity? SolveByRothsteinTrager(Entity expr, Entity.Variable x)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;
            return RothsteinTrager.Integrate(numerator, denominator, x);
        }

        /// <summary>
        /// A rational function with complex numbers among its coefficients, <c>1/((1 + i x)^2 (1 + x^2))</c>,
        /// which is what the tangent substitution makes of <c>1/(a + i a tan(x))^2</c>. Times the
        /// conjugate of its denominator over itself, <c>N/D = N D'/(D D')</c> with <c>D'</c> the
        /// polynomial whose coefficients are those of <c>D</c> conjugated, the denominator has real
        /// coefficients and the numerator is <c>P + i S</c> with <c>P</c> and <c>S</c> real: the
        /// integral is that of <c>P/(D D')</c> and <c>i</c> times that of <c>S/(D D')</c>, which the
        /// rules for real coefficients answer. An identity of polynomials, so exact wherever the
        /// quotient is defined; the factors free of <c>x</c> are taken out first, and may hold
        /// symbols.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveARationalFunctionWithComplexCoefficients(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;
            Entity constant = Number.Integer.One;
            Number.Complex[]? Read(Entity side, bool below)
            {
                Entity rest = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (!factor.ContainsNode(x))
                        constant = below ? constant / factor : constant * factor;
                    else
                        rest = rest == Number.Integer.One ? factor : rest * factor;
                }
                if (!TreeAnalyzer.TryGetPolynomial(rest, x, out var terms) || terms.Count == 0
                    || terms.Keys.Any(power => power.Sign < 0 || power.CompareTo(EInteger.FromInt32(MaximumComplexRationalDegree)) > 0))
                    return null;
                var coefficients = new Number.Complex[terms.Keys.Max()!.ToInt32Checked() + 1];
                for (var i = 0; i < coefficients.Length; i++)
                    coefficients[i] = Number.Integer.Zero;
                // A product of symbols common to every coefficient, `a + i a x`, goes out with the
                // other constants: each coefficient is its numbers times the same rest.
                Entity? scale = null;
                foreach (var term in terms)
                {
                    Number.Complex number = Number.Integer.One;
                    Entity symbols = Number.Integer.One;
                    foreach (var factor in Mulf.LinearChildren(term.Value.InnerSimplified))
                        if (factor is Number.Complex value)
                            number *= value;
                        else
                            symbols = symbols == Number.Integer.One ? factor : symbols * factor;
                    if (scale is null)
                        scale = symbols;
                    else if (symbols != scale)
                        return null;
                    coefficients[term.Key.ToInt32Checked()] = number;
                }
                if (scale is { } common && common != Number.Integer.One)
                    constant = below ? constant / common : constant * common;
                return coefficients;
            }
            if (Read(numerator, false) is not { } above || Read(denominator, true) is not { } below || below.Length < 2)
                return null;
            static bool OffTheRealLine(Number.Complex[] polynomial) => polynomial.Any(c => !c.ImaginaryPart.IsZero);
            if (!OffTheRealLine(above) && !OffTheRealLine(below))
                return null;
            static Number.Complex[] Times(Number.Complex[] left, Number.Complex[] right)
            {
                var product = new Number.Complex[left.Length + right.Length - 1];
                for (var i = 0; i < product.Length; i++)
                    product[i] = Number.Integer.Zero;
                for (var i = 0; i < left.Length; i++)
                    for (var j = 0; j < right.Length; j++)
                        product[i + j] = product[i + j] + left[i] * right[j];
                return product;
            }
            var conjugate = below.Select(c => c.Conjugate).ToArray();
            var real = Times(below, conjugate);
            var top = Times(above, conjugate);
            Entity Polynomial(IEnumerable<Number.Real> coefficients)
            {
                Entity sum = Number.Integer.Zero;
                var power = 0;
                foreach (var coefficient in coefficients)
                {
                    if (!coefficient.IsZero)
                        sum += power == 0 ? coefficient : coefficient * MathS.Pow(x, power);
                    power++;
                }
                return sum;
            }
            if (real.Any(c => !c.ImaginaryPart.IsZero))
                return null;
            var bottom = Polynomial(real.Select(c => c.RealPart));
            var realPart = Polynomial(top.Select(c => c.RealPart));
            var imaginaryPart = Polynomial(top.Select(c => c.ImaginaryPart));
            Entity answer = Number.Integer.Zero;
            if (!TreeAnalyzer.IsZero(realPart))
            {
                if (Integration.ComputeIndefiniteIntegral(realPart / bottom, x, integrateByParts) is not { } integral)
                    return null;
                answer += integral;
            }
            if (!TreeAnalyzer.IsZero(imaginaryPart))
            {
                if (Integration.ComputeIndefiniteIntegral(imaginaryPart / bottom, x, integrateByParts) is not { } integral)
                    return null;
                answer += MathS.i * integral;
            }
            // In the generic case, as the rules for the two parts answer it.
            return Functions.PartialFractions.Bare((constant * answer).InnerSimplified);
        }

        // The degree past which a rational function with complex coefficients is left alone: its
        // denominator's degree doubles under the conjugate.
        private const int MaximumComplexRationalDegree = 12;

        /// <summary>
        /// <paramref name="numerator"/> over <paramref name="denominator"/> with the greatest
        /// power of <paramref name="x"/> that divides both taken out of each, the denominator's
        /// factors kept as written; the two unchanged where none does, or where a side is not a
        /// polynomial in <paramref name="x"/>.
        /// </summary>
        private static (Entity Numerator, Entity Denominator) WithoutACommonPowerOfX(Entity numerator, Entity denominator, Entity.Variable x)
        {
            static int LowestPower(Dictionary<EInteger, Entity> polynomial)
                => polynomial.Keys.Min()!.ToInt32Unchecked();
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above) || above.Count == 0
                || above.Keys.Any(power => power.Sign < 0 || !power.CanFitInInt32()))
                return (numerator, denominator);
            var factors = new List<(Dictionary<EInteger, Entity>? Polynomial, Entity Written, int Power, int Lowest)>();
            var available = 0;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (b, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                if (!@base.ContainsNode(x))
                {
                    factors.Add((null, factor, 1, 0));
                    continue;
                }
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var polynomial) || polynomial.Count == 0
                    || polynomial.Keys.Any(k => k.Sign < 0 || !k.CanFitInInt32()))
                    return (numerator, denominator);
                var lowest = LowestPower(polynomial);
                factors.Add((polynomial, factor, power, lowest));
                available += lowest * power;
            }
            var common = System.Math.Min(LowestPower(above), available);
            if (common == 0)
                return (numerator, denominator);
            Entity Shifted(Dictionary<EInteger, Entity> polynomial, int by)
            {
                Entity sum = Number.Integer.Zero;
                foreach (var entry in polynomial.OrderBy(term => term.Key))
                {
                    var (power, coefficient) = (entry.Key, entry.Value);
                    var degree = power.ToInt32Unchecked() - by;
                    var term = degree == 0 ? coefficient : coefficient * (degree == 1 ? x : MathS.Pow(x, degree));
                    sum = sum == Number.Integer.Zero ? term : sum + term;
                }
                return sum;
            }
            var left = common;
            Entity below = Number.Integer.One;
            foreach (var (polynomial, written, power, lowest) in factors)
            {
                Entity kept = written;
                if (polynomial is not null && lowest > 0 && left >= lowest * power)
                {
                    var @base = Shifted(polynomial, lowest);
                    kept = power == 1 ? @base : MathS.Pow(@base, power);
                    left -= lowest * power;
                }
                if (kept != Number.Integer.One)
                    below = below == Number.Integer.One ? kept : below * kept;
            }
            // Whatever could not come out of a factor whole stays below the bar as written.
            var taken = common - left;
            return taken == 0 ? (numerator, denominator) : (Shifted(above, taken), below);
        }

        /// <summary>
        /// Whether <paramref name="x"/> stands below a bar somewhere inside
        /// <paramref name="expr"/>: in a divisor, or under a negative whole power.
        /// </summary>
        private static bool HasTheVariableBelowABar(Entity expr, Entity.Variable x)
            => expr.Nodes.Any(node => node is Entity.Divf(_, var divisor) && divisor.ContainsNode(x)
                || node is Entity.Powf(var @base, Number.Integer { EInteger.Sign: < 0 }) && @base.ContainsNode(x));

        private static bool TryReadAsQuotient(Entity expr, out Entity numerator, out Entity denominator)
        {
            // An exponent read evaluated: the normalisation writes `(u^2 - 1)^5` below the bar
            // as `(u^2 - 1)^(5 * (-1))`, a power whose exponent is a product of two numbers and
            // not a number, and `1/((1 - x)^(7/2) x^5)` was declined for it one level down.
            switch (expr)
            {
                case Entity.Divf(var dividend, var divisor):
                    (numerator, denominator) = (dividend, divisor);
                    return true;
                // A whole power of a quotient is the quotient of the powers: `(u/(1 - 2u^2))^2`,
                // which is how the simplifier writes the image of `sqrt((1 + x)/(3 + 2x))`
                // under the root as the variable, read as nothing before.
                case Entity.Powf(Entity.Divf(var dividend, var divisor), var exponent) when exponent.Evaled is Number.Integer { EInteger.Sign: > 0 } power && power != Number.Integer.One:
                    (numerator, denominator) = (MathS.Pow(dividend, power), MathS.Pow(divisor, power));
                    return true;
                case Entity.Powf(var @base, var exponent) when exponent.Evaled is Number.Integer { EInteger.Sign: < 0 } power:
                    // Written out rather than as base^1 when the power is -1, since everything
                    // downstream reads the denominator as a polynomial and a redundant power of
                    // one is a shape it would have to see through.
                    var reciprocated = -power;
                    (numerator, denominator) = (Number.Integer.One,
                        reciprocated == Number.Integer.One ? @base : MathS.Pow(@base, reciprocated));
                    return true;
                case Entity.Mulf:
                    Entity above = Number.Integer.One;
                    Entity below = Number.Integer.One;
                    foreach (var factor in Entity.Mulf.LinearChildren(expr))
                        switch (factor)
                        {
                            case Entity.Powf(var @base, var exponent) when exponent.Evaled is Number.Integer { EInteger.Sign: < 0 } power:
                                var positive = -power;
                                below *= positive == Number.Integer.One ? @base : MathS.Pow(@base, positive);
                                break;
                            case Entity.Powf(Entity.Divf(var dividend, var divisor), var exponent) when exponent.Evaled is Number.Integer { EInteger.Sign: > 0 } power:
                                above *= MathS.Pow(dividend, power);
                                below *= MathS.Pow(divisor, power);
                                break;
                            case Entity.Divf(var dividend, var divisor):
                                above *= dividend;
                                below *= divisor;
                                break;
                            default:
                                above *= factor;
                                break;
                        }
                    if (below == Number.Integer.One)
                    {
                        (numerator, denominator) = (expr, Number.Integer.One);
                        return false;
                    }
                    (numerator, denominator) = (above, below);
                    return true;
                default:
                    (numerator, denominator) = (expr, Number.Integer.One);
                    return false;
            }
        }

        // The constant factors gathered from every position among the factors, where a product
        // read as two operands sees neither of `x^2 * b` and `L` as constant: `x^2 (a + b L)`
        // splits into `a x^2` and `x^2 * b * L`, and the `b` inside the left product was
        // integrated around rather than taken out, by parts against `b L` with the remainder
        // one level deeper than the row without `a + b` -- five minutes where that took one
        // second. Only after the two-operand reading has declined: gathering first sent
        // `1/((a + b x)^2 (c + d x)^(3/2))` down another path and its answer grew from 700
        // characters to 24,000. Asked one level down, as before, and not as a question of its
        // own: that reading made every sub-integrand's constant multiple a top-level question,
        // and the rules scoped to the top then fired everywhere.
        private static Entity? WithTheConstantFactorsOut(Entity.Mulf product, Entity.Variable x, bool integrateByParts)
        {
            // A constant that is the number 1 is a constant found, not none: `1 * x` is x.
            Entity? constant = null;
            Entity? rest = null;
            foreach (var factor in Mulf.LinearChildren(product))
                if (!factor.ContainsNode(x))
                    constant = constant is null ? factor : constant * factor;
                else
                    rest = rest is null ? factor : rest * factor;
            if (constant is null || rest is null)
                return null;
            return Integration.ComputeAsTheSameQuestion(rest, x, integrateByParts)?.Pipe(i => constant * i);
        }

        internal static Entity? SolveAsPolynomialTerm(Entity expr, Entity.Variable x, bool integrateByParts = true) => expr switch
        {
            // The constant factors wherever they stand among the factors: `x^2 * b * L` holds
            // its `b` inside the left product, and read as two operands neither is constant.
            Entity.Mulf(var m1, var m2) product =>
                !m1.ContainsNode(x) ?
                    Integration.ComputeAsTheSameQuestion(m2, x, integrateByParts)?.Pipe(i => m1 * i) :
                !m2.ContainsNode(x) ?
                    Integration.ComputeAsTheSameQuestion(m1, x, integrateByParts)?.Pipe(i => m2 * i) :
                WithTheConstantFactorsOut(product, x, integrateByParts),

            Entity.Divf(var div, var over) =>
                // A denominator that is partly constant is split first, and the order matters.
                // The branch below turns `c/g(x)` into `c * g(x)^(-1)`, and a power is a shape
                // the rational rules do not read -- so `1/(a*(1 + x^3))` went that way and was
                // declined, although `a * (1/(1 + x^3))`, the same number, is taken apart by the
                // Mulf case above. Taking the constant out is both cheaper and more decisive.
                TakeConstantFactorOutOfDenominator(div, over, x, integrateByParts) is { } withoutIt ?
                    withoutIt :
                TakeConstantFactorOutOfNumerator(div, over, x, integrateByParts) is { } withoutItAbove ?
                    withoutItAbove :
                !div.ContainsNode(x) ?
                    // The exponent negated as a number rather than as a tree: `-power` on the
                    // node `2` is `2 * (-1)`, and `sin(x)^(2 * (-1))` is a shape the closed rule
                    // for a power of the sine does not read, so `c/sin(x)^2` went to the
                    // half-angle substitution for what is `-c cot(x)`.
                    over is Entity.Powf(var @base, var power) ?
                        Integration.ComputeIndefiniteIntegral(MathS.Pow(@base, (-power).InnerSimplified), x, integrateByParts)?.Pipe(i => div * i) :
                    // A constant over a product is the reciprocal of the product, asked as the
                    // same question with the constant in front, and not the product to the
                    // power -1: `pe/(x (d + e x) sqrt(1 - c^2 x^2))` handed on as
                    // `(x (d + e x) sqrt(1 - c^2 x^2))^(-1)` was read by no radical rule, where
                    // Euler's substitution reads the reciprocal as written.
                    div != Number.Integer.One ?
                        Integration.ComputeAsTheSameQuestion(Number.Integer.One / over, x, integrateByParts)?.Pipe(i => div * i) :
                        Integration.ComputeIndefiniteIntegral(MathS.Pow(over, -1), x, integrateByParts) :
                !over.ContainsNode(x) ?
                    Integration.ComputeAsTheSameQuestion(div, x, integrateByParts)?.Pipe(i => i / over) :
                null,

            Entity.Powf(var @base, var power) =>
                !power.ContainsNode(x) && @base == x ?
                    IntegrateAPowerOfTheVariable(@base, power, x) :
                    null,

            Entity.Variable v =>
                v == x ? MathS.Pow(x, 2) / 2 : v * x,

            _ => null
        };

        /// <summary>
        /// A polynomial numerator over a denominator with a power of a linear in it beside a
        /// factor that is not a polynomial -- <c>P(x)/((a + b x)^k S(x))</c> -- with the
        /// polynomial written in powers of the linear at its root: what the power divides goes
        /// over <c>S</c> alone, and each lower power over its own power of the linear.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>P(x) = p_0 + p_1 (a + b x) + ... + (a + b x)^k Q(x)</c> is a polynomial identity,
        /// its coefficients the Taylor coefficients of <c>P</c> at <c>-a/b</c> over the powers
        /// of <c>b</c>, so the integrand is <c>Q/S + sum p_j /((a + b x)^(k-j) S)</c> exactly and
        /// everywhere. <c>(A + B x + C x^2 + D x^3)/((a + b x) sqrt(c + d x))</c> was answered
        /// through the substitution <c>u = sqrt(c + d x)</c> term by term, a cubic in
        /// <c>u^2 - c</c> over a symbolic quadratic in <c>u</c> each time, in a hundred kilobytes
        /// of piecewise that did not evaluate within the corpus's budget; reduced, it is a
        /// quadratic over the root, three powers, and one <c>p_0/((a + b x) sqrt(c + d x))</c>.
        /// </para>
        /// <para>
        /// Only beside a factor that is not a polynomial in <c>x</c>: a quotient of polynomials
        /// is the partial fractions' and they do this and more.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByReducingThePolynomialOverALinearFactor(Entity expr, Entity.Variable x, bool integrateByParts)
            => SolveByReducingThePolynomialOverALinearFactor(expr, x, integrateByParts, alone: false);

        /// <summary>
        /// <see cref="SolveByReducingThePolynomialOverALinearFactor(Entity, Entity.Variable, bool)"/>,
        /// or with <paramref name="alone"/> a polynomial over a power of one linear and nothing else,
        /// that linear with a symbol in it: <c>t^9/(a + b t)^8</c> is a polynomial and eight powers of
        /// <c>1/(a + b t)</c>, each the table's. <see cref="SolveByPartialFractions"/> asks it so before
        /// it divides: divided out and decomposed with the symbols in it, that one went round the
        /// substitution search a dozen levels deep and took forty-six seconds, and with numbers in
        /// place of <c>a</c> and <c>b</c> it took sixty milliseconds.
        /// </summary>
        private static Entity? SolveByReducingThePolynomialOverALinearFactor(Entity expr, Entity.Variable x, bool integrateByParts, bool alone)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var polynomial) || polynomial.Count == 0
                || polynomial.Keys.Any(power => power.Sign < 0) || polynomial.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degree = polynomial.Keys.Max()!;
            if (!degree.CanFitInInt32() || degree.ToInt32Unchecked() < 1)
                return null;

            Entity? linear = null;
            var multiplicity = 0;
            Entity rest = Number.Integer.One;
            var somethingElse = false;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    rest *= factor;
                    continue;
                }
                var (@base, power) = factor is Powf(var repeated, Number.Integer { EInteger.Sign: > 0 } times) && times.EInteger.CanFitInInt32()
                    ? (repeated, times.EInteger.ToInt32Unchecked()) : (factor, 1);
                if (linear is null && TreeAnalyzer.TryGetPolynomial(@base, x, out var read) && read.Count > 0
                    && read.Keys.Max()!.Equals(EInteger.One) && read.Values.All(coefficient => !coefficient.ContainsNode(x)))
                {
                    linear = @base;
                    multiplicity = power;
                    continue;
                }
                if (!TreeAnalyzer.TryGetPolynomial(factor, x, out _))
                    somethingElse = true;
                rest *= factor;
            }
            if (linear is null || (alone ? somethingElse || rest.ContainsNode(x) || multiplicity < 2 : !somethingElse))
                return null;

            if (!TreeAnalyzer.TryGetPolynomial(linear, x, out var line))
                return null;
            if (alone && !line.Values.Any(coefficient => coefficient.Vars.Any()))
                return null;
            var beta = line[EInteger.One];
            var alpha = line.TryGetValue(EInteger.Zero, out var constantTerm) ? constantTerm : Number.Integer.Zero;
            var root = Functions.PartialFractions.Bare((-alpha / beta).InnerSimplified);
            var count = degree.ToInt32Unchecked() + 1;
            if (Functions.PartialFractions.TaylorCoefficientsAtTheRoot(numerator, root, count, x) is not { } coefficients)
                return null;

            Entity total = Number.Integer.Zero;
            for (var order = 0; order < multiplicity && order < count; order++)
            {
                if (coefficients[order] == Number.Integer.Zero)
                    continue;
                var over = multiplicity - order;
                var coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficients[order] / MathS.Pow(beta, order));
                var piece = coefficient / ((over == 1 ? linear : MathS.Pow(linear, over)) * rest);
                if (Integration.ComputeIndefiniteIntegral(piece, x, integrateByParts) is not { } integrated)
                    return null;
                total += integrated;
            }
            Entity quotient = Number.Integer.Zero;
            var offset = x - root;
            for (var order = multiplicity; order < count; order++)
            {
                if (coefficients[order] == Number.Integer.Zero)
                    continue;
                var coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(coefficients[order] / MathS.Pow(beta, multiplicity));
                var shift = order - multiplicity;
                quotient += shift == 0 ? coefficient : shift == 1 ? coefficient * offset : coefficient * MathS.Pow(offset, shift);
            }
            if (quotient != Number.Integer.Zero)
            {
                var expanded = Functions.PartialFractions.Bare(quotient.Expand().InnerSimplified);
                if (Integration.ComputeIndefiniteIntegral(expanded / rest, x, integrateByParts) is not { } integrated)
                    return null;
                total += integrated;
            }
            return total;
        }

        /// <summary>
        /// A polynomial in <c>x^2</c> over <c>a + b x^2 + c x^4</c> with a symbol in it, by the
        /// two roots in <c>x^2</c>: with <c>q = sqrt(b^2 - 4 a c)</c> and
        /// <c>r = (-b ± q)/(2c)</c>, <c>(d + e x^2)/(a + b x^2 + c x^4)</c> is
        /// <c>(d + e r_1)/(q (x^2 - r_1)) - (d + e r_2)/(q (x^2 - r_2))</c>, and
        /// <c>1/(x^2 - r)</c> is <c>atan(x/sqrt(-r))/sqrt(-r)</c> for any complex <c>r</c>. A
        /// higher even degree is divided down first, and an odd numerator is left to the
        /// substitution <c>u = x^2</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The partial fractions read written factors, and <c>a + b x^2 + c x^4</c> is written
        /// as one; over the rationals it is factored, over symbols it was declined, and Rubi's
        /// quartic files -- <c>(d x)^m (a + b x^2 + c x^4)^p</c> and the next four -- lost the
        /// even numerators to it: <c>x^2/(a + b x^2 + c x^4)</c>, <c>(d + e x^2)/(...)</c>.
        /// </para>
        /// <para>
        /// Exact wherever the two roots differ, which is the generic case; a discriminant
        /// that is zero as written declines, the square of a quadratic being another shape.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAnEvenPolynomialOverASymbolicBiquadratic(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(denominator, x, out var below) || below.Count == 0
                || !below.ContainsKey(EInteger.FromInt32(4)) || below.Keys.Any(power => !(power.IsZero || power.Equals(EInteger.FromInt32(2)) || power.Equals(EInteger.FromInt32(4))))
                || below.Values.Any(coefficient => coefficient.ContainsNode(x))
                || !denominator.Vars.Any(v => v != x))
                return null;
            var a = below.TryGetValue(EInteger.Zero, out var a0) ? a0 : Number.Integer.Zero;
            var b = below.TryGetValue(EInteger.FromInt32(2), out var b0) ? b0 : Number.Integer.Zero;
            var c = below[EInteger.FromInt32(4)];
            // Zero as a value, and not only as written: the coefficients are read off the
            // denominator as it is written, and `((c - u^2)/c - 1)(u^2 - c)` is `-u^2 (u^2 - c)/c`,
            // with `-(c/c - 1) c` for its constant term. Read as a biquadratic, one of its roots
            // in `u^2` was that zero, and `atan(u/sqrt(0))/sqrt(0)` made the answer NaN.
            // https://github.com/asc-community/AngouriMath/issues/1665
            if (Functions.PartialFractions.IsZeroAsAValue(a) || Functions.PartialFractions.IsZeroAsAValue(c))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above) || above.Count == 0
                || above.Keys.Any(power => power.Sign < 0 || !power.IsEven) || above.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;

            var discriminant = Functions.PartialFractions.Bare((b * b - 4 * a * c).Simplify());
            if (Functions.PartialFractions.IsZeroAsAValue(discriminant))
                return null;

            // The numerator in w = x^2, divided down by c w^2 + b w + a to a remainder d + e w.
            var degree = above.Keys.Max()!.ToInt32Checked() / 2;
            var inW = new Entity[degree + 1];
            for (var k = 0; k <= degree; k++)
                inW[k] = above.TryGetValue(EInteger.FromInt32(2 * k), out var at) ? at : Number.Integer.Zero;
            Entity polynomialPart = Number.Integer.Zero;
            for (var k = degree; k >= 2; k--)
            {
                var lead = Functions.PartialFractions.InLowestTermsOverTheSymbols(inW[k] / c);
                if (lead == Number.Integer.Zero)
                    continue;
                polynomialPart += lead * MathS.Pow(x, 2 * (k - 2));
                inW[k - 1] = Functions.PartialFractions.InLowestTermsOverTheSymbols(inW[k - 1] - lead * b);
                inW[k - 2] = Functions.PartialFractions.InLowestTermsOverTheSymbols(inW[k - 2] - lead * a);
            }
            var d = inW[0];
            var e = degree >= 1 ? inW[1] : Number.Integer.Zero;

            var q = MathS.Sqrt(discriminant);
            var firstRoot = (-b + q) / (2 * c);
            var secondRoot = (-b - q) / (2 * c);
            Entity total = Number.Integer.Zero;
            if (polynomialPart != Number.Integer.Zero)
            {
                if (Integration.ComputeIndefiniteIntegral(polynomialPart, x, integrateByParts) is not { } whole)
                    return null;
                total += whole;
            }
            // `1/(x^2 - r)` is `atan(x/s)/s` with `s = sqrt(-r)` for every complex `r` but zero:
            // `d/dx atan(x/s)/s` is `1/(s^2 + x^2)` whatever `s` is, and for a positive `r` the
            // arctangent of an imaginary argument is the hyperbolic one, `-atanh(x/sqrt(r))/sqrt(r)`,
            // with a constant imaginary part on each side of the poles that a derivative does not
            // see. The roots are conjugate where the discriminant is negative -- the ordinary
            // case with real coefficients -- and the two terms then sum to a real function; a
            // piecewise on the sign of a root, as the quadratic rule would write, has no
            // value there at all.
            foreach (var (root, sign) in new[] { (firstRoot, 1), (secondRoot, -1) })
            {
                var coefficient = ((d + e * root) / q).InnerSimplified;
                if (coefficient == Number.Integer.Zero)
                    continue;
                var s = MathS.Sqrt(-root);
                var part = MathS.Arctan(x / s) / s;
                total += sign == 1 ? coefficient * part : -coefficient * part;
            }
            return total;
        }

        /// <summary>
        /// A product of powers of the variable and of constant multiples of it,
        /// <c>(c x)^m (d x)^k x^n</c> times a constant, with at least one written multiple:
        /// <c>(c x)^m (d x)^k x^(n+1)/(m + k + n + 1)</c>, and the logarithm where the sum of
        /// the exponents is minus one.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The written power is kept as it is, which is what makes this exact: for every
        /// <c>x</c> but zero, <c>d/dx (c x)^m</c> is <c>m (c x)^m / x</c>, since
        /// <c>(c x)^(m-1)</c> is <c>(c x)^m / (c x)</c> whatever the branch, and each factor
        /// contributes its exponent over <c>x</c>. Opening <c>(c x)^m</c> into <c>c^m x^m</c>
        /// would need <c>c</c> or <c>x</c> positive. Rubi's <c>(e x)^m (a + b x^n)^p (c + d x^n)^q</c>
        /// with symbolic <c>m</c> and <c>n</c>, expanded, is a sum of these and was declined
        /// term by term, the power rule reading <c>x^p</c> and nothing else.
        /// </para>
        /// <para>
        /// A power of <c>x</c> alone is left to the power rule, which answers it as before.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAProductOfPowersOfTheVariable(Entity expr, Entity.Variable x)
        {
            Entity constant = Number.Integer.One;
            Entity written = Number.Integer.One;
            Entity plain = Number.Integer.Zero;
            Entity exponents = Number.Integer.Zero;
            var multiples = 0;
            foreach (var factor in Mulf.LinearChildren(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant *= factor;
                    continue;
                }
                if (factor == x)
                {
                    plain += Number.Integer.One;
                    continue;
                }
                if (factor is not Powf(var @base, var power) || power.ContainsNode(x))
                    return null;
                // A whole power of a power is the power of the product of the exponents,
                // exactly: `(x^n)^2` is `x^n x^n`. The expansion of `(a + b x^n)^2` writes it so.
                while (power is Number.Integer && @base is Powf(var inner, var innerPower) && !innerPower.ContainsNode(x))
                {
                    power = (innerPower * power).InnerSimplified;
                    @base = inner;
                }
                if (@base == x)
                {
                    plain += power;
                    continue;
                }
                if (@base is not Mulf(var left, var right)
                    || !(left == x && !right.ContainsNode(x) || right == x && !left.ContainsNode(x)))
                    return null;
                written *= MathS.Pow(@base, power);
                exponents += power;
                multiples++;
            }
            if (multiples == 0)
                return null;
            // Where the exponents sum to minus one the integrand is `K/x` for the constant
            // `K = (c x)^m (d x)^k x^(n+1)`, whose derivative is `K (m + k + n + 1)/x`, zero.
            // Simplified rather than normalised, since the sum is of symbols that cancel:
            // `(c x)^m / x^(m+1)` has `m - (m + 1) + 1`, which the normalisation leaves as
            // written and which would have gone on to divide by itself.
            var raised = Functions.PartialFractions.Bare((plain + 1).Simplify());
            var overAll = Functions.PartialFractions.Bare((exponents + raised).Simplify());
            if (overAll == Number.Integer.Zero || overAll.Evaled is Number.Complex { IsZero: true })
                return constant * written * MathS.Pow(x, raised) * IntegralPatterns.AntiderivativeLog(x);
            return constant * written * MathS.Pow(x, raised) / overAll;
        }

        /// <summary>
        /// <c>x^p</c> for a <paramref name="power"/> that does not hold the variable: the power
        /// rule, or the logarithm where the power rule would divide by zero.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <b>The exponent is normalised before it is read.</b> <c>x^(-3 + 1 + 1)</c> is
        /// <c>x^(-1)</c>, but the sum is not the integer, so comparing the written form against
        /// <c>-1</c> missed the logarithmic case and applied the power rule to it — producing
        /// <c>x^(-3 + 1 + 1 + 1)/(-3 + 1 + 1 + 1)</c>, which is <c>x^0/0</c>, which is
        /// <c>NaN</c>. That is a claim that no antiderivative exists where one plainly does, and
        /// it reached the caller: <c>(a^2 + 2abx^2 + b^2x^4)^3/x^7</c> came back <c>NaN + C</c>
        /// while the same integrand written <c>(a + bx^2)^6/x^7</c> was answered.
        /// https://github.com/asc-community/AngouriMath/issues/1258
        /// </para>
        /// <para>
        /// <b>And normalised again on the way out</b>, which is the other half and the half that
        /// explains where such an exponent comes from. This rule used to return <c>p + 1</c>
        /// standing as a sum, so an answer handed back in as an integrand — which is exactly what
        /// repeated integration by parts does — accumulated one <c>+ 1</c> per round until a
        /// round landed on <c>-1</c> spelled as a sum. The rule was feeding itself the one input
        /// it could not read.
        /// </para>
        /// <para>
        /// A <b>symbolic</b> exponent is left to the power rule as before. <c>int x^n dx</c> is
        /// <c>x^(n+1)/(n+1)</c> for every <c>n</c> but <c>-1</c>, and this does not decide
        /// whether an undecidable <c>n</c> is that one; what it fixes is an exponent that
        /// <em>is</em> decidable and was read as though it were not.
        /// </para>
        /// <para>
        /// Decidable includes a symbol that cancels: <c>x^(-1 - 3n + 3n)</c> is <c>x^(-1)</c> for
        /// every <c>n</c>, and is what expanding <c>x^(-1 - 3n) (a + b x^n)^3</c> leaves for its
        /// last term, but <see cref="Entity.InnerSimplified"/> keeps <c>-3n + 3n</c> as two terms,
        /// so the exponent plus one is asked whether it vanishes as a value. Read as written it
        /// was <c>x^0/0</c> again, and the whole answer had no value anywhere; Rubi's 1.1.3.2
        /// has four such and <c>1/(a (b x^m)^n)^(1/(m n))</c>, which is <c>x^(-m n/(m n))</c>.
        /// </para>
        /// </remarks>
        private static Entity IntegrateAPowerOfTheVariable(Entity @base, Entity power, Entity.Variable x)
        {
            var exponent = power.InnerSimplified;
            if (exponent == -1)
                return IntegralPatterns.AntiderivativeLog(@base);
            var raised = (exponent + 1).InnerSimplified;
            if (raised.Vars.Any() && VanishesIdentically(raised))
                return IntegralPatterns.AntiderivativeLog(@base);
            return MathS.Pow(x, raised) / raised;
        }

        /// <summary>
        /// Whether <paramref name="factor"/> is one of the functions integration by parts
        /// differentiates rather than integrates when the other factor is a polynomial.
        /// </summary>
        /// <remarks>
        /// <para>
        /// This is the <b>L</b> and the <b>I</b> of LIATE, which both come before <b>A</b>. The
        /// rule below implemented only the L, and the reason it gives for the logarithm is the
        /// same one that holds for an inverse trigonometric function: differentiating it turns it
        /// into something algebraic that cancels against the integrated polynomial and ends,
        /// where integrating it puts the original integral back in front of us.
        /// </para>
        /// <para>
        /// <c>x * atan(x)</c> is the case: differentiating <c>atan</c> gives <c>1/(1 + x^2)</c>
        /// and what is left is <c>x^2/(2(1 + x^2))</c>, which is answered; integrating it first
        /// gives an antiderivative holding <c>x*atan(x)</c> again, which is where the search went
        /// instead and why it was left unevaluated.
        /// </para>
        /// <para>
        /// The special functions belong here for the same reason, since each has an elementary
        /// derivative: <c>x Ei(b x)</c> leaves <c>x e^(b x)/2</c> after one step, and
        /// <c>x^2 Si(b x)</c> leaves <c>x^2 sin(b x)/3</c>, where integrating the special function
        /// first gives an antiderivative that holds it again.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static bool IsDifferentiatedBeforeAPolynomial(Entity factor)
            => factor switch
            {
                Logf or Entity.Arcsinf or Entity.Arccosf
                    or Entity.Arctanf or Entity.Arccotanf
                    or Entity.Arcsecantf or Entity.Arccosecantf => true,
                _ when IsASpecialFunction(factor) => true,
                // And a whole power of one, which is the same function for this purpose:
                // differentiating ln(x)^2 gives 2ln(x)/x, whose x cancels against the integrated
                // polynomial exactly as ln(x)'s does, leaving x*ln(x) -- one step simpler, and
                // answered by another round of parts.
                //
                // A positive whole exponent, because that is when differentiating lowers the
                // power by one and the descent is finite. A negative or fractional one is a
                // different integrand with no reason to be the factor differentiated.
                Powf(var repeated, Number.Integer power) when power.EInteger.Sign > 0
                    => IsDifferentiatedBeforeAPolynomial(repeated),
                _ => false
            };

        /// <summary>
        /// Whether <paramref name="factor"/> is a special function of an argument linear in
        /// <paramref name="x"/>, other than the logarithmic integral: differentiated beside a
        /// power of <c>x</c>, it leaves that power times <c>sin(u)</c>, <c>e^u</c> or the like,
        /// which parts against the power answer in as many steps as its degree.
        /// </summary>
        /// <remarks>
        /// Not <c>li</c>: its derivative <c>1/ln(u)</c> leaves <c>x^m/ln(a + b x)</c>, which the
        /// exponential integral's rule answers, and parts there would integrate the reciprocal of
        /// the logarithm back into <c>li</c>.
        /// </remarks>
        private static bool IsASpecialFunctionOfALinear(Entity factor, Variable x)
            => (factor switch
            {
                Entity.Erff(var u) => u,
                Entity.Erfcf(var u) => u,
                Entity.Erfif(var u) => u,
                Entity.Eif(var u) => u,
                Entity.Sif(var u) => u,
                Entity.Cif(var u) => u,
                Entity.Shif(var u) => u,
                Entity.Chif(var u) => u,
                _ => null
            }) is { } argument && TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out _);

        internal static Entity? SolveIntegratingByParts(Entity expr, Entity.Variable x)
        {
            // The measure the nested call below decreases on. Read once, since every step
            // compares against the integrand this call started from rather than against its own
            // immediate predecessor -- what has to shrink is the distance to an answer, and a
            // chain of steps that each shrink by nothing would otherwise be admitted one at a
            // time.
            var wholeSize = expr.Nodes.Count();
            // And the second component of that measure: the highest power of a logarithm or
            // inverse trigonometric factor in the integrand. `x*arctan(x)^2` leaves
            // `x^2*arctan(x)/(1 + x^2)` after one step, which has more nodes and needs one more
            // round of parts to finish, so on node count alone it was declined; on the power it
            // is one step smaller, 2 to 1, and that is the descent the step made. Ordered with
            // the power first: a step that lowers it may grow the expression, and a step that
            // keeps it must shrink the expression, so the pair is well-founded and the runaway
            // the node count was put in for is still stopped by it -- an integrand with no such
            // factor has power zero on both sides and is measured by nodes alone as before.
            // https://github.com/asc-community/AngouriMath/issues/718
            var wholePower = HighestDifferentiatedPower(expr);

            // Standard integration by parts for polynomial × function
            // The antiderivative of u is fixed up to a constant, and the constant is chosen so
            // that what v' divides by divides it: against `arctan(x)^2 ln(1 + x^2)` the
            // antiderivative of `x` is `(1 + x^2)/2` and not `x^2/2`, and the remainder is
            // `arctan(x) ln(1 + x^2) + x arctan(x)^2`, two products each answered by parts, where
            // with `x^2/2` it was two quotients by `1 + x^2` that are elementary only together.
            // Rubi's `x^m` rules do the same. For a polynomial antiderivative and a polynomial
            // divisor, where the division leaves a constant.
            static Entity WithTheConstantMatchedTo(Entity antiderivative, Entity derivativeOfV, Variable x)
            {
                // A logarithm of x, against a logarithm of a multiple of x below the bar: ln(c x) is
                // as much an antiderivative of 1/x as ln(x) is, and taken so, the logarithm the
                // derivative divides by cancels. li(b x)/x is li(b x) ln(b x) - b x, where with ln(x)
                // the remainder was ln(x)/ln(b x), which nothing read.
                // https://github.com/asc-community/AngouriMath/issues/1501
                if (TheLogarithmOfTheVariable(antiderivative, x) is (var logarithmCoefficient, true)
                    && Sumf.LinearChildren(Functions.PartialFractions.Bare(derivativeOfV))
                        .SelectMany(term => Mulf.LinearChildren(Functions.SingleQuotient.Of(term).Denominator))
                        .FirstOrDefault(factor => factor is Logf(var logBase, var argument) && logBase == MathS.e
                            && TreeAnalyzer.TryGetPolyLinear(argument, x, out var multiple, out var offset)
                            && TreeAnalyzer.IsZero(offset) && !TreeAnalyzer.IsZero(multiple)) is { } logarithmBelow)
                    return logarithmCoefficient * logarithmBelow;
                if (!TreeAnalyzer.TryGetPolynomial(antiderivative, x, out _))
                    return antiderivative;
                var divisors = Sumf.LinearChildren(Functions.PartialFractions.Bare(derivativeOfV))
                    .Select(term => Functions.SingleQuotient.Of(term).Denominator)
                    .Where(below => below.ContainsNode(x) && TreeAnalyzer.TryGetPolynomial(below, x, out _))
                    .Distinct().ToList();
                if (divisors.Count != 1)
                    return antiderivative;
                if (TreeAnalyzer.PolynomialLongDivision(antiderivative, divisors[0], genericCase: true, inTermsOf: x) is var (_, leftOver)
                    && Functions.SingleQuotient.Of(leftOver) is var (leftOverTop, _) && !leftOverTop.ContainsNode(x)
                    && leftOverTop.Evaled is Number.Complex { IsZero: false } constant)
                    return (antiderivative + (-constant).Evaled).InnerSimplified;
                // A linear divisor with a symbol in it, `a + b x`, leaves a symbol over, which the
                // case above does not read: the antiderivative less its value at the root, -a/b, is
                // divisible by the linear, and it is written as the linear times the quotient, so
                // that the linear the derivative divides by cancels as written. `x Shi(a + b x)^2`
                // is two rounds of parts that way, where with `x^2/2` the remainder kept
                // `x^2/(a + b x)` and nothing read it.
                // https://github.com/asc-community/AngouriMath/issues/1501
                if (TreeAnalyzer.TryGetPolyLinear(divisors[0], x, out var slope, out var offset) && !TreeAnalyzer.IsZero(slope)
                    && antiderivative.Substitute(x, (-offset / slope).InnerSimplified).InnerSimplified is var atTheRoot
                    && !atTheRoot.ContainsNode(x) && !TreeAnalyzer.IsZero(atTheRoot)
                    && TreeAnalyzer.PolynomialLongDivision((antiderivative - atTheRoot).Expand().InnerSimplified, divisors[0], genericCase: true, inTermsOf: x) is var (quotient, _)
                    && !quotient.ContainsNode(MathS.NaN))
                    return divisors[0] * Functions.PartialFractions.Bare(quotient);
                return antiderivative;
            }

            static Entity? IntegrateByPartsPolynomial(Entity polynomialToDifferentiate, Entity toIntegrate, Variable x, int currentRecursion = 0)
            {
                if (polynomialToDifferentiate == 0) return 0;
                if (currentRecursion == MathS.Settings.MaxExpansionTermCount) return null;

                // A power of the sine times a power of the cosine goes to its closed rule
                // directly, since that rule answers only at the top and this is one level
                // down: `u sin(u)^3/cos(u)^2` is one step of parts against `sin^3/cos^2`, which
                // the rule answers at once and the chain below it spent nine seconds declining
                // through the half-angle substitution.
                var integral = SolveByTrigonometricPowerSubstitution(toIntegrate, x, asked: true)
                    ?? Integration.ComputeIndefiniteIntegral(toIntegrate, x, false);
                if (integral is null) return null;
                var differential = polynomialToDifferentiate.Differentiate(x);
                var result = IntegrateByPartsPolynomial(differential, integral, x, currentRecursion + 1);
                return (result is null) ? null : polynomialToDifferentiate * integral - result;
            }

            // Generalized integration by parts: tries once with v and u both being integrable
            // ∫ v·u dx = v·∫u dx - ∫(v'·∫u dx) dx
            // Only attempts if both v and u can be integrated
            static Entity? TryIntegrateByPartsOnce(Entity v, Entity u, Variable x, int wholeSize, int wholePower)
            {
                // Try to integrate u -- inner-simplified, as the public entry simplifies what
                // the integrator returns: the table answers `x/sqrt(1 + x^2)` as a piecewise on
                // a coefficient's sign whose conditions are decided, `0 = 0`, and a remainder
                // holding that piecewise is read by nothing.
                var integralOfU = Integration.ComputeIndefiniteIntegral(u, x, false)?.InnerSimplified;
                // Beside a special function of a linear argument, a polynomial times something
                // else is integrated by the polynomial's parts, which end in as many steps as its
                // degree: `x sin(b x)` beside `Si(b x)`, which nothing answers with parts off.
                // https://github.com/asc-community/AngouriMath/issues/1501
                var besideASpecialFunction = IsASpecialFunctionOfALinearOrAPowerOfOne(v, x);
                var byThePolynomialsParts = false;
                if (integralOfU is null && besideASpecialFunction
                    && ThePolynomialFactor(u, x) is var (polynomialBeside, restBeside)
                    && polynomialBeside is not null && restBeside is not null)
                {
                    integralOfU = IntegrateByPartsPolynomial(polynomialBeside, restBeside, x)?.InnerSimplified;
                    byThePolynomialsParts = integralOfU is not null;
                }
                if (integralOfU is null) return null;

                // Differentiate v
                var derivativeOfV = v.Differentiate(x).InnerSimplified;
                if (derivativeOfV is Providedf(var inner, _)) derivativeOfV = inner; // TODO: signularities ignored but not handled properly
                if (derivativeOfV == Integer.Zero)
                    return v * integralOfU; // If v is constant, we're done
                // The antiderivative of u is fixed up to a constant, and the constant is
                // chosen so that what v' divides by divides it: against `arctan(x)^2 ln(1 + x^2)`
                // the antiderivative of `x` is `(1 + x^2)/2` and not `x^2/2`, and the remainder is
                // `arctan(x) ln(1 + x^2) + x arctan(x)^2`, two products each answered by parts,
                // where with `x^2/2` it was two quotients by `1 + x^2` that are elementary only
                // together. Rubi's `x^m` rules do the same.
                integralOfU = WithTheConstantMatchedTo(integralOfU, derivativeOfV, x);

                // Try to integrate the remaining term: v' · ∫u dx
                var remaining = (derivativeOfV * integralOfU).Simplify(1);
                if (remaining is Providedf(var inner_, _)) remaining = inner_; // TODO: signularities ignored but not handled properly
                // **By parts is allowed on what is left**, and that is the whole of this change.
                // One step of parts often leaves an integral that needs another: `x * ln(x)^2`
                // leaves `x * ln(x)`, which is answered by parts and by nothing else, so with
                // parts switched off here the outer integral was declined for want of the inner
                // one. Every power of a logarithm times a polynomial was out of reach that way.
                //
                // It was switched off because this recursion used to run away -- `x * ln(x)`
                // went round until the stack ran out. What stopped that was choosing the right
                // factor to differentiate (the L-before-A of LIATE, above), and since then the
                // integrator has grown two bounds that hold whatever the rules do: a set of
                // integrands already on the stack, which declines a repeat immediately, and a
                // ceiling on the depth of the descent. Those are what makes this safe now, and
                // they are checked on every entry rather than trusted to a flag.
                // https://github.com/asc-community/AngouriMath/issues/718
                // ...but only where what is left is **strictly smaller** than what we started
                // with. That is the decrease that makes the descent finite, and it is also what
                // keeps the search from widening: `sin(x)/(x^2 + 1)^2` has no elementary
                // antiderivative, so every solver runs to exhaustion on it, and letting parts
                // recurse without a measure took it from about a second to 83 -- caught by
                // `AnIntegralWithNoAnswerStillFinishesQuickly`, which exists for exactly this.
                // A power of a logarithm does decrease: `x * ln(x)^2` leaves `x * ln(x)`.
                // The power admits a larger remainder only while a factor is left for the next
                // round to differentiate. Once it has fallen to zero the remainder is whatever
                // the derivative and the integral made together -- for `asec(x)^2` times a
                // radical, a hundred-node radical expression -- and a by-parts search on that
                // is the runaway the node bound exists for: measured at thirty seconds for a
                // decline, where the node bound alone declined it in one.
                var remainingPower = HighestDifferentiatedPower(remaining);
                // And after a special function of a linear argument, whose derivative leaves the
                // power of x beside sin(u), e^u and the like: `x Si(b x)` leaves `x sin(b x)/2`,
                // which parts against the power answer in as many steps as its degree. It has
                // more nodes than `x Si(b x)` and no factor left to differentiate, so the measure
                // alone declined it, and with it every power of x beside Si or Ci.
                //
                // Only against a polynomial, which is what makes the next steps a descent on its
                // degree. Allowed against anything, it took erf(b x)^2, whose second step is
                // against x e^(-b^2 x^2), from a decline in a third of a second to a timeout.
                // https://github.com/asc-community/AngouriMath/issues/1501
                var partsOnTheRemainder = remaining.Nodes.Count() < wholeSize
                    || (remainingPower >= 1 && remainingPower < wholePower)
                    || IsASpecialFunctionOfALinear(v, x) && ThePolynomialIn(u, x) is not null
                    // And where what was integrated beside it was a polynomial times an
                    // elementary function, whose integral the polynomial's parts wrote: the
                    // remainder is then the special function's derivative times polynomials and
                    // elementary functions, and parts on it descend on their degrees.
                    || byThePolynomialsParts;
                // Spelled as the product its own next step reads, where there is one. `Simplify`
                // writes `2 arctan(x)/(1 + x^2) * x^2/2` as `arctan(x) x^2/(x^2 + 1)`, a
                // quotient, and this rule runs on a product. `x*arctan(x)^2` is answered by
                // exactly this and by nothing else.
                //
                // Only where what is left beside the factor is **rational** in the variable,
                // which is where the next round is a division and a table lookup. With a
                // radical there instead -- `asec(x)^2` times `(x^2 - 1)^(3/2)/x^5` -- the
                // re-spelled remainder handed a by-parts search a hundred-node radical
                // expression at every level below, and a one-second decline became thirty.
                if (partsOnTheRemainder
                    && TryRegroupAroundTheDifferentiatedFactor(remaining) is var (next, rest)
                    && next is not null && rest is not null
                    && IsRationalIn(rest, x))
                    remaining = next * rest;
                // A remainder that is a rational function of x and one root of a quadratic goes
                // to Euler's substitution directly, before the chain: `ln(x^2 + sqrt(1 - x^2))`
                // against 1 leaves exactly that, and the chain spent five seconds of
                // substitutions and reductions on it before Euler answered it in half of one.
                // From the top only: a nested step's remainder answered this way let a doomed
                // search above it carry on, thirty seconds where the gate leaves it at one.
                var remainingIntegral = (Integration.AnsweringTheQuestionAsked ? SolveByEulerSubstitution(remaining, x) : null)
                    ?? Integration.ComputeIndefiniteIntegral(remaining, x, partsOnTheRemainder);
                // After a special function, or a power of one, the remainder is its derivative
                // times what was integrated, written as one product over a sum: for `Ei(b x)^2`,
                // `(b x Ei(b x) - e^(b x)) e^(b x)/(b x)`, which no rule reads, where its two
                // terms are `e^(b x) Ei(b x)` and `e^(2 b x)/(b x)`, each answered when asked.
                // So its terms are asked, each as a question of its own. From the top only,
                // which is where that asking reaches, and once: a term asked so is at the top
                // itself, and its own remainder asked the same way would lift the search again,
                // each level with the depth reset. And not for every argument: see
                // TheRemainderIsAskedTermByTerm.
                // https://github.com/asc-community/AngouriMath/issues/1501
                if (remainingIntegral is null && besideASpecialFunction && TheRemainderIsAskedTermByTerm(v, u, x)
                    && Integration.AnsweringTheQuestionAsked && !askingTheTermsOfARemainder)
                {
                    var terms = remaining is Divf(var remainingAbove, var remainingBelow)
                        ? DistributedOverTheSum(remainingAbove).Select(term => term / remainingBelow).ToList()
                        : DistributedOverTheSum(remaining);
                    askingTheTermsOfARemainder = true;
                    try
                    {
                        foreach (var term in terms)
                        {
                            if ((Integration.ComputeIndefiniteIntegral(term, x, integrateByParts: true)
                                    ?? Integration.ComputeAsAQuestionOfItsOwn(term, x, integrateByParts: true)) is not { } termIntegral)
                            {
                                remainingIntegral = null;
                                break;
                            }
                            remainingIntegral = remainingIntegral is null ? termIntegral : remainingIntegral + termIntegral;
                        }
                    }
                    finally
                    {
                        askingTheTermsOfARemainder = false;
                    }
                }
                else if (remainingIntegral is null && besideASpecialFunction && TheRemainderIsAskedTermByTerm(v, u, x)
                    && Integration.AnsweringTheQuestionAsked)
                    Integration.DeclinedForItsScope();
                if (remainingIntegral is null) return null;

                return v * integralOfU - remainingIntegral;
            }

            Entity? TrySplit(Entity f, Entity g)
            {
                // Case 0: a logarithm times a polynomial. Only one of the two orders
                // terminates. Differentiating the polynomial, which is what Case 1 does,
                // leaves the logarithm to be integrated, and the antiderivative of ln(x)
                // holds an x*ln(x) that puts the original integral back in front of us --
                // that is how integral(x * ln(x), x) recursed until the stack ran out.
                // Differentiating the logarithm instead turns it into 1/x, which cancels
                // against the integrated polynomial and ends. (The L-before-A of LIATE.)
                if (IsDifferentiatedBeforeAPolynomial(f) && MathS.TryPolynomial(g, x, out _)
                    && TryIntegrateByPartsOnce(f, g, x, wholeSize, wholePower) is { } logFirstF) return logFirstF;
                if (IsDifferentiatedBeforeAPolynomial(g) && MathS.TryPolynomial(f, x, out _)
                    && TryIntegrateByPartsOnce(g, f, x, wholeSize, wholePower) is { } logFirstG) return logFirstG;

                // Case 1: One term is polynomial - use recursive polynomial integration by parts
                if (ThePolynomialIn(f, x) is { } fPoly) return IntegrateByPartsPolynomial(fPoly, g, x);
                if (ThePolynomialIn(g, x) is { } gPoly) return IntegrateByPartsPolynomial(gPoly, f, x);

                // Case 2: Neither is polynomial - try single-step integration by parts
                // This handles cases like ln(abs(x)) × ln(abs(x))
                // Try both orderings: f as v, g as u OR g as v, f as u
                //
                // **Only with a factor worth differentiating** -- a logarithm or an inverse
                // function, whose derivative is algebraic, or an exponential, whose integral
                // is itself and which the cyclic cases need. With neither, the step trades one
                // product of transcendental factors for another of the same kind with a
                // derivative in it, and searching that is where a decline went to spend thirty
                // seconds: `-3 tan(x)/(4 sec(x)^2 + 5 tan(x)^2)` against `1/sin(x)^2`, both
                // integrable, neither the right thing to differentiate. Measured on the Rubi
                // sample with the restriction and without: the same answers, eight seconds less.
                bool IsAnExponential(Entity factor)
                    => factor is Powf(var @base, var power) && !@base.ContainsNode(x) && power.ContainsNode(x);
                if (!IsDifferentiatedBeforeAPolynomial(f) && !IsDifferentiatedBeforeAPolynomial(g)
                    && !IsAnExponential(f) && !IsAnExponential(g))
                    return null;
                if (TryIntegrateByPartsOnce(f, g, x, wholeSize, wholePower) is { } result1) return result1;
                if (TryIntegrateByPartsOnce(g, f, x, wholeSize, wholePower) is { } result2) return result2;
                return null;
            }

            if (expr is Entity.Mulf(var f, var g))
            {
                if (TrySplit(f, g) is { } atTheTop) return atTheTop;

                // **And the same again with the factors regrouped.** The split above is the top
                // `Mulf` node's two children, which is a fact about how the product was written
                // rather than about the integrand: `x * cos(x) * sin(x)` parses left-associated,
                // so the two children are `x * cos(x)` and `sin(x)` -- neither a polynomial, and
                // none of the three cases above finds anything. `x * (cos(x) * sin(x))` is the
                // same function with the same factors, and it came out, because there the
                // polynomial is a child.
                //
                // So the factors are gathered and cut once more, polynomial on one side and the
                // rest on the other, which is the split every one of these cases is looking for
                // and the only one associativity can hide. Tried second, so an integrand that
                // was answered before is answered the same way.
                // https://github.com/asc-community/AngouriMath/issues/718
                if (TryRegroupAroundThePolynomial(expr, x) is var (polynomialPart, restPart)
                    && polynomialPart is not null && restPart is not null
                    && TrySplit(polynomialPart, restPart) is { } regrouped)
                    return regrouped;
            }

            // **A polynomial over something else is the polynomial times its reciprocal**, and
            // Case 1 reads a product: `x/cos(x)^2` reached nothing where `x*sec(x)^2` is one
            // step of parts, and it is what `arcsin(x)/sqrt(1 - x^2)^3` becomes under
            // `x = sin(u)`. Asked, not volunteered, like the regrouping below and for the same
            // reason: the reciprocal opens a search of its own.
            // Not over an algebraic function: a polynomial over a radical or over another
            // polynomial is the rational integrator's or Euler's, both of which have already
            // declined it by the time this runs, and a step of parts against it opens their
            // search again a level down -- one second more, measured, on a decline.
            if (Integration.AnsweringTheQuestionAsked
                && expr is Divf(var above, var below) && below.ContainsNode(x) && !IsAlgebraicIn(below, x)
                && TryRegroupAroundThePolynomialOverTheBar(above, below, x) is var (polynomialAbove, restOfTheQuotient)
                && polynomialAbove is not null && restOfTheQuotient is not null
                && TrySplit(polynomialAbove, restOfTheQuotient) is { } overTheBar)
                return overTheBar;

            // **And once more around the factor LIATE differentiates first, wherever it sits.**
            // The block above only runs on a product, so `arcsin(x)/(x^2*sqrt(1 - x^2))` never
            // reached this rule at all -- its top node is a quotient. Written as the product it
            // is, `arcsin(x) * (1/(x^2*sqrt(1 - x^2)))`, the same integrand came out. A quotient
            // is a product with reciprocals in it, and reading it as one is the whole of this.
            //
            // The cut is the logarithm or inverse trigonometric factor against everything else,
            // because that is the factor whose derivative is algebraic and cancels; taking it
            // out of the middle of a product is the same defect as taking the polynomial out,
            // with a different factor doing the work. `x*arcsin(x)/sqrt(1 - x^2)` needs both
            // moves at once: read as a product, and cut at the arcsine rather than at the top.
            //
            // **Two bounds, and both were measured rather than added for safety.** Without them
            // this is worth six more answers on the Rubi sample and forty per cent of its wall
            // clock, which is what https://github.com/asc-community/AngouriMath/issues/1265 is
            // about. With them it is worth the same six answers and three per cent.
            //
            // The first is scope: asked, not volunteered. The split is offered only for the
            // caller's own integrand, never for one another rule produced on the way somewhere.
            // A by-parts step produces quotients holding logarithms by the dozen, and each of
            // those opening a fresh by-parts attempt is where the time went --
            // `cos(x)^3*ln(sin(x))` is answered in 1.7 s by master and took 45 s without this,
            // although the rule never fires on it at the top at all.
            //
            // The second is in the regrouping: exactly one factor to differentiate, never two.
            // ...and up to two below the question asked where everything beside the
            // differentiated factor is algebraic in x with a root in it: the second step of
            // parts on `x^3 asech(a x)^2` is `x^2 asech(a x)/sqrt(1/(a x)^2 - 1)`, whose other
            // factor integrates to an algebraic expression or declines at once, and whose
            // remainder is algebraic -- none of the logarithms by the dozen the scope above
            // is there to stop. With a root only: beside a rational function the rule for a
            // rational function times a logarithm is the one that answers, and offering
            // parts there sent `(a + b atanh(c x^2))^2/x^5` into a search that did not return.
            if ((Integration.AnsweringTheQuestionAsked
                    || Integration.AnsweringTheQuestionAskedOrTwoBelow && TryRegroupAroundTheDifferentiatedFactor(expr) is var (_, algebraicOthers) && algebraicOthers is not null && IsAlgebraicIn(algebraicOthers, x) && HasARadicalOf(algebraicOthers, x))
                && TryRegroupAroundTheDifferentiatedFactor(expr) is var (differentiated, others)
                && differentiated is not null && others is not null
                && TrySplit(differentiated, others) is { } byLiate)
                return byLiate;

            // **Two factors to differentiate, taken together**, against an algebraic rest whose
            // integral is closed: `x arctan(x) ln(x + sqrt(1 + x^2))/sqrt(1 + x^2)` is the product
            // of the two transcendental factors against `x/sqrt(1 + x^2)`, whose integral is
            // `sqrt(1 + x^2)`, and the remainder `sqrt(1 + x^2) (f g)'` is `arctan(x)` plus
            // `ln(x + sqrt(1 + x^2))/sqrt(1 + x^2)`, each with one such factor and each answered.
            // The regrouping above refuses two for the reason in its remark -- choosing one
            // to differentiate is a guess, and the remainder still holds the other -- which
            // taking both together does not have: the product's derivative has one factor
            // per term. Only against an algebraic rest, which is where the integral of the
            // rest is closed and the remainder is smaller than what it came from.
            // The remainder's terms are asked at the top, each being a term of a sum asked at
            // the top and each holding one transcendental factor where the integrand held two:
            // `arctan(x)` alone is by parts against one, which answers only at the top.
            if (Integration.AnsweringTheQuestionAsked
                && TryRegroupAroundBothDifferentiatedFactors(expr) is var (bothOfThem, algebraicRest)
                && bothOfThem is not null && algebraicRest is not null
                && IsAlgebraicIn(algebraicRest, x)
                && Integration.ComputeIndefiniteIntegral(algebraicRest, x, false)?.InnerSimplified is { } integralOfTheRest)
            {
                // The derivative as differentiation writes it: simplified first, `1 + x^2` is
                // `x^2 + 1`, a spelling the substitution for `ln(x + sqrt(1 + x^2))` then did not
                // read against the `sqrt(1 + x^2)` beside it.
                var derivativeOfBoth = bothOfThem.Differentiate(x);
                integralOfTheRest = WithTheConstantMatchedTo(integralOfTheRest, derivativeOfBoth, x);
                var remaining = (derivativeOfBoth * integralOfTheRest).Simplify(1);
                if (remaining is Providedf(var bareRemaining, _))
                    remaining = bareRemaining;
                // Distributed over the sum the product rule left -- the derivative of the pair
                // is a sum and the integral of the rest multiplies it -- and no further: written
                // out in full, `arctan(x) (1 + x/sqrt(x^2 + 1))` comes apart into two terms
                // neither of which is elementary, where together they are `arctan(x)`.
                var terms = DistributedOverTheSum(remaining);
                Entity? total = null;
                foreach (var written in terms)
                {
                    // With the radicals differentiation left beside each other combined and
                    // cancelled first -- `(sqrt(x^2 + 1) + x)/(x + sqrt(x^2 + 1))` is one, and a
                    // term carrying it was thirty seconds of search where `arctan(x)` alone is
                    // a step of parts.
                    var term = CombineRadicalsIn(written, x);
                    if (Integration.ComputeAsAQuestionOfItsOwn(term, x, integrateByParts: true) is not { } termIntegral)
                    {
                        total = null;
                        break;
                    }
                    total = total is null ? termIntegral : total + termIntegral;
                }
                if (total is not null)
                    return bothOfThem * integralOfTheRest - total;
            }

            // **A bare logarithm or inverse function of something that is not linear**, by
            // parts against 1: `int f(g) dx = x f(g) - int x g' f'(g) dx`, and the remainder is
            // algebraic. A linear argument is the table's; anything else reached no rule at all,
            // since this one runs on a product and the integrand is a single node.
            // `arctan(x sqrt(1 - x^2))` had no antiderivative and is one step of this.
            // Asked, not volunteered, like the regrouping above: the remainder can be a radical
            // the search spends seconds on, and a rule that produced this shape on its way
            // somewhere is not owed that search.
            // And with two such factors, one of them differentiated and the other integrated
            // beside the rest, either way round: `x ln(1 + x^2) arctan(x)` is not elementary
            // by the two together -- the remainder holds `ln(1 + x^2)/(1 + x^2)`, which is not
            // -- and is by parts against `x ln(1 + x^2)`, whose integral is a substitution,
            // with the arctangent differentiated: the remainder is then rational and a
            // logarithm over a quadratic. Measured on the total power, which the step lowers.
            if (Integration.AnsweringTheQuestionAsked
                && TryRegroupAroundBothDifferentiatedFactors(expr) is var (twoOfThem, restBesideThem)
                && twoOfThem is not null && restBesideThem is not null)
                foreach (var differentiatedOne in Mulf.LinearChildren(twoOfThem))
                {
                    var integratedOne = Mulf.LinearChildren(twoOfThem).First(factor => factor != differentiatedOne);
                    var integrated = restBesideThem == Integer.One ? integratedOne : integratedOne * restBesideThem;
                    if (TryIntegrateByPartsOnce(differentiatedOne, integrated, x, wholeSize, wholePower) is { } oneOfTheTwo)
                        return oneOfTheTwo;
                }

            if (Integration.AnsweringTheQuestionAsked && IsDifferentiatedBeforeAPolynomial(expr)
                && expr is not Powf
                && !(expr.DirectChildren.LastOrDefault() is { } argument && TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out _))
                && TryIntegrateByPartsOnce(expr, Integer.One, x, wholeSize, wholePower) is { } againstOne)
                return againstOne;

            // Special case for powers of integrable functions, try integration by parts on base × base
            // e.g., ln(abs(x))^2 = ln(abs(x)) × ln(abs(x))
            if (expr is Powf(var @base, Integer(2)) && TryIntegrateByPartsOnce(@base, @base, x, wholeSize, wholePower) is { } result) return result;

            return null;
        }

        /// <summary>
        /// Whether <paramref name="expr"/> is built from <paramref name="x"/> by the four
        /// operations and rational powers alone: no function of <paramref name="x"/> anywhere.
        /// </summary>
        private static bool IsAlgebraicIn(Entity expr, Entity.Variable x)
            => expr.Nodes.All(node =>
                !node.ContainsNode(x)
                || node is Variable or Sumf or Minusf or Mulf or Divf
                || node is Powf(_, var power) && power is Number.Rational);

        /// <summary>
        /// Whether <paramref name="expr"/> is a quotient of polynomials in <paramref name="x"/>,
        /// read in either spelling a quotient has here.
        /// </summary>
        private static bool IsRationalIn(Entity expr, Entity.Variable x)
        {
            if (!TryReadAsQuotient(expr, out var above, out var below))
                return TreeAnalyzer.TryGetPolynomial(expr, x, out _);
            return TreeAnalyzer.TryGetPolynomial(above, x, out _) && TreeAnalyzer.TryGetPolynomial(below, x, out _);
        }

        /// <summary>
        /// The total power of the factors <see cref="IsDifferentiatedBeforeAPolynomial"/>
        /// recognises among the factors of <paramref name="expr"/> -- of each term of it, the
        /// largest, where it is a sum or a sum over a denominator -- or zero where there is
        /// none: the first component of the measure integration by parts descends on.
        /// </summary>
        /// <remarks>
        /// The total and not the highest: <c>arctan(x) ln(1 + x^2)</c> is two, and one step of
        /// parts leaves <c>2x^2 arctan(x)/(1 + x^2) - x ln(1 + x^2)/(1 + x^2)</c>, each term of
        /// which is one -- the step differentiated one of the two away, and that is the
        /// descent it made, where the highest power read one on both sides and declined the
        /// larger remainder. A step that lowers the total may grow the expression, and a
        /// step that keeps it must shrink the expression, as before.
        /// </remarks>
        private static int HighestDifferentiatedPower(Entity expr)
        {
            var (numerator, denominator) = expr is Divf(var top, var bottom) ? (top, bottom) : (expr, Number.Integer.One as Entity);
            var highest = 0;
            foreach (var term in Sumf.LinearChildren(numerator))
            {
                var total = 0;
                foreach (var (factor, underneath) in FactorsOfTheIntegrand(denominator == Number.Integer.One ? term : term / denominator))
                {
                    if (underneath || !IsDifferentiatedBeforeAPolynomial(factor))
                        continue;
                    total += factor is Powf(_, Number.Integer exponent) && exponent.EInteger.CanFitInInt32()
                        ? exponent.EInteger.ToInt32Unchecked()
                        : 1;
                }
                if (total > highest)
                    highest = total;
            }
            return highest;
        }

        /// <summary>
        /// The factors of <paramref name="expr"/> read as a product — a quotient contributing its
        /// denominator's factors as reciprocals — cut into the one
        /// <see cref="IsDifferentiatedBeforeAPolynomial"/> recognises and everything else.
        /// </summary>
        /// <remarks>
        /// Both halves <see langword="null"/> when there is no such factor, or when it is the
        /// whole integrand and there is nothing to put on the other side. One factor is taken,
        /// not all of them: it is the one that gets differentiated, and differentiating a product
        /// of two logarithms is not a step towards anything.
        /// </remarks>
        private static (Entity? Differentiated, Entity? Others) TryRegroupAroundTheDifferentiatedFactor(Entity expr)
        {
            var factors = FactorsOfTheIntegrand(expr);
            if (factors.Count < 2)
                return (null, null);

            // Exactly one, and that is a bound rather than a tidiness. With two logarithms or
            // inverse trigonometric factors there is no reason to differentiate one rather than
            // the other, so the choice is a guess -- and what is left still holds the other one,
            // so the step has not made the problem smaller. Measured on
            // `x*arctan(x)*ln(x + sqrt(1 + x^2))/sqrt(1 + x^2)`: declined in 66 ms without this
            // rule and in 39 s with it choosing one of the two.
            if (factors.Count(pair => !pair.Underneath && IsDifferentiatedBeforeAPolynomial(pair.Factor)) != 1)
                return (null, null);

            Entity? differentiated = null;
            Entity? above = null;
            Entity? below = null;
            foreach (var (factor, underneath) in factors)
                if (differentiated is null && !underneath && IsDifferentiatedBeforeAPolynomial(factor))
                    differentiated = factor;
                else if (underneath)
                    below = below is null ? factor : below * factor;
                else
                    above = above is null ? factor : above * factor;

            if (differentiated is null || (above is null && below is null))
                return (null, null);
            // **Put the rest back together as one quotient**, numerator over denominator, rather
            // than as a product of reciprocals. Which of the two it is decides whether the rules
            // below read it: `1/(x^2*sqrt(1 - x^2))` is answered and
            // `(1/x^2) * (1/sqrt(1 - x^2))` is not, and handing on the second shape means this
            // rule reproduces, inside itself, exactly the spelling defect it exists to remove.
            var others = below is null ? above! : above is null ? 1 / below : above / below;
            return (differentiated, others);
        }

        /// <summary>
        /// <paramref name="expr"/> as the terms of its top-level sum, with a product of a sum
        /// and other factors distributed one level: <c>(a + b) c</c> is <c>a c</c> and <c>b c</c>,
        /// and <c>a</c> is left as written.
        /// </summary>
        private static List<Entity> DistributedOverTheSum(Entity expr)
        {
            if (expr is Sumf or Minusf)
                return Sumf.LinearChildren(expr).ToList();
            var factors = Mulf.LinearChildren(expr).ToList();
            var sum = factors.FirstOrDefault(factor => factor is Sumf or Minusf);
            if (sum is null)
                return new List<Entity> { expr };
            Entity rest = Number.Integer.One;
            foreach (var factor in factors)
                if (!ReferenceEquals(factor, sum))
                    rest = rest * factor;
            return Sumf.LinearChildren(sum).Select(term => term * rest).ToList();
        }

        /// <summary>
        /// The two factors LIATE would differentiate, as one product, against the rest of the
        /// integrand as one quotient -- <c>1</c> where there is nothing beside them, since
        /// <c>arctan(x) ln(1 + x^2)</c> against <c>1</c> is one step of parts whose remainder,
        /// <c>x ln(1 + x^2)/(1 + x^2) + 2x^2 arctan(x)/(1 + x^2)</c>, is two terms each of which
        /// is answered on its own; <c>(null, null)</c> where there are not exactly two above
        /// the bar.
        /// </summary>
        private static (Entity? Both, Entity? Others) TryRegroupAroundBothDifferentiatedFactors(Entity expr)
        {
            var factors = FactorsOfTheIntegrand(expr);
            if (factors.Count < 2)
                return (null, null);
            if (factors.Count(pair => !pair.Underneath && IsDifferentiatedBeforeAPolynomial(pair.Factor)) != 2)
                return (null, null);
            Entity? both = null;
            Entity? above = null;
            Entity? below = null;
            foreach (var (factor, underneath) in factors)
                if (!underneath && IsDifferentiatedBeforeAPolynomial(factor))
                    both = both is null ? factor : both * factor;
                else if (underneath)
                    below = below is null ? factor : below * factor;
                else
                    above = above is null ? factor : above * factor;
            if (both is null)
                return (null, null);
            if (above is null && below is null)
                return (both, Integer.One);
            var others = below is null ? above! : above is null ? 1 / below : above / below;
            return (both, others);
        }

        /// <summary>
        /// <paramref name="expr"/> read as a product of factors, each paired with whether it sits
        /// under a division bar.
        /// </summary>
        /// <remarks>
        /// <c>a/(b*c)</c> comes back as <c>a</c> above and <c>b</c>, <c>c</c> below — which is
        /// what lets a rule that reasons about factors see through a quotient, where
        /// <see cref="Mulf.LinearChildren"/> stops at it. The flag is kept rather than folded
        /// into a reciprocal so that the caller can rebuild one quotient instead of a product of
        /// them.
        /// </remarks>
        private static List<(Entity Factor, bool Underneath)> FactorsOfTheIntegrand(Entity expr)
        {
            var factors = new List<(Entity, bool)>();
            Gather(expr, underneath: false);
            return factors;

            void Gather(Entity node, bool underneath)
            {
                switch (node)
                {
                    case Mulf(var left, var right):
                        Gather(left, underneath);
                        Gather(right, underneath);
                        break;
                    case Divf(var numerator, var denominator):
                        Gather(numerator, underneath);
                        Gather(denominator, !underneath);
                        break;
                    default:
                        factors.Add((node, underneath));
                        break;
                }
            }
        }

        /// <summary>
        /// The factors of <paramref name="expr"/> cut into the polynomial ones and the rest,
        /// where that cut is not the one the top <c>Mulf</c> node already makes.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Both halves <see langword="null"/> when there is nothing new to offer: fewer than three
        /// factors, or all of them polynomial, or none of them. In those cases the top node's own
        /// split is either the same cut or the only one there is.
        /// </para>
        /// <para>
        /// A factor free of the variable counts as polynomial, since it is a constant here and
        /// belongs with the part that gets differentiated — where it survives one step and
        /// vanishes from the recursion, rather than riding along inside an integrand.
        /// </para>
        /// </remarks>
        private static (Entity? Polynomial, Entity? Remainder) TryRegroupAroundThePolynomial(Entity expr, Entity.Variable x)
        {
            var factors = Mulf.LinearChildren(expr).ToList();
            if (factors.Count < 3)
                return (null, null);

            Entity? polynomial = null;
            Entity? rest = null;
            foreach (var factor in factors)
                if (MathS.TryPolynomial(factor, x, out _) || !factor.ContainsNode(x))
                    polynomial = polynomial is null ? factor : polynomial * factor;
                else
                    rest = rest is null ? factor : rest * factor;
            return polynomial is null || rest is null ? (null, null) : (polynomial, rest);
        }

        /// <summary>
        /// The polynomial factors of a quotient's numerator against the rest of the quotient:
        /// <c>u sec(u)^2/tan(u)^2</c> is <c>u</c> and <c>sec(u)^2/tan(u)^2</c>. The polynomial
        /// has to be in <paramref name="x"/>, or there is nothing to differentiate.
        /// </summary>
        private static (Entity? Polynomial, Entity? Remainder) TryRegroupAroundThePolynomialOverTheBar(
            Entity above, Entity below, Entity.Variable x)
        {
            Entity? polynomial = null;
            Entity? rest = null;
            foreach (var factor in Mulf.LinearChildren(above))
                if (MathS.TryPolynomial(factor, x, out _) || !factor.ContainsNode(x))
                    polynomial = polynomial is null ? factor : polynomial * factor;
                else
                    rest = rest is null ? factor : rest * factor;
            if (polynomial is null || !polynomial.ContainsNode(x))
                return (null, null);
            return (polynomial, rest is null ? Integer.One / below : rest / below);
        }

        internal static Entity? SolveLogarithmic(Entity expr, Entity.Variable x, bool integrateByParts = true) => expr switch
        {
            Entity.Logf(var @base, var arg) =>
                @base.ContainsNode(x) ?
                    Integration.ComputeIndefiniteIntegral(MathS.Ln(arg) / MathS.Ln(@base), x, integrateByParts) :
                arg is Entity.Powf(var y, var pow) ? // log(b, y^p) = ln(y^p) / ln(b) = ln(p) / ln(b) * ln(y)
                    Integration.ComputeIndefiniteIntegral(pow / MathS.Ln(@base) * MathS.Ln(y), x, integrateByParts) :
                    SolveALogarithmOrAnArctangentOfAPolynomial(expr, x),

            Entity.Arctanf or Entity.Arccotanf => SolveALogarithmOrAnArctangentOfAPolynomial(expr, x),

            _ => null
        };

        /// <summary>
        /// The logarithm, arctangent or arccotangent of a polynomial in <paramref name="x"/>,
        /// by parts against one, closed: <c>x f(P) - int x f'(P) P'</c>, whose remainder is a
        /// rational function -- <c>x P'/P</c>, <c>x P'/(1 + P^2)</c> -- and goes to the rational
        /// integrator directly.
        /// </summary>
        /// <remarks>
        /// By parts against one is a rule of the top: a nested step's remainder answered that
        /// way let a doomed search above it carry on. So <c>ln(1 + x^2)</c> one level down had no
        /// antiderivative, and every remainder that held it -- what parts leaves from
        /// <c>arctan(x) ln(1 + x^2)</c> with the arctangent differentiated, for one -- was
        /// declined for want of it. This is the same step for the one shape whose remainder is
        /// closed, and it is closed itself, so it is answered at any depth.
        /// </remarks>
        private static Entity? SolveALogarithmOrAnArctangentOfAPolynomial(Entity expr, Entity.Variable x)
        {
            Entity argument;
            Entity derivativeOfTheFunction;
            switch (expr)
            {
                case Logf(var @base, var arg) when @base == MathS.e:
                    argument = arg;
                    derivativeOfTheFunction = 1 / arg;
                    break;
                case Arctanf(var arg):
                    argument = arg;
                    derivativeOfTheFunction = 1 / (1 + MathS.Sqr(arg));
                    break;
                case Arccotanf(var arg):
                    argument = arg;
                    derivativeOfTheFunction = -1 / (1 + MathS.Sqr(arg));
                    break;
                default:
                    return null;
            }
            // A linear argument is the table's, and answered more shortly there.
            if (!argument.ContainsNode(x) || !TreeAnalyzer.TryGetPolynomial(argument, x, out var read)
                || TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out _) || read.Keys.Any(k => !k.CanFitInInt32()))
                return null;
            var remainder = Functions.PartialFractions.Bare(x * argument.Differentiate(x) * derivativeOfTheFunction);
            if (!TryReadAsQuotient(remainder, out var above, out var below)
                || !TreeAnalyzer.TryGetPolynomial(above, x, out _) || !TreeAnalyzer.TryGetPolynomial(below, x, out _))
                return null;
            var rational = above / below;
            var integratedRemainder = SolveByPartialFractions(rational, x, integrateByParts: false)
                ?? IntegralPatterns.TryStandardIntegrals(rational, x)
                ?? SolveByRothsteinTrager(rational, x);
            if (integratedRemainder is null)
                return null;
            var answer = (x * expr - integratedRemainder).InnerSimplified;
            return answer.Nodes.Any(node => node is Number.Complex { IsNaN: true }) ? null : answer;
        }

        internal static Entity? SolveExponential(Entity expr, Entity.Variable x, bool integrateByParts = true) => expr switch
        {
            Entity.Powf(var @base, var pow) =>
                @base.ContainsNode(x) ?
                    Integration.ComputeIndefiniteIntegral(MathS.Pow(MathS.e, MathS.Ln(@base) * pow), x, integrateByParts) :
                    null,

            _ => null
        };

        /// <summary>
        /// <c>(a + b sin(c x + d))^n</c> or the same with a cosine, for <c>a^2 = b^2</c> and
        /// <c>n</c> a positive half-integer, in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sqrt(1 + sin(x))</c> had no antiderivative. It is <c>-2 cos(x)/sqrt(1 + sin(x))</c>:
        /// differentiating that gives <c>(2 sin (1 + sin) + cos^2)/(1 + sin)^(3/2)</c>, and with
        /// <c>cos^2 = 1 - sin^2 = (1 - sin)(1 + sin)</c> the numerator is <c>(1 + sin)^2</c>. That
        /// cancellation is what <c>a^2 = b^2</c> buys, and it is the whole of the rule.
        /// </para>
        /// <para>
        /// Above the base case, one step of by parts lowers <c>n</c> by one:
        /// </para>
        /// <code>
        ///     int (a + b sin)^n = -b cos (a + b sin)^(n-1)/(c n) + (a (2n - 1)/n) int (a + b sin)^(n-1)
        /// </code>
        /// <para>
        /// which is checked by differentiating the first term and using <c>b^2 cos^2 =
        /// (a - b sin)(a + b sin)</c>. Applied until <c>n</c> is <c>1/2</c>, so
        /// <c>(1 - sin(2x/3))^(5/2)</c> is two steps and a base. A cosine is the same rule
        /// with <c>sin</c> replaced by <c>-cos</c> in the first term, since <c>d cos = -sin</c>.
        /// </para>
        /// <para>
        /// <b>No condition is owed.</b> <c>a + b sin</c> is never negative when <c>a^2 = b^2</c>,
        /// so its square root is real wherever the integrand is, and the base-case answer is a
        /// single antiderivative across the zeros of <c>1 + sin</c>: both it and the integrand
        /// vanish there. <c>a^2 = b^2</c> is required decidably, so a symbolic <c>a</c> beside a
        /// numeric <c>b</c> is not this shape. Rubi's rule for the same case is the source.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAHalfPowerOfOnePlusASine(Entity expr, Entity.Variable x)
        {
            if (expr is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer
                || !exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) || exponent.ERational.Sign <= 0)
                return null;
            // a + b f(u), for f a sine or cosine of something linear in x, read off the sum.
            Entity a = 0;
            Entity? b = null;
            Entity? argument = null;
            var isSine = false;
            foreach (var term in Sumf.LinearChildren(@base))
            {
                if (!term.ContainsNode(x))
                {
                    a += term;
                    continue;
                }
                Entity coefficient = 1;
                Entity? function = null;
                foreach (var factor in Mulf.LinearChildren(term))
                    if (!factor.ContainsNode(x))
                        coefficient *= factor;
                    else if (function is null && factor is Sinf or Cosf)
                        function = factor;
                    else
                        return null;
                if (function is null || b is not null)
                    return null;
                b = coefficient;
                isSine = function is Sinf;
                argument = function.DirectChildren.First();
            }
            if (b is null || argument is null)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _)
                || rate.Evaled is Number.Complex { IsZero: true })
                return null;
            // a^2 = b^2, decided rather than assumed.
            if ((MathS.Sqr(a) - MathS.Sqr(b)).Evaled is not Number.Complex { IsZero: true })
                return null;

            var n = exponent.ERational;
            // The direction of the first by-parts term: b cos for a sine, -b sin for a cosine.
            var complement = isSine ? MathS.Cos(argument) : -MathS.Sin(argument);
            Entity Step(ERational power)
            {
                var previous = Number.Rational.Create(power.Subtract(ERational.One));
                var current = Number.Rational.Create(power);
                if (power.CompareTo(ERational.Create(1, 2)) == 0)
                    return -2 * b * complement / (rate * MathS.Sqrt(@base));
                return -b * complement * MathS.Pow(@base, previous) / (rate * current)
                    + a * (2 * current - 1) / current * Step(power.Subtract(ERational.One));
            }
            return Step(n).InnerSimplified;
        }

        /// <summary>
        /// <c>(a + b cos(y) + c sin(y))^n</c> for <c>a^2 = b^2 + c^2</c>, <c>y</c> linear in
        /// <c>x</c> and <c>n</c> half-odd or a negative whole number, in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>b cos(y) + c sin(y)</c> is <c>R cos(y - phi)</c> for <c>R = sqrt(b^2 + c^2)</c>, so
        /// the base is <c>a (1 ± cos(y - phi))</c>, a square of the half angle as
        /// <c>a + a sin(y)</c> is, and <see cref="SolveAHalfPowerOfOnePlusASine"/>'s identity
        /// holds for it. Rubi's <c>sqrt(5 + 4 cos(x) + 3 sin(x))</c> and the rest of its 4.7.7
        /// with <c>a^2 = b^2 + c^2</c> were declined or past the budget. The answer needs no
        /// <c>phi</c>: with <c>S</c> the base and <c>T = b sin(y) - c cos(y)</c>,
        /// <c>T' = S - a</c>, <c>S' = -T</c> and <c>T^2 = S (2a - S)</c>, the last of which is
        /// <c>a^2 = b^2 + c^2</c>, and from them
        /// </para>
        /// <code>
        ///     d/dy (T S^(n-1)) = n S^n - a (2n - 1) S^(n-1)
        /// </code>
        /// <para>
        /// which steps <c>n</c> down to <c>1/2</c>, where the integral is <c>2T/sqrt(S)</c>, or
        /// up to <c>-1/2</c> or <c>-1</c>, where it is
        /// <c>(2/sqrt(2a)) atanh(T/(sqrt(2a) sqrt(S)))</c> and <c>T/(a S)</c>. Each base is
        /// checked by differentiating it with those three identities alone.
        /// </para>
        /// <para>
        /// For a real <c>a</c> of either sign: the derivations use only
        /// <c>S^(3/2) = S sqrt(S)</c> and <c>(sqrt(2a) sqrt(S))^2 = 2a S</c>, which hold for
        /// the principal powers, and the argument of the hyperbolic arctangent stays between
        /// <c>-1</c> and <c>1</c>, one less its square being <c>S/(2a)</c>, which is not negative
        /// since <c>S</c> has the sign of <c>a</c>. An antiderivative on every interval between
        /// the zeros of <c>S</c>, where <c>T</c> changes sign. <c>a^2 = b^2 + c^2</c> is decided,
        /// not assumed, and the cosine and the sine are both there: one alone is
        /// <see cref="SolveAHalfPowerOfOnePlusASine"/>'s.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAPowerOfACosineAndASinePlusTheirAmplitude(Entity expr, Entity.Variable x)
        {
            // A constant times one power of the base, the power above the bar or below it.
            if (!TryReadAsQuotient(expr, out var above, out var below))
                (above, below) = (expr, Number.Integer.One);
            Entity constant = Number.Integer.One;
            Entity? @base = null;
            ERational? exponent = null;
            foreach (var (side, sign) in new[] { (above, 1), (below, -1) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (!factor.ContainsNode(x))
                    {
                        constant = sign > 0 ? constant * factor : constant / factor;
                        continue;
                    }
                    if (@base is not null)
                        return null;
                    (@base, exponent) = factor is Powf(var inner, var power) && power.Evaled is Number.Rational rational
                        ? (inner, rational.ERational)
                        : (factor, ERational.One);
                    if (sign < 0)
                        exponent = exponent.Negate();
                }
            if (@base is null || exponent is null)
                return null;
            var n = exponent;
            // Half-odd, or a negative whole number, and of a modest size: a positive whole power
            // is a polynomial in the sine and cosine.
            var isHalfOdd = n.Denominator.Equals(EInteger.FromInt32(2));
            if (!isHalfOdd && !(n.Denominator.Equals(EInteger.One) && n.Sign < 0)
                || n.Abs().CompareTo(ERational.FromInt32(MaximumAmplitudePower)) > 0)
                return null;
            // a + b cos(y) + c sin(y), read off the sum.
            Entity a = Number.Integer.Zero;
            Entity? b = null, c = null, argument = null;
            foreach (var term in Sumf.LinearChildren(@base))
            {
                if (!term.ContainsNode(x))
                {
                    a = a == Number.Integer.Zero ? term : a + term;
                    continue;
                }
                Entity coefficient = Number.Integer.One;
                Entity? function = null;
                foreach (var factor in Mulf.LinearChildren(term))
                    if (!factor.ContainsNode(x))
                        coefficient = coefficient == Number.Integer.One ? factor : coefficient * factor;
                    else if (function is null && factor is Sinf or Cosf)
                        function = factor;
                    else
                        return null;
                var inner = function?.DirectChildren.First();
                if (inner is null || argument is not null && inner != argument)
                    return null;
                argument = inner;
                if (function is Cosf)
                {
                    if (b is not null) return null;
                    b = coefficient;
                }
                else
                {
                    if (c is not null) return null;
                    c = coefficient;
                }
            }
            if (b is null || c is null || argument is null || a == Number.Integer.Zero)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) || rate.ContainsNode(x)
                || rate.Evaled is Number.Complex { IsZero: true })
                return null;
            // a^2 = b^2 + c^2, decided rather than assumed.
            var excess = (MathS.Sqr(a) - MathS.Sqr(b) - MathS.Sqr(c)).InnerSimplified;
            if (excess.Evaled is not Number.Complex { IsZero: true }
                && !(excess.Vars.Any() && Functions.PartialFractions.Bare(excess.Simplify()).Evaled is Number.Complex { IsZero: true }))
                return null;
            if (a.Evaled is Number.Complex { IsZero: true })
                return null;

            var s = @base;
            var t = b * MathS.Sin(argument) - c * MathS.Cos(argument);
            var half = ERational.Create(1, 2);
            Entity Integral(ERational power)
            {
                if (power.CompareTo(half) == 0)
                    return 2 * t / MathS.Sqrt(s);
                if (power.CompareTo(half.Negate()) == 0)
                    return 2 / MathS.Sqrt(2 * a) * MathS.Hyperbolic.Artanh(t / (MathS.Sqrt(2 * a) * MathS.Sqrt(s)));
                if (power.CompareTo(ERational.FromInt32(-1)) == 0)
                    return t / (a * s);
                var current = Number.Rational.Create(power);
                if (power.Sign > 0)
                    return t * MathS.Pow(s, Number.Rational.Create(power.Subtract(ERational.One))) / current
                        + a * (2 * current - 1) / current * Integral(power.Subtract(ERational.One));
                return ((current + 1) * Integral(power.Add(ERational.One)) - t * MathS.Pow(s, current)) / (a * (2 * current + 1));
            }
            return (constant * Integral(n) / rate).InnerSimplified;
        }

        /// <summary>
        /// The largest power, either way, that <see cref="SolveAPowerOfACosineAndASinePlusTheirAmplitude"/>
        /// steps through: each step is a term of the answer.
        /// </summary>
        private const int MaximumAmplitudePower = 8;

        /// <summary>
        /// Fractional powers of <c>a ± a sin(y)</c>, or of <c>a ± a cos(y)</c>, beside anything
        /// rational in the sine and cosine of <c>y</c>, by the half angle at which they are
        /// squares: <c>1 + sin(y)</c> is <c>2 sin(u)^2</c> and <c>1 - sin(y)</c> is
        /// <c>2 cos(u)^2</c> for <c>u = y/2 + pi/4</c>, so <c>(a + a sin(y))^(3/2)</c> is
        /// <c>a^(3/2) 2^(3/2) sgn(sin(u)) sin(u)^3</c>, the sign a constant between the zeros of
        /// the sine that comes out in front of the integral, and what is left is rational in
        /// <c>sin(u)</c> and <c>cos(u)</c> -- <c>sin(y)</c> being <c>2 sin(u)^2 - 1</c> and
        /// <c>cos(y)</c> being <c>2 sin(u) cos(u)</c>. For the cosine, <c>u = y/2</c>, with
        /// <c>1 + cos(y) = 2 cos(u)^2</c> and <c>1 - cos(y) = 2 sin(u)^2</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Rubi's <c>(a + b sin)^m (c + d sin)^n (A + B sin + C sin^2)</c> files with
        /// <c>a^2 = b^2</c> and <c>c^2 = d^2</c> -- <c>(A + C sin^2)/((c - c sin)^(3/2) sqrt(a + a sin))</c>
        /// and its kin -- were timeouts: the substitution search has no radical of a
        /// trigonometric function it can rationalise, and <see cref="SolveAHalfPowerOfOnePlusASine"/>
        /// reads one such power alone. This is that rule's identity applied to the whole
        /// integrand at once.
        /// </para>
        /// <para>
        /// Exact, for any <c>a</c>: <c>1 + sin(y)</c> is not negative, so <c>(a q)^p = a^p q^p</c>
        /// for the principal powers whatever <c>a</c> is, and <c>(2 sin(u)^2)^p</c> is
        /// <c>2^p |sin(u)|^(2p)</c>. <c>a^2 = b^2</c> is decided, not assumed. Whole products
        /// <c>2p</c> only, so that the sign is a power of a sign and what is handed on is a whole
        /// power of the sine; at the top only, as every rule that writes a sign for a function.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTheHalfAngleWhereOnePlusASineIsASquare(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            Entity? argument = null;
            foreach (var node in expr.Nodes)
            {
                if (TrigonometricArgument(node) is not { } thisArgument || !thisArgument.ContainsNode(x))
                    continue;
                if (argument is null)
                    argument = thisArgument;
                else if (argument != thisArgument)
                    return null;
            }
            if (argument is null || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out var offsetOfArgument)
                || rate.ContainsNode(x) || TreeAnalyzer.IsZero(rate))
                return null;
            if (!expr.Nodes.All(node => !node.ContainsNode(x)
                    || node is Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf or Secantf or Cosecantf or Tanf or Cotanf
                    || node is Powf(_, Number.Rational)))
                return null;
            var sine = MathS.Sin(argument);
            var cosine = MathS.Cos(argument);
            // Which of the two functions the half powers are of: all of one kind, or none.
            bool? ofTheSine = null;
            var found = false;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(x))
                    continue;
                if (ReadAsOnePlusMinusAFunction(radicand, sine, cosine) is not var (_, _, isSine))
                    return null;
                if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                    return null;
                if (ofTheSine is { } kind && kind != isSine)
                    return null;
                ofTheSine = isSine;
                found = true;
            }
            if (!found || ofTheSine is not { } sineKind)
                return null;
            // One such power alone, to a positive exponent, is the closed rule's first, which
            // answers it in a single form across the zeros of `1 + sin(y)` where this one
            // writes a sign; the closed rule wants `a^2 = b^2` decided by evaluation, so
            // `sqrt(a + a sin(x))` with a symbol falls through to here.
            if (expr is Powf(_, Number.Rational { ERational.Sign: > 0 }) && SolveAHalfPowerOfOnePlusASine(expr, x) is { } closed)
                return closed;

            var u = Variable.CreateUnique(expr, "u_half_square");
            var sinU = MathS.Sin(u);
            var cosU = MathS.Cos(u);
            // sin(y) and cos(y) in u, and the two squares.
            Entity sineInU = sineKind ? 2 * MathS.Sqr(sinU) - 1 : 2 * sinU * cosU;
            Entity cosineInU = sineKind ? 2 * sinU * cosU : 2 * MathS.Sqr(cosU) - 1;
            // 1 + f is twice the square of `plus`, 1 - f twice the square of `minus`.
            Entity plus = sineKind ? sinU : cosU;
            Entity minus = sineKind ? cosU : sinU;
            Entity signs = Number.Integer.One;
            var inTheTwo = expr.Replace(node => node switch
            {
                Secantf(var a) when a == argument => 1 / cosine,
                Cosecantf(var a) when a == argument => 1 / sine,
                Tanf(var a) when a == argument => sine / cosine,
                Cotanf(var a) when a == argument => cosine / sine,
                _ => node,
            });
            var rewritten = inTheTwo.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(x))
                    return node;
                if (ReadAsOnePlusMinusAFunction(radicand, sine, cosine) is not var (a, positive, _))
                    return node;
                var square = positive ? plus : minus;
                var twoP = exponent.ERational.Numerator;
                // (a (1 ± f))^p = a^p 2^p |s|^(2p) = a^p 2^p sgn(s)^(2p) s^(2p), and 2p is odd.
                signs = signs * MathS.Signum(square);
                Entity constant = MathS.Pow(2, exponent);
                if (a != Number.Integer.One)
                    constant = MathS.Pow(a, exponent) * constant;
                return constant * MathS.Pow(square, Number.Integer.Create(twoP));
            });
            var inU = rewritten.Substitute(sine, sineInU).Substitute(cosine, cosineInU);
            // What is left of the variable is the variable itself: the angle is `rate x + offset`
            // and `u` is half of it (a quarter turn on for the sine), so `x` is
            // `(2u - pi/2 - offset)/rate` there and `(2u - offset)/rate` here -- and
            // `x^3 sqrt(a + a cos(c + d x))` is a polynomial in `u` times a cosine of it, which
            // the closed rules answer, where the rule used to decline anything beside the root.
            if (inU.ContainsNode(x))
            {
                var argumentInU = sineKind ? (2 * u - MathS.pi / 2).InnerSimplified : (2 * u).InnerSimplified;
                var xInU = ((argumentInU - offsetOfArgument) / rate).InnerSimplified;
                inU = inU.Substitute(x, xInU);
                if (inU.ContainsNode(x))
                    return null;
            }
            // dx = 2 du / rate.
            var integrand = (inU * 2 / rate).InnerSimplified;
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts) is not { } result)
                return null;
            var back = sineKind ? argument / 2 + MathS.pi / 4 : argument / 2;
            var answer = (signs == Number.Integer.One ? result : signs * result).Substitute(u, back);
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// Half-odd powers of <c>a ± a sec(y)</c>, beside powers of <c>d sec(y)</c> or
        /// <c>d cos(y)</c> and anything rational in the sine and cosine of <c>y</c>, by the
        /// half-angle tangent <c>t = tan(y/2)</c>: <c>1 + sec(y)</c> is <c>2/(1 - t^2)</c>,
        /// <c>1 - sec(y)</c> is <c>-2 t^2/(1 - t^2)</c> and <c>sec(y)</c> is
        /// <c>(1 + t^2)/(1 - t^2)</c>, so the whole is a rational function of t beside a root of
        /// <c>1 - t^2</c> or of <c>1 + t^2</c> -- or of both, which is elliptic and declined. The
        /// cosecant's the same way through the complement, <c>csc(y) = sec(pi/2 - y)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Rubi's <c>(a + b sec)^m (d sec)^n</c> files with <c>a^2 = b^2</c> hold about a thousand
        /// problems with a half-odd <c>m</c>, and none was answered, <c>sqrt(1 + sec(x))</c>
        /// included: the half angle at which <c>a + a cos(y)</c> is a square, the rule before this
        /// one, leaves a root of the cosine below the bar here, since <c>1 + sec(y)</c> is that
        /// square over <c>cos(y)</c>.
        /// </para>
        /// <para>
        /// Exact where the integrand is real. <c>a (1 + sec(y))</c> is not negative with
        /// <c>t</c> inside <c>(-1, 1)</c> for a positive <c>a</c> and outside it for a negative
        /// one, and either way <c>(2a/(1 - t^2))^p</c> is <c>(2a)^p (1 - t^2)^(-p)</c> for the
        /// principal powers; so for the secant's power beside it. For <c>1 - sec(y)</c> the square
        /// <c>t^2</c> comes out of the root as <c>|t|</c>, a sign constant between the zeros of
        /// <c>tan(y/2)</c> in front. At the question asked or one below it, since it lands on the
        /// chain in t.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByTheHalfAngleTangentBesideAHalfOddPowerOfOnePlusASecant(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            Entity? argument = null;
            foreach (var node in expr.Nodes)
            {
                if (TrigonometricArgument(node) is not { } thisArgument || !thisArgument.ContainsNode(x))
                    continue;
                if (argument is null)
                    argument = thisArgument;
                else if (argument != thisArgument)
                    return null;
            }
            if (argument is null || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _)
                || rate.ContainsNode(x) || TreeAnalyzer.IsZero(rate))
                return null;
            if (!expr.Nodes.All(node => !node.ContainsNode(x)
                    || node is Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf or Secantf or Cosecantf or Tanf or Cotanf
                    || node is Powf(_, Number.Rational)))
                return null;
            var secant = MathS.Sec(argument);
            var cosecant = new Cosecantf(argument);
            // The secant's, or the cosecant's by the complement: csc(y) is sec(y') for
            // y' = pi/2 - y, so each function of y is the complementary one of y', and the
            // half-angle tangent is t = tan(y'/2).
            bool? ofTheSecant = null;
            foreach (var node in expr.Nodes)
                if (node is Powf(var radicand, Number.Rational exponent) && exponent is not Number.Integer
                    && ReadAsOnePlusMinusAFunction(radicand, secant, cosecant) is (_, _, var isSecant))
                {
                    if (ofTheSecant is { } kind && kind != isSecant)
                        return null;
                    ofTheSecant = isSecant;
                }
            if (ofTheSecant is not { } secantKind)
                return null;
            var primary = secantKind ? secant : cosecant;
            var companion = secantKind ? MathS.Cos(argument) : MathS.Sin(argument);
            var t = Variable.CreateUnique(expr, "t_half_secant");
            var oneMinus = 1 - MathS.Sqr(t);
            var onePlus = 1 + MathS.Sqr(t);
            Entity signs = Number.Integer.One;
            var found = false;
            var declined = false;
            var roots = 0;
            // Each half-odd power, assembled in t: of a (1 ± sec(y)), or of d sec(y) or d cos(y);
            // for the cosecant, of a (1 ± csc(y)), d csc(y) or d sin(y).
            var rewritten = expr.Replace(node =>
            {
                if (declined || node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(x))
                    return node;
                if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !exponent.ERational.Numerator.CanFitInInt32())
                {
                    declined = true;
                    return node;
                }
                roots++;
                if (ReadAsOnePlusMinusAFunction(radicand, secant, cosecant) is (var a, var plus, var isSecant) && isSecant == secantKind)
                {
                    found = true;
                    if (plus)
                        return MathS.Pow(2 * a, exponent) * MathS.Pow(oneMinus, (-exponent).InnerSimplified);
                    // (-2a t^2/(1 - t^2))^p is (-2a)^p |t|^(2p) (1 - t^2)^(-p), and 2p is odd.
                    signs = signs * MathS.Signum(t);
                    return MathS.Pow(-2 * a, exponent) * MathS.Pow(t, Number.Integer.Create(exponent.ERational.Numerator)) * MathS.Pow(oneMinus, (-exponent).InnerSimplified);
                }
                // d sec(y) or d cos(y): a constant times the one function.
                Entity coefficient = Number.Integer.One;
                Entity? function = null;
                foreach (var factor in Mulf.LinearChildren(radicand))
                {
                    if (!factor.ContainsNode(x))
                        coefficient = coefficient * factor;
                    else if (function is null && (factor == primary || factor == companion))
                        function = factor;
                    else
                    {
                        declined = true;
                        return node;
                    }
                }
                if (function is null)
                {
                    declined = true;
                    return node;
                }
                var (above, below) = function == primary ? (onePlus, oneMinus) : (oneMinus, onePlus);
                return MathS.Pow(coefficient, exponent) * MathS.Pow(above, exponent) * MathS.Pow(below, (-exponent).InnerSimplified);
            });
            if (declined || !found)
                return null;
            // What is left is rational in the functions of y.
            var inT = rewritten.Replace(node => node switch
            {
                Sinf(var a) when a == argument => secantKind ? 2 * t / onePlus : oneMinus / onePlus,
                Cosf(var a) when a == argument => secantKind ? oneMinus / onePlus : 2 * t / onePlus,
                Tanf(var a) when a == argument => secantKind ? 2 * t / oneMinus : oneMinus / (2 * t),
                Cotanf(var a) when a == argument => secantKind ? oneMinus / (2 * t) : 2 * t / oneMinus,
                Secantf(var a) when a == argument => secantKind ? onePlus / oneMinus : onePlus / (2 * t),
                Cosecantf(var a) when a == argument => secantKind ? onePlus / (2 * t) : onePlus / oneMinus,
                _ => node,
            });
            // dy = 2 dt/(1 + t^2), and dx = dy/rate. Each power of the two quadratics and of t
            // gathered to one, so that they cancel and combine: left as written, `sec(y)` beside
            // `dy` reached the rules in t as `(1 + t^2)^0`, which none reads.
            var bases = new[] { oneMinus, onePlus, (Entity)t };
            // dy' = -dy for the cosecant.
            var (rest, exponents) = GatheredOverTheBases(inT * (secantKind ? 2 : -2) / (rate * onePlus), bases);
            Entity integrand = rest.InnerSimplified;
            var halfOdd = 0;
            for (var i = 0; i < bases.Length; i++)
            {
                if (exponents[i].IsZero)
                    continue;
                // Not normalised as it is gathered: 8/4 is a whole power.
                if (!exponents[i].Numerator.Remainder(exponents[i].Denominator).IsZero)
                    halfOdd++;
                integrand = integrand * MathS.Pow(bases[i], Number.Rational.Create(exponents[i]));
            }
            // A root of 1 - t^2 beside one of 1 + t^2 is elliptic: declined before it is asked.
            if (halfOdd > 1)
                return null;
            integrand = integrand.InnerSimplified;
            if (integrand.ContainsNode(x) || integrand.Nodes.Any(node => node == MathS.NaN))
                return null;
            // A rational function beside the root, which is what this lands on, is taken apart by
            // the rule for it before the chain is asked: asked as a question, the substitution
            // search ahead of that rule spent the budget on `(1 - t^2)^(3/2)/((1 + t^2)(p + q t^2)^2)`,
            // which `sqrt(a + a sec(y))/(c + d sec(y))^2` is.
            if ((SolveARationalFunctionBesideTheRootOfAQuadratic(integrand, t)
                    ?? Integration.ComputeAsAQuestionOfItsOwn(integrand, t, integrateByParts)) is not { } result)
                return null;
            var back = secantKind ? MathS.Tan(argument / 2) : MathS.Tan(MathS.pi / 4 - argument / 2);
            var answer = (signs == Number.Integer.One ? result : signs * result).Substitute(t, back);
            if (answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            // Each root written apart is exact inside t^2 < 1, where 1 - t^2 is positive, for any
            // sign of the constants. Outside it a root whose radicand is negative there is
            // imaginary, and one alone leaves the integrand complex, where the answer is nothing
            // to be wrong about; but two can make it real again -- `(1 + sec(x))^(5/2) sqrt(cos(x))`
            // is real where the cosine is negative -- and there each written apart may have
            // turned its sign where the other did not. The answer says where it holds.
            return roots < 2 ? answer : answer.Provided((secantKind ? MathS.Cos(argument) : MathS.Sin(argument)) >= Number.Integer.Zero);
        }

        /// <summary>
        /// <paramref name="expr"/> as what it is a product of beside <paramref name="bases"/>, and
        /// the sum of the exponents of each base in it, read through products, quotients and
        /// whole powers of them.
        /// </summary>
        private static (Entity Others, ERational[] Exponents) GatheredOverTheBases(Entity expr, Entity[] bases)
        {
            var exponents = bases.Select(_ => ERational.Zero).ToArray();
            Entity rest = Number.Integer.One;
            Gather(expr, ERational.One);
            return (rest, exponents);

            void Gather(Entity node, ERational power)
            {
                if (System.Array.IndexOf(bases, node) is var at and >= 0)
                {
                    exponents[at] = exponents[at].Add(power);
                    return;
                }
                switch (node)
                {
                    case Mulf(var left, var right):
                        Gather(left, power);
                        Gather(right, power);
                        return;
                    case Divf(var above, var below):
                        Gather(above, power);
                        Gather(below, power.Negate());
                        return;
                    case Powf(var @base, Number.Rational exponent) when System.Array.IndexOf(bases, @base) >= 0
                        || exponent is Number.Integer && @base is Mulf or Divf or Powf:
                        Gather(@base, power.Multiply(exponent.ERational));
                        return;
                    default:
                        rest = power.Equals(ERational.One) ? rest * node : rest * MathS.Pow(node, Number.Rational.Create(power));
                        return;
                }
            }
        }

        /// <summary>
        /// <paramref name="radicand"/> read as <c>a (1 ± f)</c> for <c>f</c> the given sine or
        /// cosine: the constant <c>a</c>, whether the sign is plus, and whether <c>f</c> is the
        /// sine. Null for anything else, including <c>a + b f</c> with <c>a^2 ≠ b^2</c>.
        /// </summary>
        private static (Entity Constant, bool Plus, bool IsSine)? ReadAsOnePlusMinusAFunction(Entity radicand, Entity sine, Entity cosine)
        {
            Entity a = Number.Integer.Zero;
            Entity? b = null;
            Entity? function = null;
            foreach (var term in Sumf.LinearChildren(radicand))
            {
                if (!term.ContainsNode(sine) && !term.ContainsNode(cosine))
                {
                    a += term;
                    continue;
                }
                Entity coefficient = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(term))
                {
                    if (factor == sine || factor == cosine)
                    {
                        if (function is not null)
                            return null;
                        function = factor;
                    }
                    else if (!factor.ContainsNode(sine) && !factor.ContainsNode(cosine))
                        coefficient *= factor;
                    else
                        return null;
                }
                if (function is null || b is not null)
                    return null;
                b = coefficient;
            }
            if (b is null || function is null)
                return null;
            a = a.InnerSimplified;
            b = b.InnerSimplified;
            if (a.Evaled is Number.Complex { IsZero: true })
                return null;
            var plus = (a - b).InnerSimplified.Evaled is Number.Complex { IsZero: true } || (a - b).Simplify().Evaled is Number.Complex { IsZero: true };
            var minus = !plus && ((a + b).InnerSimplified.Evaled is Number.Complex { IsZero: true } || (a + b).Simplify().Evaled is Number.Complex { IsZero: true });
            if (!plus && !minus)
                return null;
            return (a, plus, function == sine);
        }

        /// <summary>
        /// A whole power of the secant or cosecant, brought down two at a time by the standard
        /// reduction until the power rule for the first or the zeroth takes over.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/cos(x)^2</c> was answered and <c>1/cos(x)^6</c> was not. The rule for powers of
        /// sine and cosine reads a <b>positive</b> exponent, so a negative one — which is what a
        /// secant or cosecant is — matched nothing above the square, and the square was answered
        /// only because it is a standard integral in its own right.
        /// </para>
        /// <para>
        /// This is Rubi's rule 4.5.1.1, ported:
        /// <code>
        /// Int[(b*csc[c+d*x])^n] := -b*Cos[c+d*x]*(b*Csc[c+d*x])^(n-1)/(d*(n-1))
        ///                          + b^2*(n-2)/(n-1)*Int[(b*Csc[c+d*x])^(n-2)]
        ///     /; GtQ[n,1] &amp;&amp; IntegerQ[2*n]
        /// </code>
        /// which for the secant reads
        /// <c>∫sec^n = sec^(n-2) tan/(a(n-1)) + ((n-2)/(n-1)) ∫sec^(n-2)</c>, and for the
        /// cosecant the same with <c>-cot</c> and the sign of the first term flipped. Each step
        /// takes two off the exponent, so it ends at <c>n = 1</c> — a standard integral here
        /// already — or at <c>n = 0</c>, which is <c>x</c>.
        /// </para>
        /// <para>
        /// <b>Read through both spellings.</b> A secant is <c>sec(u)</c>, and it is also
        /// <c>cos(u)^(-n)</c> and <c>1/cos(u)^n</c>; all three arrive here, and answering one of
        /// them and not the others is the defect this file has had five times over.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveBySecantPowerReduction(Entity expr, Entity.Variable x)
        {
            if (!TryReadReciprocalTrigonometricPower(expr, out var argument, out var power, out var isSecant))
                return null;
            if (power < 2)
                return null;   // the first power and the zeroth are answered without a recursion
            // Asked, not volunteered. Answering a power of the secant that some other rule
            // produced on its way somewhere lets that rule's search carry on instead of
            // stopping, and that -- rather than any work this does -- is what took
            // `sec(x)^6*tan(x)^3` from a 637 ms decline to not returning in 400 s.
            // https://github.com/asc-community/AngouriMath/issues/1265
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) || rate.Evaled == 0)
                return null;

            var reciprocal = isSecant ? MathS.Sec(argument) : MathS.Cosec(argument);
            var partner = isSecant ? MathS.Tan(argument) : MathS.Cotan(argument);

            // The recurrence run out here rather than through the integrator. Every step is
            // determined -- the power comes down by two and the coefficient is (n-2)/(n-1) --
            // so there is nothing to search for, and asking the integrator instead would put the
            // rule's own descent behind the gate above and stop it after one step.
            //
            //   sec^(n-2) tan / (a(n-1))  +  ((n-2)/(n-1)) * the same at n-2
            //  -csc^(n-2) cot / (a(n-1))  +  ((n-2)/(n-1)) * the same at n-2
            Entity total = 0;
            Entity carried = 1;
            var remaining = power;
            while (remaining >= 2)
            {
                var lowered = remaining - 2 == 1 ? reciprocal : MathS.Pow(reciprocal, remaining - 2);
                var boundary = lowered * partner / (rate * Number.Integer.Create(remaining - 1));
                if (!isSecant)
                    boundary = -boundary;
                total += carried * boundary;
                carried *= Number.Rational.Create(remaining - 2, remaining - 1);
                remaining -= 2;
            }

            // What the recurrence lands on: sec^1 and csc^1 are the standard integrals this
            // library already carries, and sec^0 is x. Written out rather than asked for, so
            // that the rule is closed over its own recursion.
            var rest = remaining == 0
                ? x
                : isSecant
                    ? MathS.Hyperbolic.Artanh(MathS.Sin(argument)) / rate
                    : IntegralPatterns.AntiderivativeLog(MathS.Tan(argument / 2)) / rate;

            return total + carried * rest;
        }

        /// <summary>
        /// An integrand that is a power of the sine times a power of the cosine, of one common
        /// argument linear in the variable, turned into a polynomial by whichever of
        /// <c>u = cos</c>, <c>u = sin</c> and <c>u = tan</c> the two exponents admit.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <b>Everything built from the six trigonometric functions is a <c>sin^p cos^q</c></b>,
        /// and reading it that way is what makes one rule out of a family Rubi spreads over
        /// several sections: <c>tan^m sec^n</c> is <c>sin^m cos^(-m-n)</c>, <c>cot^m csc^n</c> is
        /// <c>cos^m sin^(-m-n)</c>, a power of the secant alone is <c>cos^(-n)</c>. The exponents
        /// are integers of either sign, so the same three cases below cover all of them.
        /// </para>
        /// <para>
        /// <b>Which substitution, and why exactly these three.</b> Each one has to leave a
        /// <i>Laurent polynomial</i> — a sum of powers of <c>u</c>, integrated term by term —
        /// because that is what makes the rule closed. It asks the integrator nothing.
        /// </para>
        /// <list type="bullet">
        /// <item><description>
        /// <c>p</c> odd and at least one: <c>u = cos</c>, <c>du = -sin dx</c>, so one sine goes
        /// into <c>du</c> and <c>sin^(p-1)</c> is <c>(1 - u^2)^((p-1)/2)</c>. Leaves
        /// <c>-(1 - u^2)^((p-1)/2) u^q</c>, and <c>q</c> may be anything.
        /// </description></item>
        /// <item><description>
        /// <c>q</c> odd and at least one: <c>u = sin</c>, the mirror of it.
        /// </description></item>
        /// <item><description>
        /// both even and <c>p + q</c> at most <c>-2</c>: <c>u = tan</c>, under which
        /// <c>cos^2 = 1/(1 + u^2)</c> and <c>dx = du/(1 + u^2)</c>, leaving
        /// <c>u^p (1 + u^2)^(-(p+q)/2 - 1)</c> — a polynomial exactly when <c>p + q</c> is at
        /// most <c>-2</c>, which is the condition. <c>tan^2 sec^4</c> is this case and neither
        /// of the others.
        /// </description></item>
        /// </list>
        /// <para>
        /// <b>What is deliberately left out</b>: both exponents even with <c>p + q</c> at least
        /// zero, where the tangent substitution leaves a negative power of <c>1 + u^2</c> rather
        /// than a polynomial. Those are the ordinary <c>sin^2 cos^4</c> shapes, which the
        /// power-reduction rules already answer, so the boundary costs nothing. A power of the
        /// secant or cosecant alone reaches <see cref="SolveBySecantPowerReduction"/> first,
        /// which gives a shorter answer for it.
        /// </para>
        /// <para>
        /// <b>Asked, not volunteered</b>, for the reason in
        /// <a href="https://github.com/asc-community/AngouriMath/issues/1265">#1265</a>: a rule
        /// that answers a sub-integral which used to come back unanswered lets the search that
        /// asked for it carry on, and that cost lands on integrands the rule never fires on.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTrigonometricPowerSubstitution(Entity expr, Entity.Variable x, bool asked = false)
        {
            if (!asked && !Integration.AnsweringTheQuestionAsked)
                return null;
            if (!TryReadSineCosinePowers(expr, out var argument, out var sinePower, out var cosinePower, out var factor, out var throughAProduct))
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) || rate.Evaled == 0)
                return null;
            if (IntegrateAPowerOfSineTimesAPowerOfCosine(argument, sinePower, cosinePower, factor, rate) is not { } integral)
                return null;
            if (!throughAProduct)
                return integral;
            // A fractional power of a product was read as the product of the powers, which is the
            // integrand only up to a constant on each interval where the factors keep their signs:
            // `(sin(x) tan(x))^(3/2)` is `|sin(x)|^3 cos(x)^(-3/2)` and was read as `sin(x)^3 cos(x)^(-3/2)`,
            // wrong by its sign on every other half-turn. The integrand over what was read is that
            // constant, so it multiplies the answer, and the answer is the integrand's wherever
            // both are defined.
            var read = factor * MathS.Pow(MathS.Sin(argument), Number.Rational.Create(sinePower))
                * MathS.Pow(MathS.Cos(argument), Number.Rational.Create(cosinePower));
            return expr / read * integral;
        }

        /// <summary>
        /// <c>int factor * sin(argument)^p cos(argument)^q dx</c>, where <paramref name="rate"/> is
        /// the derivative of the argument — the closed part of
        /// <see cref="SolveByTrigonometricPowerSubstitution"/>, separated so that a rule which
        /// <i>produces</i> such an integrand can use it without going back through the chain.
        /// </summary>
        /// <remarks>
        /// <see langword="null"/> where none of the three substitutions applies, which is the same
        /// boundary the rule above declines at.
        /// </remarks>
        private static Entity? IntegrateAPowerOfSineTimesAPowerOfCosine(
            Entity argument, ERational sinePower, ERational cosinePower, Entity factor, Entity rate)
        {
            // What is left after the substitution: u^leading times (1 + insideSign*u^2) raised to
            // expansionPower, all times sign -- which is what the substitution's own derivative
            // contributes, negative for the cosine and positive for the sine and the tangent.
            //
            // The exponent that decides the case must be a whole odd or even number, because it
            // is what the binomial expansion runs over. The *other* exponent -- `leading` -- need
            // only be rational: it rides through untouched and the power rule takes u^(-3/2) as
            // readily as u^(-3). That asymmetry is the whole of the fractional support.
            Entity u;
            ERational leading;
            int expansionPower, insideSign, sign;
            if (IsOddAndPositive(sinePower))
                (u, expansionPower, leading, insideSign, sign) =
                    (MathS.Cos(argument), (WholeOf(sinePower) - 1) / 2, cosinePower, -1, -1);
            else if (IsOddAndPositive(cosinePower))
                (u, expansionPower, leading, insideSign, sign) =
                    (MathS.Sin(argument), (WholeOf(cosinePower) - 1) / 2, sinePower, -1, 1);
            else if (IsEvenWhole(sinePower) && IsEvenWhole(cosinePower)
                     && WholeOf(sinePower) + WholeOf(cosinePower) <= -2)
                (u, expansionPower, leading, insideSign, sign) =
                    (MathS.Tan(argument),
                     -(WholeOf(sinePower) + WholeOf(cosinePower)) / 2 - 1, sinePower, 1, 1);
            // Neither substitution leaves a polynomial, and with both exponents whole there is
            // still a closed answer -- it just holds a logarithm, which the recurrences reach and
            // a rearranged polynomial cannot.
            else if (IsWholeAndFitsAnInt(sinePower, out var wholeSine)
                     && IsWholeAndFitsAnInt(cosinePower, out var wholeCosine))
                return (factor * IntegrateSineCosineByReduction(argument, wholeSine, wholeCosine) / rate)
                    .InnerSimplified;
            else
                return null;

            // The binomial expansion, each term integrated by the power rule -- or by the
            // logarithm at the one exponent where the power rule would divide by zero, which is
            // reachable here whenever `leading` is a negative odd whole number.
            Entity total = 0;
            var coefficient = EInteger.One;
            for (var i = 0; i <= expansionPower; i++)
            {
                var exponent = leading + ERational.FromInt32(2 * i);
                var raised = exponent + ERational.One;
                var term = raised.IsZero
                    ? IntegralPatterns.AntiderivativeLog(u)
                    : MathS.Pow(u, Number.Rational.Create(raised)) / Number.Rational.Create(raised);
                var alternating = insideSign < 0 && i % 2 != 0 ? -1 : 1;
                total += Number.Integer.Create(coefficient) * alternating * term;
                // The next binomial coefficient from this one: C(k, i+1) = C(k, i) * (k-i)/(i+1).
                coefficient = coefficient * (expansionPower - i) / (i + 1);
            }

            return (factor * sign * total / rate).InnerSimplified;
        }

        /// <summary>
        /// <c>int sin(t)^p cos(t)^q dt</c> for whole exponents of any sign, by the four standard
        /// recurrences, ending on the nine integrands with both exponents in <c>{-1, 0, 1}</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <b>This is the boundary the polynomial route stops at.</b> The three substitutions in
        /// <see cref="IntegrateAPowerOfSineTimesAPowerOfCosine"/> each leave a Laurent polynomial,
        /// so they answer the cases where one exponent is odd and positive, or where both are even
        /// and sum to at most <c>-2</c>. Everything else needs a <b>logarithm</b> somewhere, and
        /// no rearrangement of a polynomial produces one: <c>sin^2 cos^(-3)</c> is
        /// <c>x^2/sqrt(1 + x^2)</c> seen through the tangent substitution, and its antiderivative
        /// holds an inverse hyperbolic sine.
        /// </para>
        /// <para>
        /// The four recurrences, each of them one integration by parts written out:
        /// </para>
        /// <code>
        ///  q down   I(p,q) =  sin^(p+1) cos^(q-1)/(p+q)   + ((q-1)/(p+q))     I(p, q-2)
        ///  p down   I(p,q) = -sin^(p-1) cos^(q+1)/(p+q)   + ((p-1)/(p+q))     I(p-2, q)
        ///  q up     I(p,q) = -sin^(p+1) cos^(q+1)/(q+1)   + ((p+q+2)/(q+1))   I(p, q+2)
        ///  p up     I(p,q) =  sin^(p+1) cos^(q+1)/(p+1)   + ((p+q+2)/(p+1))   I(p+2, q)
        /// </code>
        /// <para>
        /// <b>Termination is <c>|p| + |q|</c>, which every branch below lowers by two</b> until
        /// both exponents are in <c>{-1, 0, 1}</c>. The downward pair divides by <c>p + q</c> and
        /// the upward pair by <c>q + 1</c> and <c>p + 1</c>; the ordering is chosen so that the
        /// branch taken never has a zero divisor. Raising is tried first for exactly that reason —
        /// <c>q + 1</c> is zero only at <c>q = -1</c>, which is already in range, so an exponent
        /// at most <c>-2</c> can always be raised, where <c>p + q</c> can vanish at any size.
        /// </para>
        /// <para>
        /// It is <b>closed</b>: the recursion is on two integers walking towards a fixed set, and
        /// it asks the integrator nothing.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        private static Entity IntegrateSineCosineByReduction(Entity argument, int sinePower, int cosinePower)
        {
            var sine = MathS.Sin(argument);
            var cosine = MathS.Cos(argument);

            if (sinePower >= -1 && sinePower <= 1 && cosinePower >= -1 && cosinePower <= 1)
                return (sinePower, cosinePower) switch
                {
                    (0, 0) => argument,
                    (1, 0) => -cosine,
                    (0, 1) => sine,
                    (1, 1) => MathS.Sqr(sine) / 2,
                    (1, -1) => -IntegralPatterns.AntiderivativeLog(cosine),      // int tan
                    (-1, 1) => IntegralPatterns.AntiderivativeLog(sine),         // int cot
                    (-1, -1) => IntegralPatterns.AntiderivativeLog(MathS.Tan(argument)),
                    // int sec and int csc, both as an inverse hyperbolic tangent. `ln|tan(t/2)|`
                    // is the usual form of the second and is avoided deliberately: it is the one
                    // base case whose argument is not `t` itself, and a caller substituting the
                    // trigonometric functions back cannot express a half-angle in terms of them.
                    // `-artanh(cos t)` is the same function and is symmetric with the first.
                    (0, -1) => MathS.Hyperbolic.Artanh(sine),
                    (-1, 0) => -MathS.Hyperbolic.Artanh(cosine),
                    _ => throw new Core.Exceptions.AngouriBugException(
                        "every pair in the base range is listed above"),
                };

            var sum = sinePower + cosinePower;
            Entity Power(Entity of, int to) => MathS.Pow(of, Number.Integer.Create(to));
            Entity Carried(int numerator, int denominator, int nextSine, int nextCosine)
                => Number.Rational.Create(numerator, denominator)
                 * IntegrateSineCosineByReduction(argument, nextSine, nextCosine);

            // Raising first, because an exponent at most -2 can always be raised and lowering can
            // be blocked by p + q being zero -- `tan(t)^2` is `sin^2 cos^(-2)`, the smallest case
            // where it is.
            if (cosinePower <= -2)
                return -Power(sine, sinePower + 1) * Power(cosine, cosinePower + 1)
                       / Number.Integer.Create(cosinePower + 1)
                     + Carried(sum + 2, cosinePower + 1, sinePower, cosinePower + 2);
            if (sinePower <= -2)
                return Power(sine, sinePower + 1) * Power(cosine, cosinePower + 1)
                       / Number.Integer.Create(sinePower + 1)
                     + Carried(sum + 2, sinePower + 1, sinePower + 2, cosinePower);
            // Both exponents are now at least -1, so p + q is zero only if one of them is -1 and
            // the other 1 -- both in range, and so already answered above.
            if (cosinePower >= 2)
                return Power(sine, sinePower + 1) * Power(cosine, cosinePower - 1)
                       / Number.Integer.Create(sum)
                     + Carried(cosinePower - 1, sum, sinePower, cosinePower - 2);
            return -Power(sine, sinePower - 1) * Power(cosine, cosinePower + 1)
                   / Number.Integer.Create(sum)
                 + Carried(sinePower - 1, sum, sinePower - 2, cosinePower);
        }

        /// <summary>
        /// A rational function of <c>x^n</c> times <c>(c + d x^n)^(k - 1/n)</c> for a whole
        /// <c>k</c>, rationalised by <c>u = x/(c + d x^n)^(1/n)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>du/dx</c> is <c>c (c + d x^n)^(-(n + 1)/n)</c>, so <c>dx/(c + d x^n)^(1/n)</c> is
        /// <c>(c + d x^n) du/c</c>; and <c>u^n = x^n/(c + d x^n)</c> gives <c>x^n = c u^n/(1 - d u^n)</c>
        /// and <c>c + d x^n = c/(1 - d u^n)</c>, so everything in <c>x^n</c> is rational in
        /// <c>u^n</c> and the integrand is a rational function of <c>u</c>. Timofeev's
        /// <c>1/((1 + x^4)(2 + x^4)^(1/4))</c> is <c>1/(1 + u^4)</c> under it, and his
        /// <c>(1 + x^4)^(3/4)/(2 + x^4)^2</c>, whose root is <c>(1 + x^4)^(1 - 1/4)</c>, is
        /// rational the same way; Welz's <c>1/((1 - x^3)(a + b x^3)^(1/3))</c> is
        /// <c>1/(1 - (a + b) u^3)</c>. Rubi's rule for <c>(c + d x^n)^p/(a + b x^n)</c> at
        /// <c>p = -1/n</c> is this substitution.
        /// </para>
        /// <para>
        /// The identity holds wherever the root is real, which is where the answer is
        /// asked; <c>u</c> goes back in as <c>x (c + d x^n)^(-1/n)</c>.
        /// </para>
        /// <para>
        /// And beside a power of <c>x</c> that is not one of <c>x^n</c>: <c>x^j</c> times a
        /// rational function of <c>x^n</c> times <c>(c + d x^n)^(k - (j + 1)/n)</c> is
        /// <c>u^j</c> times the same in <c>u</c>, since <c>x^j (c + d x^n)^(-j/n)</c> is
        /// <c>u^j</c>. Rubi's 1.1.3.4: <c>x/((a + b x^3)^(2/3) (c + d x^3))</c> is
        /// <c>u/(c - (b c - a d) u^3)</c>, and <c>x^4 (a + b x^3)^(1/3)/(c + d x^3)</c> is the
        /// same with <c>x^3</c> beside it; each was declined.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByDividingByTheRoot(Entity expr, Entity.Variable x)
        {
            // One fractional power of a binomial `c + d x^n` with exponent `k - 1/n`, and the
            // rest a rational function of x^n.
            Entity? radicand = null;
            Entity? c = null, d = null;
            var n = 0;
            var k = EInteger.Zero;
            // The power of x beside it, below n: the exponent is `k - (j + 1)/n`.
            var j = 0;
            Entity rest = Number.Integer.One;
            var (above, below) = Functions.SingleQuotient.Of(expr);
            foreach (var (side, isBelow) in new[] { (above, false), (below, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is Powf(var @base, Number.Rational exponent) && exponent is not Number.Integer && @base.ContainsNode(x))
                    {
                        var signed = isBelow ? exponent.ERational.Negate() : exponent.ERational;
                        if (radicand is not null || !TryReadAsABinomialIn(@base, x, out var readC, out var readD, out var readN)
                            || readN < 2 || !signed.Denominator.Equals(EInteger.FromInt32(readN)))
                            return null;
                        // The numerator of the exponent is k n - j - 1, for j from 0 to n - 1.
                        var nAsEInteger = EInteger.FromInt32(readN);
                        var residue = signed.Numerator.Add(EInteger.One).Remainder(nAsEInteger);
                        if (residue.Sign < 0)
                            residue = residue.Add(nAsEInteger);
                        var readJ = residue.IsZero ? 0 : readN - residue.ToInt32Checked();
                        radicand = @base;
                        c = readC;
                        d = readD;
                        n = readN;
                        j = readJ;
                        k = signed.Numerator.Add(EInteger.FromInt32(readJ + 1)).Divide(nAsEInteger);
                        continue;
                    }
                    if (factor.ContainsNode(x) && !IsRationalIn(factor, x))
                        return null;
                    rest = rest == Number.Integer.One ? (isBelow ? 1 / factor : factor) : isBelow ? rest / factor : rest * factor;
                }
            if (radicand is null || c is null || d is null || TreeAnalyzer.IsZero(c) || TreeAnalyzer.IsZero(d))
                return null;
            // The rest as a rational function of x^n, x^j taken out of it first: written in a
            // stand-in for x^n where every power of x is a multiple of n, and declined otherwise.
            if (j != 0)
            {
                // Out of the polynomial above the bar, each of whose powers is then a multiple of n.
                var (restAbove, restBelow) = Functions.SingleQuotient.Of(rest);
                if (!TreeAnalyzer.TryGetPolynomial(restAbove, x, out var aboveTerms) || aboveTerms.Count == 0)
                    return null;
                Entity lowered = Number.Integer.Zero;
                foreach (var term in aboveTerms)
                {
                    var power = term.Key.Subtract(EInteger.FromInt32(j));
                    if (power.Sign < 0 || term.Value.ContainsNode(x))
                        return null;
                    var monomial = power.IsZero ? term.Value : term.Value * MathS.Pow(x, Number.Integer.Create(power));
                    lowered = lowered == Number.Integer.Zero ? monomial : lowered + monomial;
                }
                rest = restBelow == Number.Integer.One ? lowered : lowered / restBelow;
            }
            var xToTheN = Variable.CreateUnique(expr, "x_n");
            var inXToTheN = rest.Replace(node =>
                node is Powf(var xAgain, Number.Integer power) && xAgain == x && power.EInteger.Remainder(EInteger.FromInt32(n)).IsZero
                    ? MathS.Pow(xToTheN, Number.Integer.Create(power.EInteger.Divide(EInteger.FromInt32(n))))
                    : node);
            if (inXToTheN.ContainsNode(x))
                return null;
            var u = Variable.CreateUnique(expr, "u_root");
            var uToTheN = MathS.Pow(u, n);
            var oneMinusDUToTheN = 1 - d * uToTheN;
            var binomialInU = c / oneMinusDUToTheN;
            // The factor the substitution leaves on both sides cancelled as it is written, not simplified:
            // `(1 - u^4)/((1 + u^4)(1 - u^4))` for Timofeev's above, which the rational integrator does
            // not cancel, and the search for a simpler form that did grows with the power of the binomial
            // while the symbols are in it: `1/((a + b x^2)^(7/2) (1 + x^2))` ran past 90 s on it. Each
            // base is its polynomial in u first, which collects what the substitution writes twice --
            // `1 - (-u^2) - u^2` is 1 under a secant's half angle -- and the factors stay as they are
            // written, which the rules after this read better than their product expanded.
            var restInU = inXToTheN.Substitute(xToTheN, c * uToTheN / oneMinusDUToTheN);
            if (j != 0)
                restInU = MathS.Pow(u, j) * restInU;
            var integrand = WithTheFactorsWrittenOnBothSidesCancelled(u, Functions.SingleQuotient.Combine(
                restInU
                * (k.IsZero ? Number.Integer.One : MathS.Pow(binomialInU, Number.Integer.Create(k)))
                / oneMinusDUToTheN).InnerSimplified);
            if (integrand is Providedf(var inner, _))
                integrand = inner;
            if (integrand.ContainsNode(x) || integrand.Nodes.Any(node => node == MathS.NaN))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts: false) is not { } result)
                return null;
            var answer = result.Substitute(u, x * MathS.Pow(radicand, Number.Rational.Create(-1, n)));
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// <paramref name="quotient"/> with each base that is a sum written as its polynomial in
        /// <paramref name="u"/>, and each factor then written alike above and below the bar
        /// cancelled, power for power; the factors are kept as factors.
        /// </summary>
        private static Entity WithTheFactorsWrittenOnBothSidesCancelled(Entity.Variable u, Entity quotient)
        {
            var (top, bottom) = Functions.SingleQuotient.Of(quotient);
            Entity AsItsPolynomial(Entity @base)
            {
                if (@base is not (Sumf or Minusf) || !@base.ContainsNode(u)
                    || !TreeAnalyzer.TryGetPolynomial(@base, u, out var terms)
                    || terms.Any(term => term.Key.Sign < 0 || term.Value.ContainsNode(u)))
                    return @base;
                Entity written = Number.Integer.Zero;
                foreach (var term in terms.OrderBy(term => term.Key))
                {
                    var coefficient = term.Value.InnerSimplified;
                    if (Functions.PartialFractions.IsZeroAsAValue(coefficient))
                        continue;
                    var monomial = term.Key.IsZero ? coefficient : coefficient * MathS.Pow(u, Number.Integer.Create(term.Key));
                    written = written == Number.Integer.Zero ? monomial : written + monomial;
                }
                return written.InnerSimplified;
            }
            List<(Entity Base, EInteger Power)> Factors(Entity side)
            {
                var factors = new List<(Entity Base, EInteger Power)>();
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var (@base, power) = factor is Powf(var raised, Number.Integer exponent) && exponent.EInteger.Sign > 0
                        ? (raised, exponent.EInteger) : (factor, EInteger.One);
                    @base = AsItsPolynomial(@base);
                    var at = factors.FindIndex(written => written.Base == @base);
                    if (at < 0)
                        factors.Add((@base, power));
                    else
                        factors[at] = (@base, factors[at].Power.Add(power));
                }
                return factors;
            }
            var above = Factors(top);
            var below = Factors(bottom);
            for (var i = 0; i < above.Count; i++)
            {
                if (above[i].Base is Number)
                    continue;
                var j = below.FindIndex(written => written.Base == above[i].Base);
                if (j < 0)
                    continue;
                var common = EInteger.Min(above[i].Power, below[j].Power);
                above[i] = (above[i].Base, above[i].Power.Subtract(common));
                below[j] = (below[j].Base, below[j].Power.Subtract(common));
            }
            static Entity Product(List<(Entity Base, EInteger Power)> factors)
                => factors.Where(written => !written.Power.IsZero).Aggregate((Entity)Number.Integer.One,
                    (product, written) => product * (written.Power.Equals(EInteger.One) ? written.Base : MathS.Pow(written.Base, Number.Integer.Create(written.Power))));
            return (Product(above) / Product(below)).InnerSimplified;
        }

        /// <summary>
        /// Reads <paramref name="expr"/> as <c>c + d x^n</c> with <c>c</c> and <c>d</c> free of
        /// <paramref name="x"/>.
        /// </summary>
        private static bool TryReadAsABinomialIn(Entity expr, Entity.Variable x, out Entity c, out Entity d, out int n)
        {
            c = d = Number.Integer.Zero;
            n = 0;
            if (!TreeAnalyzer.TryGetPolynomial(expr, x, out var monomials) || monomials.Count != 2
                || !monomials.TryGetValue(EInteger.Zero, out var constant))
                return false;
            foreach (var pair in monomials)
                if (!pair.Key.IsZero)
                {
                    if (!pair.Key.CanFitInInt32() || pair.Value.ContainsNode(x))
                        return false;
                    n = pair.Key.ToInt32Checked();
                    d = pair.Value;
                }
            c = constant;
            return !c.ContainsNode(x) && n >= 1;
        }

        /// <summary>
        /// A root of a quadratic binomial beside another, <c>1/((A + B x^2)^(1/3) (C + D x^2))</c>
        /// with <c>B C + 3 A D = 0</c> or <c>B C - 9 A D = 0</c>, and
        /// <c>1/((A + B x^2)^(1/4) (C + D x^2))</c> with <c>B C - 2 A D = 0</c>: the ratios at which
        /// the integral, elliptic otherwise, is elementary, in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// With <c>y</c> the root, <c>a = A^(1/3)</c>, and <c>q = sqrt(B/A)</c> or <c>sqrt(-B/A)</c> by its sign:
        /// <code>
        /// B C + 3 A D = 0, B/A &gt; 0:  -2^(1/3) q/(4 a D) (atan(a q x/(a + 2^(1/3) y)) - atan(q x)/3
        ///                                - (artanh(sqrt(3) (a - 2^(1/3) y)/(a q x)) + artanh(sqrt(3)/(q x)))/sqrt(3))
        ///                  B/A &lt; 0:   2^(1/3) q/(4 a D) (artanh(a q x/(a + 2^(1/3) y)) - artanh(q x)/3
        ///                                + (atan(sqrt(3) (a - 2^(1/3) y)/(a q x)) + atan(sqrt(3)/(q x)))/sqrt(3))
        /// B C - 9 A D = 0, B/A &gt; 0:   q/(12 a D) (atan((a - y)^2/(3 a^2 q x)) + atan(q x/3)
        ///                                - sqrt(3) artanh(sqrt(3) (a - y)/(a q x)))
        ///                  B/A &lt; 0:   q/(12 a D) (artanh((a - y)^2/(3 a^2 q x)) - artanh(q x/3)
        ///                                - sqrt(3) atan(sqrt(3) (a - y)/(a q x)))
        /// </code>
        /// and for the fourth root, with <c>s = sqrt(A + B x^2)</c> and <c>r = sqrt(|B|)</c>, times
        /// <c>B/D</c>, which takes <c>C + D x^2</c> to <c>2 A + B x^2</c>:
        /// <code>
        /// A &gt; 0, B &gt; 0:  -(atan(A^(3/4) (1 + s/sqrt(A))/(x y r)) + artanh(A^(3/4) (1 - s/sqrt(A))/(x y r)))/(2 A^(3/4) r)
        /// A &gt; 0, B &lt; 0:   (atan(A^(3/4) (1 - s/sqrt(A))/(x y r)) + artanh(A^(3/4) (1 + s/sqrt(A))/(x y r)))/(2 A^(3/4) r)
        /// A &lt; 0:          -(atan(u) + artanh(u))/(2 (-A)^(3/4) sqrt(2) r),   u = x r/((-A)^(1/4) y sqrt(2))
        /// </code>
        /// Rubi's, from its 1.1.2.3, written for any constants with the ratio; each was checked by
        /// differentiating it at points in every sign case. The derivative of each uses only that
        /// the roots are roots, so for a sign that is a symbol's both forms are given, each where
        /// it holds.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// <para>
        /// <c>x^2/((A + B x^2)^(3/4) (C + D x^2))</c> at the same ratio is the same two functions'
        /// difference where the quarter power is their sum, with another constant -- Rubi's
        /// 1.1.2.4, <c>x^2/((a - b x^2)^(3/4) (2 a - b x^2))</c>, which was declined:
        /// <code>
        /// A &gt; 0, B &gt; 0:  -(atan(A^(3/4) (1 + s/sqrt(A))/(x y r)) - artanh(A^(3/4) (1 - s/sqrt(A))/(x y r)))/(A^(1/4) r^3)
        /// A &gt; 0, B &lt; 0:   (atan(A^(3/4) (1 - s/sqrt(A))/(x y r)) - artanh(A^(3/4) (1 + s/sqrt(A))/(x y r)))/(A^(1/4) r^3)
        /// A &lt; 0:           (atan(u) - artanh(u))/((-A)^(1/4) sqrt(2) r^3)
        /// </code>
        /// each times <c>B/D</c> as before, the constants solved for from the two functions'
        /// derivatives and checked at points in every sign case.
        /// </para>
        /// </remarks>
        internal static Entity? SolveAnEllipticLookingQuotientOfBinomials(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            // Or c x^2 above, beside a three-quarter power below.
            var squareAbove = false;
            Entity constant = numerator;
            if (numerator.ContainsNode(x))
            {
                if (!TreeAnalyzer.TryGetPolynomial(numerator, x, out var above) || above.Count != 1
                    || !above.TryGetValue(EInteger.FromInt32(2), out var squared) || squared.ContainsNode(x))
                    return null;
                squareAbove = true;
                constant = squared;
            }
            Entity? radicand = null;
            var order = 0;
            Entity? other = null;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                    constant = constant / factor;
                else if (radicand is null && factor is Powf(var @base, Number.Rational power)
                    && (squareAbove
                        ? power.ERational.Equals(ERational.Create(3, 4))
                        : power.ERational.Numerator.Equals(EInteger.One)
                          && (power.ERational.Denominator.Equals(EInteger.FromInt32(3)) || power.ERational.Denominator.Equals(EInteger.FromInt32(4)))))
                {
                    radicand = @base;
                    order = power.ERational.Denominator.ToInt32Unchecked();
                }
                else if (other is null && factor is not Powf)
                    other = factor;
                else
                    return null;
            }
            if (radicand is null || other is null || EvenQuadratic(radicand) is not var (a0, b0) || EvenQuadratic(other) is not var (c0, d0))
                return null;
            var (A, B, C, D) = (a0, b0, c0, d0);
            var y = MathS.Pow(radicand, Number.Rational.Create(1, order));
            Entity? answer = null;
            if (order == 3 && VanishesIdentically(B * C + 3 * A * D))
            {
                var a = MathS.Pow(A, Number.Rational.Create(1, 3));
                var cube = MathS.Pow(2, Number.Rational.Create(1, 3));
                var three = MathS.Sqrt(3);
                var quarter = LowestOverTheSymbols(1 / (4 * D));
                Entity Positive(Entity q) => -quarter * cube * q / a * (MathS.Arctan(a * q * x / (a + cube * y)) - MathS.Arctan(q * x) / 3
                    - (MathS.Hyperbolic.Artanh(three * (a - cube * y) / (a * q * x)) + MathS.Hyperbolic.Artanh(three / (q * x))) / three);
                Entity Negative(Entity q) => quarter * cube * q / a * (MathS.Hyperbolic.Artanh(a * q * x / (a + cube * y)) - MathS.Hyperbolic.Artanh(q * x) / 3
                    + (MathS.Arctan(three * (a - cube * y) / (a * q * x)) + MathS.Arctan(three / (q * x))) / three);
                var ratio = LowestOverTheSymbols(B / A);
                answer = BySign(ratio, Positive(MathS.Sqrt(ratio)), Negative(MathS.Sqrt(LowestOverTheSymbols(-ratio))));
            }
            else if (order == 3 && VanishesIdentically(B * C - 9 * A * D))
            {
                var a = MathS.Pow(A, Number.Rational.Create(1, 3));
                var three = MathS.Sqrt(3);
                var twelfth = LowestOverTheSymbols(1 / (12 * D));
                Entity Positive(Entity q) => twelfth * q / a * (MathS.Arctan(MathS.Pow(a - y, 2) / (3 * MathS.Pow(a, 2) * q * x)) + MathS.Arctan(q * x / 3)
                    - three * MathS.Hyperbolic.Artanh(three * (a - y) / (a * q * x)));
                Entity Negative(Entity q) => twelfth * q / a * (MathS.Hyperbolic.Artanh(MathS.Pow(a - y, 2) / (3 * MathS.Pow(a, 2) * q * x)) - MathS.Hyperbolic.Artanh(q * x / 3)
                    - three * MathS.Arctan(three * (a - y) / (a * q * x)));
                var ratio = LowestOverTheSymbols(B / A);
                answer = BySign(ratio, Positive(MathS.Sqrt(ratio)), Negative(MathS.Sqrt(LowestOverTheSymbols(-ratio))));
            }
            else if (order == 4 && squareAbove && VanishesIdentically(B * C - 2 * A * D))
            {
                var s = MathS.Sqrt(radicand);
                var threeQuarters = Number.Rational.Create(3, 4);
                var quarter = Number.Rational.Create(1, 4);
                Entity BothPositive()
                {
                    var r = MathS.Sqrt(B);
                    return -(MathS.Arctan(MathS.Pow(A, threeQuarters) * (1 + s / MathS.Sqrt(A)) / (x * y * r))
                        - MathS.Hyperbolic.Artanh(MathS.Pow(A, threeQuarters) * (1 - s / MathS.Sqrt(A)) / (x * y * r))) / (MathS.Pow(A, quarter) * MathS.Pow(r, 3));
                }
                Entity SlopeNegative()
                {
                    var r = MathS.Sqrt(-B);
                    return (MathS.Arctan(MathS.Pow(A, threeQuarters) * (1 - s / MathS.Sqrt(A)) / (x * y * r))
                        - MathS.Hyperbolic.Artanh(MathS.Pow(A, threeQuarters) * (1 + s / MathS.Sqrt(A)) / (x * y * r))) / (MathS.Pow(A, quarter) * MathS.Pow(r, 3));
                }
                Entity ConstantNegative()
                {
                    var r = MathS.Sqrt(B);
                    var u = x * r / (MathS.Pow(-A, quarter) * y * MathS.Sqrt(2));
                    return (MathS.Arctan(u) - MathS.Hyperbolic.Artanh(u)) / (MathS.Pow(-A, quarter) * MathS.Sqrt(2) * MathS.Pow(r, 3));
                }
                var toTheRatio = LowestOverTheSymbols(B / D);
                var form = BySigns(A, B, BothPositive(), SlopeNegative(), ConstantNegative());
                answer = toTheRatio == Number.Integer.One ? form : toTheRatio * form;
            }
            else if (order == 4 && !squareAbove && VanishesIdentically(B * C - 2 * A * D))
            {
                var s = MathS.Sqrt(radicand);
                var threeQuarters = Number.Rational.Create(3, 4);
                Entity BothPositive()
                {
                    var r = MathS.Sqrt(B);
                    return -(MathS.Arctan(MathS.Pow(A, threeQuarters) * (1 + s / MathS.Sqrt(A)) / (x * y * r))
                        + MathS.Hyperbolic.Artanh(MathS.Pow(A, threeQuarters) * (1 - s / MathS.Sqrt(A)) / (x * y * r))) / (2 * MathS.Pow(A, threeQuarters) * r);
                }
                Entity SlopeNegative()
                {
                    var r = MathS.Sqrt(-B);
                    return (MathS.Arctan(MathS.Pow(A, threeQuarters) * (1 - s / MathS.Sqrt(A)) / (x * y * r))
                        + MathS.Hyperbolic.Artanh(MathS.Pow(A, threeQuarters) * (1 + s / MathS.Sqrt(A)) / (x * y * r))) / (2 * MathS.Pow(A, threeQuarters) * r);
                }
                Entity ConstantNegative()
                {
                    var r = MathS.Sqrt(B);
                    var u = x * r / (MathS.Pow(-A, Number.Rational.Create(1, 4)) * y * MathS.Sqrt(2));
                    return -(MathS.Arctan(u) + MathS.Hyperbolic.Artanh(u)) / (2 * MathS.Pow(-A, threeQuarters) * MathS.Sqrt(2) * r);
                }
                var toTheRatio = LowestOverTheSymbols(B / D);
                var form = BySigns(A, B, BothPositive(), SlopeNegative(), ConstantNegative());
                answer = toTheRatio == Number.Integer.One ? form : toTheRatio * form;
            }
            return answer is null ? null : (constant * answer).InnerSimplified;

            // A + B x^2, both nonzero.
            (Entity, Entity)? EvenQuadratic(Entity polynomial)
            {
                if (!TreeAnalyzer.TryGetPolynomial(polynomial, x, out var terms) || terms.Count != 2
                    || !terms.TryGetValue(EInteger.Zero, out var free) || !terms.TryGetValue(EInteger.FromInt32(2), out var square)
                    || free.ContainsNode(x) || square.ContainsNode(x) || VanishesIdentically(free) || VanishesIdentically(square))
                    return null;
                return (free, square);
            }
        }

        /// <summary>
        /// A <b>binomial differential</b> <c>x^m (a + b x^n)^(p/q)</c>, in the two of Chebyshev's
        /// three cases that are not a whole power: <c>(m + 1)/n</c> whole, or
        /// <c>(m + 1)/n + p/q</c> whole.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>x^2 sqrt(1 + x^3)</c> came out and <c>x^5 sqrt(1 + x^3)</c> did not, and the two are
        /// the same substitution. Under <c>u = (a + b x^n)^(1/q)</c> the first leaves a monomial
        /// in <c>u</c>, which the general substitution finds because <c>x^(n-1)</c> is <c>du</c>
        /// up to a constant; the second leaves a <b>polynomial</b>, which it does not, because
        /// what multiplies <c>du</c> there is <c>x^3</c> rather than a constant.
        /// </para>
        /// <para>
        /// Writing <c>s = (m + 1)/n</c> and substituting:
        /// </para>
        /// <code>
        ///     x^n = (u^q - a)/b       x^m dx = (q/(n b)) ((u^q - a)/b)^(s-1) u^(q-1) du
        ///     int x^m (a + b x^n)^(p/q) dx = (q/(n b)) int ((u^q - a)/b)^(s-1) u^(p+q-1) du
        /// </code>
        /// <para>
        /// which is a polynomial in <c>u</c> when <c>s</c> is a whole number of at least one,
        /// expanded by the binomial theorem and integrated term by term; and a <b>rational
        /// function</b> of <c>u</c> when <c>s</c> is a whole number of at most zero, which the
        /// rational integrator answers — <c>sqrt(1 + x^3)/x</c> is <c>(2/3) int u^2/(u^2 - 1) du</c>,
        /// and <c>1/(x sqrt(1 - x^3))</c> is <c>(2/3) int 1/(u^2 - 1) du</c>. Both were declined
        /// for <c>s = 0</c>, which the rule read as "not a polynomial" and left at that.
        /// </para>
        /// <para>
        /// <b>The third case comes down to the second.</b> Where <c>s + p/q</c> is whole instead,
        /// <c>x = 1/y</c> turns <c>x^m (a + b x^n)^(p/q) dx</c> into
        /// <c>-y^m' (b + a y^n)^(p/q) dy</c> with <c>m' = -m - 2 - n p/q</c> and
        /// <c>(m' + 1)/n = -(s + p/q)</c>, whole — so it is the second case in <c>y</c>, with the
        /// roles of <c>a</c> and <c>b</c> exchanged. Its <c>u</c>, whose <c>q</c>-th power is
        /// <c>b + a/x^n</c>, is put back as <c>(a + b x^n)^(1/q)/x^(n/q)</c>, which has that power
        /// at every <c>x</c>. <c>(b + a/x^n)^(1/q)</c> is the same number for a positive <c>x</c>,
        /// and for a negative one only under an odd root, which is real here:
        /// <c>1/(1 + x^4)^(5/4)</c> came out as <c>1/(1 + 1/x^4)^(1/4)</c>, an even function
        /// whose derivative is the integrand's negative for every negative <c>x</c>, where
        /// <c>x/(1 + x^4)^(1/4)</c> is right on the whole line.
        /// <c>x^6 (3 + 4x^4)^(1/4)</c> and <c>(x^3 - 1)/(2 + x^3)^(1/3)</c> are this. Chebyshev
        /// proved there is no fourth case: outside these the integrand has no elementary
        /// antiderivative at all, which is worth knowing before anyone goes looking.
        /// </para>
        /// <para>
        /// The theorem is about the exponents, and <c>m</c> and <c>n</c> are read as rationals and
        /// <c>a</c> and <c>b</c> as anything free of the variable, since neither substitution
        /// reads the coefficients: <c>x^(7/3) (a + b x^2)^(1/3)</c> is the third case. A power of
        /// a multiple of the variable, <c>(c x)^(5/2)</c>, is read as <c>x^(5/2)</c> times
        /// <c>(c x)^(5/2)/x^(5/2)</c>, whose derivative is zero: it is <c>c^(5/2)</c> for a
        /// positive <c>c x</c> and constant on either side of zero whatever the signs, so it
        /// stands outside the integral as written. Rubi's 1.1.2.2 and 1.1.3.2,
        /// <c>(c x)^m (a + b x^n)^p</c>, are written so.
        /// </para>
        /// <para>
        /// Where <c>m + 1 + n (p/q + 1)</c> is zero, a case of the third, the answer is one product
        /// of powers, <c>x^(m+1) (a + b x^n)^(p/q+1)/(a (m + 1))</c>, and is given as that.
        /// <see cref="SolveAsTheDerivativeOfAProductOfPowers"/> finds it too, but is asked at the
        /// top and one level below only, and below that the third case wrote it out through the
        /// rational integrator, many terms where one will do.
        /// </para>
        /// <para>
        /// Here with numbers only. With a symbol in <c>a</c>, <c>b</c> or the multiple it is
        /// <see cref="SolveABinomialDifferentialWithSymbols"/>, asked after the rules written for
        /// a root of a quadratic and for a rational function of <c>x^n</c> beside the root of its
        /// binomial, which answer what they share with this more shortly: asked first,
        /// <c>1/(a - b x^4)^(1/4)</c> came out as two logarithms and two arctangents where
        /// <see cref="SolveByDividingByTheRoot"/> gives two arctangents.
        /// </para>
        /// <para>
        /// Closed in one step: the polynomial case is a sum of powers, and the rational case
        /// goes to the rational integrator directly, not back into the chain -- which is what
        /// lets it be volunteered at any depth rather than asked at the top only
        /// (<a href="https://github.com/asc-community/AngouriMath/issues/1265">#1265</a>):
        /// <c>tan(x)/sqrt(1 + sec(x)^3)</c> is <c>1/(u sqrt(1 + u^3))</c> under <c>u = sec(x)</c>,
        /// one level down, and was declined there.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveABinomialDifferential(Entity expr, Entity.Variable x)
            => SolveABinomialDifferential(expr, x, withSymbols: false);

        /// <summary>
        /// <see cref="SolveABinomialDifferential(Entity, Entity.Variable)"/> where a symbol stands
        /// in <c>a</c>, <c>b</c> or the multiple, and nowhere else: what the first asking left
        /// for the rules after it, and they declined.
        /// </summary>
        internal static Entity? SolveABinomialDifferentialWithSymbols(Entity expr, Entity.Variable x)
            => SolveABinomialDifferential(expr, x, withSymbols: true);

        private static Entity? SolveABinomialDifferential(Entity expr, Entity.Variable x, bool withSymbols)
        {
            if (!TryReadABinomialDifferential(expr, x, out var power, out var exponent,
                    out var inner, out var free, out var leading, out var factor))
                return null;
            if (withSymbols != (free.Vars.Any() || leading.Vars.Any() || factor.Vars.Any(symbol => symbol != x)))
                return null;
            var u = Variable.CreateUnique(expr, "u_binom");
            var bracket = (free + leading * MathS.Pow(x, Number.Rational.Create(inner))).InnerSimplified;
            var root = MathS.Pow(bracket, Number.Rational.Create(EInteger.One, exponent.Denominator));

            // m + 1 + n (p/q + 1) = 0, a case of the third with one term for its answer:
            // (x^(m+1) (a + b x^n)^(p/q+1))' is (m + 1) a x^m (a + b x^n)^(p/q) exactly there.
            var raisedPower = power.Add(ERational.One);
            if (!raisedPower.IsZero && raisedPower.Add(inner.Multiply(exponent.Add(ERational.One))).IsZero)
                return (factor * MathS.Pow(x, Number.Rational.Create(raisedPower))
                        * MathS.Pow(bracket, Number.Rational.Create(exponent.Add(ERational.One)))
                        / (free * Number.Rational.Create(raisedPower))).InnerSimplified;

            // The second case: s = (m + 1)/n whole.
            var s = raisedPower.Divide(inner);
            if (s.IsInteger())
                return IntegrateABinomialDifferentialInTheSecondCase(
                    power, inner, exponent, free, leading, u, root, factor);

            // The third: s + p/q whole, taken to the second by x = 1/y.
            if (!s.Add(exponent).IsInteger())
                return null;
            var reflectedPower = power.Negate().Subtract(ERational.FromInt32(2)).Subtract(inner.Multiply(exponent));
            var back = root / MathS.Pow(x, Number.Rational.Create(inner.Divide(ERational.FromEInteger(exponent.Denominator))));
            if (IntegrateABinomialDifferentialInTheSecondCase(
                    reflectedPower, inner, exponent, leading, free, u, back, Number.Integer.MinusOne) is not { } reflected)
                return null;
            return (factor * reflected).InnerSimplified;
        }

        /// <summary>
        /// <c>int factor * v^m (a + b v^n)^(p/q) dv</c> with <c>(m + 1)/n</c> whole, in
        /// <paramref name="u"/> and then written as <paramref name="back"/>, anything whose
        /// <c>q</c>-th power is <c>a + b v^n</c>: a polynomial in <c>u</c> expanded term by term for
        /// <c>s >= 1</c>, and a rational function of <c>u</c> handed to the rational integrator for
        /// <c>s &lt;= 0</c>.
        /// </summary>
        private static Entity? IntegrateABinomialDifferentialInTheSecondCase(
            ERational power, ERational inner, ERational exponent, Entity free, Entity leading,
            Entity.Variable u, Entity back, Entity factor)
        {
            var whole = power.Add(ERational.One).Divide(inner);
            if (!whole.IsInteger())
                return null;
            var wholeInteger = whole.ToEIntegerIfExact();
            if (!wholeInteger.CanFitInInt32())
                return null;
            var s = wholeInteger.ToInt32Checked();
            var q = exponent.Denominator.ToInt32Checked();
            var p = exponent.Numerator.ToInt32Checked();
            var a = free;
            var b = leading;
            var outside = Number.Integer.Create(q) / (Number.Rational.Create(inner) * ToThe(b, s));

            if (s < 1)
            {
                // (q/(n b^s)) int u^(p+q-1) / (u^q - a)^(1-s) du: a rational function of u.
                var overPower = 1 - s;
                Entity denominator = overPower == 1 ? MathS.Pow(u, q) - a : MathS.Pow(MathS.Pow(u, q) - a, overPower);
                Entity numerator = p + q - 1 == 0 ? Number.Integer.One : MathS.Pow(u, p + q - 1);
                // To the rational integrator directly rather than back into the chain, so that
                // this closes in one step wherever it is asked -- below the secant substitution
                // for `tan(x)/sqrt(1 + sec(x)^3)`, which is `1/(u sqrt(1 + u^3))` one level down
                // -- instead of opening the search that had it confined to the top level.
                var rational = (numerator / denominator).InnerSimplified;
                if ((IntegralPatterns.TryStandardIntegrals(rational, u)
                     ?? SolveByPartialFractions(rational, u, integrateByParts: false)
                     ?? SolveByRothsteinTrager(rational, u)) is not { } inU)
                    return null;
                return (factor * outside * inU.Substitute(u, back)).InnerSimplified;
            }

            // (q/(n b^s)) * int (u^q - a)^(s-1) u^(p+q-1) du, the binomial expanded.
            Entity total = 0;
            var binomial = EInteger.One;
            for (var i = 0; i <= s - 1; i++)
            {
                // Term i of (u^q - a)^(s-1) is C(s-1, i) u^(q i) (-a)^(s-1-i).
                var raised = q * i + p + q;
                if (raised == 0)
                    return null;   // the power rule would divide by zero; not a polynomial after all
                total += Number.Integer.Create(binomial)
                       * ToThe(-a, s - 1 - i)
                       * MathS.Pow(u, Number.Integer.Create(raised)) / Number.Integer.Create(raised);
                binomial = binomial * (s - 1 - i) / (i + 1);
            }
            return (factor * outside * total.Substitute(u, back)).InnerSimplified;

            // The zeroth power as the one it is: with a symbol in the base, `b^0` is simplified
            // to 1 provided `b` is not zero, a condition the answer has no use for.
            static Entity ToThe(Entity @base, int power)
                => power == 0 ? Number.Integer.One : MathS.Pow(@base, Number.Integer.Create(power));
        }

        /// <summary>
        /// Reads <paramref name="expr"/> as a multiple of <c>x^m (a + b x^n)^(p/q)</c>, with
        /// <c>m</c> and <c>n</c> rational, <c>q</c> above one, <c>n</c> neither zero nor one, and
        /// the multiple, <c>a</c> and <c>b</c> free of the variable -- or the multiple
        /// <c>(c x^k)^r/x^(k r)</c>, whose derivative is zero, of a power of a monomial.
        /// </summary>
        /// <remarks>
        /// A whole exponent on the bracket is a polynomial and wants expanding rather than this;
        /// <c>n = 1</c> is a radical of something linear, which
        /// <see cref="SolveByLinearRadicalSubstitution"/> answers in its own terms and more
        /// shortly.
        /// </remarks>
        private static bool TryReadABinomialDifferential(
            Entity expr, Entity.Variable x, out ERational power, out ERational exponent,
            out ERational inner, out Entity free, out Entity leading, out Entity factor)
        {
            power = ERational.Zero;
            exponent = ERational.Zero;
            inner = ERational.Zero;
            free = 0;
            leading = 0;
            factor = 1;

            Entity? bracket = null;
            var exponentFound = ERational.Zero;
            var powerFound = ERational.Zero;
            Entity constantFactor = 1;
            if (!Read(expr, 1) || bracket is null)
                return false;

            var lowest = exponentFound.ToLowestTerms();
            if (lowest.Denominator.Equals(EInteger.One)
                || !lowest.Numerator.CanFitInInt32() || !lowest.Denominator.CanFitInInt32())
                return false;

            // `a + b x^n`: one term free of the variable and one monomial in it.
            Entity? constantPart = null;
            Entity? monomial = null;
            foreach (var term in Sumf.LinearChildren(bracket))
                if (!term.ContainsNode(x))
                    constantPart = constantPart is null ? term : constantPart + term;
                else if (monomial is null)
                    monomial = term;
                else
                    return false;
            if (constantPart is null || monomial is null)
                return false;
            if (!TryReadAMonomial(monomial, x, out var degree, out var coefficient)
                || degree.IsZero || degree.CompareTo(ERational.One) == 0)
                return false;
            if (VanishesIdentically(constantPart) || VanishesIdentically(coefficient))
                return false;

            power = powerFound;
            exponent = lowest;
            inner = degree;
            // A number as the number it is, so that the answer is written as it was for numbers.
            free = constantPart.Evaled is Number.Rational freeValue ? freeValue : constantPart.InnerSimplified;
            leading = coefficient.Evaled is Number.Rational leadingValue ? leadingValue : coefficient.InnerSimplified;
            factor = constantFactor;
            return true;

            bool Read(Entity node, int multiplicity)
            {
                switch (node)
                {
                    case var constant when !constant.ContainsNode(x):
                        constantFactor = multiplicity > 0
                            ? constantFactor * MathS.Pow(constant, multiplicity)
                            : constantFactor / MathS.Pow(constant, -multiplicity);
                        return true;
                    case Variable v when v == x:
                        powerFound = powerFound.Add(ERational.FromInt32(multiplicity));
                        return true;
                    case Mulf(var left, var right):
                        return Read(left, multiplicity) && Read(right, multiplicity);
                    case Divf(var above, var below):
                        return Read(above, multiplicity) && Read(below, -multiplicity);
                    case Powf(var @base, Number.Rational raised)
                        when TryReadAMonomial(@base, x, out var ofTheBase, out _):
                        // x^r, or (c x^k)^r as x^(k r) times (c x^k)^r/x^(k r): that is
                        // c^r for a positive c x^k, and constant on either side of zero whatever
                        // the signs, so it stands outside as written.
                        var raisedHere = raised.ERational.Multiply(ERational.FromInt32(multiplicity));
                        var ofTheVariable = ofTheBase.Multiply(raised.ERational);
                        powerFound = powerFound.Add(ofTheBase.Multiply(raisedHere));
                        if (@base != x)
                        {
                            var standingOutside = node / MathS.Pow(x, Number.Rational.Create(ofTheVariable));
                            constantFactor = multiplicity > 0
                                ? constantFactor * MathS.Pow(standingOutside, multiplicity)
                                : constantFactor / MathS.Pow(standingOutside, -multiplicity);
                        }
                        return true;
                    case Powf(var @base, Number.Rational raised):
                        if (bracket is not null && bracket != @base)
                            return false;
                        bracket = @base;
                        exponentFound = exponentFound.Add(ERational.FromInt32(multiplicity).Multiply(raised.ERational));
                        return true;
                    case Sumf or Minusf:
                        if (bracket is not null && bracket != node)
                            return false;
                        bracket = node;
                        exponentFound = exponentFound.Add(ERational.FromInt32(multiplicity));
                        return true;
                    default:
                        return false;
                }
            }
        }

        /// <summary>
        /// Reads <c>c * x^n</c>, giving the degree, any rational, and the coefficient, anything
        /// free of the variable.
        /// </summary>
        private static bool TryReadAMonomial(Entity term, Entity.Variable x, out ERational degree, out Entity coefficient)
        {
            degree = ERational.Zero;
            coefficient = 1;
            switch (term)
            {
                case Variable v when v == x:
                    degree = ERational.One;
                    return true;
                case Powf(var @base, Number.Rational raised) when @base == x:
                    degree = raised.ERational;
                    return true;
                case Mulf(var left, var right) when !left.ContainsNode(x):
                    if (!TryReadAMonomial(right, x, out degree, out var fromRight))
                        return false;
                    coefficient = left * fromRight;
                    return true;
                case Mulf(var left, var right) when !right.ContainsNode(x):
                    if (!TryReadAMonomial(left, x, out degree, out var fromLeft))
                        return false;
                    coefficient = right * fromLeft;
                    return true;
                case Divf(var above, var below) when !below.ContainsNode(x):
                    if (!TryReadAMonomial(above, x, out degree, out var fromAbove))
                        return false;
                    coefficient = fromAbove / below;
                    return true;
                case Divf(var above, var below) when !above.ContainsNode(x):
                    if (!TryReadAMonomial(below, x, out var belowDegree, out var fromBelow))
                        return false;
                    degree = belowDegree.Negate();
                    coefficient = above / fromBelow;
                    return true;
                default:
                    return false;
            }
        }

        /// <summary>
        /// A polynomial times an exponential of a linear over a whole power of a linear:
        /// <c>P(x) F^(a + b x)/(c + d x)^n</c>, onto the exponential integral. Under
        /// <c>u = c + d x</c>, <c>F^(a + b x)</c> is <c>F^(a - b c/d) e^(k u)</c> with <c>k = b ln F/d</c>,
        /// and <c>P</c> a polynomial in <c>u</c>, so every term is <c>u^m e^(k u)</c>: elementary for
        /// <c>m >= 0</c>, <c>Ei(k u)</c> for <c>m = -1</c>, and below that
        /// <c>e^(k u) u^(m + 1)/(m + 1) - k/(m + 1)</c> times the one above, by parts. Rubi's 2.3,
        /// <c>F^(c (a + b x))/(d + e x)^n</c> and <c>e^(-a - b x) (a + b x)^3/x^n</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// Only where some term's power is negative: without one the product is elementary, and the
        /// rules for a polynomial times an exponential answer it.
        /// </remarks>
        internal static Entity? SolveAnExponentialOfALinearOverAPowerOfALinear(Entity expr, Entity.Variable x)
        {
            // An exponential of the variable and a quotient, before anything is read.
            if (expr is not Divf || AnExponentialOfALinear(expr, x) is not { } exponential)
                return null;
            Entity constant = Number.Integer.One;
            Entity? linear = null;
            var power = 0;
            Entity? polynomial = null;
            var sawTheExponential = false;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (!underneath && !sawTheExponential && factor == exponential)
                {
                    sawTheExponential = true;
                    continue;
                }
                // The linear, or a whole power of it, below the bar.
                if (underneath)
                {
                    var (candidate, k) = factor is Powf(var below, Number.Integer n) && n.EInteger.Sign > 0 && n.EInteger.CanFitInInt32()
                        ? (below, n.EInteger.ToInt32Checked()) : (factor, 1);
                    if (linear is not null && linear != candidate
                        || !TreeAnalyzer.TryGetPolyLinear(candidate, x, out var slopeOfIt, out _) || TreeAnalyzer.IsZero(slopeOfIt))
                        return null;
                    linear = candidate;
                    power += k;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (!sawTheExponential || linear is null || power > 12
                || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var d, out var c)
                || !TreeAnalyzer.TryGetPolyLinear(exponential.Exponent, x, out var b, out var a) || TreeAnalyzer.IsZero(b))
                return null;
            var u = Variable.CreateUnique(expr, "u");
            var inU = polynomial is null ? Number.Integer.One : polynomial.Substitute(x, (u - c) / d);
            if (!TreeAnalyzer.TryGetPolynomial(inU, u, out var powers) || powers.Keys.All(degree => degree.CompareTo(EInteger.FromInt32(power)) >= 0))
                return null;
            var logarithmOfTheBase = exponential.Base == MathS.e ? (Entity)Number.Integer.One : MathS.Ln(exponential.Base);
            var rate = (b * logarithmOfTheBase / d).InnerSimplified;
            var exponentialOfU = MathS.Pow(MathS.e, rate * u);
            Entity sum = Number.Integer.Zero, ei = Number.Integer.Zero;
            foreach (var monomial in powers)
            {
                if (!monomial.Key.CanFitInInt32())
                    return null;
                var (elementary, eiCoefficient) = APowerTimesAnExponential(monomial.Key.ToInt32Checked() - power, rate, exponentialOfU, u);
                sum += monomial.Value * elementary;
                ei += monomial.Value * eiCoefficient;
            }
            // Where the exponential integrals cancel, the antiderivative is elementary, and the
            // exponential ansatz writes it shorter: e^x x/(1 + x)^2 is e^x/(1 + x).
            ei = ei.InnerSimplified;
            if (TreeAnalyzer.IsZero(ei))
                return null;
            var shifted = MathS.Pow(exponential.Base, (a - b * c / d).InnerSimplified);
            return Functions.PartialFractions.Bare((constant * shifted / d * (sum + ei * MathS.Ei(rate * u)).Substitute(u, linear)).InnerSimplified);
        }

        /// <summary>
        /// <c>int u^m e^(k u) du</c>, where <paramref name="exponential"/> is <c>e^(k u)</c>, as its
        /// elementary part and the coefficient of <c>Ei(k u)</c> in it:
        /// <c>e^(k u) sum_i (-1)^i m!/(m - i)! u^(m - i)/k^(i + 1)</c> for <c>m >= 0</c>, <c>Ei(k u)</c> for
        /// <c>m = -1</c>, and by parts toward it below that. Kept apart, so that where the
        /// coefficients of <c>Ei</c> cancel across the terms of a sum the answer is seen to be
        /// elementary, and left to the rules that write it shortest.
        /// </summary>
        private static (Entity Elementary, Entity EiCoefficient) APowerTimesAnExponential(int m, Entity k, Entity exponential, Entity.Variable u)
        {
            if (m == -1)
                return (Number.Integer.Zero, Number.Integer.One);
            if (m < -1)
            {
                // int u^m e^(k u) = u^(m + 1) e^(k u)/(m + 1) - k/(m + 1) int u^(m + 1) e^(k u)
                var (above, eiAbove) = APowerTimesAnExponential(m + 1, k, exponential, u);
                return (MathS.Pow(u, m + 1) * exponential / (m + 1) - k / (m + 1) * above, -k / (m + 1) * eiAbove);
            }
            Entity sum = Number.Integer.Zero;
            Entity falling = Number.Integer.One;
            for (var i = 0; i <= m; i++)
            {
                var term = falling * MathS.Pow(u, m - i) / MathS.Pow(k, i + 1);
                sum = i % 2 == 0 ? sum + term : sum - term;
                falling *= m - i;
            }
            return (exponential * sum, Number.Integer.Zero);
        }

        /// <summary>
        /// A sum of exponentials of the variable, times a polynomial, over a whole power of a
        /// linear: <c>P(x) sum_j c_j e^(r_j x)/(e + f x)^n</c>, which is how a polynomial in
        /// <c>sinh</c> and <c>cosh</c> of a linear arrives, onto the hyperbolic sine and cosine
        /// integrals. Under <c>u = e + f x</c> each term is <c>u^m e^(k u)</c>, the exponential
        /// integral's (<see cref="APowerTimesAnExponential"/>), and two of opposite rates pair:
        /// <c>A Ei(k u) + B Ei(-k u) = (A + B) Chi(k u) + (A - B) Shi(k u)</c>, since
        /// <c>Ei(y) + Ei(-y) = 2 Chi(y)</c> and <c>Ei(y) - Ei(-y) = 2 Shi(y)</c> for <c>y > 0</c>, and
        /// for <c>y &lt; 0</c> up to a constant. A rate of 0, which an even power leaves, is a power
        /// of <c>u</c> alone. Rubi's 6.1.1, <c>(c + d x)^m (a + b sinh(e + f x))^n</c>, with
        /// <c>m</c> negative.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// After <see cref="SolveAnExponentialOfALinearOverAPowerOfALinear"/>, which answers one
        /// exponential alone; and only where an integral is left.
        /// </remarks>
        internal static Entity? SolveAHyperbolicOfALinearOverAPowerOfALinear(Entity expr, Entity.Variable x)
        {
            if (expr is not (Divf or Mulf) || !HasASumOfExponentials(expr, x))
                return null;
            Entity constant = Number.Integer.One;
            Entity? linear = null;
            var power = 0;
            Entity? polynomial = null;
            Entity? exponentials = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                var (@base, exponent) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath)
                    exponent = -exponent;
                if (exponent < 0 && TreeAnalyzer.TryGetPolyLinear(@base, x, out var slopeOfIt, out _) && !TreeAnalyzer.IsZero(slopeOfIt))
                {
                    if (linear is not null && linear != @base)
                        return null;
                    linear = @base;
                    power -= exponent;
                    continue;
                }
                if (underneath)
                    return null;
                if (factor.Nodes.Any(node => node is Powf(var b, var e) && !b.ContainsNode(x) && e.ContainsNode(x)))
                {
                    exponentials = exponentials is null ? factor : exponentials * factor;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (exponentials is null || linear is null || power > 12 || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var f, out var e0))
                return null;
            // The exponentials as a sum of c e^(r x), gathered by the rate r.
            var rates = new List<(Entity Rate, Entity Coefficient)>();
            foreach (var term in Sumf.LinearChildren(exponentials.Expand()))
            {
                if (ReadAnExponentialTerm(term, x) is not { } read)
                    return null;
                // The same rate may be written two ways, `2 (-b)` and `-2 b`.
                var at = rates.FindIndex(pair => pair.Rate == read.Rate
                    || pair.Rate.Vars.Any() && TreeAnalyzer.IsZero(Functions.PartialFractions.Bare((pair.Rate - read.Rate).Simplify())));
                if (at < 0)
                    rates.Add(read);
                else
                    rates[at] = (read.Rate, rates[at].Coefficient + read.Coefficient);
            }
            var u = Variable.CreateUnique(expr, "u");
            var inU = polynomial is null ? Number.Integer.One : polynomial.Substitute(x, (u - e0) / f);
            if (!TreeAnalyzer.TryGetPolynomial(inU, u, out var powers) || powers.Keys.All(degree => degree.CompareTo(EInteger.FromInt32(power)) >= 0)
                || powers.Keys.Any(degree => !degree.CanFitInInt32()))
                return null;
            Entity sum = Number.Integer.Zero;
            // The constant in front goes into each coefficient, so that the numbers fold.
            var overall = (constant / f).InnerSimplified;
            // The coefficient of Ei(k u) for each rate k in u, to be paired.
            var integrals = new List<(Entity Rate, Entity Coefficient)>();
            foreach (var (rate, coefficientOfTheRate) in rates)
            {
                var coefficient = (overall * coefficientOfTheRate).InnerSimplified;
                if (TreeAnalyzer.IsZero(rate))
                {
                    // The terms of rate 0 come from several products and may cancel, as in
                    // `cosh(y) sinh(y)^3`, where `e^(2 a) e^(-2 a)` has to be seen to be 1.
                    var constantPart = Functions.PartialFractions.Bare(coefficient.Simplify());
                    if (TreeAnalyzer.IsZero(constantPart))
                        continue;
                    foreach (var monomial in powers)
                    {
                        var m = monomial.Key.ToInt32Checked() - power;
                        sum += constantPart * monomial.Value * (m == -1 ? MathS.Ln(u) : MathS.Pow(u, m + 1) / (m + 1));
                    }
                    continue;
                }
                // e^(r x) = e^(-r e/f) e^(k u) with k = r/f.
                var k = (rate / f).InnerSimplified;
                var shifted = (coefficient * MathS.Pow(MathS.e, (-rate * e0 / f).InnerSimplified)).InnerSimplified;
                var exponentialOfU = MathS.Pow(MathS.e, k * u);
                Entity elementary = Number.Integer.Zero, ei = Number.Integer.Zero;
                foreach (var monomial in powers)
                {
                    var (below, eiBelow) = APowerTimesAnExponential(monomial.Key.ToInt32Checked() - power, k, exponentialOfU, u);
                    elementary += monomial.Value * below;
                    ei += monomial.Value * eiBelow;
                }
                sum += shifted * elementary;
                ei = (shifted * ei).InnerSimplified;
                if (!TreeAnalyzer.IsZero(ei))
                    integrals.Add((k, ei));
            }
            if (integrals.Count == 0)
                return null;
            // Pairs of opposite rates as Chi and Shi, the positive rate written.
            while (integrals.Count > 0)
            {
                var (k, a) = integrals[0];
                integrals.RemoveAt(0);
                // Simplified, since `d/f` and `-d/f` do not cancel inner-simplified.
                var opposite = integrals.FindIndex(pair => TreeAnalyzer.IsZero(Functions.PartialFractions.Bare((pair.Rate + k).Simplify())));
                if (opposite < 0)
                {
                    sum += Functions.PartialFractions.Bare(a.Simplify()) * MathS.Ei(k * u);
                    continue;
                }
                var b = integrals[opposite].Coefficient;
                integrals.RemoveAt(opposite);
                if (k.Evaled is Number.Real { IsNegative: true })
                    (k, a, b) = ((-k).InnerSimplified, b, a);
                // The two coefficients simplified, which is where `e e^(-4/3)` becomes `e^(-1/3)`.
                sum += Functions.PartialFractions.Bare((a + b).Simplify()) * MathS.Chi(k * u)
                    + Functions.PartialFractions.Bare((a - b).Simplify()) * MathS.Shi(k * u);
            }
            return Functions.PartialFractions.Bare(sum.Substitute(u, linear).InnerSimplified);
        }

        /// <summary>
        /// A term <c>c e^(r x)</c> of an expanded sum of exponentials, as its rate and coefficient:
        /// a product of constants and of constants to linears in <paramref name="x"/>, or
        /// <see langword="null"/>.
        /// </summary>
        private static (Entity Rate, Entity Coefficient)? ReadAnExponentialTerm(Entity term, Entity.Variable x)
        {
            Entity rate = Number.Integer.Zero;
            Entity coefficient = Number.Integer.One;
            foreach (var (written, underneath) in FactorsOfTheIntegrand(term))
                if (!Read(written, underneath ? -1 : 1))
                    return null;
            // The rate is a sum of the slopes, `b + b - b - b` for four exponentials of `a + b x`,
            // and inner simplification leaves that as `2 b + 2 (-b)`, a zero nothing reads: a
            // rate with a symbol in it is simplified.
            var folded = rate.InnerSimplified;
            if (folded.Vars.Any())
                folded = Functions.PartialFractions.Bare(folded.Simplify());
            return (folded, coefficient.InnerSimplified);

            // A factor to a whole power: a constant, an exponential of a linear, or a product or
            // a quotient of those -- `(e^(2 x)/4)^2`, as the expansion of `sinh(x)^2 cosh(x)^2`
            // leaves one, is `e^(4 x)/16`.
            bool Read(Entity factor, int times)
            {
                while (factor is Powf(var inner, Number.Integer whole) && whole.EInteger.CanFitInInt32())
                    (factor, times) = (inner, times * whole.EInteger.ToInt32Checked());
                if (!factor.ContainsNode(x))
                {
                    coefficient *= times == 1 ? factor : MathS.Pow(factor, times);
                    return true;
                }
                switch (factor)
                {
                    case Mulf(var left, var right):
                        return Read(left, times) && Read(right, times);
                    case Divf(var numerator, var denominator):
                        return Read(numerator, times) && Read(denominator, -times);
                    case Powf(var @base, var exponent) when !@base.ContainsNode(x)
                        && TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out var intercept):
                        var logarithm = @base == MathS.e ? (Entity)Number.Integer.One : MathS.Ln(@base);
                        rate += times * slope * logarithm;
                        coefficient *= MathS.Pow(@base, times * intercept);
                        return true;
                    default:
                        return false;
                }
            }
        }

        /// <summary>
        /// An exponential of a linear, or a sum of them -- which is how <c>sinh</c> and <c>cosh</c>
        /// arrive -- times a polynomial, over two or more linears each to a whole power: split into
        /// partial fractions over the linears, and each term the one-linear question of
        /// <see cref="SolveAnExponentialOfALinearOverAPowerOfALinear"/> and
        /// <see cref="SolveAHyperbolicOfALinearOverAPowerOfALinear"/>. <c>e^x/(x (x + 1))</c> is
        /// <c>e^x/x - e^x/(x + 1)</c>, which is <c>Ei(x) - Ei(x + 1)/e</c>; the trigonometric rule
        /// splits the same way (<see cref="OverAPowerOfALinear"/>). It is also what by parts leaves
        /// of <c>Ei(a + b x)/x^2</c>, <c>e^(a + b x)/((a + b x) x)</c>. A quadratic below the bar is
        /// the linears of its two roots: Rubi's 6.2.2, <c>cosh(c + d x)/(a + b x^2)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        internal static Entity? SolveAnExponentialOverSeveralLinears(Entity expr, Entity.Variable x)
        {
            if (expr is not (Divf or Mulf) || AnExponentialOfALinear(expr, x) is null && !HasASumOfExponentials(expr, x))
                return null;
            Entity constant = Number.Integer.One;
            var linears = new List<(Entity Linear, int Power)>();
            Entity? polynomial = null;
            Entity? exponentials = null;
            // The denominator as it is written, each quadratic monic, for the division.
            Entity written = Number.Integer.One;
            void AddALinear(Entity linear, int power)
            {
                var at = linears.FindIndex(pair => pair.Linear == linear);
                if (at < 0)
                    linears.Add((linear, power));
                else
                    linears[at] = (linear, linears[at].Power + power);
            }
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                var (@base, exponent) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath)
                    exponent = -exponent;
                if (exponent < 0 && TreeAnalyzer.TryGetPolyLinear(@base, x, out var slopeOfIt, out _) && !TreeAnalyzer.IsZero(slopeOfIt))
                {
                    AddALinear(@base, -exponent);
                    written *= MathS.Pow(@base, -exponent);
                    continue;
                }
                // A quadratic is its leading coefficient times the linears of its two roots, complex
                // where its discriminant is negative, as the trigonometric rule writes it:
                // `cosh(c + d x)/(a + b x^2)` is a sum over `x -/+ sqrt(-a/b)`, each the one-linear
                // question, and the integrals of the two conjugate arguments add up to a real answer.
                if (exponent < 0 && TreeAnalyzer.TryGetPolyQuadratic(@base, x, out var leading, out var middle, out var last) && !TreeAnalyzer.IsZero(leading))
                {
                    var discriminant = MathS.Sqrt(middle * middle - 4 * leading * last);
                    constant /= MathS.Pow(leading, -exponent);
                    AddALinear(LessTheRoot(((-middle + discriminant) / (2 * leading)).InnerSimplified, x), -exponent);
                    AddALinear(LessTheRoot(((-middle - discriminant) / (2 * leading)).InnerSimplified, x), -exponent);
                    written *= MathS.Pow(Monic(leading, middle, last, x), -exponent);
                    continue;
                }
                // And a binomial past the quadratic the linears of its roots: `cosh(c + d x)/(a + b x^3)`.
                if (exponent < 0 && TheRootsOfABinomial(@base, x) is { } binomial)
                {
                    constant /= MathS.Pow(binomial.Leading, -exponent);
                    foreach (var root in binomial.Roots)
                        AddALinear(LessTheRoot(root, x), -exponent);
                    written *= MathS.Pow(binomial.Monic, -exponent);
                    continue;
                }
                if (underneath)
                    return null;
                if (factor.Nodes.Any(node => node is Powf(var b, var e) && !b.ContainsNode(x) && e.ContainsNode(x)))
                {
                    exponentials = exponentials is null ? factor : exponentials * factor;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (exponentials is null || linears.Count < 2 || linears.Count > 4 || linears.Sum(pair => pair.Power) > 12)
                return null;
            // Exponentials of linears only, which is what the one-linear rules read: split, a term of
            // `sinh(sqrt((1 - a x)/(1 + a x)))/(1 - a^2 x^2)` goes to the whole integrator, and the
            // substitution that answers the question whole in a tenth of a second is not reached.
            if (!Sumf.LinearChildren(exponentials.Expand()).All(term => ReadAnExponentialTerm(term, x) is not null))
                return null;
            // Over each linear by partial fractions, as the trigonometric rule does it.
            var denominator = linears.Aggregate((Entity)Number.Integer.One, (product, pair) => product * MathS.Pow(pair.Linear, pair.Power));
            if (OverEachLinear(polynomial ?? Number.Integer.One, written, denominator, linears.Sum(pair => pair.Power), x) is not { } terms)
                return null;
            Entity sum = Number.Integer.Zero;
            foreach (var term in terms)
            {
                // Each term as the quotient the one-linear rules read, or, with no linear left, the
                // elementary product of a polynomial and the exponentials.
                var (above, linear, power) = OverOneLinear(term, x);
                var question = linear is null ? above * exponentials : above * exponentials / MathS.Pow(linear, power);
                if ((SolveAnExponentialOfALinearOverAPowerOfALinear(question, x)
                        ?? SolveAHyperbolicOfALinearOverAPowerOfALinear(question, x)
                        ?? Integration.ComputeIndefiniteIntegral(question, x, false)) is not { } integral)
                    return null;
                sum += integral;
            }
            return Functions.PartialFractions.Bare((constant * sum).InnerSimplified);
        }

        /// <summary>
        /// Exponentials of one linear below the bar, beside polynomials of <c>x</c> with one below
        /// the bar: in <c>w</c>, the exponential every other is a whole power of, the exponentials
        /// are a rational function of <c>w</c>, and where that is a sum of whole powers of <c>w</c>
        /// -- its denominator in lowest terms a power of <c>w</c> alone -- each term is an
        /// exponential of a linear over the polynomials, which
        /// <see cref="SolveAnExponentialOfALinearOverAPowerOfALinear"/> answers onto the exponential
        /// integral. <c>1 + tanh(z)</c> is <c>2 e^(2z)/(e^(2z) + 1)</c>, so
        /// <c>1/((c + d x)(a + a tanh(e + f x)))</c> is <c>(1 + e^(-2(e + f x)))/(2 a (c + d x))</c>.
        /// Rubi's 6.3.1 and 6.4.1, <c>(c + d x)^m (a + a tanh(e + f x))^n</c> and the same with
        /// <c>coth</c>, for a negative <c>m</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// The rules for an exponential over a linear read it above the bar: <c>e^(-2x)/x</c> was
        /// answered and <c>1/(x e^(2x))</c> declined. Where the denominator keeps a factor other
        /// than <c>w</c> after cancelling, <c>1/(x (1 + e^x))</c>, the integral is neither elementary
        /// nor an exponential integral, and this declines.
        /// </remarks>
        internal static Entity? SolveAnExponentialBelowTheBarBesideAPowerOfALinear(Entity expr, Entity.Variable x)
        {
            bool IsAnExponential(Entity node) => node is Powf(var b, var p) && !b.ContainsNode(x) && p.ContainsNode(x);
            if (!expr.Nodes.Any(node => node is Divf(_, var below) && below.Nodes.Any(IsAnExponential)
                    || node is Powf(var raised, Number.Integer { IsNegative: true }) && raised.Nodes.Any(IsAnExponential)))
                return null;
            Entity constant = Number.Integer.One;
            Entity aboveX = Number.Integer.One;
            Entity belowX = Number.Integer.One;
            Entity exponentials = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor.Nodes.Any(IsAnExponential))
                {
                    exponentials = underneath ? exponentials / factor : exponentials * factor;
                    continue;
                }
                // A polynomial, or a whole power of one, above or below the bar.
                var (@base, power) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath)
                    power = -power;
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var read) || read.Keys.Any(degree => degree.Sign < 0) || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                    return null;
                if (power > 0)
                    aboveX = aboveX == Number.Integer.One ? MathS.Pow(@base, power) : aboveX * MathS.Pow(@base, power);
                else
                    belowX = belowX == Number.Integer.One ? MathS.Pow(@base, -power) : belowX * MathS.Pow(@base, -power);
            }
            // Nothing of x below the bar: a polynomial beside the exponentials is the rules' by parts.
            if (belowX == Number.Integer.One || exponentials.Complexity > 160)
                return null;

            // One base, and every exponent a rational multiple of the first, its offset included,
            // so that w is a power of the base at that exponent and no constant is left beside it.
            Entity? commonBase = null;
            Entity? unit = null, unitSlope = null, unitOffset = null;
            var multiples = new Dictionary<Entity, ERational>();
            foreach (var node in exponentials.Nodes)
            {
                if (!IsAnExponential(node) || multiples.ContainsKey(node) || node is not Powf(var @base, var exponent))
                    continue;
                if (!TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out var offset) || TreeAnalyzer.IsZero(slope))
                    return null;
                if (commonBase is null)
                {
                    (commonBase, unit, unitSlope, unitOffset) = (@base, exponent, slope, offset);
                    multiples[node] = ERational.One;
                    continue;
                }
                if (@base != commonBase
                    || Functions.PartialFractions.Bare((slope / unitSlope!).Simplify()).Evaled is not Number.Rational ratio || ratio.ERational.IsZero
                    || !IsTheZeroPolynomial((offset - ratio * unitOffset!).InnerSimplified))
                    return null;
                multiples[node] = ratio.ERational;
            }
            if (commonBase is null || unit is null)
                return null;
            if (commonBase != MathS.e && (commonBase.Evaled is Number.Complex and not Number.Real || commonBase.Evaled is Number.Real { IsNegative: true } || TreeAnalyzer.IsZero(commonBase)))
                return null;
            var numerators = EInteger.Zero;
            var denominators = EInteger.One;
            foreach (var multiple in multiples.Values)
            {
                numerators = numerators.Gcd(multiple.Numerator.Abs());
                denominators = denominators.Multiply(multiple.Denominator).Divide(denominators.Gcd(multiple.Denominator));
            }
            var step = ERational.Create(numerators, denominators);
            if (multiples.Values.Any(multiple => multiple.Divide(step).ToLowestTerms().Numerator.Abs().CompareTo(EInteger.FromInt32(12)) > 0))
                return null;
            var w = Variable.CreateUnique(expr, "w_exp");
            var inW = exponentials.Replace(node =>
                multiples.TryGetValue(node, out var multiple) ? MathS.Pow(w, Number.Integer.Create(multiple.Divide(step).ToLowestTerms().Numerator)) : node);
            if (inW.ContainsNode(x))
                return null;

            // A sum of whole powers of w: its denominator in lowest terms a power of w alone.
            var (top, bottom) = Functions.SingleQuotient.Of(inW);
            if (!TreeAnalyzer.TryGetPolynomial(bottom, w, out var below) || below.Count != 1)
            {
                if (!Functions.PolynomialGcd.TryCancel(top, bottom, out var cancelled, maxComplexity: 1024))
                    return null;
                (top, bottom) = Functions.SingleQuotient.Of(cancelled is Providedf(var inner, _) ? inner : cancelled);
                if (!TreeAnalyzer.TryGetPolynomial(bottom, w, out below) || below.Count != 1)
                    return null;
            }
            var lowest = below.Keys.Single();
            var leading = below[lowest];
            if (!TreeAnalyzer.TryGetPolynomial(top, w, out var above) || above.Count > 16 || TreeAnalyzer.IsZero(leading))
                return null;

            Entity sum = Number.Integer.Zero;
            foreach (var term in above)
            {
                if (TreeAnalyzer.IsZero(term.Value))
                    continue;
                var power = term.Key.Subtract(lowest);
                var exponential = power.IsZero ? Number.Integer.One
                    : MathS.Pow(commonBase, (Number.Rational.Create(step.Multiply(ERational.FromEInteger(power))) * unit).InnerSimplified);
                var question = constant * term.Value / leading * aboveX * exponential / belowX;
                var integral = power.IsZero
                    ? Integration.ComputeIndefiniteIntegral(question, x, false)
                    : SolveAnExponentialOfALinearOverAPowerOfALinear(question, x) ?? SolveAnExponentialOverSeveralLinears(question, x)
                        ?? Integration.ComputeIndefiniteIntegral(question, x, false);
                if (integral is null || integral.Nodes.Any(node => node is Integralf))
                    return null;
                sum += integral;
            }
            return sum == Number.Integer.Zero ? null : Functions.PartialFractions.Bare(sum.InnerSimplified);
        }

        /// <summary>
        /// An exponential of a linear times sines and cosines of linears, and a polynomial, over
        /// linears: each sine and cosine is written as exponentials, <c>sin(c x) = (e^(i c x) - e^(-i c x))/(2i)</c>,
        /// the product multiplied out, and every term is an exponential of a linear with a
        /// complex rate over the linears, which <see cref="SolveAnExponentialOfALinearOverAPowerOfALinear"/>
        /// and <see cref="SolveAnExponentialOverSeveralLinears"/> answer with the exponential
        /// integral of a complex argument. <c>e^(2x) sin(x)/x</c> is
        /// <c>(Ei((2 + i) x) - Ei((2 - i) x))/(2i)</c>, real where <c>x</c> is: the two terms are
        /// conjugates. What by parts leaves of <c>Si(ln(x))</c>, under <c>t = ln(x)</c>, is
        /// <c>e^t sin(t)/t</c>. Rubi's 8.4, <c>(e x)^m Si(d (a + b ln(c x^n)))</c>, answers the same way.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// Only with an exponential of a real rate beside the sine or cosine: alone over a linear,
        /// the sine and cosine integrals are their closed form, and the rule for them answers.
        /// </remarks>
        internal static Entity? SolveAnExponentialTimesATrigonometricOverLinears(Entity expr, Entity.Variable x)
        {
            if (expr is not (Divf or Mulf))
                return null;
            int exponentialsByShape = 0, trigonometricsByShape = 0;
            var aPowerOfASumByShape = false;
            CountFactorsByShape(expr, x, ref exponentialsByShape, ref trigonometricsByShape, ref aPowerOfASumByShape);
            if (exponentialsByShape == 0 || trigonometricsByShape == 0)
                return null;
            Entity constant = Number.Integer.One;
            Entity? polynomial = null;
            var linears = new List<(Entity Linear, int Power)>();
            var exponents = new List<WrittenExponent>();
            var terms = new List<(Entity Coefficient, int[] Multiples)> { (Number.Integer.One, new int[MostExponents]) };
            int exponentials = 0, trigonometrics = 0;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                var (@base, exponent) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath && TreeAnalyzer.TryGetPolyLinear(@base, x, out var slopeOfIt, out _) && !TreeAnalyzer.IsZero(slopeOfIt))
                {
                    var at = linears.FindIndex(pair => pair.Linear == @base);
                    if (at < 0)
                        linears.Add((@base, exponent));
                    else
                        linears[at] = (@base, linears[at].Power + exponent);
                    continue;
                }
                if (underneath)
                    return null;
                if (AsExponentialsOfQuadratics(factor, x, exponents) is { } read)
                {
                    if (factor.Nodes.Any(node => node is Sinf or Cosf))
                        trigonometrics++;
                    else
                        exponentials++;
                    if (Multiplied(terms, read) is not { } product)
                        return null;
                    terms = product;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (exponentials == 0 || trigonometrics == 0 || linears.Count == 0 || linears.Count > 4 || linears.Sum(pair => pair.Power) > 12)
                return null;
            var below = linears.Aggregate((Entity)Number.Integer.One, (product, pair) => product * MathS.Pow(pair.Linear, pair.Power));
            var above = polynomial ?? Number.Integer.One;
            Entity sum = Number.Integer.Zero;
            foreach (var (coefficient, multiples) in terms)
            {
                var (a, b, c) = TheExponent(multiples, exponents);
                // Linear exponents only: a quadratic left is the Gaussian's, and is another rule's.
                if (!TreeAnalyzer.IsZero(a))
                    return null;
                var factorOfTheTerm = TreeAnalyzer.IsZero(c) ? coefficient : coefficient * MathS.Pow(MathS.e, c);
                var question = TreeAnalyzer.IsZero(b)
                    ? above / below
                    : MathS.Pow(MathS.e, b * x) * above / below;
                if (((TreeAnalyzer.IsZero(b) ? null
                        : linears.Count == 1 ? SolveAnExponentialOfALinearOverAPowerOfALinear(question, x) : SolveAnExponentialOverSeveralLinears(question, x))
                        ?? Integration.ComputeIndefiniteIntegral(question, x, false)) is not { } integral)
                    return null;
                sum += factorOfTheTerm * integral;
            }
            return Functions.PartialFractions.Bare((constant * sum).InnerSimplified);
        }

        /// <summary>Whether a factor of <paramref name="expr"/> is a sum with an exponential of the variable in it.</summary>
        private static bool HasASumOfExponentials(Entity expr, Entity.Variable x) => expr switch
        {
            Sumf or Minusf => expr.Nodes.Any(node => node is Powf(var b, var e) && !b.ContainsNode(x) && e.ContainsNode(x)),
            Powf(var @base, Number.Integer) => HasASumOfExponentials(@base, x),
            Mulf(var left, var right) => HasASumOfExponentials(left, x) || HasASumOfExponentials(right, x),
            Divf(var numerator, _) => HasASumOfExponentials(numerator, x),
            _ => false,
        };

        /// <summary>
        /// A factor of <paramref name="expr"/>, read through products and quotients, that is a
        /// constant to a linear in <paramref name="x"/>, above the bar, or <see langword="null"/>.
        /// </summary>
        private static Powf? AnExponentialOfALinear(Entity expr, Entity.Variable x) => expr switch
        {
            Mulf(var left, var right) => AnExponentialOfALinear(left, x) ?? AnExponentialOfALinear(right, x),
            Divf(var numerator, _) => AnExponentialOfALinear(numerator, x),
            Powf(var @base, var exponent) power when !@base.ContainsNode(x) && exponent.ContainsNode(x)
                && TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out _) && !TreeAnalyzer.IsZero(slope) => power,
            _ => null
        };

        /// <summary>
        /// A product of exponentials of polynomials of degree at most two, whole powers of sines
        /// and cosines of such polynomials, whole powers of sums of those exponentials -- which is
        /// how a hyperbolic function is written -- and a polynomial, where some exponent is left a
        /// quadratic. A sine or cosine is written as exponentials, <c>sin(q) = (e^(i q) - e^(-i q))/(2i)</c>,
        /// and the product multiplied out is a sum of terms <c>k P(x) e^(Q(x))</c>, with <c>Q</c> of
        /// degree at most two: the Gaussian's moments where <c>Q</c> is a quadratic, and elementary
        /// where it is not. Rubi's 4.7.6, 6.1.5 and 6.2.5, <c>f^(a + b x + c x^2) sin(d + e x + f x^2)^n</c>
        /// and <c>f^(a + b x + c x^2) cosh(d + e x + f x^2)^n</c>, 6.1.4's <c>x^2 sinh(a + b x + c x^2)^2</c>,
        /// and 2.3's <c>f^(a + b x + c x^2) g^(d + e x + f x^2)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// <para>
        /// A sine or cosine is taken only beside an exponential. Alone, or beside a polynomial,
        /// the sine of a quadratic is a Fresnel integral, and <c>x sin(x^2)</c> is <c>-cos(x^2)/2</c>,
        /// which the substitution answers with no imaginary unit in it. A sum of exponentials is
        /// taken beside another exponential, or in a power: <c>x^2 sinh(q)</c> alone is a sum the
        /// integrator splits, and each of its terms is the Gaussian's.
        /// </para>
        /// <para>
        /// A term's exponent is kept as whole multiples of the exponents the integrand writes, not
        /// as their sum: <c>e^(i q)</c> times <c>e^(-i q)</c> is then the multiple 0, decidably,
        /// where the sum <c>i q + (-i) q</c> is not read as zero, and a Gaussian of it would
        /// divide by a square's coefficient that is.
        /// </para>
        /// </remarks>
        internal static Entity? SolveAProductOfExponentialsOfQuadratics(Entity expr, Entity.Variable x)
        {
            if (expr is not (Mulf or Divf or Powf))
                return null;
            // By the written shape first, which reads and allocates nothing: most products asked
            // here have one exponential in them, or none, and no sine.
            int exponentials = 0, trigonometrics = 0;
            var aPowerOfASum = false;
            CountFactorsByShape(expr, x, ref exponentials, ref trigonometrics, ref aPowerOfASum);
            if (trigonometrics > 0 ? exponentials == 0 : exponentials < 2 && !aPowerOfASum)
                return null;
            (exponentials, trigonometrics, aPowerOfASum) = (0, 0, false);
            Entity constant = Number.Integer.One;
            Entity? polynomial = null;
            var powerOfX = 0;
            var exponents = new List<WrittenExponent>();
            var terms = new List<(Entity Coefficient, int[] Multiples)> { (Number.Integer.One, new int[MostExponents]) };
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (AsExponentialsOfQuadratics(factor, x, exponents) is { } read)
                {
                    // Below the bar, a single exponential only, whose reciprocal is one too.
                    if (underneath)
                    {
                        if (read.Count != 1)
                            return null;
                        var (coefficient, multiples) = read[0];
                        for (var i = 0; i < multiples.Length; i++)
                            multiples[i] = -multiples[i];
                        read[0] = (1 / coefficient, multiples);
                    }
                    if (factor.Nodes.Any(node => node is Sinf or Cosf))
                        trigonometrics++;
                    else
                        exponentials++;
                    aPowerOfASum |= read.Count > 1 && factor is Powf(_, Number.Integer { EInteger: var power }) && power.CompareTo(EInteger.One) > 0;
                    if (Multiplied(terms, read) is not { } product)
                        return null;
                    terms = product;
                    continue;
                }
                // A power of x, above or below the bar, read apart from the polynomial: below it, it
                // is a moment about 0 of a term without a linear part.
                if (APowerOfTheVariable(factor, x) is { } k)
                {
                    powerOfX += underneath ? -k : k;
                    continue;
                }
                if (!underneath && TreeAnalyzer.TryGetPolynomial(factor, x, out var inX)
                    && inX.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(MostPowerOfAPolynomialBesideExponentials)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (trigonometrics > 0 ? exponentials == 0 : exponentials < 2 && !aPowerOfASum)
                return null;
            var quadratics = new List<(Entity Coefficient, Entity A, Entity B, Entity C)>(terms.Count);
            foreach (var (coefficient, multiples) in terms)
            {
                var (a, b, c) = TheExponent(multiples, exponents);
                quadratics.Add((coefficient, a, b, c));
            }
            // Some exponent left a quadratic: with none, the product is the elementary
            // exponential's, and the rules for that answer it without an imaginary unit.
            if (!quadratics.Any(term => !TreeAnalyzer.IsZero(term.A)))
                return null;
            // The polynomial and the power of x together: as the product written, for the moments
            // at a square's centre, which substitute into it as the integrand writes it, and as
            // each power of x with its coefficient, for the moments about 0 and the elementary terms.
            Entity? written = powerOfX > 0 ? (polynomial is null ? MathS.Pow(x, powerOfX) : MathS.Pow(x, powerOfX) * polynomial) : polynomial;
            Dictionary<EInteger, Entity>? powers = null;
            if (polynomial is not null && !TreeAnalyzer.TryGetPolynomial(polynomial, x, out powers))
                return null;
            if (powerOfX != 0)
            {
                var shifted = new Dictionary<EInteger, Entity>();
                if (powers is null)
                    shifted[EInteger.FromInt32(powerOfX)] = Number.Integer.One;
                else
                    foreach (var monomial in powers)
                        shifted[monomial.Key + powerOfX] = monomial.Value;
                powers = shifted;
            }
            if (powers is not null && powers.Keys.Any(power => power.Abs().CompareTo(EInteger.FromInt32(MostPowerOfAPolynomialBesideExponentials)) > 0))
                return null;
            var aNegativePower = powers is not null && powers.Keys.Any(power => power.Sign < 0);
            Entity total = Number.Integer.Zero;
            foreach (var (coefficient, a, b, c) in quadratics)
            {
                Entity? integral;
                if (!TreeAnalyzer.IsZero(a))
                {
                    if (TreeAnalyzer.IsZero(b) && powers is not null)
                        integral = IntegralPatterns.MomentsAboutZero(powers, MathS.e, a, c, x);
                    // At a square's centre only a polynomial is a sum of moments.
                    else if (aNegativePower)
                        return null;
                    else
                        integral = IntegralPatterns.APolynomialTimesTheGaussian(written, MathS.e, a, b, c, x);
                }
                // A negative power beside an elementary exponential is the exponential integral.
                else if (aNegativePower)
                    return null;
                else if (!TreeAnalyzer.IsZero(b))
                    integral = MathS.Pow(MathS.e, b * x + c) * APolynomialAgainstAnExponential(powers, b, x);
                else
                    integral = MathS.Pow(MathS.e, c) * APolynomialIntegrated(powers, x);
                if (integral is null)
                    return null;
                total += coefficient * integral;
            }
            return (constant * total).InnerSimplified;
        }

        /// <summary><c>k</c> where <paramref name="factor"/> is <c>x^k</c> for a whole <c>k</c>, or <see langword="null"/>.</summary>
        private static int? APowerOfTheVariable(Entity factor, Entity.Variable x)
            => factor == x ? 1
                : factor is Powf(var @base, Number.Integer { EInteger: var power }) && @base == x && power.CanFitInInt32() ? power.ToInt32Checked()
                : null;

        /// <summary>
        /// An exponent the integrand writes, <c>A x^2 + B x + C</c> once read, of the exponential
        /// <c>Base^Written</c>, or of <c>e^(i Written)</c> for a sine or cosine of it.
        /// </summary>
        private sealed record WrittenExponent(Entity Base, Entity Written, bool Imaginary, Entity A, Entity B, Entity C);

        private const int MostExponents = 6;
        private const int MostPowerOfAPolynomialBesideExponentials = 32;
        private const int MostPowerOfASumOfExponentials = 8;
        private const int MostExponentialTerms = 64;

        /// <summary>
        /// Counts the factors of <paramref name="expr"/> by their written shape alone: a sine or
        /// cosine, or a power of one; an exponential of <paramref name="x"/>; and a sum, which may
        /// be one of exponentials, or a whole power of a sum. An over-count, which the reading
        /// that follows corrects: <c>(1 + x)</c> is counted as a sum.
        /// </summary>
        private static void CountFactorsByShape(Entity expr, Entity.Variable x, ref int exponentials, ref int trigonometrics, ref bool aPowerOfASum)
        {
            switch (expr)
            {
                case Mulf(var left, var right):
                    CountFactorsByShape(left, x, ref exponentials, ref trigonometrics, ref aPowerOfASum);
                    CountFactorsByShape(right, x, ref exponentials, ref trigonometrics, ref aPowerOfASum);
                    break;
                case Divf(var numerator, var denominator):
                    CountFactorsByShape(numerator, x, ref exponentials, ref trigonometrics, ref aPowerOfASum);
                    CountFactorsByShape(denominator, x, ref exponentials, ref trigonometrics, ref aPowerOfASum);
                    break;
                case Sinf or Cosf or Powf(Sinf or Cosf, Number.Integer):
                    trigonometrics++;
                    break;
                case Powf(var @base, var exponent) when !@base.ContainsNode(x) && exponent.ContainsNode(x):
                case Sumf or Minusf:
                    exponentials++;
                    break;
                case Powf(Sumf or Minusf or Mulf or Divf, Number.Integer { EInteger: var power }) when power.CompareTo(EInteger.One) > 0:
                    exponentials++;
                    aPowerOfASum = true;
                    break;
            }
        }

        /// <summary>
        /// <paramref name="expr"/> as a sum of terms <c>k e^(m_1 Q_1 + m_2 Q_2 + ...)</c>, where the
        /// <c>Q_j</c> are <paramref name="exponents"/> and the <c>m_j</c> whole, or
        /// <see langword="null"/>: an exponential of a polynomial of degree at most two, a sine or
        /// cosine of one, and sums, products, quotients by a constant and small whole powers of those.
        /// </summary>
        private static List<(Entity Coefficient, int[] Multiples)>? AsExponentialsOfQuadratics(Entity expr, Entity.Variable x, List<WrittenExponent> exponents)
        {
            switch (expr)
            {
                case var constant when !constant.ContainsNode(x):
                    return new() { (constant, new int[MostExponents]) };
                case Powf(var @base, var exponent) when !@base.ContainsNode(x):
                {
                    // e^(-q), as sinh(q) writes it, is -1 times the exponent of its e^q.
                    var (written, multiple) = exponent switch
                    {
                        Mulf(Number.Integer k, var inner) when k.EInteger.Abs().CompareTo(EInteger.FromInt32(MostPowerOfASumOfExponentials)) <= 0 => (inner, k.EInteger.ToInt32Checked()),
                        Mulf(var inner, Number.Integer k) when k.EInteger.Abs().CompareTo(EInteger.FromInt32(MostPowerOfASumOfExponentials)) <= 0 => (inner, k.EInteger.ToInt32Checked()),
                        _ => (exponent, 1)
                    };
                    if (TheWrittenExponent(@base, written, imaginary: false, x, exponents) is not { } index)
                        return null;
                    var multiples = new int[MostExponents];
                    multiples[index] = multiple;
                    return new() { (Number.Integer.One, multiples) };
                }
                // sin(q) = (e^(i q) - e^(-i q))/(2i) and cos(q) = (e^(i q) + e^(-i q))/2.
                case Sinf(var argument):
                    return AnImaginaryPair(-MathS.i / 2, MathS.i / 2, argument, x, exponents);
                case Cosf(var argument):
                    return AnImaginaryPair(Number.Rational.Create(1, 2), Number.Rational.Create(1, 2), argument, x, exponents);
                case Sumf(var left, var right):
                {
                    if (AsExponentialsOfQuadratics(left, x, exponents) is not { } l || AsExponentialsOfQuadratics(right, x, exponents) is not { } r)
                        return null;
                    l.AddRange(r);
                    return l.Count > MostExponentialTerms ? null : l;
                }
                case Minusf(var left, var right):
                {
                    if (AsExponentialsOfQuadratics(left, x, exponents) is not { } l || AsExponentialsOfQuadratics(right, x, exponents) is not { } r)
                        return null;
                    foreach (var (coefficient, multiples) in r)
                        l.Add((-coefficient, multiples));
                    return l.Count > MostExponentialTerms ? null : l;
                }
                case Mulf(var left, var right):
                {
                    if (AsExponentialsOfQuadratics(left, x, exponents) is not { } l || AsExponentialsOfQuadratics(right, x, exponents) is not { } r)
                        return null;
                    return Multiplied(l, r);
                }
                case Divf(var numerator, var denominator) when !denominator.ContainsNode(x):
                {
                    if (AsExponentialsOfQuadratics(numerator, x, exponents) is not { } n)
                        return null;
                    for (var i = 0; i < n.Count; i++)
                        n[i] = (n[i].Coefficient / denominator, n[i].Multiples);
                    return n;
                }
                case Powf(var inner, Number.Integer power) when power.EInteger.Sign > 0
                    && power.EInteger.CompareTo(EInteger.FromInt32(MostPowerOfASumOfExponentials)) <= 0:
                {
                    if (AsExponentialsOfQuadratics(inner, x, exponents) is not { } once)
                        return null;
                    var result = once;
                    for (var k = power.EInteger.ToInt32Checked(); k > 1 && result is not null; k--)
                        result = Multiplied(result, once);
                    return result;
                }
                default:
                    return null;
            }
        }

        /// <summary>
        /// The index of <c>Base^Written</c>, or of <c>e^(i Written)</c>, among
        /// <paramref name="exponents"/>, read and added where it is not there yet, or
        /// <see langword="null"/> where it is not a polynomial of degree at most two.
        /// </summary>
        private static int? TheWrittenExponent(Entity @base, Entity written, bool imaginary, Entity.Variable x, List<WrittenExponent> exponents)
        {
            for (var i = 0; i < exponents.Count; i++)
                if (exponents[i].Imaginary == imaginary && exponents[i].Base == @base && exponents[i].Written == written)
                    return i;
            if (exponents.Count == MostExponents || !written.ContainsNode(x)
                || !TreeAnalyzer.TryGetPolyQuadratic(written, x, out var a, out var b, out var c))
                return null;
            // A zero coefficient is left the integer zero: 0 ln(f), simplified, is 0 provided f is
            // not 0, which is not read as zero, and 0 x^2 would be taken for a Gaussian's square.
            Entity scale = imaginary ? MathS.i : @base == MathS.e ? Number.Integer.One : MathS.Ln(@base);
            exponents.Add(new(@base, written, imaginary, Scaled(a, scale), Scaled(b, scale), Scaled(c, scale)));
            return exponents.Count - 1;

            static Entity Scaled(Entity coefficient, Entity scale)
                => TreeAnalyzer.IsZero(coefficient) ? Number.Integer.Zero
                    : scale == Number.Integer.One ? coefficient : (scale * coefficient).InnerSimplified;
        }

        /// <summary>
        /// <c>k_+ e^(i q) + k_- e^(-i q)</c> for the <paramref name="argument"/> <c>q</c>, or
        /// <see langword="null"/> where it is not a polynomial of degree at most two.
        /// </summary>
        private static List<(Entity Coefficient, int[] Multiples)>? AnImaginaryPair(Entity plus, Entity minus, Entity argument, Entity.Variable x, List<WrittenExponent> exponents)
        {
            if (TheWrittenExponent(MathS.e, argument, imaginary: true, x, exponents) is not { } index)
                return null;
            var (up, down) = (new int[MostExponents], new int[MostExponents]);
            (up[index], down[index]) = (1, -1);
            return new() { (plus, up), (minus, down) };
        }

        /// <summary>
        /// The product of two sums of exponentials, with the terms of one exponent gathered, and
        /// <see langword="null"/> past <see cref="MostExponentialTerms"/>.
        /// </summary>
        private static List<(Entity Coefficient, int[] Multiples)>? Multiplied(List<(Entity Coefficient, int[] Multiples)> left, List<(Entity Coefficient, int[] Multiples)> right)
        {
            if (left.Count * right.Count > MostExponentialTerms)
                return null;
            var gathered = new List<(Entity Coefficient, int[] Multiples)>();
            foreach (var l in left)
                foreach (var r in right)
                {
                    var multiples = new int[MostExponents];
                    for (var i = 0; i < multiples.Length; i++)
                        multiples[i] = l.Multiples[i] + r.Multiples[i];
                    var coefficient = l.Coefficient * r.Coefficient;
                    var at = gathered.FindIndex(term => term.Multiples.SequenceEqual(multiples));
                    if (at < 0)
                        gathered.Add((coefficient, multiples));
                    else
                        gathered[at] = (gathered[at].Coefficient + coefficient, multiples);
                }
            var product = new List<(Entity Coefficient, int[] Multiples)>(gathered.Count);
            foreach (var (coefficient, multiples) in gathered)
            {
                var simplified = coefficient.InnerSimplified;
                if (!TreeAnalyzer.IsZero(simplified))
                    product.Add((simplified, multiples));
            }
            return product;
        }

        /// <summary>
        /// <c>(A, B, C)</c> of the exponent <c>sum_j m_j Q_j</c>, with the zero multiples left out,
        /// so that a term with none is decidably <c>e^0</c>.
        /// </summary>
        private static (Entity A, Entity B, Entity C) TheExponent(int[] multiples, List<WrittenExponent> exponents)
        {
            Entity a = Number.Integer.Zero, b = Number.Integer.Zero, c = Number.Integer.Zero;
            for (var i = 0; i < exponents.Count; i++)
            {
                if (multiples[i] == 0)
                    continue;
                var (m, exponent) = (multiples[i], exponents[i]);
                a = Plus(a, m, exponent.A);
                b = Plus(b, m, exponent.B);
                c = Plus(c, m, exponent.C);
            }
            return (a.InnerSimplified, b.InnerSimplified, c.InnerSimplified);

            static Entity Plus(Entity sum, int multiple, Entity coefficient)
            {
                if (coefficient == Number.Integer.Zero)
                    return sum;
                var term = multiple == 1 ? coefficient : multiple * coefficient;
                return sum == Number.Integer.Zero ? term : sum + term;
            }
        }

        /// <summary>
        /// <c>int P(x) e^(b x) dx</c> over <c>e^(b x)</c>: <c>sum_j (-1)^j P^(j)(x)/b^(j + 1)</c>, by
        /// parts, for <c>P</c> read into <paramref name="monomials"/>, or 1 where they are absent.
        /// </summary>
        private static Entity APolynomialAgainstAnExponential(Dictionary<EInteger, Entity>? monomials, Entity rate, Entity.Variable x)
        {
            if (monomials is null)
                return 1 / rate;
            Entity sum = Number.Integer.Zero;
            foreach (var monomial in monomials)
            {
                var power = monomial.Key.ToInt32Checked();
                // The j-th derivative of x^k is k!/(k - j)! x^(k - j).
                Entity falling = Number.Integer.One;
                for (var j = 0; j <= power; j++)
                {
                    var term = monomial.Value * falling * MathS.Pow(x, power - j) / MathS.Pow(rate, j + 1);
                    sum = j % 2 == 0 ? sum + term : sum - term;
                    falling *= power - j;
                }
            }
            return sum;
        }

        /// <summary>
        /// <c>int P(x) dx</c> for <c>P</c> read into <paramref name="monomials"/>, or <c>x</c> where
        /// they are absent.
        /// </summary>
        private static Entity APolynomialIntegrated(Dictionary<EInteger, Entity>? monomials, Entity.Variable x)
        {
            if (monomials is null)
                return x;
            Entity sum = Number.Integer.Zero;
            foreach (var monomial in monomials)
            {
                var power = monomial.Key.ToInt32Checked() + 1;
                sum += monomial.Value * MathS.Pow(x, power) / power;
            }
            return sum;
        }

        /// <summary>
        /// A polynomial times an exponential times a sine or a cosine —
        /// <c>P(x) e^(a x) cos(b x)</c> and its kin — integrated by the repeated by-parts that
        /// this shape is the textbook case for, run out here rather than through the chain.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>e^x cos(x)</c> came out and <c>x e^x cos(x)</c> did not. The polynomial by-parts
        /// integrates its <c>dv</c> with by-parts switched off, and <c>e^x cos(x)</c> is answered
        /// by <b>nothing but</b> by-parts — the cyclic one, where the integral comes back a
        /// multiple of itself. So the outer integral was declined for want of the inner one.
        /// </para>
        /// <para>
        /// <b>Switching that flag on is not the fix, and this is measured.</b> It buys these
        /// integrands and takes <c>x tan(x)^3 sec(x)^4</c> from 20 ms to <b>94 seconds</b> to
        /// decline — one test, the whole of a 76% slowdown in the calculus suite. The cost and
        /// the gain both arrive on the <i>second</i> round, integrating the antiderivative the
        /// first produced, so no size measure separates them: what separates them is whether the
        /// search succeeds, and that is only known by running it.
        /// https://github.com/asc-community/AngouriMath/issues/1265
        /// </para>
        /// <para>
        /// So the family is named instead of searched for. <c>int e^(a x)(c cos(b x) + d sin(b x))
        /// dx</c> is closed:
        /// </para>
        /// <code>
        ///     e^(ax) [ (a c - b d) cos(bx) + (b c + a d) sin(bx) ] / (a^2 + b^2)
        /// </code>
        /// <para>
        /// and it stays in the same shape, so integrating <c>x^k</c> against it by parts lowers
        /// <c>k</c> by one and leaves the same shape again. That terminates in <c>k + 1</c> steps
        /// with no search at all, which is what makes this <b>closed</b>.
        /// </para>
        /// <para>
        /// <c>a = 0</c> and <c>b = 0</c> are both admitted — a polynomial times a bare sine, or a
        /// bare exponential — though those already came out, so what this adds is the two
        /// together. Both zero is a polynomial and is declined, since it is the power rule's.
        /// </para>
        /// <para>
        /// <b>Asked, not volunteered</b>:
        /// <a href="https://github.com/asc-community/AngouriMath/issues/1265">#1265</a>.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPolynomialTimesAnExponentialAndATrigonometric(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            if (!TryReadAnExponentialTimesATrigonometric(expr, x,
                    out var polynomial, out var rate, out var frequency, out var sinePower, out var cosinePower))
                return null;

            // One sine or one cosine, or neither, is the shape the loop closes. A power of either,
            // or both together, is a sum of multiple angles -- `sin^3 u = (3 sin u - sin 3u)/4` --
            // and each term of that sum is the shape again, at its own frequency, so the loop
            // runs once per term and the answers add. `e^u sin(u)^3` is what
            // `e^(arcsin(x)) x^3/sqrt(1 - x^2)` becomes under `x = sin(u)`, and it was declined
            // for the cube.
            if (sinePower + cosinePower <= 1)
                return IntegrateAPolynomialTimesAnExponentialTimesOneTrigonometric(
                    polynomial, rate, frequency, sinePower == 1 ? 0 : 1, sinePower == 1 ? 1 : 0, x);

            Entity total = 0;
            foreach (var (multiple, isSine, coefficient) in MultipleAngles(sinePower, cosinePower))
            {
                var term = IntegrateAPolynomialTimesAnExponentialTimesOneTrigonometric(
                    (coefficient * polynomial).InnerSimplified, rate, (multiple * frequency).InnerSimplified,
                    isSine ? 0 : 1, isSine ? 1 : 0, x);
                if (term is null)
                    return null;
                total += term;
            }
            return total.InnerSimplified;
        }

        /// <summary>
        /// <c>sin^s cos^c</c> of one argument as a sum of sines and cosines of its multiples:
        /// each entry is a multiple, whether it is a sine, and its coefficient. Built by
        /// multiplying one sine or cosine in at a time through the product-to-sum identities,
        /// which keeps the count of terms linear in the powers.
        /// </summary>
        private static List<(int Multiple, bool IsSine, Entity Coefficient)> MultipleAngles(int sinePower, int cosinePower)
        {
            var terms = new Dictionary<(int, bool), Entity> { [(0, false)] = Number.Integer.One };
            void Add(int k, bool isSine, Entity coefficient)
            {
                // sin(-k t) = -sin(k t), cos(-k t) = cos(k t), sin(0) = 0.
                if (k < 0)
                {
                    k = -k;
                    if (isSine) coefficient = -coefficient;
                }
                if (k == 0 && isSine)
                    return;
                terms[(k, isSine)] = terms.TryGetValue((k, isSine), out var already) ? already + coefficient : coefficient;
            }
            for (var i = 0; i < sinePower + cosinePower; i++)
            {
                var bySine = i < sinePower;
                var next = new Dictionary<(int, bool), Entity>();
                var previous = terms;
                terms = next;
                foreach (var pair in previous)
                {
                    var (k, isSine) = pair.Key;
                    var half = (pair.Value / 2).InnerSimplified;
                    if (bySine)
                    {
                        // cos(k t) sin(t) = (sin((k+1) t) - sin((k-1) t))/2
                        // sin(k t) sin(t) = (cos((k-1) t) - cos((k+1) t))/2
                        if (!isSine) { Add(k + 1, true, half); Add(k - 1, true, -half); }
                        else { Add(k - 1, false, half); Add(k + 1, false, -half); }
                    }
                    else
                    {
                        // cos(k t) cos(t) = (cos((k-1) t) + cos((k+1) t))/2
                        // sin(k t) cos(t) = (sin((k+1) t) + sin((k-1) t))/2
                        if (!isSine) { Add(k - 1, false, half); Add(k + 1, false, half); }
                        else { Add(k + 1, true, half); Add(k - 1, true, half); }
                    }
                }
            }
            return terms.Select(pair => (pair.Key.Item1, pair.Key.Item2, pair.Value.InnerSimplified))
                        .Where(term => term.Item3 != Number.Integer.Zero)
                        .ToList();
        }

        /// <summary>
        /// A polynomial in sines and cosines of one linear, times a polynomial, over a whole power
        /// of a linear: <c>P(x) T(sin(a + b x), cos(a + b x))/(e + f x)^n</c>, onto the sine and
        /// cosine integrals. Each monomial <c>sin^s cos^c</c> of <c>T</c> is a sum of sines and
        /// cosines of multiples of the argument, and under <c>u = e + f x</c>, with
        /// <c>alpha = a - b e/f</c> and <c>k = b/f</c>, <c>sin(j (a + b x))</c> is
        /// <c>sin(j alpha) cos(j k u) + cos(j alpha) sin(j k u)</c> and the cosine likewise, so every
        /// term is <c>u^m sin(q u)</c> or <c>u^m cos(q u)</c>: elementary for <c>m >= 0</c>,
        /// <c>Si(q u)</c> and <c>Ci(q u)</c> for <c>m = -1</c>, which is their definition, and below
        /// that by parts toward them. The constant term an even power leaves is a power of <c>u</c>
        /// alone. Several linears below the bar are split into partial fractions over them, each
        /// term the question for one; and an argument <c>a + b x^r</c> beside a power of <c>x</c> is
        /// the same question under <c>u = x^r</c>, where <c>x^p dx</c> is <c>u^((p + 1)/r - 1) du/r</c>.
        /// Rubi's 4.1.10, <c>(c + d x)^m (a + b sin(e + f x))^n</c>, 4.1.11,
        /// <c>sin(c + d x)/(x^m (a + b x)^n)</c>, and 4.1.12, <c>(e x)^m (a + b sin(c + d x^n))^p</c>,
        /// with <c>m</c> negative.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// Only where a sine or cosine integral is left: otherwise the product is elementary, and
        /// the rules that write it shortest answer it.
        /// </remarks>
        internal static Entity? SolveATrigonometricOfALinearOverAPowerOfALinear(Entity expr, Entity.Variable x)
        {
            // A sine or a cosine of the variable, before anything is read.
            if (expr is not (Divf or Mulf or Powf or Sinf or Cosf) || ASineOrCosineArgument(expr, x) is not { } argument)
                return null;
            if (TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) && !TreeAnalyzer.IsZero(rate))
                return OverAPowerOfALinear(expr, x, argument);
            return UnderAPowerOfTheVariable(expr, x, argument);
        }

        // x - r, written x + |r| where the root is a negative number: x + 1 for the root -1.
        private static Entity LessTheRoot(Entity root, Entity.Variable x) =>
            root is Number.Complex { RealPart.IsNegative: true } or Number.Complex { RealPart.EDecimal.IsZero: true, ImaginaryPart.IsNegative: true }
                ? x + (-root).InnerSimplified : (x - root).InnerSimplified;

        // A quadratic divided by its leading coefficient, `x^2 + (b/a) x + c/a`, in the generic
        // case: the division declines a divisor with a condition on it.
        private static Entity Monic(Entity leading, Entity middle, Entity last, Entity.Variable x) =>
            Functions.PartialFractions.Bare((MathS.Sqr(x) + middle / leading * x + last / leading).InnerSimplified);

        // `a + b x^n` for an n of 3 or 4, as its leading coefficient, its n roots, and itself monic in
        // the generic case. The roots are `(a/b)^(1/n)` times the n-th roots of -1, `e^(i pi (2k + 1)/n)`:
        // only their n-th power is used, so they are the roots whichever branch the n-th root takes.
        private static (Entity Leading, Entity[] Roots, Entity Monic)? TheRootsOfABinomial(Entity binomial, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(binomial, x, out var terms) || terms.Count != 2
                || !terms.TryGetValue(EInteger.Zero, out var free) || free.ContainsNode(x) || TreeAnalyzer.IsZero(free))
                return null;
            var top = terms.First(term => !term.Key.IsZero);
            if (top.Value.ContainsNode(x) || TreeAnalyzer.IsZero(top.Value) || !top.Key.CanFitInInt32() || top.Key.ToInt32Checked() is not (3 or 4))
                return null;
            var n = top.Key.ToInt32Checked();
            var scale = MathS.Pow(Functions.PartialFractions.InLowestTermsOverTheSymbols(free / top.Value), Number.Rational.Create(1, n));
            Entity[] rootsOfMinusOne = n == 3
                ? new Entity[] { -1, (1 + MathS.i * MathS.Sqrt(3)) / 2, (1 - MathS.i * MathS.Sqrt(3)) / 2 }
                : new Entity[] { (1 + MathS.i) / MathS.Sqrt(2), (1 - MathS.i) / MathS.Sqrt(2), (-1 + MathS.i) / MathS.Sqrt(2), (-1 - MathS.i) / MathS.Sqrt(2) };
            return (top.Value, rootsOfMinusOne.Select(root => (root * scale).InnerSimplified).ToArray(),
                Functions.PartialFractions.Bare((MathS.Pow(x, n) + free / top.Value).InnerSimplified));
        }

        /// <summary>
        /// <paramref name="numerator"/> over a denominator as terms each over one linear: the
        /// polynomial part first, divided by the denominator as it is <paramref name="written"/>,
        /// and the proper rest split into partial fractions over <paramref name="overTheLinears"/>,
        /// the same denominator with each quadratic in it written as the linears of its roots.
        /// Divided by those linears, `x^2` over `(x - r)(x + r)`, `r = sqrt(-a/b)`, left a remainder
        /// in `r^2` that nothing read as `-a/b`. Only where the fraction is not proper already:
        /// divided, `x` over `(c + d x)(x - 2)` came back as a quotient and a remainder
        /// `2 provided not c + d x = 0`, which nothing splits. Null where the split declines.
        /// </summary>
        private static List<Entity>? OverEachLinear(Entity numerator, Entity written, Entity overTheLinears, int degreeBelow, Entity.Variable x)
        {
            var terms = new List<Entity>();
            if (numerator.ContainsNode(x)
                && TreeAnalyzer.TryGetPolynomial(numerator, x, out var monomialsAbove)
                && monomialsAbove.Keys.Any(degree => degree.CompareTo(EInteger.FromInt32(degreeBelow)) >= 0)
                && TreeAnalyzer.PolynomialLongDivision(numerator, written, genericCase: true, inTermsOf: x) is var (quotient, remainder))
            {
                if (!TreeAnalyzer.IsZero(quotient))
                    terms.Add(quotient);
                // The remainder comes over the divisor already.
                numerator = remainder is Divf(var left, _) ? left : (numerator - quotient * written).Expand().InnerSimplified;
            }
            if (!TreeAnalyzer.IsZero(numerator))
            {
                if (!Functions.PartialFractions.TrySplitOverWrittenFactors(numerator, overTheLinears, x, out var decomposition))
                    return null;
                // The sum of the fractions, over a constant it may come divided by.
                var fractions = decomposition.InnerSimplified;
                if (fractions is Divf(var over, var by) && !by.ContainsNode(x))
                    fractions = Sumf.LinearChildren(over).Aggregate((Entity)Number.Integer.Zero, (all, one) => all + one / by);
                terms.AddRange(Sumf.LinearChildren(fractions));
            }
            return terms;
        }

        /// <summary>
        /// <see cref="SolveATrigonometricOfALinearOverAPowerOfALinear"/> where the argument is
        /// <paramref name="argument"/>, linear in <paramref name="x"/>. Two or more linears below
        /// the bar are split into partial fractions over them first, each term the one-linear
        /// question.
        /// </summary>
        private static Entity? OverAPowerOfALinear(Entity expr, Entity.Variable x, Entity argument)
        {
            var (sine, cosine) = (MathS.Sin(argument), MathS.Cos(argument));
            var (tangent, cotangent, secant, cosecant) = (MathS.Tan(argument), MathS.Cotan(argument), MathS.Sec(argument), MathS.Cosec(argument));
            var s = Variable.CreateUnique(expr, "s");
            var c = Variable.CreateUnique(expr + s, "c");
            Entity constant = Number.Integer.One;
            var linears = new List<(Entity Linear, int Power)>();
            Entity? polynomial = null;
            Entity? trigonometric = null;
            // The denominator as it is written, each quadratic monic, for the division.
            Entity written = Number.Integer.One;
            void AddALinear(Entity linear, int power)
            {
                var at = linears.FindIndex(pair => pair.Linear == linear);
                if (at < 0)
                    linears.Add((linear, power));
                else
                    linears[at] = (linear, linears[at].Power + power);
            }
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                // A polynomial in the sine and the cosine, above the bar, the other four written as
                // quotients of the two: `tan(u) cos(u)^2`, which the substitution x = tan(u)
                // leaves, is `s c`, and what is not a polynomial after that is declined below.
                if (factor.ContainsNode(sine) || factor.ContainsNode(cosine) || factor.ContainsNode(tangent)
                    || factor.ContainsNode(cotangent) || factor.ContainsNode(secant) || factor.ContainsNode(cosecant))
                {
                    var read = factor.Replace(node =>
                        node == sine ? s : node == cosine ? c : node == tangent ? s / c : node == cotangent ? c / s
                        : node == secant ? 1 / c : node == cosecant ? 1 / s : node);
                    if (read.ContainsNode(x))
                        return null;
                    read = underneath ? 1 / read : read;
                    trigonometric = trigonometric is null ? read : trigonometric * read;
                    continue;
                }
                var (@base, exponent) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath)
                    exponent = -exponent;
                // A linear, or a whole power of one, below the bar or as a negative power.
                if (exponent < 0)
                {
                    if (TreeAnalyzer.TryGetPolyLinear(@base, x, out var slopeOfIt, out _) && !TreeAnalyzer.IsZero(slopeOfIt))
                    {
                        AddALinear(@base, -exponent);
                        written *= MathS.Pow(@base, -exponent);
                    }
                    // A quadratic is its leading coefficient times the linears of its two roots,
                    // complex where its discriminant is negative: `sin(c + d x)/(a + b x^2)` is a
                    // sum over `x -/+ sqrt(-a/b)`, each the one-linear question, and the sine and
                    // cosine integrals of the two conjugate arguments add up to a real answer.
                    else if (TreeAnalyzer.TryGetPolyQuadratic(@base, x, out var leading, out var middle, out var last) && !TreeAnalyzer.IsZero(leading))
                    {
                        var discriminant = MathS.Sqrt(middle * middle - 4 * leading * last);
                        var first = ((-middle + discriminant) / (2 * leading)).InnerSimplified;
                        var second = ((-middle - discriminant) / (2 * leading)).InnerSimplified;
                        constant /= MathS.Pow(leading, -exponent);
                        AddALinear(LessTheRoot(first, x), -exponent);
                        AddALinear(LessTheRoot(second, x), -exponent);
                        written *= MathS.Pow(Monic(leading, middle, last, x), -exponent);
                    }
                    // And a binomial past the quadratic the linears of its roots: `sin(c + d x)/(a + b x^3)`.
                    else if (TheRootsOfABinomial(@base, x) is { } binomial)
                    {
                        constant /= MathS.Pow(binomial.Leading, -exponent);
                        foreach (var root in binomial.Roots)
                            AddALinear(LessTheRoot(root, x), -exponent);
                        written *= MathS.Pow(binomial.Monic, -exponent);
                    }
                    else
                        return null;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                {
                    polynomial = polynomial is null ? factor : polynomial * factor;
                    continue;
                }
                return null;
            }
            if (trigonometric is null || linears.Count == 0 || linears.Count > 4 || linears.Sum(pair => pair.Power) > 12
                || MultipleAnglesOf(trigonometric, s, c) is not { } angles)
                return null;
            if (linears.Count == 1)
                return AgainstAPowerOfALinear(polynomial, linears[0].Linear, linears[0].Power, angles, argument, x, needsAnIntegral: true) is var (one, _) && one is not null
                    ? Functions.PartialFractions.Bare((constant * one).InnerSimplified)
                    : null;
            // Over each linear by partial fractions, and each term the one-linear question.
            var denominator = linears.Aggregate((Entity)Number.Integer.One, (product, pair) => product * MathS.Pow(pair.Linear, pair.Power));
            if (OverEachLinear(polynomial ?? Number.Integer.One, written, denominator, linears.Sum(pair => pair.Power), x) is not { } terms)
                return null;
            Entity sum = Number.Integer.Zero;
            var special = false;
            foreach (var term in terms)
            {
                var (above, linear, power) = OverOneLinear(term, x);
                var (integral, integrals) = AgainstAPowerOfALinear(above, linear, power, angles, argument, x, needsAnIntegral: false);
                if (integral is null)
                    return null;
                sum += integral;
                special |= integrals;
            }
            return special ? Functions.PartialFractions.Bare((constant * sum).InnerSimplified) : null;
        }

        /// <summary>
        /// A term of a partial-fraction decomposition as what is above the bar, the linear below
        /// it and its power, or the term itself above and no linear.
        /// </summary>
        private static (Entity Above, Entity? Linear, int Power) OverOneLinear(Entity term, Entity.Variable x)
        {
            Entity above = Number.Integer.One;
            Entity? linear = null;
            var power = 0;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(term))
            {
                var (@base, exponent) = factor is Powf(var raised, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                    ? (raised, whole.EInteger.ToInt32Checked()) : (factor, 1);
                if (underneath)
                    exponent = -exponent;
                if (exponent < 0 && @base.ContainsNode(x) && (linear is null || linear == @base))
                {
                    linear = @base;
                    power -= exponent;
                }
                else
                    above = underneath ? above / factor : above * factor;
            }
            return (above, linear, power);
        }

        /// <summary>
        /// <c>T</c>, a polynomial in <paramref name="s"/> and <paramref name="c"/> standing for
        /// the sine and the cosine of one argument, as sines and cosines of multiples of it: each
        /// entry a multiple, whether a sine, and its coefficient, the multiple 0 standing for 1.
        /// </summary>
        private static Dictionary<(int Multiple, bool IsSine), Entity>? MultipleAnglesOf(Entity trigonometric, Entity.Variable s, Entity.Variable c)
        {
            if (!TreeAnalyzer.TryGetPolynomial(trigonometric, s, out var inTheSine))
                return null;
            var angles = new Dictionary<(int Multiple, bool IsSine), Entity>();
            foreach (var ofOnePower in inTheSine)
            {
                var (sines, ofTheSines) = (ofOnePower.Key, ofOnePower.Value);
                if (sines.Sign < 0 || !sines.CanFitInInt32() || !TreeAnalyzer.TryGetPolynomial(ofTheSines, c, out var inTheCosine))
                    return null;
                foreach (var term in inTheCosine)
                {
                    var (cosines, coefficient) = (term.Key, term.Value);
                    if (cosines.Sign < 0 || !cosines.CanFitInInt32() || coefficient.ContainsNode(s) || coefficient.ContainsNode(c)
                        || sines.ToInt32Checked() + cosines.ToInt32Checked() > MaximumTrigonometricPower)
                        return null;
                    var (sinePower, cosinePower) = (sines.ToInt32Checked(), cosines.ToInt32Checked());
                    var terms = (sinePower + cosinePower) switch
                    {
                        0 => new List<(int Multiple, bool IsSine, Entity Coefficient)> { (0, false, Number.Integer.One) },
                        1 => new List<(int Multiple, bool IsSine, Entity Coefficient)> { (1, sinePower == 1, Number.Integer.One) },
                        _ => MultipleAngles(sinePower, cosinePower),
                    };
                    foreach (var (multiple, isSine, weight) in terms)
                        angles[(multiple, isSine)] = angles.TryGetValue((multiple, isSine), out var already)
                            ? already + coefficient * weight : coefficient * weight;
                }
            }
            return angles;
        }

        /// <summary>
        /// <c>int P(x) T(x)/L^n dx</c>, with <c>T</c> given by its multiple angles and <c>L</c> a
        /// linear or, where <paramref name="linear"/> is <see langword="null"/>, <c>x</c> and
        /// <c>n = 0</c>; and whether a sine or cosine integral is left in it. Where
        /// <paramref name="needsAnIntegral"/> and none is, the answer is left to other rules.
        /// </summary>
        private static (Entity? Integral, bool Special) AgainstAPowerOfALinear(Entity? polynomial, Entity? linear, int power,
            Dictionary<(int Multiple, bool IsSine), Entity> angles, Entity argument, Entity.Variable x, bool needsAnIntegral)
        {
            linear ??= x;
            if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var f, out var e)
                || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var b, out var a))
                return (null, false);
            var u = Variable.CreateUnique(linear + argument + (polynomial ?? Number.Integer.One), "u");
            var inU = polynomial is null ? Number.Integer.One : polynomial.Substitute(x, (u - e) / f);
            if (!TreeAnalyzer.TryGetPolynomial(inU, u, out var powers) || powers.Keys.Any(degree => !degree.CanFitInInt32())
                || needsAnIntegral && powers.Keys.All(degree => degree.CompareTo(EInteger.FromInt32(power)) >= 0))
                return (null, false);
            var alpha = (a - b * e / f).InnerSimplified;
            var rateInU = (b / f).InnerSimplified;
            Entity sum = Number.Integer.Zero;
            var special = false;
            foreach (var angle in angles)
            {
                var ((multiple, isSine), coefficient) = (angle.Key, angle.Value);
                if (multiple == 0)
                {
                    // What even powers leave: a Laurent polynomial in u.
                    foreach (var monomial in powers)
                    {
                        var m = monomial.Key.ToInt32Checked() - power;
                        sum += coefficient * monomial.Value * (m == -1 ? MathS.Ln(u) : MathS.Pow(u, m + 1) / (m + 1));
                    }
                    continue;
                }
                // sin(j alpha + q u) = sin(j alpha) cos(q u) + cos(j alpha) sin(q u), and the
                // cosine's; a negative q turned positive, since sin(-y) = -sin(y) and
                // cos(-y) = cos(y), so that Ci is asked a positive argument where u is.
                var phase = (multiple * alpha).InnerSimplified;
                var (sineOfThePhase, cosineOfThePhase) = phase.Evaled is Number.Real { IsNegative: true }
                    ? (-MathS.Sin((-phase).InnerSimplified), MathS.Cos((-phase).InnerSimplified))
                    : (MathS.Sin(phase), MathS.Cos(phase));
                var (onTheSine, onTheCosine) = isSine
                    ? (cosineOfThePhase, sineOfThePhase)
                    : (-sineOfThePhase, cosineOfThePhase);
                var frequency = (multiple * rateInU).InnerSimplified;
                if (frequency.Evaled is Number.Real { IsNegative: true })
                    (frequency, onTheSine) = ((-frequency).InnerSimplified, -onTheSine);
                Entity elementary = Number.Integer.Zero, si = Number.Integer.Zero, ci = Number.Integer.Zero;
                foreach (var monomial in powers)
                {
                    var m = monomial.Key.ToInt32Checked() - power;
                    var ofTheSine = APowerTimesASineOrACosine(m, sine: true, frequency, u);
                    var ofTheCosine = APowerTimesASineOrACosine(m, sine: false, frequency, u);
                    elementary += monomial.Value * (onTheSine * ofTheSine.Elementary + onTheCosine * ofTheCosine.Elementary);
                    si += monomial.Value * (onTheSine * ofTheSine.Si + onTheCosine * ofTheCosine.Si);
                    ci += monomial.Value * (onTheSine * ofTheSine.Ci + onTheCosine * ofTheCosine.Ci);
                }
                (si, ci) = ((coefficient * si).InnerSimplified, (coefficient * ci).InnerSimplified);
                special |= !TreeAnalyzer.IsZero(si) || !TreeAnalyzer.IsZero(ci);
                sum += coefficient * elementary + si * MathS.Si(frequency * u) + ci * MathS.Ci(frequency * u);
            }
            if (needsAnIntegral && !special)
                return (null, false);
            return ((sum / f).Substitute(u, linear).InnerSimplified, special);
        }

        /// <summary>
        /// <see cref="SolveATrigonometricOfALinearOverAPowerOfALinear"/> where the argument is
        /// <c>a + b x^r</c>, beside a power of <paramref name="x"/>: under <c>u = x^r</c>,
        /// <c>x^p T(sin(a + b x^r), cos(a + b x^r)) dx</c> is <c>u^((p + 1)/r - 1) T(sin(a + b u), cos(a + b u)) du/r</c>.
        /// </summary>
        private static Entity? UnderAPowerOfTheVariable(Entity expr, Entity.Variable x, Entity argument)
        {
            // r, from x^r, b/x or b/x^k in the argument.
            Entity? r = null;
            foreach (var node in argument.Nodes)
            {
                Entity? candidate = node switch
                {
                    Powf(var @base, var exponent) when @base == x && !exponent.ContainsNode(x) => exponent,
                    Divf(var above, var below) when below == x && !above.ContainsNode(x) => Number.Integer.MinusOne,
                    Divf(var above, Powf(var @base, var exponent)) when @base == x && !above.ContainsNode(x) && !exponent.ContainsNode(x) => -exponent,
                    _ => null,
                };
                if (candidate is null)
                    continue;
                if (r is not null && r != candidate)
                    return null;
                r = candidate;
            }
            if (r is null || TreeAnalyzer.IsZero(r))
                return null;
            var u = Variable.CreateUnique(expr, "u");
            // x^r written as u where it was read, rather than x as u^(1/r): (u^(1/n))^n is not
            // folded for a symbolic n.
            var argumentInU = argument.Replace(node => node switch
            {
                Powf(var @base, var exponent) when @base == x && exponent == r => u,
                Divf(var above, var below) when below == x && r == Number.Integer.MinusOne => above * u,
                Divf(var above, Powf(var @base, var exponent)) when @base == x && (-exponent) == r => above * u,
                _ => node,
            }).InnerSimplified;
            if (argumentInU.ContainsNode(x) || !TreeAnalyzer.TryGetPolyLinear(argumentInU, u, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                return null;
            var (sine, cosine) = (MathS.Sin(argument), MathS.Cos(argument));
            Entity constant = Number.Integer.One;
            Entity p = Number.Integer.Zero;
            Entity trigonometric = Number.Integer.One;
            var sawOne = false;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                    constant = underneath ? constant / factor : constant * factor;
                else if (factor == x)
                    p += underneath ? -1 : 1;
                else if (factor is Powf(var @base, var exponent) && @base == x && !exponent.ContainsNode(x))
                    p += underneath ? -exponent : exponent;
                else if (!underneath && (factor.ContainsNode(sine) || factor.ContainsNode(cosine)))
                {
                    var inU = factor.Replace(node => node == sine ? MathS.Sin(argumentInU) : node == cosine ? MathS.Cos(argumentInU) : node);
                    if (inU.ContainsNode(x))
                        return null;
                    trigonometric *= inU;
                    sawOne = true;
                }
                else
                    return null;
            }
            // Only a whole power of u leaves the shape the linear case reads.
            // Simplified, since a symbolic r cancels only there: x^(-1 - r) leaves -r/r - 1, and
            // bare, since the cancellation holds where r is not 0, which it is not here.
            if (!sawOne || Functions.PartialFractions.Bare(((p + 1) / r - 1).Simplify()) is not Number.Integer { EInteger: var whole }
                || !whole.CanFitInInt32() || whole.Sign >= 0)
                return null;
            var integrand = constant / r * MathS.Pow(u, whole.ToInt32Checked()) * trigonometric;
            return OverAPowerOfALinear(integrand, u, argumentInU)?.Substitute(u, MathS.Pow(x, r)).InnerSimplified;
        }

        /// <summary>
        /// <c>int u^m sin(q u) du</c>, or the cosine's, as its elementary part and the coefficients
        /// of <c>Si(q u)</c> and <c>Ci(q u)</c> in it: <c>Si(q u)</c> and <c>Ci(q u)</c> themselves for
        /// <c>m = -1</c>; below that
        /// <c>int u^m sin(q u) = u^(m + 1) sin(q u)/(m + 1) - q/(m + 1) int u^(m + 1) cos(q u)</c> and
        /// <c>int u^m cos(q u) = u^(m + 1) cos(q u)/(m + 1) + q/(m + 1) int u^(m + 1) sin(q u)</c>; and
        /// above it <c>-u^m cos(q u)/q + m/q int u^(m - 1) cos(q u)</c> and
        /// <c>u^m sin(q u)/q - m/q int u^(m - 1) sin(q u)</c>, all by parts.
        /// </summary>
        private static (Entity Elementary, Entity Si, Entity Ci) APowerTimesASineOrACosine(int m, bool sine, Entity q, Entity.Variable u)
        {
            if (m == -1)
                return sine
                    ? (Number.Integer.Zero, Number.Integer.One, Number.Integer.Zero)
                    : (Number.Integer.Zero, Number.Integer.Zero, Number.Integer.One);
            if (m < -1)
            {
                var (elementary, si, ci) = APowerTimesASineOrACosine(m + 1, !sine, q, u);
                var by = (sine ? -q / (m + 1) : q / (m + 1)).InnerSimplified;
                // u^(m + 1)/(m + 1), written as -1/(|m + 1| u^|m + 1|)
                var written = -(sine ? MathS.Sin(q * u) : MathS.Cos(q * u)) / (-(m + 1) * MathS.Pow(u, -(m + 1)));
                return ((written + by * elementary).InnerSimplified, (by * si).InnerSimplified, (by * ci).InnerSimplified);
            }
            var first = sine ? -MathS.Pow(u, m) * MathS.Cos(q * u) / q : MathS.Pow(u, m) * MathS.Sin(q * u) / q;
            if (m == 0)
                return (first.InnerSimplified, Number.Integer.Zero, Number.Integer.Zero);
            var (below, _, _) = APowerTimesASineOrACosine(m - 1, !sine, q, u);
            return ((first + (sine ? m / q : -m / q) * below).InnerSimplified, Number.Integer.Zero, Number.Integer.Zero);
        }

        /// <summary>
        /// The argument of a sine or a cosine of <paramref name="x"/> among the factors of
        /// <paramref name="expr"/>, above the bar and read through whole powers and sums, or
        /// <see langword="null"/>.
        /// </summary>
        private static Entity? ASineOrCosineArgument(Entity expr, Entity.Variable x) => expr switch
        {
            Sinf(var argument) when argument.ContainsNode(x) => argument,
            Cosf(var argument) when argument.ContainsNode(x) => argument,
            Tanf(var argument) when argument.ContainsNode(x) => argument,
            Cotanf(var argument) when argument.ContainsNode(x) => argument,
            Secantf(var argument) when argument.ContainsNode(x) => argument,
            Cosecantf(var argument) when argument.ContainsNode(x) => argument,
            Powf(var @base, Number.Integer) => ASineOrCosineArgument(@base, x),
            Mulf(var left, var right) => ASineOrCosineArgument(left, x) ?? ASineOrCosineArgument(right, x),
            Divf(var numerator, var denominator) => ASineOrCosineArgument(numerator, x) ?? ASineOrCosineArgument(denominator, x),
            Sumf(var left, var right) => ASineOrCosineArgument(left, x) ?? ASineOrCosineArgument(right, x),
            Minusf(var left, var right) => ASineOrCosineArgument(left, x) ?? ASineOrCosineArgument(right, x),
            _ => null,
        };

        /// <summary>
        /// <c>int P(x) e^(a x) (c cos(b x) + d sin(b x)) dx</c>, closed by as many rounds of parts
        /// as <c>P</c> has degree.
        /// </summary>
        private static Entity? IntegrateAPolynomialTimesAnExponentialTimesOneTrigonometric(
            Entity polynomial, Entity rate, Entity frequency, Entity onTheCosine, Entity onTheSine, Entity.Variable x)
        {
            // a^2 + b^2, which is zero when both are, and then the integrand is a polynomial --
            // and when the rate is the frequency times i: `e^(-i u) cos(u)` is
            // `(1 + e^(-2 i u))/2`, a resonance the formula divides by zero on, and it answered
            // NaN for `e^(-i arctan(a x))/(c + a^2 c x^2)^(3/2)` under `x = tan(u)/a`.
            var scale = (MathS.Sqr(rate) + MathS.Sqr(frequency)).InnerSimplified;
            var bothZero = rate.Evaled is Number.Complex { IsZero: true } && frequency.Evaled is Number.Complex { IsZero: true };
            if (bothZero)
                return null;
            var exponential = MathS.Pow(MathS.e, rate * x);
            var cosine = MathS.Cos(frequency * x);
            var sine = MathS.Sin(frequency * x);
            // Symbolically as well as numerically: with a symbolic frequency `f` the rate `-i f`
            // leaves `-f^2 + f^2`, which `InnerSimplified` does not collect.
            if (scale == 0 || scale.Evaled is Number.Complex { IsZero: true }
                || scale.Vars.Any() && Functions.PartialFractions.Bare(scale.Simplify()).Evaled is Number.Complex { IsZero: true })
            {
                // Resonant: by Euler, `c cos(bx) + d sin(bx)` is
                // `(c - i d) e^(i b x)/2 + (c + i d) e^(-i b x)/2`, and each term beside
                // `P(x) e^(a x)` is a polynomial times one exponential -- one of them, with
                // `a = -i b` or `a = i b`, a polynomial alone -- which are closed on their own.
                // `e^(i arctan(a x))/sqrt(c + a^2 c x^2)` under `x = tan(u)/a` is `e^(i u) cos(u)`.
                var plus = ((onTheCosine - MathS.i * onTheSine) / 2).InnerSimplified;
                var minus = ((onTheCosine + MathS.i * onTheSine) / 2).InnerSimplified;
                Entity resonant = Number.Integer.Zero;
                foreach (var (coefficient, exponent) in new[] { (plus, (rate + MathS.i * frequency).InnerSimplified), (minus, (rate - MathS.i * frequency).InnerSimplified) })
                {
                    if (coefficient.Evaled is Number.Complex { IsZero: true })
                        continue;
                    var term = exponent.Evaled is Number.Complex { IsZero: true } ? polynomial : polynomial * MathS.Pow(MathS.e, exponent * x);
                    if (Integration.ComputeIndefiniteIntegral(term.InnerSimplified, x, integrateByParts: false) is not { } termIntegral || termIntegral.Nodes.Any(node => node == MathS.NaN))
                        return null;
                    resonant += coefficient * termIntegral;
                }
                return resonant.InnerSimplified;
            }

            // Integrating `e^(ax)(c cos + d sin)` leaves the same shape, so one step of by parts
            // against `P(x)` lowers its degree and leaves this loop's own state: a polynomial and
            // the pair of coefficients. `total` collects the boundary terms.
            Entity total = 0;
            var carried = polynomial;
            var c = onTheCosine;
            var d = onTheSine;
            for (var step = 0; ; step++)
            {
                if (step > MaximumByPartsSteps)
                    return null;   // the degree should fall every round; if it has not, decline
                // int e^(ax) cos(bx) = e^(ax)(a cos + b sin)/(a^2+b^2), and
                // int e^(ax) sin(bx) = e^(ax)(a sin - b cos)/(a^2+b^2). Together, for
                // `c cos + d sin`, the cosine collects `a c - b d` and the sine `b c + a d`.
                var nextC = ((rate * c - frequency * d) / scale).InnerSimplified;
                var nextD = ((frequency * c + rate * d) / scale).InnerSimplified;
                var antiderivative = exponential * (nextC * cosine + nextD * sine);

                total += carried * antiderivative;
                // Bare: a constant factor with symbols in it differentiates to a *conditional*
                // zero -- `F^(a c)` gives `0 provided not F = 0 or a c > 0` -- and the loop,
                // comparing against the number, carried on until it ran out of steps and
                // declined. The conditions are the constant's own and travel with it in the
                // answer; what the loop asks is whether the degree has fallen to nothing.
                var derivative = Functions.PartialFractions.Bare(carried.Differentiate(x).InnerSimplified);
                if (derivative == 0 || derivative.Evaled is Number.Complex { IsZero: true })
                    return total.InnerSimplified;
                // `- int P'(x) * (that) dx`, which is this loop again with the sign folded in.
                carried = (-derivative).InnerSimplified;
                c = nextC;
                d = nextD;
            }
        }

        /// <summary>
        /// How many rounds of by parts are admitted before the rule gives up on its own
        /// termination. The degree of the polynomial falls every round, so a polynomial this rule
        /// accepted cannot reach it; it is a backstop against a <c>Differentiate</c> that does not
        /// lower the degree rather than a bound on anything expected.
        /// </summary>
        private const int MaximumByPartsSteps = 64;

        /// <summary>
        /// The largest total power of the sine and the cosine the rule expands into multiple
        /// angles; past it the sum has more terms than any answer is worth.
        /// </summary>
        private const int MaximumTrigonometricPower = 8;

        /// <summary>
        /// Reads <paramref name="expr"/> as <c>P(x) e^(a x) (c cos(b x) + d sin(b x))</c>, where
        /// <c>P</c> is a polynomial and <c>a</c> and <c>b</c> are free of the variable.
        /// </summary>
        /// <remarks>
        /// A base other than <c>e</c> is read through: <c>2^x</c> is <c>e^(x ln 2)</c>, so
        /// <c>2^x x cos(x)</c> is this shape and was declined for the spelling alone.
        /// </remarks>
        private static bool TryReadAnExponentialTimesATrigonometric(
            Entity expr, Entity.Variable x, out Entity polynomial,
            out Entity rate, out Entity frequency, out int sinePower, out int cosinePower)
        {
            polynomial = 1;
            rate = 0;
            frequency = 0;
            sinePower = 0;
            cosinePower = 0;

            Entity? rateFound = null;
            Entity? frequencyFound = null;
            var cosines = 0;
            var sines = 0;
            Entity polynomialPart = 1;
            if (!Read(expr, 1))
                return false;
            // Powers of the sine and the cosine, of one argument, above the bar: a reciprocal
            // sine or cosine is a different integrand. A secant or a cosecant *below* the bar is
            // a cosine or a sine above it and is read as one.
            if (cosines < 0 || sines < 0 || cosines + sines > MaximumTrigonometricPower)
                return false;
            var asPolynomial = ThePolynomialIn(polynomialPart, x);
            if (asPolynomial is null && polynomialPart.ContainsNode(x))
                return false;

            polynomial = polynomialPart.ContainsNode(x) ? asPolynomial! : polynomialPart;
            rate = rateFound ?? 0;
            frequency = frequencyFound ?? 0;
            sinePower = sines;
            cosinePower = cosines;
            // A bare polynomial is the power rule's, and a polynomial times a bare exponential or
            // a bare sine already came out; what is new is the two together. Reading them all the
            // same way costs nothing and keeps the rule one thing.
            return rateFound is not null || frequencyFound is not null;

            bool Read(Entity node, int multiplicity)
            {
                switch (node)
                {
                    case Sinf(var argument) when multiplicity == 1:
                        sines++;
                        return AgreesOnTheFrequency(argument);
                    case Cosf(var argument) when multiplicity == 1:
                        cosines++;
                        return AgreesOnTheFrequency(argument);
                    case Cosecantf(var argument) when multiplicity == -1:
                        sines++;
                        return AgreesOnTheFrequency(argument);
                    case Secantf(var argument) when multiplicity == -1:
                        cosines++;
                        return AgreesOnTheFrequency(argument);
                    case Powf(Sinf(var argument), Number.Integer power) when multiplicity == 1 && power.EInteger.Sign > 0 && power.EInteger.CanFitInInt32():
                        sines += power.EInteger.ToInt32Unchecked();
                        return AgreesOnTheFrequency(argument);
                    case Powf(Cosf(var argument), Number.Integer power) when multiplicity == 1 && power.EInteger.Sign > 0 && power.EInteger.CanFitInInt32():
                        cosines += power.EInteger.ToInt32Unchecked();
                        return AgreesOnTheFrequency(argument);
                    case Powf(Cosecantf(var argument), Number.Integer power) when multiplicity == -1 && power.EInteger.Sign > 0 && power.EInteger.CanFitInInt32():
                        sines += power.EInteger.ToInt32Unchecked();
                        return AgreesOnTheFrequency(argument);
                    case Powf(Secantf(var argument), Number.Integer power) when multiplicity == -1 && power.EInteger.Sign > 0 && power.EInteger.CanFitInInt32():
                        cosines += power.EInteger.ToInt32Unchecked();
                        return AgreesOnTheFrequency(argument);
                    case Powf(var @base, var power)
                        when !@base.ContainsNode(x) && power.ContainsNode(x) && @base != 0:
                        // e^(ax), and any other base through its logarithm.
                        if (!TreeAnalyzer.TryGetPolyLinear(power, x, out var slope, out var offset))
                            return false;
                        var thisRate = (slope * (@base == MathS.e ? 1 : MathS.Ln(@base))).InnerSimplified;
                        rateFound = rateFound is null
                            ? (multiplicity * thisRate).InnerSimplified
                            : (rateFound + multiplicity * thisRate).InnerSimplified;
                        // The constant part of the exponent is a factor, not a rate -- and there
                        // is none to take when the exponent has no constant part. `MathS.Pow`
                        // leaves `b^0` written out, and a factor of `d^0` standing in front of
                        // the polynomial is enough to stop `TryPolynomial` reading it, so
                        // `d^x x cos(x)` was declined where `2^x x cos(x)` came out: with a
                        // numeric base the same dead factor is folded away and with a symbolic
                        // one it is not. `d^x cos(x)` hid it, because a polynomial part free of
                        // the variable is never read as a polynomial at all.
                        // https://github.com/asc-community/AngouriMath/issues/718
                        if (offset.Evaled is not Number.Integer(0))
                            polynomialPart *= MathS.Pow(@base, offset * multiplicity);
                        return true;
                    case Mulf(var left, var right):
                        return Read(left, multiplicity) && Read(right, multiplicity);
                    case Divf(var above, var below):
                        return Read(above, multiplicity) && Read(below, -multiplicity);
                    default:
                        if (multiplicity != 1)
                            return false;
                        polynomialPart *= node;
                        return true;
                }
            }

            bool AgreesOnTheFrequency(Entity argument)
            {
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset)
                    || offset.Evaled is not Number.Integer(0))
                    return false;   // a phase would want the angle-sum identity first
                if (frequencyFound is not null && frequencyFound != slope)
                    return false;
                frequencyFound = slope;
                return true;
            }
        }

        /// <summary>
        /// A power of the variable times an odd half-power of a quadratic without a linear term —
        /// <c>x^m (a + b x^2)^(k/2)</c> with <c>k</c> odd — turned into a power of the sine times
        /// a power of the cosine, which
        /// <see cref="IntegrateAPowerOfSineTimesAPowerOfCosine"/> answers in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(1 + x^2)^(3/2)</c>, <c>x^5/sqrt(5 + x^2)</c>, <c>1/(x^2 sqrt(1 - x^2))</c> and
        /// their kin had no antiderivative. A square root of a quadratic is the largest single
        /// class the Rubi suites leave unanswered here, and this is the part of it that comes out
        /// <b>closed</b>.
        /// </para>
        /// <para>
        /// <b>Why the trigonometric substitution rather than Euler's.</b> Euler's rationalises the
        /// radical and lands on a rational function, which then has to be integrated by the whole
        /// chain — a speculative hand-off that
        /// <a href="https://github.com/asc-community/AngouriMath/issues/1244">#1244</a> measured
        /// at tens of seconds on integrands it never answers. This lands on <c>sin^p cos^q</c>,
        /// which is a Laurent polynomial after one more substitution and is integrated term by
        /// term without asking the integrator anything. Same class of integrand; one of the two
        /// routes is closed and the other is a search.
        /// </para>
        /// <para>
        /// <b>Three substitutions, chosen by the two signs.</b> With <c>r = sqrt(|a/b|)</c>:
        /// </para>
        /// <list type="bullet">
        /// <item><description>
        /// <c>a &gt; 0, b &gt; 0</c>: <c>x = r tan(t)</c>, under which <c>a + b x^2 = a sec(t)^2</c>
        /// and <c>dx = r sec(t)^2 dt</c>, leaving <c>sin(t)^m cos(t)^(-m-k-2)</c>.
        /// </description></item>
        /// <item><description>
        /// <c>a &gt; 0, b &lt; 0</c>: <c>x = r sin(t)</c>, under which <c>a + b x^2 = a cos(t)^2</c>
        /// and <c>dx = r cos(t) dt</c>, leaving <c>sin(t)^m cos(t)^(k+1)</c>.
        /// </description></item>
        /// <item><description>
        /// <c>a &lt; 0, b &gt; 0</c>: <c>x = r sec(t)</c>, added in
        /// <a href="https://github.com/asc-community/AngouriMath/pull/1277">#1277</a>. Its domain
        /// is two intervals rather than one, and the sign that makes the second one right is
        /// written out in <see cref="IntegrateAPowerTimesARadicalQuadratic"/>.
        /// </description></item>
        /// </list>
        /// <para>
        /// Both signs negative is a radicand negative everywhere, with no real integrand to
        /// integrate, and there is no fourth case.
        /// </para>
        /// <para>
        /// <b>Coming back.</b> The answer arrives in <c>sin(t)</c>, <c>cos(t)</c> and
        /// <c>tan(t)</c>, each of which is algebraic in <c>x</c> under the substitution, and in
        /// <c>t</c> itself wherever the recursion bottoms out on <c>int 1 dt</c> — which is where
        /// an <c>arcsin</c> or an <c>arctan</c> enters an otherwise algebraic answer.
        /// </para>
        /// <para>
        /// <b>Volunteered, and deliberately so</b> — this is the one rule of the five that is not
        /// scoped to <see cref="Integration.AnsweringTheQuestionAsked"/>. Scope is right for a
        /// rule whose answers only ever let some other search carry on into ground that was
        /// doomed, which is what
        /// <a href="https://github.com/asc-community/AngouriMath/issues/1265">#1265</a> is about.
        /// It is wrong for this one, because the sub-integrals it answers are the ones integration
        /// by parts asks for and then uses: <c>int x arcsin(x) dx</c> leaves
        /// <c>int x^2/sqrt(1 - x^2) dx</c>, which is squarely this rule's and was refused for
        /// sitting one level down. Ungating it is worth <b>ten</b> more of the Rubi sample and
        /// measures free — same wall clock, same timeouts, and the same 28.8 s over a probe of
        /// integrands that are declined either way.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveARadicalOfAQuadraticAsTrigonometric(
            Entity expr, Entity.Variable x, bool aWholePowerCounts = false)
        {
            if (!TryReadAPowerTimesARadicalQuadratic(expr, x, out var power, out var half,
                    out var constant, out var middle, out var quadratic, out var factor))
                return null;
            // An odd count is a genuine radical and is this rule's straight away. An even one is a
            // rational function, which partial fractions answers in a form people expect -- so it
            // reaches this only from the second call site, below that rule, with what it declined.
            // `1/(x (1 + x^2)^2)` is the shape that gets here: a repeated irreducible quadratic
            // beside a negative power of the variable, which the rational split does not take
            // apart and the tangent substitution turns into `sin^(-1) cos^3`.
            if (half % 2 == 0 && !aWholePowerCounts)
                return null;

            if (middle.IsZero)
                return TimesTheFactor(factor,
                    IntegrateAPowerTimesARadicalQuadratic(expr, x, power, half, constant, quadratic));

            // **Completing the square, and then the same rule again.** `y = x + b/(2c)` turns
            // `a + b x + c x^2` into `A + c y^2` with `A = a - b^2/(4c)`, which is the shape
            // above. What the shift costs is the power of the variable outside the radical:
            // `x^m` is `(y - h)^m`, a sum of `m + 1` terms each of which is this rule's shape
            // again, so the answer is their sum. That needs `m` to be a non-negative whole
            // number -- a negative one is not a finite sum -- which is why a negative power
            // beside a shifted quadratic is declined rather than shifted.
            if (power < 0)
                return null;
            var shift = middle / (ERational.FromInt32(2) * quadratic);
            var shiftedConstant = constant - middle * middle / (ERational.FromInt32(4) * quadratic);
            var shifted = (x + Number.Rational.Create(shift)).InnerSimplified;

            Entity total = 0;
            var binomial = EInteger.One;
            for (var j = power; j >= 0; j--)
            {
                var piece = IntegrateAPowerTimesARadicalQuadratic(
                    expr, shifted, j, half, shiftedConstant, quadratic);
                if (piece is null)
                    return null;
                total += Number.Integer.Create(binomial)
                       * MathS.Pow(-Number.Rational.Create(shift), power - j)
                       * piece;
                // C(m, j-1) from C(m, j): multiply by j and divide by m - j + 1.
                binomial = binomial * j / (power - j + 1);
            }
            return TimesTheFactor(factor, total);
        }

        /// <summary>Multiplies an answer by the constant taken out of the integrand, or keeps a decline.</summary>
        private static Entity? TimesTheFactor(Entity factor, Entity? answer)
            => answer is null ? null : (factor * answer).InnerSimplified;

        /// <summary>
        /// <c>int y^m (A + c y^2)^(k/2) dy</c>, written back in terms of
        /// <paramref name="inTermsOf"/> -- which is the variable itself where the quadratic had no
        /// linear term, and the shifted variable where it did.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <b>Where the answer holds.</b> Each of the three substitutions is a bijection only on
        /// the interval where the radicand is positive, and that is where the integrand is real
        /// in the first place: everywhere for <c>A, c &gt; 0</c>, between the two roots for
        /// <c>c &lt; 0</c>, and outside them for <c>A &lt; 0</c>. The answer is an antiderivative
        /// on each such interval, which is the standing caveat on a trigonometric substitution
        /// and is not something this writes as a condition.
        /// </para>
        /// </remarks>
        private static Entity? IntegrateAPowerTimesARadicalQuadratic(
            Entity expr, Entity inTermsOf, int power, int half, ERational constant, ERational quadratic)
        {
            // Both coefficients decided and neither zero. Their two signs pick one of the three
            // substitutions, and there is no fourth: `A + c y^2` with both positive is
            // `A(1 + tan^2)`, with `c` negative it is `A(1 - sin^2)`, and with `A` negative it is
            // `|A|(sec^2 - 1)`. Both negative is a radicand that is negative everywhere, which is
            // not this rule's business.
            if (quadratic.IsZero || constant.IsZero
                || (constant.Sign < 0 && quadratic.Sign < 0))
                return null;

            var secant = constant.Sign < 0;
            // **The secant branch only for a genuine radical**, and that is a correctness bound
            // rather than a scope one. It is the one substitution whose domain is two intervals,
            // and both of them exclude `|y| < r`. Where the power is odd the integrand excludes
            // that interval too -- it is a square root of something negative there -- so the
            // answer is valid wherever the integrand is. Where the power is *even* the integrand
            // is an ordinary polynomial, real on the whole line, and an answer built from
            // `sqrt(y^2 - r^2)` is wrong on the middle: `(2x + 3x^2)^2` came back with the sign
            // reversed at `x = -0.5`, which is a wrong answer and not a missing condition.
            if (secant && half % 2 == 0)
                return null;
            var a = Number.Rational.Create(constant.Abs());
            var b = Number.Rational.Create(quadratic);
            var r = MathS.Sqrt(Number.Rational.Create(constant.Abs() / quadratic.Abs()));

            var t = Variable.CreateUnique(expr, "t_trig");
            // The three substitutions and what each leaves, with `r = sqrt(|A/c|)`:
            //
            //   A > 0, c > 0   y = r tan(t)   dy = r sec^2 dt   ->  sin^m cos^(-m-k-2)
            //   A > 0, c < 0   y = r sin(t)   dy = r cos dt     ->  sin^m cos^(k+1)
            //   A < 0, c > 0   y = r sec(t)   dy = r sec tan dt ->  sin^(k+1) cos^(-m-k-2)
            //
            // and the constant outside is `r^(m+1) |A|^(k/2)` in all three.
            var sinePower = ERational.FromInt32(secant ? half + 1 : power);
            var cosinePower = ERational.FromInt32(
                secant || quadratic.Sign > 0 ? -power - half - 2 : half + 1);
            var coefficient = MathS.Pow(r, power + 1) * MathS.Pow(a, Number.Rational.Create(half, 2));

            if (IntegrateAPowerOfSineTimesAPowerOfCosine(t, sinePower, cosinePower, 1, 1) is not { } inT)
                return null;

            // Back in terms of the variable. Each of the three is algebraic under the
            // substitution, so the answer stays algebraic except where the recursion bottoms out
            // on `int 1 dt` -- which is where the inverse function below enters.
            //
            // Under the secant substitution `tan(t)^2` is `y^2/r^2 - 1`, which is the radicand
            // over `|A|`, so the radical the integrand came in with is what goes back in.
            var radicand = ((secant ? -a : a) + b * MathS.Sqr(inTermsOf)).InnerSimplified;
            var radical = MathS.Sqrt(radicand);
            // **The secant branch is written for the right interval and reflected onto the left.**
            // It is the one substitution whose domain is two intervals, and the two are not the
            // same calculation: `(a tan(t)^2)^(k/2)` is `a^(k/2) |tan(t)|^k`, and `tan(t)` is
            // negative for `t` in `(pi/2, pi)`, which is where `y < -r` lands. Writing `tan(t)^k`
            // there is wrong by a sign for odd `k`, and the sign it is wrong by depends on the
            // power outside the radical as well, so patching the three replacements one at a time
            // does not converge -- measured, and it does not.
            //
            // What is true without cases: the integrand `y^m (b y^2 - a)^(k/2)` is even or odd
            // under `y -> -y` according to `m`, so an antiderivative `F` valid for `y > r` gives
            // the whole answer as `sign(y)^(m+1) F(|y|)`. So everything below is written in
            // `|y|`, where the substitution's own interval is the principal one and every sign is
            // positive, and the reflection is applied once at the end.
            var absolute = MathS.Abs(inTermsOf);
            var (sine, cosine, tangent) =
                secant
                ? (radical / (absolute * MathS.Sqrt(b)),
                   r / absolute,
                   radical / MathS.Sqrt(a))
                : quadratic.Sign > 0
                ? (inTermsOf * MathS.Sqrt(b) / radical,
                   MathS.Sqrt(a) / radical,
                   inTermsOf * MathS.Sqrt(b) / MathS.Sqrt(a))
                : (inTermsOf * MathS.Sqrt(-b) / MathS.Sqrt(a),
                   radical / MathS.Sqrt(a),
                   inTermsOf * MathS.Sqrt(-b) / radical);

            // `t` itself appears whenever the reduction bottoms out on `int 1 dt`, and that is
            // where an inverse trigonometric function enters an answer that is otherwise
            // algebraic -- `int sqrt(1 - x^2)/x^2 dx` holds an arcsine for exactly this reason.
            var angle = secant
                ? MathS.Arccos(r / absolute)
                : quadratic.Sign > 0
                ? MathS.Arctan(inTermsOf * MathS.Sqrt(b) / MathS.Sqrt(a))
                : MathS.Arcsin(inTermsOf * MathS.Sqrt(-b) / MathS.Sqrt(a));

            // **Two passes, and the order is load-bearing.** `Replace` rewrites a node's children
            // before the node, so a single pass that also matched a bare `t` turned `tan(t)` into
            // `tan(arccos(...))` -- the parent no longer matched once its child had been replaced.
            // That answer is correct and cannot be evaluated: `EvalNumerical` throws on it, so a
            // caller gets an antiderivative it can differentiate and not one it can use. The
            // trigonometric functions of `t` go first, and only what is left of `t` becomes the
            // angle. https://github.com/asc-community/AngouriMath/issues/718
            var answer = inT
                .Replace(node => node switch
                {
                    Sinf(var inner) when inner == t => sine,
                    Cosf(var inner) when inner == t => cosine,
                    Tanf(var inner) when inner == t => tangent,
                    _ => node
                })
                .Replace(node => node is Variable v && v == t ? angle : node);
            if (answer.ContainsNode(t))
                return null;
            // The reflection, once: `sign(y)^(m+1)`, which is `sign(y)` for an even power outside
            // the radical and nothing for an odd one. A factor constant on each interval changes
            // an antiderivative by a constant there and nothing else.
            if (secant && power % 2 == 0)
                answer *= MathS.Signum(inTermsOf);
            return (coefficient * answer).InnerSimplified;
        }

        /// <summary>
        /// Reads <paramref name="expr"/> as a rational multiple of
        /// <c>x^m (a + b x^2)^(k/2)</c> with <c>k</c> odd, however the radical is spelled.
        /// </summary>
        /// <remarks>
        /// The half-power is what makes this rule's rather than the ordinary power rule's: an even
        /// <c>k</c> is a whole power of a polynomial, which expanding answers. The quadratic has
        /// no linear term, so a shifted one — <c>x/sqrt(1 + x + x^2)</c> — is not read here and
        /// wants completing the square first, which is its own step.
        /// </remarks>
        private static bool TryReadAPowerTimesARadicalQuadratic(
            Entity expr, Entity.Variable x, out int power, out int half,
            out ERational constant, out ERational middle, out ERational quadratic, out Entity factor)
        {
            power = 0;
            half = 0;
            constant = ERational.Zero;
            middle = ERational.Zero;
            quadratic = ERational.Zero;
            factor = 1;

            Entity? radicandFound = null;
            var halfFound = 0;
            var powerFound = 0;
            Entity constantFactor = 1;
            var read = Read(expr, 1);
            if (!read || radicandFound is null)
                return false;
            if (!TreeAnalyzer.TryGetPolyQuadratic(radicandFound, x, out var square, out var linear, out var free))
                return false;
            if (free.Evaled is not Number.Rational freeValue
                || linear.Evaled is not Number.Rational linearValue
                || square.Evaled is not Number.Rational squareValue)
                return false;

            power = powerFound;
            half = halfFound;
            constant = freeValue.ERational;
            middle = linearValue.ERational;
            quadratic = squareValue.ERational;
            factor = constantFactor;
            return !quadratic.IsZero;

            bool Read(Entity node, int multiplicity)
            {
                switch (node)
                {
                    case Variable v when v == x:
                        powerFound += multiplicity;
                        return true;
                    case Mulf(var left, var right):
                        return Read(left, multiplicity) && Read(right, multiplicity);
                    case Divf(var above, var below):
                        return Read(above, multiplicity) && Read(below, -multiplicity);
                    // A whole power of the quadratic, counted on the same scale -- `Q^2` is
                    // `Q^(4/2)`. Whether an even count is acceptable is the caller's to decide,
                    // and the two callers decide differently: a radical is this rule's before
                    // anything else has tried, and a whole power is only its if the rational
                    // machinery has already declined.
                    case Powf(var @base, Number.Integer whole)
                        when @base.ContainsNode(x) && @base != x && whole.EInteger.CanFitInInt32():
                        if (radicandFound is not null && radicandFound != @base)
                            return false;
                        radicandFound = @base;
                        halfFound += multiplicity * 2 * whole.EInteger.ToInt32Checked();
                        return true;
                    // The radical, in any odd half power: sqrt(Q), Q^(3/2), 1/Q^(5/2).
                    case Powf(var @base, Number.Rational exponent)
                        when @base.ContainsNode(x)
                             && exponent.ERational.Denominator.Equals(EInteger.FromInt32(2))
                             && exponent.ERational.Numerator.CanFitInInt32():
                        if (radicandFound is not null && radicandFound != @base)
                            return false;
                        radicandFound = @base;
                        halfFound += multiplicity * exponent.ERational.Numerator.ToInt32Checked();
                        return true;
                    // The quadratic written out rather than raised, which is the power one.
                    case Sumf or Minusf when node.ContainsNode(x):
                        if (radicandFound is not null && radicandFound != node)
                            return false;
                        radicandFound = node;
                        halfFound += multiplicity * 2;
                        return true;
                    // A whole power of the variable, written as one.
                    case Powf(var @base, Number.Integer exponent)
                        when @base == x && exponent.EInteger.CanFitInInt32():
                        powerFound += multiplicity * exponent.EInteger.ToInt32Checked();
                        return true;
                    case Number.Rational rational when node is not Powf:
                        constantFactor = multiplicity > 0
                            ? constantFactor * MathS.Pow(rational, multiplicity)
                            : constantFactor / MathS.Pow(rational, -multiplicity);
                        return true;
                    default:
                        return false;
                }
            }
        }

        /// <summary>
        /// Reads <paramref name="expr"/> as a rational multiple of <c>sin(u)^p cos(u)^q</c> over
        /// one common argument, however the six trigonometric functions spell it.
        /// </summary>
        /// <remarks>
        /// A tangent contributes <c>(+1, -1)</c>, a secant <c>(0, -1)</c>, a cosecant
        /// <c>(-1, 0)</c> and a cotangent <c>(-1, +1)</c>, so a product of any of them over one
        /// argument is a pair of integers. Anything else in the product — a second argument, a
        /// non-integer power, a function of the variable that is not one of the six — makes the
        /// whole read fail, because a rule that guesses at the part it did not recognise answers
        /// a question it was not asked.
        /// </remarks>
        private static bool TryReadSineCosinePowers(
            Entity expr, out Entity argument, out ERational sinePower, out ERational cosinePower, out Entity factor)
            => TryReadSineCosinePowers(expr, out argument, out sinePower, out cosinePower, out factor, out _);

        /// <summary>
        /// <see cref="TryReadSineCosinePowers(Entity, out Entity, out ERational, out ERational, out Entity)"/>,
        /// and whether a fractional power of a product was read as the product of the powers:
        /// true only up to a constant on each interval where the factors keep their signs.
        /// </summary>
        private static bool TryReadSineCosinePowers(
            Entity expr, out Entity argument, out ERational sinePower, out ERational cosinePower, out Entity factor, out bool throughAProduct)
        {
            Entity? common = null;
            var sine = ERational.Zero;
            var cosine = ERational.Zero;
            Entity constant = 1;
            var distributed = false;
            var read = Read(expr, ERational.One);
            argument = common ?? 0;
            sinePower = sine;
            cosinePower = cosine;
            factor = constant;
            throughAProduct = distributed;
            return read && common is not null && !(sine.IsZero && cosine.IsZero);

            bool Agrees(Entity candidate)
            {
                if (common is null)
                {
                    common = candidate;
                    return true;
                }
                return common == candidate;
            }

            bool Read(Entity node, ERational multiplicity)
            {
                switch (node)
                {
                    case Sinf(var a): sine += multiplicity; return Agrees(a);
                    case Cosf(var a): cosine += multiplicity; return Agrees(a);
                    case Tanf(var a): sine += multiplicity; cosine -= multiplicity; return Agrees(a);
                    case Cotanf(var a): sine -= multiplicity; cosine += multiplicity; return Agrees(a);
                    case Secantf(var a): cosine -= multiplicity; return Agrees(a);
                    case Cosecantf(var a): sine -= multiplicity; return Agrees(a);
                    case Mulf(var left, var right):
                        return Read(left, multiplicity) && Read(right, multiplicity);
                    case Divf(var above, var below):
                        return Read(above, multiplicity) && Read(below, -multiplicity);
                    // A rational exponent, not only a whole one: `sin(x)/sqrt(cos(x)^3)` is
                    // `sin cos^(-3/2)`, and the substitution that answers it does not care
                    // whether the exponent it carries along is whole — the power rule takes
                    // <c>u^(-3/2)</c> as readily as <c>u^(-3)</c>. Which of the three cases
                    // applies still turns on a whole exponent, and that is checked there.
                    // Not a fractional power of an even power, though: `(sin^2)^(3/2)` is
                    // `|sin|^3`, and read as `sin^3` it was integrated as one, wrong on every
                    // other half-turn; `sqrt(a sin^2)^5`, `1/sqrt(a cot^2)`, `(csc^2)^(3/2)`,
                    // `x sqrt(sin^2)` were four of Rubi's answered so.
                    // https://github.com/asc-community/AngouriMath/issues/1387
                    case Powf(var @base, Number.Rational power) when power is not Number.Integer && HasAnEvenPowerOfATrigonometricFunction(@base):
                        return false;
                    case Powf(var @base, Number.Rational power):
                        // Through anything but one function, or a positive multiple of one, a
                        // power with an even denominator splits across factors whose signs it
                        // does not see: `(sin tan)^(3/2)` is real where the sine is negative and
                        // `sin^3 cos^(-3/2)` is its negative there. An odd denominator is read as
                        // it always was, the real root: `(c sin^3)^(1/3)` as `c^(1/3) sin`, which
                        // is the integrand wherever that is real.
                        if ((multiplicity * power.ERational).ToLowestTerms().Denominator.IsEven
                            && @base is not TrigonometricFunction
                            && !(@base is Mulf(Number.Rational { IsPositive: true }, TrigonometricFunction)))
                            distributed = true;
                        return Read(@base, multiplicity * power.ERational);
                    // A rational factor rides along; anything else is declined rather than
                    // carried, since carrying it would claim the rest of the product is
                    // trigonometric when it has not been read. A rational *factor* and a
                    // rational *exponent* are told apart by the case above matching first.
                    case Number.Rational rational when node is not Powf:
                        constant = IsWholeAndFitsAnInt(multiplicity, out var times)
                            ? times > 0
                                ? constant * MathS.Pow(rational, times)
                                : constant / MathS.Pow(rational, -times)
                            : constant * MathS.Pow(rational, Number.Rational.Create(multiplicity));
                        return true;
                    default:
                        return false;
                }
            }
        }

        /// <summary>
        /// Whether an even whole power of a sine, cosine, tangent, cotangent, secant or
        /// cosecant stands anywhere in <paramref name="expr"/>: a fractional power of it is a
        /// power of the function's modulus, not of the function.
        /// </summary>
        private static bool HasAnEvenPowerOfATrigonometricFunction(Entity expr)
            => expr.Nodes.Any(node => node is Powf(TrigonometricFunction, Number.Integer even) && even.EInteger.IsEven && !even.EInteger.IsZero);

        /// <summary>
        /// Whether <paramref name="value"/> is a whole number small enough to count with, and
        /// what that number is.
        /// </summary>
        private static bool IsWholeAndFitsAnInt(ERational value, out int whole)
        {
            var lowest = value.ToLowestTerms();
            if (lowest.Denominator.Equals(EInteger.One) && lowest.Numerator.CanFitInInt32())
            {
                whole = lowest.Numerator.ToInt32Checked();
                return true;
            }
            whole = 0;
            return false;
        }

        /// <summary>
        /// Whether <paramref name="value"/> is an odd whole number of at least one — the exponent
        /// that lets one factor of the function go into <c>du</c> and leaves an even power, which
        /// is a polynomial in the other function.
        /// </summary>
        private static bool IsOddAndPositive(ERational value)
            => IsWholeAndFitsAnInt(value, out var whole) && whole >= 1 && whole % 2 != 0;

        /// <summary>Whether <paramref name="value"/> is an even whole number.</summary>
        private static bool IsEvenWhole(ERational value)
            => IsWholeAndFitsAnInt(value, out var whole) && whole % 2 == 0;

        /// <summary>
        /// The whole number <paramref name="value"/> is, for a value one of the two tests above
        /// has already said is whole.
        /// </summary>
        private static int WholeOf(ERational value)
            => value.ToLowestTerms().Numerator.ToInt32Checked();

        /// <summary>
        /// Reads <paramref name="expr"/> as a whole power of a secant or a cosecant, however it
        /// is written: as the node, as a negative power of cosine or sine, or as one over a
        /// positive power of them.
        /// </summary>
        private static bool TryReadReciprocalTrigonometricPower(
            Entity expr, out Entity argument, out int power, out bool isSecant)
        {
            argument = 0;
            power = 0;
            isSecant = false;
            switch (expr)
            {
                case Secantf(var secantArgument):
                    (argument, power, isSecant) = (secantArgument, 1, true);
                    return true;
                case Cosecantf(var cosecantArgument):
                    (argument, power, isSecant) = (cosecantArgument, 1, false);
                    return true;
                case Powf(Secantf(var raisedSecant), Number.Integer secantPower)
                    when secantPower.EInteger.Sign > 0 && secantPower.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (raisedSecant, secantPower.EInteger.ToInt32Checked(), true);
                    return true;
                case Powf(Cosecantf(var raisedCosecant), Number.Integer cosecantPower)
                    when cosecantPower.EInteger.Sign > 0 && cosecantPower.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (raisedCosecant, cosecantPower.EInteger.ToInt32Checked(), false);
                    return true;
                // cos(u)^(-n) is sec(u)^n, and sin(u)^(-n) is csc(u)^n.
                case Powf(Cosf(var loweredCosine), Number.Integer negativeCosine)
                    when negativeCosine.EInteger.Sign < 0 && negativeCosine.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (loweredCosine, -negativeCosine.EInteger.ToInt32Checked(), true);
                    return true;
                case Powf(Sinf(var loweredSine), Number.Integer negativeSine)
                    when negativeSine.EInteger.Sign < 0 && negativeSine.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (loweredSine, -negativeSine.EInteger.ToInt32Checked(), false);
                    return true;
                // And one over a positive power, which is the same thing spelled as a quotient.
                case Divf(var one, var below) when one == Number.Integer.One:
                    return TryReadTrigonometricDenominator(below, ref argument, ref power, ref isSecant);
                default:
                    return false;
            }
        }

        private static bool TryReadTrigonometricDenominator(
            Entity below, ref Entity argument, ref int power, ref bool isSecant)
        {
            switch (below)
            {
                case Cosf(var cosine):
                    (argument, power, isSecant) = (cosine, 1, true);
                    return true;
                case Sinf(var sine):
                    (argument, power, isSecant) = (sine, 1, false);
                    return true;
                case Powf(Cosf(var cosine), Number.Integer cosinePower)
                    when cosinePower.EInteger.Sign > 0 && cosinePower.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (cosine, cosinePower.EInteger.ToInt32Checked(), true);
                    return true;
                case Powf(Sinf(var sine), Number.Integer sinePower)
                    when sinePower.EInteger.Sign > 0 && sinePower.EInteger.CanFitInInt32():
                    (argument, power, isSecant) =
                        (sine, sinePower.EInteger.ToInt32Checked(), false);
                    return true;
                default:
                    return false;
            }
        }

        /// <summary>
        /// Whether <paramref name="inverse"/>, or a function of it and of nothing else in
        /// <paramref name="x"/>, is a factor below the bar of <paramref name="expr"/> or a
        /// negative power of one.
        /// </summary>
        private static bool TheInverseIsBelowTheBar(Entity expr, Entity inverse, Entity.Variable x)
        {
            var u = Variable.CreateUnique(expr, "u_inv");
            return FactorsOfTheIntegrand(expr).Any(pair =>
                (pair.Underneath || pair.Factor is Powf(_, Number.Integer { EInteger.Sign: < 0 }))
                && pair.Factor.ContainsNode(inverse) && !pair.Factor.Substitute(inverse, u).ContainsNode(x));
        }

        /// <summary>
        /// <see cref="SolveByInverseTrigonometricSubstitution"/> where the inverse function is
        /// below the bar, asked before the general substitution search: under the substitution the
        /// integrand is the sine and cosine integrals' at once, and the search in front of it spent
        /// five seconds on <c>x/((c + a^2 c x^2)^2 arctan(a x))</c> finding nothing. Only that
        /// question is asked in <c>u</c>, of <see cref="SolveATrigonometricOfALinearOverAPowerOfALinear"/>.
        /// Where the substitution leaves anything else -- a quadratic it does not read as a
        /// multiple of the radicand, <c>(a^2 + a^2 tan(u)^2)^3</c> -- the whole search in
        /// <c>u</c> runs past thirty seconds, on integrands the general substitution search
        /// answers in under one.
        /// </summary>
        internal static Entity? SolveAReciprocalOfAnInverseTrigonometricFunction(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not (Divf or Mulf or Powf))
                return null;
            Entity? inverse = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not (Arcsinf or Arccosf or Arctanf or Arcsecantf or Arccosecantf or Arccotanf))
                    continue;
                if (inverse is not null && inverse != node)
                    return null;
                inverse = node;
            }
            return inverse is not null && TheInverseIsBelowTheBar(expr, inverse, x)
                ? UndoingTheInverseTrigonometricFunction(expr, x, integrateByParts, onlyTheSineAndCosineIntegrals: true)
                : null;
        }

        /// <summary>
        /// An integrand holding an inverse trigonometric function of the variable itself,
        /// integrated by the substitution that undoes it: <c>x = sin(u)</c> for <c>arcsin(x)</c>,
        /// <c>x = tan(u)</c> for <c>arctan(x)</c>, <c>x = cos(u)</c> and <c>x = sec(u)</c> for the
        /// other two.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>e^(arcsin(x)) x^3/sqrt(1 - x^2)</c> had no antiderivative. Under <c>x = sin(u)</c> it
        /// is <c>e^u sin(u)^3</c>, which the product-to-sum rewrite and the closed
        /// exponential-times-trigonometric rule answer between them; <c>x arcsec(x)/sqrt(x^2 - 1)</c>
        /// is <c>u sec(u)^2</c> under <c>x = sec(u)</c>, one step of parts. The general
        /// substitution does not find these because it substitutes for a subtree and asks what
        /// is left, and what is left here is <c>x</c> itself, which only the <b>inverse</b>
        /// substitution removes -- the same reason <see cref="SolveByLogarithmSubstitution"/>
        /// exists beside it.
        /// </para>
        /// <para>
        /// <b>The radical goes by construction.</b> <c>sqrt(1 - x^2)</c> under <c>x = sin(u)</c>
        /// is <c>cos(u)</c> on the principal branch, where <c>u</c> lies in <c>[-pi/2, pi/2]</c>
        /// and the cosine is not negative; substituting and simplifying instead would leave
        /// <c>sqrt(1 - sin(u)^2)</c>, which the simplifier is right not to call <c>cos(u)</c>.
        /// So <c>(1 - x^2)^(k/2)</c> becomes <c>cos(u)^k</c> directly, and likewise
        /// <c>(1 + x^2)^(k/2)</c> into <c>sec(u)^k</c> for the tangent, each on its principal
        /// branch. That branch is the one the inverse function is defined on, so the answer holds
        /// wherever the integrand is read through it. For the secant <c>(x^2 - 1)^(k/2)</c> is
        /// <c>|tan(u)|^k</c>, and on the arcsecant's range the tangent has the sign of the
        /// argument, so it becomes <c>tan(u)^k</c> times that sign to the <c>k</c>, as the
        /// cosecant's and the cotangent's roots carry theirs.
        /// </para>
        /// <para>
        /// Exactly one inverse function, of the variable or of a linear <c>c x + d</c> in it,
        /// and nothing left in <c>x</c> afterwards; otherwise declined. Handed to the
        /// integrator in <c>u</c>, where the trigonometric rules are. With the linear,
        /// <c>x = (sin(u) - d)/c</c> and <c>dx = cos(u) du/c</c>, and the radical that goes
        /// is of a constant multiple of <c>1 - (c x + d)^2</c> -- Rubi's
        /// <c>(d - c^2 d x^2)^p (a + b arcsin(c x))^n</c> -- taken as that multiple's root
        /// times the cosine, the generic case. A power of <c>a + b arcsin(c x)</c> counts
        /// as a power of the inverse: <c>x arcsin(a x)^2</c> under the sine is
        /// <c>u^2 sin(u) cos(u)/a^2</c>, parts twice against <c>sin(2u)</c>, where parts in
        /// <c>x</c> stalled on <c>x^2 arcsin(a x)/sqrt(1 - a^2 x^2)</c>.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByInverseTrigonometricSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
            => UndoingTheInverseTrigonometricFunction(expr, x, integrateByParts, onlyTheSineAndCosineIntegrals: false);

        /// <summary>
        /// <see cref="SolveByInverseTrigonometricSubstitution"/>, or, with
        /// <paramref name="onlyTheSineAndCosineIntegrals"/>, the substitution taken because the
        /// inverse function is below the bar and the question in <c>u</c> asked of the sine and
        /// cosine integrals' rule alone.
        /// </summary>
        private static Entity? UndoingTheInverseTrigonometricFunction(Entity expr, Entity.Variable x, bool integrateByParts, bool onlyTheSineAndCosineIntegrals)
        {
            // The one inverse function, of the variable or of a linear in it.
            Entity? inverse = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not (Arcsinf or Arccosf or Arctanf or Arcsecantf or Arccosecantf or Arccotanf))
                    continue;
                if (inverse is not null && inverse != node)
                    return null;
                inverse = node;
            }
            if (inverse is null)
                return null;
            var argument = inverse.DirectChildren.First();
            if (!argument.ContainsNode(x))
                return null;
            Entity slope = Number.Integer.One, offset = Number.Integer.Zero;
            var linear = argument != x;
            if (linear)
            {
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var readSlope, out var readOffset)
                    || readSlope is null || readOffset is null || TreeAnalyzer.IsZero(readSlope) || readSlope.Evaled is Number.Complex { IsZero: true })
                    return null;
                (slope, offset) = (readSlope, readOffset);
            }

            var u = Variable.CreateUnique(expr, "u_inv");
            // The sign the root has, where it has one: a constant on each half of the range,
            // carried through the integration as a symbol and written back as the sign of the
            // argument, which it is -- the sign of u for the cosecant and the cotangent, and of
            // tan(u) for the secant.
            var signOfU = Variable.CreateUnique(expr, "s_inv");
            // x in terms of u, dx/du, the quadratic whose root goes by construction and what it
            // becomes, and the way back.
            Entity xInU, dxdu, radicandBase, root;
            // Written for the argument; with a linear argument, x itself is `(L - d)/c` and
            // dx is `dL/c`.
            switch (inverse)
            {
                case Arcsinf:
                    (xInU, dxdu, radicandBase, root) = (MathS.Sin(u), MathS.Cos(u), 1 - MathS.Sqr(argument), MathS.Cos(u));
                    break;
                case Arccosf:
                    (xInU, dxdu, radicandBase, root) = (MathS.Cos(u), -MathS.Sin(u), 1 - MathS.Sqr(argument), MathS.Sin(u));
                    break;
                case Arctanf:
                    (xInU, dxdu, radicandBase, root) = (MathS.Tan(u), MathS.Sqr(MathS.Sec(u)), 1 + MathS.Sqr(argument), MathS.Sec(u));
                    break;
                case Arccotanf:
                    // The range here is (-pi/2, pi/2], where the cosecant is not negative on
                    // the positive half and negative on the other: the root is kept as `|csc|`,
                    // which is `csc(u) sgn(u)`, so the answer holds on both.
                    (xInU, dxdu, radicandBase, root) = (MathS.Cotan(u), -MathS.Sqr(MathS.Cosec(u)), 1 + MathS.Sqr(argument), MathS.Cosec(u) * signOfU);
                    break;
                case Arccosecantf:
                    // arccsc has the range [-pi/2, 0) ∪ (0, pi/2], where the cotangent has the
                    // sign of u: `sqrt(x^2 - 1)` is `cot(u) sgn(u)`.
                    (xInU, dxdu, radicandBase, root) = (MathS.Cosec(u), -MathS.Cosec(u) * MathS.Cotan(u), MathS.Sqr(argument) - 1, MathS.Cotan(u) * signOfU);
                    break;
                default:
                    // arcsec has the range [0, pi/2) ∪ (pi/2, pi], where the tangent has the sign
                    // of the argument: `sqrt(x^2 - 1)` is `tan(u) sgn(x)`. Taken as `tan(u)`, the
                    // answer was right for x > 1 and its derivative the integrand's negative for
                    // every x < -1, where the integrand is as real: `x arcsec(x)/sqrt(x^2 - 1)`.
                    (xInU, dxdu, radicandBase, root) = (MathS.Sec(u), MathS.Sec(u) * MathS.Tan(u), MathS.Sqr(argument) - 1, MathS.Tan(u) * signOfU);
                    break;
            }
            if (linear)
            {
                xInU = ((xInU - offset) / slope).InnerSimplified;
                dxdu = dxdu / slope;
            }

            // What the substitution is for: a radical of the quadratic it removes, or an
            // exponential of the inverse function, which it turns into `e^u`. With neither the
            // integrand is by parts' -- `x arcsin(x)` is `u sin(u) cos(u)` under the sine, an
            // answer in `sin(2 arcsin(x))` where parts gives one in `x` -- and the time spent
            // here is spent on nothing: `x arctan(x)^2 ln(1 + x^2)` cost 0.6 s of it.
            var radicalsRemoved = 0;
            var rewritten = expr
                .Substitute(inverse, u)
                .Replace(node =>
                {
                    // A whole power of the quadratic from the second up counts as well: parts
                    // in x on `x (d - c^2 d x^2)^3 (a + b arcsin(c x))` leaves a seventh-degree
                    // polynomial over the root and went past its budget there, where under
                    // the sine it is a polynomial in the sine and cosine beside `a + b u`.
                    var wholePower = node is Powf(var wholeBase, Number.Integer whole) && whole.EInteger.CompareTo(EInteger.FromInt32(2)) >= 0
                        && whole.EInteger.CompareTo(EInteger.FromInt32(64)) <= 0 && wholeBase.ContainsNode(x) ? whole.EInteger.ToInt32Unchecked() : 0;
                    if (wholePower > 0 && node is Powf(var quadratic, _) && TreeAnalyzer.TryGetPolyQuadratic(quadratic, x, out _, out _, out _)
                        && TryReadAConstantMultipleOf(quadratic, radicandBase, x) is { } wholeMultiple)
                    {
                        radicalsRemoved++;
                        return MathS.Pow(wholeMultiple, wholePower) * MathS.Pow(root, 2 * wholePower);
                    }
                    if (!TryReadAHalfPower(node, out var @base, out var numerator))
                        return node;
                    if (IsTheSameQuadratic(@base, radicandBase, x))
                    {
                        radicalsRemoved++;
                        return MathS.Pow(root, numerator);
                    }
                    // A constant multiple of the quadratic, `d - c^2 d x^2` for `1 - (c x)^2`:
                    // the multiple's root times the root of the quadratic, the generic case.
                    if (linear || TreeAnalyzer.TryGetPolyQuadratic(@base, x, out _, out _, out _))
                    {
                        if (TryReadAConstantMultipleOf(@base, radicandBase, x) is { } multiple)
                        {
                            radicalsRemoved++;
                            return MathS.Pow(multiple, Number.Rational.Create(numerator, 2)) * MathS.Pow(root, numerator);
                        }
                    }
                    return node;
                });
            var exponentialOfTheInverse = expr.Nodes.Any(node =>
                node is Powf(var @base, var power) && !@base.ContainsNode(x) && power.ContainsNode(inverse));
            // Or a power of the inverse function above the first: parts on `x^3 arccsc(x)^2`
            // leaves `x^2 arccsc(x)/sqrt(x^2 - 1)` and stalls, where under `x = csc(u)` it is
            // `-u^2 csc(u)^4 cot(u)`, two steps of parts against a power of the cosecant.
            // Or of a function of it alone -- `(a + b arcsin(c x))^2` -- which is a power of
            // u after the substitution.
            var powerOfTheInverse = expr.Nodes.Any(node =>
                node is Powf(var @base, Number.Integer power) && power.EInteger.CompareTo(EInteger.One) > 0
                    && @base.ContainsNode(inverse) && !@base.Substitute(inverse, u).ContainsNode(x));
            // Or, asked for the sine and cosine integrals, the inverse function below the bar, or
            // a function of it alone there: `x^m/(a + b arcsin(c x))^n` is a polynomial in the
            // sine and cosine over a power of `a + b u`, where parts in x has no integral of the
            // reciprocal to take.
            if (onlyTheSineAndCosineIntegrals)
            {
                if (!TheInverseIsBelowTheBar(expr, inverse, x))
                    return null;
            }
            else
            {
                if (radicalsRemoved == 0 && !exponentialOfTheInverse && !powerOfTheInverse)
                    return null;
                // The cosecant, the cotangent and the secant carry a sign into the root, and a
                // first power of any of them beside a root is parts' -- `arccot(x)/(1 + x^2)^(3/2)`
                // is `x arccot(x)/sqrt(1 + x^2) + 1/sqrt(1 + x^2)` there, with no sign in it.
                if (inverse is Arccosecantf or Arccotanf or Arcsecantf && !exponentialOfTheInverse && !powerOfTheInverse)
                    return null;
            }
            // And nothing else of `x` under a root, which the construction did not reach:
            // `x^3 arcsin(x)/sqrt(1 - x^4)` under the sine is a root of `1 - sin(u)^4`, worse
            // than what it came from, and 1.4 s of declining it.
            if (rewritten.Nodes.Any(node =>
                    node is Powf(var @base, Number.Rational power) && power is not Number.Integer && @base.ContainsNode(x)))
                return null;
            rewritten = rewritten.Substitute(x, xInU);
            if (rewritten.ContainsNode(x))
                return null;

            // As one quotient with the common factors cancelled: `x/sqrt(1 - x^2)` under the
            // sine leaves `sin(u) cos(u)/cos(u)`, and the closed exponential-times-trigonometric
            // rule reads a cosine above the bar and not one below it.
            var (numerator, denominator) = Functions.SingleQuotient.Of((rewritten * dxdu).InnerSimplified);
            var integrand = CancelCommonFactors(numerator, denominator);
            if (integrand is Providedf(var inner, _))
                integrand = inner;
            // A cosecant or a secant left below the bar is a sine or a cosine above it:
            // `arccsc(x)^4/(x^2 sqrt(x^2 - 1))` under the cosecant is `-u^4/csc(u)`, which parts
            // does not read, and `-u^4 sin(u)`, which it does.
            if (integrand.Nodes.Any(node => node is Cosecantf or Secantf))
            {
                var asSinesAndCosines = integrand.Replace(node => node switch
                {
                    Cosecantf(var argument) => 1 / MathS.Sin(argument),
                    Secantf(var argument) => 1 / MathS.Cos(argument),
                    _ => node,
                });
                var (top, bottom) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(asSinesAndCosines));
                integrand = CancelCommonFactors(top, bottom);
                if (integrand is Providedf(var innerCombined, _))
                    integrand = innerCombined;
            }

            // The sign squared is one: an even power of it, from a whole power of the
            // quadratic, is folded before the question is asked, since `e^u sin(u)^4/s^6` is
            // not the exponential-times-trigonometric rule's and `e^u sin(u)^4` is.
            if (integrand.ContainsNode(signOfU))
                integrand = integrand
                    .Replace(node => node is Powf(var b, Number.Integer k) && b == signOfU ? (k.EInteger.IsEven ? Number.Integer.One : signOfU) : node)
                    .InnerSimplified;
            // The same question in another variable, not a step in the search for it: asked at
            // the top when this was, so the closed rules that answer only at the top --
            // `e^u sin(u)^3` is the exponential-times-trigonometric rule's -- are consulted.
            var result = onlyTheSineAndCosineIntegrals
                ? SolveATrigonometricOfALinearOverAPowerOfALinear(integrand, u)
                : Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts);
            if (result is null)
                return null;
            if (result.ContainsNode(signOfU))
                // The sign squared is one, and the sign itself is the argument's: `arccsc(c x + d)`
                // has the sign of `c x + d`, which is the sign of x only for a positive c and no d.
                result = result
                    .Replace(node => node is Powf(var b, Number.Integer k) && b == signOfU ? (k.EInteger.IsEven ? Number.Integer.One : signOfU) : node)
                    .Substitute(signOfU, MathS.Signum(argument));
            return TrigonometryOfTheInverseInX(result.Substitute(u, inverse), inverse, argument);
        }

        /// <summary>
        /// The constant <c>k</c> with <paramref name="candidate"/> equal to
        /// <c>k</c> times <paramref name="wanted"/> as functions of <paramref name="x"/>,
        /// decided at sampled points and then read exactly from the quotient, else null.
        /// </summary>
        private static Entity? TryReadAConstantMultipleOf(Entity candidate, Entity wanted, Entity.Variable x)
        {
            if (!AreProportionalAtSampledPoints(candidate, wanted, x))
                return null;
            var ratio = Functions.PartialFractions.Bare((candidate / wanted).Simplify());
            // Two proportional quadratics whose quotient does not simplify free of x: the
            // integrand's `1 - a^2 x^2` arrives divided through by its leading coefficient, as
            // `1/(-a^2) + x^2`, and the ratio is that of the leading coefficients.
            if (ratio.ContainsNode(x)
                && TreeAnalyzer.TryGetPolyQuadratic(candidate, x, out var candidateLeading, out _, out _)
                && TreeAnalyzer.TryGetPolyQuadratic(wanted, x, out var wantedLeading, out _, out _)
                && !TreeAnalyzer.IsZero(wantedLeading))
                ratio = Functions.PartialFractions.Bare((candidateLeading / wantedLeading).Simplify());
            if (ratio.ContainsNode(x) || ratio.Nodes.Any(node => node == MathS.NaN))
                return null;
            // A multiple that is known negative is refused: `sqrt(k Q)` is `sqrt(k) sqrt(Q)`
            // for a positive k and for a symbol taken as one, and for `k = -1` with a negative
            // Q it is off by a sign -- `arcosh(a x)^2/sqrt(1 - a^2 x^2)` came back with `i a`
            // below where the integrand is real.
            if (ratio.Evaled is Number.Complex evaluated && (evaluated is not Number.Real || evaluated is Number.Real { IsNegative: true }))
                return null;
            return ratio;
        }

        /// <summary>
        /// An exponential of <c>i</c> times an inverse trigonometric function, written
        /// algebraically: <c>e^(i arctan(L))</c> is <c>(1 + i L)/sqrt(1 + L^2)</c>,
        /// <c>e^(i arcsin(L))</c> is <c>sqrt(1 - L^2) + i L</c> and <c>e^(i arccos(L))</c> is
        /// <c>L + i sqrt(1 - L^2)</c>, each on the principal branch for a real <c>L</c>, and
        /// <c>e^(n i f(L))</c> is that to the <c>n</c>th, for a rational <c>n</c>. Rubi's
        /// <c>e^(i arctan(a x))/sqrt(c + a^2 c x^2)</c> is then <c>(1 + i a x)/(sqrt(c) (1 + a^2 x^2))</c>,
        /// a rational function; under <c>x = tan(u)/a</c> it was <c>e^(i u) sec(u)</c>, which
        /// nothing in <c>u</c> reads. The integrand as rewritten is asked as a question of
        /// its own, and the answer checked at sampled points where a symbol is involved.
        /// </summary>
        internal static Entity? SolveByWritingAnExponentialOfAnInverseAlgebraically(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var rewrote = false;
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var @base, var exponent) || @base != MathS.e || !exponent.ContainsNode(x))
                    return node;
                // The exponent as n i times one inverse function of a real argument.
                Entity? inverse = null;
                foreach (var inner in exponent.Nodes)
                    if (inner is Arctanf or Arcsinf or Arccosf)
                    {
                        if (inverse is not null && inverse != inner)
                            return node;
                        inverse = inner;
                    }
                if (inverse is null || inverse.DirectChildren.First() is not { } argument || !argument.ContainsNode(x))
                    return node;
                var placeholder = Variable.CreateUnique(exponent, "u_exp");
                var inThePlaceholder = exponent.Replace(inner => inner == inverse ? placeholder : inner);
                if (inThePlaceholder.ContainsNode(x)
                    || !TreeAnalyzer.TryGetPolyLinear(inThePlaceholder, placeholder, out var coefficient, out var constantPart)
                    || coefficient is null || constantPart is null || constantPart.Evaled is not Number.Complex { IsZero: true })
                    return node;
                if ((coefficient / MathS.i).InnerSimplified.Evaled is not Number.Rational n)
                    return node;
                rewrote = true;
                // The tangent's as two powers, `(1 + i L)^n (1 + L^2)^(-n/2)`, which the
                // radical rules read where a power of the quotient is one node to them; for an
                // n that is not whole, as the power of the quotient,
                // `((1 + i L)/(1 - i L))^(n/2)`, the same on the principal branch for a real L --
                // the quotient is `e^(2 i arctan(L))` and `2 arctan(L)` is its principal
                // argument -- and one power of a quotient of linears, which the substitution
                // for it reads, where `(1 + i a x)^(3/2) (1 + a^2 x^2)^(-3/4)` is two radicals
                // of different orders that nothing reads.
                if (inverse is Arctanf)
                {
                    var halfPower = Number.Rational.Create(n.ERational.Negate().Divide(2));
                    if (n is not Number.Integer)
                        return MathS.Pow((1 + MathS.i * argument) / (1 - MathS.i * argument), Number.Rational.Create(n.ERational.Divide(2)));
                    return (n == Number.Integer.One ? 1 + MathS.i * argument : MathS.Pow(1 + MathS.i * argument, n)) * MathS.Pow(1 + MathS.Sqr(argument), halfPower);
                }
                Entity unit = inverse is Arcsinf
                    ? MathS.Sqrt(1 - MathS.Sqr(argument)) + MathS.i * argument
                    : argument + MathS.i * MathS.Sqrt(1 - MathS.Sqr(argument));
                return n == Number.Integer.One ? unit : MathS.Pow(unit, n);
            });
            if (!rewrote)
                return null;
            // A fractional power of a constant multiple of the quadratic the rewrite brought
            // in, as the multiple's power times the quadratic's, the generic case, so that
            // `(1 + a^2 x^2)^(-1/2)` and `(c + a^2 c x^2)^(-1/2)` meet as one power:
            // `e^(i arctan(a x))/sqrt(c + a^2 c x^2)` is `(1 + i a x)/(sqrt(c) (1 + a^2 x^2))`.
            var quadratics = new List<Entity>();
            foreach (var node in rewritten.Nodes)
                if (node is Powf(var q, Number.Rational r) && r is not Number.Integer && q.ContainsNode(x) && TreeAnalyzer.TryGetPolyQuadratic(q, x, out _, out _, out _)
                    && !quadratics.Contains(q))
                    quadratics.Add(q);
            if (quadratics.Count > 1)
            {
                var first = quadratics[0];
                rewritten = rewritten.Replace(node =>
                    node is Powf(var q, Number.Rational r) && r is not Number.Integer && q != first && quadratics.Contains(q)
                    && TryReadAConstantMultipleOf(q, first, x) is { } multiple
                        ? MathS.Pow(multiple, r) * MathS.Pow(first, r)
                        : node);
            }
            if (Integration.ComputeAsAQuestionOfItsOwn(rewritten.InnerSimplified, x, integrateByParts) is not { } answer)
                return null;
            if (answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            // Checked at sampled points where a symbol is involved -- a point where the
            // derivative cannot be evaluated, a fractional power of a complex number at a
            // symbol, is not a verdict -- and the simplified answer must not be NaN either:
            // a piecewise with complex coefficients simplified to NaN for
            // `x e^(-2 i arctan(a + b x))`, and an answer that simplifies to a claim of
            // non-existence is not given.
            if (expr.Vars.Any(symbol => symbol != x) && !Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                return null;
            if (answer.Nodes.Any(node => node is Piecewise) && answer.Simplify().Nodes.Any(node => node == MathS.NaN))
                return null;
            return answer;
        }

        /// <summary>
        /// An integrand holding an inverse hyperbolic function of a linear in the variable,
        /// integrated by the substitution that undoes it. The inverse hyperbolic functions
        /// are not nodes here -- <c>arsinh(L)</c> is written <c>ln(L + sqrt(L^2 + 1))</c>,
        /// <c>arcosh(L)</c> is <c>ln(L + sqrt(L^2 - 1))</c> and <c>artanh(L)</c> is
        /// <c>ln((1 + L)/(1 - L))/2</c> -- so the logarithm is read for the function it is,
        /// and under <c>L = sinh(u)</c>, <c>cosh(u)</c> or <c>tanh(u)</c> it is <c>u</c>, the
        /// radical of <c>L^2 + 1</c> is <c>cosh(u)</c>, of <c>L^2 - 1</c> is <c>sinh(u)</c>
        /// (for <c>u</c> not negative, where the principal <c>arcosh</c> lies) and
        /// <c>1 - L^2</c> is <c>sech(u)^2</c>; a constant multiple of the quadratic is the
        /// multiple's power times that, the generic case. What is left is a function of
        /// <c>u</c> and of exponentials of it, which the exponential rules read: Rubi's
        /// <c>x arsinh(a x)</c> is <c>u sinh(2u)/(2 a^2)</c>, parts once, where parts in
        /// <c>x</c> left the logarithm's derivative as a quotient of radicals.
        /// The way back writes <c>e^u</c> as <c>L + sqrt(L^2 + 1)</c> and <c>e^(-u)</c> as
        /// <c>sqrt(L^2 + 1) - L</c>, on the principal branch.
        /// <c>arsech(L)</c> and <c>arcsch(L)</c> are the <c>arcosh</c> and <c>arsinh</c> of
        /// <c>1/L</c>, and so <c>u</c> under <c>L = sech(u)</c> and <c>L = csch(u)</c>, with
        /// <c>e^u</c> as <c>1/L + sqrt(1/L^2 - 1)</c> and <c>1/L + sqrt(1/L^2 + 1)</c>: Rubi's
        /// <c>1/(x^2 (a + b arcsch(c x)))</c> is <c>-c cosh(u)/(a + b u)</c>, which the
        /// hyperbolic sine and cosine integrals answer.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByInverseHyperbolicSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // The one inverse hyperbolic function in the integrand, read off its logarithm.
            Entity? inverse = null;
            Entity? argument = null;
            var kind = 0;   // 1 sinh, 2 cosh, 3 tanh, 4 sech, 5 csch
            foreach (var node in expr.Nodes)
            {
                if (node is not Logf(var @base, var antilogarithm) || @base != MathS.e || !antilogarithm.ContainsNode(x))
                    continue;
                var read = ReadAnInverseHyperbolic(antilogarithm, x);
                if (read is null)
                    return null;   // a logarithm of something else: not this route's
                if (inverse is not null && inverse != node)
                    return null;
                (inverse, argument, kind) = (node, read.Value.Argument, read.Value.Kind);
            }
            if (inverse is null || argument is null)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset) || slope is null || offset is null
                || TreeAnalyzer.IsZero(slope) || slope.Evaled is Number.Complex { IsZero: true })
                return null;
            // The secant's and the cosecant's are taken only where they land on what the rules for
            // exponentials close: `x^m` beside a function of the inverse alone, `m <= -2`, and the
            // argument `c x`. Under `x = sech(u)/c` that is `cosh(u)^(-m - 2) sinh(u)` times the
            // function of u, a polynomial in `e^u` and `e^(-u)` -- `1/(x^2 (a + b arcsch(c x)))` is
            // `-c cosh(u)/(a + b u)` -- where a power of x above the bar is a power of `cosh(u)` below
            // it: `x^3 arsech(a x)^2` is `u^2 sinh(u)/cosh(u)^5` over `-a^4`. By parts in x answers
            // such integrands in a fraction of a second, where the searches in u held their test
            // past five minutes.
            if (kind >= 4 && (!TreeAnalyzer.IsZero(offset) || APowerOfXBesideAFunctionOfTheInverse(expr, inverse, x) is not { } degree || degree > -2))
                return null;
            // The tangent's logarithm carries a half in front: `ln((1 + L)/(1 - L))/2` is u, and
            // the logarithm alone is 2u.
            var u = Variable.CreateUnique(expr, "u_inv");
            var expU = MathS.Pow(MathS.e, u);
            var expMinusU = MathS.Pow(MathS.e, -u);
            var sinh = (expU - expMinusU) / 2;
            var cosh = (expU + expMinusU) / 2;
            Entity argumentInU, dArgument;
            Entity? radicandBase, root;
            switch (kind)
            {
                case 1:
                    (argumentInU, dArgument, radicandBase, root) = (sinh, cosh, MathS.Sqr(argument) + 1, cosh);
                    break;
                case 2:
                    (argumentInU, dArgument, radicandBase, root) = (cosh, sinh, MathS.Sqr(argument) - 1, sinh);
                    break;
                case 3:
                    (argumentInU, dArgument, radicandBase, root) = (sinh / cosh, 1 / MathS.Sqr(cosh), 1 - MathS.Sqr(argument), 1 / cosh);
                    break;
                // The principal arsech is not negative, so the root of `1 - sech(u)^2` is
                // `tanh(u)`; the arcsch takes either sign, and the root of `1 + csch(u)^2` is
                // `|coth(u)|`, which is no radical this route removes.
                case 4:
                    (argumentInU, dArgument, radicandBase, root) = (1 / cosh, -sinh / MathS.Sqr(cosh), 1 - MathS.Sqr(argument), sinh / cosh);
                    break;
                default:
                    (argumentInU, dArgument, radicandBase, root) = (1 / sinh, -cosh / MathS.Sqr(sinh), (Entity?)null, (Entity?)null);
                    break;
            }
            var logarithmInU = kind == 3 ? 2 * u : u;

            var radicalsRemoved = 0;
            var rewritten = expr
                .Substitute(inverse, logarithmInU)
                .Replace(node =>
                {
                    if (radicandBase is null || root is null)
                        return node;
                    if (node is Powf(var wholeBase, Number.Integer whole) && whole.EInteger.CompareTo(EInteger.FromInt32(2)) >= 0
                        && whole.EInteger.CompareTo(EInteger.FromInt32(64)) <= 0 && wholeBase.ContainsNode(x)
                        && TreeAnalyzer.TryGetPolyQuadratic(wholeBase, x, out _, out _, out _)
                        && TryReadAConstantMultipleOf(wholeBase, radicandBase, x) is { } wholeMultiple)
                    {
                        radicalsRemoved++;
                        return MathS.Pow(wholeMultiple, whole) * MathS.Pow(root, 2 * whole.EInteger.ToInt32Unchecked());
                    }
                    if (!TryReadAHalfPower(node, out var @base, out var numerator))
                        return node;
                    if (IsTheSameQuadratic(@base, radicandBase, x))
                    {
                        radicalsRemoved++;
                        return MathS.Pow(root, numerator);
                    }
                    if (TreeAnalyzer.TryGetPolyQuadratic(@base, x, out _, out _, out _) && TryReadAConstantMultipleOf(@base, radicandBase, x) is { } multiple)
                    {
                        radicalsRemoved++;
                        return MathS.Pow(multiple, Number.Rational.Create(numerator, 2)) * MathS.Pow(root, numerator);
                    }
                    return node;
                });
            var powerOfTheInverse = expr.Nodes.Any(node =>
                node is Powf(var @base, Number.Integer power) && power.EInteger.CompareTo(EInteger.One) > 0
                    && @base.ContainsNode(inverse) && !@base.Substitute(inverse, u).ContainsNode(x));
            var exponentialOfTheInverse = expr.Nodes.Any(node =>
                node is Powf(var @base, var power) && !@base.ContainsNode(x) && power.ContainsNode(inverse));
            // Any other root of x is one the construction did not reach, and worse in u.
            if (rewritten.Nodes.Any(node =>
                    node is Powf(var @base, Number.Rational power) && power is not Number.Integer && @base.ContainsNode(x)))
                return null;
            // Taken whenever the inverse is there, unlike the trigonometric route: parts in x
            // does not read the logarithm's derivative, a quotient of radicals, so there is no
            // answer in x to prefer -- unless another function of x stands beside it, which
            // the exponentials of u do not read: `x arctan(x) arsinh(x)/sqrt(1 + x^2)` is
            // `u sinh(u) arctan(sinh(u))` under the sine, ten seconds of search that found
            // nothing, where parts in x answers it in seventy milliseconds.
            _ = (radicalsRemoved, powerOfTheInverse, exponentialOfTheInverse);
            if (rewritten.Nodes.Any(node => node is Function && node is not Powf && node != inverse && node.ContainsNode(x)))
                return null;
            rewritten = rewritten.Substitute(x, ((argumentInU - offset) / slope).InnerSimplified);
            if (rewritten.ContainsNode(x))
                return null;
            var (numerator, denominator) = Functions.SingleQuotient.Of((rewritten * dArgument / slope).InnerSimplified);
            var integrand = CancelCommonFactors(numerator, denominator);
            if (integrand is Providedf(var inner, _))
                integrand = inner;
            // A product of powers of the hyperbolic functions is a product of powers of sums
            // of exponentials, which no rule reads whole; expanded, it is a sum of `u^n e^(k u)`
            // terms, each closed. Only where the denominator is free of u, since expanding a
            // quotient's numerator alone helps nothing.
            if (integrand is not Divf(_, var below) || !below.ContainsNode(u))
            {
                var expanded = integrand.Expand();
                if (expanded is Sumf)
                    integrand = expanded;
            }
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts) is not { } result)
                return null;
            // The way back: u is the inverse function, e^u and e^(-u) its two exponentials in
            // the argument, on the principal branch.
            Entity plus, minus;
            switch (kind)
            {
                case 1:
                    (plus, minus) = (argument + MathS.Sqrt(MathS.Sqr(argument) + 1), MathS.Sqrt(MathS.Sqr(argument) + 1) - argument);
                    break;
                case 2:
                    (plus, minus) = (argument + MathS.Sqrt(MathS.Sqr(argument) - 1), argument - MathS.Sqrt(MathS.Sqr(argument) - 1));
                    break;
                case 4:
                    (plus, minus) = (1 / argument + MathS.Sqrt(1 / MathS.Sqr(argument) - 1), 1 / argument - MathS.Sqrt(1 / MathS.Sqr(argument) - 1));
                    break;
                case 5:
                    (plus, minus) = (1 / argument + MathS.Sqrt(1 / MathS.Sqr(argument) + 1), MathS.Sqrt(1 / MathS.Sqr(argument) + 1) - 1 / argument);
                    break;
                default:
                    // e^(-u) as the reciprocal, not as the root of the reciprocal: off the real
                    // domain the principal roots of a quotient and of its reciprocal are not
                    // reciprocals, and the check at sampled points found the difference.
                    (plus, minus) = (MathS.Sqrt((1 + argument) / (1 - argument)), 1 / MathS.Sqrt((1 + argument) / (1 - argument)));
                    break;
            }
            var back = result
                .Replace(node => node switch
                {
                    Powf(var b, var e) when b == MathS.e && e == u => plus,
                    Powf(var b, var e) when b == MathS.e && e.ContainsNode(u) && TreeAnalyzer.TryGetPolyLinear(e, u, out var k, out var m) && k is { } && m is { } && !k.ContainsNode(u) && !m.ContainsNode(u)
                        => k.Evaled is Number.Integer { EInteger.Sign: < 0 } ? MathS.Pow(MathS.e, m) * MathS.Pow(minus, -k) : MathS.Pow(MathS.e, m) * MathS.Pow(plus, k),
                    _ => node,
                })
                .Substitute(u, kind == 3 ? inverse / 2 : inverse);
            if (back.ContainsNode(u) || back.Nodes.Any(node => node == MathS.NaN))
                return null;
            // Checked on the real domain of the inverse, where the identities the route rests
            // on hold -- with the symbols pinned to values near one, the argument is inside
            // (-1, 1) at small x for the tangent and past 1 at large x for the cosine -- and
            // then at the default points as well, some of them off that domain: an integrand
            // can be real there through two imaginary factors cancelling, `e^artanh(a x)` over
            // `sqrt(1 - a^2 x^2)` past `a x = 1`, and an answer that holds only on the domain
            // is a wrong answer at every such point. Declined rather than given there, so that
            // a route answering everywhere can.
            var points = kind switch
            {
                2 => new[] { "1.43", "3.17", "2.2", "5.1" },
                3 => new[] { "0.29", "-0.61", "0.13", "-0.4" },
                // Inside (0, 1] for a slope up to about four, where the principal arsech is real.
                4 => new[] { "0.07", "0.11", "0.19", "0.23" },
                _ => null,
            };
            var derivative = back.Differentiate(x);
            if (points is { } && !Functions.PartialFractions.HoldsAtSampledPoints(derivative, expr, x, points))
                return null;
            if (!Functions.PartialFractions.HoldsAtSampledPoints(derivative, expr, x))
            {
                // Where the integrand is not real off the tangent's domain either, the answer
                // has nothing there to be wrong about: it is given on the domain and says so,
                // as an answer through an even root says where the root is real. Rubi's
                // `1/((1 - a^2 x^2)^(5/2) artanh(a x))` is `(Chi(3 u) + 3 Chi(u))/(4 a)` for
                // `u = artanh(a x)`, and past `a x = 1`, where `sqrt(1 - a^2 x^2)` is not
                // `sech(u)`, the integrand is not real.
                if (kind != 3 || Functions.PartialFractions.DiffersWhereReal(derivative, expr, x))
                    return null;
                return back.Provided(1 - MathS.Sqr(argument) > Number.Integer.Zero);
            }
            return back;
        }

        /// <summary>
        /// The <c>m</c> for which <paramref name="expr"/> is <c>x^m</c> times a function of
        /// <paramref name="inverse"/> alone, else null: with the inverse written as a symbol, such an
        /// integrand at <c>2x</c> is <c>2^m</c> times itself wherever it is evaluated, and two points
        /// with every other symbol pinned say whether it is.
        /// </summary>
        private static int? APowerOfXBesideAFunctionOfTheInverse(Entity expr, Entity inverse, Entity.Variable x)
        {
            var w = Variable.CreateUnique(expr, "w_inv");
            var inW = expr.Substitute(inverse, w);
            if (!inW.ContainsNode(x))
                return 0;
            using var _ = MathS.Settings.DowncastingEnabled.Set(false);
            var pins = new[] { "0.61", "1.37", "2.23", "0.83", "1.91" };
            var index = 0;
            foreach (var symbol in inW.Vars.Where(symbol => symbol != x).ToList())
                inW = inW.Substitute(symbol, Number.Real.Create(EDecimal.FromString(pins[index++ % pins.Length])));
            double? RatioAt(string at)
            {
                var point = EDecimal.FromString(at);
                if (inW.Substitute(x, Number.Real.Create(point.Multiply(2))).Evaled is not Number.Complex doubled
                    || inW.Substitute(x, Number.Real.Create(point)).Evaled is not Number.Complex single
                    || single.IsZero || doubled.IsNaN || single.IsNaN)
                    return null;
                // Read by its parts, since with the downcasting off a quotient on the real line is
                // still a Complex.
                var ratio = doubled / single;
                var real = ratio.RealPart.EDecimal;
                return real.IsFinite && real.Sign > 0 && ratio.ImaginaryPart.EDecimal.Abs().CompareTo(real.Multiply(EDecimal.FromString("1e-30"))) <= 0
                    ? real.ToDouble() : null;
            }
            if (RatioAt("0.37") is not { } first || RatioAt("0.53") is not { } second)
                return null;
            var degree = System.Math.Log(first, 2);
            var rounded = System.Math.Round(degree);
            if (System.Math.Abs(degree - rounded) > 1e-9 || System.Math.Abs(System.Math.Log(second, 2) - rounded) > 1e-9)
                return null;
            return (int)rounded;
        }

        /// <summary>
        /// The argument and the kind (1 <c>arsinh</c>, 2 <c>arcosh</c>, 3 <c>artanh</c>,
        /// 4 <c>arsech</c>, 5 <c>arcsch</c>) of the inverse hyperbolic function whose logarithm
        /// has <paramref name="antilogarithm"/> as its argument -- <c>L + sqrt(L^2 + 1)</c>,
        /// <c>L + sqrt(L^2 - 1)</c>, <c>(1 + L)/(1 - L)</c>, <c>1/L + sqrt(1/L^2 - 1)</c> or
        /// <c>1/L + sqrt(1/L^2 + 1)</c> for a linear <c>L</c> -- else null.
        /// </summary>
        private static (Entity Argument, int Kind)? ReadAnInverseHyperbolic(Entity antilogarithm, Entity.Variable x)
        {
            if (antilogarithm is Sumf(var left, var right))
            {
                foreach (var (linear, radical) in new[] { (left, right), (right, left) })
                {
                    if (!TryReadAHalfPower(radical, out var radicand, out var numeratorOfHalf) || numeratorOfHalf != 1 || !linear.ContainsNode(x))
                        continue;
                    if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out _) || slope is null || TreeAnalyzer.IsZero(slope))
                        continue;
                    if (IsTheSameQuadraticOnceSimplified(radicand, MathS.Sqr(linear) + 1, x))
                        return (linear, 1);
                    if (IsTheSameQuadraticOnceSimplified(radicand, MathS.Sqr(linear) - 1, x))
                        return (linear, 2);
                }
                // The secant's and the cosecant's are the cosine's and the sine's of the
                // reciprocal: `arsech(L)` is `ln(1/L + sqrt(1/L^2 - 1))` and `arcsch(L)` is
                // `ln(1/L + sqrt(1/L^2 + 1))`.
                foreach (var (reciprocal, radical) in new[] { (left, right), (right, left) })
                {
                    if (!TryReadAHalfPower(radical, out var radicand, out var numeratorOfHalf) || numeratorOfHalf != 1 || !reciprocal.ContainsNode(x))
                        continue;
                    // Read off the bar where it is written as one, since the simplification leaves
                    // `1/(1/(c x))` as it is, and the answer would carry it.
                    var linear = reciprocal switch
                    {
                        Divf(var one, var denominator) when one == Number.Integer.One => denominator,
                        Powf(var @base, Number.Integer minusOne) when minusOne == Number.Integer.MinusOne => @base,
                        _ => (1 / reciprocal).InnerSimplified,
                    };
                    if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out _) || slope is null || TreeAnalyzer.IsZero(slope))
                        continue;
                    if (VanishesOnceSimplified(radicand - (1 / MathS.Sqr(linear) - 1)))
                        return (linear, 4);
                    if (VanishesOnceSimplified(radicand - (1 / MathS.Sqr(linear) + 1)))
                        return (linear, 5);
                }
                return null;
            }
            if (antilogarithm is Divf(var above, var below)
                && TreeAnalyzer.TryGetPolyLinear(above, x, out var slopeAbove, out var offsetAbove) && slopeAbove is { } && offsetAbove is { }
                && TreeAnalyzer.TryGetPolyLinear(below, x, out var slopeBelow, out var offsetBelow) && slopeBelow is { } && offsetBelow is { }
                && VanishesOnceSimplified(slopeAbove + slopeBelow)
                && VanishesOnceSimplified(offsetAbove - 1)
                && VanishesOnceSimplified(offsetBelow - 1))
                return ((slopeAbove * x).InnerSimplified, 3);
            return null;

            // Zero as written, evaluated, or once simplified: `a + (-a)` for a symbol a.
            static bool VanishesOnceSimplified(Entity expr)
                => expr.InnerSimplified.Evaled is Number.Complex { IsZero: true }
                    || expr.Vars.Any() && Functions.PartialFractions.Bare(expr.Simplify()).Evaled is Number.Complex { IsZero: true };

            // The same quadratic coefficient by coefficient, with symbols: `(c x)^2 + 1`
            // against `c^2 x^2 + 1`, which the evaluated difference does not settle.
            static bool IsTheSameQuadraticOnceSimplified(Entity candidate, Entity wanted, Entity.Variable x)
                => TreeAnalyzer.TryGetPolyQuadratic(candidate, x, out var a, out var b, out var c)
                   && TreeAnalyzer.TryGetPolyQuadratic(wanted, x, out var a2, out var b2, out var c2)
                   && a is { } && b is { } && c is { } && a2 is { } && b2 is { } && c2 is { }
                   && VanishesOnceSimplified(a - a2) && VanishesOnceSimplified(b - b2) && VanishesOnceSimplified(c - c2);
        }

        /// <summary>
        /// A trigonometric function of the inverse function of <paramref name="x"/> written
        /// in <paramref name="x"/>, on the principal branch: <c>cos(arcsin(x))</c> is
        /// <c>sqrt(1 - x^2)</c> there, since the cosine is not negative on
        /// <c>[-pi/2, pi/2]</c>; <c>tan(arcsec(x))</c> is <c>x sqrt(1 - 1/x^2)</c>, the sine
        /// not negative on <c>[0, pi]</c>; and the cosine of <c>arccot(x)</c>, whose range
        /// here is <c>(-pi/2, pi/2]</c>, is <c>|x|/sqrt(1 + x^2)</c>. Whatever is not one of
        /// these compositions, a multiple angle among them, is left as it is.
        /// </summary>
        private static Entity TrigonometryOfTheInverseInX(Entity result, Entity inverse, Entity x)
        {
            Entity sine, cosine;
            switch (inverse)
            {
                case Arcsinf:
                    (sine, cosine) = (x, MathS.Sqrt(1 - MathS.Sqr(x)));
                    break;
                case Arccosf:
                    (sine, cosine) = (MathS.Sqrt(1 - MathS.Sqr(x)), x);
                    break;
                case Arctanf:
                    (sine, cosine) = (x / MathS.Sqrt(1 + MathS.Sqr(x)), 1 / MathS.Sqrt(1 + MathS.Sqr(x)));
                    break;
                case Arccotanf:
                    (sine, cosine) = (MathS.Abs(x) / (x * MathS.Sqrt(1 + MathS.Sqr(x))), MathS.Abs(x) / MathS.Sqrt(1 + MathS.Sqr(x)));
                    break;
                case Arcsecantf:
                    (sine, cosine) = (MathS.Sqrt(1 - 1 / MathS.Sqr(x)), 1 / x);
                    break;
                case Arccosecantf:
                    (sine, cosine) = (1 / x, MathS.Sqrt(1 - 1 / MathS.Sqr(x)));
                    break;
                default:
                    return result;
            }
            var written = result.Replace(node => node switch
            {
                Sinf(var argument) when argument == inverse => sine,
                Cosf(var argument) when argument == inverse => cosine,
                Tanf(var argument) when argument == inverse => sine / cosine,
                Cotanf(var argument) when argument == inverse => cosine / sine,
                Secantf(var argument) when argument == inverse => 1 / cosine,
                Cosecantf(var argument) when argument == inverse => 1 / sine,
                _ => node,
            });
            return written == result ? result : written.InnerSimplified;
        }

        /// <summary>
        /// <c>base^(n/2)</c> in either of its spellings, <c>(base)^(3/2)</c> or <c>sqrt(base)^3</c>:
        /// the second is the first on the principal branch, since <c>Log(sqrt(z)) = Log(z)/2</c>
        /// exactly, so <c>(z^(1/2))^n = z^(n/2)</c> for every integer <c>n</c>.
        /// </summary>
        private static bool TryReadAHalfPower(Entity node, out Entity @base, out int numerator)
        {
            @base = 0;
            numerator = 0;
            switch (node)
            {
                case Powf(var inner, Number.Rational half)
                    when half is not Number.Integer
                         && half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                         && half.ERational.Numerator.CanFitInInt32():
                    @base = inner;
                    numerator = half.ERational.Numerator.ToInt32Unchecked();
                    return true;
                case Powf(Powf(var inner, Number.Rational half), Number.Integer power)
                    when half is not Number.Integer
                         && half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                         && half.ERational.Numerator.CanFitInInt32()
                         && power.EInteger.CanFitInInt32():
                    @base = inner;
                    numerator = half.ERational.Numerator.ToInt32Unchecked() * power.EInteger.ToInt32Unchecked();
                    return true;
                default:
                    return false;
            }
        }

        /// <summary>
        /// Whether <paramref name="candidate"/> is the quadratic <paramref name="wanted"/> in
        /// <paramref name="x"/>, by coefficients rather than by spelling.
        /// </summary>
        private static bool IsTheSameQuadratic(Entity candidate, Entity wanted, Entity.Variable x)
            => TreeAnalyzer.TryGetPolyQuadratic(candidate, x, out var a, out var b, out var c)
               && TreeAnalyzer.TryGetPolyQuadratic(wanted, x, out var a2, out var b2, out var c2)
               && (a - a2).Evaled is Number.Complex { IsZero: true }
               && (b - b2).Evaled is Number.Complex { IsZero: true }
               && (c - c2).Evaled is Number.Complex { IsZero: true };

        /// <summary>
        /// An integrand that is a function of <c>ln(x)</c> and of nothing else, integrated by the
        /// substitution <c>u = ln(x)</c>, under which <c>dx</c> is <c>e^u du</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sin(ln(x))</c> had no antiderivative, and it is one substitution away from one that
        /// does: under <c>u = ln(x)</c> it becomes <c>e^u sin(u)</c>, which is the cyclic
        /// by-parts integral and is closed by
        /// <see cref="SolveAPolynomialTimesAnExponentialAndATrigonometric"/>. The same for
        /// <c>ln(x)^n</c> beside anything, and for <c>e^(1/ln(x))</c> and its kin.
        /// </para>
        /// <para>
        /// <b>The substitution is an inverse one</b>, which is what makes it different from every
        /// other substitution here and why the general one does not find it. The others divide by
        /// <c>du/dx</c> and ask what is left; this one goes the other way — <c>x = e^u</c>, so
        /// <c>dx</c> is <c>e^u du</c>, and the exponential is <b>introduced</b> rather than
        /// cancelled. That only pays because the integrator answers exponentials times almost
        /// anything.
        /// </para>
        /// <para>
        /// <b>The test is the rewrite itself</b>: replace every <c>ln(x)</c> and see whether an
        /// <c>x</c> survives. <c>ln(x) + x</c> keeps one and is declined, which is right — it is
        /// not a function of the logarithm alone. A different base is read through first, since
        /// <c>log(b, x)</c> is <c>ln(x)/ln(b)</c> and declining it for the spelling would be the
        /// defect this file has had repeatedly.
        /// </para>
        /// <para>
        /// <b>Where the answer holds.</b> <c>u = ln(x)</c> is a bijection from the positive reals
        /// to the whole line, so the answer is an antiderivative for <c>x &gt; 0</c> — which is
        /// where an integrand built from <c>ln(x)</c> is real, with one kind of exception. A
        /// radical function of whole powers of <c>x = e^u</c>, <c>sqrt(sinh(2 ln(x)))</c> or
        /// <c>1/csch(2 ln(x))^(1/2)</c>, is real for a negative <c>x</c> too, where <c>ln(x)</c>
        /// is <c>ln(-x) + i pi</c>; and the rules that integrate it in <c>u</c> take <c>e^u</c> to
        /// be positive, which it is for every real <c>u</c>. That answer is given
        /// <c>provided x &gt; 0</c>. Written in powers of <c>x</c>, which
        /// <see cref="SolveByFoldingAnExponentialOfALogarithm"/> does before this, the same
        /// integrand is answered on both sides of zero where the rules read it.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByLogarithmSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // A logarithm to another base first: log(b, x) is ln(x)/ln(b), and a rule that
            // declined it for having a different node would be answering the spelling.
            expr = expr.Replace(node =>
                node is Logf(var @base, var argument) && !@base.ContainsNode(x) && @base != MathS.e
                    ? MathS.Ln(argument) / MathS.Ln(@base)
                    : node);

            var logarithm = MathS.Ln(x);
            if (!expr.ContainsNode(logarithm))
                return null;

            var u = Variable.CreateUnique(expr, "u_log");
            var inU = expr.Substitute(logarithm, u);
            if (inU.ContainsNode(x))
                return null;

            var integrand = Functions.SingleQuotient.Combine(inU * MathS.Pow(MathS.e, u)).InnerSimplified;
            if (integrand is Providedf(var inner, _))
                integrand = inner;

            if (Integration.ComputeIndefiniteIntegral(integrand, u, integrateByParts) is not { } result)
                return null;
            var back = result.Substitute(u, MathS.Ln(x));
            return IsARadicalFunctionOfWholePowersOfTheExponential(inU, u) ? back.Provided(x > Number.Integer.Zero) : back;
        }

        /// <summary>
        /// Whether <paramref name="expr"/> holds <paramref name="t"/> only in exponentials
        /// <c>e^(k t + a)</c> with a whole <c>k</c>, some of them under a power that is not
        /// whole: a radical function of whole powers of <c>e^t</c>. At <c>t = s + i pi</c>,
        /// where a substitution <c>t = ln(c x^n)</c> lands for a negative <c>c x^n</c>, it is the
        /// same function of <c>-e^s</c>, real again wherever its radicands are positive; and an
        /// integral of it in <c>t</c> is found for a real <c>t</c>, under which <c>e^t</c> is
        /// positive and gives up its powers from under a root.
        /// </summary>
        private static bool IsARadicalFunctionOfWholePowersOfTheExponential(Entity expr, Entity.Variable t)
        {
            var exponential = Variable.CreateUnique(expr, "w_exp");
            var inExponentials = expr.Replace(node =>
                node is Powf(var @base, var exponent) && @base == MathS.e && exponent.ContainsNode(t)
                && TreeAnalyzer.TryGetPolyLinear(exponent, t, out var slope, out var offset)
                && slope.Evaled is Number.Integer && !offset.ContainsNode(t)
                    ? exponential
                    : node);
            return !inExponentials.ContainsNode(t)
                && inExponentials.Nodes.Any(node => node is Powf(var @base, var power) && @base.ContainsNode(exponential) && power.Evaled is not Number.Integer);
        }

        /// <summary>
        /// A power of <c>x</c> times a function of one logarithm of a monomial, <c>x^m G(ln(c x^n))</c>,
        /// under <c>t = ln(c x^n)</c>: <c>dx = x dt/n</c>, and <c>x^(m + 1)</c> is
        /// <c>K e^((m + 1) t/n)</c> with <c>K = x^(m + 1) (c x^n)^(-(m + 1)/n)</c>, whose derivative
        /// is 0 wherever it is defined. So the answer is <c>K/n</c> times the integral of
        /// <c>e^((m + 1) t/n) G(t)</c> at <c>t = ln(c x^n)</c>, an antiderivative wherever
        /// <c>c x^n</c> is positive -- for an even <c>n</c> and a positive <c>c</c> the whole line,
        /// negative <c>x</c> included, where <c>ln(c x^n)</c> is not <c>ln(c) + n ln(x)</c>. Where
        /// <c>c x^n</c> is negative, <c>t</c> is <c>ln(-c x^n) + i pi</c>, and a function of whole
        /// powers of <c>e^t</c>, <c>sqrt(sinh(2 t))</c> say, is real there as well; a radical one
        /// has its integral in <c>t</c> found for a real <c>t</c>, under which <c>e^t</c> is
        /// positive, so that answer is given <c>provided c x^n &gt; 0</c>. A power of a monomial,
        /// <c>(e x)^p</c>, is <c>x^p</c> times a factor of the same kind. What by parts leaves of
        /// <c>(e x)^m Si(d (a + b ln(c x^n)))</c> is this, with <c>G(t)</c> a sine over a linear in
        /// <c>t</c>. Rubi's answers to 8.3 to 8.5 are written in exactly this <c>K</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// After <see cref="SolveByLogarithmSubstitution"/>, which answers <c>ln(x)</c> alone.
        /// </remarks>
        internal static Entity? SolveByAPowerAndALogarithmOfAMonomial(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Logf))
                return null;
            Entity constant = Number.Integer.One;
            Entity m = Number.Integer.Zero;
            Entity locallyConstant = Number.Integer.One;
            Entity rest = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                // x, a power of x, or a power of a monomial (k x)^p, p free of x.
                var (@base, power) = factor is Powf(var raised, var exponent) && !exponent.ContainsNode(x) ? (raised, exponent) : (factor, (Entity)Number.Integer.One);
                if (TheMonomial(@base, x) is var (coefficientOfIt, degreeOfIt) && degreeOfIt == Number.Integer.One)
                {
                    var p = underneath ? -power : power;
                    m = m + p;
                    if (coefficientOfIt != Number.Integer.One)
                        locallyConstant = locallyConstant * MathS.Pow(@base, p) * MathS.Pow(x, -p);
                    continue;
                }
                rest = underneath ? rest / factor : rest * factor;
            }
            // One logarithm of a monomial in what is left.
            var logarithms = rest.Nodes.OfType<Logf>().Where(node => node.Base == MathS.e && node.ContainsNode(x)).Distinct().ToList();
            if (logarithms.Count != 1 || TheMonomial(logarithms[0].Antilogarithm, x) is not var (c, n) || TreeAnalyzer.IsZero(n))
                return null;
            var t = Variable.CreateUnique(expr, "t_log");
            var inT = rest.Substitute(logarithms[0], t);
            if (inT.ContainsNode(x))
                return null;
            var mPlusOne = (m + Number.Integer.One).InnerSimplified;
            // One quotient, as the logarithm substitution writes its own: `e^((m + 2) t)/t` is the
            // exponential integral, and as a product with `t^(-1)` it went to integration by parts.
            // https://github.com/asc-community/AngouriMath/issues/1646
            var integrand = Functions.SingleQuotient.Combine(inT * MathS.Pow(MathS.e, (mPlusOne / n).InnerSimplified * t)).InnerSimplified;
            if (integrand is Providedf(var bare, _))
                integrand = bare;
            if (Integration.ComputeIndefiniteIntegral(integrand, t, integrateByParts) is not { } inTIntegral)
                return null;
            // Of ln(x) itself, K is 1, and written as x^(m + 1) x^(-(m + 1)) it is not seen to be.
            var k = logarithms[0].Antilogarithm == x ? Number.Integer.One
                : MathS.Pow(x, mPlusOne) * MathS.Pow(logarithms[0].Antilogarithm, (-mPlusOne / n).InnerSimplified);
            var back = constant * locallyConstant * k / n * inTIntegral.Substitute(t, logarithms[0]);
            if (back.Nodes.Any(node => node == MathS.NaN))
                return null;
            // Positive for every x other than 0 when n is even and c a positive number, and
            // nothing to say then.
            var positiveEverywhere = n.Evaled is Number.Integer whole && whole.EInteger.IsEven && c.Evaled is Number.Real { IsPositive: true };
            return !positiveEverywhere && IsARadicalFunctionOfWholePowersOfTheExponential(inT, t)
                ? back.Provided(logarithms[0].Antilogarithm > Number.Integer.Zero)
                : back;
        }

        /// <summary>
        /// <paramref name="expr"/> as <c>c x^n</c>, <c>c</c> and <c>n</c> free of <paramref name="x"/>,
        /// or <see langword="null"/>.
        /// </summary>
        private static (Entity Coefficient, Entity Degree)? TheMonomial(Entity expr, Entity.Variable x)
        {
            if (expr == x)
                return (Number.Integer.One, Number.Integer.One);
            if (expr is Powf(var @base, var power) && @base == x && !power.ContainsNode(x))
                return (Number.Integer.One, power);
            if (expr is Mulf(var left, var right))
            {
                if (!left.ContainsNode(x) && TheMonomial(right, x) is var (c, n))
                    return (left * c, n);
                if (!right.ContainsNode(x) && TheMonomial(left, x) is var (c2, n2))
                    return (right * c2, n2);
            }
            return null;
        }

        /// <summary>
        /// A quotient of two <b>homogeneous</b> polynomials in <c>sin(u)</c> and <c>cos(u)</c>,
        /// integrated by <c>t = tan(u)</c> — which turns it into a rational function of <c>t</c>
        /// whenever the two degrees differ by an even number.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(cos(x) + sin(x))^6</c> took <b>231 seconds</b> to be declined and
        /// <c>1/(b^2 cos(x)^2 + a^2 sin(x)^2)</c> was one of the Rubi sample's three timeouts.
        /// Both are this shape, and so is <c>sin(x)/(cos(x)^3 + sin(x)^3)</c>.
        /// </para>
        /// <para>
        /// <b>Why the degrees decide it.</b> Writing <c>t = tan(u)</c> and <c>c = cos(u)</c>, a
        /// homogeneous polynomial of degree <c>n</c> in the pair is <c>c^n</c> times a polynomial
        /// in <c>t</c> alone. So a quotient of degrees <c>n</c> over <c>d</c> is
        /// <c>c^(n-d) N(t)/D(t)</c>, and with <c>c^2 = 1/(1 + t^2)</c> and
        /// <c>dx = dt/(a(1 + t^2))</c>:
        /// </para>
        /// <code>
        ///     f dx = [N(t)/D(t)] (1 + t^2)^((d - n)/2 - 1) dt / a
        /// </code>
        /// <para>
        /// which is rational exactly when <c>d - n</c> is even. Odd is a genuine boundary rather
        /// than a first cut: there the substitution leaves a square root of <c>1 + t^2</c> behind,
        /// which is a different problem and not a rational one.
        /// </para>
        /// <para>
        /// This is the third of Bioche's rules, and it is the one the other two do not cover:
        /// <see cref="SolveByTangentSubstitution"/> answers an integrand that is a function of
        /// <c>tan</c> <i>alone</i>, and <c>1/(b^2 cos^2 + a^2 sin^2)</c> is not — it is a function
        /// of <c>tan</c> times <c>sec^2</c>, which is what the degree difference of two is saying.
        /// </para>
        /// <para>
        /// <b>Where the answer holds.</b> <c>t = tan(u)</c> is a bijection on each interval
        /// between the poles of the tangent, so the answer is an antiderivative on each of them —
        /// the standing caveat on this substitution, shared with the half-angle one, and not
        /// something this writes as a condition.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByHomogeneousTrigonometricSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator))
                return null;
            if (!TryReadAHomogeneousTrigonometricProduct(numerator, x, out var above, out var aboveDegree, out var argument)
                || !TryReadAHomogeneousTrigonometricProduct(denominator, x, out var below, out var belowDegree, out var otherArgument))
                return null;
            // A side free of the variable is degree zero and names no argument -- `1/(cos + sin)^2`
            // is the common case and was declined for it. Only one side may be silent; if both
            // are, there is no integrand here.
            argument ??= otherArgument;
            otherArgument ??= argument;
            if (argument is null || argument != otherArgument)
                return null;
            var difference = belowDegree - aboveDegree;
            if (difference % 2 != 0)
                return null;   // an odd difference leaves a root of 1 + t^2, which is not rational
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) || rate.Evaled == 0)
                return null;

            var t = Variable.CreateUnique(expr, "t_homog");
            var inT = Functions.SingleQuotient.Combine(
                above.Substitute(HomogeneousTangent, t).Substitute(HomogeneousCosine, 1)
                / below.Substitute(HomogeneousTangent, t).Substitute(HomogeneousCosine, 1)
                * MathS.Pow(1 + MathS.Sqr(t), Number.Integer.Create(difference / 2 - 1))
                / rate).Simplify();
            if (inT is Providedf(var inner, _))
                inT = inner;
            if (inT.ContainsNode(x))
                return null;

            return Integration.ComputeIndefiniteIntegral(inT, t, integrateByParts) is { } result
                ? result.Substitute(t, MathS.Tan(argument))
                : null;
        }

        /// <summary>
        /// A sum of a cosine and a sine of one argument turned into one cosine:
        /// <c>a cos(y) + b sin(y)</c> is <c>R cos(u)</c> for <c>R = sqrt(a^2 + b^2)</c> and
        /// <c>u = y - phi</c>, where <c>cos(y) = (a cos(u) - b sin(u))/R</c> and
        /// <c>sin(y) = (b cos(u) + a sin(u))/R</c>. <c>1/(a cos(x) + b sin(x))^3</c> is
        /// <c>sec(u)^3/R^3</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// This is the case <see cref="SolveByHomogeneousTrigonometricSubstitution"/> cannot take:
        /// a quotient whose degrees in the sine and cosine differ by an odd number, which the
        /// tangent leaves with a root of <c>1 + t^2</c>. After the rotation the denominator is one
        /// power of one cosine, and what is above it a polynomial in <c>cos(u)</c> and
        /// <c>sin(u)</c> with <c>a/R</c> and <c>b/R</c> for coefficients -- shapes the rules for
        /// powers of the sine and cosine answer in a fraction of a second, where the original was
        /// declined after the substitution search had spent its budget.
        /// </para>
        /// <para>
        /// The way back needs no <c>phi</c>, whose quadrant would depend on the signs of
        /// <c>a</c> and <c>b</c>: <c>cos(u)</c> and <c>sin(u)</c> are
        /// <c>(a cos(y) + b sin(y))/R</c> and <c>(a sin(y) - b cos(y))/R</c>, and a bare
        /// <c>u</c> is <c>y</c> less a constant, which belongs to the constant of integration.
        /// An answer holding <c>u</c> in any other way -- <c>tan(u/2)</c>, <c>sin(2u)</c> -- is
        /// declined rather than rewritten. <c>R</c> is the real root for real <c>a</c> and
        /// <c>b</c>, not both zero; where <c>a^2 + b^2</c> is zero -- <c>a cos(y) + i a sin(y)</c>,
        /// which is <c>a e^(i y)</c> -- there is nothing to rotate.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByRotatingACosineAndASineIntoOneCosine(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Below the bar only. A sum above it is a polynomial in the sine and cosine, and the
            // rotation writes one there itself -- `cos(y)` becomes `(a cos(u) - b sin(u))/R` --
            // so a rule that rotated any sum it found would rotate its own output again, and did:
            // `cos(x)/(a cos(x) + b sin(x))^2` went round `u_1`, `u_2`, `u_3` until the budget
            // ran out. After one rotation the denominator is a power of one cosine, and there is
            // nothing left below the bar to rotate.
            // Only sines and cosines: a tangent, cotangent, secant or cosecant is a quotient with
            // a sine or cosine below it, which the rotation turns into one more sum of the two --
            // `csc(x)^2/(a cos(x) + b sin(x))`, declined in a quarter of a second, spent two
            // minutes going round that way when the node sat above the bar where the check
            // below does not see it.
            if (expr.Nodes.Any(node => node is Tanf or Cotanf or Secantf or Cosecantf && node.ContainsNode(x)))
                return null;
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            Entity? sum = null, a = null, b = null, argument = null;
            foreach (var node in below.Nodes)
            {
                if (node is not (Sumf or Minusf) || !node.ContainsNode(x)
                    || !TryReadACosineAndASine(node, x, out var cosineCoefficient, out var sineCoefficient, out var nodeArgument))
                    continue;
                if (sum is not null && node != sum)
                    return null;
                (sum, a, b, argument) = (node, cosineCoefficient, sineCoefficient, nodeArgument);
            }
            if (sum is null || a is null || b is null || argument is null || above.Nodes.Contains(sum))
                return null;
            // And nothing else below the bar holds x. A secant or cosecant above puts a cosine or
            // sine below it, which the rotation turns into another sum of the two -- so
            // `sec(y)/(a cos(y) + b sin(y))^2` rotated into a quotient over one more such sum,
            // and round again. Those want the partial fractions over the two linear factors,
            // which is not this rule; here the denominator becomes one power of one cosine.
            if (below.Replace(node => node == sum ? Number.Integer.One : node).ContainsNode(x))
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out _) || rate.ContainsNode(x)
                || rate.Evaled is Number.Complex { IsZero: true })
                return null;
            // The homogeneous substitution's case is its own: a quotient of homogeneous
            // polynomials whose degrees differ by an even number is rational under the tangent.
            if (TryReadAsQuotient(expr, out var numerator, out var denominator)
                && TryReadAHomogeneousTrigonometricProduct(numerator, x, out _, out var aboveDegree, out _)
                && TryReadAHomogeneousTrigonometricProduct(denominator, x, out _, out var belowDegree, out _)
                && (belowDegree - aboveDegree) % 2 == 0)
                return null;
            var squared = (MathS.Sqr(a) + MathS.Sqr(b)).InnerSimplified;
            if (squared.Evaled is Number.Complex { IsZero: true }
                || squared.Vars.Any() && Functions.PartialFractions.Bare(squared.Simplify()).Evaled is Number.Complex { IsZero: true })
                return null;
            // `R` is integrated as a symbol and written out only in the answer: a root of a
            // symbolic sum in the integrand, constant as it is, sent `cos(x)/(a cos(x) +
            // b sin(x))^2` down the rules for radicals past its budget, where with `R` as a
            // symbol it is a tenth of a second.
            var radius = Variable.CreateUnique(expr, "r_rot");
            var u = Variable.CreateUnique(expr, "u_rot");
            var whole = Variable.CreateUnique(expr, "w_rot");
            var cosU = MathS.Cos(u);
            var sinU = MathS.Sin(u);
            var cosY = (a * cosU - b * sinU) / radius;
            var sinY = (b * cosU + a * sinU) / radius;
            // The sum itself first, as one cosine: rotated term by term it would be
            // `a (a cos(u) - b sin(u))/R + b (b cos(u) + a sin(u))/R`, which the inner
            // simplification does not collect back into `R cos(u)`.
            var rotated = expr.Replace(node => node == sum ? whole : node).Replace(node => node switch
            {
                Cosf(var y) when y == argument => cosY,
                Sinf(var y) when y == argument => sinY,
                _ => node,
            }).Substitute(whole, radius * cosU);
            if (rotated.ContainsNode(x))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn((rotated / rate).InnerSimplified, u, integrateByParts) is not { } inU)
                return null;
            var cosBack = sum / radius;
            var sinBack = (a * MathS.Sin(argument) - b * MathS.Cos(argument)) / radius;
            var back = inU.Replace(node => node switch
            {
                Cosf(var v) when v == u => cosBack,
                Sinf(var v) when v == u => sinBack,
                Tanf(var v) when v == u => sinBack / cosBack,
                Cotanf(var v) when v == u => cosBack / sinBack,
                Secantf(var v) when v == u => radius / sum,
                Cosecantf(var v) when v == u => 1 / sinBack,
                _ => node,
            });
            if (back.ContainsNode(u))
            {
                if (!TreeAnalyzer.TryGetPolyLinear(back, u, out var slope, out _) || slope.ContainsNode(u))
                    return null;
                back = back.Substitute(u, argument);
            }
            return back.Substitute(radius, MathS.Sqrt(squared));
        }

        /// <summary>
        /// Reads <paramref name="sum"/> as <c>a cos(y) + b sin(y)</c>: two terms, a constant times
        /// the cosine and a constant times the sine of one argument holding <paramref name="x"/>.
        /// </summary>
        private static bool TryReadACosineAndASine(Entity sum, Entity.Variable x, out Entity a, out Entity b, out Entity argument)
        {
            a = b = argument = Number.Integer.Zero;
            var terms = Sumf.LinearChildren(sum);
            if (terms.Count != 2)
                return false;
            Entity? cosine = null, sine = null, found = null;
            foreach (var term in terms)
            {
                Entity coefficient = Number.Integer.One;
                Entity? function = null;
                foreach (var factor in Mulf.LinearChildren(term))
                {
                    if (!factor.ContainsNode(x))
                    {
                        coefficient = coefficient == Number.Integer.One ? factor : coefficient * factor;
                        continue;
                    }
                    if (function is not null || factor is not (Cosf or Sinf))
                        return false;
                    function = factor;
                }
                var (isCosine, y) = function switch
                {
                    Cosf(var inner) => (true, inner),
                    Sinf(var inner) => (false, inner),
                    _ => (false, (Entity?)null),
                };
                if (y is null || found is not null && y != found)
                    return false;
                found = y;
                if (isCosine)
                {
                    if (cosine is not null) return false;
                    cosine = coefficient;
                }
                else
                {
                    if (sine is not null) return false;
                    sine = coefficient;
                }
            }
            if (cosine is null || sine is null || found is null)
                return false;
            (a, b, argument) = (cosine, sine, found);
            return true;
        }

        /// <summary>
        /// <see cref="TryReadAHomogeneousTrigonometricPolynomial"/> over a product, a factor at a
        /// time, with a whole power of a factor read as that power of it: the degrees add, and
        /// the rewritten factors are multiplied and raised as they were written.
        /// </summary>
        /// <remarks>
        /// Reading the whole product at once expands it first, and an expanded power is a
        /// polynomial the rational integrator has to factor again: <c>(a cos(x) + b sin(x))^4</c>
        /// became <c>a^4 + 4 a^3 b t + 6 a^2 b^2 t^2 + 4 a b^3 t^3 + b^4 t^4</c> under
        /// <c>t = tan(x)</c>, which with numbers is <c>(2 + 3t)^4</c> again in a moment and with
        /// symbols is a quartic nothing factors -- <c>sec(x)^2/(a cos(x) + b sin(x))^4</c> ran past
        /// ten minutes where <c>(1 + t^2)^2/(a + b t)^4</c> takes half a second. The whole product is
        /// still read at once where a factor on its own is not homogeneous.
        /// </remarks>
        private static bool TryReadAHomogeneousTrigonometricProduct(
            Entity expr, Entity.Variable x, out Entity rewritten, out int degree, out Entity? argument)
        {
            rewritten = Number.Integer.One;
            degree = 0;
            argument = null;
            var factors = Mulf.LinearChildren(expr);
            if (factors.Count > 1 || expr is Powf(_, Number.Integer))
            {
                var product = (Entity)Number.Integer.One;
                var total = 0;
                Entity? common = null;
                var read = true;
                foreach (var factor in factors)
                {
                    var (@base, power) = factor is Powf(var b, Number.Integer whole) && whole.EInteger.CanFitInInt32() && !whole.EInteger.IsZero
                        ? (b, whole.EInteger.ToInt32Checked())
                        : (factor, 1);
                    if (!TryReadAHomogeneousTrigonometricPolynomial(@base, x, out var one, out var oneDegree, out var oneArgument)
                        || oneArgument is not null && common is not null && oneArgument != common)
                    {
                        read = false;
                        break;
                    }
                    common ??= oneArgument;
                    total += power * oneDegree;
                    var raised = power == 1 ? one : MathS.Pow(one, Number.Integer.Create(power));
                    product = product == Number.Integer.One ? raised : product * raised;
                }
                if (read)
                {
                    rewritten = product;
                    degree = total;
                    argument = common;
                    return true;
                }
            }
            return TryReadAHomogeneousTrigonometricPolynomial(expr, x, out rewritten, out degree, out argument);
        }

        /// <summary>The two placeholders a homogeneous polynomial is rewritten over.</summary>
        [ConstantField] private static readonly Entity.Variable HomogeneousTangent =
            Entity.Variable.CreateVariableOrConstant("__homogeneous_tangent");

        /// <summary>See <see cref="HomogeneousTangent"/>.</summary>
        [ConstantField] private static readonly Entity.Variable HomogeneousCosine =
            Entity.Variable.CreateVariableOrConstant("__homogeneous_cosine");

        /// <summary>
        /// Reads <paramref name="expr"/> as a homogeneous polynomial in <c>sin(u)</c> and
        /// <c>cos(u)</c> over one common argument, rewritten with <c>sin(u)</c> as
        /// <c>tangent * cosine</c> and <c>cos(u)</c> as <c>cosine</c> so that the caller can put
        /// <c>cosine</c> to one and read off the polynomial in the tangent.
        /// </summary>
        /// <remarks>
        /// Homogeneous means every term has the same total degree, and that is checked rather
        /// than assumed: <c>1 + cos(u)</c> has terms of degree zero and one and is declined, which
        /// is right — it is not this substitution's, and the half-angle one answers it.
        /// </remarks>
        private static bool TryReadAHomogeneousTrigonometricPolynomial(
            Entity expr, Entity.Variable x, out Entity rewritten, out int degree, out Entity? argument)
        {
            rewritten = expr;
            degree = 0;
            argument = null;

            var found = (Entity?)null;
            var theDegree = (int?)null;
            // The terms with their degrees, for the parity case below.
            var terms = new List<(Entity Term, int Degree)>();
            var expanded = expr.Expand();
            foreach (var term in Entity.Sumf.LinearChildren(expanded))
            {
                var thisDegree = 0;
                foreach (var factor in Entity.Mulf.LinearChildren(term))
                {
                    var (piece, power) = factor is Powf(var @base, Number.Integer whole)
                                         && whole.EInteger.CanFitInInt32()
                        ? (@base, whole.EInteger.ToInt32Checked())
                        : (factor, 1);
                    // The secant and the cosecant are the cosine and the sine to the power
                    // minus one, and the tangent and the cotangent are of degree zero, so a
                    // sum with them in it is homogeneous or not by the same count:
                    // Timofeev's `1/(2 sec(x) + sin(x))^2` has `4 sec^2 + 4 sec sin + sin^2`
                    // below, of degrees -2, 0 and 2, homogeneous up to parity.
                    var (argumentOfThis, degreeOfThis) = piece switch
                    {
                        Sinf(var a) => (a, power),
                        Cosf(var a) => (a, power),
                        Secantf(var a) => (a, -power),
                        Cosecantf(var a) => (a, -power),
                        Tanf(var a) => (a, 0),
                        Cotanf(var a) => (a, 0),
                        _ => (null, 0),
                    };
                    // A trigonometric function free of x is a coefficient: `cos(a)` beside
                    // `sin(x)`, as the unifier writes `sin(x - a)` out, is not a second argument.
                    if (argumentOfThis is null || !argumentOfThis.ContainsNode(x))
                    {
                        if (piece.ContainsNode(x))
                            return false;   // anything else in the term is not this shape
                        continue;
                    }
                    if (found is not null && found != argumentOfThis) return false;
                    found = argumentOfThis;
                    thisDegree += degreeOfThis;
                }
                terms.Add((term, thisDegree));
                if (theDegree is null)
                    theDegree = thisDegree;
                else if (theDegree != thisDegree)
                    theDegree = -1;   // not homogeneous as written; the parity case below
            }
            if (theDegree is null)
                return false;
            if (found is null)
            {
                // No sine or cosine at all: a constant, which is homogeneous of degree zero and
                // needs no rewriting. It names no argument, and the caller takes the other side's.
                degree = 0;
                return !expr.ContainsNode(x);
            }

            // **Homogeneous up to parity is homogeneous**: a term two degrees short of the
            // highest is the same term times `sin^2 + cos^2`, which is one. `sin + sin^2 cos`
            // has degrees one and three and is `sin (sin^2 + cos^2) + sin^2 cos`, of degree
            // three throughout; it is what `cos(x)/(sin(x)(2 + sin(2x)))` has below the bar once
            // its arguments are unified, and it was declined here for the spelling. A term an
            // odd number short is a genuine boundary -- no power of one bridges it.
            var highest = terms.Max(pair => pair.Degree);
            if (theDegree == -1)
            {
                if (terms.Any(pair => (highest - pair.Degree) % 2 != 0))
                    return false;
                var pythagorean = MathS.Sqr(MathS.Sin(found)) + MathS.Sqr(MathS.Cos(found));
                Entity raised = Number.Integer.Zero;
                foreach (var (term, thisDegree) in terms)
                {
                    var levels = (highest - thisDegree) / 2;
                    var lifted = levels == 0 ? term : term * MathS.Pow(pythagorean, levels);
                    raised = raised == Number.Integer.Zero ? lifted : raised + lifted;
                }
                expanded = raised.Expand();
            }

            degree = highest;
            argument = found;
            rewritten = expanded.Replace(node => node switch
            {
                Sinf(var a) when a == found => HomogeneousTangent * HomogeneousCosine,
                Cosf(var a) when a == found => HomogeneousCosine,
                Secantf(var a) when a == found => 1 / HomogeneousCosine,
                Cosecantf(var a) when a == found => 1 / (HomogeneousTangent * HomogeneousCosine),
                Tanf(var a) when a == found => HomogeneousTangent,
                Cotanf(var a) when a == found => 1 / HomogeneousTangent,
                _ => node
            });
            return true;
        }

        /// <summary>
        /// A product of powers of the trigonometric functions of one argument, some of them not
        /// whole, which is <c>sin(z)^M cos(z)^N</c> times a constant on every interval where both
        /// are continuous: with <c>M + N</c> even integrated as
        /// <c>tan(z)^M (1 + tan(z)^2)^(-(M + N)/2)</c>, and with <c>M</c> or <c>N</c> an odd whole
        /// number as the plain product, Chebyshev's other two cases.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sqrt(c sin(x))/sqrt(d cos(x))</c> is <c>sqrt(c/d) sqrt(tan(x))</c> wherever both
        /// roots are real, and was declined, with the rest of such products the corpus has, a
        /// constant inside a root among them: <c>(d csc(x))^(3/2) sqrt(c sec(x))</c>,
        /// <c>(a sin(x))^(5/2) sqrt(b sec(x))</c>, <c>(d sec(x))^(5/2) sqrt(b tan(x))</c>. Each is
        /// a power of the sine times a power of the cosine, and with the exponents adding up to an
        /// even number it is a function of the tangent: <c>sin^M cos^N</c> is <c>tan^M cos^(M + N)</c>,
        /// and <c>cos^(M + N)</c> is <c>(1 + tan^2)^(-(M + N)/2)</c> exactly. Rubi's 4.1.0 to
        /// 4.6.0.
        /// </para>
        /// <para>
        /// The constant is not written: the answer is the integrand times the antiderivative of the
        /// tangent's form over that form, a quotient whose logarithmic derivative is zero -- both
        /// halves have <c>(M cot(z) - N tan(z)) z'</c> -- so it is constant wherever it is
        /// continuous, and the answer holds on every interval where the integrand is, the constants
        /// inside the roots whatever their signs.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAProductOfPowersOfTrigonometricFunctionsThroughTheTangent(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Powf(var radicand, Number.Rational fraction) && fraction is not Number.Integer && radicand.ContainsNode(x)))
                return null;
            Entity? argument = null;
            Number.Rational sine = Number.Integer.Zero;
            Number.Rational cosine = Number.Integer.Zero;
            var notWhole = false;
            Entity constant = Number.Integer.One;
            Entity varying = Number.Integer.One;
            foreach (var (factor, underneath) in ThroughWholePowersOfProducts(FactorsOfTheIntegrand(expr)))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                varying = underneath ? varying / factor : varying * factor;
                var (@base, power) = factor is Powf(var b, var p) && p.Evaled is Number.Rational r
                    ? (b, r)
                    : (factor, (Number.Rational)Number.Integer.One);
                // A constant multiple of a function, and a whole power of one inside the power:
                // `(b tan(z)^3)^(3/2)`.
                if (@base is Mulf(var left, var right))
                    @base = !left.ContainsNode(x) ? right : !right.ContainsNode(x) ? left : @base;
                if (@base is Powf(var inner, Number.Integer innerPower))
                    (@base, power) = (inner, (Number.Rational)(power * innerPower));
                if (underneath)
                    power = (Number.Rational)(-power);
                if (power is not Number.Integer)
                    notWhole = true;
                // The powers of the sine and of the cosine each function is.
                (Entity Of, int OnSine, int OnCosine)? read = @base switch
                {
                    Sinf(var of) => (of, 1, 0),
                    Cosf(var of) => (of, 0, 1),
                    Tanf(var of) => (of, 1, -1),
                    Cotanf(var of) => (of, -1, 1),
                    Secantf(var of) => (of, 0, -1),
                    Cosecantf(var of) => (of, -1, 0),
                    _ => null
                };
                if (read is null || argument is not null && argument != read.Value.Of)
                    return null;
                var (functionOf, onSine, onCosine) = read.Value;
                argument = functionOf;
                sine = (Number.Rational)(sine + power * onSine);
                cosine = (Number.Rational)(cosine + power * onCosine);
            }
            if (argument is null || !notWhole
                || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                return null;
            Entity form;
            if ((sine + cosine) is Number.Integer { EInteger: var total } && total.IsEven && total.CanFitInInt32())
            {
                // The exponents add up to an even number: a function of the tangent.
                var tangent = MathS.Tan(argument);
                var half = -total.ToInt32Checked() / 2;
                form = half == 0
                    ? MathS.Pow(tangent, sine)
                    : MathS.Pow(tangent, sine) * MathS.Pow(1 + MathS.Sqr(tangent), half);
            }
            else if (sine is Number.Integer { EInteger: var m } && !m.IsEven || cosine is Number.Integer { EInteger: var n } && !n.IsEven)
                // An odd whole power of one of them: the plain product, which the substitution by
                // the other answers, `(d sec(x))^(5/2) sqrt(b tan(x))` being `sin^(1/2) cos^(-3)`
                // times a constant.
                form = (sine is Number.Integer { IsZero: true } ? Number.Integer.One : MathS.Pow(MathS.Sin(argument), sine))
                       * (cosine is Number.Integer { IsZero: true } ? Number.Integer.One : MathS.Pow(MathS.Cos(argument), cosine));
            else
                return null;
            form = form.InnerSimplified;
            // Already the form, and then the substitution's to answer as it stands.
            if (varying == form || varying.InnerSimplified == form)
                return null;
            if (Integration.ComputeAsTheSameQuestion(form, x, integrateByParts) is not { } answer
                || answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            return constant * varying * answer / form;
        }


        /// <summary>
        /// <paramref name="factors"/> with a whole power of a product read as the product of the
        /// powers, a negative one on the other side of the bar: <c>1/(cos(x)^(7/2) sqrt(sin(x)))</c>
        /// comes back from the polynomial term's <c>c/g</c> as <c>(cos(x)^(7/2) sqrt(sin(x)))^(-1)</c>,
        /// one factor that is no function's power, and the half-angle substitution searched it for
        /// twenty seconds before the tangent's form was reached.
        /// </summary>
        private static IEnumerable<(Entity Factor, bool Underneath)> ThroughWholePowersOfProducts(IEnumerable<(Entity Factor, bool Underneath)> factors)
        {
            foreach (var (factor, underneath) in factors)
            {
                if (factor is not Powf(Mulf product, Number.Integer { EInteger: var power }) || power.IsZero)
                {
                    yield return (factor, underneath);
                    continue;
                }
                var magnitude = Number.Integer.Create(power.Abs());
                foreach (var child in Mulf.LinearChildren(product))
                    yield return (magnitude == Number.Integer.One ? child : MathS.Pow(child, magnitude), power.Sign < 0 ? !underneath : underneath);
            }
        }

        /// <summary>
        /// A power of the cotangent that is not whole below the bar of an integrand with the
        /// tangent of the same argument in it, written as a power of the tangent above it:
        /// <c>1/cot(z)^p = K tan(z)^p</c> with <c>K = 1/(cot(z)^p tan(z)^p)</c>, which is 1
        /// wherever the tangent is positive and a constant on every interval where it keeps its
        /// sign, so it stands in front of the answer, the way Rubi writes it.
        /// </summary>
        /// <remarks>
        /// <c>1/(cot(x)^(7/2) (a + b tan(x))^(3/2))</c> was declined while
        /// <c>tan(x)^(7/2)/(a + b tan(x))^(3/2)</c> was answered: the tangent substitution
        /// writes the cotangent as <c>1/tan</c>, and a power of <c>1/u</c> that is not whole below
        /// the bar is read by no rule. Only below the bar: above it the substitution's
        /// <c>(1/u)^p</c> is read, and <c>cot(x)^(3/2)/(a + b tan(x))</c>, answered in four
        /// seconds so, ran past a minute as <c>tan(x)^(-3/2)</c>, while
        /// <c>cot(x)^(7/2) sqrt(a + b tan(x))</c>, declined in a second, took a hundred to be.
        /// And only beside the tangent; a power of the cotangent alone keeps the answer it had.
        /// Rubi's 4.3.2.1 and 4.3.3.1.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAPowerOfTheCotangentInTheTangent(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Cotanf))
                return null;
            Entity? power = null;
            Entity? argument = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
                if (underneath && factor is Powf(Cotanf(var cotangentArgument), var exponent) && cotangentArgument.ContainsNode(x)
                    && exponent.Evaled is Number.Rational fraction && fraction is not Number.Integer)
                {
                    if (power is not null)
                        return null;
                    (power, argument) = (factor, cotangentArgument);
                }
            if (power is not Powf(var cotangent, var p) || argument is null)
                return null;
            // The cotangent nowhere else, and the tangent somewhere: the power is then all of
            // the cotangent there is, and the integrand is the tangent substitution's.
            var tangent = MathS.Tan(argument);
            if (expr.Nodes.Count(node => node == cotangent) != 1 || !expr.ContainsNode(tangent))
                return null;
            var rewritten = expr.Replace(node => node == power ? MathS.Pow(tangent, (-p).InnerSimplified) : node);
            var constant = power * MathS.Pow(tangent, p);
            return Integration.ComputeAsTheSameQuestion(rewritten, x, integrateByParts)?.Pipe(answer => answer / constant);
        }

        /// <summary>
        /// An integrand that is a function of <c>tan(x)</c> and of nothing else, integrated by
        /// the substitution <c>u = tan(x)</c>, under which <c>dx</c> is <c>du/(1 + u^2)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The substitution that turns every rational function of the tangent into a rational
        /// function, and <c>int sqrt(tan(x))</c> — the last of the five integrals
        /// <a href="https://github.com/asc-community/AngouriMath/issues/233">#233</a> lists — into
        /// <c>int sqrt(u)/(1 + u^2) du</c>.
        /// </para>
        /// <para>
        /// <b>Why this is not a candidate in <see cref="SolveBySubstitution"/>.</b> That one
        /// divides the integrand by <c>du/dx</c> and asks whether any <c>x</c> is left, which
        /// works when the substitution survives the division. Here it does not:
        /// <c>sqrt(tan(x))</c> over the derivative of <c>sqrt(tan(x))</c> is
        /// <c>2 tan(x) cos(x)^2</c>, which is <c>sin(2x)</c> and is simplified to it — a correct
        /// answer to a question that has stopped being about the tangent. Rewriting the integrand
        /// asks a different question and does not lose the shape.
        /// </para>
        /// <para>
        /// The test is the rewrite itself: replace every <c>tan(x)</c> and see whether an
        /// <c>x</c> survives. <c>tan(x) + x</c> keeps one and is declined, which is right — it is
        /// not a function of the tangent alone. <b>The cotangent is covered</b>, by writing it as
        /// <c>1/tan</c> on the way in: it is the same function the other way up, and declining it
        /// for having its own node meant <c>tan(x)^2</c> was answered and <c>cot(x)^2</c> was not.
        /// </para>
        /// <para>
        /// <b>No condition is owed by the substitution</b>, but the answer inherits the
        /// tangent's: <c>u = tan(x)</c> is undefined exactly where the integrand is, since the
        /// integrand is a function of it, and <c>1 + u^2</c> is never zero for real <c>u</c>.
        /// </para>
        /// </remarks>
        internal static Entity? SolveByTangentSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // The cotangent first, because it is the tangent written the other way up and this
            // rule used to decline it for no better reason than the node being a different one.
            // `tan(x)^2` was answered and `cot(x)^2` was not, though the second is `1/tan(x)^2`.
            //
            // cot(u) = 1/tan(u) wherever either is defined: both are cos(u)/sin(u), and the
            // points where the quotient is written differently -- tan undefined at odd multiples
            // of pi/2, where cot is zero -- are removable in the same way for both, so this
            // neither widens nor narrows the domain of an integrand built from them.
            expr = expr.Replace(node =>
                node is Cotanf(var cotangentArgument)
                    ? 1 / MathS.Tan(cotangentArgument)
                    : node);

            // An odd root of a product of powers of the sine and the cosine is the product of
            // the roots, exactly on the reals: the odd root is the real one, an odd function,
            // so `(ab)^(1/3)` is `a^(1/3) b^(1/3)` whatever the signs, and `(s^k)^(p/q)` is
            // `s^(kp/q)` under the same convention. Timofeev's
            // `((sin/cos^7)^(1/3) - 3 tan)/(cos^5 sin)^(2/3)` is
            // `(sin^(1/3) cos^(-7/3) - 3 tan)/(cos^(10/3) sin^(2/3))` so, a polynomial in the
            // cube root of the tangent under the substitution, and was a search past its
            // budget as written. Only here, where the factors are read next: split in the
            // open chain the same roots sent `(sin cos^2)^(1/3)` into a thirty-second search.
            expr = expr.Replace(node =>
                node is Powf(var product, Number.Rational fraction) && fraction is not Number.Integer
                && !fraction.ERational.Denominator.IsEven && product is Mulf or Divf
                && WithTheOddRootOnEachFactor(product, fraction, x) is { } apart
                    ? apart
                    : node);

            var tangent = MathS.Tan(x);
            // Or a sine or a cosine under a root, for the writing by the sign below, or an even
            // power of the secant or the cosecant under one, which the next step writes in the
            // tangent: `sqrt(a + b csc(x)^2)` is `sqrt(a + b + b/tan(x)^2)`. A rational function
            // of those is the half-angle substitution's.
            if (!expr.ContainsNode(tangent) && !(HasARadicalOf(expr, x) && expr.Nodes.Any(node =>
                    node is Sinf or Cosf && node.ContainsNode(x)
                    || node is Powf(Secantf or Cosecantf, Number.Integer { EInteger.IsEven: true }) && node.ContainsNode(x))))
                return null;

            // An even power of the secant, cosine, sine or cosecant of x is a rational function
            // of the tangent, exactly and wherever it is defined: `sec^2 = 1 + tan^2`,
            // `cos^2 = 1/(1 + tan^2)`, `sin^2 = tan^2/(1 + tan^2)`. Timofeev's
            // `(sec^2 - 3 tan sqrt(4 sec^2 + 5 tan^2))/(sin^2 (4 sec^2 + 5 tan^2)^(3/2))` is
            // `((1 + u^2) - 3u sqrt(4 + 9u^2))/(u^2 (4 + 9u^2)^(3/2))` under the tangent, and was
            // declined for the secant and the sine that survived the rewriting. An odd power is
            // not a function of the tangent -- its sign is not -- and is left, to survive and
            // decline as before.
            var secantSquared = 1 + MathS.Sqr(tangent);
            expr = expr.Replace(node => node switch
            {
                Powf(Secantf(var a), Number.Integer even) when a == x && even.EInteger.IsEven && even.EInteger.Sign > 0
                    => MathS.Pow(secantSquared, even.EInteger.ToInt32Checked() / 2),
                Powf(Cosf(var a), Number.Integer even) when a == x && even.EInteger.IsEven && even.EInteger.Sign > 0
                    => MathS.Pow(secantSquared, -(even.EInteger.ToInt32Checked() / 2)),
                Powf(Sinf(var a), Number.Integer even) when a == x && even.EInteger.IsEven && even.EInteger.Sign > 0
                    => MathS.Pow(MathS.Sqr(tangent) / secantSquared, even.EInteger.ToInt32Checked() / 2),
                Powf(Cosecantf(var a), Number.Integer even) when a == x && even.EInteger.IsEven && even.EInteger.Sign > 0
                    => MathS.Pow(secantSquared / MathS.Sqr(tangent), even.EInteger.ToInt32Checked() / 2),
                _ => node,
            });

            // The double angle is the tangent's too, exactly: `sin(2x) = 2 tan/(1 + tan^2)`,
            // `cos(2x) = (1 - tan^2)/(1 + tan^2)`, `tan(2x) = 2 tan/(1 - tan^2)` and the
            // cotangent its reciprocal -- Timofeev's `sqrt(tan(x) tan(2x))` and `sqrt(cot(2x)/cot(x))`.
            static bool IsTwice(Entity argument, Entity.Variable x)
                => TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var intercept)
                   && slope.Evaled == Number.Integer.Create(2) && intercept.Evaled == Number.Integer.Zero;
            expr = expr.Replace(node => node switch
            {
                Sinf(var a) when IsTwice(a, x) => 2 * tangent / secantSquared,
                Cosf(var a) when IsTwice(a, x) => (1 - MathS.Sqr(tangent)) / secantSquared,
                Tanf(var a) when IsTwice(a, x) => 2 * tangent / (1 - MathS.Sqr(tangent)),
                Cotanf(var a) when IsTwice(a, x) => (1 - MathS.Sqr(tangent)) / (2 * tangent),
                Cotanf(var a) when a == x => 1 / tangent,
                _ => node,
            });

            var uSub = Variable.CreateUnique(expr, "u_tan");
            var inU = expr.Substitute(tangent, uSub);
            if (inU.ContainsNode(x))
            {
                // An odd power of the sine or the cosine is its sign times a function of the
                // tangent: `cos(x) = sgn(cos(x))/sqrt(1 + tan^2)` and `sin(x) = tan(x) cos(x)`,
                // the sign a constant between the zeros of the cosine. Timofeev's
                // `sin(x)^7/sin(2x)^(7/2)` is `sgn(cos(x)) u^(7/2)/(2^(7/2) (1 + u^2))` so, a
                // binomial under `t = sqrt(u)`; the sign goes back in as `sgn(cos(x))`. Only
                // where that leaves the tangent alone and something algebraic in it.
                var sign = Variable.CreateUnique(expr, "sgn_cos");
                var rootOfSecantSquared = MathS.Sqrt(secantSquared);
                var odd = expr.Replace(node => node switch
                {
                    Cosf(var a) when a == x => sign / rootOfSecantSquared,
                    Sinf(var a) when a == x => sign * tangent / rootOfSecantSquared,
                    Powf(Cosf(var a), Number.Integer k) when a == x && k.EInteger.CanFitInInt32() && !k.EInteger.IsEven
                        => MathS.Pow(sign / rootOfSecantSquared, k),
                    Powf(Sinf(var a), Number.Integer k) when a == x && k.EInteger.CanFitInInt32() && !k.EInteger.IsEven
                        => MathS.Pow(sign * tangent / rootOfSecantSquared, k),
                    _ => node,
                }).Substitute(tangent, uSub);
                if (odd.ContainsNode(x) || !IsAlgebraicIn(odd, uSub))
                    return null;
                // The sign is 1 or -1, and the integrand is even or odd in it: with the sign
                // one, the function of u to integrate, and the sign in front where the two
                // differ. Decided at a point, since the two are the same expression up to it.
                var withOne = Functions.PartialFractions.Bare(odd.Substitute(sign, Number.Integer.One));
                var withMinusOne = Functions.PartialFractions.Bare(odd.Substitute(sign, Number.Integer.MinusOne));
                // With every symbol pinned to a rational too: Moses's `sqrt(A^2 + B^2 sin(x)^2)/sin(x)`
                // was an exception out of the evaluation, with A and B still in it.
                var at = Number.Rational.Create(37, 100);
                var atOne = withOne.Substitute(uSub, at);
                var atMinusOne = withMinusOne.Substitute(uSub, at);
                var pinned = 0;
                foreach (var symbol in atOne.Vars.Concat(atMinusOne.Vars).Distinct().ToList())
                {
                    var value = Number.Rational.Create(7 + 4 * pinned++, 3);
                    atOne = atOne.Substitute(symbol, value);
                    atMinusOne = atMinusOne.Substitute(symbol, value);
                }
                if (atOne.Evaled is not Number.Complex valueWithOne || atMinusOne.Evaled is not Number.Complex valueWithMinusOne)
                    return null;
                bool oddInTheSign;
                if ((valueWithOne - valueWithMinusOne).Abs() < 1e-9 * (1 + valueWithOne.Abs()))
                    oddInTheSign = false;
                else if ((valueWithOne + valueWithMinusOne).Abs() < 1e-9 * (1 + valueWithOne.Abs()))
                    oddInTheSign = true;
                else
                    return null;
                // A fractional power of a quotient by `1 + u^2`, or of a positive number times
                // something, comes apart exactly: the denominator is positive and so is the
                // number, and a positive real factor leaves the argument of the rest alone.
                for (var round = 0; round < 4; round++)
                {
                    var apart = withOne.Replace(node =>
                    {
                        if (node is not Powf(var @base, Number.Rational fraction) || fraction is Number.Integer || !@base.ContainsNode(uSub))
                            return node;
                        var (top, bottom) = Functions.SingleQuotient.Of(@base);
                        if (bottom != Number.Integer.One && IsPositiveForReal(bottom, uSub))
                            return MathS.Pow(top, fraction) * MathS.Pow(bottom, Number.Rational.Create(fraction.ERational.Negate()));
                        if (@base is Mulf && Mulf.LinearChildren(@base).FirstOrDefault(factor => !factor.ContainsNode(uSub) && factor.Evaled is Number.Real { IsPositive: true }) is { } positive)
                        {
                            var rest = Mulf.LinearChildren(@base).Where(factor => factor != positive).Aggregate(Number.Integer.One as Entity, (product, factor) => product * factor);
                            return MathS.Pow(positive, fraction) * MathS.Pow(rest, fraction);
                        }
                        return node;
                    });
                    if (apart == withOne)
                        break;
                    withOne = apart;
                }
                var signed = Functions.SingleQuotient.Combine(withOne / secantSquared.Substitute(tangent, uSub)).Simplify();
                if (signed is Providedf(var bareSigned, _))
                    signed = bareSigned;
                if (signed.ContainsNode(x) || signed.Nodes.Any(node => node == MathS.NaN))
                    return null;
                if (Integration.ComputeIndefiniteIntegral(signed, uSub, integrateByParts) is not { } signedResult
                    || signedResult.Nodes.Any(node => node == MathS.NaN))
                    return null;
                var back = signedResult.Substitute(uSub, tangent);
                return oddInTheSign ? MathS.Signum(MathS.Cos(x)) * back : back;
            }

            // Combined into one quotient, not merely inner-simplified. Writing the cotangent as
            // 1/tan puts a quotient inside a quotient -- cot(x)^2 arrives as (1/u)^2/(1 + u^2) --
            // and `InnerSimplified` leaves that nesting standing. Everything downstream wants a
            // single Divf of two polynomials, and it is the difference between an answer and
            // none: `1/(u^2*(1 + u^2))` is integrated and `(1/u)^2/(1 + u^2)`, which is the same
            // expression, is not. The half-angle and exponential substitutions comb their
            // integrands for the same reason.
            var integrand = Functions.SingleQuotient
                .Combine(inU / (1 + MathS.Sqr(uSub))).Simplify();
            if (integrand is Providedf(var withoutCondition, _))
                integrand = withoutCondition;
            return Integration.ComputeIndefiniteIntegral(integrand, uSub, integrateByParts) is { } result
                ? result.Substitute(uSub, tangent)
                : null;
        }
        /// <summary>
        /// <c>(prod f_i^(k_i))^(p/q)</c>, <c>q</c> odd, as <c>prod f_i^(k_i p/q)</c> where every
        /// <c>f_i</c> is a trigonometric function of <paramref name="x"/> itself or free of it,
        /// and the powers of the sine and the cosine that come out sum to an even integer --
        /// then the product is <c>tan^a (1 + tan^2)^k</c> with <c>k</c> whole, a function of the
        /// tangent. Null otherwise: <c>(2 sin/cos^3)^(1/3)</c> is <c>(2 u (1 + u^2))^(1/3)</c> read
        /// whole and is answered so, where <c>2^(1/3) sin^(1/3)/cos</c> is not a function of
        /// the tangent and goes the long way round.
        /// </summary>
        private static Entity? WithTheOddRootOnEachFactor(Entity product, Number.Rational fraction, Entity.Variable x)
        {
            Entity? rebuilt = null;
            var total = ERational.Zero;
            foreach (var factor in Mulf.LinearChildren(product))
            {
                var @base = factor;
                var exponent = EInteger.One;
                while (@base is Powf(var inner, Number.Integer whole))
                {
                    exponent = exponent.Multiply(whole.EInteger);
                    @base = inner;
                }
                var trigonometric = @base switch
                {
                    Sinf(var a) => a,
                    Cosf(var a) => a,
                    Tanf(var a) => a,
                    Secantf(var a) => a,
                    Cosecantf(var a) => a,
                    Cotanf(var a) => a,
                    _ => null,
                };
                if (trigonometric is not null ? trigonometric != x : @base.ContainsNode(x))
                    return null;
                var each = fraction.ERational.Multiply(ERational.FromEInteger(exponent));
                // The sine and the cosine count one, their reciprocals minus one, and the
                // tangent, a sine over a cosine, nothing.
                total = total.Add(each.Multiply(@base switch
                {
                    Sinf or Cosf => ERational.One,
                    Secantf or Cosecantf => ERational.FromInt32(-1),
                    _ => ERational.Zero,
                }));
                var power = MathS.Pow(@base, Number.Rational.Create(each));
                rebuilt = rebuilt is null ? power : rebuilt * power;
            }
            var reduced = total.ToLowestTerms();
            return reduced.Denominator.Equals(EInteger.One) && reduced.Numerator.IsEven ? rebuilt : null;
        }

        /// <summary>
        /// Every whole power of a product written as the product of the powers, <c>(a P)^5</c>
        /// as <c>a^5 P^5</c>, which is exact for a whole power and is the spelling the rational
        /// reader needs: <c>(4u^2 + 12u^4 + 12u^6 + 4u^8)/(a (1 - u^2))^5</c> was declined after
        /// five seconds and is answered in 27 ms as <c>.../(a^4 (1 - u^2)^5)</c>. Four rounds,
        /// since a distributed factor may itself be such a power.
        /// </summary>
        private static Entity WithWholePowersOfProductsDistributed(Entity integrand)
        {
            for (var round = 0; round < 4; round++)
            {
                var distributed = integrand.Replace(node =>
                    node is Powf(Mulf(var l, var r), Number.Integer power) ? MathS.Pow(l, power) * MathS.Pow(r, power) : node);
                if (distributed == integrand)
                    break;
                integrand = distributed;
            }
            return integrand;
        }

        /// <summary>
        /// An integrand holding a fractional power of something <b>linear</b> in the variable,
        /// turned into a rational function by <c>u^q = a*x + b</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Setting <c>u = (a*x + b)^(1/q)</c> gives <c>x = (u^q - b)/a</c> and
        /// <c>dx = (q/a) u^(q-1) du</c>, and every occurrence of the radical becomes a power of
        /// <c>u</c>. A quotient of polynomials in <c>x</c> and that radical is then a quotient of
        /// polynomials in <c>u</c>, which the rational integrator answers.
        /// </para>
        /// <para>
        /// <b>Why the general substitution does not already do this, which is the point.</b>
        /// <see cref="SolveBySubstitution"/> rewrites <em>sub-expressions</em>: it finds
        /// <c>1 + x</c> inside <c>x/sqrt(1 + x)</c>, replaces that, and is left with a bare
        /// <c>x</c> it cannot express, so it declines. This substitutes for <b>x itself</b>, so
        /// there is nothing left behind to fail on. <c>x/sqrt(1 + x)</c> and
        /// <c>x/sqrt(2 - 3x)</c> had no antiderivative for exactly that reason.
        /// </para>
        /// <para>
        /// <b>One q for the whole integrand.</b> Where several radicals share a base —
        /// <c>sqrt(x + 1)</c> beside <c>(x + 1)^(1/3)</c> — the exponent denominators are taken
        /// together by their least common multiple, so one substitution clears both. Radicals over
        /// <em>different</em> linear bases are not handled: <c>sqrt(1 - x) + sqrt(1 + x)</c> needs
        /// two substitutions at once and is declined rather than half-rewritten.
        /// </para>
        /// <para>
        /// <b>No condition is owed by the rewrite itself.</b> <c>a</c> is non-zero, since a zero
        /// coefficient is not a linear expression in <c>x</c> and the reader below rejects it,
        /// and <c>u^q = a*x + b</c> is invertible wherever the radical it came from is defined.
        /// The answer inherits the radical's own domain and adds nothing -- <b>except where the
        /// even-root step below has read <c>u</c> as a non-negative real</b>, which it is only
        /// where the radical is real. Beyond that, <c>u</c> is imaginary and the integrand can
        /// still be real: <c>x sqrt(c - a c x) / e^(3 atanh(a x))</c> above <c>a x = 1</c> is the
        /// product of two imaginary factors, and the answer built for a real <c>u</c> is not its
        /// antiderivative there (Rubi 7.3.6). So the answer says what it used: it is given
        /// <c>provided a x + b &gt;= 0</c> exactly when that step changed the integrand.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByLinearRadicalSubstitution(Entity expr, Entity.Variable x, bool integrateByParts, bool variableIsNonnegative = false)
        {
            // Every fractional power in the tree whose base is linear in x, collected with the
            // base it is over so that radicals over different bases are told apart.
            //
            // **Two bases, when both are square roots.** `sqrt(u)/(u sqrt(1 + u))` -- what
            // `sqrt(1 + tanh(4x))` becomes under `u = e^(8x)` -- was declined here for the second
            // base, and it is one substitution: with `s = sqrt(u)` the other root is
            // `sqrt(1 + s^2)`, a root of a quadratic, which the rules for those answer. So a
            // second base is admitted where every radical is a square root; its radicals are
            // substituted rather than built, and what they become is the next rule's. A third
            // base, or a cube root beside a second base, is declined as before.
            //
            // And only where the two bases are not both negative anywhere on the reals, unless
            // the caller knows its variable to be non-negative. Where both are, the integrand
            // is real -- `sqrt(x - 1) sqrt(x - 2)` below 1 is `-sqrt((1 - x)(2 - x))` -- and the
            // answer, built through an imaginary `u`, is not its antiderivative there: measured
            // by quadrature over [-1.5, 0.3], -3.66 against the answer's -4.68, with the two
            // agreeing to twelve digits above 2. The exponential substitution's `u = e^(k x)`
            // never is negative, and it says so.
            Entity? radicalBase = null;
            Entity? otherBase = null;
            var denominators = new List<int>();
            var allSquareRoots = true;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer)
                    continue;
                if (!@base.ContainsNode(x))
                    continue;
                if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                    allSquareRoots = false;
                // A radical over something that is not linear is **skipped rather than refused**,
                // and that is where the nested ones come from. `sqrt(x + sqrt(1 + x))` holds two:
                // the inner one is over something linear and is what the substitution is for, and
                // the outer one is over a sum holding the inner one. Declining because of the
                // outer one refused the whole family -- and it need not, because the substitution
                // eliminates `x` from it anyway: with `u^2 = 1 + x` the outer base is `u^2 + u - 1`
                // and the integrand becomes `2u sqrt(u^2 + u - 1)`, which the quadratic radical
                // rule answers. The check that no `x` survives, below, is what makes skipping safe
                // rather than a guess. https://github.com/asc-community/AngouriMath/issues/718
                // A quotient of two linears is a base of its own kind: `sqrt((1 + x)/(3 + 2x))`
                // under `u = sqrt((1 + x)/(3 + 2x))` has `x = (3u^2 - 1)/(1 - 2u^2)`, rational,
                // and the answer holds wherever the root is real -- below `-3/2` too, where
                // both linears are negative and the root of each is not. Split into a root
                // over a root it is declined for that, and rightly.
                if (!TreeAnalyzer.TryGetPolyLinear(@base, x, out var slope, out _) || slope.Evaled == 0)
                {
                    if (radicalBase is null && IsAQuotientOfLinears(@base, x))
                    {
                        radicalBase = @base;
                        if (!exponent.ERational.Denominator.CanFitInInt32())
                            return null;
                        denominators.Add(exponent.ERational.Denominator.ToInt32Checked());
                    }
                    continue;
                }
                if (radicalBase is null)
                    radicalBase = @base;
                else if (radicalBase != @base)
                {
                    if (otherBase is null)
                        otherBase = @base;
                    else if (otherBase != @base)
                        return null;   // three different bases at once
                    continue;
                }
                if (!exponent.ERational.Denominator.CanFitInInt32())
                    return null;
                denominators.Add(exponent.ERational.Denominator.ToInt32Checked());
            }
            if (radicalBase is null || denominators.Count == 0)
                return null;
            if (otherBase is not null && !allSquareRoots)
                return null;
            if (otherBase is not null && !variableIsNonnegative
                && !AtMostOneIsNegativeOnTheReals(new List<Entity> { radicalBase, otherBase }, x))
                return null;

            var q = denominators.Aggregate(1, Lcm);
            if (q < 2 || q > 12)   // beyond this the rewritten polynomial is not worth building
                return null;

            var u = Variable.CreateUnique(expr, "u_rad");
            Entity xInU;
            Entity dx;
            if (TreeAnalyzer.TryGetPolyLinear(radicalBase, x, out var a, out var b))
            {
                // x = (u^q - b) / a, and dx = (q/a) u^(q-1) du.
                xInU = (MathS.Pow(u, q) - b) / a;
                dx = Number.Integer.Create(q) / a * MathS.Pow(u, q - 1);
            }
            else
            {
                if (otherBase is not null)
                    return null;
                // u^q = (a x + b)/(c x + d), so x = (d u^q - b)/(a - c u^q).
                var (above, below) = Functions.SingleQuotient.Of(radicalBase);
                if (!TreeAnalyzer.TryGetPolyLinear(above, x, out a, out b) || !TreeAnalyzer.TryGetPolyLinear(below, x, out var c, out var d))
                    return null;
                xInU = ((d * MathS.Pow(u, q) - b) / (a - c * MathS.Pow(u, q))).InnerSimplified;
                dx = xInU.Differentiate(u).InnerSimplified;
            }

            // Each radical becomes its power of u **by construction** rather than by substituting
            // and then simplifying. Substituting alone turns (x + 1)^(1/2) into ((u^6))^(1/2), and
            // the simplifier is right to refuse to call that u^3 — it is |u^3| on the reals and
            // worse off them. Building u^3 directly is sound here because u is the principal
            // q-th root of a*x + b by definition of the substitution, and it is the difference
            // between answering 1/(sqrt(x+1) + (x+1)^(1/3)) and handing it back.
            var rewritten = expr.Replace(node =>
                node is Powf(var radical, Number.Rational e) && e is not Number.Integer
                && radical == radicalBase
                && e.ERational.Denominator.CanFitInInt32()
                && e.ERational.Numerator.CanFitInInt32()
                    ? MathS.Pow(u, q / e.ERational.Denominator.ToInt32Checked()
                                   * e.ERational.Numerator.ToInt32Checked())
                    : node);

            rewritten = rewritten.Substitute(x, xInU);
            if (rewritten.ContainsNode(x))
                return null;

            var integrand = Functions.SingleQuotient.Combine((rewritten * dx).Simplify());
            if (integrand is Providedf(var inner, _))
                integrand = inner;
            // The quotient of linears leaves `(a (1 - u^2))^5` below the bar, which the rational
            // reader does not read and whose distributed spelling it answers at once: Rubi's
            // `x^3 sqrt((a x + 1)/(a x - 1))` took nine seconds through the split terms, and
            // takes half of one as a single quotient over `a^5 (1 - u^2)^5`. Only where the
            // integrand in u is rational: with a root of u still in it -- a second base, as in
            // Timofeev's 314 -- the distributed spelling sent the radical rules down a path
            // that answered with a sign function, where the undistributed one is answered exactly.
            if (!integrand.Nodes.Any(node => node is Powf(var radicand, Number.Rational fractional) && fractional is not Number.Integer && radicand.ContainsNode(u)))
                integrand = WithWholePowersOfProductsDistributed(integrand);
            // For an even q the principal root is not negative wherever it is real, and a root
            // holding a power of u gives that power up: `1/sqrt(t + t^(3/2))` under `u = sqrt(t)`
            // is `2u/sqrt(u^2 + u^3)`, a root of a cubic, and is `2/sqrt(1 + u)`. Where the
            // radical is not real, u is not a non-negative real and the identities do not hold,
            // so an answer that used them is conditioned on the radicand -- unless the caller
            // knows its variable to be non-negative, as an exponential is.
            // https://github.com/asc-community/AngouriMath/issues/718
            Entity? condition = null;
            if (q % 2 == 0)
            {
                var factored = FactorANonnegativeVariableOutOfRadicals(integrand, u);
                if (factored != integrand && !variableIsNonnegative)
                    condition = radicalBase >= Number.Integer.Zero;
                integrand = factored;
            }

            if (Integration.ComputeIndefiniteIntegral(integrand, u, integrateByParts) is not { } result)
                return null;
            var back = result.Substitute(u, MathS.Pow(radicalBase, Number.Rational.Create(1, q)));
            return condition is null ? back : back.Provided(condition);
        }

        /// <summary>
        /// Fractional powers of two different linears in the variable, <c>(a x + b)^(p/q)</c>
        /// beside <c>(c x + d)^(r/q)</c>, rationalised by <c>t = ((a x + b)/(c x + d))^(1/q)</c>
        /// where every term of the integrand carries a whole power of the second linear once
        /// the first is written through <c>t</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// With <c>t^q = (a x + b)/(c x + d)</c>, <c>x = (d t^q - b)/(a - c t^q)</c> and
        /// <c>c x + d = (a d - b c)/(a - c t^q)</c>, both rational in <c>t</c>; and
        /// <c>(a x + b)^(p/q) = t^p (c x + d)^(p/q)</c>. So each term of the integrand is a
        /// power of <c>t</c> times a power of the second linear, and where that power's
        /// numerator is the same modulo <c>q</c> across the terms above the line and across
        /// those below, the powers left are whole and the integrand is rational in <c>t</c>.
        /// <c>1/((x - 1)^4 (x + 1)^2)^(1/3)</c> is <c>(x - 1)^(-4/3) (x + 1)^(-2/3)</c>: with
        /// <c>t^3 = (x - 1)/(x + 1)</c> it is <c>t^(-4) (x + 1)^(-2)</c>, and
        /// <c>x (1 + x)^(2/3) sqrt(1 - x)</c> over a sum of two such products is the same with
        /// <c>q = 6</c>, every product there carrying <c>(1 - x)^(7/6)</c>.
        /// </para>
        /// <para>
        /// <b>Where it holds: everywhere.</b> <c>t</c> is written back as the quotient of the
        /// two principal roots, <c>(a x + b)^(1/q) / (c x + d)^(1/q)</c>, and not as the root of
        /// the quotient: a whole power of a quotient is the quotient of the powers, so
        /// <c>t^p</c> is <c>(a x + b)^(p/q) / (c x + d)^(p/q)</c> for every complex <c>x</c>,
        /// where the root of the quotient agrees with that only where the two linears have the
        /// same sign. Written the first way the answer to Timofeev's 315 held on <c>(-1, 1)</c>
        /// and failed above 1, where <c>sqrt(1 - x)</c> is imaginary.
        /// </para>
        /// <para>
        /// After <see cref="SolveByLinearRadicalSubstitution"/>, which answers one linear base
        /// and declines two of different roots; this is those.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByAQuotientOfTwoLinearRadicals(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            Entity? first = null;
            Entity? second = null;
            var denominators = new List<int>();
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer)
                    continue;
                if (!@base.ContainsNode(x))
                    continue;
                if (!TreeAnalyzer.TryGetPolyLinear(@base, x, out var slope, out _) || slope.Evaled == 0)
                    return null;
                if (!exponent.ERational.Denominator.CanFitInInt32() || !exponent.ERational.Numerator.CanFitInInt32())
                    return null;
                denominators.Add(exponent.ERational.Denominator.ToInt32Checked());
                if (first is null)
                    first = @base;
                else if (first != @base)
                {
                    if (second is null)
                        second = @base;
                    else if (second != @base)
                        return null;
                }
            }
            if (first is null || second is null)
                return null;
            var q = denominators.Aggregate(1, Lcm);
            if (q < 2 || q > 12)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(first, x, out var a, out var b) || !TreeAnalyzer.TryGetPolyLinear(second, x, out var c, out var d))
                return null;
            // Two proportional linears are one radical with a constant in it: their determinant
            // a d - b c is zero, and the second linear in t would be 0/(a - c t^q), everything it
            // multiplies vanishing -- Rubi's `sin(a + b (c + d x)^(1/3))/(c e + d e x)^(1/3)`
            // came back as `0 provided ...`. With `c x + d = k (a x + b)`, a power of the second
            // is `k^r` times the same power of the first, the generic reading of a root of a
            // product; a known-negative k under an even root is not taken, since there the two
            // differ by a sign wherever the first linear is negative. The integrand is then the
            // one-linear question, asked again.
            // https://github.com/asc-community/AngouriMath/issues/1386
            var determinant = (a * d - b * c).InnerSimplified;
            if (determinant.Evaled is Number.Complex { IsZero: true }
                || determinant.Vars.Any() && Functions.PartialFractions.Bare(determinant.Simplify()).Evaled is Number.Complex { IsZero: true })
                return AsOneLinearRadical(expr, x, first, second, Functions.PartialFractions.Bare((c / a).Simplify()), integrateByParts);

            var t = Variable.CreateUnique(expr, "t_rad");
            var w = Variable.CreateUnique(expr, "w_rad");
            var tq = MathS.Pow(t, q);
            var xInT = ((d * tq - b) / (a - c * tq)).InnerSimplified;
            var secondInT = ((a * d - b * c) / (a - c * tq)).InnerSimplified;
            var dx = xInT.Differentiate(t).InnerSimplified;

            // Each radical becomes its powers by construction, as in the linear rule: the
            // first linear's (p/q')-th power is t^k w^k and the second's is w^k, k = p q/q',
            // with w standing for the second linear's q-th root.
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var radical, Number.Rational e) || e is Number.Integer || (radical != first && radical != second))
                    return node;
                var k = q / e.ERational.Denominator.ToInt32Checked() * e.ERational.Numerator.ToInt32Checked();
                return radical == first ? MathS.Pow(t, k) * MathS.Pow(w, k) : MathS.Pow(w, k);
            });
            rewritten = rewritten.Substitute(x, xInT);
            if (rewritten.ContainsNode(x))
                return null;
            // The powers of w read off the terms as written first, which keeps a power of a
            // quadratic the derivative of x(t) carries as the power it is: for Hearn's
            // `sqrt(a + b x) sqrt(c + d x)` the rational function is `t^2 / (b - d t^2)^3`, and
            // read after simplification it is over a quartic times the quadratic, which the
            // rational rules with symbols in the coefficients do not take apart. Where a term
            // holds w other than as a factor, the terms are read as polynomials in w after
            // simplification, as before.
            var root = Number.Rational.Create(1, q);
            var back = MathS.Pow(first, root) / MathS.Pow(second, root);
            foreach (var simplified in new[] { false, true })
            {
                var product = rewritten * dx;
                if (simplified)
                {
                    product = product.Simplify();
                    if (product is Providedf(var bareProduct, _))
                        product = bareProduct;
                }
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(product));
                var aboveTerms = simplified ? TermsAsPolynomialInW(above, w) : TermsByFactorsOfW(above, w);
                var belowTerms = simplified ? TermsAsPolynomialInW(below, w) : TermsByFactorsOfW(below, w);
                if (aboveTerms is null || belowTerms is null)
                    continue;
                // The powers of w above the line agree modulo q, and so do those below, and the
                // two residues agree: then every power left after t^q's worth is taken is whole.
                if (Residue(aboveTerms.Select(term => term.Power), q) is not { } residueAbove
                    || Residue(belowTerms.Select(term => term.Power), q) is not { } residueBelow || residueAbove != residueBelow)
                    continue;
                Entity rebuilt = WithWholePowersOfTheSecond(aboveTerms, residueAbove, q, secondInT)
                    / WithWholePowersOfTheSecond(belowTerms, residueBelow, q, secondInT);
                // A rational function of t; the condition the rebuilding attaches -- a power of
                // a quotient is defined where the quotient is -- is the substitution's, not the
                // integrand's, whose own domain the answer inherits.
                var integrand = Functions.SingleQuotient.Combine(simplified ? rebuilt.Simplify() : rebuilt.InnerSimplified);
                if (integrand is Providedf(var rational, _))
                    integrand = rational;
                if (integrand.ContainsNode(w))
                    continue;
                // t as the quotient of the two principal roots, not the root of the quotient:
                // then t^p is (a x + b)^(p/q) over (c x + d)^(p/q) for every complex x, and the
                // identity the rewriting rests on holds off the real line too.
                if (Integration.ComputeIndefiniteIntegral(integrand, t, integrateByParts) is { } result)
                    return result.Substitute(t, back);
            }
            return null;

            // Each additive term as its power of w and the rest, w taken as a factor of the
            // term and nowhere else; null where a term holds w inside a sum or a power.
            static List<(EInteger Power, Entity Coefficient)>? TermsByFactorsOfW(Entity expr, Variable w)
            {
                var terms = new List<(EInteger, Entity)>();
                foreach (var term in Sumf.LinearChildren(expr))
                {
                    var power = EInteger.Zero;
                    Entity? coefficient = null;
                    foreach (var factor in Mulf.LinearChildren(term))
                    {
                        if (factor == w)
                            power = power.Add(1);
                        else if (factor is Powf(var b, Number.Integer e) && b == w)
                            power = power.Add(e.EInteger);
                        else if (factor.ContainsNode(w))
                            return null;
                        else
                            coefficient = coefficient is null ? factor : coefficient * factor;
                    }
                    terms.Add((power, coefficient ?? Number.Integer.One));
                }
                return terms;
            }

            static List<(EInteger Power, Entity Coefficient)>? TermsAsPolynomialInW(Entity expr, Variable w)
                => TreeAnalyzer.TryGetPolynomial(expr, w, out var monomials)
                    ? monomials.Select(pair => (pair.Key, pair.Value)).ToList()
                    : null;

            static int? Residue(IEnumerable<EInteger> exponents, int q)
            {
                int? residue = null;
                foreach (var exponent in exponents)
                {
                    if (!exponent.CanFitInInt32())
                        return null;
                    var r = ((exponent.ToInt32Checked() % q) + q) % q;
                    if (residue is null)
                        residue = r;
                    else if (residue != r)
                        return null;
                }
                return residue ?? 0;
            }

            // w^e with e = residue + m q is (second)^m, the residue's worth cancelling between
            // the two lines.
            static Entity WithWholePowersOfTheSecond(List<(EInteger Power, Entity Coefficient)> terms, int residue, int q, Entity secondInT)
            {
                Entity? sum = null;
                foreach (var (power, coefficient) in terms)
                {
                    var m = (power.ToInt32Checked() - residue) / q;
                    Entity term = m == 0 ? coefficient : coefficient * MathS.Pow(secondInT, m);
                    sum = sum is null ? term : sum + term;
                }
                return sum ?? Number.Integer.Zero;
            }
        }

        /// <summary>
        /// <paramref name="expr"/> with every fractional power of <paramref name="second"/>, which is
        /// <paramref name="ratio"/> times <paramref name="first"/>, written as the ratio's power
        /// times the same power of <paramref name="first"/>, and asked again; null where the ratio
        /// is known negative under an even root, or the rewrite leaves the question as it was.
        /// </summary>
        private static Entity? AsOneLinearRadical(Entity expr, Entity.Variable x, Entity first, Entity second, Entity ratio, bool integrateByParts)
        {
            if (ratio.ContainsNode(x))
                return null;
            var negative = ratio.Evaled is Number.Real { IsNegative: true };
            var refused = false;
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer || @base != second)
                    return node;
                if (negative && exponent.ERational.Denominator.IsEven)
                    refused = true;
                return MathS.Pow(ratio, exponent) * MathS.Pow(first, exponent);
            });
            if (refused || rewritten == expr)
                return null;
            // The same question, respelled: a rule scoped to the question asked is owed it, as in
            // SolveByCancellingWithFunctionsAsIndeterminates, and with one linear left under a
            // root this rule does not see it again.
            return Integration.ComputeAsTheSameQuestion(rewritten.InnerSimplified, x, integrateByParts);
        }

        /// <summary>
        /// A polynomial over a power of a linear beside the square roots of two others,
        /// <c>P(x) (a + b x)^(m/2) (c + d x)^(n/2) / (g + h x)^k</c> with <c>m</c> and <c>n</c>
        /// odd and neither below <c>-1</c>, and <c>k &gt;= 0</c>, by undetermined coefficients:
        /// algebraic terms times <c>sqrt(a + b x) sqrt(c + d x)</c>, and a multiple of each of
        /// two integrals that are not algebraic.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Write <c>S = sqrt(a + b x) sqrt(c + d x)</c> and <c>Q = (a + b x)(c + d x)</c>. Over
        /// <c>S</c> the integrand is <c>T(x)/((g + h x)^k S)</c>, where
        /// <c>T = P (a + b x)^((m + 1)/2) (c + d x)^((n + 1)/2)</c> is a polynomial, and
        /// <see cref="IntegrateOverARootOfAQuadratic"/> takes that to algebraic terms and two
        /// integrals, as it does for the root of one quadratic.
        /// </para>
        /// <para>
        /// <b>The two integrals left.</b> With <c>t = sqrt(a + b x)/sqrt(c + d x)</c>,
        /// <c>dx/S = 2 dt/(b - d t^2)</c>, so <c>int 1/S</c> is <c>2 artanh(sqrt(r) t)/(b sqrt(r))</c>
        /// with <c>r = d/b</c>. And <c>dx/(y S) = -2 dt/(p t^2 + q)</c> with <c>y = g + h x</c>,
        /// <c>p = g d - h c</c> and <c>q = h a - g b</c>, so <c>int 1/(y S)</c> is
        /// <c>-2 arctan(sqrt(rho) t)/(q sqrt(rho))</c> with <c>rho = p/q</c>. Each derivative
        /// needs only <c>sqrt(z)^2 = z</c>, so each holds for every value of the symbols that the
        /// divisions allow. Each is real for one sign of <c>r</c> or <c>rho</c> and the other
        /// function for the other sign: the one for the sign of a number, and both, each where
        /// it holds, for a quantity with symbols in it. The slopes are divided by, which is the
        /// generic case, as everywhere in the integrator.
        /// </para>
        /// <para>
        /// The substitution <see cref="SolveByAQuotientOfTwoLinearRadicals"/> answers the same
        /// integrands. With symbols in the linears, though, its rational function in <c>t</c> is
        /// over a power of <c>b - d t^2</c> that grows with the degree of <c>P</c>. Rubi's 1.1.1.6
        /// <c>(A + B x + C x^2) sqrt(c + d x) sqrt(e + f x)</c> took more than 4 GB that way,
        /// where this is a triangular system.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAPolynomialOverAPowerOfALinearBesideTwoRoots(Entity expr, Entity.Variable x)
        {
            // The two bases, read before anything is built, since this asks every sub-integrand.
            Entity? first = null;
            Entity? second = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer || !@base.ContainsNode(x))
                    continue;
                if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !exponent.ERational.Numerator.CanFitInInt32())
                    return null;
                if (first is null)
                    first = @base;
                else if (first != @base)
                {
                    if (second is null)
                        second = @base;
                    else if (second != @base)
                        return null;
                }
            }
            // With numbers in both linears the combining of roots and the quotient substitution
            // answer, and in their own forms; this is for the symbols, which those declined or
            // took gigabytes over. Two proportional linears are one root with a constant in it,
            // which AsOneLinearRadical takes.
            if (first is null || second is null
                || !first.Vars.Concat(second.Vars).Any(symbol => symbol != x)
                || !TreeAnalyzer.TryGetPolyLinear(first, x, out var b, out var a)
                || !TreeAnalyzer.TryGetPolyLinear(second, x, out var d, out var c)
                || IsZeroOverTheSymbols(b) || IsZeroOverTheSymbols(d) || IsZeroOverTheSymbols(b * c - a * d))
                return null;
            if (ReadBesideSquareRoots(expr, x, first, second) is not var (halves, above, constantBelow, third, order))
                return null;

            // (a + b x)^(m/2) is (a + b x)^((m + 1)/2) over its root. Below -1 there is a pole
            // at the root of a linear under a root, which is the substitution's.
            if (halves[first] % 2 == 0 || halves[second] % 2 == 0)
                return null;
            var wholeOfFirst = (halves[first] + 1) / 2;
            var wholeOfSecond = (halves[second] + 1) / 2;
            if (wholeOfFirst < 0 || wholeOfSecond < 0
                || CoefficientsBesideARoot(above * WholePower(first, wholeOfFirst) * WholePower(second, wholeOfSecond), x) is not { } t)
                return null;

            // h^2 Q at the third linear's root is (h a - g b)(h c - g d), zero where it shares a
            // root with one under a root.
            ALinearBesideTheRoot? pole = null;
            if (third is { })
            {
                if (!TreeAnalyzer.TryGetPolyLinear(third, x, out var h, out var g) || IsZeroOverTheSymbols(h))
                    return null;
                pole = new(third, g, h, order, new[] { h * a - g * b, h * c - g * d }, SharesARoot: false);
            }
            if (IntegrateOverARootOfAQuadratic(expr, x, t, a * c, a * d + b * c, b * d, xi => (a + b * xi) * (c + d * xi), pole, b, 0, belowTheRoot: 0)
                is not var (algebraic, ofTheLogarithm, ofTheThirdKind))
                return null;
            var answer = algebraic * MathS.Sqrt(first) * MathS.Sqrt(second);
            var root = MathS.Sqrt(first) / MathS.Sqrt(second);
            if (ofTheLogarithm != Number.Integer.Zero)
            {
                // int 1/S over 1/b, with 2 artanh(z) written as the logarithm the library writes it as.
                var r = LowestOverTheSymbols(d / b);
                answer = answer + BySign(r,
                    ofTheLogarithm * MathS.Ln((1 + MathS.Sqrt(r) * root) / (1 - MathS.Sqrt(r) * root)) / MathS.Sqrt(r),
                    2 * ofTheLogarithm * MathS.Arctan(MathS.Sqrt(-r) * root) / MathS.Sqrt(-r));
            }
            if (ofTheThirdKind != Number.Integer.Zero)
            {
                // int 1/(y S) over 1/(h a - g b), -2 arctan(sqrt(rho) t)/sqrt(rho) with
                // rho = (g d - h c)/(h a - g b).
                var atThePole = pole!.AtThePole;
                var rho = LowestOverTheSymbols(-atThePole[1] / atThePole[0]);
                answer = answer + BySign(rho,
                    -2 * ofTheThirdKind * MathS.Arctan(MathS.Sqrt(rho) * root) / MathS.Sqrt(rho),
                    -ofTheThirdKind * MathS.Ln((1 + MathS.Sqrt(-rho) * root) / (1 - MathS.Sqrt(-rho) * root)) / MathS.Sqrt(-rho));
            }
            return (constantBelow == Number.Integer.One ? answer : answer / constantBelow).InnerSimplified;
        }

        /// <summary>
        /// A polynomial over a power of a linear beside a half-odd power of a quadratic,
        /// <c>P(x) Q^(m/2) / (g + h x)^k</c> with <c>m</c> odd and <c>k &gt;= 1</c>, by undetermined
        /// coefficients: algebraic terms times <c>sqrt(Q)</c>, and a multiple of each of two
        /// integrals that are not algebraic.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Over <c>S = sqrt(Q)</c> the integrand is <c>T(x)/((g + h x)^k S)</c>, where
        /// <c>T = P Q^((m + 1)/2)</c> is a polynomial, or below <c>m = -1</c>,
        /// <c>P/((g + h x)^k Q^n S)</c> with <c>n = -(m + 1)/2</c>; and
        /// <see cref="IntegrateOverARootOfAQuadratic"/> takes either to algebraic terms and two
        /// integrals.
        /// </para>
        /// <para>
        /// <b>The two integrals left.</b> With <c>Q = q0 + q1 x + q2 x^2</c>, <c>int 1/S</c> is
        /// <c>ln(2 sqrt(q2) S + 2 q2 x + q1)/sqrt(q2)</c>, and
        /// <c>-arcsin((2 q2 x + q1)/sqrt(q1^2 - 4 q0 q2))/sqrt(-q2)</c>, real where <c>q2 &lt; 0</c>,
        /// as the root of a quadratic alone is answered. With <c>y = g + h x</c>,
        /// <c>H = q0 h^2 - q1 g h + q2 g^2</c>, which is <c>h^2 Q</c> at the root of <c>y</c>, and
        /// <c>Z = 2 q0 h - q1 g + (q1 h - 2 q2 g) x</c>, <c>int 1/(y S)</c> is
        /// <c>-artanh(Z/(2 sqrt(H) S))/sqrt(H)</c>, written as the logarithm the library writes it
        /// as, and <c>arctan(Z/(2 sqrt(-H) S))/sqrt(-H)</c>, real where <c>H &lt; 0</c>. The
        /// derivative of each of those two needs only <c>sqrt(z)^2 = z</c>. Each pair is given by
        /// the sign of its quantity, as for the roots of two linears. And since
        /// <c>Z^2 - 4 H Q</c> is <c>(q1^2 - 4 q0 q2) y^2</c>, the artanh is of a number less than
        /// 1 in size where <c>Q</c> has no real root, and of one more than 1 where it has two:
        /// there it is written as the logarithm of <c>(z + 1)/(z - 1)</c>, which differs from
        /// that of <c>(1 + z)/(1 - z)</c> by a constant and is the real one.
        /// </para>
        /// <para>
        /// <b>Where it is asked.</b> Only with the linear below the bar. A polynomial beside the
        /// root alone is <see cref="SolveAPolynomialTimesAnOddHalfPowerOfAQuadratic"/>'s, which also
        /// answers a leading coefficient that is zero. A first power of the linear with numbers in
        /// it and in <c>Q</c> is <see cref="SolveALinearBesideTheRootOfAQuadratic"/>'s, whose answer
        /// is real on both sides of the linear's root, and
        /// <see cref="SolveARationalFunctionBesideTheRootOfAQuadratic"/> takes distinct linears
        /// apart into it. A power past the first is this rule's, and so is a first power with a
        /// symbol in it, which those decline: <c>1/((g + h x) sqrt(a + c x^2))</c> was declined.
        /// </para>
        /// <para>
        /// Rubi's 1.2.1.9, <c>(d + e x + f x^2) sqrt(a + c x^2)/(g + h x)^4</c> and its like, was
        /// declined or ran past its budget, where this is a triangular system and a recurrence.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAPolynomialOverAPowerOfALinearBesideARootOfAQuadratic(Entity expr, Entity.Variable x)
        {
            // The quadratic, read before anything is built, since this asks every sub-integrand.
            Entity? quadratic = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer || !@base.ContainsNode(x))
                    continue;
                if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !exponent.ERational.Numerator.CanFitInInt32()
                    || quadratic is { } && quadratic != @base)
                    return null;
                quadratic = @base;
            }
            // A square below the root is the modulus of its root, which the rules for it take; and
            // each closed form is chosen by the sign of a quantity, which a number off the real
            // line does not have. Without the linear, and with a first power of it and numbers
            // only, the rules further down answer: see the remarks.
            if (quadratic is null || HoldsTheImaginaryUnit(expr) || CoefficientsBesideARoot(quadratic, x) is not { Length: 3 } q
                || IsZeroOverTheSymbols(q[2]) || IsZeroOverTheSymbols(q[1] * q[1] - 4 * q[0] * q[2])
                || ReadBesideSquareRoots(expr, x, quadratic) is not var (halves, above, constantBelow, third, order)
                || order == 0 || order == 1 && !quadratic.Vars.Concat(third!.Vars).Any(symbol => symbol != x))
                return null;

            // Q^(m/2) is Q^((m + 1)/2) over its root, and below -1 a power of Q below the bar
            // beside it, Q^n with n = -(m + 1)/2.
            if (halves[quadratic] % 2 == 0)
                return null;
            var belowTheRoot = halves[quadratic] < -1 ? -(halves[quadratic] + 1) / 2 : 0;
            if (CoefficientsBesideARoot(belowTheRoot == 0 ? above * WholePower(quadratic, (halves[quadratic] + 1) / 2) : above, x) is not { } t)
                return null;
            var (q0, q1, q2) = (q[0], q[1], q[2]);
            ALinearBesideTheRoot? pole = null;
            if (third is { })
            {
                if (!TreeAnalyzer.TryGetPolyLinear(third, x, out var h, out var g) || IsZeroOverTheSymbols(h))
                    return null;
                // h^2 Q at the linear's root; where that is zero, h Q' there, which is not, since
                // the root is a simple one.
                var atTheRoot = q0 * h * h - q1 * g * h + q2 * g * g;
                pole = IsZeroOverTheSymbols(atTheRoot)
                    ? new(third, g, h, order, new[] { q1 * h - 2 * q2 * g }, SharesARoot: true)
                    : new(third, g, h, order, new[] { atTheRoot }, SharesARoot: false);
            }
            if (IntegrateOverARootOfAQuadratic(expr, x, t, q0, q1, q2, xi => quadratic.Substitute(x, xi), pole, null, null, belowTheRoot)
                is not var (algebraic, ofTheFirstKind, ofTheThirdKind))
                return null;
            var root = MathS.Sqrt(quadratic);
            var answer = algebraic * root;
            if (ofTheFirstKind != Number.Integer.Zero)
            {
                var derivative = 2 * q2 * x + q1;
                answer = answer + BySign(q2,
                    ofTheFirstKind * MathS.Ln(2 * MathS.Sqrt(q2) * root + derivative) / MathS.Sqrt(q2),
                    -ofTheFirstKind * MathS.Arcsin(LowestOverTheSymbols(derivative / MathS.Sqrt(q1 * q1 - 4 * q0 * q2))) / MathS.Sqrt(-q2));
            }
            if (ofTheThirdKind != Number.Integer.Zero)
            {
                var (_, g, h, _, atThePole, _) = pole!;
                var z = 2 * q0 * h - q1 * g + (q1 * h - 2 * q2 * g) * x;
                var twiceTheRoot = 2 * MathS.Sqrt(atThePole[0]) * root;
                // z^2 - 4 H Q is (q1^2 - 4 q0 q2) (g + h x)^2, so z/(2 sqrt(H) S) is less than 1 in
                // size where that is negative, and the logarithm of (1 + it)/(1 - it) is real, and
                // more where it is positive, and the logarithm of (it + 1)/(it - 1) is.
                Entity Logarithm(Entity ratio) => -ofTheThirdKind * MathS.Ln(ratio) / (2 * MathS.Sqrt(atThePole[0]));
                answer = answer + BySigns(atThePole[0], q1 * q1 - 4 * q0 * q2,
                    Logarithm((z + twiceTheRoot) / (z - twiceTheRoot)),
                    Logarithm((twiceTheRoot + z) / (twiceTheRoot - z)),
                    ofTheThirdKind * MathS.Arctan(z / (2 * MathS.Sqrt(-atThePole[0]) * root)) / MathS.Sqrt(-atThePole[0]));
            }
            return (constantBelow == Number.Integer.One ? answer : answer / constantBelow).InnerSimplified;
        }

        /// <summary>
        /// <paramref name="expr"/> as one quotient beside the square roots of
        /// <paramref name="radicands"/>: the power of each root counted in halves, above the bar
        /// and below; the rest of what is above; the constants below; and one more factor with
        /// x in it below, to a whole power, if there is one. Null where there is anything else
        /// below.
        /// </summary>
        private static (Dictionary<Entity, int> Halves, Entity Above, Entity ConstantBelow, Entity? Third, int Order)?
            ReadBesideSquareRoots(Entity expr, Entity.Variable x, params Entity[] radicands)
        {
            // As one quotient, with a negative half-power read as the root below the bar it is.
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr.Replace(node =>
                node is Powf(var @base, Number.Rational power) && power is not Number.Integer && power.ERational.Sign < 0
                    ? Number.Integer.One / MathS.Pow(@base, Number.Rational.Create(power.ERational.Negate()))
                    : node));
            var halves = new Dictionary<Entity, int>();
            foreach (var radicand in radicands)
                halves[radicand] = 0;
            Entity above = Number.Integer.One;
            Entity constantBelow = Number.Integer.One;
            Entity? third = null;
            var order = 0;
            foreach (var (side, sign) in new[] { (numerator, 1), (denominator, -1) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var (@base, inHalves) = factor switch
                    {
                        Powf(var whole, Number.Integer k) when k.EInteger.CanFitInInt32() => (whole, 2 * k.EInteger.ToInt32Unchecked()),
                        Powf(var radicand, Number.Rational r) when r.ERational.Denominator.Equals(EInteger.FromInt32(2))
                            && r.ERational.Numerator.CanFitInInt32() => (radicand, r.ERational.Numerator.ToInt32Unchecked()),
                        _ => (factor, 2),
                    };
                    if (halves.ContainsKey(@base))
                        halves[@base] += sign * inHalves;
                    else if (!factor.ContainsNode(x))
                    {
                        if (sign > 0)
                            above = above * factor;
                        else
                            constantBelow = constantBelow * factor;
                    }
                    else if (sign > 0)
                        above = above * factor;
                    else if (inHalves <= 0 || inHalves % 2 != 0 || third is { } && third != @base)
                        return null;
                    else
                    {
                        third = @base;
                        order += inHalves / 2;
                    }
                }
            return (halves, above, constantBelow, third, order);
        }

        /// <summary>
        /// The coefficients of <paramref name="polynomial"/> in <paramref name="x"/>, from
        /// <c>x^0</c> up; null where it is not a polynomial or is of a degree past
        /// <see cref="MaximumDegreeBesideARoot"/>.
        /// </summary>
        private static Entity[]? CoefficientsBesideARoot(Entity polynomial, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(polynomial, x, out var monomials))
                return null;
            var degree = 0;
            foreach (var pair in monomials)
            {
                if (pair.Key.Sign < 0 || pair.Key.CompareTo(EInteger.FromInt32(MaximumDegreeBesideARoot)) > 0
                    || pair.Value.ContainsNode(x))
                    return null;
                degree = System.Math.Max(degree, pair.Key.ToInt32Unchecked());
            }
            var coefficients = new Entity[degree + 1];
            for (var j = 0; j <= degree; j++)
                coefficients[j] = monomials.TryGetValue(EInteger.FromInt32(j), out var coefficient) ? coefficient : Number.Integer.Zero;
            return coefficients;
        }

        /// <summary>
        /// The integral of <c>T(x)/((g + h x)^k S)</c>, <c>T</c> a polynomial with the coefficients
        /// <paramref name="t"/> and <c>S</c> a square root of <c>Q = q0 + q1 x + q2 x^2</c>, by
        /// undetermined coefficients: the algebraic terms, which the caller multiplies by
        /// <c>S</c>; a multiple of <c>int 1/S</c>; and with the linear, a multiple of
        /// <c>int 1/((g + h x) S)</c>. Null where a coefficient is not written back in the
        /// symbols.
        /// </summary>
        /// <remarks>
        /// <para>
        /// All this uses of <c>S</c> is <c>S' = Q'/(2 S)</c>, which holds because
        /// <c>sqrt(z)^2 = z</c> for every complex <c>z</c>, so <c>S</c> may be the root of <c>Q</c> or
        /// a product of the roots of its factors.
        /// </para>
        /// <para>
        /// <b>The polynomial part.</b> In powers of <c>y = g + h x</c>, the terms of <c>T</c> from
        /// <c>y^k</c> up leave a polynomial <c>R(x)</c>, and
        /// <c>int R/S = U S + lambda int 1/S</c>. The derivative of <c>U S</c> is
        /// <c>(U' Q + U Q'/2)/S</c>, so <c>R = U' Q + U Q'/2 + lambda</c>, which for <c>U</c> of one
        /// degree less than <c>R</c> is triangular. The coefficient of <c>x^j</c> on the right is
        /// <c>(j + 1) q0 u_(j+1) + (j + 1/2) q1 u_j + j q2 u_(j-1)</c>. That is solved for
        /// <c>u_(j-1)</c> from the top down, and <c>lambda</c> is what is left at <c>x^0</c>.
        /// </para>
        /// <para>
        /// <b>The terms over powers of <c>y</c>.</b> With <c>xi = -g/h</c> and <c>s = x - xi</c>, write
        /// <c>Q = alpha + beta s + gamma s^2</c>. The derivative of <c>S s^(1-j)</c> is
        /// <c>(2 (1 - j) alpha s^(-j) + (3 - 2j) beta s^(1-j) + (4 - 2j) gamma s^(2-j)) / (2 S)</c>.
        /// So for <c>j &gt;= 2</c>, <c>I_j = int 1/(s^j S)</c> is given by <c>S s^(1-j)</c> and the two
        /// integrals before it, and all the way down it is algebraic terms and a multiple of
        /// <c>I_1</c>, where <c>alpha</c>, the value of <c>Q</c> at the root of <c>y</c>, is not zero.
        /// Where it is, the linear shares a root with <c>Q</c>, and the derivative of
        /// <c>S s^(-j)</c> is <c>((1 - 2j) beta s^(-j) + (2 - 2j) gamma s^(1-j)) / (2 S)</c>: then
        /// every <c>I_j</c> is algebraic, from <c>I_1 = -2 S/(beta s)</c> up, and there is no
        /// third integral.
        /// </para>
        /// <para>
        /// <b>A power of <c>Q</c> below the bar too.</b> <c>T/((g + h x)^k Q^n S)</c> for
        /// <paramref name="belowTheRoot"/> <c>n &gt;= 1</c>, where <c>alpha</c> is not zero: the
        /// terms over powers of <c>y</c> are those of the series of <c>T/Q^n</c> at the linear's root
        /// below <c>s^k</c>, and what is left is <c>V/Q^n</c> with <c>V</c> a polynomial. Divided by
        /// <c>Q</c> <c>n</c> times, <c>V</c> is a polynomial part, which goes as above, and a
        /// linear <c>r0 + r1 x</c> over each power <c>Q^p</c>. And
        /// <c>int (r0 + r1 x)/Q^(p + 1/2)</c> is <c>(A + B x)/Q^(p - 1/2)</c> and
        /// <c>(2p - 2) B int 1/Q^(p - 1/2)</c>, with <c>A</c> and <c>B</c> from two equations whose
        /// determinant is <c>q1^2 - 4 q0 q2</c>: algebraic all the way down, since at <c>p = 1</c>
        /// there is nothing left.
        /// </para>
        /// <para>
        /// <b>Back in the symbols.</b> A symbol stands for <c>xi</c> until the end, so that what
        /// is computed is polynomial in it, and <c>alpha^(k-1)</c>, or <c>beta^k</c> beside a shared
        /// root, is divided by once. Each coefficient is then written homogeneous in <c>g</c> and
        /// <c>h</c>, with the powers of <c>h</c> counted, over the factors the caller writes
        /// <c>h^2 alpha</c> or <c>h beta</c> as: <paramref name="pole"/>'s <c>AtThePole</c>. The multiple of <c>int 1/S</c> is divided by
        /// <paramref name="firstKindOver"/> first, where there is one, and the multiple of
        /// <c>int 1/(y S)</c> by the factor <paramref name="thirdKindAlsoOver"/> names: the
        /// caller's closed forms have them below the bar.
        /// </para>
        /// </remarks>
        private static (Entity Algebraic, Entity OfTheFirstKind, Entity OfTheThirdKind)? IntegrateOverARootOfAQuadratic(
            Entity expr, Entity.Variable x, Entity[] t, Entity q0, Entity q1, Entity q2, System.Func<Entity, Entity> quadraticAt,
            ALinearBesideTheRoot? pole, Entity? firstKindOver, int? thirdKindAlsoOver, int belowTheRoot)
        {
            var degree = t.Length - 1;
            // Around the linear's root, a symbol xi stands for -g/h until the end, so that what
            // is computed is polynomial in it: T/(g + h x)^k is T/(h^k (x - xi)^k), and with
            // T = sum tau_i (x - xi)^i its terms from (x - xi)^k up are the polynomial R(x), and the
            // rest are tau_(k-j)/(x - xi)^j.
            Variable? xi = null;
            var order = 0;
            var polynomial = t;
            var overThePole = new SortedDictionary<int, Entity>();
            Entity ofTheThirdKind = Number.Integer.Zero;
            // What the coefficients over the pole are divided by: a power of each factor of
            // h^2 alpha, or of h beta, and the powers of h that brings; and the power of them the
            // rest is divided by, where Q is below the bar too.
            var belowThePole = 0;
            var hOfThePole = 0;
            var belowTheRest = 0;
            // (A + B x)/Q^p, p from 1 up to n, which the caller multiplies by S as well.
            var overTheQuadratic = new (Entity A, Entity B)[belowTheRoot + 1];
            if (belowTheRoot > 0 && pole is null)
                return null;
            if (pole is { } linear)
            {
                if (linear.AtThePole.Any(IsZeroOverTheSymbols) || belowTheRoot > 0 && linear.SharesARoot)
                    return null;
                order = linear.Order;
                xi = Variable.CreateUnique(expr, "pole");
                var beta = LowestOverTheSymbols(q1 + 2 * q2 * xi);
                var gamma = q2;
                var tau = new Entity[degree + 1];
                for (var i = 0; i <= degree; i++)
                {
                    Entity sum = Number.Integer.Zero;
                    for (var m = i; m <= degree; m++)
                        if (t[m] != Number.Integer.Zero)
                            sum = sum + t[m] * BinomialCoefficient(m, i) * WholePower(xi, m - i);
                    tau[i] = LowestOverTheSymbols(sum);
                }
                if (belowTheRoot == 0)
                {
                    polynomial = new Entity[System.Math.Max(degree - order + 1, 0)];
                    for (var m = 0; m < polynomial.Length; m++)
                    {
                        Entity sum = Number.Integer.Zero;
                        for (var i = order + m; i <= degree; i++)
                            if (tau[i] != Number.Integer.Zero)
                                sum = sum + tau[i] * BinomialCoefficient(i - order, m) * WholePower(-xi, i - order - m);
                        polynomial[m] = LowestOverTheSymbols(sum);
                    }
                }
                if (linear.SharesARoot)
                {
                    // Q = beta (x - xi) + gamma (x - xi)^2, so
                    //     I_j = (2 S (x - xi)^(-j) - (2 - 2j) gamma I_(j-1)) / ((1 - 2j) beta),
                    // and beta^j I_j is a polynomial in xi times powers of x - xi, times S: sum
                    // tau_(k-j) I_j over beta^k.
                    var previous = new Dictionary<int, Entity>();
                    for (var j = 1; j <= order; j++)
                    {
                        var these = new Dictionary<int, Entity> { [-j] = 2 * WholePower(beta, j - 1) };
                        foreach (var pair in previous)
                            these[pair.Key] = these.TryGetValue(pair.Key, out var so)
                                ? so - (2 - 2 * j) * gamma * pair.Value : -(2 - 2 * j) * gamma * pair.Value;
                        previous = these.ToDictionary(pair => pair.Key, pair => LowestOverTheSymbols(pair.Value / (1 - 2 * j)));
                        if (order - j > degree || tau[order - j] == Number.Integer.Zero)
                            continue;
                        var weight = tau[order - j] * WholePower(beta, order - j);
                        foreach (var pair in previous)
                            overThePole[pair.Key] = overThePole.TryGetValue(pair.Key, out var so) ? so + weight * pair.Value : weight * pair.Value;
                    }
                    foreach (var power in overThePole.Keys.ToList())
                        overThePole[power] = LowestOverTheSymbols(overThePole[power]);
                    belowThePole = order;
                    hOfThePole = order;
                }
                else
                {
                    var alpha = LowestOverTheSymbols(quadraticAt(xi));
                    // I_j = int 1/((x - xi)^j S), with Q = alpha + beta (x - xi) + gamma (x - xi)^2. The
                    // derivative of S (x - xi)^(1-j) is
                    //     (2 (1 - j) alpha (x - xi)^(-j) + (3 - 2j) beta (x - xi)^(1-j)
                    //         + (4 - 2j) gamma (x - xi)^(2-j)) / (2 S),
                    // so alpha^(j-1) I_j is a polynomial in xi times powers of x - xi, times S, and a
                    // polynomial in xi times I_1: divided by alpha only once, at the end.
                    var scaled = new Dictionary<int, Entity>[order + 1];
                    var ofTheFirst = new Entity[order + 1];
                    scaled[0] = new Dictionary<int, Entity>();
                    ofTheFirst[0] = Number.Integer.Zero;
                    if (order >= 1)
                    {
                        scaled[1] = new Dictionary<int, Entity>();
                        ofTheFirst[1] = Number.Integer.One;
                    }
                    for (var j = 2; j <= order; j++)
                    {
                        var these = new Dictionary<int, Entity> { [1 - j] = 2 * WholePower(alpha, j - 2) };
                        foreach (var (earlier, times) in new[] { (scaled[j - 1], (3 - 2 * j) * beta), (scaled[j - 2], (4 - 2 * j) * gamma * alpha) })
                            foreach (var pair in earlier)
                                these[pair.Key] = these.TryGetValue(pair.Key, out var so) ? so - times * pair.Value : -times * pair.Value;
                        scaled[j] = these.ToDictionary(pair => pair.Key, pair => LowestOverTheSymbols(pair.Value / (2 * (1 - j))));
                        ofTheFirst[j] = LowestOverTheSymbols((-(3 - 2 * j) * beta * ofTheFirst[j - 1] - (4 - 2 * j) * gamma * alpha * ofTheFirst[j - 2]) / (2 * (1 - j)));
                    }
                    // The numerators over (x - xi)^j are tau_(k-j), or with Q^n below the bar too, the
                    // terms of the series of T/Q^n at xi, alpha^(n + k - 1) times over.
                    var principal = tau;
                    if (belowTheRoot > 0)
                    {
                        belowTheRest = belowTheRoot + order - 1;
                        if (OverAPowerOfTheQuadratic(tau, alpha, beta, gamma) is not { } split)
                            return null;
                        principal = split.Principal;
                        polynomial = split.Polynomial;
                        overTheQuadratic = split.OverTheQuadratic;
                    }
                    // sum principal_(k-j) I_j over alpha^(k-1), and the alpha^(n + k - 1) of the series.
                    for (var j = 1; j <= order; j++)
                    {
                        if (order - j >= principal.Length || principal[order - j] == Number.Integer.Zero)
                            continue;
                        var weight = principal[order - j] * WholePower(alpha, order - j);
                        foreach (var pair in scaled[j])
                            overThePole[pair.Key] = overThePole.TryGetValue(pair.Key, out var so) ? so + weight * pair.Value : weight * pair.Value;
                        ofTheThirdKind = ofTheThirdKind + weight * ofTheFirst[j];
                    }
                    foreach (var power in overThePole.Keys.ToList())
                        overThePole[power] = LowestOverTheSymbols(overThePole[power]);
                    ofTheThirdKind = LowestOverTheSymbols(ofTheThirdKind);
                    belowThePole = order - 1 + belowTheRest;
                    hOfThePole = 2 * belowThePole;
                }
            }

            // T/Q^n around xi, with s = x - xi: the series of 1/Q is sum p_i s^i/alpha^(i+1), with
            // p_0 = 1 and p_i = -(beta p_(i-1) + gamma alpha p_(i-2)), so that of 1/Q^n is
            // sum pi_i s^i/alpha^(n+i), pi the n-th power of p, and alpha^(n+k-1) times the terms
            // of T/Q^n below s^k are polynomials in xi. What is left, V/Q^n, has
            // V = (alpha^(n+k-1) T - Q^n sum_(i<k) w_i s^i)/s^k a polynomial; in x, divided by Q
            // n times, it is the polynomial part over the quotient, and (r0 + r1 x)/Q^p over the
            // remainders, each of which comes down to (A + B x) S/Q^p and the next power's.
            (Entity[] Principal, Entity[] Polynomial, (Entity A, Entity B)[] OverTheQuadratic)? OverAPowerOfTheQuadratic(
                Entity[] tau, Entity alpha, Entity beta, Entity gamma)
            {
                var n = belowTheRoot;
                var scale = n + order - 1;
                var p = new Entity[order];
                for (var i = 0; i < order; i++)
                    p[i] = i == 0 ? Number.Integer.One
                        : LowestOverTheSymbols(-(beta * p[i - 1] + (i >= 2 ? gamma * alpha * p[i - 2] : Number.Integer.Zero)));
                var pi = p;
                for (var power = 2; power <= n; power++)
                    pi = Product(pi, p, order);
                var principal = new Entity[order];
                for (var i = 0; i < order; i++)
                {
                    Entity sum = Number.Integer.Zero;
                    for (var l = 0; l <= System.Math.Min(i, tau.Length - 1); l++)
                        if (tau[l] != Number.Integer.Zero)
                            sum = sum + tau[l] * pi[i - l] * WholePower(alpha, order - 1 - i + l);
                    principal[i] = LowestOverTheSymbols(sum);
                }
                var quadratic = new[] { alpha, beta, gamma };
                var qn = new Entity[] { Number.Integer.One };
                for (var power = 1; power <= n; power++)
                    qn = Product(qn, quadratic, 2 * power + 1);
                var top = System.Math.Max(tau.Length - 1, 2 * n + order - 1);
                var inS = new Entity[top - order + 1];
                for (var m = order; m <= top; m++)
                {
                    Entity sum = m < tau.Length ? tau[m] * WholePower(alpha, scale) : Number.Integer.Zero;
                    for (var i = 0; i < order; i++)
                        if (m - i <= 2 * n && principal[i] != Number.Integer.Zero)
                            sum = sum - qn[m - i] * principal[i];
                    inS[m - order] = LowestOverTheSymbols(sum);
                }
                var inX = new Entity[inS.Length];
                for (var j = 0; j < inX.Length; j++)
                {
                    Entity sum = Number.Integer.Zero;
                    for (var m = j; m < inS.Length; m++)
                        if (inS[m] != Number.Integer.Zero)
                            sum = sum + inS[m] * BinomialCoefficient(m, j) * WholePower(-xi!, m - j);
                    inX[j] = LowestOverTheSymbols(sum);
                }
                // The remainders by Q: the i-th is over Q^(n-i).
                var carried = new (Entity R0, Entity R1)[n + 1];
                var quotient = inX;
                for (var i = 0; i < n; i++)
                {
                    var rest = (Entity[])quotient.Clone();
                    var next = new Entity[System.Math.Max(rest.Length - 2, 0)];
                    for (var m = rest.Length - 1; m >= 2; m--)
                    {
                        var c = LowestOverTheSymbols(rest[m] / q2);
                        next[m - 2] = c;
                        rest[m - 1] = rest[m - 1] - c * q1;
                        rest[m - 2] = rest[m - 2] - c * q0;
                    }
                    carried[n - i] = (rest.Length > 0 ? LowestOverTheSymbols(rest[0]) : Number.Integer.Zero,
                        rest.Length > 1 ? LowestOverTheSymbols(rest[1]) : Number.Integer.Zero);
                    quotient = next;
                }
                // int (r0 + r1 x)/Q^(p + 1/2) = (A + B x)/Q^(p - 1/2) + (2p - 2) B int 1/Q^(p - 1/2), where
                // (p - 1/2)(B q1 - 2 A q2) = r1 and (p - 1/2)(2 B q0 - A q1) = r0: the derivative of
                // (A + B x)/Q^(p - 1/2) is (B Q - (p - 1/2)(A + B x) Q')/Q^(p + 1/2). At p = 1 there is
                // nothing left over.
                var discriminant = q1 * q1 - 4 * q0 * q2;
                var overTheQuadratic = new (Entity A, Entity B)[n + 1];
                for (var level = n; level >= 1; level--)
                {
                    var (r0, r1) = carried[level];
                    var half = Number.Rational.Create(2 * level - 1, 2);
                    var a = LowestOverTheSymbols((2 * q0 * r1 - q1 * r0) / (half * discriminant));
                    var b = LowestOverTheSymbols((q1 * r1 - 2 * q2 * r0) / (half * discriminant));
                    overTheQuadratic[level] = (a, b);
                    if (level >= 2)
                        carried[level - 1] = (LowestOverTheSymbols(carried[level - 1].R0 + (2 * level - 2) * b), carried[level - 1].R1);
                }
                return (principal, quotient, overTheQuadratic);
            }
            static Entity[] Product(Entity[] left, Entity[] right, int terms)
            {
                var product = new Entity[terms];
                for (var i = 0; i < terms; i++)
                {
                    Entity sum = Number.Integer.Zero;
                    for (var l = 0; l <= i; l++)
                        if (l < left.Length && i - l < right.Length && left[l] != Number.Integer.Zero && right[i - l] != Number.Integer.Zero)
                            sum = sum + left[l] * right[i - l];
                    product[i] = LowestOverTheSymbols(sum);
                }
                return product;
            }

            // The polynomial part: u_(j-1) from the top down, and lambda at x^0.
            var u = new Entity[polynomial.Length + 1];
            for (var j = 0; j < u.Length; j++)
                u[j] = Number.Integer.Zero;
            Entity lambda = Number.Integer.Zero;
            if (polynomial.Length > 0)
            {
                var n = polynomial.Length - 1;
                for (var j = n; j >= 1; j--)
                    u[j - 1] = LowestOverTheSymbols((polynomial[j] - (j + 1) * q0 * u[j + 1] - Number.Rational.Create(2 * j + 1, 2) * q1 * u[j]) / (j * q2));
                lambda = polynomial[0] - q0 * u[1] - q1 * u[0] / 2;
            }

            // xi back to -g/h, with the 1/h^k in front. Each side of a coefficient is a
            // polynomial in xi, written homogeneous in g and h with the powers of h counted:
            // substituted as it stands, each term would bring its own power of h below the bar,
            // and over one bar they multiply.
            Entity? Back(Entity coefficient, int powerOfH, int[] overTheFactors)
            {
                var (above, below) = Functions.SingleQuotient.Of(LowestOverTheSymbols(coefficient));
                if (xi is null)
                    return LowestOverTheSymbols(above / below);
                if (Homogeneous(above) is not var (aboveInGAndH, aboveDegree) || Homogeneous(below) is not var (belowInGAndH, belowDegree))
                    return null;
                var h = pole!.H;
                var power = powerOfH + belowDegree - aboveDegree - order;
                var numerator = LowestOverTheSymbols(power > 0 ? aboveInGAndH * WholePower(h, power) : aboveInGAndH);
                if (numerator == Number.Integer.Zero)
                    return Number.Integer.Zero;
                var denominator = LowestOverTheSymbols(power < 0 ? belowInGAndH * WholePower(h, -power) : belowInGAndH);
                // alpha^(k-1) is (h^2 alpha)^(k-1)/h^(2 (k - 1)), and beta^k is (h beta)^k/h^k, their
                // powers of h counted in powerOfH, and h^2 alpha or h beta left in the factors the
                // caller writes it as.
                Entity written = denominator;
                for (var i = 0; i < overTheFactors.Length; i++)
                    written = written * WholePower(pole.AtThePole[i], overTheFactors[i]);
                var lowest = LowestOverTheSymbols(numerator / written);
                return lowest.Complexity <= (numerator / written).Complexity ? lowest : numerator / written;
            }
            (Entity, int)? Homogeneous(Entity inXi)
            {
                if (!TreeAnalyzer.TryGetPolynomial(inXi, xi!, out var byPower) || byPower.Keys.Any(power => power.Sign < 0 || !power.CanFitInInt32()))
                    return null;
                var (_, g, h, _, _, _) = pole!;
                var top = byPower.Keys.Max()!.ToInt32Unchecked();
                Entity sum = Number.Integer.Zero;
                foreach (var pair in byPower)
                    sum = sum + pair.Value * WholePower(-g, pair.Key.ToInt32Unchecked()) * WholePower(h, top - pair.Key.ToInt32Unchecked());
                return (LowestOverTheSymbols(sum), top);
            }

            var factors = pole?.AtThePole.Length ?? 0;
            var overTheRest = Enumerable.Repeat(belowTheRest, factors).ToArray();
            Entity algebraic = Number.Integer.Zero;
            for (var j = u.Length - 1; j >= 0; j--)
                if (u[j] != Number.Integer.Zero)
                {
                    if (Back(u[j], 2 * belowTheRest, overTheRest) is not { } coefficient)
                        return null;
                    if (coefficient != Number.Integer.Zero)
                        algebraic = algebraic + coefficient * WholePower(x, j);
                }
            for (var power = belowTheRoot; power >= 1; power--)
            {
                var (a, b) = overTheQuadratic[power];
                if (Back(a, 2 * belowTheRest, overTheRest) is not { } constant || Back(b, 2 * belowTheRest, overTheRest) is not { } slope)
                    return null;
                if (constant != Number.Integer.Zero || slope != Number.Integer.Zero)
                    algebraic = algebraic + (constant + slope * x) / WholePower(quadraticAt(x), power);
            }
            // (x - xi)^p is h^(-p) (g + h x)^p.
            var overThePoleFactors = Enumerable.Repeat(belowThePole, factors).ToArray();
            foreach (var pair in overThePole)
            {
                if (Back(pair.Value, -pair.Key + hOfThePole, overThePoleFactors) is not { } coefficient)
                    return null;
                if (coefficient != Number.Integer.Zero)
                    algebraic = algebraic + coefficient / WholePower(pole!.Linear, -pair.Key);
            }
            Entity ofTheFirstKind = Number.Integer.Zero;
            if (lambda != Number.Integer.Zero)
            {
                if (Back(firstKindOver is null ? lambda : lambda / firstKindOver, 2 * belowTheRest, overTheRest) is not { } coefficient)
                    return null;
                ofTheFirstKind = coefficient;
            }
            // int 1/((x - xi) S) is h int 1/(y S).
            Entity thirdKind = Number.Integer.Zero;
            if (xi is { } && ofTheThirdKind != Number.Integer.Zero)
            {
                if (thirdKindAlsoOver is { } factor)
                    overThePoleFactors[factor]++;
                if (Back(ofTheThirdKind, hOfThePole + 1, overThePoleFactors) is not { } coefficient)
                    return null;
                thirdKind = coefficient;
            }
            return (algebraic, ofTheFirstKind, thirdKind);
        }

        /// <summary>
        /// The linear below the bar beside the root of a quadratic <c>Q</c>, for
        /// <see cref="IntegrateOverARootOfAQuadratic"/>: as written, <c>g + h x</c>, to the power
        /// <c>Order</c>. <c>AtThePole</c> holds the factors the caller writes <c>h^2 Q(-g/h)</c> as,
        /// or where that is zero and the linear shares a root with <c>Q</c>, <c>h Q'(-g/h)</c>.
        /// </summary>
        private sealed record ALinearBesideTheRoot(Entity Linear, Entity G, Entity H, int Order, Entity[] AtThePole, bool SharesARoot);

        private static Entity LowestOverTheSymbols(Entity e) => Functions.PartialFractions.InLowestTermsOverTheSymbols(e);

        // Each closed form is real on one side of the sign of the quantity under its roots, and
        // complex by a constant on the other: the form for the sign of a number, and both, each
        // where it holds, for a quantity with symbols in it, as `1/(a - x^2)` is answered. A
        // number times even powers of symbols has the number's sign wherever the symbols are
        // real and not zero, which is the generic case: `-b^2` in `a^2 - b^2 x^2` is negative.
        private static Entity BySign(Entity quantity, Entity wherePositive, Entity whereNegative)
            => SignOfANumberTimesEvenPowers(quantity) is { } sign
                ? (sign < 0 ? whereNegative : wherePositive)
                : MathS.Piecewise((wherePositive, new Greaterf(quantity, Number.Integer.Zero)), (whereNegative, new Lessf(quantity, Number.Integer.Zero)));

        // The same where the form for a positive first quantity is chosen by the sign of a second,
        // as one piecewise rather than one inside another.
        private static Entity BySigns(Entity first, Entity second, Entity wherePositiveAndPositive, Entity wherePositiveAndNegative, Entity whereNegative)
        {
            var wherePositive = BySign(second, wherePositiveAndPositive, wherePositiveAndNegative);
            if (wherePositive is not Piecewise || SignOfANumberTimesEvenPowers(first) is { })
                return BySign(first, wherePositive, whereNegative);
            var positive = new Greaterf(first, Number.Integer.Zero);
            return MathS.Piecewise(
                (wherePositiveAndPositive, new Andf(positive, new Greaterf(second, Number.Integer.Zero))),
                (wherePositiveAndNegative, new Andf(positive, new Lessf(second, Number.Integer.Zero))),
                (whereNegative, new Lessf(first, Number.Integer.Zero)));
        }

        private static int? SignOfANumberTimesEvenPowers(Entity quantity)
        {
            var sign = 1;
            foreach (var factor in Mulf.LinearChildren(quantity.InnerSimplified))
                switch (factor)
                {
                    case Number.Real { IsZero: true }:
                        return null;
                    case Number.Real number:
                        sign *= number.IsNegative ? -1 : 1;
                        break;
                    case Powf(Variable, Number.Integer power) when power.EInteger.IsEven && !power.EInteger.IsZero:
                        break;
                    default:
                        return null;
                }
            return sign;
        }

        private static bool IsZeroOverTheSymbols(Entity e) => e.InnerSimplified is var simplified
            && (simplified.Evaled is Number.Complex { IsZero: true } || simplified.Vars.Any() && LowestOverTheSymbols(simplified) == Number.Integer.Zero);

        // Not e^0, which is 1 only where e is not 0, and says so.
        private static Entity WholePower(Entity e, int n) => n switch { 0 => Number.Integer.One, 1 => e, _ => MathS.Pow(e, n) };

        private static Entity BinomialCoefficient(int n, int k)
        {
            var result = EInteger.One;
            for (var i = 1; i <= k; i++)
                result = result.Multiply(EInteger.FromInt32(n - k + i)).Divide(EInteger.FromInt32(i));
            return Number.Integer.Create(result);
        }

        /// <summary>
        /// The degree of the polynomial <see cref="IntegrateOverARootOfAQuadratic"/> solves for:
        /// one unknown a degree. Rubi's 1.1.1.6 reaches eight, and 1.2.1.9 ten.
        /// </summary>
        private const int MaximumDegreeBesideARoot = 16;

        /// <summary>
        /// Whether <paramref name="expr"/> is a quotient of two polynomials linear in
        /// <paramref name="x"/>, the one below with a slope.
        /// </summary>
        private static bool IsAQuotientOfLinears(Entity expr, Entity.Variable x)
        {
            var (above, below) = Functions.SingleQuotient.Of(expr);
            return below != Number.Integer.One
                && TreeAnalyzer.TryGetPolyLinear(above, x, out _, out _)
                && TreeAnalyzer.TryGetPolyLinear(below, x, out var slope, out _)
                && slope.Evaled is not Number.Complex { IsZero: true };
        }

        /// <summary>
        /// Whether <paramref name="expr"/> is a polynomial in one sine or one cosine of one
        /// argument holding <paramref name="x"/>, and nothing else of <paramref name="x"/>.
        /// </summary>
        private static bool IsAPolynomialInOneTrigonometricFunction(Entity expr, Entity.Variable x)
        {
            var functions = expr.Nodes.Where(node => node is Sinf or Cosf && node.ContainsNode(x)).Distinct().ToList();
            if (functions.Count == 2)
            {
                // A polynomial in the sine and the cosine of one argument with the cosine only
                // in even powers is a polynomial in the sine, by Pythagoras, and the other way
                // about: Timofeev's `sqrt(3 cos(x)^2 - sin(x)^2)` is `sqrt(3 - 4 sin(x)^2)`,
                // and beside `cos(3x)` it was declined for the two functions under the root.
                if (TrigonometricArgument(functions[0]) != TrigonometricArgument(functions[1]) || functions[0].GetType() == functions[1].GetType())
                    return false;
                var first = Variable.CreateUnique(expr, "trig_1");
                var second = Variable.CreateUnique(expr, "trig_2");
                var inBoth = expr.Substitute(functions[0], first).Substitute(functions[1], second);
                if (inBoth.ContainsNode(x))
                    return false;
                var expanded = inBoth.Expand();
                return IsEvenIn(expanded, first, second) || IsEvenIn(expanded, second, first);

                static bool IsEvenIn(Entity polynomial, Entity.Variable even, Entity.Variable other)
                    => TreeAnalyzer.TryGetPolynomial(polynomial, even, out var read)
                       && read.All(pair => pair.Key.IsEven && pair.Key.Sign >= 0 && TreeAnalyzer.TryGetPolynomial(pair.Value, other, out _));
            }
            if (functions.Count != 1)
                return false;
            var placeholder = Variable.CreateUnique(expr, "trig");
            var inPlaceholder = expr.Substitute(functions[0], placeholder);
            return !inPlaceholder.ContainsNode(x) && TreeAnalyzer.TryGetPolynomial(inPlaceholder, placeholder, out _);
        }

        /// <summary>
        /// Trigonometric functions of several arguments that are whole or rational multiples of one
        /// linear, <c>p + q x</c>, written in <c>u = p + q x</c>: <c>csc(a + b x) csc(2a + 2b x)^2</c>
        /// is <c>csc(u) csc(2u)^2</c> over <c>b</c>, whose arguments are multiples of <c>u</c> alone,
        /// which the rule that unifies the arguments reads.
        /// </summary>
        /// <remarks>
        /// That rule takes a numeric slope and writes an offset out by the addition formula, so
        /// <c>csc(1 + x) csc(2 + 2x)^2</c> became a rational function of the sine and cosine with
        /// <c>sin(2)</c> and <c>cos(2)</c> in its coefficients, and ran twenty seconds; with the slope
        /// a symbol it declined at once. Only where some argument has an offset or a symbolic
        /// slope, the rest being that rule's already, and where x stands nowhere else. At the
        /// question asked or one below it, since it lands on the chain in u. Rubi's 4.7.1.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingMultiplesOfOneLinearArgument(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            Entity? first = null;
            Entity? firstSlope = null;
            Entity? firstOffset = null;
            var arguments = new List<Entity>();
            var needed = false;
            foreach (var node in expr.Nodes)
            {
                if (TrigonometricArgument(node) is not { } argument || !argument.ContainsNode(x) || arguments.Contains(argument))
                    continue;
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset) || slope.ContainsNode(x) || offset.ContainsNode(x)
                    || TreeAnalyzer.IsZero(slope))
                    return null;
                arguments.Add(argument);
                (first, firstSlope, firstOffset) = first is null ? (argument, slope, offset) : (first, firstSlope, firstOffset);
                if (slope.Evaled is not Number.Rational || offset.Evaled is not Number.Complex { IsZero: true })
                    needed = true;
            }
            if (first is null || firstSlope is null || firstOffset is null || arguments.Count < 2 || !needed)
                return null;
            // Each argument r times the first, r a rational number.
            var ratios = new Dictionary<Entity, Entity>();
            foreach (var argument in arguments)
            {
                TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset);
                var ratio = (slope! / firstSlope).InnerSimplified;
                if (ratio.Evaled is not Number.Rational)
                    ratio = Functions.PartialFractions.Bare(ratio.Simplify());
                if (ratio.Evaled is not Number.Rational rational || !VanishesIdentically(offset! - rational * firstOffset))
                    return null;
                ratios[argument] = rational;
            }
            var u = Variable.CreateUnique(expr, "u_argument");
            Entity? Of(Entity argument) => ratios.TryGetValue(argument, out var r) ? (r == Number.Integer.One ? u : r * u) : null;
            var inU = expr.Replace(node => node switch
            {
                Sinf(var a) when Of(a) is { } v => MathS.Sin(v),
                Cosf(var a) when Of(a) is { } v => MathS.Cos(v),
                Tanf(var a) when Of(a) is { } v => MathS.Tan(v),
                Cotanf(var a) when Of(a) is { } v => MathS.Cotan(v),
                Secantf(var a) when Of(a) is { } v => MathS.Sec(v),
                Cosecantf(var a) when Of(a) is { } v => new Cosecantf(v),
                _ => node,
            });
            if (inU.ContainsNode(x))
                return null;
            // dx = du/q.
            if (Integration.ComputeAsAQuestionOfItsOwn((inU / firstSlope).InnerSimplified, u, integrateByParts) is not { } answer)
                return null;
            var back = answer.Substitute(u, first);
            return back.Nodes.Any(node => node == MathS.NaN) ? null : back;
        }

        /// <summary>
        /// An algebraic integrand in which a linear <c>c + d x</c> stands under a power inside a
        /// sum, written in <c>u = c + d x</c>: <c>x^3/(a + b (c + d x)^3)</c> is
        /// <c>(u - c)^3/(d^4 (a + b u^3))</c>, and <c>(c + d x)^4/(a + b (c + d x)^3)</c> is
        /// <c>u^4/(d (a + b u^3))</c>, which the rules for a binomial answer.
        /// </summary>
        /// <remarks>
        /// In x the sum is a polynomial whose roots are those of <c>a + b u^n</c> moved and
        /// scaled, which the partial fractions do not read, and the substitution search reads
        /// one function at a time: Rubi's 1.1.3.2, 1.2.3.2 and 1.3.1 write whole sections so.
        /// Only where one linear, up to a constant multiple, stands under the powers inside sums,
        /// with an offset or a slope other than 1, and x stands nowhere but in polynomials and
        /// powers of them: written in u, nothing is left in x. At the question asked or one below
        /// it, since it lands on the chain in u.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAFunctionOfOneShiftedLinear(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            // Algebraic in x: sums, products, quotients and powers with exponents free of it.
            foreach (var node in expr.Nodes)
                if (node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf)
                    && !(node is Powf(_, var exponent) && !exponent.ContainsNode(x)))
                    return null;
            Entity? linear = null;
            Entity? slope = null;
            Entity? offset = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not (Sumf or Minusf))
                    continue;
                foreach (var term in Sumf.LinearChildren(node))
                    foreach (var factor in Mulf.LinearChildren(term))
                    {
                        if (factor is not Powf(var @base, _) || !@base.ContainsNode(x)
                            || !TreeAnalyzer.TryGetPolyLinear(@base, x, out var d, out var c)
                            || d.ContainsNode(x) || c.ContainsNode(x) || TreeAnalyzer.IsZero(d))
                            continue;
                        if (linear is null)
                            (linear, slope, offset) = (@base, d, c);
                        else if (!VanishesIdentically(slope! * c - d * offset!))
                            return null;
                    }
            }
            if (linear is null || slope is null || offset is null
                || VanishesIdentically(offset) && VanishesIdentically(slope - 1))
                return null;
            // x = (u - c)/d, and each base linear in u written as one.
            var u = Variable.CreateUnique(expr, "u_linear");
            var inU = expr.Substitute(x, (u - offset) / slope).InnerSimplified.Replace(node =>
                node is Powf(var @base, var power) && @base.ContainsNode(u)
                    && TreeAnalyzer.TryGetPolyLinear(@base, u, out var d, out var c) && !d.ContainsNode(u) && !c.ContainsNode(u)
                    ? MathS.Pow(Functions.PartialFractions.InLowestTermsOverTheSymbols(d) * u + Functions.PartialFractions.InLowestTermsOverTheSymbols(c), power)
                    : node);
            if (inU.ContainsNode(x))
                return null;
            // dx = du/d.
            if (Integration.ComputeAsAQuestionOfItsOwn((inU / slope).InnerSimplified, u, integrateByParts) is not { } answer)
                return null;
            var back = answer.Substitute(u, linear);
            return back.Nodes.Any(node => node == MathS.NaN) ? null : back;
        }

        /// <summary>
        /// An integrand whose trigonometric functions have <b>different multiples</b> of one
        /// argument — <c>sin(x)/cos(2x)</c>, <c>cos(x)/(sin(x) tan(x/2))</c> — rewritten so that
        /// every one of them is of the same argument, and handed on.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Every trigonometric rule here reads one argument: a quotient of homogeneous
        /// polynomials in <c>sin(u)</c> and <c>cos(u)</c>, a function of <c>tan(u)</c>, the
        /// half-angle substitution in <c>u</c>. An integrand with <c>x</c> and <c>2x</c> in it
        /// is none of those and every one of them declined it — while the same integrand with
        /// <c>cos(2x)</c> written as <c>1 - 2 sin(x)^2</c> came out. Nothing was missing but the
        /// rewriting. Product-to-sum, beside this, goes the other way, and fires on a product of
        /// two different arguments; this fires on anything else built from them.
        /// </para>
        /// <para>
        /// The common argument is <c>g x</c> with <c>g</c> the greatest common divisor of the
        /// slopes, so <c>x</c> and <c>x/2</c> share <c>x/2</c> and <c>2x</c> and <c>3x</c> share
        /// <c>x</c>. Each function of <c>n g x</c> is then a polynomial in <c>sin(g x)</c> and
        /// <c>cos(g x)</c> through the Chebyshev recurrences, <c>cos(n t) = T_n(cos t)</c> and
        /// <c>sin(n t) = sin(t) U_(n-1)(cos t)</c>, which are identities and owe no condition;
        /// a tangent, secant or cosecant is the quotient of those it stands for. Slopes are
        /// rational and the multiples are capped, since a function of <c>50x</c> beside one of
        /// <c>x</c> is a degree-fifty polynomial nobody wants.
        /// </para>
        /// <para>
        /// It terminates: what it hands on has one argument, on which this rule declines.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByUnifyingTrigonometricArguments(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Rational in the trigonometric functions, and no more: a radical of one, or a
            // fractional power, is a different integrand, and the expanded polynomial under it
            // is one no rule reads. `sqrt(cos(x) sin(x)^3)` beside `sin(2x)` and
            // `(2 - 3 sin(x)^2)^(3/5) sin(4x)` were each five seconds spent to decline once the
            // rewriting let them through; each declined in a tenth of that before.
            //
            // And bounded in the degree the rewriting produces: a power of a sum holding a
            // function of `3x`, raised to the fifth, is a polynomial of degree fifteen in the
            // sine and cosine, and `1/(cos(x) + cos(3x))^5` went the same way for it.
            var slopes = new List<Number.Rational>();
            var arguments = new HashSet<(ERational Slope, Entity Offset)>();
            var anOffset = false;
            foreach (var node in expr.Nodes)
            {
                if (!node.ContainsNode(x))
                    continue;
                switch (node)
                {
                    case Variable or Sumf or Minusf or Mulf or Divf:
                    case Sinf or Cosf or Tanf or Cotanf or Secantf or Cosecantf:
                    case Powf(_, Number.Integer):
                        break;
                    // A fractional power of a polynomial in *one* function of one argument is
                    // let through: `(2 - 3 sin(x)^2)^(3/5) sin(4x)` is, under the sine, a sum of
                    // binomial differentials once the multiple is written out, and the binomial
                    // rule answers those at any depth now. A root of a product of two functions
                    // is not -- `sqrt(cos(x) sin(x)^3)` beside `sin(2x)` was thirty seconds to
                    // decline let through -- and nor is anything else.
                    case Powf(var radicalBase, Number.Rational) when IsAPolynomialInOneTrigonometricFunction(radicalBase, x):
                        break;
                    default:
                        return null;
                }
                if (TrigonometricArgument(node) is not { } argument || !argument.ContainsNode(x))
                    continue;
                // An offset free of x is allowed, and written out by the addition formula
                // below: Timofeev's `tan(x) tan(x - a)` is a rational function of `tan(x)` once
                // `tan(x - a)` is `(tan(x) - tan(a))/(1 + tan(x) tan(a))`.
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset)
                    || offset.ContainsNode(x)
                    || slope.Evaled is not Number.Rational rational || rational.IsZero)
                    return null;
                slopes.Add(rational);
                arguments.Add((rational.ERational, offset.InnerSimplified));
                if (offset.Evaled is not Number.Complex { IsZero: true })
                    anOffset = true;
            }
            if (slopes.Count < 2 || arguments.Count < 2)
                return null;

            // g = gcd of the numerators over the lcm of the denominators, so that every slope is
            // a whole multiple of it; nothing to do when they are all the same multiple.
            var numerators = EInteger.Zero;
            var denominators = EInteger.One;
            foreach (var slope in slopes)
            {
                numerators = numerators.Gcd(slope.ERational.Numerator.Abs());
                denominators = denominators.Multiply(slope.ERational.Denominator)
                    .Divide(denominators.Gcd(slope.ERational.Denominator));
            }
            var common = ERational.Create(numerators, denominators);
            var multiples = new HashSet<int>();
            foreach (var slope in slopes)
            {
                // Reduced before its numerator is read: `Divide` leaves `2/2` as it is.
                var multiple = slope.ERational.Divide(common).ToLowestTerms();
                if (!multiple.IsInteger() || !multiple.Numerator.Abs().CanFitInInt32())
                    return null;
                var n = multiple.Numerator.Abs().ToInt32Unchecked();
                if (n > MaximumUnifiedMultiple)
                    return null;
                multiples.Add(n);
            }
            if (multiples.Count < 2 && !anOffset)
                return null;
            if (ExpandedDegree(expr, x, common) > MaximumUnifiedDegree)
                return null;

            var theta = (Number.Rational.Create(common) * x).InnerSimplified;

            // Up before down. With only the argument and its double present, an integrand that
            // is even in the smaller one is a function of the doubled one alone, at half the
            // degree the other direction gives; that is tried first and the rest falls through.
            if (!anOffset && multiples.Count == 2 && multiples.Contains(1) && multiples.Contains(2)
                && TryRaiseToTheDoubledArgument(expr, x, theta) is { } raised)
            {
                var (raisedNumerator, raisedDenominator) = Functions.SingleQuotient.Of(raised.InnerSimplified);
                if (Integration.ComputeIndefiniteIntegral(
                        CancelCommonFactors(raisedNumerator, raisedDenominator), x, integrateByParts: false) is { } fromAbove)
                    return fromAbove;
            }

            var sine = MathS.Sin(theta);
            var cosine = MathS.Cos(theta);
            var rewritten = expr.Replace(node =>
            {
                if (TrigonometricArgument(node) is not { } argument || !argument.ContainsNode(x)
                    || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset)
                    || slope.Evaled is not Number.Rational rational)
                    return node;
                var multiple = rational.ERational.Divide(common).ToLowestTerms();
                var n = multiple.Numerator.Abs().ToInt32Unchecked();
                var negative = multiple.Numerator.Sign < 0;
                var (sin, cos) = SineAndCosineOfAMultiple(n, sine, cosine);
                if (negative)
                    sin = -sin;
                if (offset.Evaled is not Number.Complex { IsZero: true })
                {
                    // sin(u + c) = sin(u) cos(c) + cos(u) sin(c), cos(u + c) = cos(u) cos(c) - sin(u) sin(c).
                    var (sinOfOffset, cosOfOffset) = (MathS.Sin(offset).InnerSimplified, MathS.Cos(offset).InnerSimplified);
                    (sin, cos) = (sin * cosOfOffset + cos * sinOfOffset, cos * cosOfOffset - sin * sinOfOffset);
                }
                return node switch
                {
                    Sinf => sin,
                    Cosf => cos,
                    Tanf => sin / cos,
                    Cotanf => cos / sin,
                    Secantf => 1 / cos,
                    Cosecantf => 1 / sin,
                    _ => node
                };
            });
            // As one quotient with the common factors cancelled, before it is handed on. The
            // rewriting leaves a quotient of quotients with a factor to cancel -- `tan(x)/tan(2x)`
            // becomes `(s/c) / (2sc/(2c^2 - 1))` -- and on that shape, or on the single quotient
            // with the `s` still in it, the search ran for twenty-five seconds to decline what is
            // `1 - 1/(2c^2)` and answered in a quarter of one. `Simplify` is not the tool: it
            // folds `2sc` back into `sin(2x)` and hands this rule its own input.
            var (numerator, denominator) = Functions.SingleQuotient.Of(rewritten.InnerSimplified);
            var cancelled = CancelCommonFactors(numerator, denominator);
            // A radicand in both functions with one of them in even powers only is written
            // in the other by Pythagoras, in each way that is open where both are even:
            // Timofeev's `sin(5x)/(5 cos(x)^2 + 9 sin(x)^2)^(5/2)` is a polynomial in the
            // cosine times the sine over `(9 - 4 cos(x)^2)^(5/2)`, `u = cos(x)`'s at once, and
            // handed on with the two functions under the root it ran the budget out.
            foreach (var spelling in RadicandsInOneFunction(cancelled, sine, cosine))
                if (Integration.ComputeIndefiniteIntegral(spelling, x, integrateByParts: false) is { } answer)
                    return answer;
            return null;
        }

        /// <summary>
        /// <paramref name="expr"/> with every fractional-power base that is a polynomial in
        /// <paramref name="sine"/> and <paramref name="cosine"/> together, one of them in even
        /// powers only, written in the other; the spelling in the cosine first and then in
        /// the sine where both are open, and <paramref name="expr"/> itself where there is
        /// nothing to write.
        /// </summary>
        private static IEnumerable<Entity> RadicandsInOneFunction(Entity expr, Entity sine, Entity cosine)
        {
            var bases = expr.Nodes.Where(node => node is Powf(var @base, Number.Rational r) && r is not Number.Integer
                && @base.ContainsNode(sine) && @base.ContainsNode(cosine)).Select(node => ((Powf)node).Base).Distinct().ToList();
            if (bases.Count == 0)
            {
                yield return expr;
                yield break;
            }
            var s = Variable.CreateUnique(expr, "s_rad");
            var c = Variable.CreateUnique(expr, "c_rad");
            Entity? InTheOther(Entity @base, Entity.Variable even, Entity.Variable other, Entity evenSquaredAs)
            {
                var inBoth = @base.Substitute(sine, s).Substitute(cosine, c).Expand();
                if (!TreeAnalyzer.TryGetPolynomial(inBoth, even, out var read)
                    || !read.All(pair => pair.Key.IsEven && pair.Key.Sign >= 0 && TreeAnalyzer.TryGetPolynomial(pair.Value, other, out _)))
                    return null;
                Entity written = Number.Integer.Zero;
                foreach (var pair in read)
                {
                    var half = pair.Key.ToInt32Checked() / 2;
                    written += pair.Value * (half == 0 ? Number.Integer.One : MathS.Pow(evenSquaredAs, half));
                }
                return written.Expand().InnerSimplified.Substitute(s, sine).Substitute(c, cosine);
            }
            var any = false;
            foreach (var (even, other, evenSquaredAs) in new[] { (s, c, 1 - MathS.Sqr(c)), (c, s, 1 - MathS.Sqr(s)) })
            {
                var respelled = new Dictionary<Entity, Entity>();
                foreach (var @base in bases)
                    if (InTheOther(@base, even, other, evenSquaredAs) is { } written && written != @base)
                        respelled[@base] = written;
                if (respelled.Count == 0)
                    continue;
                any = true;
                yield return expr.Replace(node => node is Powf(var @base, Number.Rational r) && r is not Number.Integer && respelled.TryGetValue(@base, out var written)
                    ? MathS.Pow(written, r) : node);
            }
            if (!any)
                yield return expr;
        }

        /// <summary>
        /// <paramref name="expr"/>, whose trigonometric functions are of <paramref name="theta"/>
        /// and of <c>2 theta</c>, rewritten in <c>sin(2 theta)</c> and <c>cos(2 theta)</c> alone
        /// — or <see langword="null"/> where it is not even in <paramref name="theta"/>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sin^2 = (1 - C)/2</c>, <c>cos^2 = (1 + C)/2</c> and <c>sin cos = S/2</c>, with
        /// <c>S</c> and <c>C</c> the sine and cosine of the doubled argument; so a monomial
        /// <c>sin^p cos^q</c> is a rational function of <c>S</c> and <c>C</c> exactly when
        /// <c>p + q</c> is even, negative powers included, and an expression built from such
        /// monomials by sums, products and quotients is one too. Going up to the doubled argument
        /// where that holds gives polynomials of half the degree the other direction does:
        /// <c>sec(2t)/(1 + sec(t)^2 + 3 tan(t))</c> is answered in a third of a second written in
        /// <c>2t</c> and declined after five written in <c>t</c>.
        /// </para>
        /// </remarks>
        private static Entity? TryRaiseToTheDoubledArgument(Entity expr, Entity.Variable x, Entity theta)
        {
            var sine = MathS.Sin(theta);
            var cosine = MathS.Cos(theta);
            var doubledSine = MathS.Sin((2 * theta).InnerSimplified);
            var doubledCosine = MathS.Cos((2 * theta).InnerSimplified);

            // A monomial sin^p cos^q of the small argument, as a function of the doubled one:
            // (sin cos)^k times an even power of whichever is left, with k the smaller of the two
            // exponents so that the leftover power is p - q or q - p, even by the parity check.
            Entity? Monomial(int p, int q)
            {
                if ((p + q) % 2 != 0)
                    return null;
                // Either exponent will do for k, since p - q is even; the one that leaves the
                // smaller exponents behind gives the tidier form -- sec^2 as 2/(1 + C) rather
                // than as 2(1 - C)/S^2.
                static int Size(int k, int p, int q) => System.Math.Abs(k) + System.Math.Abs(p - k) + System.Math.Abs(q - k);
                var k = Size(p, p, q) <= Size(q, p, q) ? p : q;
                Entity result = k == 0 ? Number.Integer.One : MathS.Pow(doubledSine / 2, k);
                if (p != k)
                    result *= MathS.Pow((1 - doubledCosine) / 2, (p - k) / 2);
                if (q != k)
                    result *= MathS.Pow((1 + doubledCosine) / 2, (q - k) / 2);
                return result;
            }

            Entity? Raise(Entity node)
            {
                if (!node.ContainsNode(x))
                    return node;
                switch (node)
                {
                    case Sumf(var a, var b):
                        return Raise(a) is { } summandA && Raise(b) is { } summandB ? summandA + summandB : null;
                    case Minusf(var a, var b):
                        return Raise(a) is { } ma && Raise(b) is { } mb ? ma - mb : null;
                    case Divf(var a, var b):
                        return Raise(a) is { } da && Raise(b) is { } db ? da / db : null;
                    case Mulf:
                    {
                        // The sine and cosine powers of the small argument gathered across the
                        // product, so that sin * cos pairs off; every other factor on its own.
                        int p = 0, q = 0;
                        Entity rest = Number.Integer.One;
                        foreach (var factor in Mulf.LinearChildren(node))
                        {
                            var (@base, power) = factor is Powf(var pb, Number.Integer pe) && pe.EInteger.CanFitInInt32()
                                ? (pb, pe.EInteger.ToInt32Unchecked())
                                : (factor, 1);
                            if (@base == sine) p += power;
                            else if (@base == cosine) q += power;
                            else if (@base is Tanf(var ta) && ta == theta) { p += power; q -= power; }
                            else if (@base is Cotanf(var ca) && ca == theta) { p -= power; q += power; }
                            else if (@base is Secantf(var sa) && sa == theta) q -= power;
                            else if (@base is Cosecantf(var csa) && csa == theta) p -= power;
                            else if (Raise(factor) is { } raised) rest *= raised;
                            else return null;
                        }
                        return Monomial(p, q) is { } monomial ? rest * monomial : null;
                    }
                    case Powf(var @base, Number.Integer exponent) when exponent.EInteger.CanFitInInt32():
                    {
                        var n = exponent.EInteger.ToInt32Unchecked();
                        if (@base == sine) return Monomial(n, 0);
                        if (@base == cosine) return Monomial(0, n);
                        if (@base is Tanf(var ta) && ta == theta) return Monomial(n, -n);
                        if (@base is Cotanf(var ca) && ca == theta) return Monomial(-n, n);
                        if (@base is Secantf(var sa) && sa == theta) return Monomial(0, -n);
                        if (@base is Cosecantf(var csa) && csa == theta) return Monomial(-n, 0);
                        return Raise(@base) is { } rb ? MathS.Pow(rb, exponent) : null;
                    }
                    case Sinf(var a) when a == theta: return null;
                    case Cosf(var a) when a == theta: return null;
                    case Tanf(var a) when a == theta: return Monomial(1, -1);
                    case Cotanf(var a) when a == theta: return Monomial(-1, 1);
                    case Secantf(var a) when a == theta: return null;
                    case Cosecantf(var a) when a == theta: return null;
                    // Of the doubled argument, everything in its sine and cosine, which is what
                    // the rules below read.
                    case Tanf(var a) when a == doubledSine.DirectChildren.First(): return doubledSine / doubledCosine;
                    case Cotanf(var a) when a == doubledSine.DirectChildren.First(): return doubledCosine / doubledSine;
                    case Secantf(var a) when a == doubledSine.DirectChildren.First(): return 1 / doubledCosine;
                    case Cosecantf(var a) when a == doubledSine.DirectChildren.First(): return 1 / doubledSine;
                    default:
                        // A function of the doubled argument, or anything else, stays as it is;
                        // a bare sine or cosine of the small argument is odd and was declined above.
                        return node.DirectChildren.Any(child => child.ContainsNode(x) && Raise(child) is null) ? null : node;
                }
            }

            return Raise(expr);
        }

        /// <summary>
        /// <paramref name="numerator"/> over <paramref name="denominator"/> with every factor
        /// that appears in both, to a whole power, divided out by the smaller of the two powers.
        /// Factors are compared as written, which is what a rewriting that built both sides from
        /// the same pieces needs and no more.
        /// </summary>
        private static Entity CancelCommonFactors(Entity numerator, Entity denominator)
        {
            static Dictionary<Entity, int> Powers(Entity side)
            {
                var powers = new Dictionary<Entity, int>();
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    // Nested whole powers folded, so that `((2t + 1)^2)^2` and `(2t + 1)^4` are
                    // one factor: a substitution that squares what it built leaves the first.
                    var @base = factor;
                    var power = 1;
                    while (@base is Powf(var inner, Number.Integer e) && e.EInteger.CanFitInInt32())
                    {
                        power *= e.EInteger.ToInt32Unchecked();
                        @base = inner;
                    }
                    powers[@base] = powers.TryGetValue(@base, out var already) ? already + power : power;
                }
                return powers;
            }
            static Entity Rebuild(Dictionary<Entity, int> powers)
            {
                Entity built = Number.Integer.One;
                foreach (var pair in powers)
                {
                    if (pair.Value == 0)
                        continue;
                    var factor = pair.Value == 1 ? pair.Key : MathS.Pow(pair.Key, pair.Value);
                    built = built == Number.Integer.One ? factor : built * factor;
                }
                return built;
            }

            var above = Powers(numerator);
            var below = Powers(denominator);
            foreach (var pair in above.ToList())
                if (below.TryGetValue(pair.Key, out var underneath) && pair.Value > 0 && underneath > 0)
                {
                    var shared = System.Math.Min(pair.Value, underneath);
                    above[pair.Key] = pair.Value - shared;
                    below[pair.Key] = underneath - shared;
                }
            var top = Rebuild(above);
            var bottom = Rebuild(below);
            return bottom == Number.Integer.One ? top : top / bottom;
        }

        /// <summary>
        /// The largest multiple <see cref="SolveByUnifyingTrigonometricArguments"/> expands;
        /// past it the Chebyshev polynomials are longer than any answer they lead to.
        /// </summary>
        private const int MaximumUnifiedMultiple = 6;

        /// <summary>
        /// The largest degree, in the sine and cosine of the common argument, that the rewriting
        /// is allowed to produce anywhere in the integrand.
        /// </summary>
        private const int MaximumUnifiedDegree = 16;

        /// <summary>
        /// An upper bound on the degree in <c>sin(g x)</c> and <c>cos(g x)</c> that rewriting
        /// <paramref name="expr"/> to the common slope <paramref name="common"/> produces: a
        /// function of <c>n g x</c> is degree <c>n</c>, a product adds, a power multiplies, a sum
        /// or quotient takes the larger side.
        /// </summary>
        private static int ExpandedDegree(Entity expr, Entity.Variable x, ERational common)
        {
            if (!expr.ContainsNode(x))
                return 0;
            switch (expr)
            {
                case Sumf or Minusf or Divf:
                    return expr.DirectChildren.Max(child => ExpandedDegree(child, x, common));
                case Mulf:
                    return expr.DirectChildren.Sum(child => ExpandedDegree(child, x, common));
                case Powf(var @base, Number.Integer power) when power.EInteger.CanFitInInt32():
                    return ExpandedDegree(@base, x, common) * System.Math.Abs(power.EInteger.ToInt32Unchecked());
                default:
                    if (TrigonometricArgument(expr) is { } argument
                        && TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out _)
                        && slope.Evaled is Number.Rational rational)
                    {
                        var multiple = rational.ERational.Divide(common).ToLowestTerms();
                        return multiple.Numerator.Abs().CanFitInInt32() ? multiple.Numerator.Abs().ToInt32Unchecked() : int.MaxValue / 4;
                    }
                    return 1;
            }
        }

        private static Entity? TrigonometricArgument(Entity node) => node switch
        {
            Sinf(var a) => a,
            Cosf(var a) => a,
            Tanf(var a) => a,
            Cotanf(var a) => a,
            Secantf(var a) => a,
            Cosecantf(var a) => a,
            _ => null
        };

        /// <summary>
        /// <c>sin(n t)</c> and <c>cos(n t)</c> as polynomials in <paramref name="sine"/> and
        /// <paramref name="cosine"/>, by the Chebyshev recurrences.
        /// </summary>
        private static (Entity Sine, Entity Cosine) SineAndCosineOfAMultiple(int n, Entity sine, Entity cosine)
        {
            // T_0 = 1, T_1 = c, T_(k+1) = 2c T_k - T_(k-1); U_0 = 1, U_1 = 2c, likewise.
            Entity tPrevious = 1, tCurrent = cosine;
            Entity uPrevious = 1, uCurrent = 2 * cosine;
            if (n == 0)
                return (0, 1);
            for (var k = 1; k < n; k++)
            {
                (tPrevious, tCurrent) = (tCurrent, (2 * cosine * tCurrent - tPrevious).InnerSimplified);
                (uPrevious, uCurrent) = (uCurrent, (2 * cosine * uCurrent - uPrevious).InnerSimplified);
            }
            // sin(n t) = sin(t) U_(n-1)(cos t): after the loop uPrevious is U_(n-1).
            return ((sine * uPrevious).InnerSimplified, tCurrent);
        }

        /// <summary>
        /// <c>N B^r</c>, for a fractional <c>r</c> and an <c>N</c> and a <c>B</c> that are
        /// polynomials in <paramref name="x"/> and the functions of it in them, answered as
        /// <c>P(x) B^(r + 1)</c> for a polynomial <c>P</c> where there is one: the derivative of
        /// that is <c>B^r (P' B + (r + 1) P B')</c>, and <c>P' B + (r + 1) P B' = N</c> is a linear
        /// system in the coefficients of <c>P</c> once the functions of <c>x</c> are taken for
        /// indeterminates.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Bronstein's <c>(5x^2 + 3 (e^x + x)^(1/3) + e^x (3x + 2x^2))/(x (e^x + x)^(1/3))</c> is
        /// <c>3/x + (5x + e^x (2x + 3))/(e^x + x)^(1/3)</c>, and the second is
        /// <c>3x (e^x + x)^(2/3)</c>: with <c>P = c_0 + c_1 x</c> and <c>r = -1/3</c>,
        /// <c>c_1 (e^x + x) + (2/3)(c_0 + c_1 x)(e^x + 1) = 5x + e^x (2x + 3)</c> is
        /// <c>c_1 = 3</c>, <c>c_0 = 0</c>. Nothing else read it: the substitution
        /// <c>u = e^x + x</c> wants <c>1 + e^x</c> beside the root and finds <c>5x + e^x (2x + 3)</c>.
        /// </para>
        /// <para>
        /// The degree of <c>P</c> is the degree of <c>N</c> in <c>x</c>, the functions of <c>x</c>
        /// held constant, and one more; the system is exact, over the rationals, and its
        /// solution is checked by differentiating back at sampled points, since an identity
        /// between two functions taken for independent indeterminates -- <c>e^x</c> and
        /// <c>e^(2x)</c>, say -- can fail to be found and cannot be found wrongly, but a
        /// derivative the reader did not expect can. Closed, and volunteered at any depth.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByAPolynomialTimesAPowerOfTheBase(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            Entity? radicalBase = null;
            Number.Rational? exponent = null;
            Entity rest = Number.Integer.One;
            Entity constantBelow = Number.Integer.One;
            foreach (var (side, isBelow) in new[] { (numerator, false), (denominator, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is Powf(var @base, Number.Rational power) && power is not Number.Integer && @base.ContainsNode(x))
                    {
                        if (radicalBase is not null)
                            return null;
                        radicalBase = @base;
                        exponent = isBelow ? Number.Rational.Create(power.ERational.Negate()) : power;
                        continue;
                    }
                    if (!factor.ContainsNode(x))
                    {
                        if (isBelow) constantBelow = constantBelow * factor;
                        else rest = rest * factor;
                        continue;
                    }
                    if (isBelow || HasARadicalOf(factor, x))
                        return null;
                    rest = rest * factor;
                }
            if (radicalBase is null || exponent is null || HasARadicalOf(radicalBase, x)
                || !radicalBase.Nodes.Any(node => node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf or Powf(_, Number.Integer))))
                return null;

            // The degree of N in x with the functions of x held constant.
            var atoms = new Dictionary<Entity, Entity.Variable>();
            var named = expr;
            Entity WithAtoms(Entity e) => e.Replace(node =>
            {
                if (!node.ContainsNode(x) || node is Variable or Sumf or Minusf or Mulf or Divf || node is Powf(_, Number.Integer { IsNegative: false }))
                    return node;
                if (!atoms.TryGetValue(node, out var atom))
                {
                    atom = Variable.CreateUnique(named, "atom");
                    named = named + atom;
                    atoms[node] = atom;
                }
                return atom;
            });
            var n = WithAtoms(rest);
            if (!TreeAnalyzer.TryGetPolynomial(n, x, out var nRead) || nRead.Keys.Any(k => !k.CanFitInInt32()))
                return null;
            var degree = (nRead.Count == 0 ? 0 : nRead.Keys.Max()!.ToInt32Unchecked()) + 1;
            if (degree > 4)
                return null;

            // P' B + (r + 1) P B' - N, linear in the unknowns; written with the functions of x
            // as indeterminates, as one polynomial, whose every coefficient must vanish.
            var unknowns = new List<Entity.Variable>();
            for (var k = 0; k <= degree; k++)
            {
                var unknown = Variable.CreateUnique(named, "c" + k);
                named = named + unknown;
                unknowns.Add(unknown);
            }
            Entity polynomial = Number.Integer.Zero;
            for (var k = 0; k <= degree; k++)
                polynomial = polynomial + unknowns[k] * (k == 0 ? Number.Integer.One : k == 1 ? x : MathS.Pow(x, k));
            var rPlusOne = Number.Rational.Create(exponent.ERational.Add(ERational.One));
            var identity = polynomial.Differentiate(x) * radicalBase + rPlusOne * polynomial * radicalBase.Differentiate(x) - rest / constantBelow;
            var (top, bottom) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(WithAtoms(Functions.PartialFractions.Bare(identity))));
            if (bottom.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(bottom, x, out _))
                return null;
            var variables = top.Vars.Where(v => !unknowns.Contains(v)).OrderBy(v => v.Name, System.StringComparer.Ordinal).ToList();
            if (variables.Count == 0 || variables.Count > MultivariatePolynomial.MaxVariables)
                return null;
            var indices = new Dictionary<Variable, int>();
            for (var i = 0; i < variables.Count; i++)
                indices[variables[i]] = i;
            // top = E_0 + sum_k c_k E_k.
            Entity AtUnit(int which)
            {
                var e = top;
                for (var k = 0; k <= degree; k++)
                    e = e.Substitute(unknowns[k], k == which ? Number.Integer.One : Number.Integer.Zero);
                return Functions.PartialFractions.Bare(e);
            }
            if (MultivariatePolynomial.TryParse(AtUnit(-1), indices) is not { } constantPart)
                return null;
            var columns = new List<MultivariatePolynomial>();
            for (var k = 0; k <= degree; k++)
            {
                if (MultivariatePolynomial.TryParse(AtUnit(k), indices) is not { } column)
                    return null;
                columns.Add(column.Subtract(constantPart));
            }
            var monomials = columns.SelectMany(column => column.Terms.Select(term => term.Key)).Concat(constantPart.Terms.Select(term => term.Key)).Distinct().ToList();
            var matrix = new Entity[monomials.Count][];
            var rhs = new Entity[monomials.Count];
            for (var row = 0; row < monomials.Count; row++)
            {
                matrix[row] = new Entity[degree + 1];
                for (var k = 0; k <= degree; k++)
                    matrix[row][k] = columns[k].Terms.FirstOrDefault(term => term.Key == monomials[row]).Value is { } c ? Number.Rational.Create(c) : Number.Integer.Zero;
                rhs[row] = constantPart.Terms.FirstOrDefault(term => term.Key == monomials[row]).Value is { } d ? Number.Rational.Create(d.Negate()) : Number.Integer.Zero;
            }
            if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                return null;
            Entity p = Number.Integer.Zero;
            for (var k = 0; k <= degree; k++)
                if (values[k].Evaled is Number.Complex { IsZero: false })
                    p = p + values[k] * (k == 0 ? Number.Integer.One : k == 1 ? x : MathS.Pow(x, k));
            if (p == Number.Integer.Zero)
                return null;
            var answer = (p * MathS.Pow(radicalBase, rPlusOne)).InnerSimplified;
            // Checked as a fact about the function, since two functions taken for
            // independent indeterminates may not be.
            if (!Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// An integrand <c>e^h R</c>, with <c>R</c> rational in <c>x</c> and <c>h</c> rational
        /// in <c>x</c> or absent, integrated by the ansatz <c>F = e^h N/D</c>: <c>D</c> read
        /// off the denominator of <c>R</c>, <c>N</c> a polynomial of unknown coefficients, and
        /// <c>F' = e^h R</c> a linear system in them.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>e^x x/(1 + x)^2</c> is <c>(e^x/(1 + x))'</c>; <c>e^(x^2)(1 + 2x^2)</c> is
        /// <c>(x e^(x^2))'</c>; <c>(4x^5 - 1)/(1 + x + x^5)^2</c> is <c>(-x/(1 + x + x^5))'</c>.
        /// None had an antiderivative: the first two are not a polynomial times an exponential,
        /// which is the shape by parts reads, and the third has a denominator nothing factors.
        /// Each is the derivative of something of the same shape, and that is what is looked
        /// for -- Liouville's theorem says the elementary antiderivative of <c>e^h R</c>, where
        /// there is one, is <c>e^h</c> times a rational function, so an ansatz that fails here
        /// fails because there is no such antiderivative and not because the shape was wrong.
        /// For <c>h = 0</c> this is the rational part of the Hermite reduction, with the
        /// logarithmic part required to vanish; a denominator with a repeated factor and a
        /// logarithmic part beside it is left to the splits, as before.
        /// </para>
        /// <para>
        /// <b>Which <c>D</c>.</b> Differentiating raises the multiplicity of every factor of the
        /// denominator by one, so <c>D</c> is the denominator of <c>R</c> with each factor's
        /// written power lowered by one, and then the denominator itself, and <c>1</c> where the
        /// denominator is <c>1</c>. With <c>h = p/q</c> the identity is
        /// </para>
        /// <code>
        ///     ((N' D - N D') q^2 + (p' q - p q') N D) D_R  =  N_R D^2 q^2
        /// </code>
        /// <para>
        /// a polynomial identity in <c>x</c>, linear in the coefficients of <c>N</c>, solved by
        /// the same elimination the symbolic partial-fraction split uses and checked the same way
        /// before anything is returned: at sampled points with every symbol pinned. The degree
        /// of <c>N</c> is bounded by the degrees in that identity, with a little to spare;
        /// an unknown the system does not need is zero.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByExponentialAnsatz(Entity expr, Entity.Variable x)
        {
            // A sum whose terms share one exponential is read whole -- `e^(x^2) + 2x^2 e^(x^2)`
            // is `(x e^(x^2))'` and neither term is elementary on its own, so splitting the sum
            // first, which linearity does, loses it.
            Entity? exponent = null;
            Entity rest = 0;
            foreach (var term in Sumf.LinearChildren(expr))
            {
                if (ReadOneExponentialTimesTheRest(term, x) is not var (h, r) || h is null)
                    return null;
                if (exponent is null)
                    exponent = h;
                else if (exponent != h)
                    return null;
                rest += r;
            }
            return exponent is null || IntegrateByAnsatz(exponent, rest, x) is not { } answer ? null : InTheBaseWritten(answer, expr, x);
        }

        /// <summary>
        /// <paramref name="answer"/> with the exponential written in the base the integrand
        /// wrote it in: the ansatz reads <c>F^u</c> as <c>e^(u ln F)</c> and builds its answer
        /// on that, and <c>F^(a + b x + c x^3)/ln(F)</c> is the answer to give for Rubi's
        /// <c>F^(a + b x + c x^3)(b + 3 c x^2)</c>, not <c>e^((a + b x + c x^3) ln F)/ln(F)</c>.
        /// </summary>
        private static Entity InTheBaseWritten(Entity answer, Entity integrand, Entity.Variable x)
        {
            var written = new Dictionary<Entity, Entity>();
            foreach (var node in integrand.Nodes)
                if (node is Powf(var @base, var power) && @base != MathS.e && !@base.ContainsNode(x) && power.ContainsNode(x) && power is not Number)
                {
                    written[(power * MathS.Ln(@base)).InnerSimplified] = node;
                    written[(-power * MathS.Ln(@base)).InnerSimplified] = MathS.Pow(@base, -power);
                }
            return written.Count == 0 ? answer
                : answer.Replace(node => node is Powf(var e, var exponent) && e == MathS.e && written.TryGetValue(exponent, out var asWritten) ? asWritten : node);
        }

        /// <summary>
        /// <c>e^(a x)</c> times a rational function of <c>sin(x)</c> and <c>cos(x)</c>, closed by
        /// an ansatz in the half-angle tangent: <c>F = e^(a x) P(t)/Q(t)</c> with <c>t = tan(x/2)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Timofeev's <c>e^x (1 - sin(x))/(1 - cos(x))</c> had no antiderivative, and it is
        /// <c>-e^x cot(x/2)</c>. Nothing here reads it: the exponential times a trigonometric
        /// rule wants a polynomial in sine and cosine, the half-angle substitution wants no
        /// exponential, and by parts goes round in a circle. Under <c>t = tan(x/2)</c> the
        /// trigonometric part is a rational function <c>r(t)</c>, and the integrand is
        /// <c>e^(a x) r(t)</c> with <c>dt/dx = (1 + t^2)/2</c>; differentiating the ansatz,
        /// </para>
        /// <code>
        ///     F' = e^(a x) [a P/Q + (P'Q - P Q') (1 + t^2)/(2 Q^2)]
        /// </code>
        /// <para>
        /// and asking that it equal <c>e^(a x) n(t)/d(t)</c> is one polynomial identity,
        /// <c>[a P Q + (P'Q - P Q')(1 + t^2)/2] d = n Q^2</c>, linear in the coefficients of
        /// <c>P</c>. <c>Q</c> is tried from <c>d</c>'s written factors, as the exponential ansatz
        /// tries its denominators; the identity is exact, so a solution is an answer and the
        /// absence of one a decline. Timofeev's has <c>r = (1 - t)^2/(2 t^2)</c>, <c>Q = t</c>,
        /// <c>P = -1</c>.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByExponentialHalfAngleAnsatz(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            if (ReadOneExponentialTimesTheRest(expr, x) is not var (exponent, rest) || exponent is null)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(exponent, x, out var a, out _) || a.ContainsNode(x) || a.Evaled is Number.Complex { IsZero: true })
                return null;
            // The rest is built from sin(x) and cos(x) by the field operations, and no other
            // function of x: written over the two, then in the half-angle tangent.
            var sine = MathS.Sin(x);
            var cosine = MathS.Cos(x);
            var overTheTwo = rest.Replace(node => node switch
            {
                Tanf(var arg) when arg == x => sine / cosine,
                Cotanf(var arg) when arg == x => cosine / sine,
                Secantf(var arg) when arg == x => 1 / cosine,
                Cosecantf(var arg) when arg == x => 1 / sine,
                _ => node
            });
            if (overTheTwo.Nodes.Any(node => node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf)
                                              && !(node is Powf(_, Number.Integer))))
                return null;
            if (overTheTwo.Nodes.Any(node => node is Sinf(var arg) && arg != x || node is Cosf(var arg2) && arg2 != x))
                return null;

            var t = Variable.CreateUnique(expr, "t_half");
            var tSquared = MathS.Sqr(t);
            var inT = Functions.SingleQuotient.Combine(
                overTheTwo.Substitute(sine, 2 * t / (1 + tSquared)).Substitute(cosine, (1 - tSquared) / (1 + tSquared))).Simplify();
            if (inT is Providedf(var inner, _))
                inT = inner;
            if (inT.ContainsNode(x))
                return null;
            var (n, d) = Functions.SingleQuotient.Of(inT);
            if (!TreeAnalyzer.TryGetPolynomial(n, t, out var nRead) || !TreeAnalyzer.TryGetPolynomial(d, t, out var dRead))
                return null;
            var degreeN = nRead.Count == 0 ? 0 : nRead.Keys.Max()!.ToInt32Checked();
            var degreeD = dRead.Count == 0 ? 0 : dRead.Keys.Max()!.ToInt32Checked();
            if (degreeN > MaximumAnsatzDegree || degreeD > MaximumAnsatzDegree)
                return null;

            var half = Number.Rational.Create(1, 2);
            foreach (var q in CandidateDenominators(d, t))
            {
                var degreeQ = TreeAnalyzer.TryGetPolynomial(q, t, out var qRead) && qRead.Count > 0
                    ? qRead.Keys.Max()!.ToInt32Checked() : 0;
                // The bracket has degree deg P + max(deg Q + 1, ...) against n Q^2 / d.
                var degreeP = System.Math.Max(degreeQ, degreeQ + degreeN - degreeD + 2);
                if (degreeP > MaximumAnsatzDegree)
                    continue;
                var qPrime = q.Differentiate(t);
                var columns = new List<Dictionary<EInteger, Entity>>();
                var failed = false;
                for (var k = 0; k <= degreeP; k++)
                {
                    Entity tk = k == 0 ? Number.Integer.One : k == 1 ? t : MathS.Pow(t, k);
                    Entity tkPrime = k == 0 ? Number.Integer.Zero : k == 1 ? Number.Integer.One : k * MathS.Pow(t, k - 1);
                    var bracket = a * tk * q + (tkPrime * q - tk * qPrime) * (1 + tSquared) * half;
                    if (!TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare((bracket * d).Expand()), t, out var column))
                    {
                        failed = true;
                        break;
                    }
                    columns.Add(column);
                }
                if (failed)
                    continue;
                if (!TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare((n * MathS.Sqr(q)).Expand()), t, out var target))
                    continue;
                var monomials = columns.SelectMany(column => column.Keys).Concat(target.Keys).Distinct().OrderBy(k => k).ToList();
                var matrix = new Entity[monomials.Count][];
                var rhs = new Entity[monomials.Count];
                for (var row = 0; row < monomials.Count; row++)
                {
                    matrix[row] = new Entity[columns.Count];
                    for (var k = 0; k < columns.Count; k++)
                        matrix[row][k] = columns[k].TryGetValue(monomials[row], out var entry) ? entry : Number.Integer.Zero;
                    rhs[row] = target.TryGetValue(monomials[row], out var wanted) ? wanted : Number.Integer.Zero;
                }
                if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                    continue;
                Entity polynomial = Number.Integer.Zero;
                for (var k = 0; k < values.Length; k++)
                {
                    var value = values[k].InnerSimplified;
                    if (value.Evaled is Number.Complex { IsZero: true })
                        continue;
                    polynomial += value * (k == 0 ? Number.Integer.One : k == 1 ? t : MathS.Pow(t, k));
                }
                var tangent = MathS.Tan(x / 2);
                var answer = (MathS.Pow(MathS.e, exponent) * polynomial / q).Substitute(t, tangent);
                // The solve can answer a system it only nearly satisfies; the derivative decides.
                if (!Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                    continue;
                return answer.InnerSimplified;
            }
            return null;
        }

        /// <summary>
        /// An exponential times a rational function of <c>x</c> and <c>ln(x)</c>, with the
        /// logarithm allowed in the exponent too, closed by an ansatz
        /// <c>F = e^h P(x, L)/(D(x) L^k)</c> with <c>L = ln(x)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Hearn's <c>(-1 + (1 - x) ln(x))/(e^x ln(x)^2)</c> is <c>(x e^(-x)/ln(x))'</c> and Hebisch's
        /// <c>e^(x + 1/ln(x)) (-1 + (1 + x) ln(x)^2)/ln(x)^2</c> is <c>(x e^(x + 1/ln(x)))'</c>; neither
        /// had an antiderivative, and neither is reached by parts or by any substitution,
        /// since the logarithm is not a whole subtree to replace. They are the exponential
        /// ansatz one level up the tower: <c>x</c> and <c>ln(x)</c> are algebraically
        /// independent, so with <c>L</c> standing for <c>ln(x)</c> and <c>L' = 1/x</c>, the
        /// derivative of the ansatz divided by <c>e^h</c> is a rational function of <c>x</c> and
        /// <c>L</c>, and asking it to equal the integrand's is one polynomial identity in the
        /// two -- linear in the coefficients of <c>P</c>, one equation per monomial
        /// <c>x^i L^j</c>. The identity is exact, so a solution is an answer and its absence a
        /// decline; the derivative of what comes out is checked against the integrand at
        /// sampled points all the same.
        /// </para>
        /// <para>
        /// The denominator is tried from the integrand's: its <c>x</c>-part as the exponential
        /// ansatz tries its denominators, times <c>L^k</c> for every <c>k</c> from zero up to
        /// the written power, smallest first so that the answer carries no common factor. Degrees are bounded like the other
        /// ansatz's, and the columns are built one monomial at a time by differentiating the
        /// candidate and clearing one common denominator, so nothing here is expanded with
        /// unknowns in it.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByLogarithmTowerAnsatz(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            var logarithm = MathS.Ln(x);
            if (!expr.ContainsNode(logarithm))
                return null;
            if (ReadOneExponentialTimesTheRest(expr, x) is not var (exponent, rest) || exponent is null)
                return null;

            // Rational in x and L, and nothing else of x, on both sides.
            var L = Variable.CreateUnique(expr, "L_tower");
            var restInL = rest.Substitute(logarithm, L);
            var exponentInL = exponent.Substitute(logarithm, L);
            static bool IsRationalInBoth(Entity e, Entity.Variable x, Entity.Variable L)
                => e.Nodes.All(node => !(node.ContainsNode(x) || node.ContainsNode(L))
                    || node is Variable or Sumf or Minusf or Mulf or Divf
                    || node is Powf(_, Number.Integer));
            if (!IsRationalInBoth(restInL, x, L) || !IsRationalInBoth(exponentInL, x, L))
                return null;
            if (!exponentInL.ContainsNode(x) && !exponentInL.ContainsNode(L))
                return null;

            var (above, below) = Functions.SingleQuotient.Of(restInL.InnerSimplified);
            if (!TryReadInBoth(above, x, L, out var aboveRead) || !TryReadInBoth(below, x, L, out var belowRead))
                return null;
            var degreeAboveX = aboveRead.Keys.Max(k => k.Item1);
            var degreeAboveL = aboveRead.Keys.Max(k => k.Item2);
            var degreeBelowX = belowRead.Keys.Max(k => k.Item1);
            var degreeBelowL = belowRead.Keys.Max(k => k.Item2);
            if (degreeAboveX > MaximumAnsatzDegree || degreeBelowX > MaximumAnsatzDegree
                || degreeAboveL > MaximumTowerDegree || degreeBelowL > MaximumTowerDegree)
                return null;

            // The denominator's x-part and L-part, read off the written factors.
            Entity xPart = Number.Integer.One;
            var lPower = 0;
            foreach (var factor in Mulf.LinearChildren(below))
            {
                if (factor == L) { lPower += 1; continue; }
                if (factor is Powf(var b, Number.Integer e) && b == L && e.EInteger.CanFitInInt32()) { lPower += e.EInteger.ToInt32Unchecked(); continue; }
                if (factor.ContainsNode(L))
                    return null;   // L inside a written factor with x: not a shape this reads
                xPart = xPart * factor;
            }

            var hPrime = exponentInL.Differentiate(x) + exponentInL.Differentiate(L) / x;
            var degreePX = System.Math.Max(degreeBelowX, degreeBelowX + degreeAboveX - degreeBelowX + 2);
            var degreePL = System.Math.Max(lPower, degreeAboveL + 1);
            if (degreePX > MaximumAnsatzDegree || degreePL > MaximumTowerDegree)
                return null;

            // The smallest power of L first, so that the answer found is the one without a
            // common factor of L above and below.
            var lPowers = new List<int>();
            for (var k = 0; k <= lPower; k++)
                lPowers.Add(k);
            foreach (var d in CandidateDenominators(xPart, x))
                foreach (var k in lPowers)
                {
                    var denominator = (k == 0 ? d : d * MathS.Pow(L, k));
                    // The derivative of e^h x^i L^j / (d L^k), over e^h, has denominator dividing
                    // x d^2 L^(k+1) times whatever h' brought; clearing by that and the
                    // integrand's denominator gives polynomials on both sides.
                    var (hAbove, hBelow) = Functions.SingleQuotient.Of(hPrime.InnerSimplified);
                    var clearing = x * MathS.Sqr(denominator) * L * hBelow;
                    var columns = new List<Dictionary<(int, int), Entity>>();
                    var monomialsOfP = new List<(int, int)>();
                    var failed = false;
                    for (var i = 0; i <= degreePX && !failed; i++)
                        for (var j = 0; j <= degreePL; j++)
                        {
                            // The candidate with its powers of L folded into one, so that its
                            // derivative is a Laurent monomial and not a quotient rule on L/L.
                            Entity candidate = MathS.Pow(x, i) * (j - k == 0 ? Number.Integer.One : MathS.Pow(L, j - k)) / d;
                            var derivative = hPrime * candidate + candidate.Differentiate(x) + candidate.Differentiate(L) / x;
                            var cleared = Functions.PartialFractions.Bare(
                                Functions.SingleQuotient.Combine(derivative * clearing * below).Simplify().Expand());
                            if (!TryReadInBoth(cleared, x, L, out var column))
                            {
                                failed = true;
                                break;
                            }
                            columns.Add(column);
                            monomialsOfP.Add((i, j));
                        }
                    if (failed)
                        continue;
                    if (!TryReadInBoth(Functions.PartialFractions.Bare((above * clearing).Simplify().Expand()), x, L, out var target))
                        continue;

                    var monomials = columns.SelectMany(c => c.Keys).Concat(target.Keys).Distinct().OrderBy(m => m).ToList();
                    var matrix = new Entity[monomials.Count][];
                    var rhs = new Entity[monomials.Count];
                    for (var row = 0; row < monomials.Count; row++)
                    {
                        matrix[row] = new Entity[columns.Count];
                        for (var c = 0; c < columns.Count; c++)
                            matrix[row][c] = columns[c].TryGetValue(monomials[row], out var entry) ? entry : Number.Integer.Zero;
                        rhs[row] = target.TryGetValue(monomials[row], out var wanted) ? wanted : Number.Integer.Zero;
                    }
                    if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                        continue;
                    Entity numerator = Number.Integer.Zero;
                    for (var c = 0; c < values.Length; c++)
                    {
                        var value = values[c].InnerSimplified;
                        if (value.Evaled is Number.Complex { IsZero: true })
                            continue;
                        var (i, j) = monomialsOfP[c];
                        numerator += value * MathS.Pow(x, i) * MathS.Pow(L, j);
                    }
                    if (numerator.Evaled is Number.Complex { IsZero: true })
                        continue;
                    // The generic case, as the integrator answers everywhere: the condition
                    // simplifying attaches, `not ln(x) = 0`, is the integrand's own pole.
                    var answer = Functions.PartialFractions.Bare(
                        (MathS.Pow(MathS.e, exponent) * (numerator / denominator).Substitute(L, logarithm)).InnerSimplified);
                    if (!Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                        continue;
                    return answer;
                }
            return null;
        }

        /// <summary>The largest power of the logarithm the tower ansatz reads or tries.</summary>
        private const int MaximumTowerDegree = 4;

        /// <summary>
        /// A product of powers times a sum that is the derivative of the product with some of
        /// the powers raised by one: <c>e^x x^2 ln(x)^2 (3 + (3 + x) ln(x))</c> is
        /// <c>(e^x x^3 ln(x)^3)'</c>, and Rubi's
        /// <c>F^(c (a + b x)) x^m ln(d x)^n (p + p n + p (1 + m + b c x ln F) ln(d x))</c> is
        /// <c>(p F^(c (a + b x)) x^(m + 1) ln(d x)^(n + 1))'</c>, for symbols <c>m</c> and <c>n</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The product rule on <c>G = K prod f_i^(e_i)</c> gives <c>G' = G sum e_i f_i'/f_i</c>,
        /// so an integrand of that shape is a product of the same powers, each lowered where
        /// its base's derivative divides it, times a sum. Read the other way: the sum in the
        /// integrand names the powers to raise. Every subset of the powers with a base holding
        /// <c>x</c> and an exponent free of it is tried raised by one, the exponentials kept,
        /// and the integrand divided by the candidate's derivative must be a constant: decided
        /// at sampled points first, with every symbol pinned, and where it is, the constant is
        /// the quotient of the two sums simplified -- <c>p</c> above -- and the answer is checked
        /// by differentiating it back. Nothing else reads a symbolic exponent: the Risch-Norman
        /// ansatz wants whole powers of its monomials, and splitting the sum loses it, since
        /// <c>F^(c(a + bx)) x^m ln(dx)^n</c> on its own is not elementary.
        /// </para>
        /// <para>
        /// Where a power is not a whole one, the sum may be missing -- the product of powers is
        /// then a constant times its own raised product's derivative -- and x may be raised from
        /// nothing, a power of it the integrand does not have.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAsTheDerivativeOfAProductOfPowers(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            Entity constant = Number.Integer.One;
            Entity? bracket = null;
            var raisable = new List<(Entity Base, Entity Exponent)>();
            var logarithmicDerivativesKept = new List<Entity>();
            Entity kept = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor is Sumf or Minusf)
                {
                    if (bracket is not null || underneath)
                        return null;
                    bracket = factor;
                    continue;
                }
                if (factor is Powf(var @base, var exponent) && !exponent.ContainsNode(x))
                {
                    raisable.Add((@base, underneath ? (-exponent).InnerSimplified : exponent));
                    continue;
                }
                if (factor is Powf(var constantBase, var power) && !constantBase.ContainsNode(x))
                {
                    var h = constantBase == MathS.e ? power : power * MathS.Ln(constantBase);
                    var derivative = Functions.PartialFractions.Bare(h.Differentiate(x).InnerSimplified);
                    logarithmicDerivativesKept.Add(underneath ? -derivative : derivative);
                    kept = underneath ? kept / factor : kept * factor;
                    continue;
                }
                raisable.Add((factor, underneath ? Number.Integer.MinusOne : Number.Integer.One));
            }
            if (raisable.Count == 0 || raisable.Count > 4)
                return null;
            // Where a power is not a whole one -- a root, or a symbolic exponent -- two more
            // candidates, each a shape nothing else reads. With no sum beside two or more powers,
            // the product is the derivative's up to a constant: `1/(x^2 sqrt(a x + b x^4))` is
            // `(-2/(3 a) sqrt(a x + b x^4)/x^2)'`, the root raised and the power of x kept; a
            // power on its own is the power rule's, or the binomial's. And x raised from nothing
            // where it is not among the powers, in front of them: Rubi's
            // `(a + b x^n + c x^(2 n))^p (a + b (1 + n + n p) x^n + c (1 + 2 n (1 + p)) x^(2 n))`
            // is `(x (a + b x^n + c x^(2 n))^(p + 1))'`. Whole powers only are a rational
            // function's, or a polynomial's beside a function, and the rules for those answer them.
            if (raisable.Any(pair => pair.Exponent is not Number.Integer))
            {
                if (raisable.Count >= 2)
                    bracket ??= Number.Integer.One;
                if (!raisable.Any(pair => pair.Base == x))
                    raisable.Insert(0, (x, Number.Integer.Zero));
            }
            if (bracket is null)
                return null;
            for (var subset = 1; subset < 1 << raisable.Count; subset++)
            {
                Entity candidate = kept;
                Entity productOfRaisedBases = Number.Integer.One;
                for (var i = 0; i < raisable.Count; i++)
                    if ((subset & (1 << i)) != 0)
                        productOfRaisedBases *= raisable[i].Base;
                // The bracket the candidate's derivative has, against the integrand's: the
                // candidate is the integrand's powers with the raised bases in besides, so
                // G' is (integrand without its bracket) (product of raised bases) (sum of the
                // logarithmic derivatives), and the constant is the quotient of the brackets.
                // Written as a sum of products, each raised base's logarithmic derivative times
                // the other raised bases, so that it reads as a polynomial wherever the bases do:
                // with `f'/f` left in, it read as nothing, and the constant fell to simplifying a
                // quotient of the two brackets -- past a minute for Rubi's
                // `x (a + b x + c x^2)^m (d + e x + f x^2 + g x^3)^n (...)`, 0.3 s read off one
                // monomial.
                Entity bracketOfTheDerivative = Number.Integer.Zero;
                foreach (var derivative in logarithmicDerivativesKept)
                    bracketOfTheDerivative += derivative * productOfRaisedBases;
                for (var i = 0; i < raisable.Count; i++)
                {
                    var (@base, exponent) = raisable[i];
                    var raised = (subset & (1 << i)) != 0;
                    var newExponent = raised ? (exponent + 1).InnerSimplified : exponent;
                    if (newExponent.Evaled is Number.Complex { IsZero: true })
                        continue;   // a power raised to nothing: not a factor of the candidate
                    candidate *= newExponent == Number.Integer.One ? @base : MathS.Pow(@base, newExponent);
                    if (!raised)
                    {
                        bracketOfTheDerivative += newExponent * @base.Differentiate(x) * productOfRaisedBases / @base;
                        continue;
                    }
                    Entity theOtherRaisedBases = Number.Integer.One;
                    for (var j = 0; j < raisable.Count; j++)
                        if (j != i && (subset & (1 << j)) != 0)
                            theOtherRaisedBases *= raisable[j].Base;
                    bracketOfTheDerivative += newExponent * @base.Differentiate(x) * theOtherRaisedBases;
                }
                if (candidate == kept)
                    continue;
                bracketOfTheDerivative = Functions.PartialFractions.Bare(bracketOfTheDerivative.InnerSimplified);
                if (!AreProportionalAtSampledPoints(bracket, bracketOfTheDerivative, x))
                    continue;
                // The constant is the quotient of one monomial's coefficients, the two
                // brackets read as polynomials in x and in the transcendental atoms holding
                // it -- `ln(d x)` -- each an indeterminate; or, where they do not read so,
                // the quotient of the brackets simplified.
                if (!TryReadTheRatioOfBrackets(bracket, bracketOfTheDerivative, x, out var k))
                {
                    k = Functions.SingleQuotient.Combine(bracket / bracketOfTheDerivative).Simplify();
                    if (k is Providedf(var inner, _))
                        k = inner;
                }
                k = Functions.PartialFractions.Bare((constant * k).InnerSimplified);
                if (k.ContainsNode(x) || k.Nodes.Any(node => node == MathS.NaN))
                    continue;
                var answer = (k * candidate).InnerSimplified;
                bool holds;
                using (MathS.Settings.DowncastingEnabled.Set(false))
                    holds = Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x);
                if (holds)
                    return answer;
            }
            return null;
        }

        /// <summary>
        /// The constant <c>k</c> with <paramref name="left"/> equal to <c>k</c> times
        /// <paramref name="right"/>, read off one monomial with both written as polynomials
        /// in <paramref name="x"/> and in every atom holding it -- a logarithm, an exponential
        /// -- as an indeterminate; false where either does not read so, or the monomial is
        /// missing from <paramref name="left"/>. Whether the constant holds for every
        /// monomial is the caller's to check.
        /// </summary>
        private static bool TryReadTheRatioOfBrackets(Entity left, Entity right, Entity.Variable x, [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out Entity? k)
        {
            k = null;
            var atoms = new List<(Entity Atom, Entity.Variable Symbol)>();
            Entity everything = left + right;
            Entity InAtoms(Entity entry) => entry.Replace(node =>
            {
                if (!node.ContainsNode(x) || node == x || node is Sumf or Minusf or Mulf or Divf || node is Powf(_, Number.Integer { EInteger.Sign: >= 0 }))
                    return node;
                foreach (var (atom, symbol) in atoms)
                    if (atom == node)
                        return symbol;
                var fresh = Variable.CreateUnique(everything, "t_atom");
                atoms.Add((node, fresh));
                everything += fresh;
                return fresh;
            });
            var leftInAtoms = InAtoms(left);
            var rightInAtoms = InAtoms(right);
            var variables = new List<Entity.Variable> { x };
            variables.AddRange(atoms.Select(pair => pair.Symbol));
            if (!TryReadInAll(leftInAtoms, variables, out var leftRead) || !TryReadInAll(rightInAtoms, variables, out var rightRead))
                return false;
            // A monomial whose coefficient on the right is a number first, so that the
            // constant is the left coefficient over it and not a quotient of symbols to be
            // cancelled; the quotient is simplified either way, and it is small.
            foreach (var numbersFirst in new[] { true, false })
                foreach (var pair in rightRead)
                {
                    if (pair.Value.Evaled is Number.Complex { IsZero: true } || numbersFirst != pair.Value.Evaled is Number.Rational)
                        continue;
                    if (!leftRead.TryGetValue(pair.Key, out var above))
                        return false;
                    k = Functions.PartialFractions.Bare((above / pair.Value).Simplify());
                    return true;
                }
            return false;
        }

        /// <summary>
        /// Whether <paramref name="left"/> is a constant multiple of <paramref name="right"/>,
        /// decided at sampled points with every symbol pinned; false where fewer than two
        /// points evaluate.
        /// </summary>
        private static bool AreProportionalAtSampledPoints(Entity left, Entity right, Entity.Variable x)
        {
            // Sampled in decimals: a pinned symbol is a small rational, and a symbolic
            // exponent pinned so makes `(F^(g (e + f x)))^n` an exact rational power whose
            // numerator has more digits than there is time for.
            using var _ = MathS.Settings.DowncastingEnabled.Set(false);
            var parameters = left.Vars.Concat(right.Vars).Where(v => v != x).Distinct().ToList();
            var pinned = 0;
            foreach (var parameter in parameters)
            {
                var fraction = (pinned % 3) switch { 0 => "1.37", 1 => "2.71", _ => "0.83" };
                var value = Number.Real.Create(EDecimal.FromString(fraction).Add(EDecimal.FromInt32(pinned)));
                left = left.Substitute(parameter, value);
                right = right.Substitute(parameter, value);
                pinned++;
            }
            Number.Complex? ratio = null;
            var compared = 0;
            foreach (var at in new[] { "0.29", "1.43", "3.17", "0.61" })
            {
                var point = Number.Real.Create(EDecimal.FromString(at));
                // A point where either side has no value is not a verdict.
                if (left.Substitute(x, point).Evaled is not Number.Complex l || right.Substitute(x, point).Evaled is not Number.Complex r
                    || l.IsNaN || r.IsNaN || r.Abs().EDecimal.CompareTo(EDecimal.FromString("1e-30")) < 0)
                    continue;
                var here = l / r;
                if (ratio is null)
                    ratio = here;
                else
                {
                    var difference = (here - ratio).Abs().EDecimal;
                    var scale = EDecimal.Max(EDecimal.One, ratio.Abs().EDecimal);
                    if (difference.CompareTo(scale.Multiply(EDecimal.FromString("1e-9"))) > 0)
                        return false;
                }
                compared++;
            }
            return compared >= 2;
        }

        /// <summary>
        /// A rational function of <c>x</c> and of exponentials and logarithms built over it,
        /// integrated by the Risch-Norman ansatz: <c>F = P/Q + sum c_j ln(q_j)</c> with <c>P</c> a
        /// polynomial of unknown coefficients in <c>x</c> and the transcendental monomials, <c>Q</c>
        /// tried from the integrand's denominator, and the <c>q_j</c> its factors.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Hearn's <c>e^(1 - x e^(x^2) + 2x^2)(x + 2x^3)/(1 - x e^(x^2))^2</c> is
        /// <c>(e^(1 - x e^(x^2))/(1 - x e^(x^2)))'</c>, and his
        /// <c>e^(x^2)/x + 2x e^(x^2) ln(x) + (ln(x) - 2)/(x + ln(x)^2)^2 + (1 + 1/x + 2 ln(x)/x)/(x + ln(x)^2)</c>
        /// is <c>(e^(x^2) ln(x) - ln(x)/(x + ln(x)^2) + ln(x + ln(x)^2))'</c>. Neither had an
        /// antiderivative: the first is an exponential of something with an exponential in it,
        /// and the second a sum whose terms are not elementary apart -- <c>e^(x^2)/x</c> is
        /// not -- so that every split loses it. With <c>t_1 = e^(x^2)</c>, <c>t_2 = ln(x)</c>,
        /// <c>t_3 = e^(1 - x t_1 + 2x^2)</c> for indeterminates, each with the derivative it has
        /// -- <c>2x t_1</c>, <c>1/x</c>, <c>(4x - t_1 - 2x^2 t_1) t_3</c> -- the integrand is a
        /// rational function of <c>x</c> and the <c>t</c>, and Liouville's theorem says its
        /// elementary antiderivative, where there is one, is a rational function of the same
        /// plus logarithms with constant coefficients. The rational part's denominator divides
        /// the integrand's with each factor's power lowered by one, the exponential monomials
        /// excepted, which may stand to any power; the logarithms' arguments are the
        /// denominator's factors. So <c>F' = f</c>, over one denominator, is a polynomial
        /// identity in <c>x</c> and the <c>t</c>, linear in the unknown coefficients of <c>P</c>
        /// and the <c>c_j</c>: one equation per monomial, solved by the elimination the other
        /// ansätze use. The identity is exact, so a solution is an answer and its absence a
        /// decline; the derivative of what comes out is checked against the integrand at
        /// sampled points all the same. This is the parallel Risch algorithm of Norman and
        /// Moore as a heuristic, with the degrees bounded as the tower ansätze bound theirs.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByRischNormanAnsatz(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // The transcendental monomials: every exponential and natural logarithm of
            // something in x, innermost first, each read in the indeterminates of the ones
            // inside it.
            var towers = expr.Nodes
                .Where(node => node.ContainsNode(x) && (node is Powf(var b, var e) && b == MathS.e && e.ContainsNode(x)
                                                       || node is Logf(var lb, var arg) && lb == MathS.e && arg.ContainsNode(x)))
                .Distinct()
                .OrderBy(node => node.Nodes.Count())
                .ToList();
            if (towers.Count == 0 || towers.Count > 3)
                return null;
            // Only a tower the closed rules do not read: an exponential of something that is
            // not linear in x -- of a polynomial, or of something with an exponential or a
            // logarithm in it -- or a logarithm of something other than x. Exponentials of
            // linears, however many, are the exponential substitution's, and `ln(x)` beside
            // them the logarithm tower's; this rule before the splits took twenty seconds on
            // `e^x (1 + sinh(x))/(1 + cosh(x))` to decline what those answer in a moment.
            static bool IsPlain(Entity tower, Entity.Variable x)
                => tower is Powf(_, var g) && TreeAnalyzer.TryGetPolyLinear(g, x, out _, out _)
                   || tower is Logf(_, var argument) && argument == x;
            if (towers.All(tower => IsPlain(tower, x)))
                return null;
            var monomials = new List<(Entity.Variable Indeterminate, Entity Written, Entity Derivative)>();
            var map = new Dictionary<Entity, Entity>();
            Entity InIndeterminates(Entity e) => e.Replace(node => map.TryGetValue(node, out var t) ? t : node);
            foreach (var tower in towers)
            {
                var written = InIndeterminates(tower);
                if (map.ContainsKey(written))
                    continue;
                var t = Variable.CreateUnique(expr, $"t{monomials.Count + 1}_rn");
                // t' in x and the indeterminates so far: e^g has g' e^g, and ln(g) has g'/g.
                Entity derivative = written switch
                {
                    Powf(_, var g) => Derived(g) * t,
                    Logf(_, var g) => Derived(g) / g,
                    _ => Number.Integer.Zero,
                };
                map[written] = t;
                monomials.Add((t, written, derivative));
            }
            Entity Derived(Entity g)
            {
                var result = g.Differentiate(x);
                foreach (var (t, _, derivative) in monomials)
                    if (g.ContainsNode(t))
                        result += g.Differentiate(t) * derivative;
                return result.InnerSimplified;
            }
            var variables = new List<Entity.Variable> { x };
            variables.AddRange(monomials.Select(m => m.Indeterminate));
            var integrand = InIndeterminates(expr);
            if (integrand.Nodes.Any(node => variables.Any(node.ContainsNode) && node is not (Variable or Sumf or Minusf or Mulf or Divf) && node is not Powf(_, Number.Integer)))
                return null;
            // With x itself in it beside the towers: a function of exponentials alone --
            // `e^x sech(e^x)` -- is the exponential substitution's, and three seconds of a
            // system that has no arctangent to offer.
            if (!integrand.ContainsNode(x))
                return null;
            // Rational in everything: read as a quotient of polynomials, cancelled by the
            // greatest common divisor with the indeterminates as variables -- a sum brought
            // over one bar carries every term's denominator, and the degrees decide the size
            // of the system.
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(integrand).InnerSimplified);
            if (Functions.PolynomialGcd.TryCancel(above.Expand().InnerSimplified, below.Expand().InnerSimplified, out var cancelled) && cancelled is not null)
                (above, below) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(cancelled));
            if (!TryReadInAll(above, variables, out var aboveRead) || !TryReadInAll(below, variables, out var belowRead))
                return null;
            var degreeAbove = aboveRead.Keys.Select(k => k.Max()).DefaultIfEmpty(0).Max();
            var degreeBelow = belowRead.Keys.Select(k => k.Max()).DefaultIfEmpty(0).Max();
            if (degreeAbove > MaximumAnsatzDegree || degreeBelow > MaximumAnsatzDegree)
                return null;

            // The denominator's factors with their powers, the exponential indeterminates
            // apart, which may stand to any power in the answer's denominator: of each term of
            // the integrand as written, the highest power of each factor -- the least common
            // multiple, where bringing the sum over one bar multiplies the terms' denominators
            // together.
            var factors = new List<(Entity Factor, int Power)>();
            foreach (var term in Sumf.LinearChildren(integrand))
            {
                var (_, termBelow) = Functions.SingleQuotient.Of(term);
                foreach (var factor in Mulf.LinearChildren(termBelow))
                {
                    var (@base, power) = factor is Powf(var inner, Number.Integer whole) && whole.EInteger.CanFitInInt32() ? (inner, whole.EInteger.ToInt32Unchecked()) : (factor, 1);
                    if (!variables.Any(@base.ContainsNode))
                        continue;
                    if (@base is Variable v && monomials.Any(m => m.Indeterminate == v && m.Written is Powf))
                        continue;
                    var index = factors.FindIndex(f => f.Factor == @base);
                    if (index >= 0)
                        factors[index] = (@base, System.Math.Max(factors[index].Power, power));
                    else
                        factors.Add((@base, power));
                }
            }
            // The derivative of a generator, with the tower's derivatives in it, over the
            // indeterminates: symbolic in the indeterminates, since each has the derivative
            // the chain rule gives it.
            Entity Differentiated(Entity generator)
            {
                var result = generator.Differentiate(x);
                foreach (var (t, _, derivative) in monomials)
                    if (generator.ContainsNode(t))
                        result += generator.Differentiate(t) * derivative;
                return result;
            }
            var exponentialIndeterminates = monomials.Where(m => m.Written is Powf).Select(m => m.Indeterminate).ToList();
            // Q: the factors with their powers lowered by one, and then as they are; each
            // exponential indeterminate to every power from zero up to the numerator's degree
            // in it plus one, since a power of an exponential above the bar is one below in
            // the answer -- Hearn's has e^(2x^2) above and 1/e^(2x^2) in its answer.
            var qCandidates = new List<Entity>();
            foreach (var lowered in new[] { true, false })
            {
                Entity q = Number.Integer.One;
                foreach (var (factor, power) in factors)
                {
                    var p = lowered ? power - 1 : power;
                    if (p > 0)
                        q = q * (p == 1 ? factor : MathS.Pow(factor, p));
                }
                qCandidates.Add(q);
            }
            qCandidates = qCandidates.Distinct().ToList();
            var exponentialBounds = exponentialIndeterminates.Select(t =>
            {
                var index = variables.IndexOf(t);
                var aboveDegree = aboveRead.Keys.Select(k => k[index]).DefaultIfEmpty(0).Max();
                return System.Math.Min(MaximumTowerDegree, aboveDegree + 2);
            }).ToList();
            var logarithmGenerators = factors.Select(f => f.Factor).Distinct().ToList();
            foreach (var q in qCandidates)
                foreach (var exponentPowers in Combinations(exponentialBounds))
                {
                    Entity denominator = q;
                    for (var i = 0; i < exponentialIndeterminates.Count; i++)
                        if (exponentPowers[i] > 0)
                            denominator = denominator * MathS.Pow(exponentialIndeterminates[i], exponentPowers[i]);
                    // The generators: x^a prod t^b over the denominator, and the logarithms of
                    // the denominator's factors. Everything is brought over one denominator,
                    // `denominator^2 * below` times the logarithms' arguments and the ln-towers'
                    // arguments (whose derivatives have them below), by exact products of
                    // polynomials: (m/Q)' is (m' Q - m Q')/Q^2 and (ln q)' is q'/q, so the
                    // columns are polynomials without a quotient to simplify.
                    var monomialGenerators = new List<Entity>();
                    var bounds = new List<int>();
                    for (var i = 0; i < variables.Count; i++)
                    {
                        var index = i;
                        var degree = aboveRead.Keys.Concat(belowRead.Keys).Select(k => k[index]).DefaultIfEmpty(0).Max();
                        bounds.Add(i == 0 ? System.Math.Min(MaximumAnsatzDegree, degree + 1) : System.Math.Min(MaximumTowerDegree, degree + 1));
                    }
                    foreach (var powers in Combinations(bounds))
                    {
                        Entity monomial = Number.Integer.One;
                        for (var i = 0; i < variables.Count; i++)
                            if (powers[i] > 0)
                                monomial = monomial == Number.Integer.One ? MathS.Pow(variables[i], powers[i]) : monomial * MathS.Pow(variables[i], powers[i]);
                        monomialGenerators.Add(monomial);
                    }
                    if (monomialGenerators.Count + logarithmGenerators.Count > 200)
                        continue;
                    Entity towersBelow = Number.Integer.One;
                    foreach (var (_, written, _) in monomials)
                        if (written is Logf(_, var g))
                            towersBelow = towersBelow * g;
                    Entity logArguments = Number.Integer.One;
                    foreach (var argument in logarithmGenerators)
                        logArguments = logArguments * argument;
                    var denominatorPrime = Differentiated(denominator);
                    var generators = new List<Entity>();
                    var columns = new List<Dictionary<int[], Entity>>();
                    var failed = false;
                    foreach (var monomial in monomialGenerators)
                    {
                        generators.Add(monomial / denominator);
                        var numerator = (Differentiated(monomial) * denominator - monomial * denominatorPrime) * below * logArguments * towersBelow;
                        if (!TryReadInAll(Functions.PartialFractions.Bare(numerator.Expand().InnerSimplified), variables, out var column))
                        {
                            failed = true;
                            break;
                        }
                        columns.Add(column);
                    }
                    if (!failed)
                        foreach (var argument in logarithmGenerators)
                        {
                            generators.Add(MathS.Ln(argument));
                            Entity others = Number.Integer.One;
                            foreach (var other in logarithmGenerators)
                                if (other != argument)
                                    others = others * other;
                            var numerator = Differentiated(argument) * MathS.Sqr(denominator) * below * others * towersBelow;
                            if (!TryReadInAll(Functions.PartialFractions.Bare(numerator.Expand().InnerSimplified), variables, out var column))
                            {
                                failed = true;
                                break;
                            }
                            columns.Add(column);
                        }
                    if (failed)
                        continue;
                    var targetNumerator = above * MathS.Sqr(denominator) * logArguments * towersBelow;
                    if (!TryReadInAll(Functions.PartialFractions.Bare(targetNumerator.Expand().InnerSimplified), variables, out var target))
                        continue;
                    var keys = columns.SelectMany(c => c.Keys).Concat(target.Keys).Distinct(new IntArrayComparer()).ToList();
                    var matrix = new Entity[keys.Count][];
                    var rhs = new Entity[keys.Count];
                    for (var row = 0; row < keys.Count; row++)
                    {
                        matrix[row] = new Entity[columns.Count];
                        for (var c = 0; c < columns.Count; c++)
                            matrix[row][c] = columns[c].TryGetValue(keys[row], out var entry) ? entry : Number.Integer.Zero;
                        rhs[row] = target.TryGetValue(keys[row], out var wanted) ? wanted : Number.Integer.Zero;
                    }
                    if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                        continue;
                    Entity answer = Number.Integer.Zero;
                    for (var c = 0; c < values.Length; c++)
                    {
                        var value = values[c].InnerSimplified;
                        if (value.Evaled is Number.Complex { IsZero: true })
                            continue;
                        answer += value * generators[c];
                    }
                    if (answer == Number.Integer.Zero)
                        continue;
                    // Back in the functions, outermost first.
                    for (var i = monomials.Count - 1; i >= 0; i--)
                        answer = answer.Substitute(monomials[i].Indeterminate, monomials[i].Written);
                    answer = Functions.PartialFractions.Bare(answer.InnerSimplified);
                    if (!Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                        continue;
                    return answer;
                }
            return null;

            static IEnumerable<int[]> Combinations(List<int> bounds)
            {
                var current = new int[bounds.Count];
                while (true)
                {
                    yield return (int[])current.Clone();
                    var i = 0;
                    while (i < bounds.Count)
                    {
                        current[i]++;
                        if (current[i] <= bounds[i])
                            break;
                        current[i] = 0;
                        i++;
                    }
                    if (i == bounds.Count)
                        yield break;
                }
            }
        }

        private sealed class IntArrayComparer : IEqualityComparer<int[]>
        {
            public bool Equals(int[]? a, int[]? b) => a is not null && b is not null && a.SequenceEqual(b);
            public int GetHashCode(int[] a)
            {
                var hash = 17;
                foreach (var v in a)
                    hash = hash * 31 + v;
                return hash;
            }
        }

        /// <summary>
        /// <paramref name="expr"/> as a polynomial in all of <paramref name="variables"/> with
        /// coefficients free of them, keyed by the powers in the variables' order.
        /// </summary>
        private static bool TryReadInAll(Entity expr, List<Entity.Variable> variables, out Dictionary<int[], Entity> read)
        {
            read = new Dictionary<int[], Entity>(new IntArrayComparer());
            var result = read;
            bool Read(Entity e, int index, int[] prefix)
            {
                if (index == variables.Count)
                {
                    if (variables.Any(e.ContainsNode))
                        return false;
                    result[prefix] = result.TryGetValue(prefix, out var already) ? already + e : e;
                    return true;
                }
                if (!TreeAnalyzer.TryGetPolynomial(e, variables[index], out var monomials))
                    return false;
                foreach (var pair in monomials)
                {
                    if (pair.Key.Sign < 0 || !pair.Key.CanFitInInt32())
                        return false;
                    var next = (int[])prefix.Clone();
                    next[index] = pair.Key.ToInt32Unchecked();
                    if (!Read(pair.Value, index + 1, next))
                        return false;
                }
                return true;
            }
            if (!Read(expr, 0, new int[variables.Count]))
                return false;
            if (read.Count == 0)
                read[new int[variables.Count]] = Number.Integer.Zero;
            return true;
        }

        /// <summary>
        /// A rational function of <c>x</c> and of <c>sin(x)</c> and <c>cos(x)</c> together, with
        /// an exponential <c>e^(a x)</c> in front or not, closed by the ansatz
        /// <c>F = e^(a x) P/Q</c> with <c>P</c> and <c>Q</c> polynomials in the three.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Timofeev's <c>x^2/(x cos(x) - sin(x))^2</c> is <c>((x sin(x) + cos(x))/(x cos(x) - sin(x)))'</c>
        /// and <c>(2x + sin(2x))/(cos(x) + x sin(x))^2</c> is <c>(2x sin(x)/(x sin(x) + cos(x)))'</c>;
        /// neither had an antiderivative. Nothing reads them: the half-angle substitution
        /// wants no bare <c>x</c>, by parts goes round in a circle, and no subtree is a
        /// substitution. They are the logarithm tower's ansatz with the sine and cosine for
        /// the logarithm. The ring of polynomials in <c>x</c>, <c>sin(x)</c> and <c>cos(x)</c>
        /// is <c>Q[x, s, c]/(s^2 + c^2 - 1)</c>, an integral domain with the basis
        /// <c>x^i c^k</c>, <c>x^i s c^k</c>, and it is closed under the derivative --
        /// <c>(s c^k)' = c^(k+1) - k (1 - c^2) c^(k-1)</c> -- so <c>F' = N/D</c> is the identity
        /// <c>(a P Q + P' Q - P Q') D = N Q^2</c> in that ring, one equation per basis element
        /// and linear in the coefficients of <c>P</c>. Exact, so a solution is an answer and
        /// its absence a decline; the derivative of what comes out is checked against the
        /// integrand at sampled points all the same. <c>Q</c> is tried from the integrand's
        /// written denominator as the other ansätze try theirs, the factors with their powers
        /// lowered by one and then as they are. The half-angle tangent was tried for the
        /// tower first, and every substitution of it leaves powers of <c>1 + t^2</c> above and
        /// below that nothing cancels; the ring needs no substitution.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTrigonometricTowerAnsatz(Entity expr, Entity.Variable x)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            var sine = MathS.Sin(x);
            var cosine = MathS.Cos(x);
            if (!expr.ContainsNode(sine) && !expr.ContainsNode(cosine)
                && !expr.Nodes.Any(node => node is Tanf(var a) && a == x || node is Cotanf(var b) && b == x
                                          || node is Secantf(var c) && c == x || node is Cosecantf(var d) && d == x))
                return null;
            if (ReadOneExponentialTimesTheRest(expr, x) is not var (exponent, rest))
                return null;
            Entity a = Number.Integer.Zero;
            if (exponent is not null)
            {
                if (!TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out _) || slope.ContainsNode(x))
                    return null;
                a = slope;
            }
            var overTheTwo = rest.Replace(node => node switch
            {
                Tanf(var arg) when arg == x => sine / cosine,
                Cotanf(var arg) when arg == x => cosine / sine,
                Secantf(var arg) when arg == x => 1 / cosine,
                Cosecantf(var arg) when arg == x => 1 / sine,
                _ => node
            });
            // Rational in x and the two, and of the two only with the argument x or a whole
            // multiple of it; and x bare somewhere, or this is the half-angle substitution's
            // and it has declined.
            if (overTheTwo.Nodes.Any(node => node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf)
                                              && !(node is Powf(_, Number.Integer))))
                return null;
            var s = Variable.CreateUnique(expr, "s_tower");
            var c = Variable.CreateUnique(expr, "c_tower");
            // A multiple angle is a polynomial in the two: `sin(2x)` is `2 s c`, and
            // Timofeev's `(2x + sin(2x))/(cos(x) + x sin(x))^2` is `(2x sin(x)/(x sin(x) + cos(x)))'`.
            static bool IsAWholeMultiple(Entity argument, Entity.Variable x, out int k)
            {
                k = 0;
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var intercept)
                    || intercept.Evaled is not Number.Complex { IsZero: true }
                    || slope.Evaled is not Number.Integer whole || whole.EInteger.Sign <= 0 || whole.EInteger.CompareTo(EInteger.FromInt32(MaximumTrigonometricTowerDegree)) > 0)
                    return false;
                k = whole.EInteger.ToInt32Checked();
                return true;
            }
            var inTheThree = overTheTwo.Replace(node =>
            {
                if (node is Sinf(var argument) && IsAWholeMultiple(argument, x, out var k))
                    return MultipleAngle(k, s, c).Sine;
                if (node is Cosf(var argument2) && IsAWholeMultiple(argument2, x, out var k2))
                    return MultipleAngle(k2, s, c).Cosine;
                return node;
            });
            if (inTheThree.Nodes.Any(node => node is Sinf(var arg) && arg.ContainsNode(x) || node is Cosf(var arg2) && arg2.ContainsNode(x)))
                return null;
            if (!inTheThree.ContainsNode(x) || !(inTheThree.ContainsNode(s) || inTheThree.ContainsNode(c)))
                return null;

            var (above, below) = Functions.SingleQuotient.Of(inTheThree);
            if (!TrigonometricPolynomial.TryRead(above, x, s, c, out var n) || !TrigonometricPolynomial.TryRead(below, x, s, c, out var d))
                return null;
            if (n.DegreeInX > MaximumTrigonometricTowerDegree || d.DegreeInX > MaximumTrigonometricTowerDegree
                || n.TrigonometricDegree > MaximumTrigonometricTowerDegree || d.TrigonometricDegree > MaximumTrigonometricTowerDegree)
                return null;

            // The denominators tried, from the written factors that hold any of the three.
            var factors = Mulf.LinearChildren(below).Where(f => f.ContainsNode(x) || f.ContainsNode(s) || f.ContainsNode(c)).ToList();
            var candidates = new List<Entity>();
            Entity lowered = Number.Integer.One;
            foreach (var factor in factors)
                if (factor is Powf(var @base, Number.Integer power) && power.EInteger.Sign > 0 && power.EInteger.CanFitInInt32())
                {
                    var one = power.EInteger.ToInt32Unchecked() - 1;
                    if (one > 0)
                        lowered *= one == 1 ? @base : MathS.Pow(@base, one);
                }
            candidates.Add(lowered);
            if (factors.Count > 0)
                candidates.Add(below);

            foreach (var candidate in candidates.Distinct())
            {
                if (!TrigonometricPolynomial.TryRead(candidate, x, s, c, out var q))
                    continue;
                var degreePX = System.Math.Max(q.DegreeInX, n.DegreeInX + 2);
                var degreePT = System.Math.Max(q.TrigonometricDegree, n.TrigonometricDegree + 1);
                if (degreePX > MaximumTrigonometricTowerDegree || degreePT > MaximumTrigonometricTowerDegree + 1)
                    continue;
                var qPrime = q.Derivative();
                var qSquared = q.Times(q);
                var target = n.Times(qSquared);
                var columns = new List<TrigonometricPolynomial>();
                var monomialsOfP = new List<(int X, int C, int S)>();
                for (var i = 0; i <= degreePX; i++)
                    for (var k = 0; k <= degreePT; k++)
                        for (var flag = 0; flag <= 1; flag++)
                        {
                            if (k + flag > degreePT)
                                continue;
                            var m = TrigonometricPolynomial.Monomial(i, k, flag);
                            // (a m Q + m' Q - m Q') D, the coefficient of this unknown.
                            var bracket = m.Derivative().Times(q).Minus(m.Times(qPrime));
                            if (a.Evaled is not Number.Complex { IsZero: true })
                                bracket = bracket.Plus(m.Times(q).Scaled(a));
                            columns.Add(bracket.Times(d));
                            monomialsOfP.Add((i, k, flag));
                        }
                var keys = columns.SelectMany(column => column.Terms.Keys).Concat(target.Terms.Keys).Distinct().OrderBy(key => key).ToList();
                var matrix = new Entity[keys.Count][];
                var rhs = new Entity[keys.Count];
                for (var row = 0; row < keys.Count; row++)
                {
                    matrix[row] = new Entity[columns.Count];
                    for (var column = 0; column < columns.Count; column++)
                        matrix[row][column] = columns[column].Terms.TryGetValue(keys[row], out var entry) ? entry : Number.Integer.Zero;
                    rhs[row] = target.Terms.TryGetValue(keys[row], out var wanted) ? wanted : Number.Integer.Zero;
                }
                if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                    continue;
                Entity numerator = Number.Integer.Zero;
                for (var column = 0; column < values.Length; column++)
                {
                    var value = values[column].InnerSimplified;
                    if (value.Evaled is Number.Complex { IsZero: true })
                        continue;
                    var (i, k, flag) = monomialsOfP[column];
                    numerator += value * TrigonometricPolynomial.Monomial(i, k, flag).ToEntity(x, s, c);
                }
                if (numerator.Evaled is Number.Complex { IsZero: true })
                    continue;
                var quotient = (numerator / candidate).Substitute(s, sine).Substitute(c, cosine);
                var answer = Functions.PartialFractions.Bare(
                    (exponent is null ? quotient : MathS.Pow(MathS.e, exponent) * quotient).InnerSimplified);
                if (!Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                    continue;
                return answer;
            }
            return null;
        }

        /// <summary>The largest degree in x or in the two the trigonometric tower ansatz reads or tries.</summary>
        private const int MaximumTrigonometricTowerDegree = 6;

        /// <summary>
        /// <c>sin(k x)</c> and <c>cos(k x)</c> as polynomials in <paramref name="s"/> and
        /// <paramref name="c"/>, by <c>sin((k + 1)x) = sin(kx) cos(x) + cos(kx) sin(x)</c> and
        /// <c>cos((k + 1)x) = cos(kx) cos(x) - sin(kx) sin(x)</c>.
        /// </summary>
        private static (Entity Sine, Entity Cosine) MultipleAngle(int k, Entity.Variable s, Entity.Variable c)
        {
            Entity sine = s;
            Entity cosine = c;
            for (var i = 1; i < k; i++)
                (sine, cosine) = (sine * c + cosine * s, cosine * c - sine * s);
            return (sine, cosine);
        }

        /// <summary>
        /// A polynomial in <c>x</c>, <c>sin(x)</c> and <c>cos(x)</c> with every <c>sin^2</c>
        /// written as <c>1 - cos^2</c>, so that the basis is <c>x^i cos^k</c> and
        /// <c>x^i sin cos^k</c>: keyed by the degree in x, the degree in the cosine and the
        /// sine's presence, with coefficients free of the three. Two are equal as functions
        /// exactly when their terms are.
        /// </summary>
        private sealed class TrigonometricPolynomial
        {
            internal readonly Dictionary<(int X, int C, int S), Entity> Terms = new();

            internal int DegreeInX => Terms.Count == 0 ? 0 : Terms.Keys.Max(key => key.X);
            internal int TrigonometricDegree => Terms.Count == 0 ? 0 : Terms.Keys.Max(key => key.C + key.S);

            internal static TrigonometricPolynomial Monomial(int i, int k, int flag)
            {
                var monomial = new TrigonometricPolynomial();
                monomial.Terms[(i, k, flag)] = Number.Integer.One;
                return monomial;
            }

            private void Add((int X, int C, int S) key, Entity coefficient)
            {
                var sum = Terms.TryGetValue(key, out var already) ? (already + coefficient).InnerSimplified : coefficient;
                if (sum.Evaled is Number.Complex { IsZero: true })
                    Terms.Remove(key);
                else
                    Terms[key] = sum;
            }

            internal TrigonometricPolynomial Plus(TrigonometricPolynomial other)
            {
                var sum = new TrigonometricPolynomial();
                foreach (var pair in Terms) sum.Add(pair.Key, pair.Value);
                foreach (var pair in other.Terms) sum.Add(pair.Key, pair.Value);
                return sum;
            }

            internal TrigonometricPolynomial Minus(TrigonometricPolynomial other) => Plus(other.Scaled(Number.Integer.MinusOne));

            internal TrigonometricPolynomial Scaled(Entity by)
            {
                var scaled = new TrigonometricPolynomial();
                foreach (var pair in Terms) scaled.Add(pair.Key, (by * pair.Value).InnerSimplified);
                return scaled;
            }

            internal TrigonometricPolynomial Times(TrigonometricPolynomial other)
            {
                var product = new TrigonometricPolynomial();
                foreach (var leftPair in Terms)
                    foreach (var rightPair in other.Terms)
                    {
                        var (left, right) = (leftPair.Key, rightPair.Key);
                        var coefficient = (leftPair.Value * rightPair.Value).InnerSimplified;
                        var i = left.X + right.X;
                        var k = left.C + right.C;
                        if (left.S + right.S == 2)
                        {
                            // sin^2 is 1 - cos^2.
                            product.Add((i, k, 0), coefficient);
                            product.Add((i, k + 2, 0), (-coefficient).InnerSimplified);
                        }
                        else
                            product.Add((i, k, left.S + right.S), coefficient);
                    }
                return product;
            }

            /// <summary>The derivative in x, with <c>(sin cos^k)' = cos^(k+1) - k (1 - cos^2) cos^(k-1)</c>.</summary>
            internal TrigonometricPolynomial Derivative()
            {
                var derivative = new TrigonometricPolynomial();
                foreach (var pair in Terms)
                {
                    var (i, k, flag) = pair.Key;
                    var coefficient = pair.Value;
                    if (i > 0)
                        derivative.Add((i - 1, k, flag), (i * coefficient).InnerSimplified);
                    if (flag == 0)
                    {
                        // (cos^k)' = -k sin cos^(k-1)
                        if (k > 0)
                            derivative.Add((i, k - 1, 1), (-k * coefficient).InnerSimplified);
                    }
                    else
                    {
                        derivative.Add((i, k + 1, 0), coefficient);
                        if (k > 0)
                        {
                            derivative.Add((i, k - 1, 0), (-k * coefficient).InnerSimplified);
                            derivative.Add((i, k + 1, 0), (k * coefficient).InnerSimplified);
                        }
                    }
                }
                return derivative;
            }

            internal Entity ToEntity(Entity.Variable x, Entity.Variable s, Entity.Variable c)
            {
                Entity sum = Number.Integer.Zero;
                foreach (var pair in Terms.OrderBy(pair => pair.Key))
                {
                    var (i, k, flag) = pair.Key;
                    Entity term = pair.Value;
                    if (i > 0) term *= i == 1 ? x : MathS.Pow(x, i);
                    if (flag == 1) term *= s;
                    if (k > 0) term *= k == 1 ? c : MathS.Pow(c, k);
                    sum = sum == Number.Integer.Zero ? term : sum + term;
                }
                return sum;
            }

            /// <summary>
            /// <paramref name="expr"/>, a polynomial in the three as written, read into the
            /// basis; <see langword="false"/> where it is not one.
            /// </summary>
            internal static bool TryRead(Entity expr, Entity.Variable x, Entity.Variable s, Entity.Variable c, out TrigonometricPolynomial read)
            {
                read = new TrigonometricPolynomial();
                if (!TreeAnalyzer.TryGetPolynomial(expr.Expand(), x, out var inX))
                    return false;
                foreach (var pairInX in inX)
                {
                    var powerOfX = pairInX.Key;
                    var coefficientInX = pairInX.Value;
                    if (powerOfX.Sign < 0 || !powerOfX.CanFitInInt32())
                        return false;
                    if (!TreeAnalyzer.TryGetPolynomial(coefficientInX, s, out var inS))
                        return false;
                    foreach (var pairInS in inS)
                    {
                        var powerOfS = pairInS.Key;
                        var coefficientInS = pairInS.Value;
                        if (powerOfS.Sign < 0 || !powerOfS.CanFitInInt32())
                            return false;
                        if (!TreeAnalyzer.TryGetPolynomial(coefficientInS, c, out var inC))
                            return false;
                        foreach (var pair in inC)
                        {
                            var powerOfC = pair.Key;
                            var coefficient = pair.Value;
                            if (powerOfC.Sign < 0 || !powerOfC.CanFitInInt32() || coefficient.ContainsNode(x) || coefficient.ContainsNode(s) || coefficient.ContainsNode(c))
                                return false;
                            // sin^(2m + f) is (1 - cos^2)^m sin^f.
                            var j = powerOfS.ToInt32Unchecked();
                            var term = Monomial(powerOfX.ToInt32Unchecked(), powerOfC.ToInt32Unchecked(), j % 2).Scaled(coefficient);
                            var oneMinusCosineSquared = new TrigonometricPolynomial();
                            oneMinusCosineSquared.Terms[(0, 0, 0)] = Number.Integer.One;
                            oneMinusCosineSquared.Terms[(0, 2, 0)] = Number.Integer.MinusOne;
                            for (var m = 0; m < j / 2; m++)
                                term = term.Times(oneMinusCosineSquared);
                            read = read.Plus(term);
                        }
                    }
                }
                return true;
            }
        }

        /// <summary>
        /// <paramref name="expr"/> as a polynomial in <paramref name="x"/> and <paramref name="L"/>
        /// with coefficients free of both, keyed by the pair of degrees.
        /// </summary>
        private static bool TryReadInBoth(Entity expr, Entity.Variable x, Entity.Variable L, out Dictionary<(int, int), Entity> read)
        {
            read = new Dictionary<(int, int), Entity>();
            if (!TreeAnalyzer.TryGetPolynomial(expr, x, out var inX))
                return false;
            foreach (var pair in inX)
            {
                if (pair.Key.Sign < 0 || !pair.Key.CanFitInInt32())
                    return false;
                if (!TreeAnalyzer.TryGetPolynomial(pair.Value, L, out var inL))
                    return false;
                foreach (var inner in inL)
                {
                    if (inner.Key.Sign < 0 || !inner.Key.CanFitInInt32() || inner.Value.ContainsNode(x) || inner.Value.ContainsNode(L))
                        return false;
                    var key = (pair.Key.ToInt32Unchecked(), inner.Key.ToInt32Unchecked());
                    read[key] = read.TryGetValue(key, out var already) ? already + inner.Value : inner.Value;
                }
            }
            if (read.Count == 0)
                read[(0, 0)] = Number.Integer.Zero;
            return true;
        }

        /// <summary>
        /// <paramref name="term"/> as one exponential of something in <paramref name="x"/> times
        /// everything else, or a <see langword="null"/> exponent where there is not exactly one.
        /// </summary>
        private static (Entity? Exponent, Entity Remainder)? ReadOneExponentialTimesTheRest(Entity term, Entity.Variable x)
        {
            Entity? exponent = null;
            Entity rest = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(term))
            {
                if (factor is Powf(var @base, var power) && !@base.ContainsNode(x) && power.ContainsNode(x)
                    && power is not Number)
                {
                    if (exponent is not null)
                        return null;
                    var h = @base == MathS.e ? power : power * MathS.Ln(@base);
                    exponent = (underneath ? -h : h).InnerSimplified;
                    continue;
                }
                rest = underneath ? rest / factor : rest * factor;
            }
            return (exponent, rest);
        }

        /// <summary>
        /// The ansatz of <see cref="SolveByExponentialAnsatz"/> for <c>e^h R</c>, or for
        /// <c>R</c> alone when <paramref name="h"/> is <see langword="null"/>.
        /// </summary>
        internal static Entity? IntegrateByAnsatz(Entity? h, Entity rational, Entity.Variable x)
        {
            var (above, below) = Functions.SingleQuotient.Of(rational.InnerSimplified);
            if (!TreeAnalyzer.TryGetPolynomial(above, x, out var numeratorRead)
                || !TreeAnalyzer.TryGetPolynomial(below, x, out var denominatorRead)
                || numeratorRead.Count == 0 || denominatorRead.Count == 0)
                return null;
            foreach (var pair in numeratorRead.Concat(denominatorRead))
                if (pair.Key.Sign < 0 || pair.Value.ContainsNode(x))
                    return null;

            Entity p = 0, q = 1;
            if (h is not null)
            {
                (p, q) = Functions.SingleQuotient.Of(h.InnerSimplified);
                if (!TreeAnalyzer.TryGetPolynomial(p, x, out var pRead) || !TreeAnalyzer.TryGetPolynomial(q, x, out var qRead))
                    return null;
                foreach (var pair in pRead.Concat(qRead))
                    if (pair.Key.Sign < 0 || pair.Value.ContainsNode(x))
                        return null;
            }

            var degreeAbove = (int)numeratorRead.Keys.Max()!.ToInt32Checked();
            var degreeBelow = (int)denominatorRead.Keys.Max()!.ToInt32Checked();
            if (degreeAbove > MaximumAnsatzDegree || degreeBelow > MaximumAnsatzDegree)
                return null;

            foreach (var d in CandidateDenominators(below, x))
            {
                if (IntegrateByAnsatzOver(h, p, q, above, below, d, x, degreeAbove, degreeBelow) is { } answer)
                    return answer;
            }
            return null;
        }

        /// <summary>
        /// Whether <c>sum values_k columns_k = target</c> holds coefficient by coefficient in
        /// rational arithmetic; false where a coefficient or a value is not rational.
        /// </summary>
        private static bool IdentityHoldsExactly(List<Dictionary<EInteger, Entity>> columns, Entity[] values, Dictionary<EInteger, Entity> target)
        {
            var sums = new Dictionary<EInteger, ERational>();
            for (var k = 0; k < columns.Count; k++)
            {
                if (values[k].Evaled is not Number.Rational value)
                    return false;
                if (value.ERational.IsZero)
                    continue;
                foreach (var pair in columns[k])
                {
                    if (pair.Value.Evaled is not Number.Rational coefficient)
                        return false;
                    var term = coefficient.ERational.Multiply(value.ERational);
                    sums[pair.Key] = sums.TryGetValue(pair.Key, out var so) ? so.Add(term).ToLowestTerms() : term.ToLowestTerms();
                }
            }
            foreach (var pair in target)
            {
                if (pair.Value.Evaled is not Number.Rational wanted)
                    return false;
                var have = sums.TryGetValue(pair.Key, out var sum) ? sum : ERational.Zero;
                if (!have.Subtract(wanted.ERational).ToLowestTerms().IsZero)
                    return false;
                sums.Remove(pair.Key);
            }
            return sums.Values.All(sum => sum.IsZero);
        }

        /// <summary>The product of two polynomials given as coefficients by power, each coefficient simplified.</summary>
        private static Dictionary<EInteger, Entity> PolynomialProduct(Dictionary<EInteger, Entity> left, Dictionary<EInteger, Entity> right)
        {
            // Over the rationals in rational arithmetic: sixty columns of degree a hundred
            // and twenty as expressions simplified coefficient by coefficient did not return.
            if (AsRationals(left) is { } leftRationals && AsRationals(right) is { } rightRationals)
            {
                var rationalProduct = new Dictionary<EInteger, ERational>();
                foreach (var l in leftRationals)
                    foreach (var r in rightRationals)
                    {
                        var power = l.Key + r.Key;
                        var term = l.Value.Multiply(r.Value);
                        rationalProduct[power] = rationalProduct.TryGetValue(power, out var so) ? so.Add(term).ToLowestTerms() : term.ToLowestTerms();
                    }
                var written = new Dictionary<EInteger, Entity>();
                foreach (var pair in rationalProduct)
                    if (!pair.Value.IsZero)
                        written[pair.Key] = Number.Rational.Create(pair.Value);
                return written;
            }
            var sums = new Dictionary<EInteger, List<Entity>>();
            foreach (var l in left)
                foreach (var r in right)
                {
                    var power = l.Key + r.Key;
                    if (!sums.TryGetValue(power, out var terms))
                        sums[power] = terms = new List<Entity>();
                    terms.Add(l.Value * r.Value);
                }
            var product = new Dictionary<EInteger, Entity>();
            foreach (var pair in sums)
            {
                Entity sum = pair.Value[0];
                for (var i = 1; i < pair.Value.Count; i++)
                    sum += pair.Value[i];
                var simplified = sum.InnerSimplified;
                if (simplified != Number.Integer.Zero && simplified.Evaled is not Number.Complex { IsZero: true })
                    product[pair.Key] = simplified;
            }
            return product;
        }

        /// <summary>The coefficients as rationals, or null where one is not.</summary>
        private static Dictionary<EInteger, ERational>? AsRationals(Dictionary<EInteger, Entity> poly)
        {
            var rationals = new Dictionary<EInteger, ERational>();
            foreach (var pair in poly)
            {
                if (pair.Value.Evaled is not Number.Rational rational)
                    return null;
                rationals[pair.Key] = rational.ERational;
            }
            return rationals;
        }

        private static Dictionary<EInteger, Entity> PolynomialSum(Dictionary<EInteger, Entity> left, Dictionary<EInteger, Entity> right)
        {
            var sum = new Dictionary<EInteger, Entity>(left);
            foreach (var pair in right)
            {
                var value = sum.TryGetValue(pair.Key, out var so) ? (so + pair.Value).InnerSimplified : pair.Value;
                if (value == Number.Integer.Zero || value.Evaled is Number.Complex { IsZero: true })
                    sum.Remove(pair.Key);
                else
                    sum[pair.Key] = value;
            }
            return sum;
        }

        private static Dictionary<EInteger, Entity> PolynomialDifference(Dictionary<EInteger, Entity> left, Dictionary<EInteger, Entity> right)
        {
            var negated = new Dictionary<EInteger, Entity>();
            foreach (var pair in right)
                negated[pair.Key] = (-pair.Value).InnerSimplified;
            return PolynomialSum(left, negated);
        }

        private static Dictionary<EInteger, Entity> PolynomialDerivative(Dictionary<EInteger, Entity> poly)
        {
            var derivative = new Dictionary<EInteger, Entity>();
            foreach (var pair in poly)
                if (!pair.Key.IsZero)
                    derivative[pair.Key - 1] = (Number.Integer.Create(pair.Key) * pair.Value).InnerSimplified;
            return derivative;
        }

        /// <summary>
        /// The denominators the ansatz tries, in order: the denominator with every written power
        /// lowered by one, and the denominator as it is.
        /// </summary>
        private static IEnumerable<Entity> CandidateDenominators(Entity denominator, Entity.Variable x)
        {
            var variableFactors = Mulf.LinearChildren(denominator).Where(f => f.ContainsNode(x)).ToList();
            // One written power on its own is tried at every level below it: with an exponential
            // in front the antiderivative's denominator need not be one below the integrand's --
            // `e^(1/x)(1 + x)/x^4` is `(-e^(1/x)(1 - x + x^2)/x^2)'`, two below.
            if (variableFactors.Count == 1
                && variableFactors[0] is Powf(var only, Number.Integer onlyPower)
                && onlyPower.EInteger.Sign > 0 && onlyPower.EInteger.CanFitInInt32())
            {
                for (var level = onlyPower.EInteger.ToInt32Unchecked() - 1; level >= 0; level--)
                    yield return level == 0 ? Number.Integer.One : level == 1 ? only : MathS.Pow(only, level);
                yield return denominator;
                yield break;
            }
            Entity lowered = Number.Integer.One;
            foreach (var factor in variableFactors)
                if (factor is Powf(var @base, Number.Integer power) && power.EInteger.Sign > 0)
                {
                    var one = power.EInteger.Subtract(EInteger.One);
                    if (one.IsZero)
                        continue;
                    lowered *= one.Equals(EInteger.One) ? @base : MathS.Pow(@base, Number.Integer.Create(one));
                }
            yield return lowered;
            if (denominator.ContainsNode(x))
                yield return denominator;
        }

        /// <summary>
        /// <paramref name="denominator"/> with each written factor taken into its irreducible
        /// factors over the rationals and equal factors gathered into one power, or
        /// <see langword="null"/> where the written factors already have that structure -- the
        /// same count of distinct factors with the same multiplicities -- so that a
        /// denominator which is already factored keeps its own spelling.
        /// </summary>
        /// <summary>
        /// <paramref name="denominator"/> with each written base that is a polynomial in
        /// <paramref name="x"/> with rational coefficients, of degree at least two and not a
        /// sum of monomials as it stands, written as that sum; null where every base already is.
        /// </summary>
        private static Entity? TryWriteBasesAsPolynomials(Entity denominator, Entity.Variable x)
        {
            var changed = false;
            Entity product = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                var (@base, power) = factor is Powf(var b, Number.Integer e) ? (b, (Entity)e) : (factor, Number.Integer.One);
                if (@base.ContainsNode(x) && @base is not Variable && !IsASumOfMonomials(@base, x)
                    && Functions.PolynomialFactoring.TryGetRationalCoefficients(@base, x, 1, 2, 64, out var coefficients))
                {
                    var written = Functions.RationalPolynomial.Create(coefficients).ToEntity(x);
                    if (written != @base)
                    {
                        changed = true;
                        @base = written;
                    }
                }
                product *= power == Number.Integer.One ? @base : MathS.Pow(@base, power);
            }
            return changed ? product : null;
        }

        /// <summary>Whether <paramref name="expr"/> is written as a sum of rational multiples of powers of <paramref name="x"/>.</summary>
        private static bool IsASumOfMonomials(Entity expr, Entity.Variable x)
        {
            foreach (var term in Sumf.LinearChildren(expr))
            {
                var bare = term is Mulf(var l, var r) && !l.ContainsNode(x) ? r : term is Mulf(var l2, var r2) && !r2.ContainsNode(x) ? l2 : term;
                if (bare.ContainsNode(x) && bare != x && bare is not Powf(Variable, Number.Integer))
                    return false;
            }
            return true;
        }

        /// <summary>
        /// <paramref name="denominator"/> with the content of every written sum among its
        /// factors taken out in front of it: <c>(a u + a)(1 - u^2)</c> is <c>a (u + 1)(1 - u^2)</c>,
        /// and <c>-a t^6 - 2a t^5 - a t^4 + a t^2 + 2a t + a</c> is <c>a</c> times the
        /// polynomial over the rationals. Null where no factor has one.
        /// </summary>
        /// <remarks>
        /// The content is the gcd of the coefficients as polynomials in the symbols, and a
        /// factor whose coefficients share one is a constant times a smaller polynomial: with
        /// the constant written inside, <c>(a u + a)</c> was a symbolic linear whose root the
        /// factor <c>1 - u^2</c> beside it shares, which the symbolic split declines, and the
        /// sextic the half-angle makes of <c>tan(x)/(a + a csc(x))</c> was a polynomial with a
        /// symbol in every coefficient, which nothing factors -- where over the rationals it is
        /// <c>(t - 1)(t + 1)^3 (t^2 + 1)</c>. Rubi's <c>a + a csc(x)</c> and the like are what
        /// this is for.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? WithTheContentOutOfEachSumFactor(Entity denominator, Entity.Variable x)
        {
            var changed = false;
            Entity product = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                // Whole powers only: `(c a + d a x)^(1/3)` is `a^(1/3) (c + d x)^(1/3)` for a
                // positive `a` and not for a negative one, and a symbol is neither.
                var (@base, power) = factor is Powf(var b, Number.Integer p) ? (b, p) : (factor, Number.Integer.One);
                if (@base is not (Sumf or Minusf) || !@base.ContainsNode(x) || !@base.Vars.Any(v => v != x)
                    || !TreeAnalyzer.TryGetPolynomial(@base, x, out var read) || read.Count < 2
                    || read.Keys.Any(degree => degree.Sign < 0) || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                {
                    product *= factor;
                    continue;
                }
                var variables = @base.Vars.OrderBy(v => v.Name, System.StringComparer.Ordinal).ToList();
                if (variables.Count > MultivariatePolynomial.MaxVariables)
                {
                    product *= factor;
                    continue;
                }
                var indices = new Dictionary<Variable, int>();
                for (var i = 0; i < variables.Count; i++)
                    indices[variables[i]] = i;
                var rest = Enumerable.Range(0, variables.Count).Where(i => variables[i] != x).ToList();
                // The lowest power of x every term holds comes out too: `a u^4 + b u^3` is
                // `u^3 (a u + b)`, which is what the sine substitution makes of `cot^3/(a + b csc)`,
                // and neither the refactoring over the rationals nor the symbolic split reads
                // a symbolic polynomial for the monomial it is a multiple of.
                var lowest = read.Keys.Min()!;
                if (MultivariatePolynomial.TryParse(@base, indices) is not { } polynomial
                    || Functions.PolynomialGcd.ContentIn(polynomial, indices[x], rest, 0) is not { } content
                    || content.IsConstant && lowest.IsZero
                    || polynomial.DivideExact(content) is not { } primitive)
                {
                    product *= factor;
                    continue;
                }
                var monomial = lowest.IsZero ? Number.Integer.One : lowest.Equals(EInteger.One) ? x : MathS.Pow(x, Number.Integer.Create(lowest));
                var primitivePart = primitive.ToEntity(variables);
                if (!lowest.IsZero && TreeAnalyzer.PolynomialLongDivision(primitivePart, monomial, genericCase: true, inTermsOf: x) is var (divided, remainder)
                    && (remainder is Divf(var top, _) ? top : remainder).Evaled is Number.Complex { IsZero: true })
                    primitivePart = divided.InnerSimplified;
                else if (!lowest.IsZero)
                {
                    product *= factor;
                    continue;
                }
                Entity constantPart = content.IsConstant ? monomial : lowest.IsZero ? content.ToEntity(variables) : content.ToEntity(variables) * monomial;
                product *= power == Number.Integer.One ? constantPart * primitivePart : MathS.Pow(constantPart, power) * MathS.Pow(primitivePart, power);
                changed = true;
            }
            return changed ? product : null;
        }

        /// <summary>
        /// <paramref name="denominator"/> with every quadratic factor that has a root off the real line
        /// in common with a linear factor beside it written as its leading coefficient times the
        /// linears of its two roots, each linear with such a root written as its slope times
        /// <c>x - r</c>, and the powers of one linear gathered into one; <see langword="null"/>
        /// where no quadratic shares such a root. <c>(1 + i x)(1 + x^2)</c> is
        /// <c>i (x - i)^2 (x + i)</c>.
        /// </summary>
        private static Entity? OverAComplexRootSharedWithAQuadratic(Entity denominator, Entity.Variable x)
        {
            // With numbers only, the split over the rationals and the imaginary unit answers it as
            // it is written.
            if (!denominator.Vars.Any(symbol => symbol != x))
                return null;
            var written = new List<(Entity Base, EInteger Power)>();
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                written.Add(factor is Powf(var @base, Number.Integer n) && n.EInteger.Sign > 0 ? (@base, n.EInteger) : (factor, EInteger.One));
            }
            // The roots of the linears that are not real, each with the linear's slope.
            var roots = new Dictionary<Entity, (Number.Complex Root, Entity Slope)>();
            foreach (var (@base, _) in written)
                if (TreeAnalyzer.TryGetPolyLinear(@base, x, out var slope, out var offset) && !TreeAnalyzer.IsZero(slope)
                    && Functions.PartialFractions.Bare((-offset / slope).Simplify()).Evaled is Number.Complex root && root is not Number.Real)
                    roots[@base] = (root, slope);
            if (roots.Count == 0)
                return null;
            var gathered = new Dictionary<Entity, EInteger>();
            void Add(Entity @base, EInteger power) => gathered[@base] = gathered.TryGetValue(@base, out var before) ? before.Add(power) : power;
            var shared = false;
            foreach (var (@base, power) in written)
            {
                if (roots.TryGetValue(@base, out var linear))
                {
                    constant = constant * MathS.Pow(linear.Slope, Number.Integer.Create(power));
                    Add((x - linear.Root).InnerSimplified, power);
                    continue;
                }
                if (TreeAnalyzer.TryGetPolyQuadratic(@base, x, out var a, out var b, out var c) && !TreeAnalyzer.IsZero(a)
                    && a.Evaled is Number.Complex && b.Evaled is Number.Complex && c.Evaled is Number.Complex
                    && roots.Values.FirstOrDefault(candidate => (a * candidate.Root * candidate.Root + b * candidate.Root + c).Evaled is Number.Complex { IsZero: true }) is var (root, _)
                    && root is not null)
                {
                    shared = true;
                    var other = (-b / a - root).Evaled;
                    constant = constant * MathS.Pow(a, Number.Integer.Create(power));
                    Add((x - root).InnerSimplified, power);
                    Add((x - other).InnerSimplified, power);
                    continue;
                }
                Add(@base, power);
            }
            if (!shared)
                return null;
            Entity product = constant;
            foreach (var pair in gathered)
                product = product * (pair.Value.Equals(EInteger.One) ? pair.Key : MathS.Pow(pair.Key, Number.Integer.Create(pair.Value)));
            return product;
        }

        /// <summary>
        /// <paramref name="numerator"/> over <paramref name="denominator"/>, the denominator's
        /// written factors taken apart over their greatest common divisors -- with one another,
        /// and each with its own derivative in <paramref name="x"/> -- until they are coprime and
        /// squarefree as written, and what the numerator shares with them cancelled;
        /// <see langword="null"/> where no factor holds a symbol, they are coprime and squarefree
        /// already, or one is not a polynomial.
        /// </summary>
        /// <remarks>
        /// The divisors are taken over the rationals in every variable, so a factor of the symbols
        /// alone can come with one: that goes in front, as a constant, and each factor kept is
        /// primitive in <paramref name="x"/>. `c d^2 + 2 c d e x + c e^2 x^2` shares `c (d + e x)`
        /// with its derivative, and is `c (d + e x)^2`.
        /// </remarks>
        private static (Entity Numerator, Entity Denominator)? OverSymbolicFactorsWrittenApart(Entity numerator, Entity denominator, Entity.Variable x)
        {
            var written = new List<(Entity Base, int Power)>();
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant == Number.Integer.One ? factor : constant * factor;
                    continue;
                }
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (b, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                // Over one bar, the constant below it in front: the integrator writes a quadratic
                // monic, `a/c + (c d^2 + a e^2)/(c d e) x + x^2`, and it is a polynomial in the
                // symbols over `c d e`.
                var (overOneBar, belowTheBar) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(@base));
                if (belowTheBar.ContainsNode(x))
                    return null;
                if (belowTheBar != Number.Integer.One)
                {
                    var front = power == 1 ? belowTheBar : MathS.Pow(belowTheBar, power);
                    constant = constant == Number.Integer.One ? 1 / front : constant / front;
                }
                written.Add((overOneBar, power));
            }
            if (!written.Any(pair => pair.Base.Vars.Any(v => v != x)))
                return null;
            var (numeratorOverOneBar, belowTheNumerator) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(numerator));
            if (!belowTheNumerator.ContainsNode(x))
            {
                numerator = numeratorOverOneBar;
                if (belowTheNumerator != Number.Integer.One)
                    constant = constant == Number.Integer.One ? belowTheNumerator : constant * belowTheNumerator;
            }
            var variables = numerator.Vars.Concat(denominator.Vars).Distinct().OrderBy(v => v.Name, System.StringComparer.Ordinal).ToList();
            if (variables.Count > MultivariatePolynomial.MaxVariables)
                return null;
            var indices = new Dictionary<Variable, int>();
            for (var i = 0; i < variables.Count; i++)
                indices[variables[i]] = i;
            var all = Enumerable.Range(0, variables.Count).ToList();
            var at = indices[x];
            var rest = all.Where(i => i != at).ToList();
            var parts = new List<(MultivariatePolynomial Poly, int Power)>();
            var degree = 0;
            foreach (var (@base, power) in written)
            {
                if (MultivariatePolynomial.TryParse(@base, indices) is not { } poly || poly.DegreeIn(at) == 0)
                    return null;
                degree += poly.DegreeIn(at);
                parts.Add((poly, power));
            }
            if (degree > 12 || parts.Count < 2 && parts[0].Poly.DegreeIn(at) < 2)
                return null;

            // A power of x is what a factor shares with x^k beside it, or with its own derivative
            // where its lowest term is x^k, and taking it out is the content's, before this. Split
            // here, `b x^2 + c x^4` came apart as `x^2 (b/c + x^2) c`, and over that monic quadratic
            // with a symbol below its bar Rubi's `x^12 (A + B x^2)/(b x^2 + c x^4)^3` had an answer
            // of four million characters, where with the content taken out it has seven thousand.
            bool IsAPowerOfX(MultivariatePolynomial poly)
                => poly.Monomials.Take(2).Count() == 1
                   && rest.All(variable => MultivariatePolynomial.PowerOfMonomial(poly.Monomials.First(), variable) == 0);

            // What is free of x in a factor goes in front, to the factor's power.
            void Front(MultivariatePolynomial free, int power)
            {
                if (free.IsConstant && free.SameAs(MultivariatePolynomial.One(free.VariableCount)))
                    return;
                var front = free.ToEntity(variables);
                var raised = power == 1 ? front : MathS.Pow(front, power);
                constant = constant == Number.Integer.One ? raised : constant * raised;
            }
            bool Keep(MultivariatePolynomial poly, int power)
            {
                // A part free of x goes in front whole, its sign with it: a divisor is found up to
                // a unit, so taking -(b u^2 - 1)^2 apart leaves a part -1, whose content is 1.
                if (poly.DegreeIn(at) == 0)
                {
                    Front(poly, power);
                    return true;
                }
                if (Functions.PolynomialGcd.ContentIn(poly, at, rest, 0) is not { } content || poly.DivideExact(content) is not { } primitive)
                    return false;
                Front(content, power);
                parts.Add((primitive, power));
                return true;
            }

            var changed = false;
            for (var round = 0; round < 64; round++)
            {
                var split = false;
                for (var i = 0; i < parts.Count && !split; i++)
                {
                    var (poly, power) = parts[i];
                    // A factor repeated inside: what it shares with its derivative.
                    if (poly.DegreeIn(at) >= 2 && Functions.PolynomialGcd.Gcd(poly, poly.DerivativeIn(at), all, 0) is { } repeated
                        && repeated.DegreeIn(at) >= 1 && !IsAPowerOfX(repeated) && poly.DivideExact(repeated) is { } remaining)
                    {
                        parts.RemoveAt(i);
                        if (!Keep(repeated, power) || !Keep(remaining, power))
                            return null;
                        split = true;
                        break;
                    }
                    // Two factors that share one.
                    for (var j = i + 1; j < parts.Count; j++)
                    {
                        if (Functions.PolynomialGcd.Gcd(poly, parts[j].Poly, all, 0) is not { } common || common.DegreeIn(at) == 0 || IsAPowerOfX(common))
                            continue;
                        if (poly.DivideExact(common) is not { } left || parts[j].Poly.DivideExact(common) is not { } right)
                            return null;
                        var other = parts[j].Power;
                        parts.RemoveAt(j);
                        parts.RemoveAt(i);
                        if (!Keep(common, power + other) || !Keep(left, power) || !Keep(right, other))
                            return null;
                        split = true;
                        break;
                    }
                }
                if (!split)
                    break;
                changed = true;
            }

            // A factor that shares one with the numerator, taken apart the same way:
            // `(d + e x)^6/(a d e + (c d^2 + a e^2) x + c d e x^2)^4` is `(d + e x)^2/(a e + c d x)^4`.
            var top = MultivariatePolynomial.TryParse(numerator, indices);
            for (var round = 0; top is not null && round < 16; round++)
            {
                var split = false;
                for (var i = 0; i < parts.Count; i++)
                {
                    var (poly, power) = parts[i];
                    if (poly.DegreeIn(at) < 2 || Functions.PolynomialGcd.Gcd(top, poly, all, 0) is not { } common
                        || common.DegreeIn(at) == 0 || IsAPowerOfX(common) || common.DegreeIn(at) == poly.DegreeIn(at)
                        || poly.DivideExact(common) is not { } remaining)
                        continue;
                    parts.RemoveAt(i);
                    if (!Keep(common, power) || !Keep(remaining, power))
                        return null;
                    split = true;
                    break;
                }
                if (!split)
                    break;
                changed = true;
            }
            if (!changed)
                return null;

            // What the numerator shares with the factors, cancelled.
            Entity above = numerator;
            if (top is not null)
            {
                var cancelled = false;
                for (var i = 0; i < parts.Count; i++)
                    while (parts[i].Power > 0 && top.DivideExact(parts[i].Poly) is { } fewer)
                    {
                        top = fewer;
                        parts[i] = (parts[i].Poly, parts[i].Power - 1);
                        cancelled = true;
                    }
                if (cancelled)
                    above = top.ToEntity(variables);
            }
            // Each factor monic in x, the leading coefficient to its power in front, which is how
            // the integrator writes a factor: `d + e x` is `e (d/e + x)`, and written the other
            // way the next normalisation took `e` out again and the answer carried `e^(-8) e^8`.
            var monicFactors = new List<Entity>();
            foreach (var (poly, power) in parts)
            {
                if (power == 0)
                    continue;
                var lead = poly.LeadingCoefficientIn(at).ToEntity(variables);
                Entity monic = Number.Integer.Zero;
                foreach (var pair in poly.CoefficientsIn(at).OrderBy(pair => pair.Key))
                {
                    var coefficient = pair.Key == poly.DegreeIn(at) ? Number.Integer.One : Reduced(pair.Value.ToEntity(variables) / lead);
                    var term = pair.Key == 0 ? coefficient : coefficient * (pair.Key == 1 ? x : MathS.Pow(x, pair.Key));
                    monic = monic == Number.Integer.Zero ? term : monic + term;
                }
                monicFactors.Add(power == 1 ? monic : MathS.Pow(monic, power));
                var raised = power == 1 ? lead : MathS.Pow(lead, power);
                constant = constant == Number.Integer.One ? raised : constant * raised;
            }
            // The constant in lowest terms: the bars and the contents taken out of the factors
            // and the leading coefficients put back leave `e^(-8) e^8` in it as written.
            Entity below = Reduced(constant);
            foreach (var factor in monicFactors)
                below = below == Number.Integer.One ? factor : below * factor;
            return (above, below);

            static Entity Reduced(Entity constant)
                => constant.Vars.Any() ? Functions.PartialFractions.InLowestTermsOverTheSymbols(constant) : constant.InnerSimplified;
        }

        /// <summary>
        /// <paramref name="denominator"/> with every written factor that has rational coefficients
        /// and splits over the rationals written in its factors, where another written factor
        /// has a symbol in a coefficient; <see langword="null"/> where there is no such factor
        /// beside a symbolic one.
        /// </summary>
        /// <remarks>
        /// The split over symbolic linear factors reads the linears it finds written, and the
        /// refactoring over the rationals reads a denominator only when all of it is rational.
        /// The half-angle tangent writes `sec(x)^4/(a + b sin(x))^2` as
        /// `2 (1 + t^2)^5/((1 - t^2)^4 (a t^2 + 2 b t + a)^2)`, where `1 - t^2` is a quadratic to
        /// the one and the symbols beside it close the other, and the Hermite reduction took it:
        /// for `1/((1 - t^2)^3 (a t^2 + 2 b t + a)^2)` its one solve answered with coefficients over
        /// a polynomial of degree 48 in `a` and `b`, 514,694 characters to the first term, and did
        /// not return in 20 s. Written in its linears it is under a second.
        /// </remarks>
        private static Entity? WithRationalFactorsSplitBesideASymbolicOne(Entity denominator, Entity.Variable x)
        {
            var besideASymbol = false;
            var split = false;
            Entity product = Number.Integer.One;
            void Times(Entity factor) => product = product == Number.Integer.One ? factor : product * factor;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (b, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                if (!factor.ContainsNode(x) || @base.Vars.Any(v => v != x)
                    || Functions.PolynomialFactorization.FactorComplete(@base, x) is not { } factorization
                    || factorization.Parts.Count == 1 && factorization.Parts[0].Multiplicity == 1)
                {
                    besideASymbol |= factor.ContainsNode(x) && @base.Vars.Any(v => v != x);
                    Times(factor);
                    continue;
                }
                if (factorization.Constant.CompareTo(ERational.One) != 0)
                    Times(MathS.Pow(Number.Rational.Create(factorization.Constant), power));
                foreach (var part in factorization.Parts)
                {
                    var multiplicity = part.Multiplicity * power;
                    Times(multiplicity == 1 ? part.Factor.ToEntity(x) : MathS.Pow(part.Factor.ToEntity(x), multiplicity));
                }
                split = true;
            }
            return besideASymbol && split ? product : null;
        }

        private static Entity? TryWriteInIrreducibleFactors(Entity denominator, Entity.Variable x)
        {
            // Only where the written bases, each taken once, share a factor among them or
            // repeat one inside -- a product that is not squarefree -- can the spelling be
            // hiding what the rules below want written; written coprime squarefree bases to
            // whatever powers are the Hermite reduction's and the coprime split's as they
            // stand. One gcd decides that, where factoring every rational denominator cost
            // `(4x^5 - 1)/(x^5 + x + 1)^2` four times its answer.
            if (!HasARepeatedFactor(SquarefreePartAsWritten(denominator, x), x))
                return null;
            var writtenPowers = new List<int>();
            var gathered = new Dictionary<Entity, int>();
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant *= factor;
                    continue;
                }
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.Sign > 0 && e.EInteger.CanFitInInt32()
                    ? (b, e.EInteger.ToInt32Unchecked())
                    : (factor, 1);
                writtenPowers.Add(power);
                if (Functions.PolynomialFactorization.FactorComplete(@base, x) is not { } factorization)
                {
                    // Not a polynomial with rational coefficients: kept as written.
                    gathered[@base] = gathered.TryGetValue(@base, out var so) ? so + power : power;
                    continue;
                }
                if (factorization.Constant.CompareTo(ERational.One) != 0)
                    constant *= MathS.Pow(Number.Rational.Create(factorization.Constant), power);
                foreach (var part in factorization.Parts)
                {
                    var piece = part.Factor.ToEntity(x);
                    gathered[piece] = gathered.TryGetValue(piece, out var sofar) ? sofar + part.Multiplicity * power : part.Multiplicity * power;
                }
            }
            if (gathered.Count == 0)
                return null;
            var same = gathered.Count == writtenPowers.Count
                && gathered.Values.OrderBy(v => v).SequenceEqual(writtenPowers.OrderBy(v => v));
            if (same)
                return null;
            Entity product = constant.InnerSimplified;
            foreach (var pair in gathered)
            {
                Entity factor = pair.Value == 1 ? pair.Key : MathS.Pow(pair.Key, pair.Value);
                product = product == Number.Integer.One ? factor : product * factor;
            }
            return product;
        }

        /// <summary>
        /// Whether the polynomial <paramref name="expr"/> in <paramref name="x"/>, with rational
        /// coefficients, shares a factor of positive degree with its derivative.
        /// <see langword="false"/> where it is not such a polynomial.
        /// </summary>
        private static bool HasARepeatedFactor(Entity expr, Entity.Variable x)
        {
            if (!Functions.PolynomialFactoring.TryGetRationalCoefficients(
                    expr, x, leastTerms: 2, leastDegree: 2, IntegerPolynomial.MaxDegree, out var rational))
                return false;
            var denominator = EInteger.One;
            foreach (var coefficient in rational)
                denominator = denominator.Multiply(coefficient.Denominator).Divide(denominator.Gcd(coefficient.Denominator));
            var whole = new EInteger[rational.Length];
            for (var i = 0; i < whole.Length; i++)
                whole[i] = rational[i].Numerator.Multiply(denominator.Divide(rational[i].Denominator));
            var poly = IntegerPolynomial.Create(whole);
            return IntegerPolynomial.Gcd(poly, poly.Derivative()).Degree > 0;
        }

        /// <summary>
        /// The product of the distinct written factors of <paramref name="denominator"/>, each
        /// to the first power: the denominator of the logarithmic part of a Hermite reduction.
        /// </summary>
        private static Entity SquarefreePartAsWritten(Entity denominator, Entity.Variable x)
        {
            Entity product = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                    continue;
                var @base = factor is Powf(var b, Number.Integer power) && power.EInteger.Sign > 0 ? b : factor;
                product = product == Number.Integer.One ? @base : product * @base;
            }
            return product;
        }

        private static Entity? IntegrateByAnsatzOver(
            Entity? h, Entity p, Entity q, Entity above, Entity below, Entity d, Entity.Variable x,
            int degreeAbove, int degreeBelow)
        {
            var degreeD = TreeAnalyzer.TryGetPolynomial(d, x, out var dRead) && dRead.Count > 0
                ? (int)dRead.Keys.Max()!.ToInt32Checked() : 0;
            var degreeQ = TreeAnalyzer.TryGetPolynomial(q, x, out var qRead) && qRead.Count > 0
                ? (int)qRead.Keys.Max()!.ToInt32Checked() : 0;
            // Hermite's bound is `deg N < deg D`; with an exponential in front the numerator can
            // run past it by as much as the integrand's own excess and the exponent's
            // denominator -- `e^(x^2)(1 + 2x^2)` has `N = x` over `D = 1`. Two to spare either
            // way, since an unknown the system does not need is set to zero and costs nothing.
            var degreeN = System.Math.Max(degreeD - 1,
                degreeD + System.Math.Max(degreeAbove - degreeBelow, 0) + degreeQ + 2);
            if (degreeN > MaximumAnsatzDegree)
                return null;

            // With no exponential this is the Hermite reduction in full: `R = (N/D)' + M/D_1`,
            // with `D_1` the product of the distinct factors and `M` a second unknown
            // polynomial, so that a logarithmic part beside the rational one does not defeat
            // the ansatz -- `(1 + x^2 + x^4)/((1 + x^2)(4 + x^2)^2)` has both. What is left,
            // `M/D_1`, is a proper fraction over a squarefree denominator, which the splits
            // answer. With an exponential there is no logarithmic part to look for.
            Entity? squarefree = null;
            var degreeM = -1;
            if (h is null)
            {
                squarefree = SquarefreePartAsWritten(below, x);
                var degreeSquarefree = TreeAnalyzer.TryGetPolynomial(squarefree, x, out var sRead) && sRead.Count > 0
                    ? (int)sRead.Keys.Max()!.ToInt32Checked() : 0;
                if (degreeSquarefree > 0 && squarefree != below)
                    degreeM = degreeSquarefree - 1;
                else
                    squarefree = null;
            }

            // The identity, linear in the unknown coefficients, is built **one column at a
            // time** as a numeric polynomial rather than once with the unknowns in it: with
            // fourteen unknowns over a degree-eleven denominator the single symbolic expansion
            // did not return, and the same fourteen numeric ones take a moment. The identity is
            //
            //     [(N' D - N D') q^2 + (p' q - p q') N D] D_R  =  N_R D^2 q^2            (exponential)
            //     (N' D - N D') D_1 D_R + M D^2 D_R           =  N_R D^2 D_1            (Hermite)
            //
            // so the column for the k-th coefficient of N is the left side with N = x^k, the
            // column for the j-th of M is x^j D^2 D_R, and the right side is the constant.
            // In coefficient arithmetic rather than by expanding the products as expressions:
            // the expander estimates a product's terms before it collects them and declines
            // past two thousand, and `(u^4 - 7u^2 + 14)^10` beside its own powers is past that
            // long before the twenty-odd terms it collects to -- Welz's
            // `1/((3 - 2x)^(11/2) (1 + x + 2x^2)^5)` under `u = sqrt(3 - 2x)`.
            if (!TreeAnalyzer.TryGetPolynomial(d, x, out var dPoly) || !TreeAnalyzer.TryGetPolynomial(q, x, out var qPoly)
                || !TreeAnalyzer.TryGetPolynomial(p, x, out var pPoly) || !TreeAnalyzer.TryGetPolynomial(below, x, out var belowPoly)
                || !TreeAnalyzer.TryGetPolynomial(above, x, out var abovePoly))
                return null;
            Dictionary<EInteger, Entity>? squarefreePoly = null;
            if (squarefree is not null && !TreeAnalyzer.TryGetPolynomial(squarefree, x, out squarefreePoly))
                return null;
            var dPrimePoly = PolynomialDerivative(dPoly);
            var qSquared = PolynomialProduct(qPoly, qPoly);
            var dSquared = PolynomialProduct(dPoly, dPoly);
            var scale = squarefreePoly is null ? belowPoly : PolynomialProduct(squarefreePoly, belowPoly);
            var wronskian = h is null ? null : PolynomialDifference(PolynomialProduct(PolynomialDerivative(pPoly), qPoly), PolynomialProduct(pPoly, PolynomialDerivative(qPoly)));
            var columns = new List<Dictionary<EInteger, Entity>>();
            for (var k = 0; k <= degreeN; k++)
            {
                var xk = new Dictionary<EInteger, Entity> { [k] = Number.Integer.One };
                var xkPrime = k == 0 ? new Dictionary<EInteger, Entity>() : new Dictionary<EInteger, Entity> { [k - 1] = Number.Integer.Create(k) };
                var term = PolynomialProduct(PolynomialDifference(PolynomialProduct(xkPrime, dPoly), PolynomialProduct(xk, dPrimePoly)), qSquared);
                if (wronskian is not null)
                    term = PolynomialSum(term, PolynomialProduct(PolynomialProduct(wronskian, xk), dPoly));
                columns.Add(PolynomialProduct(term, scale));
            }
            var dSquaredBelow = PolynomialProduct(dSquared, belowPoly);
            for (var j = 0; j <= degreeM; j++)
                columns.Add(PolynomialProduct(new Dictionary<EInteger, Entity> { [j] = Number.Integer.One }, dSquaredBelow));
            var targetRead = squarefreePoly is null
                ? PolynomialProduct(PolynomialProduct(abovePoly, dSquared), qSquared)
                : PolynomialProduct(PolynomialProduct(abovePoly, dSquared), squarefreePoly);

            // The rows by their power of x, not in the order the dictionaries met them: that order
            // is the spelling's, and the elimination's pivots follow it. `(1 + x^2)^3` below the bar
            // where `(x^2 + 1)^3` is written left the solution in coefficients of the thirty-sixth
            // degree in the symbols that nothing cancelled, and the logarithmic part they made was
            // forty seconds of declining; in the one order both are under a second.
            var powers = columns.SelectMany(c => c.Keys).Concat(targetRead.Keys).Distinct().OrderBy(power => power).ToList();
            var width = columns.Count;
            var matrix = new Entity[powers.Count][];
            var rhs = new Entity[powers.Count];
            for (var row = 0; row < powers.Count; row++)
            {
                matrix[row] = new Entity[width];
                for (var column = 0; column < width; column++)
                    matrix[row][column] = columns[column].TryGetValue(powers[row], out var entry) ? entry.InnerSimplified : Number.Integer.Zero;
                rhs[row] = targetRead.TryGetValue(powers[row], out var wanted) ? wanted.InnerSimplified : Number.Integer.Zero;
            }
            if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values))
                return null;

            Entity solvedN = 0;
            for (var k = 0; k <= degreeN; k++)
                if (values[k] != Number.Integer.Zero)
                    solvedN += values[k] * (k == 0 ? Number.Integer.One : k == 1 ? x : MathS.Pow(x, k));
            Entity solvedM = 0;
            for (var j = 0; j <= degreeM; j++)
                if (values[degreeN + 1 + j] != Number.Integer.Zero)
                    solvedM += values[degreeN + 1 + j] * (j == 0 ? Number.Integer.One : j == 1 ? x : MathS.Pow(x, j));
            solvedN = Functions.PartialFractions.Bare(solvedN);
            solvedM = Functions.PartialFractions.Bare(solvedM);

            Entity exponential = h is null ? Number.Integer.One : MathS.Pow(MathS.e, h);
            var rationalPart = exponential * solvedN / d;
            var integrand = exponential * above / below;
            // Over the rationals the identity is checked coefficient by coefficient, exactly,
            // which is what the solve established; the sampled check is for symbols, and on a
            // rational part of degree fifty-eight it was four seconds of differentiating.
            var checkedExactly = IdentityHoldsExactly(columns, values, targetRead);
            if (squarefree is null)
            {
                if (!checkedExactly && !Functions.PartialFractions.HoldsAtSampledPoints(rationalPart.Differentiate(x), integrand, x))
                    return null;
                return rationalPart.InnerSimplified;
            }

            var logarithmicPart = solvedM / squarefree;
            if (!checkedExactly && !Functions.PartialFractions.HoldsAtSampledPoints(rationalPart.Differentiate(x) + logarithmicPart, integrand, x))
                return null;
            if (solvedM == Number.Integer.Zero || solvedM.Evaled is Number.Complex { IsZero: true })
                return rationalPart.InnerSimplified;
            // The logarithmic part is a proper rational function over a squarefree denominator,
            // and the splits are what answer that; handing it to the whole integrator instead
            // sent one of them through every substitution and by-parts attempt there is, thirty
            // seconds to decline what the splits decline in a few milliseconds.
            // The rest is checked as the ansatz was: a logarithmic part whose coefficients
            // came out of the elimination as quotients of forty-fifth-degree polynomials in
            // the symbols was integrated wrongly further down, and the sum was a wrong answer
            // that every part of the way had passed.
            // https://github.com/asc-community/AngouriMath/issues/1369
            if (SolveByPartialFractions(logarithmicPart.InnerSimplified, x, integrateByParts: false) is not { } rest
                || !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(rest, logarithmicPart, x))
                return null;
            return (rationalPart + rest).InnerSimplified;
        }

        /// <summary>
        /// The largest degree, of the numerator, the denominator or the ansatz polynomial, that
        /// <see cref="SolveByExponentialAnsatz"/> and the Hermite reduction take on. Twelve
        /// while the system was eliminated as expressions; over the rationals it is lifted
        /// p-adically, and sixty-three unknowns -- Welz's <c>1/((3 - 2x)^(21/2) (1 + x + 2x^2)^10)</c>
        /// under <c>u = sqrt(3 - 2x)</c> -- are fifty milliseconds.
        /// </summary>
        private const int MaximumAnsatzDegree = 64;

        /// <summary>
        /// A power of x times a whole power of its logarithm, <c>x^p ln(x)^n</c>, by the
        /// closed reduction
        /// <c>x^(p + 1) sum_(k = 0..n) (-1)^k n!/(n - k)! ln(x)^(n - k)/(p + 1)^(k + 1)</c>, for
        /// any <c>p</c> but <c>-1</c>, where it is <c>ln(x)^(n + 1)/(n + 1)</c>. And the same
        /// for <c>F = A + B ln(c x^r)</c> in the logarithm's place, whose derivative is
        /// <c>s/x</c> for <c>s = B r</c>: each step of parts brings a factor <c>s</c>, so the
        /// sum is over <c>(-s)^k n!/(n - k)! F^(n - k)/(p + 1)^(k + 1)</c>, and at <c>p = -1</c>
        /// it is <c>F^(n + 1)/((n + 1) s)</c>. Rubi's <c>(e x)^q (a + b ln(c x^n))^3</c>, and
        /// <c>t^(-2 - m) (A + B ln(e t^n))^2</c> in the variable of the quotient substitution.
        /// </summary>
        /// <remarks>
        /// By parts <c>n</c> times, written out: each step takes one from the power of the
        /// logarithm and divides by <c>p + 1</c>. Timofeev's <c>x^m ln(x)^2</c> and
        /// <c>ln(x)^2/x^(5/2)</c> had no antiderivative -- the first step of by parts was
        /// taken and the second, on <c>x^m ln(x)</c> with the symbol still in the exponent,
        /// was not -- where <c>x^m ln(x)</c> and <c>x^2 ln(x)^2</c> were answered. Closed, exact,
        /// and volunteered at any depth.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPowerTimesAPowerOfTheLogarithm(Entity expr, Entity.Variable x)
        {
            Entity? p = null;
            var n = 0;
            Entity constant = Number.Integer.One;
            var logarithm = MathS.Ln(x);
            Entity? affine = null;   // F, where the factor is a power of A + B ln(c x^r) and not of ln x
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor == x && p is null)
                    p = underneath ? Number.Integer.MinusOne : Number.Integer.One;
                else if (factor is Powf(var @base, var exponent) && @base == x && !exponent.ContainsNode(x) && p is null)
                    p = underneath ? -exponent : exponent;
                else if (factor is Powf(Mulf(var scale, var scaled), var scaledExponent) && scaled == x && !scale.ContainsNode(x) && !scaledExponent.ContainsNode(x) && p is null)
                {
                    // `(d x)^m` as `d^m x^m`, the generic case, as the table's power rule takes it.
                    p = underneath ? -scaledExponent : scaledExponent;
                    var scalePower = MathS.Pow(scale, scaledExponent);
                    constant = underneath ? constant / scalePower : constant * scalePower;
                }
                else if (factor == logarithm && n == 0 && !underneath)
                    n = 1;
                else if (factor is Powf(var l, Number.Integer whole) && l == logarithm && whole.EInteger.Sign > 0 && whole.EInteger.CanFitInInt32() && n == 0 && !underneath)
                    n = whole.EInteger.ToInt32Unchecked();
                else if (n == 0 && !underneath && factor is not Powf && IsAffineInALogarithmOfAPowerOfX(factor, x))
                    (affine, n) = (factor, 1);
                else if (n == 0 && !underneath && factor is Powf(var f, Number.Integer wholeOfF) && wholeOfF.EInteger.Sign > 0 && wholeOfF.EInteger.CanFitInInt32() && IsAffineInALogarithmOfAPowerOfX(f, x))
                    (affine, n) = (f, wholeOfF.EInteger.ToInt32Unchecked());
                else
                    return null;
            }
            if (n == 0 || n > 12 || p is null && affine is null)
                return null;
            // A power of F alone is the case p = 0.
            p = (p ?? Number.Integer.Zero).InnerSimplified;
            if (p.Evaled is Number.Complex and not Number.Real)
                return null;
            // The factor F and s with F' = s/x: ln x itself, or A + B ln(c x^r) with s = B r.
            Entity slopeOfF = Number.Integer.One;
            if (affine is { })
            {
                logarithm = affine;
                slopeOfF = Functions.PartialFractions.Bare((affine.Differentiate(x) * x).Simplify());
                if (slopeOfF.ContainsNode(x) || slopeOfF.Evaled is Number.Complex { IsZero: true })
                    return null;
            }
            if ((p + 1).InnerSimplified.Evaled is Number.Complex { IsZero: true })
                return (constant * MathS.Pow(logarithm, n + 1) / ((n + 1) * slopeOfF)).InnerSimplified;
            // Written out term by term, each with its coefficient folded: the derivative of
            // `x^3 ln(x)/3 - x^3/9` cancels symbolically against `x^2 ln(x)`, where a nested
            // `x^3 (ln(x)/3 - 1/9)` left a residual the simplifier did not close.
            var pPlusOne = (p + 1).InnerSimplified;
            var powerOfX = MathS.Pow(x, pPlusOne);
            Entity sum = Number.Integer.Zero;
            var fallingFactorial = EInteger.One;   // n!/(n - k)!
            for (var k = 0; k <= n; k++)
            {
                if (k > 0)
                    fallingFactorial = fallingFactorial.Multiply(EInteger.FromInt32(n - k + 1));
                var sign = k % 2 == 0 ? Number.Integer.One : Number.Integer.MinusOne;
                var slopePower = k == 0 || slopeOfF == Number.Integer.One ? Number.Integer.One : MathS.Pow(slopeOfF, k);
                var coefficient = (constant * sign * Number.Integer.Create(fallingFactorial) * slopePower / MathS.Pow(pPlusOne, k + 1)).InnerSimplified;
                Entity term = n - k == 0 ? coefficient * powerOfX : coefficient * powerOfX * (n - k == 1 ? logarithm : MathS.Pow(logarithm, n - k));
                sum = sum == Number.Integer.Zero ? term : sum + term;
            }
            return sum.InnerSimplified;
        }

        /// <summary>
        /// A power of x times a half-odd power of a logarithm, <c>x^p F^n</c> with <c>F</c> =
        /// <c>ln x</c> or <c>A + B ln(c x^r)</c> and <c>2n</c> odd, onto the Gaussian's moments.
        /// With <c>t = sqrt(F)</c> and <c>F' = s/x</c>, <c>dx = 2 x t dt/s</c>, and
        /// <c>x^(p + 1) e^(-(p + 1) F/s)</c> is a constant, so the integral is that constant times
        /// <c>2/s</c> times the integral of <c>t^(2n + 1) e^((p + 1) t^2/s)</c>: an even moment of
        /// the Gaussian, which the table answers. At <c>p = -1</c> it is
        /// <c>F^(n + 1)/(s (n + 1))</c>. Rubi's 3.1.2, <c>(d x)^m (a + b ln(c x^n))^p</c> for a
        /// half-odd <c>p</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// The constant is written <c>x^(p + 1) e^(-(p + 1) F/s)</c>, as Rubi writes it, rather
        /// than with <c>ln(c x^r)</c> split into <c>ln c + r ln x</c>, which holds only where
        /// <c>c</c> is positive. The logarithm to the right of a whole power of it is
        /// <see cref="SolveAPowerTimesAPowerOfTheLogarithm"/>'s.
        /// </remarks>
        internal static Entity? SolveAPowerTimesAHalfOddPowerOfTheLogarithm(Entity expr, Entity.Variable x)
        {
            Entity? p = null;
            Number.Rational? n = null;
            Entity constant = Number.Integer.One;
            Entity? logarithm = null;
            Dictionary<EInteger, Entity>? polynomial = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor == x && p is null)
                    p = underneath ? Number.Integer.MinusOne : Number.Integer.One;
                else if (factor is Powf(var @base, var exponent) && @base == x && !exponent.ContainsNode(x) && p is null)
                    p = underneath ? -exponent : exponent;
                else if (factor is Powf(Mulf(var scale, var scaled), var scaledExponent) && scaled == x && !scale.ContainsNode(x) && !scaledExponent.ContainsNode(x) && p is null)
                {
                    p = underneath ? -scaledExponent : scaledExponent;
                    var scalePower = MathS.Pow(scale, scaledExponent);
                    constant = underneath ? constant / scalePower : constant * scalePower;
                }
                else if (n is null && factor is Powf(var f, Number.Rational half) && half.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                {
                    if (f == MathS.Ln(x) || IsAffineInALogarithmOfAPowerOfX(f, x))
                        (logarithm, n) = (f, underneath ? Number.Rational.Create(-half.ERational) : half);
                    // The logarithm of a power of a linear, Rubi's 3.3: the same question under
                    // u = d + e x. Declined, it was integrated by parts against the half-odd
                    // power's own antiderivative, which took (f + g x) (a + b ln(c (d + e x)^n))^(3/2)
                    // 37 s to give up.
                    else if (LinearUnderALogarithm(f, x) is { } linear)
                        return ByTheLinearUnderTheLogarithm(expr, x, linear);
                    else
                        return null;
                }
                // A polynomial beside it, which is how a linear outside the logarithm arrives once
                // the linear inside it has been substituted: summed a power at a time.
                else if (polynomial is null && !underneath && TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials)
                         && monomials.Count > 1 && monomials.Keys.All(power => power.Sign >= 0 && power.CompareTo(EInteger.FromInt32(12)) <= 0))
                    polynomial = monomials;
                else
                    return null;
            }
            if (logarithm is null || n is null)
                return null;
            p = (p ?? Number.Integer.Zero).InnerSimplified;
            if (p.Evaled is Number.Complex and not Number.Real)
                return null;
            Entity slopeOfF = Number.Integer.One;
            if (logarithm != MathS.Ln(x))
            {
                slopeOfF = Functions.PartialFractions.Bare((logarithm.Differentiate(x) * x).Simplify());
                if (slopeOfF.ContainsNode(x) || slopeOfF.Evaled is Number.Complex { IsZero: true })
                    return null;
            }
            if (polynomial is null)
                return HalfOddLogarithmicTerm(p, logarithm, n, slopeOfF, x) is { } single ? (constant * single).InnerSimplified : null;
            Entity sum = Number.Integer.Zero;
            foreach (var monomial in polynomial)
            {
                if (HalfOddLogarithmicTerm((p + Number.Integer.Create(monomial.Key)).InnerSimplified, logarithm, n, slopeOfF, x) is not { } term)
                    return null;
                sum += monomial.Value * term;
            }
            return (constant * sum).InnerSimplified;
        }

        /// <summary>
        /// The linear <c>d + e x</c>, with <c>d</c> not zero, whose powers and constant multiples
        /// make up the argument of the one logarithm in <paramref name="expr"/>, or
        /// <see langword="null"/>.
        /// </summary>
        private static Entity? LinearUnderALogarithm(Entity expr, Entity.Variable x)
        {
            Entity? argument = null;
            foreach (var node in expr.Nodes)
                if (node is Logf(var @base, var antilogarithm) && @base == MathS.e && antilogarithm.ContainsNode(x))
                {
                    if (argument is not null && argument != antilogarithm)
                        return null;
                    argument = antilogarithm;
                }
            if (argument is null)
                return null;
            foreach (var node in argument.Nodes)
                if (node is Sumf or Minusf && TreeAnalyzer.TryGetPolyLinear(node, x, out var slope, out var intercept)
                    && !TreeAnalyzer.IsZero(slope) && !TreeAnalyzer.IsZero(intercept))
                {
                    var placeholder = Variable.CreateUnique(argument, "u_lin");
                    var inThePlaceholder = argument.Replace(child => child == node ? placeholder : child);
                    return !inThePlaceholder.ContainsNode(x) && IsAProductOfPowersOfTheVariable(inThePlaceholder, placeholder) ? node : null;
                }
            return null;
        }

        /// <summary>
        /// <paramref name="expr"/> under <c>u = d + e x</c>, with <paramref name="linear"/> the
        /// <c>d + e x</c> under its logarithm, answered as a power or a polynomial of <c>u</c>
        /// beside a half-odd power of <c>A + B ln(c u^r)</c> and written back in <c>x</c>.
        /// </summary>
        private static Entity? ByTheLinearUnderTheLogarithm(Entity expr, Entity.Variable x, Entity linear)
        {
            if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out var intercept) || slope is null || intercept is null)
                return null;
            var u = Variable.CreateUnique(expr, "u");
            var inU = (expr.Replace(node => node == linear ? u : node).Substitute(x, (u - intercept) / slope) / slope).InnerSimplified;
            if (inU.ContainsNode(x) || LinearUnderALogarithm(inU, u) is not null)
                return null;
            return SolveAPowerTimesAHalfOddPowerOfTheLogarithm(inU, u)?.Substitute(u, linear).InnerSimplified;
        }

        /// <summary>
        /// The integral of <c>x^q F^n</c> for a half-odd <c>n</c> and <c>F' = s/x</c>: see
        /// <see cref="SolveAPowerTimesAHalfOddPowerOfTheLogarithm"/>.
        /// </summary>
        private static Entity? HalfOddLogarithmicTerm(Entity q, Entity logarithm, Number.Rational n, Entity slopeOfF, Entity.Variable x)
        {
            var qPlusOne = (q + 1).InnerSimplified;
            if (qPlusOne.Evaled is Number.Complex { IsZero: true })
                return MathS.Pow(logarithm, n + 1) / ((n + 1) * slopeOfF);
            // t^(2n + 1) e^((q + 1) t^2/s) in a variable of its own, for the table's moments.
            var t = Variable.CreateUnique(logarithm, "t");
            var power = (2 * n.ERational + ERational.One).ToEInteger();
            if (!power.CanFitInInt32() || power.Abs().CompareTo(EInteger.FromInt32(32)) > 0)
                return null;
            var gaussian = MathS.Pow(MathS.e, (qPlusOne / slopeOfF).InnerSimplified * MathS.Sqr(t));
            var inT = power.IsZero ? gaussian : MathS.Pow(t, Number.Integer.Create(power)) * gaussian;
            if (IntegralPatterns.TryStandardIntegrals(inT, t) is not { } answerInT)
                return null;
            // x^(q + 1) e^(-(q + 1) ln(x)) is 1 wherever ln(x) is real, so for ln(x) itself it is left out.
            Entity theConstant = logarithm == MathS.Ln(x)
                ? Number.Integer.One
                : MathS.Pow(x, qPlusOne) * MathS.Pow(MathS.e, -qPlusOne * logarithm / slopeOfF);
            return 2 / slopeOfF * theConstant * answerInT.Substitute(t, MathS.Sqrt(logarithm));
        }

        /// <summary>
        /// A power of x over a whole power of an affine function of a logarithm,
        /// <c>x^p (A + B L)^(-k)</c> with <c>L = ln(c x^r)</c>, onto the exponential integral. With
        /// <c>t = A + B L</c> and <c>L' = s/x</c>, <c>dx = x dt/(B s)</c>, and
        /// <c>x^(p + 1) e^(-(p + 1) t/(B s))</c> is a constant, so the integral is that constant over
        /// <c>B s</c> times <c>int e^((p + 1) t/(B s)) t^(-k) dt</c>, which is <c>Ei</c> by parts. A
        /// polynomial beside it is summed a power at a time, and the logarithm of a power of a linear
        /// is the same question under <c>u = d + e x</c>. Rubi's 3.1.2 and 3.3,
        /// <c>(d x)^m/(a + b ln(c x^n))^k</c>; <c>1/ln(x)</c> is <c>Ei(ln x)</c>, which is <c>li(x)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// The constant is written as <see cref="SolveAPowerTimesAHalfOddPowerOfTheLogarithm"/>
        /// writes it, and for <c>ln(x)</c> itself it is <c>e^(-(p + 1) A/B)</c>, wherever <c>ln(x)</c>
        /// is real. Beside <c>1/x</c> the rate is 0 and the integral is a power of <c>t</c>, which the
        /// rules for logarithms answer.
        /// </remarks>
        internal static Entity? SolveAPowerOverAPowerOfALogarithm(Entity expr, Entity.Variable x)
        {
            if (expr is not (Divf or Powf or Mulf) || !expr.Nodes.Any(node => node is Logf))
                return null;
            Entity? p = null;
            Entity constant = Number.Integer.One;
            Entity? affine = null;
            var k = 0;
            Dictionary<EInteger, Entity>? polynomial = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor == x && p is null)
                    p = underneath ? Number.Integer.MinusOne : Number.Integer.One;
                else if (factor is Powf(var @base, var exponent) && @base == x && !exponent.ContainsNode(x) && p is null)
                    p = underneath ? -exponent : exponent;
                // (g x)^m, as a substitution u = (a + b x)/(c + d x) leaves (a g + b g x)^m.
                else if (factor is Powf(Mulf(var left, var right), var scaledExponent) && (left == x) != (right == x)
                         && !(left == x ? right : left).ContainsNode(x) && !scaledExponent.ContainsNode(x) && p is null)
                {
                    p = underneath ? -scaledExponent : scaledExponent;
                    var scalePower = MathS.Pow(left == x ? right : left, scaledExponent);
                    constant = underneath ? constant / scalePower : constant * scalePower;
                }
                else if (affine is null && AReciprocalPowerOfALogarithm(factor, underneath, x) is { } read)
                    (affine, k) = read;
                else if (polynomial is null && !underneath && TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials)
                         && monomials.Count > 1 && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                    polynomial = monomials;
                else
                    return null;
            }
            if (affine is null || k < 1 || k > 12)
                return null;
            if (TheLogarithmOfAPowerOfX(affine, x) is not { } logarithm)
            {
                if (LinearUnderALogarithm(affine, x) is { } linear)
                    return UnderTheLinearUnderTheLogarithm(expr, x, linear, SolveAPowerOverAPowerOfALogarithm);
                // A power of x inside, d + e x^m, beside x^(j m - 1): the same question under u = x^m,
                // as Rubi's 3.4 asks it. Left to the substitution search, the search took it by parts
                // first, down every choice, past the budget.
                if (polynomial is null && p?.InnerSimplified is Number.Integer { EInteger: var pw } && pw.CanFitInInt32()
                    && APowerOfXUnderALogarithm(affine, x) is { } m && (pw.ToInt32Checked() + 1) % m == 0 && (pw.ToInt32Checked() + 1) / m >= 1)
                {
                    var u = Variable.CreateUnique(expr, "u");
                    var affineInU = affine.Replace(node => node is Powf(var b, Number.Integer n) && b == x && n.EInteger.Equals(EInteger.FromInt32(m)) ? u : node);
                    if (affineInU.ContainsNode(x))
                        return null;
                    var j = (pw.ToInt32Checked() + 1) / m;
                    var inU = (j == 1 ? Number.Integer.One : MathS.Pow(u, j - 1)) * MathS.Pow(affineInU, -k) * constant / m;
                    return SolveAPowerOverAPowerOfALogarithm(inU, u)?.Substitute(u, MathS.Pow(x, m)).InnerSimplified;
                }
                return null;
            }
            var t = Variable.CreateUnique(expr, "t");
            if (!TreeAnalyzer.TryGetPolyLinear(affine.Replace(node => node == logarithm ? t : node), t, out var slope, out var intercept)
                || slope.ContainsNode(x) || intercept.ContainsNode(x) || TreeAnalyzer.IsZero(slope))
                return null;
            var rate = Functions.PartialFractions.Bare((logarithm.Differentiate(x) * x).Simplify());
            if (rate.ContainsNode(x) || rate.Evaled is Number.Complex { IsZero: true } || rate.Nodes.Any(node => node == MathS.NaN))
                return null;
            p = (p ?? Number.Integer.Zero).InnerSimplified;
            // Bare: the simplification attaches `provided not B r = 0` to the quotients it
            // cancels, and the generic case is what every rule answers in. Carried, it is what a
            // substitution above checks the answer's derivative against, and fails at every point.
            if (polynomial is null)
                return AReciprocalPowerOfALogarithmTerm(p, affine, k, logarithm, slope, intercept, rate, x) is { } single
                    ? Functions.PartialFractions.Bare((constant * single).InnerSimplified) : null;
            Entity sum = Number.Integer.Zero;
            foreach (var monomial in polynomial)
            {
                if (AReciprocalPowerOfALogarithmTerm((p + Number.Integer.Create(monomial.Key)).InnerSimplified, affine, k, logarithm, slope, intercept, rate, x) is not { } term)
                    return null;
                sum += monomial.Value * term;
            }
            return Functions.PartialFractions.Bare((constant * sum).InnerSimplified);
        }

        /// <summary>
        /// <c>m</c> where the one logarithm in <paramref name="expr"/> holds <c>d + e x^m</c> for a whole
        /// <c>m >= 2</c>, <c>d</c> not zero, or <see langword="null"/>.
        /// </summary>
        private static int? APowerOfXUnderALogarithm(Entity expr, Entity.Variable x)
        {
            foreach (var node in expr.Nodes)
                if (node is Logf(var @base, var argument) && @base == MathS.e && argument.ContainsNode(x))
                    foreach (var inner in argument.Nodes)
                        if (inner is Sumf or Minusf && TreeAnalyzer.TryGetPolynomial(inner, x, out var monomials)
                            && monomials.Count == 2 && monomials.ContainsKey(EInteger.Zero) && !TreeAnalyzer.IsZero(monomials[EInteger.Zero])
                            && monomials.Keys.Max() is { } degree && degree.CompareTo(EInteger.One) > 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0)
                            return degree.ToInt32Checked();
            return null;
        }

        /// <summary>
        /// <c>(F, k)</c> where <paramref name="factor"/> is <c>F^(-k)</c> above the bar or <c>F^k</c>
        /// below it, for a whole <c>k >= 1</c> and <c>F</c> holding a logarithm of <paramref name="x"/>.
        /// </summary>
        private static (Entity Affine, int Power)? AReciprocalPowerOfALogarithm(Entity factor, bool underneath, Entity.Variable x)
        {
            var (inner, power) = factor is Powf(var b, Number.Integer n) && n.EInteger.CanFitInInt32() ? (b, n.EInteger.ToInt32Checked()) : (factor, 1);
            if (!underneath)
                power = -power;
            return power > 0 && inner.Nodes.Any(node => node is Logf(_, var argument) && argument.ContainsNode(x)) ? (inner, power) : null;
        }

        /// <summary>
        /// The integral of <c>x^q F^(-k)</c> for <c>F = A + B L</c> and <c>L' = s/x</c>: see
        /// <see cref="SolveAPowerOverAPowerOfALogarithm"/>.
        /// </summary>
        private static Entity? AReciprocalPowerOfALogarithmTerm(Entity q, Entity affine, int k, Entity logarithm, Entity slope, Entity intercept, Entity rate, Entity.Variable x)
        {
            var qPlusOne = (q + 1).InnerSimplified;
            if (qPlusOne.Evaled is Number.Complex { IsZero: true })
                return null;
            var t = Variable.CreateUnique(affine, "t");
            var growth = (qPlusOne / (slope * rate)).InnerSimplified;
            var (elementaryInT, eiInT) = APowerTimesAnExponential(-k, growth, MathS.Pow(MathS.e, growth * t), t);
            var inT = elementaryInT + eiInT * MathS.Ei(growth * t);
            // x^(q + 1) e^(-(q + 1) t/(B s)), which for ln(x) itself is e^(-(q + 1) A/B).
            Entity theConstant = logarithm == MathS.Ln(x)
                ? MathS.Pow(MathS.e, (-qPlusOne * intercept / slope).InnerSimplified)
                : MathS.Pow(x, qPlusOne) * MathS.Pow(MathS.e, -growth * affine);
            return theConstant / (slope * rate) * inT.Substitute(t, affine);
        }

        /// <summary>
        /// A power of x times an exponential of a quadratic in a logarithm, <c>x^p G^(Q(L))</c> with
        /// <c>L</c> = <c>ln(c x^r)</c> and <c>Q</c> a quadratic with a square term, onto the
        /// Gaussian. With <c>t = L</c> and <c>L' = s/x</c>, <c>dx = x dt/s</c>, and
        /// <c>x^(p + 1) e^(-(p + 1) L/s)</c> is a constant, so the integral is that constant over
        /// <c>s</c> times the integral of <c>e^(Q(t) ln G + (p + 1) t/s)</c>: the Gaussian with a
        /// linear term, which the table answers. A polynomial beside it is summed a power at a time,
        /// and the logarithm of a power of a linear is the same question under <c>u = d + e x</c>.
        /// Rubi's 2.3, <c>F^(f (a + b ln(c (d + e x)^n))^2) (g + h x)^m</c> and
        /// <c>F^(f (a + b ln(c (d + e x)^n)^2)) (g + h x)^m</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// The constant is written <c>x^(p + 1) e^(-(p + 1) L/s)</c>, as
        /// <see cref="SolveAPowerTimesAHalfOddPowerOfTheLogarithm"/> writes it and as Rubi does,
        /// rather than with <c>ln(c x^r)</c> split into <c>ln c + r ln x</c>, which holds only
        /// where <c>c</c> is positive. A quadratic without its square term is a power of
        /// <c>c x^r</c>, which the rules for powers answer.
        /// </remarks>
        internal static Entity? SolveAPowerTimesAnExponentialOfAQuadraticInALogarithm(Entity expr, Entity.Variable x)
        {
            // The exponential and its logarithm first, which allocates nothing where there is
            // none; and the logarithm of a linear before any factor is read, since beside it a
            // constant multiple of that linear, (d g + e g x)^m, is a factor only in u.
            if (expr is not (Mulf or Divf or Powf) || AnExponentialOfALogarithm(expr, x) is not { } theExponential)
                return null;
            if (TheLogarithmOfAPowerOfX(theExponential.Exponent, x) is not { } logarithm)
                return LinearUnderALogarithm(theExponential.Exponent, x) is { } linear ? UnderTheLinearUnderTheLogarithm(expr, x, linear, SolveAPowerTimesAnExponentialOfAQuadraticInALogarithm) : null;
            Entity? p = null;
            Entity constant = Number.Integer.One;
            Entity? @base = null, exponent = null;
            Dictionary<EInteger, Entity>? polynomial = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor == x && p is null)
                    p = underneath ? Number.Integer.MinusOne : Number.Integer.One;
                else if (factor is Powf(var b, var e) && b == x && !e.ContainsNode(x) && p is null)
                    p = underneath ? -e : e;
                else if (factor is Powf(Mulf(var left, var right), var scaledExponent) && (left == x) != (right == x)
                         && !(left == x ? right : left).ContainsNode(x) && !scaledExponent.ContainsNode(x) && p is null)
                {
                    p = underneath ? -scaledExponent : scaledExponent;
                    var scalePower = MathS.Pow(left == x ? right : left, scaledExponent);
                    constant = underneath ? constant / scalePower : constant * scalePower;
                }
                else if (exponent is null && factor is Powf(var g, var power) && !g.ContainsNode(x) && power.ContainsNode(x))
                    (@base, exponent) = (g, underneath ? -power : power);
                else if (polynomial is null && !underneath && TreeAnalyzer.TryGetPolynomial(factor, x, out var monomials)
                         && monomials.Count > 1 && monomials.Keys.All(degree => degree.Sign >= 0 && degree.CompareTo(EInteger.FromInt32(12)) <= 0))
                    polynomial = monomials;
                else
                    return null;
            }
            if (@base is null || exponent is null || !exponent.ContainsNode(logarithm))
                return null;
            var t = Variable.CreateUnique(expr, "t");
            var inT = exponent.Replace(node => node == logarithm ? t : node);
            if (inT.ContainsNode(x) || !TreeAnalyzer.TryGetPolyQuadratic(inT, t, out var square, out _, out _) || TreeAnalyzer.IsZero(square))
                return null;
            var rate = Functions.PartialFractions.Bare((logarithm.Differentiate(x) * x).Simplify());
            if (rate.ContainsNode(x) || rate.Evaled is Number.Complex { IsZero: true } || rate.Nodes.Any(node => node == MathS.NaN))
                return null;
            var exponentInT = @base == MathS.e ? inT : inT * MathS.Ln(@base);
            p = (p ?? Number.Integer.Zero).InnerSimplified;
            if (polynomial is null)
                return ExponentialOfAQuadraticInALogarithmTerm(p, exponentInT, t, logarithm, rate, x) is { } single ? (constant * single).InnerSimplified : null;
            Entity sum = Number.Integer.Zero;
            foreach (var monomial in polynomial)
            {
                if (ExponentialOfAQuadraticInALogarithmTerm((p + Number.Integer.Create(monomial.Key)).InnerSimplified, exponentInT, t, logarithm, rate, x) is not { } term)
                    return null;
                sum += monomial.Value * term;
            }
            return (constant * sum).InnerSimplified;
        }

        /// <summary>
        /// The integral of <c>x^q e^(E(L))</c>, where <paramref name="exponentInT"/> is <c>E</c> in
        /// <paramref name="t"/> standing for <paramref name="logarithm"/> and <c>L' = s/x</c>: see
        /// <see cref="SolveAPowerTimesAnExponentialOfAQuadraticInALogarithm"/>.
        /// </summary>
        private static Entity? ExponentialOfAQuadraticInALogarithmTerm(Entity q, Entity exponentInT, Entity.Variable t, Entity logarithm, Entity rate, Entity.Variable x)
        {
            var qPlusOne = (q + 1).InnerSimplified;
            var atMinusOne = qPlusOne.Evaled is Number.Complex { IsZero: true };
            var inT = MathS.Pow(MathS.e, atMinusOne ? exponentInT : exponentInT + qPlusOne / rate * t);
            if (IntegralPatterns.TryStandardIntegrals(inT, t) is not { } answerInT)
                return null;
            // x^(q + 1) e^(-(q + 1) ln(x)) is 1 wherever ln(x) is real, so for ln(x) itself it is left out.
            Entity theConstant = atMinusOne || logarithm == MathS.Ln(x)
                ? Number.Integer.One
                : MathS.Pow(x, qPlusOne) * MathS.Pow(MathS.e, -qPlusOne * logarithm / rate);
            return theConstant / rate * answerInT.Substitute(t, logarithm);
        }

        /// <summary>
        /// A factor of <paramref name="expr"/> that is an exponential of <paramref name="x"/> with a
        /// logarithm in its exponent, read through products and quotients, or <see langword="null"/>.
        /// </summary>
        private static Powf? AnExponentialOfALogarithm(Entity expr, Entity.Variable x) => expr switch
        {
            Mulf(var left, var right) => AnExponentialOfALogarithm(left, x) ?? AnExponentialOfALogarithm(right, x),
            Divf(var numerator, var denominator) => AnExponentialOfALogarithm(numerator, x) ?? AnExponentialOfALogarithm(denominator, x),
            Powf(var @base, var exponent) power when !@base.ContainsNode(x) && exponent.ContainsNode(x)
                && exponent.Nodes.Any(node => node is Logf) => power,
            _ => null
        };

        /// <summary>
        /// The one natural logarithm of <paramref name="x"/> in <paramref name="expr"/>, where its
        /// argument is a constant times a power of <paramref name="x"/>, or <see langword="null"/>.
        /// </summary>
        private static Entity? TheLogarithmOfAPowerOfX(Entity expr, Entity.Variable x)
        {
            Entity? logarithm = null;
            foreach (var node in expr.Nodes)
                if (node is Logf(var @base, var argument) && @base == MathS.e && argument.ContainsNode(x))
                {
                    if (logarithm is not null && logarithm != node)
                        return null;
                    logarithm = node;
                }
            return logarithm is Logf(_, var antilogarithm) && IsAProductOfPowersOfTheVariable(antilogarithm, x) ? logarithm : null;
        }

        /// <summary>
        /// <paramref name="expr"/> under <c>u = d + e x</c>, with <paramref name="linear"/> the
        /// <c>d + e x</c> under the logarithm, answered by <paramref name="solve"/> in <c>u</c> and
        /// written back in <c>x</c>. A constant multiple of the linear, as <c>(d g + e g x)^m</c>
        /// writes one, is read as <c>g u</c>, where substituting for <c>x</c> would leave a sum
        /// that is a multiple of <c>u</c> only once simplified.
        /// </summary>
        private static Entity? UnderTheLinearUnderTheLogarithm(Entity expr, Entity.Variable x, Entity linear, System.Func<Entity, Entity.Variable, Entity?> solve)
        {
            if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out var intercept) || slope is null || intercept is null)
                return null;
            var u = Variable.CreateUnique(expr, "u");
            var inU = (expr.Replace(node =>
            {
                if (node == linear)
                    return u;
                if (node is not (Sumf or Minusf) || !TreeAnalyzer.TryGetPolyLinear(node, x, out var nodeSlope, out var nodeIntercept)
                    || TreeAnalyzer.IsZero(nodeSlope) || TreeAnalyzer.IsZero(nodeIntercept))
                    return node;
                // Bare: simplified, k g/k is g provided k is not 0, which k is, the linear being one.
                return Functions.PartialFractions.Bare((nodeIntercept * slope - nodeSlope * intercept).Simplify()).Evaled is Number.Complex { IsZero: true }
                    ? Functions.PartialFractions.Bare((nodeSlope / slope).Simplify()) * u
                    : node;
            }).Substitute(x, (u - intercept) / slope) / slope).InnerSimplified;
            if (inU.ContainsNode(x) || LinearUnderALogarithm(inU, u) is not null)
                return null;
            return solve(inU, u)?.Substitute(u, linear).InnerSimplified;
        }

        /// <summary>
        /// Whether <paramref name="expr"/> is <c>A + B ln(c x^r)</c> with <c>A</c>, <c>B</c>,
        /// <c>c</c> and <c>r</c> free of <paramref name="x"/> and the logarithm present: one
        /// logarithm of <paramref name="x"/> in it, the expression linear in that logarithm,
        /// and the logarithm's argument a constant times a power of <paramref name="x"/>.
        /// </summary>
        /// <summary>
        /// Whether <paramref name="expr"/> is built from <paramref name="x"/> and constants by
        /// products, quotients and powers with exponents free of <paramref name="x"/>, however
        /// nested: <c>c (d x^m)^n</c>, and not <c>x + 1</c> or <c>e^x</c>.
        /// </summary>
        private static bool IsAProductOfPowersOfTheVariable(Entity expr, Entity.Variable x)
            => !expr.ContainsNode(x) || expr == x || expr switch
            {
                Mulf(var left, var right) => IsAProductOfPowersOfTheVariable(left, x) && IsAProductOfPowersOfTheVariable(right, x),
                Divf(var left, var right) => IsAProductOfPowersOfTheVariable(left, x) && IsAProductOfPowersOfTheVariable(right, x),
                Powf(var @base, var exponent) => !exponent.ContainsNode(x) && IsAProductOfPowersOfTheVariable(@base, x),
                _ => false,
            };

        private static bool IsAffineInALogarithmOfAPowerOfX(Entity expr, Entity.Variable x)
        {
            Entity? logarithm = null;
            foreach (var node in expr.Nodes)
                if (node is Logf(var @base, var argument) && @base == MathS.e && argument.ContainsNode(x))
                {
                    if (logarithm is not null && logarithm != node)
                        return false;
                    logarithm = node;
                }
            if (logarithm is not Logf(_, var antilogarithm))
                return false;
            // The argument c x^r, read before it is differentiated: products, quotients and
            // powers of x and of constants, however nested -- `c (d x^m)^n` -- and nothing
            // else of x. Simplifying the logarithmic derivative of any argument was what took
            // `atanh(tanh(a + b x))^4` -- a fourth power of a logarithm of a quotient of
            // exponentials, a 300 ms answer before -- past three minutes on the way to
            // declining.
            if (!IsAProductOfPowersOfTheVariable(antilogarithm, x))
                return false;
            // The argument c x^r: its logarithmic derivative is r/x.
            var rate = Functions.PartialFractions.Bare((antilogarithm.Differentiate(x) * x / antilogarithm).Simplify());
            if (rate.ContainsNode(x) || rate.Nodes.Any(node => node == MathS.NaN))
                return false;
            var placeholder = Variable.CreateUnique(expr, "u_log");
            var inThePlaceholder = expr.Replace(node => node == logarithm ? placeholder : node);
            if (inThePlaceholder.ContainsNode(x))
                return false;
            return TreeAnalyzer.TryGetPolyLinear(inThePlaceholder, placeholder, out var slope, out _) && slope is { } && !TreeAnalyzer.IsZero(slope);
        }

        /// <summary>
        /// The same reduction with a power of x below: <c>P Q^(m/2)/x^n</c> is
        /// <c>R Q^(k + 1/2)/x^(n - 1) + K_1/sqrt(Q) + K_2/(x sqrt(Q))</c>, the two remainders the
        /// table's and the linear-beside-the-root rule's.
        /// </summary>
        /// <remarks>
        /// With <c>s = k + 1/2</c> the derivative of <c>R Q^s/x^(n - 1)</c> is
        /// <c>Q^(s - 1) x^(-n) ((R' x - (n - 1) R) Q + s R Q' x)</c>, and the two remainders
        /// over the same <c>Q^(s - 1) x^(-n)</c> are <c>K_1 Q^(-k) x^n</c> and
        /// <c>K_2 Q^(-k) x^(n - 1)</c>, polynomials both; the identity is one equation per
        /// power of x, linear in the coefficients of <c>R</c> and in the two constants.
        /// Stewart's <c>sqrt(x^2 - a^2)/x^4</c> and <c>sqrt(a^2 - x^2)/x^2</c> had no
        /// antiderivative, with the symbol in the radicand; the second is
        /// <c>-sqrt(a^2 - x^2)/x - arcsin(x/a)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPolynomialOverAPowerOfXTimesAnOddHalfPowerOfAQuadratic(Entity expr, Entity.Variable x)
        {
            Entity? radicand = null;
            var m = 0;
            var n = 0;
            Entity polynomial = Number.Integer.One;
            Entity constant = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational exponent) && exponent is not Number.Integer
                    && exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) && exponent.ERational.Numerator.CanFitInInt32()
                    && radicand is null)
                {
                    radicand = @base;
                    m = exponent.ERational.Numerator.ToInt32Unchecked() * (underneath ? -1 : 1);
                    continue;
                }
                if (underneath)
                {
                    if (factor == x && n == 0)
                        n = 1;
                    else if (factor is Powf(var xOf, Number.Integer whole) && xOf == x && whole.EInteger.Sign > 0 && whole.EInteger.CanFitInInt32() && n == 0)
                        n = whole.EInteger.ToInt32Unchecked();
                    else
                        return null;
                    continue;
                }
                polynomial = polynomial * factor;
            }
            if (n == 0 || n > 8 || radicand is null || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out var b, out var c)
                || TreeAnalyzer.IsZero(a) || TreeAnalyzer.IsZero(c)
                || !TreeAnalyzer.TryGetPolynomial(polynomial.Expand(), x, out var pRead) || pRead.Keys.Any(k => k.Sign < 0 || !k.CanFitInInt32())
                || pRead.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degreeOfP = pRead.Count == 0 ? 0 : pRead.Keys.Max()!.ToInt32Unchecked();
            if (degreeOfP >= n || degreeOfP > 8 || m > 9 || m < -9)
                return null;   // a proper quotient by the power; anything else is the rule before this one's after a division
            foreach (var coefficient in new[] { a, b, c, constant }.Concat(pRead.Values))
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;

            var q = new Dictionary<EInteger, Entity> { [EInteger.Zero] = c, [EInteger.One] = b, [EInteger.FromInt32(2)] = a };
            var qPrime = new Dictionary<EInteger, Entity> { [EInteger.Zero] = b, [EInteger.One] = (2 * a).InnerSimplified };
            Dictionary<EInteger, Entity> PowerOfQ(int power)
            {
                var result = new Dictionary<EInteger, Entity> { [EInteger.Zero] = Number.Integer.One };
                for (var i = 0; i < power; i++)
                    result = PolynomialProduct(result, q);
                return result;
            }
            static Dictionary<EInteger, Entity> Monomial(int power) => new() { [EInteger.FromInt32(power)] = Number.Integer.One };
            static Dictionary<EInteger, Entity> Scaled(Dictionary<EInteger, Entity> poly, Entity by)
            {
                var scaled = new Dictionary<EInteger, Entity>();
                foreach (var pair in poly)
                    scaled[pair.Key] = (by * pair.Value).InnerSimplified;
                return scaled;
            }
            var positive = m >= -1;
            var jPrime = positive ? (m + 1) / 2 : 0;
            var k = positive ? 0 : (m + 1) / 2;   // s = k + 1/2, and m = 2k - 1 for a negative m
            var sValue = Number.Rational.Create(2 * k + 1, 2);
            var target = positive ? PolynomialProduct(pRead, PowerOfQ(jPrime)) : pRead;
            var degreeOfTarget = target.Count == 0 ? 0 : target.Keys.Max()!.ToInt32Unchecked();
            var degreeOfR = System.Math.Max(degreeOfTarget, 2 * (-k) + n) + 1;
            var columns = new List<Dictionary<EInteger, Entity>>();
            for (var i = 0; i <= degreeOfR; i++)
            {
                // ((i - n + 1) x^i) Q + s x^(i + 1) Q'
                var column = PolynomialSum(
                    Scaled(PolynomialProduct(Monomial(i), q), Number.Integer.Create(i - n + 1)),
                    Scaled(PolynomialProduct(Monomial(i + 1), qPrime), sValue));
                columns.Add(column);
            }
            var qToMinusK = PowerOfQ(-k);
            columns.Add(PolynomialProduct(qToMinusK, Monomial(n)));
            columns.Add(PolynomialProduct(qToMinusK, Monomial(n - 1)));
            var rows = columns.SelectMany(column => column.Keys).Concat(target.Keys).Max()!.ToInt32Unchecked() + 1;
            var matrix = new Entity[rows][];
            var rhs = new Entity[rows];
            for (var row = 0; row < rows; row++)
            {
                var power = EInteger.FromInt32(row);
                matrix[row] = new Entity[columns.Count];
                for (var column = 0; column < columns.Count; column++)
                    matrix[row][column] = columns[column].TryGetValue(power, out var entry) ? entry : Number.Integer.Zero;
                rhs[row] = target.TryGetValue(power, out var wanted) ? wanted : Number.Integer.Zero;
            }
            if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                return null;
            Entity r = Number.Integer.Zero;
            for (var i = 0; i <= degreeOfR; i++)
            {
                var value = values[i].InnerSimplified;
                if (value.Evaled is Number.Complex { IsZero: true })
                    continue;
                r = r + value * (i == 0 ? Number.Integer.One : i == 1 ? x : MathS.Pow(x, i));
            }
            var k1 = values[degreeOfR + 1].InnerSimplified;
            var k2 = values[degreeOfR + 2].InnerSimplified;
            var root = MathS.Pow(radicand, Number.Rational.Create(1, 2));
            Entity answer = r == Number.Integer.Zero
                ? Number.Integer.Zero
                : r * MathS.Pow(radicand, sValue) / (n == 1 ? Number.Integer.One : n == 2 ? x : MathS.Pow(x, n - 1));
            if (k1.Evaled is not Number.Complex { IsZero: true })
            {
                if (IntegralPatterns.TryStandardIntegrals(1 / root, x) is not { } table || table is Piecewise && a.Evaled is not Number)
                    return null;
                answer = answer + k1 * table;
            }
            if (k2.Evaled is not Number.Complex { IsZero: true })
            {
                if (SolveALinearBesideTheRootOfAQuadratic(1 / (x * root), x) is not { } besideTheRoot || besideTheRoot is Piecewise && a.Evaled is not Number)
                    return null;
                answer = answer + k2 * besideTheRoot;
            }
            answer = (constant * answer).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// An exponential of a linear times a polynomial times an odd half power of a
        /// quadratic, <c>e^(a x + b) P Q^(m/2)</c>, closed by the ansatz <c>F = e^(a x + b) R Q^(k + 1/2)</c>
        /// with <c>m = 2k - 1</c>: <c>F' = e^(a x + b) Q^(k - 1/2) (a R Q + R' Q + (k + 1/2) R Q')</c>,
        /// and <c>a R Q + R' Q + (k + 1/2) R Q' = P</c> is a linear system in the coefficients
        /// of <c>R</c>, exact.
        /// </summary>
        /// <remarks>
        /// Timofeev's <c>e^x (1 - x - x^2)/sqrt(1 - x^2)</c> is <c>(e^x sqrt(1 - x^2))'</c> and
        /// had no antiderivative: by parts goes round in a circle and nothing substitutes.
        /// Liouville's theorem says the elementary antiderivative of <c>e^(a x)</c> times an
        /// algebraic function, where there is one, is <c>e^(a x)</c> times an algebraic function
        /// of the same field, which is what is looked for; there is no remainder term, unlike
        /// the reduction without the exponential, so an empty solution is a decline.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAnExponentialTimesAnOddHalfPowerOfAQuadratic(Entity expr, Entity.Variable x)
        {
            if (ReadOneExponentialTimesTheRest(expr, x) is not var (exponent, rest) || exponent is null
                || !TreeAnalyzer.TryGetPolyLinear(exponent, x, out var a, out _) || a.ContainsNode(x) || TreeAnalyzer.IsZero(a))
                return null;
            Entity? radicand = null;
            var m = 0;
            Entity polynomial = Number.Integer.One;
            Entity constant = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(rest))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational power) && power is not Number.Integer
                    && power.ERational.Denominator.Equals(EInteger.FromInt32(2)) && power.ERational.Numerator.CanFitInInt32()
                    && radicand is null)
                {
                    radicand = @base;
                    m = power.ERational.Numerator.ToInt32Unchecked() * (underneath ? -1 : 1);
                    continue;
                }
                if (underneath)
                    return null;
                polynomial = polynomial * factor;
            }
            if (radicand is null || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var qa, out var qb, out var qc)
                || TreeAnalyzer.IsZero(qa)
                || !TreeAnalyzer.TryGetPolynomial(polynomial.Expand(), x, out var pRead) || pRead.Keys.Any(k => k.Sign < 0 || !k.CanFitInInt32())
                || pRead.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degreeOfP = pRead.Count == 0 ? 0 : pRead.Keys.Max()!.ToInt32Unchecked();
            if (degreeOfP > 8 || m > 9 || m < -9)
                return null;
            var k = (m + 1) / 2;   // m = 2k - 1, exact for odd m of either sign
            var q = new Dictionary<EInteger, Entity> { [EInteger.Zero] = qc, [EInteger.One] = qb, [EInteger.FromInt32(2)] = qa };
            var qPrime = new Dictionary<EInteger, Entity> { [EInteger.Zero] = qb, [EInteger.One] = (2 * qa).InnerSimplified };
            var halfOdd = Number.Rational.Create(2 * k + 1, 2);
            var degreeOfR = degreeOfP + 1;
            var columns = new List<Dictionary<EInteger, Entity>>();
            for (var i = 0; i <= degreeOfR; i++)
            {
                var monomial = new Dictionary<EInteger, Entity> { [EInteger.FromInt32(i)] = Number.Integer.One };
                var column = PolynomialProduct(PolynomialDerivative(monomial), q);
                var alongQ = new Dictionary<EInteger, Entity>();
                foreach (var pair in PolynomialProduct(monomial, q))
                    alongQ[pair.Key] = (a * pair.Value).InnerSimplified;
                var alongQPrime = new Dictionary<EInteger, Entity>();
                foreach (var pair in PolynomialProduct(monomial, qPrime))
                    alongQPrime[pair.Key] = (halfOdd * pair.Value).InnerSimplified;
                columns.Add(PolynomialSum(PolynomialSum(column, alongQ), alongQPrime));
            }
            var rows = columns.SelectMany(column => column.Keys).Concat(pRead.Keys).Max()!.ToInt32Unchecked() + 1;
            var matrix = new Entity[rows][];
            var rhs = new Entity[rows];
            for (var row = 0; row < rows; row++)
            {
                var power = EInteger.FromInt32(row);
                matrix[row] = new Entity[columns.Count];
                for (var column = 0; column < columns.Count; column++)
                    matrix[row][column] = columns[column].TryGetValue(power, out var entry) ? entry : Number.Integer.Zero;
                rhs[row] = pRead.TryGetValue(power, out var wanted) ? wanted : Number.Integer.Zero;
            }
            if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                return null;
            Entity r = Number.Integer.Zero;
            for (var i = 0; i <= degreeOfR; i++)
            {
                var value = values[i].InnerSimplified;
                if (value.Evaled is Number.Complex { IsZero: true })
                    continue;
                r = r + value * (i == 0 ? Number.Integer.One : i == 1 ? x : MathS.Pow(x, i));
            }
            if (r == Number.Integer.Zero)
                return null;
            var answer = (constant * MathS.Pow(MathS.e, exponent) * r * MathS.Pow(radicand, Number.Rational.Create(2 * k + 1, 2))).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// A polynomial times an odd half power of a quadratic, <c>P Q^(m/2)</c>, reduced to
        /// <c>R Q^(k + 1/2) + K/sqrt(Q)</c> by one linear solve, with <c>K/sqrt(Q)</c> the
        /// table's -- an arcsine or a logarithm by the sign of the leading coefficient, a
        /// piecewise where that sign is a symbol's.
        /// </summary>
        /// <remarks>
        /// <para>
        /// For <c>m = 2j - 1</c> at least <c>-1</c> the ansatz is <c>F = R sqrt(Q)</c>, and
        /// <c>F' = P Q^j/sqrt(Q) - K/sqrt(Q)</c> is <c>R' Q + R Q'/2 + K = P Q^j</c>; for
        /// <c>m = -2j - 3</c> it is <c>F = R Q^(-j - 1/2)</c>, and the identity
        /// <c>R' Q - (j + 1/2) R Q' + K Q^(j + 1) = P</c>. Each is one equation per power of
        /// x, linear in the coefficients of <c>R</c> and in <c>K</c>, exact; a solution is an
        /// answer and its absence a decline.
        /// </para>
        /// <para>
        /// Hearn's <c>r/sqrt(-alpha^2 - 2k r + 2pe r^2)</c>, Stewart's
        /// <c>x^2/(a^2 - x^2)^(3/2)</c> and Apostol's <c>(a^2 - x^2)^(5/2)</c> had no
        /// antiderivative: with a symbol in the radicand the trigonometric substitution has
        /// no sign to go on and Euler's takes a root of it, while <c>1/sqrt(Q)</c> alone was
        /// answered, as a piecewise on the sign of the leading coefficient, with
        /// <c>arcsin(x/sqrt(a^2))</c> right for either sign of <c>a</c>. The reduction is what
        /// every table does before that line. Numeric coefficients reach this only from a
        /// sub-integral, since the substitutions in front answer them.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPolynomialTimesAnOddHalfPowerOfAQuadratic(Entity expr, Entity.Variable x)
        {
            Entity? radicand = null;
            var m = 0;
            Entity polynomial = Number.Integer.One;
            Entity constant = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational exponent) && exponent is not Number.Integer
                    && exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) && exponent.ERational.Numerator.CanFitInInt32()
                    && radicand is null)
                {
                    radicand = @base;
                    m = exponent.ERational.Numerator.ToInt32Unchecked() * (underneath ? -1 : 1);
                    continue;
                }
                if (underneath)
                    return null;
                polynomial = polynomial * factor;
            }
            if (radicand is null || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out var b, out var c)
                || TreeAnalyzer.IsZero(a)
                || !TreeAnalyzer.TryGetPolynomial(polynomial.Expand(), x, out var pRead) || pRead.Keys.Any(k => k.Sign < 0 || !k.CanFitInInt32())
                || pRead.Values.Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degreeOfP = pRead.Count == 0 ? 0 : pRead.Keys.Max()!.ToInt32Unchecked();
            if (degreeOfP > 8 || m > 9 || m < -9)
                return null;
            foreach (var coefficient in new[] { a, b, c, constant }.Concat(pRead.Values))
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;

            // Each coefficient that is neither a number nor a symbol is named for the solve and
            // written back into what it gives. Carried through the elimination as written,
            // `g^2/f^2` as the leading coefficient of `sqrt(a + b x + g^2 x^2/f^2)` came back in an
            // answer of 188,000 characters after four seconds, where a symbol in its place gives a
            // short one at once.
            var names = new List<(Variable Name, Entity Value)>();
            Entity Named(Entity value)
            {
                if (value is Number or Variable)
                    return value;
                foreach (var (name, named) in names)
                    if (named == value)
                        return name;
                var fresh = Variable.CreateUnique(expr, "k_named" + names.Count);
                names.Add((fresh, value));
                return fresh;
            }
            Entity Back(Entity value)
            {
                foreach (var (name, named) in names)
                    value = value.Substitute(name, named);
                return value;
            }
            var (namedA, namedB, namedC) = (Named(a), Named(b), Named(c));
            pRead = pRead.ToDictionary(pair => pair.Key, pair => Named(pair.Value));

            var q = new Dictionary<EInteger, Entity> { [EInteger.Zero] = namedC, [EInteger.One] = namedB, [EInteger.FromInt32(2)] = namedA };
            var qPrime = new Dictionary<EInteger, Entity> { [EInteger.Zero] = namedB, [EInteger.One] = (2 * namedA).InnerSimplified };
            Dictionary<EInteger, Entity> PowerOfQ(int j)
            {
                var result = new Dictionary<EInteger, Entity> { [EInteger.Zero] = Number.Integer.One };
                for (var i = 0; i < j; i++)
                    result = PolynomialProduct(result, q);
                return result;
            }
            // The target and the coefficient of R's monomials and of K, by the sign of m.
            var positive = m >= -1;
            var j = positive ? (m + 1) / 2 : (-m - 3) / 2;
            var target = positive ? PolynomialProduct(pRead, PowerOfQ(j)) : pRead;
            var degreeOfTarget = target.Count == 0 ? 0 : target.Keys.Max()!.ToInt32Unchecked();
            var degreeOfR = System.Math.Max(degreeOfTarget, 2 * j + 2) + 1;
            var factorOnRQPrime = positive ? Number.Rational.Create(1, 2) : Number.Rational.Create(-(2 * j + 1), 2);
            var columns = new List<Dictionary<EInteger, Entity>>();
            for (var k = 0; k <= degreeOfR; k++)
            {
                var monomial = new Dictionary<EInteger, Entity> { [EInteger.FromInt32(k)] = Number.Integer.One };
                var scaled = new Dictionary<EInteger, Entity>();
                foreach (var pair in PolynomialProduct(monomial, qPrime))
                    scaled[pair.Key] = (factorOnRQPrime * pair.Value).InnerSimplified;
                columns.Add(PolynomialSum(PolynomialProduct(PolynomialDerivative(monomial), q), scaled));
            }
            columns.Add(positive ? new Dictionary<EInteger, Entity> { [EInteger.Zero] = Number.Integer.One } : PowerOfQ(j + 1));
            var rows = columns.SelectMany(column => column.Keys).Concat(target.Keys).Max()!.ToInt32Unchecked() + 1;
            var matrix = new Entity[rows][];
            var rhs = new Entity[rows];
            for (var row = 0; row < rows; row++)
            {
                var power = EInteger.FromInt32(row);
                matrix[row] = new Entity[columns.Count];
                for (var column = 0; column < columns.Count; column++)
                    matrix[row][column] = columns[column].TryGetValue(power, out var entry) ? entry : Number.Integer.Zero;
                rhs[row] = target.TryGetValue(power, out var wanted) ? wanted : Number.Integer.Zero;
            }
            if (!Functions.PartialFractions.TrySolveLinear(matrix, rhs, out var values) || values is null)
                return null;
            Entity r = Number.Integer.Zero;
            for (var k = 0; k <= degreeOfR; k++)
            {
                var value = Back(values[k]).InnerSimplified;
                if (value.Evaled is Number.Complex { IsZero: true })
                    continue;
                r = r + value * (k == 0 ? Number.Integer.One : k == 1 ? x : MathS.Pow(x, k));
            }
            var kValue = Back(values[degreeOfR + 1]).InnerSimplified;
            var root = MathS.Pow(radicand, Number.Rational.Create(1, 2));
            var powerOfQInFront = positive ? root : MathS.Pow(radicand, Number.Rational.Create(-(2 * j + 1), 2));
            Entity reduced = r == Number.Integer.Zero ? Number.Integer.Zero : r * powerOfQInFront;
            Entity answer;
            if (kValue.Evaled is Number.Complex { IsZero: true })
                answer = reduced;
            else if (IntegralPatterns.TryStandardIntegrals(1 / root, x) is not { } table)
                return null;
            else if (table is Piecewise piecewise)
            {
                // The table's arm for a vanishing leading coefficient is not this
                // reduction's, which divided by it: on that arm the integrand is a polynomial
                // times a power of a linear, and the chain answers it as that.
                var arms = new List<Providedf>();
                foreach (var arm in piecewise.Cases)
                {
                    if (arm.Predicate == a.EqualTo(0))
                    {
                        var overALinear = polynomial * MathS.Pow(b * x + c, Number.Rational.Create(m, 2));
                        if (Integration.ComputeIndefiniteIntegral(overALinear.InnerSimplified, x, integrateByParts: false) is not { } onTheArm)
                            return null;
                        arms.Add(new Providedf(onTheArm, arm.Predicate));
                    }
                    else
                        arms.Add(new Providedf(reduced + kValue * arm.Expression, arm.Predicate));
                }
                answer = MathS.Piecewise(arms);
            }
            else
                answer = reduced + kValue * table;
            answer = (constant * answer).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.HoldsAtSampledPoints(answer.Differentiate(x), expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// A constant over a linear beside the square root of a quadratic,
        /// <c>K/((x - p) sqrt(Q))</c>, by the reciprocal of the linear: with <c>t = 1/(x - p)</c>
        /// the root becomes one of a quadratic in <c>t</c> alone, and the table answers that.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>Q(p + 1/t) = (Q(p) t^2 + Q'(p) t + a)/t^2</c>, so <c>sqrt(Q) = sqrt(R(t))/|t|</c>
        /// with <c>R(t) = Q(p) t^2 + Q'(p) t + a</c>, and <c>dx = -dt/t^2</c>: the integrand is
        /// <c>-K sgn(t) dt/sqrt(R(t))</c>, whose integral is the table's, an arcsine or a
        /// logarithm by the sign of <c>Q(p)</c> -- a piecewise where that sign is a symbol's.
        /// The sign of <c>t</c> is the sign of <c>x - p</c>, and the antiderivative is
        /// <c>-K sgn(x - p) G(1/(x - p))</c> on both sides of <c>p</c>, exactly.
        /// </para>
        /// <para>
        /// This is the shape the Euler substitution answers at length, as a partial-fraction
        /// decomposition in <c>t</c>, and declines for a leading coefficient that is a
        /// symbol of the wrong sign: Hearn's <c>1/(r sqrt(-alpha^2 - epsilon^2 + 2h r^2 - 2k r^4))</c>
        /// is <c>1/(2u sqrt(-alpha^2 - epsilon^2 + 2h u - 2k u^2))</c> under <c>u = r^2</c>, with
        /// <c>-2k</c> in front and <c>-alpha^2 - epsilon^2</c> behind, and neither Euler's first
        /// nor second substitution has a real radical to take. Here <c>Q(0)</c> is
        /// <c>-alpha^2 - epsilon^2</c>, the arcsine arm, and the answer is Rubi's. Closed, and
        /// volunteered at any depth for it: the reciprocal substitution and <c>u = x^2</c> both
        /// hand it what they make.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveALinearBesideTheRootOfAQuadratic(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            if (numerator.ContainsNode(x))
                return null;
            Entity? radicand = null;
            Entity? linear = null;
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational half) && half == Number.Rational.Create(1, 2) && radicand is null)
                    radicand = @base;
                else if (linear is null && TreeAnalyzer.TryGetPolyLinear(factor, x, out var slope, out _)
                    && slope.Evaled is not Number.Complex { IsZero: true })
                    linear = factor;
                else
                    return null;
            }
            if (radicand is null || linear is null
                || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out var b, out var c)
                || a.Evaled is Number.Complex { IsZero: true }
                || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var m, out var n))
                return null;
            // A coefficient that is a number is a real one, as in every rule about a real root.
            foreach (var coefficient in new[] { a, b, c, m, n, numerator, constant })
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;

            // (x - p) with p = -n/m, and K = numerator/(m constant).
            var p = (-n / m).InnerSimplified;
            var k = (numerator / (m * constant)).InnerSimplified;
            var atP = (a * p * p + b * p + c).InnerSimplified;
            var slopeAtP = (2 * a * p + b).InnerSimplified;
            var t = Variable.CreateUnique(expr, "t_recip");
            var inT = 1 / MathS.Pow(atP * MathS.Sqr(t) + slopeAtP * t + a, Number.Rational.Create(1, 2));
            if (IntegralPatterns.TryStandardIntegrals(inT, t) is not { } g)
                return null;
            var answer = (-k * MathS.Signum(x - p) * g.Substitute(t, 1 / (x - p))).InnerSimplified;
            return answer.Nodes.Any(node => node is Number.Complex { IsNaN: true }) ? null : answer;
        }

        /// <summary>
        /// A linear over a quadratic beside the square root of another quadratic,
        /// <c>(g + h x)/(A sqrt(B))</c>, in closed form, symbols in the coefficients included:
        /// two arctangents of <c>L/sqrt(B)</c>, each for a linear <c>L</c> for which <c>A</c> is
        /// a sum of multiples of <c>B</c> and <c>L^2</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// For <c>L = lambda + mu x</c>, <c>u = L/sqrt(B)</c> has <c>du = N dx/(2 B^(3/2))</c>
        /// with <c>N = (2 mu B0 - lambda B1) + (mu B1 - 2 lambda B2) x</c>, and
        /// <c>alpha + beta u^2</c> is <c>(alpha B + beta L^2)/B</c>. Where
        /// <c>alpha B + beta L^2 = rho A</c>, then, <c>N dx/(A sqrt(B))</c> is
        /// <c>2 rho du/(alpha + beta u^2)</c>. The three equations that says, one for each power
        /// of x, have a solution where their determinant is zero, which is a quadratic in
        /// <c>lambda : mu</c>, <c>E lambda^2 - 2 P lambda mu + F mu^2</c> with
        /// <c>P = A2 B0 - A0 B2</c>, <c>E = A2 B1 - A1 B2</c> and <c>F = A1 B0 - A0 B1</c>. Its two
        /// roots give two such numerators, independent unless <c>q = sqrt(P^2 - E F)</c> is zero
        /// or <c>B</c> is a square, and <c>g + h x</c> is a sum of the two.
        /// </para>
        /// <para>
        /// Each piece is <c>2 rho arctan(k u)/(alpha k)</c> with <c>k = sqrt(beta/alpha)</c>. Its
        /// derivative is <c>2 rho/(alpha + alpha k^2 u^2)</c>, and <c>alpha k^2</c> is <c>beta</c>
        /// on either branch of the root, so the piece holds where <c>beta/alpha</c> is negative
        /// too, as the hyperbolic arctangent it is there.
        /// </para>
        /// <para>
        /// Rubi's 1.2.1.6 closes these the same way, and its 4.3.9 and 4.4.9 come to them under
        /// the tangent: <c>1/sqrt(a + b tan(x) + c tan(x)^2)</c> is
        /// <c>1/((1 + t^2) sqrt(a + b t + c t^2))</c>, for which <c>q</c> is
        /// <c>sqrt((a - c)^2 + b^2)</c>. That is the nested surd the rotation of the tangent
        /// takes only as a number, since the rotation hands the rational integrator a quotient
        /// over it; here it is one root in a closed form.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveALinearOverAQuadraticBesideTheRootOfAnother(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            Entity? radicand = null;
            Entity? quadratic = null;
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational half) && half == Number.Rational.Create(1, 2) && radicand is null)
                    radicand = @base;
                // A power of a linear is a repeated linear, the reciprocal substitution's.
                else if (quadratic is null && factor is not Powf)
                    quadratic = factor;
                else
                    return null;
            }
            if (radicand is null || quadratic is null
                || !TreeAnalyzer.TryGetPolyQuadratic(quadratic, x, out var a2, out var a1, out var a0)
                || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var b2, out var b1, out var b0)
                || !TreeAnalyzer.TryGetPolyLinear(numerator, x, out var h, out var g)
                || VanishesIdentically(a2) || VanishesIdentically(b2))
                return null;
            // A coefficient that is a number is a real one, as in every rule about a real root.
            foreach (var coefficient in new[] { a0, a1, a2, b0, b1, b2, g, h, constant })
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;
            // Two distinct roots below the bar, and none repeated under the root.
            if (VanishesIdentically(a1 * a1 - 4 * a0 * a2) || VanishesIdentically(b1 * b1 - 4 * b0 * b2))
                return null;

            var p = (a2 * b0 - a0 * b2).InnerSimplified;
            var e = (a2 * b1 - a1 * b2).InnerSimplified;
            var f = (a1 * b0 - a0 * b1).InnerSimplified;
            // Zero where the two quadratics are proportional, which is one power of one base.
            // Expanded, so that the root reads as Rubi's does, sqrt(a^2 - 2 a c + b^2 + c^2) for
            // 1 + t^2 beside a + b t + c t^2, and not with `- b (-b)` in it.
            var qSquared = (p * p - e * f).Expand().InnerSimplified;
            if (VanishesIdentically(qSquared))
                return null;
            var q = MathS.Sqrt(qSquared).InnerSimplified;
            var roots = !VanishesIdentically(e) ? new[] { (Lambda: p + q, Mu: e), (Lambda: p - q, Mu: e) }
                : !VanishesIdentically(f) ? new[] { (Lambda: f, Mu: p + q), (Lambda: f, Mu: p - q) }
                // Both even, and the substitutions are u = 1/sqrt(B) and u = x/sqrt(B).
                : new[] { (Lambda: (Entity)Number.Integer.One, Mu: (Entity)Number.Integer.Zero), (Lambda: (Entity)Number.Integer.Zero, Mu: (Entity)Number.Integer.One) };

            var root = MathS.Sqrt(radicand);
            var numerators = new (Entity Constant, Entity Slope)[2];
            var pieces = new Entity[2];
            for (var i = 0; i < 2; i++)
            {
                var (lambda, mu) = roots[i];
                numerators[i] = ((2 * mu * b0 - lambda * b1).InnerSimplified, (mu * b1 - 2 * lambda * b2).InnerSimplified);
                // alpha B + beta L^2 = rho A, from the first two of its three equations that are
                // independent.
                (Entity Alpha, Entity Beta, Entity Rho)? found = null;
                foreach (var (alpha, beta, rho) in new[]
                {
                    (a0 * mu * mu - a2 * lambda * lambda, p, b0 * mu * mu - b2 * lambda * lambda),
                    (a1 * lambda * lambda - 2 * a0 * lambda * mu, a0 * b1 - a1 * b0, b1 * lambda * lambda - 2 * b0 * lambda * mu),
                    (2 * a2 * lambda * mu - a1 * mu * mu, a1 * b2 - a2 * b1, 2 * b2 * lambda * mu - b1 * mu * mu),
                })
                    if (!VanishesIdentically(alpha) && !VanishesIdentically(beta) && !VanishesIdentically(rho))
                    {
                        found = (alpha.InnerSimplified, beta.InnerSimplified, rho.InnerSimplified);
                        break;
                    }
                if (found is not { } triple)
                    return null;
                var u = (lambda + mu * x) / root;
                // Where beta/alpha is a negative number, the hyperbolic arctangent it is, written
                // so: arctan(i kappa u)/(i kappa) is artanh(kappa u)/kappa.
                var ratio = (triple.Beta / triple.Alpha).InnerSimplified;
                if (ratio.Evaled is Number.Real { IsNegative: true })
                {
                    var kappa = MathS.Sqrt((-ratio).InnerSimplified).InnerSimplified;
                    pieces[i] = 2 * triple.Rho * MathS.Hyperbolic.Artanh(kappa * u) / (triple.Alpha * kappa);
                }
                else
                {
                    var k = MathS.Sqrt(ratio).InnerSimplified;
                    pieces[i] = 2 * triple.Rho * MathS.Arctan(k * u) / (triple.Alpha * k);
                }
            }
            // g + h x as a sum of the two numerators; the determinant is 2 q E disc(B) up to its
            // sign, or disc(B) where both are even, none of them zero here.
            var ((c0, s0), (c1, s1)) = (numerators[0], numerators[1]);
            var determinant = c0 * s1 - c1 * s0;
            Entity answer = Number.Integer.Zero;
            foreach (var (share, piece) in new[] { ((g * s1 - c1 * h) / determinant, pieces[0]), ((c0 * h - g * s0) / determinant, pieces[1]) })
            {
                var simplified = share.InnerSimplified;
                if (simplified.Evaled is not Number.Complex { IsZero: true })
                    answer = answer + simplified * piece;
            }
            answer = (answer / constant).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(answer, expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// The largest the linear <c>p + q x</c> of one step of
        /// <see cref="SolveAPolynomialOverAPowerOfAQuadraticBesideTheRootOfAnother"/> is let grow,
        /// its two coefficients' complexities together: past it the reduction declines rather than
        /// hand the next step a numerator of tens of thousands of nodes. With six symbols the
        /// cube of <c>d + k x + f x^2</c> beside <c>sqrt(a + b x + c x^2)</c> reached 10,700 at
        /// its second step and took over two minutes to answer and check; the square reaches a
        /// few hundred, and Rubi's `sqrt(a + a sec(x))/(c + d sec(x))^3` 1,010.
        /// </summary>
        private const int LargestReducedCoefficients = 4000;

        /// <summary>
        /// A polynomial over a power of a quadratic beside the square root of another quadratic,
        /// <c>P/(A^k sqrt(B))</c> with <c>k</c> at least two and <c>P</c> of degree below
        /// <c>2k</c>, one power of <c>A</c> at a time down to the first, which
        /// <see cref="SolveALinearOverAQuadraticBesideTheRootOfAnother"/> closes.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Over <c>A^j</c>, <c>P</c> is <c>L + A R</c> with <c>L</c> linear, and <c>R</c> goes a
        /// power down as it is. For <c>L = g + h x</c>, the derivative of
        /// <c>(p + q x) sqrt(B)/A^(j - 1)</c> is
        /// <c>(2 q A B + (p + q x) W)/(2 A^j sqrt(B))</c> with <c>W = B' A - 2 (j - 1) B A'</c>,
        /// so <c>L/(A^j sqrt(B))</c> is that derivative and <c>S/(A^(j - 1) sqrt(B))</c> wherever
        /// <c>2 L = 2 q A B + (p + q x) W + 2 A S</c>. That is five linear equations, one for each
        /// power of x up to the fourth, in <c>p</c>, <c>q</c> and the three coefficients of a
        /// quadratic <c>S</c>, and they have a solution where <c>A</c> and <c>B</c> have no root
        /// in common: Hermite's reduction, as Rubi's 1.2.1.6 takes these. Over <c>A</c> itself,
        /// what is left is <c>sigma A + L</c>, <c>sigma</c> over the root alone and <c>L</c> over
        /// <c>A</c> beside it.
        /// </para>
        /// <para>
        /// Beside a half-odd power of the secant or the cosecant, the half-angle tangent leaves
        /// these: <c>sqrt(a + a sec(x))/(c + d sec(x))^2</c> has <c>(c + d) + (d - c) t^2</c>
        /// squared below the bar beside <c>sqrt(1 - t^2)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAPolynomialOverAPowerOfAQuadraticBesideTheRootOfAnother(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            Entity? radicand = null;
            Entity? quadratic = null;
            var power = 0;
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational half) && half == Number.Rational.Create(1, 2) && radicand is null)
                    radicand = @base;
                else if (quadratic is null && factor is Powf(var repeated, Number.Integer { EInteger.Sign: > 0 } whole)
                    && repeated is not Powf && whole.EInteger.CanFitInInt32() && whole.EInteger.ToInt32Unchecked() >= 2)
                {
                    quadratic = repeated;
                    power = whole.EInteger.ToInt32Unchecked();
                }
                else
                    return null;
            }
            if (radicand is null || quadratic is null || quadratic == radicand
                || !TreeAnalyzer.TryGetPolyQuadratic(quadratic, x, out var a2, out var a1, out var a0)
                || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var b2, out var b1, out var b0)
                || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var monomials)
                || VanishesIdentically(a2) || VanishesIdentically(b2))
                return null;
            if (monomials.Any(pair => pair.Key.Sign < 0 || pair.Value.ContainsNode(x))
                || monomials.Count > 0 && monomials.Keys.Max()!.CompareTo(EInteger.FromInt32(2 * power)) >= 0)
                return null;
            // A coefficient that is a number is a real one, as in every rule about a real root.
            foreach (var coefficient in new[] { a0, a1, a2, b0, b1, b2, constant }.Concat(monomials.Values))
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;
            // Every coefficient without the condition a division by a symbol writes on it,
            // `k/f provided not f = 0`: that is the generic case this answers in, and the linear
            // solve below reads no condition.
            static Entity WithoutConditions(Entity coefficient)
                => coefficient.InnerSimplified.Replace(node => node is Providedf(var inner, _) ? inner : node);
            (a0, a1, a2, b0, b1, b2) = (WithoutConditions(a0), WithoutConditions(a1), WithoutConditions(a2), WithoutConditions(b0), WithoutConditions(b1), WithoutConditions(b2));
            var coefficients = new Entity[2 * power];
            for (var i = 0; i < coefficients.Length; i++)
                coefficients[i] = monomials.TryGetValue(EInteger.FromInt32(i), out var monomial) ? WithoutConditions(monomial) : Number.Integer.Zero;

            var root = MathS.Sqrt(radicand);
            Entity answer = Number.Integer.Zero;
            for (var j = power; j >= 1; j--)
            {
                // The polynomial over A^j as L + A R: R's coefficients and L's.
                var rest = (Entity[])coefficients.Clone();
                var quotient = new Entity[System.Math.Max(rest.Length - 2, 0)];
                for (var d = rest.Length - 1; d >= 2; d--)
                {
                    var term = WithoutConditions(rest[d] / a2);
                    quotient[d - 2] = term;
                    rest[d] = Number.Integer.Zero;
                    rest[d - 1] = WithoutConditions(rest[d - 1] - term * a1);
                    rest[d - 2] = WithoutConditions(rest[d - 2] - term * a0);
                }
                var (g, h) = (rest.Length > 0 ? rest[0] : Number.Integer.Zero, rest.Length > 1 ? rest[1] : Number.Integer.Zero);
                if (j == 1)
                {
                    // sigma A + L over A, beside the root: sigma over the root alone, and L over A.
                    if (quotient.Length > 1 && quotient.Skip(1).Any(extra => !VanishesIdentically(extra)))
                        return null;
                    if (quotient.Length > 0 && !VanishesIdentically(quotient[0]))
                    {
                        if (Integration.ComputeIndefiniteIntegral(quotient[0] / root, x, integrateByParts: false) is not { } overTheRoot)
                            return null;
                        answer = answer + overTheRoot;
                    }
                    if (!VanishesIdentically(g) || !VanishesIdentically(h))
                    {
                        if (SolveALinearOverAQuadraticBesideTheRootOfAnother((g + h * x) / (quadratic * root), x) is not { } overTheQuadratic)
                            return null;
                        answer = answer + overTheQuadratic;
                    }
                    break;
                }
                // 2 L = 2 q A B + (p + q x) W + 2 A S, one equation for each power of x, in
                // p, q and S = S0 + S1 x + S2 x^2. The fourth power's gives S2, and the third's
                // and the second's S1 and S0, each linear in p and q; the first's and the
                // constant's are then two equations in p and q alone, solved by their
                // determinant, which is not zero where A and B have no root in common.
                var m = j - 1;
                var w3 = WithoutConditions(2 * a2 * b2 * (1 - 2 * m));
                var w2 = WithoutConditions(2 * a1 * b2 + a2 * b1 - 2 * m * (a1 * b2 + 2 * a2 * b1));
                var w1 = WithoutConditions(2 * a0 * b2 + a1 * b1 - 2 * m * (a1 * b1 + 2 * a2 * b0));
                var w0 = WithoutConditions(a0 * b1 - 2 * m * a1 * b0);
                // S2 = sigma2 q, S1 = alpha1 q + beta1 p, S0 = alpha0 q + beta0 p.
                var sigma2 = WithoutConditions(2 * b2 * (m - 1));
                var alpha1 = WithoutConditions(-(2 * (a2 * b1 + a1 * b2) + w2 + 2 * a1 * sigma2) / (2 * a2));
                var beta1 = WithoutConditions(-w3 / (2 * a2));
                var alpha0 = WithoutConditions(-(2 * (a2 * b0 + a1 * b1 + a0 * b2) + w1 + 2 * a0 * sigma2 + 2 * a1 * alpha1) / (2 * a2));
                var beta0 = WithoutConditions(-(w2 + 2 * a1 * beta1) / (2 * a2));
                // p and q from the constant's equation and the first power's.
                var pOfConstant = WithoutConditions(w0 + 2 * a0 * beta0);
                var qOfConstant = WithoutConditions(2 * a0 * b0 + 2 * a0 * alpha0);
                var pOfFirst = WithoutConditions(w1 + 2 * a0 * beta1 + 2 * a1 * beta0);
                var qOfFirst = WithoutConditions(2 * (a1 * b0 + a0 * b1) + w0 + 2 * a0 * alpha1 + 2 * a1 * alpha0);
                var determinant = WithoutConditions(pOfConstant * qOfFirst - qOfConstant * pOfFirst);
                if (VanishesIdentically(determinant))
                    return null;
                var pValue = WithoutConditions((2 * g * qOfFirst - 2 * h * qOfConstant) / determinant);
                var qValue = WithoutConditions((2 * h * pOfConstant - 2 * g * pOfFirst) / determinant);
                if ((long)pValue.Complexity + qValue.Complexity > LargestReducedCoefficients)
                    return null;
                var values = new[]
                {
                    pValue, qValue,
                    WithoutConditions(alpha0 * qValue + beta0 * pValue),
                    WithoutConditions(alpha1 * qValue + beta1 * pValue),
                    WithoutConditions(sigma2 * qValue),
                };
                answer = answer + (values[0] + values[1] * x) * root / MathS.Pow(quadratic, m);
                // What is left over A^(j - 1): R, and S.
                var next = new Entity[2 * m];
                for (var i = 0; i < next.Length; i++)
                {
                    Entity sum = i < quotient.Length ? quotient[i] : Number.Integer.Zero;
                    if (i < 3)
                        sum = sum + values[2 + i];
                    next[i] = WithoutConditions(sum);
                }
                // S is a quadratic, and over A^(j - 1) with j - 1 = 1 its square term is sigma's.
                if (m == 1 && !VanishesIdentically(values[4]))
                    next = new[] { next[0], next[1], WithoutConditions(values[4]) };
                coefficients = next;
            }
            answer = (answer / constant).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(answer, expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// A polynomial over a power of a linear beside the square root of a quadratic,
        /// <c>P/((x - p)^k sqrt(Q))</c> with <c>P</c> of degree below <c>k</c>, by the reciprocal
        /// of the linear as <see cref="SolveALinearBesideTheRootOfAQuadratic"/> takes it for a
        /// constant over the first power: under <c>t = 1/(x - p)</c> it is
        /// <c>-sgn(t) P(p + 1/t) t^(k - 1)/sqrt(R(t))</c> with
        /// <c>R(t) = Q(p) t^2 + Q'(p) t + a</c>, a polynomial over the root of a quadratic, which
        /// the reduction for those closes. The pieces the partial fractions leave over
        /// <c>t^3</c> when <c>cot(x)^3 sqrt(a + b tan(x) + c tan(x)^2)</c> is taken under the
        /// tangent.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        private static Entity? SolveAPolynomialOverAPowerOfALinearBesideTheRoot(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            Entity? radicand = null;
            Entity? linear = null;
            var power = 0;
            Entity constant = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                if (factor is Powf(var @base, Number.Rational half) && half == Number.Rational.Create(1, 2) && radicand is null)
                    radicand = @base;
                else if (linear is null && factor is Powf(var repeated, Number.Integer { EInteger.Sign: > 0 } whole) && whole.EInteger.CanFitInInt32())
                    (linear, power) = (repeated, whole.EInteger.ToInt32Unchecked());
                else
                    return null;
            }
            if (radicand is null || linear is null
                || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var m, out var n) || VanishesIdentically(m)
                || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out var b, out var c) || VanishesIdentically(a)
                || !TreeAnalyzer.TryGetPolynomial(numerator, x, out var read)
                || read.Keys.Any(degree => degree.Sign < 0 || degree.CompareTo(EInteger.FromInt32(power)) >= 0))
                return null;
            foreach (var coefficient in new[] { a, b, c, m, n, constant }.Concat(read.Values))
                if (coefficient.Evaled is Number.Complex and not Number.Real)
                    return null;
            var p = (-n / m).InnerSimplified;
            var atP = (a * p * p + b * p + c).InnerSimplified;
            // A root of the radicand leaves a linear under the root, which is not this.
            if (VanishesIdentically(atP)
                || Functions.PartialFractions.TaylorCoefficientsAtTheRoot(numerator, p, power, x) is not { } taylor)
                return null;
            var slopeAtP = (2 * a * p + b).InnerSimplified;
            var t = Variable.CreateUnique(expr, "t_recip");
            // P(p + 1/t) t^(k - 1) is the sum of the Taylor coefficients times t^(k - 1 - j), and
            // (x - p)^k is L^k/m^k.
            Entity polynomialInT = Number.Integer.Zero;
            for (var j = 0; j < power; j++)
                if (taylor[j].Evaled is not Number.Complex { IsZero: true })
                    polynomialInT += j == power - 1 ? taylor[j] : taylor[j] * MathS.Pow(t, Number.Integer.Create(power - 1 - j));
            var inT = (polynomialInT / (constant * MathS.Pow(m, Number.Integer.Create(power)))).InnerSimplified
                * MathS.Pow(atP * MathS.Sqr(t) + slopeAtP * t + a, Number.Rational.Create(-1, 2));
            if (SolveAPolynomialTimesAnOddHalfPowerOfAQuadratic(inT, t) is not { } g)
                return null;
            var answer = (-MathS.Signum(x - p) * g.Substitute(t, 1 / (x - p))).InnerSimplified;
            if (answer.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(answer, expr, x))
                return null;
            return answer;
        }

        /// <summary>
        /// A polynomial over a product of distinct linears, beside the square root of a
        /// quadratic above or below the bar, taken apart as the rational function it is over
        /// that root: <c>N sqrt(Q)/D</c> is <c>N Q/(D sqrt(Q))</c>, and <c>P/D</c> is a polynomial
        /// plus a constant over each linear, so the integrand is a polynomial over the root
        /// plus one <c>K/((x - p) sqrt(Q))</c> per linear -- the rule before this one's shape,
        /// each. And with a quadratic below the bar, a power of a linear or a power of the root's
        /// own quadratic, a linear over the quadratic or a polynomial over the power for each,
        /// every one of them closed beside the root.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Moses' <c>sqrt(A^2 + B^2 (1 - y^2))/(1 - y^2)</c>: the root is of <c>A^2 + B^2 - B^2 y^2</c>,
        /// so this is <c>(A^2 + B^2 - B^2 y^2)/((1 - y^2) sqrt(Q))</c>, whose rational part is
        /// <c>B^2 + (A^2)/(1 - y^2)</c>, and <c>1/(1 - y^2)</c> is a half over <c>1 - y</c> and a
        /// half over <c>1 + y</c>. Each piece is a line of the table, and the whole was declined:
        /// the Euler substitution takes the generic first substitution for a symbolic leading
        /// coefficient, with <c>sqrt(-B^2)</c> in it.
        /// </para>
        /// <para>
        /// Only where there is something to take apart -- at least two pieces, each strictly
        /// smaller: a polynomial over the root alone, or one linear with nothing divided out,
        /// is the rule before this one's or the chain's already, and asking again would be
        /// asking the same question. The polynomial part goes to the chain, for
        /// <c>x^n/sqrt(Q)</c> is the trigonometric substitution's or Euler's by its shape; the
        /// linears are closed.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveARationalFunctionBesideTheRootOfAQuadratic(Entity expr, Entity.Variable x)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            Entity? radicand = null;
            var rootBelow = false;
            var wholePower = 0;
            Entity above = Number.Integer.One;
            Entity below = Number.Integer.One;
            foreach (var (side, isBelow) in new[] { (numerator, false), (denominator, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is Powf(var @base, Number.Rational half) && half is not Number.Integer && @base.ContainsNode(x))
                    {
                        if (radicand is not null || half.ERational.Denominator.CompareTo(EInteger.FromInt32(2)) != 0
                            || !half.ERational.Numerator.CanFitInInt32())
                            return null;
                        radicand = @base;
                        var n = half.ERational.Numerator.ToInt32Unchecked();
                        rootBelow = isBelow != (n < 0);
                        // Q^(n/2) is Q^((|n| - 1)/2) sqrt(Q) on the side it is on.
                        wholePower = (System.Math.Abs(n) - 1) / 2;
                        if (wholePower > 0)
                        {
                            if (rootBelow) below = below * MathS.Pow(@base, wholePower);
                            else above = above * MathS.Pow(@base, wholePower);
                        }
                        continue;
                    }
                    if (factor.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(factor, x, out _))
                        return null;
                    if (isBelow) below = below * factor;
                    else above = above * factor;
                }
            if (radicand is null || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out _, out _)
                || a.Evaled is Number.Complex { IsZero: true })
                return null;
            // The quadratic standing whole beside its own root, up to a constant, is one power
            // of one base: `u^2 (1/2 - u^2/2)^(-1/2) / (1 - u^2)` is `sqrt(2) u^2 (1 - u^2)^(-3/2)`,
            // and is asked as that. Taken apart over the linears of `1 - u^2` instead, each
            // piece's answer carries a sign, `sgn(u - 1)`, of which the whole has no need --
            // and whose derivative is not read where the argument is not shown to be real, so
            // the answer to Timofeev's `arcsin(sqrt((x - a)/(x + a)))` could not be checked.
            if (WithTheQuadraticAsItsRoot(expr, radicand, x) is { } gathered)
                return Integration.ComputeIndefiniteIntegral(gathered, x, integrateByParts: false);
            // Written over the root: N sqrt(Q)/D is N Q/(D sqrt(Q)).
            if (!rootBelow)
                above = above * radicand;
            if (!below.ContainsNode(x))
                return null;

            // The denominator as distinct linears: factored over the integers where it is
            // numeric, and as written otherwise.
            var factors = new List<Entity>();
            Entity constant = Number.Integer.One;
            // Or with a quadratic among them, a power of one, a power of a linear, or a power of
            // the radicand: the partial fractions split over those as well, and each piece is
            // closed beside the root -- over a quadratic by the rule before this one, over a power
            // of a quadratic a power at a time down to that, over a power of a linear by its
            // reciprocal, over a power of the radicand by the reduction for a polynomial beside a
            // half-odd power. `tan(x)^5 sqrt(a + b tan(x) + c tan(x)^2)` is
            // `t^5 sqrt(a + b t + c t^2)/(1 + t^2)` under the tangent, a polynomial over the root
            // and a linear over `1 + t^2` beside it.
            var beyondTheLinears = false;
            var aQuadratic = false;
            var written = Functions.PolynomialFactoring.TryFactor(below, x, out var factored) && factored is not null ? factored : below;
            foreach (var factor in Mulf.LinearChildren(written))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = constant * factor;
                    continue;
                }
                if (TreeAnalyzer.TryGetPolyLinear(factor, x, out var slope, out _) && slope.Evaled is not Number.Complex { IsZero: true })
                {
                    factors.Add(factor);
                    continue;
                }
                var isAPowerOfALinear = factor is Powf(var repeated, Number.Integer { EInteger.Sign: > 0 })
                    && TreeAnalyzer.TryGetPolyLinear(repeated, x, out var repeatedSlope, out _) && repeatedSlope.Evaled is not Number.Complex { IsZero: true };
                var isAPowerOfTheRadicand = factor is Powf(var raised, Number.Integer { EInteger.Sign: > 0 }) && raised == radicand;
                var isAQuadratic = factor is not Powf && TreeAnalyzer.TryGetPolyQuadratic(factor, x, out var leading, out _, out _) && !VanishesIdentically(leading);
                var isAPowerOfAQuadratic = factor is Powf(var repeatedQuadratic, Number.Integer { EInteger.Sign: > 0 }) && repeatedQuadratic != radicand
                    && repeatedQuadratic is not Powf && TreeAnalyzer.TryGetPolyQuadratic(repeatedQuadratic, x, out var repeatedLeading, out _, out _)
                    && !VanishesIdentically(repeatedLeading);
                if (!isAPowerOfALinear && !isAPowerOfTheRadicand && !isAQuadratic && !isAPowerOfAQuadratic)
                    return null;
                factors.Add(factor);
                beyondTheLinears = true;
                aQuadratic |= isAQuadratic || isAPowerOfTheRadicand || isAPowerOfAQuadratic;
            }
            // Powers of linears only beside a quadratic, which is what the split is for: over
            // the linears alone the reciprocal writes a sign of each, `sgn(sqrt(1 + x) - 1)` once
            // `sqrt(x + sqrt(1 + x))/x^2` is taken back from `u = sqrt(1 + x)`, whose derivative
            // is not read where the argument is not shown real -- and Euler's substitution, after
            // this, answers those without one.
            if (beyondTheLinears && !aQuadratic)
                return null;
            // Distinct: two factors with the same root are one repeated, which is not this.
            // Beyond the linears the split decides that, and merges linears with one root.
            if (!beyondTheLinears)
                for (var i = 0; i < factors.Count; i++)
                    for (var j = i + 1; j < factors.Count; j++)
                        if (!TryReadAsQuotient(factors[i] / factors[j], out var top, out var bottom)
                            || Functions.PolynomialGcd.TryCancel(top, bottom, out _))
                            return null;
            var linears = factors.Aggregate(Number.Integer.One as Entity, (product, factor) => product * factor);

            // P/D as a polynomial plus a proper part, the proper part over each linear.
            Entity polynomialPart = Number.Integer.Zero;
            Entity properNumerator = above;
            // A zero is one with the condition the division writes on it as well, `0 provided not
            // 1 - t^2 = 0`, which read as a piece asks for its integral and declines the whole.
            static bool IsZero(Entity e) => Functions.PartialFractions.Bare(e).Evaled is Number.Complex { IsZero: true };
            if (TreeAnalyzer.PolynomialLongDivision(above, linears, genericCase: true, inTermsOf: x) is var (quotient, proper)
                && !IsZero(quotient))
            {
                polynomialPart = quotient;
                var (properTop, properBottom) = Functions.SingleQuotient.Of(proper);
                if (properBottom != linears && !TryReadAsQuotient(proper, out properTop, out properBottom))
                    return null;
                properNumerator = properTop;
                if (properNumerator.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(properNumerator, x, out _))
                    return null;
            }
            var pieces = new List<Entity>();
            if (!IsZero(polynomialPart))
                pieces.Add(polynomialPart);
            if (!IsZero(properNumerator))
            {
                if (factors.Count == 1)
                    pieces.Add(properNumerator / factors[0]);
                else if (Functions.PartialFractions.TrySplitOverWrittenFactors(properNumerator, linears, x, out var decomposition) && decomposition is not null)
                {
                    // The split comes back as a sum over a constant; the constant goes to each term.
                    var (terms, over) = decomposition is Divf(var splitTop, var splitBottom) && !splitBottom.ContainsNode(x)
                        ? (splitTop, splitBottom) : (decomposition, Number.Integer.One as Entity);
                    foreach (var term in Sumf.LinearChildren(terms))
                        if (!IsZero(term))
                            pieces.Add(term / over);
                }
                else
                    return null;
            }
            if (pieces.Count < 2)
                return null;   // nothing was taken apart

            var root = MathS.Pow(radicand, Number.Rational.Create(1, 2));
            Entity answer = Number.Integer.Zero;
            // Beyond the linears the pieces with a denominator first, so that one no rule closes
            // declines the whole before the chain is asked for the polynomial part.
            var inOrder = beyondTheLinears
                ? pieces.OrderBy(piece => piece.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(piece, x, out _) ? 0 : 1).ToList()
                : pieces;
            foreach (var piece in inOrder)
            {
                // Written as `coefficient / sqrt(Q)`, the shape the table reads for a constant.
                var overTheRoot = (piece / constant).InnerSimplified / root;
                // Beyond the linears each piece is closed where it can be, before the chain is
                // asked for a polynomial part as it always was: the pieces are asked a level
                // below a substitution already, where the scoped rules decline.
                var integrated = SolveALinearBesideTheRootOfAQuadratic(overTheRoot, x)
                    ?? (beyondTheLinears
                        ? SolveALinearOverAQuadraticBesideTheRootOfAnother(overTheRoot, x)
                            ?? SolveAPolynomialOverAPowerOfAQuadraticBesideTheRootOfAnother(overTheRoot, x)
                            ?? SolveAPolynomialOverAPowerOfALinearBesideTheRoot(overTheRoot, x)
                            ?? SolveAPolynomialTimesAnOddHalfPowerOfAQuadratic(
                                OverAPowerOfTheRadicand((piece / constant).InnerSimplified, radicand, x) ?? overTheRoot, x)
                        : null)
                    ?? (piece.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(piece, x, out _) ? null : Integration.ComputeIndefiniteIntegral(overTheRoot, x, integrateByParts: false));
                if (integrated is null)
                    return null;
                answer = answer + integrated;
            }
            answer = answer.InnerSimplified;
            return answer.Nodes.Any(node => node is Number.Complex { IsNaN: true }) ? null : answer;
        }

        /// <summary>
        /// A piece over a whole power of <paramref name="radicand"/>, beside its root, as the one
        /// half-odd power the two are: <c>(g + h x)/(Q^j sqrt(Q))</c> is
        /// <c>(g + h x) Q^(-j - 1/2)</c>, which the reduction for a polynomial beside a half-odd
        /// power reads and the two factors written apart it does not; null where the piece is
        /// over anything else.
        /// </summary>
        private static Entity? OverAPowerOfTheRadicand(Entity piece, Entity radicand, Entity.Variable x)
        {
            var (top, bottom) = Functions.SingleQuotient.Of(piece);
            var power = 0;
            Entity rest = Number.Integer.One;
            var written = radicand.InnerSimplified;
            foreach (var factor in Mulf.LinearChildren(bottom))
            {
                if (!factor.ContainsNode(x))
                    rest = rest * factor;
                else if (factor == radicand || factor == written)
                    power += 1;
                else if (factor is Powf(var @base, Number.Integer { EInteger.Sign: > 0 } whole) && (@base == radicand || @base == written)
                    && whole.EInteger.CanFitInInt32())
                    power += whole.EInteger.ToInt32Unchecked();
                else
                    return null;
            }
            return power == 0 ? null : top / rest * MathS.Pow(radicand, Number.Rational.Create(-(2 * power + 1), 2));
        }

        /// <summary>
        /// The product with a whole power of a constant multiple of <paramref name="radicand"/>
        /// written as that constant's power times the power of <paramref name="radicand"/>
        /// itself, so that the normalisation gathers it with the root; null where no factor is
        /// such a multiple, the factor that is <paramref name="radicand"/> as written included,
        /// since that one the normalisation has gathered already.
        /// </summary>
        private static Entity? WithTheQuadraticAsItsRoot(Entity expr, Entity radicand, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(radicand, x, out var radicandMonomials))
                return null;
            var found = false;
            Entity? rebuilt = null;
            foreach (var factor in Mulf.LinearChildren(expr))
            {
                var (@base, power) = factor is Powf(var inner, Number.Integer whole) ? (inner, whole) : (factor, Number.Integer.One);
                Entity written = factor;
                if (!found && @base != radicand && @base.ContainsNode(x) && ConstantRatio(@base) is { } ratio)
                {
                    found = true;
                    written = MathS.Pow(ratio, power) * MathS.Pow(radicand, power);
                }
                rebuilt = rebuilt is null ? written : rebuilt * written;
            }
            return found ? rebuilt : null;

            Entity? ConstantRatio(Entity polynomial)
            {
                if (!TreeAnalyzer.TryGetPolynomial(polynomial, x, out var monomials) || monomials.Count != radicandMonomials.Count)
                    return null;
                Entity? ratio = null;
                foreach (var pair in monomials)
                {
                    if (!radicandMonomials.TryGetValue(pair.Key, out var reference))
                        return null;
                    var here = (pair.Value / reference).InnerSimplified;
                    if (here.ContainsNode(x) || (ratio is not null && here != ratio))
                        return null;
                    ratio ??= here;
                }
                return ratio;
            }
        }

        /// <summary>
        /// A linear below the bar that divides the radicand of a half-odd power beside it, written
        /// over that radicand: the quadratic is <c>P = L M</c>, so <c>1/L</c> is <c>M/P</c> and
        /// <c>L^(-n) P^s</c> is <c>M^n P^(s - n)</c>, exactly, for a whole <c>n</c>.
        /// <c>x/((d + e x) sqrt(d^2 - e^2 x^2))</c> is the polynomial <c>x (d - e x)</c> over
        /// <c>(d^2 - e^2 x^2)^(3/2)</c>, which the rules for a polynomial beside a half-odd power
        /// of a quadratic answer. Rubi's 1.2.1.4 writes most of its rows this way.
        /// </summary>
        /// <remarks>
        /// The rules in front read a linear beside the root as a pole to take apart, and a linear
        /// that divides the radicand leaves nothing to take apart: its residue is the radicand's
        /// value at its root, zero. Only below the bar, so the rewrite never makes the shape it
        /// reads -- <c>M^n</c> is written above -- and a whole power only, where the rewrite
        /// needs no branch.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingALinearBelowTheBarOverTheRadicand(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // At the question asked only. Below it the rule rewrote what the substitution search
            // asks of each of its candidates, and every rewrite was a search of its own:
            // `1/(x^2 (d + e x) sqrt(a d e + (c d^2 + a e^2) x + c d e x^2))` declined in 80 ms
            // before the rule, ran past ninety seconds with it at every depth, and is answered
            // in half a second with it here.
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            if (!expr.Nodes.Any(node => node is Powf(var radicand, Number.Rational { ERational: var power })
                    && power.Denominator.Equals(EInteger.FromInt32(2)) && radicand.ContainsNode(x)))
                return null;
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            if (!below.ContainsNode(x))
                return null;
            // The factors on both sides of the bar as powers, those below with the exponent negated.
            var factors = new List<(Entity Base, Entity Exponent)>();
            foreach (var factor in Mulf.LinearChildren(above))
                factors.Add(factor is Powf(var @base, var exponent) ? (@base, exponent) : (factor, Number.Integer.One));
            foreach (var factor in Mulf.LinearChildren(below))
                factors.Add(factor is Powf(var @base, var exponent) ? (@base, (-exponent).InnerSimplified) : (factor, Number.Integer.MinusOne));
            // One half-odd power of a quadratic.
            var rootAt = -1;
            Entity? a = null, b = null, c = null;
            for (var i = 0; i < factors.Count; i++)
                if (factors[i].Exponent is Number.Rational { ERational: var power } and not Number.Integer
                    && power.Denominator.Equals(EInteger.FromInt32(2)) && factors[i].Base.ContainsNode(x))
                {
                    if (rootAt >= 0 || !TreeAnalyzer.TryGetPolyQuadratic(factors[i].Base, x, out a, out b, out c)
                        || a.Evaled is Number.Complex { IsZero: true })
                        return null;
                    rootAt = i;
                }
            if (rootAt < 0 || a is null || b is null || c is null)
                return null;
            // And nothing else in the integrand a root of x: this is a rational function beside
            // one root. Where the radicand's own factors stand under roots elsewhere --
            // `(1 - x^2)^(1/4)` beside `sqrt(1 - x)` and `sqrt(1 + x)`, Timofeev's 314 -- the
            // integrand is the two-linear-radicals rules', and the rewrite took it down a route
            // whose answer held `sgn(sqrt(1 - x))`, which nothing differentiates.
            for (var k = 0; k < factors.Count; k++)
                if (k != rootAt && factors[k].Base.ContainsNode(x)
                    && (factors[k].Exponent is not Number.Integer
                        || factors[k].Base.Nodes.Any(node => node is Powf(var inner, var power) && power is not Number.Integer && inner.ContainsNode(x))))
                    return null;
            for (var j = 0; j < factors.Count; j++)
            {
                if (factors[j].Exponent is not Number.Integer { IsNegative: true } negated
                    || !TreeAnalyzer.TryGetPolyLinear(factors[j].Base, x, out var slope, out var intercept)
                    || slope.Evaled is Number.Complex { IsZero: true })
                    continue;
                // L = l1 x + l0 divides P = a x^2 + b x + c where P vanishes at -l0/l1, which
                // times l1^2 is a l0^2 - b l0 l1 + c l1^2; the other factor is then
                // M = (a/l1) x + (b l1 - a l0)/l1^2.
                if (!VanishesIdentically(a * intercept * intercept - b * intercept * slope + c * slope * slope))
                    continue;
                // Each coefficient simplified where it holds a symbol: the normalisation leaves
                // `((c d^2 + a e^2) e - c d e d)/e^2` as written where it is `a e`, and the rules
                // below searched forty seconds on the one spelling and answered the other at once.
                var leading = (a / slope).InnerSimplified;
                var constant = ((b * slope - a * intercept) / (slope * slope)).InnerSimplified;
                if (leading.Vars.Any())
                    leading = Functions.PartialFractions.Bare(leading.Simplify());
                if (constant.Vars.Any())
                    constant = Functions.PartialFractions.Bare(constant.Simplify());
                var other = (leading * x + constant).InnerSimplified;
                var times = -negated;
                var (radicand, power) = factors[rootAt];
                Entity written = MathS.Pow(other, times) * MathS.Pow(radicand, (power - times).InnerSimplified);
                for (var k = 0; k < factors.Count; k++)
                    if (k != rootAt && k != j)
                        written = written * MathS.Pow(factors[k].Base, factors[k].Exponent);
                var rewritten = written.InnerSimplified;
                if (rewritten == expr || rewritten == expr.InnerSimplified)
                    return null;
                return Integration.ComputeAsTheSameQuestion(rewritten, x, integrateByParts);
            }
            return null;
        }

        /// <summary>
        /// Whether <paramref name="expr"/>, free of the variable, is zero for every value of its
        /// symbols: at a point first, which settles most of them without simplifying, and then
        /// simplified, since <see cref="Entity.InnerSimplified"/> leaves <c>a^2 b^2 - a^2 b^2</c>
        /// written as two terms.
        /// </summary>
        private static bool VanishesIdentically(Entity expr)
        {
            var inner = expr.InnerSimplified;
            if (inner.Evaled is Number.Complex { IsZero: true })
                return true;
            if (!inner.Vars.Any())
                return false;
            var pinned = inner;
            var values = new[] { 1.37, 0.61, 2.23, 1.91, 0.83, 1.13 };
            var index = 0;
            foreach (var symbol in inner.Vars.ToList())
                pinned = pinned.Substitute(symbol, values[index++ % values.Length]);
            if (pinned.Evaled is Number.Complex { IsNaN: false } value
                && ((Number.Real)value.Abs()).EDecimal.ToDouble() > 1e-9)
                return false;
            return Functions.PartialFractions.Bare(inner.Simplify()).Evaled is Number.Complex { IsZero: true };
        }

        /// <summary>
        /// A rational function of <c>x</c> and one square root of a quadratic in <c>x</c>,
        /// rationalised by an Euler substitution and handed to the rational integrator.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The trigonometric substitution beside this answers <c>x^m sqrt(a + b x^2)^k</c> and
        /// nothing wider; <c>sqrt(2 - x - x^2)/x^2</c>, <c>1/((4 + x^2) sqrt(1 + 4x^2))</c> and
        /// <c>x sqrt(2 r x - x^2)</c> had no antiderivative, and neither did any of the
        /// integrands that other rules reduce to a rational function of <c>x</c> and one such
        /// root -- the nested radicals of Bondarenko's suite under <c>u = sqrt(1 + x)</c>, the
        /// by-parts remainders of Charlwood's inverse functions.
        /// </para>
        /// <para>
        /// <b>Euler's three substitutions</b>, for <c>Q = a x^2 + b x + c</c>:
        /// </para>
        /// <list type="bullet">
        /// <item><c>a &gt; 0</c>: <c>sqrt(Q) = t - sqrt(a) x</c>, so <c>x = (t^2 - c)/(2 sqrt(a) t + b)</c>.</item>
        /// <item><c>c &gt; 0</c>: <c>sqrt(Q) = x t + sqrt(c)</c>, so <c>x = (2 sqrt(c) t - b)/(a - t^2)</c>.</item>
        /// <item><c>c = 0</c>: <c>sqrt(Q) = x t</c>, so <c>x = b/(t^2 - a)</c> -- the third substitution at
        /// the root the quadratic has at zero.</item>
        /// </list>
        /// <para>
        /// Each makes <c>x</c>, <c>sqrt(Q)</c> and <c>dx/dt</c> rational in <c>t</c>, so the
        /// integrand becomes a rational function of <c>t</c>; whichever applies with its radical
        /// a rational number is taken first, and a symbol in <c>a</c> or <c>c</c> takes the first
        /// in the generic case. The result goes to the rational integrator <b>directly</b> --
        /// long division, the splits, the Hermite reduction, the binomial rule -- and not back
        /// into the chain: an earlier Euler rule rewrote and handed on, and its cost was in the
        /// open search below it and in a <c>Simplify</c> it ran before it could tell whether it
        /// applied at all (https://github.com/asc-community/AngouriMath/issues/1265). This one
        /// decides by reading the tree, in microseconds, and finishes in one closed step or not
        /// at all.
        /// </para>
        /// <para>
        /// Bounded in the degree of the rational function it produces, since a degree the
        /// splits cannot factor is declined by them at a cost that grows with it. Asked, not
        /// volunteered, like every rule that lands on a search of any size.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByEulerSubstitution(Entity expr, Entity.Variable x)
        {

            // One square root of a quadratic in x, and otherwise a rational function of x --
            // or, besides those, powers of `x + sqrt(Q)` and `sqrt(Q) - x` to any exponent,
            // which the first substitution makes powers of `t`: see below.
            Entity? radicand = null;
            var powersOfTheSubstitution = new List<Powf>();
            foreach (var node in expr.Nodes)
            {
                if (!node.ContainsNode(x))
                    continue;
                switch (node)
                {
                    case Variable or Sumf or Minusf or Mulf or Divf:
                        break;
                    case Powf(_, Number.Integer):
                        break;
                    case Powf(var radicalBase, Number.Rational half) when half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                            && radicalBase.Nodes.All(inner => inner is not Powf(_, Number.Rational r) || r is Number.Integer):
                        if (radicand is null)
                            radicand = radicalBase;
                        else if (radicand != radicalBase)
                            return null;
                        break;
                    case Powf(var @base, var exponent) when !exponent.ContainsNode(x) && @base.Nodes.Any(inner => inner is Powf(_, Number.Rational)):
                        powersOfTheSubstitution.Add((Powf)node);
                        break;
                    default:
                        return null;
                }
            }
            // The radical inside such a power is the radical: `(x + sqrt(1 + x^2))^b` holds it.
            if (radicand is null)
                foreach (var power in powersOfTheSubstitution)
                    foreach (var inner in power.Base.Nodes)
                        if (inner is Powf(var innerBase, Number.Rational innerHalf) && innerHalf.ERational.Denominator.Equals(EInteger.FromInt32(2)) && innerBase.ContainsNode(x))
                        {
                            if (radicand is null) radicand = innerBase;
                            else if (radicand != innerBase) return null;
                        }
            if (radicand is null
                || !TreeAnalyzer.TryGetPolyQuadratic(radicand, x, out var a, out var b, out var c)
                || a.Evaled is Number.Complex { IsZero: true })
                return null;
            // A missing linear term is the trigonometric substitution's and answered more shortly there.
            if (b.Evaled is Number.Complex { IsZero: true } && expr.Nodes.Count(n => n == radicand) == 1
                && TryReadAPowerTimesARadicalQuadratic(expr, x))
                return null;

            // A perfect square under the root is no radical: `sqrt(u^2)` is `|u|`, which
            // `SolveByTakingARootOfAPerfectSquare` writes as `sgn(u) u`, and the substitution
            // written for it -- `t = sqrt(u^2) - u`, which is zero on half the line -- is
            // declined rather than made.
            if ((b * b - Number.Integer.Create(4) * a * c).InnerSimplified.Evaled is Number.Complex { IsZero: true })
                return null;

            var t = Variable.CreateUnique(expr, "t_euler");
            Entity xInT, rootInT;
            Entity backSubstitution;
            // A coefficient that is a number has to be a real one: `sqrt(x^2 - i)` is not a
            // radical any of the three substitutions is about, and taking `-i` for a symbol
            // produced `NaN` for an answer.
            if (a.Evaled is Number.Complex and not Number.Real || b.Evaled is Number.Complex and not Number.Real
                || c.Evaled is Number.Complex and not Number.Real)
                return null;
            var aValue = a.Evaled as Number.Real;
            var cValue = c.Evaled as Number.Real;
            Entity sqrtA = MathS.Sqrt(a).InnerSimplified;
            Entity sqrtC = MathS.Sqrt(c).InnerSimplified;
            var aPositive = aValue is { IsPositive: true };
            var cPositive = cValue is { IsPositive: true };
            var aRational = aPositive && sqrtA.Evaled is Number.Rational;
            var cRational = cPositive && sqrtC.Evaled is Number.Rational;
            // Whichever applies with its radical a rational number first; then a real one; then
            // the generic case for a symbol.
            int which;
            if (cValue is { IsZero: true }) which = 3;
            else if (aRational) which = 1;
            else if (cRational) which = 2;
            else if (aPositive) which = 1;
            else if (cPositive) which = 2;
            else if (aValue is null) which = 1;
            else if (cValue is null) which = 2;
            else if (aValue.IsNegative && cValue.IsNegative && b.Evaled is Number.Real)
            {
                // a < 0 and c < 0: the radical is real between the roots where there are two,
                // and none of the three substitutions reads that. Shifted to the vertex,
                // x = y - b/(2a), the quadratic is a y^2 + c' with c' = c - b^2/(4a), positive
                // exactly when the roots are real, and that is the second substitution's:
                // `1/(x sqrt(-5 + 10x - 4x^2))`, Hearn's under u = r^2.
                var shift = (-b / (2 * a)).InnerSimplified;
                if ((c - b * b / (4 * a)).Evaled is not Number.Real { IsPositive: true })
                    return null;
                var y = Variable.CreateUnique(expr, "y_euler");
                if (SolveByEulerSubstitution(expr.Substitute(x, y + shift), y) is not { } inY)
                    return null;
                // The radicand comes back written as `Q(x - s + s)`; it is written as `Q(x)`.
                var writtenBack = radicand.Substitute(x, y + shift).Substitute(y, x - shift);
                return inY.Substitute(y, x - shift).Replace(node => node == writtenBack ? radicand : node).InnerSimplified;
            }
            else return null;   // a < 0 and c < 0 with no real root: the radical is nowhere real

            switch (which)
            {
                case 3:
                    // sqrt(Q) = x t: x = b/(t^2 - a)
                    xInT = b / (MathS.Sqr(t) - a);
                    rootInT = xInT * t;
                    backSubstitution = MathS.Pow(radicand, Number.Rational.Create(1, 2)) / x;
                    break;
                case 1:
                    // sqrt(Q) = t - sqrt(a) x: x = (t^2 - c)/(2 sqrt(a) t + b)
                    xInT = (MathS.Sqr(t) - c) / (2 * sqrtA * t + b);
                    rootInT = t - sqrtA * xInT;
                    backSubstitution = MathS.Pow(radicand, Number.Rational.Create(1, 2)) + sqrtA * x;
                    break;
                default:
                    // sqrt(Q) = x t + sqrt(c): x = (2 sqrt(c) t - b)/(a - t^2)
                    xInT = (2 * sqrtC * t - b) / (a - MathS.Sqr(t));
                    rootInT = xInT * t + sqrtC;
                    backSubstitution = (MathS.Pow(radicand, Number.Rational.Create(1, 2)) - sqrtC) / x;
                    break;
            }

            // **A power of the substitution itself.** With `t = sqrt(Q) + sqrt(a) x`, a factor
            // `(x + sqrt(Q))^b` is `t^b` for `a = 1`, exactly and for any `b`, and `sqrt(Q) - x`
            // is `c/t`, since `(sqrt(Q) + x)(sqrt(Q) - x) = Q - x^2 = b x + c` -- `c/t` when the
            // linear term is absent. Welz's `(x + sqrt(b + x^2))^a` and Bondarenko's
            // `1/(1 + sqrt(x + sqrt(1 + x^2)))` are both this: the first becomes Laurent
            // monomials in `t` to the power `a`, the second a rational function of `sqrt(t)`,
            // and each is handed to the chain in `t` rather than to the rational integrator,
            // since neither is a quotient of polynomials.
            var powered = false;
            if (powersOfTheSubstitution.Count > 0)
            {
                if (which != 1 || !(a.Evaled is Number.Integer { IsZero: false } aOne && aOne.EInteger.Equals(EInteger.One)))
                    return null;
                // `x - sqrt(Q)` is the same substitution with the root's sign flipped:
                // `t = x - sqrt(Q)` gives the same `x(t)`, `sqrt(Q) = x - t` in place of `t - x`,
                // and `t = x - sqrt(Q)` on the way back. Both signs in one integrand is neither.
                var root = MathS.Pow(radicand, Number.Rational.Create(1, 2));
                var flipped = (bool?)null;
                foreach (var power in powersOfTheSubstitution)
                {
                    var plus = (power.Base - (x + root)).Simplify().Evaled is Number.Complex { IsZero: true };
                    var minus = (power.Base - (x - root)).Simplify().Evaled is Number.Complex { IsZero: true };
                    if (!plus && !minus)
                        return null;
                    if (flipped is null)
                        flipped = minus;
                    else if (flipped != minus)
                        return null;
                    expr = expr.Substitute(power, MathS.Pow(t, power.Exponent));
                }
                if (flipped == true)
                {
                    rootInT = xInT - t;
                    backSubstitution = x - root;
                }
                powered = true;
            }

            var dxdt = xInT.Differentiate(t);
            var rewritten = expr.Replace(node =>
                node is Powf(var @base, Number.Rational half) && @base == radicand
                    ? MathS.Pow(rootInT, Number.Integer.Create(half.ERational.Numerator))
                    : node)
                .Substitute(x, xInT) * dxdt;
            if (powered)
            {
                if (rewritten.ContainsNode(x))
                    return null;
                // With the written factors cancelled first: `1/sqrt(Q)` brings `(t^2 + c)` below
                // the bar and `dx/dt` brings it above, and beside a symbolic power of `t`
                // nothing later cancels them.
                var (poweredAbove, poweredBelow) = Functions.SingleQuotient.Of(rewritten.InnerSimplified);
                // The powers of t with an exponent that is not a whole number are set aside,
                // and what is left -- two polynomials in t -- is cancelled by their gcd, since
                // the two spellings of `t^2 + c` the substitution produces are not equal as
                // written; then they are put back.
                Entity setAside = Number.Integer.One;
                Entity polynomialAbove = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(poweredAbove))
                    if (factor is Powf(var pb, var pe) && pb == t && pe is not Number.Integer)
                        setAside = setAside * factor;
                    else
                        polynomialAbove = polynomialAbove * factor;
                Entity cancelledPowered = polynomialAbove / poweredBelow;
                if (Functions.PolynomialGcd.TryCancel(polynomialAbove.InnerSimplified, poweredBelow.InnerSimplified, out var poweredByGcd) && poweredByGcd is not null)
                    cancelledPowered = Functions.PartialFractions.Bare(poweredByGcd);
                var poweredInT = Functions.SingleQuotient.Combine(setAside * cancelledPowered).Simplify();
                if (poweredInT is Providedf(var bareInT, _))
                    poweredInT = bareInT;
                var inTByTheChain = Integration.ComputeIndefiniteIntegral(poweredInT, t, integrateByParts: true);
                if (inTByTheChain is null)
                    return null;
                var poweredAnswer = inTByTheChain.Substitute(t, backSubstitution).InnerSimplified;
                return poweredAnswer.Nodes.Any(n => n is Number.Complex { IsNaN: true }) ? null : poweredAnswer;
            }
            var (numerator, denominator) = Functions.SingleQuotient.Of(rewritten.InnerSimplified);
            var cancelled = CancelCommonFactors(numerator, denominator);
            (numerator, denominator) = Functions.SingleQuotient.Of(cancelled);
            // And by the polynomial gcd where the written factors do not match: the third
            // substitution leaves `(2t)^2 - 2(t^2 + 1)` above and `2t^2 - (t^2 + 1)` below for
            // `1/((1 + x^2)^2 sqrt(x^2 - 1))`, one factor twice the other, and the degree read
            // off the uncancelled quotient was ten where the bound is eight. Only where the
            // bound would otherwise refuse it, since the gcd hands back expanded sides and the
            // rational integrator does better with the written ones.
            // ...and only where the uncancelled degree is within twice the bound: the gcd of
            // two polynomials of degree thirty with the coefficients a power eleven over two
            // produces did not return in ninety seconds for `1/((3 - 2x + x^2)^(11/2) (1 + x + 2x^2)^5)`,
            // which the bound alone declined in a moment.
            if (TreeAnalyzer.TryGetPolynomial(numerator, t, out var beforeAbove) && TreeAnalyzer.TryGetPolynomial(denominator, t, out var beforeBelow)
                && System.Math.Max(beforeAbove.Count == 0 ? 0 : (int)beforeAbove.Keys.Max()!.ToInt32Checked(),
                                   beforeBelow.Count == 0 ? 0 : (int)beforeBelow.Keys.Max()!.ToInt32Checked()) is var uncancelled
                && uncancelled > MaximumEulerDegree && uncancelled <= 2 * MaximumEulerDegree
                && Functions.PolynomialGcd.TryCancel(numerator, denominator, out var byGcd) && byGcd is not null)
                (numerator, denominator) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(byGcd));
            // Each side rebuilt as a polynomial from its coefficients, so that a factor which has
            // collapsed to a constant -- `-1 - t^2 + 2 t t - 1 - t^2` is `-2` -- is one before
            // the rational readers see it: one of them divided by that factor's zero leading
            // coefficient and read a NaN. Every coefficient must be finite for the same reason.
            if (!TreeAnalyzer.TryGetPolynomial(numerator, t, out var above) || !TreeAnalyzer.TryGetPolynomial(denominator, t, out var below))
                return null;
            var degree = System.Math.Max(above.Count == 0 ? 0 : (int)above.Keys.Max()!.ToInt32Checked(),
                                         below.Count == 0 ? 0 : (int)below.Keys.Max()!.ToInt32Checked());
            if (degree > MaximumEulerDegree)
                return null;
            Entity? Rebuilt(Dictionary<EInteger, Entity> read)
            {
                Entity? built = null;
                foreach (var pair in read.OrderBy(pair => pair.Key))
                {
                    var coefficient = pair.Value.InnerSimplified;
                    if (coefficient.Evaled is Number.Complex { IsFinite: false })
                        return null;
                    if (coefficient.Evaled is Number.Complex { IsZero: true })
                        continue;
                    var k = pair.Key.ToInt32Checked();
                    Entity term = k == 0 ? coefficient : coefficient * (k == 1 ? t : MathS.Pow(t, k));
                    built = built is null ? term : built + term;
                }
                return built ?? Number.Integer.Zero;
            }
            // The denominator keeps its written factors -- with `sqrt(c)` irrational only the
            // split over written factors reads it -- and each factor is rebuilt on its own.
            Entity? cleanDenominator = null;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                var (@base, power) = factor is Powf(var b0, Number.Integer e0) ? (b0, e0) : (factor, Number.Integer.One);
                if (!TreeAnalyzer.TryGetPolynomial(@base, t, out var baseRead) || Rebuilt(baseRead) is not { } cleanBase)
                    return null;
                if (cleanBase == Number.Integer.Zero)
                    return null;
                Entity cleanFactor = power == Number.Integer.One ? cleanBase : MathS.Pow(cleanBase, power);
                cleanDenominator = cleanDenominator is null ? cleanFactor : cleanDenominator * cleanFactor;
            }
            if (Rebuilt(above) is not { } cleanNumerator || cleanDenominator is null)
                return null;
            var rational = cleanNumerator / cleanDenominator;

            // The Rothstein-Trager resultant behind the splits, for a denominator they cannot
            // take apart: `1/(1 + x sqrt(1 - x^2))` is one over a quartic in t irreducible over
            // the rationals, whose residues are in a quadratic field.
            // ...and a polynomial in t, which none of those reads: `1/(x sqrt(3x - x^2))` under
            // the third substitution is the constant -2/3.
            var inT = SolveByPartialFractions(rational, t, integrateByParts: false)
                   ?? IntegralPatterns.TryStandardIntegrals(rational, t)
                   ?? SolveByRothsteinTrager(rational, t)
                   ?? (cleanDenominator.Evaled is Number ? Integration.ComputeIndefiniteIntegral(rational, t, integrateByParts: false) : null);
            if (inT is null)
                return null;
            var answer = inT.Substitute(t, backSubstitution).InnerSimplified;
            // Not answering is legitimate; answering NaN is not.
            return answer.Nodes.Any(n => n is Number.Complex { IsNaN: true }) ? null : answer;
        }

        /// <summary>
        /// A rational function of <c>x</c> and one square root of a <b>palindromic quartic</b>
        /// <c>a x^4 + d x^3 + b x^2 + s d x + a</c>, integrated by <c>u = x - 1/x</c> or
        /// <c>u = x + 1/x</c> as <c>s</c> is <c>-1</c> or <c>+1</c>: the quartic is <c>x^2</c>
        /// times a quadratic in <c>u</c>, and the rest becomes a rational function of <c>u</c>
        /// where it is one.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Charlwood's <c>(1 + x^2)/((1 - x^2) sqrt(1 + x^4))</c> had no antiderivative. A root of
        /// a quartic is nothing Euler's substitutions or the trigonometric ones read, and it is
        /// not a binomial. But <c>1 + x^4 = x^2 (x^2 + 1/x^2) = x^2 ((x - 1/x)^2 + 2)</c>, and with
        /// <c>u = x - 1/x</c>, <c>du = (1 + 1/x^2) dx</c>, the integrand is <c>-du/(u sqrt(u^2 + 2))</c>
        /// -- a root of a quadratic over a rational function, which Euler answers. Its
        /// companion <c>(1 - x^2)/((1 + x^2) sqrt(1 + x^4))</c> wants <c>u = x + 1/x</c>, under
        /// which <c>x^2 + 1/x^2</c> is <c>u^2 - 2</c>. Both are tried.
        /// </para>
        /// <para>
        /// <b>The algebra.</b> With <c>u = x + s/x</c> for <c>s = -1</c> or <c>+1</c>:
        /// <c>x^2 + 1/x^2 = u^2 - 2s</c> and <c>x + s/x = u</c>, so
        /// <c>Q = a x^4 + d x^3 + b x^2 + s d x + a = x^2 (a u^2 + d u + b - 2 a s)</c>;
        /// and <c>dx = x^2 du/(x^2 - s)</c>. For <c>N/(D sqrt(Q))</c> the integrand is then
        /// <c>[N x/(D (x^2 - s))] du/sqrt(a u^2 + d u + b - 2as)</c>, and for <c>N sqrt(Q)/D</c> it
        /// is <c>[N x^3/(D (x^2 - s))] sqrt(a u^2 + d u + b - 2as) du</c>. Odd terms fix the
        /// sign: Timofeev's <c>(1 - x^2)/((1 + 2ax + x^2) sqrt(1 + 2ax + 2bx^2 + 2ax^3 + x^4))</c>
        /// is one of <c>u = x + 1/x</c> only, <c>-du/((u + 2a) sqrt(u^2 + 2au + 2b - 2))</c>, and
        /// its coefficients are symbols. The bracket is a rational
        /// function of <c>x</c>; the rule asks whether it is one of <c>u</c>, by undetermined
        /// coefficients on <c>P(u)/S(u)</c> and a check at sampled points, and declines where
        /// it is not -- which is the only way this can fail, and is exact.
        /// </para>
        /// <para>
        /// <b>The sign of <c>x</c>.</b> <c>sqrt(Q) = |x| sqrt(a u^2 + d u + b - 2as)</c>, and the
        /// rule takes <c>|x| = x</c>: what comes out is an antiderivative for <c>x &gt; 0</c>. It
        /// is made one everywhere by parity where the integrand has one, which is exact: an
        /// odd integrand has an even antiderivative, so <c>F(|x|)</c> serves on both sides, and
        /// an even one has an odd antiderivative, <c>sgn(x) F(|x|)</c>. An integrand of neither
        /// parity -- every one with odd terms under the root -- is answered by the sign of
        /// <c>x</c> instead: the integrand in <c>u</c> is <c>sgn(x) R(u) du/sqrt(q(u))</c> on both
        /// sides, so <c>sgn(x) G(x + s/x)</c> is an antiderivative on both, and is what is
        /// returned. A caller that knows its variable is positive, as the exponential
        /// substitution does of <c>u = e^x</c>, says so and gets <c>G(x + s/x)</c> bare.
        /// </para>
        /// <para>
        /// A half-odd power of the quartic, <c>Q^(3/2)</c>, is <c>Q sqrt(Q)</c>, a whole power
        /// beside the root, and is read as that: <c>sinh(x)^2 sinh(2x)/(1 - sinh(x)^2)^(3/2)</c>
        /// under <c>u = e^x</c> is a rational function over <c>(6u^2 - u^4 - 1)^(3/2)</c>.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByReciprocalSubstitution(Entity expr, Entity.Variable x, bool variableIsPositive = false)
        {
            if (!Integration.AnsweringTheQuestionAsked && !variableIsPositive)
                return null;
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);

            // Exactly one radical, a half-odd power of a palindromic quartic, as a factor above
            // or below the bar; polynomials elsewhere.
            Entity? quartic = null;
            var rootBelow = false;
            Entity above = Number.Integer.One;
            Entity below = Number.Integer.One;
            foreach (var (side, isBelow) in new[] { (numerator, false), (denominator, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is Powf(var @base, Number.Rational half) && half is not Number.Integer && @base.ContainsNode(x))
                    {
                        if (quartic is not null || half.ERational.Denominator.CompareTo(EInteger.FromInt32(2)) != 0
                            || !half.ERational.Numerator.CanFitInInt32())
                            return null;
                        quartic = @base;
                        var n = half.ERational.Numerator.ToInt32Unchecked();
                        rootBelow = isBelow != (n < 0);
                        // Q^(n/2) = Q^((|n| - 1)/2) sqrt(Q), the whole power on the root's side.
                        var whole = (System.Math.Abs(n) - 1) / 2;
                        if (whole > 0)
                        {
                            if (rootBelow) below = below * MathS.Pow(@base, whole);
                            else above = above * MathS.Pow(@base, whole);
                        }
                        continue;
                    }
                    if (factor.ContainsNode(x) && !TreeAnalyzer.TryGetPolynomial(factor, x, out _))
                        return null;
                    if (isBelow) below = below * factor;
                    else above = above * factor;
                }
            if (quartic is null || !TreeAnalyzer.TryGetPolynomial(quartic, x, out var read))
                return null;
            Entity Coefficient(int degree) => read.TryGetValue(EInteger.FromInt32(degree), out var c) ? c : Number.Integer.Zero;
            if (read.Keys.Any(k => !k.CanFitInInt32() || k.ToInt32Unchecked() is not (0 or 1 or 2 or 3 or 4)))
                return null;
            var a = Coefficient(4);
            var b = Coefficient(2);
            var c = Coefficient(0);
            // The odd terms: `d x^3 + e x` is `x^2 (d x + e/x)`, which is `d x^2 u` under
            // `u = x + s/x` exactly when `e = s d`. Timofeev's
            // `sqrt(1 + 2ax + 2bx^2 + 2ax^3 + x^4)` is one, under `u = x + 1/x`, and its
            // coefficients are symbols: a coefficient is a real number or not a number at all.
            var d = Coefficient(3);
            var e = Coefficient(1);
            static bool IsRealOrSymbolic(Entity coefficient) => coefficient.Evaled is Number.Real || coefficient.Evaled is not Number;
            // `2a - 2a` is not collected by the inner simplification; the full one is asked
            // only where the difference is not a number already.
            static bool IsIdenticallyZero(Entity difference) => difference.Evaled is Number number ? number == 0 : TreeAnalyzer.IsZero(difference.Simplify());
            if (a.Evaled is not Number.Real { IsZero: false } || !IsIdenticallyZero(a - c)
                || !IsRealOrSymbolic(b) || !IsRealOrSymbolic(d) || !IsRealOrSymbolic(e))
                return null;

            foreach (var sign in new[] { -1, 1 })
            {
                if (!IsIdenticallyZero(e - sign * d))
                    continue;
                // R(x) = N x^k / (D (x^2 - s)), k = 1 with the root below, 3 above.
                var bracket = above * (rootBelow ? x : MathS.Pow(x, 3)) / (below * (MathS.Sqr(x) - sign));
                if (!TryWriteInTheReciprocalVariable(bracket, x, sign, out var u, out var inU))
                    continue;
                var quadratic = a * MathS.Sqr(u) + d * u + (b - 2 * sign * a);
                var integrand = (inU * MathS.Pow(quadratic, Number.Rational.Create(rootBelow ? -1 : 1, 2))).InnerSimplified;
                if (Integration.ComputeIndefiniteIntegral(integrand, u, integrateByParts: true) is not { } inTermsOfU)
                    continue;
                var forPositiveX = inTermsOfU.Substitute(u, x + Number.Integer.Create(sign) / x);
                if (forPositiveX.Nodes.Any(node => node == MathS.NaN))
                    continue;
                if (variableIsPositive)
                    return forPositiveX;

                // Extended to x < 0 by parity where the integrand has one, and by the sign
                // of x otherwise: sqrt(Q) is |x| sqrt(q(u)) on both sides, so the integrand
                // in u carries a factor sgn(x) there, and sgn(x) G(u(x)) is exact everywhere.
                return ExtendedByParity(expr, forPositiveX, x) ?? MathS.Signum(x) * forPositiveX;
            }
            return null;
        }

        /// <summary>
        /// Whether every fractional power of a quotient in <paramref name="x"/> in
        /// <paramref name="expr"/> has a monomial in <paramref name="x"/> below its bar, and
        /// there is at least one: the shape <c>sqrt(1/(c x)^2 - 1)</c> has, and
        /// <c>sqrt((1 + x)/(1 - x))</c> has not.
        /// </summary>
        private static bool EveryRootStandsOverAMonomial(Entity expr, Entity.Variable x)
        {
            var any = false;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer || !@base.ContainsNode(x))
                    continue;
                var (above, below) = Functions.SingleQuotient.Of(AsOneQuotient(@base));
                if (below == Number.Integer.One || !below.ContainsNode(x))
                    continue;
                // ...and a polynomial above it, so that what comes out is the root of a
                // polynomial: `(1 + ln(u^2)/u^2)^(-3/2)` has a monomial below and is not this,
                // and written apart at every depth it fed Bronstein's `sqrt(x + ln(x))` search.
                if (!TreeAnalyzer.TryGetPolynomial(below, x, out var monomials) || monomials.Count != 1
                    || !TreeAnalyzer.TryGetPolynomial(above, x, out _))
                    return false;
                any = true;
            }
            return any;
        }

        /// <summary>
        /// <paramref name="forPositive"/>, an antiderivative of <paramref name="integrand"/> for
        /// <paramref name="x"/> positive, extended to the other side by parity, which is exact:
        /// an odd integrand has an even antiderivative, so <c>F(|x|)</c> serves on both sides,
        /// and an even one has an odd antiderivative, <c>sgn(x) F(|x|)</c>. An integrand of
        /// neither parity is declined rather than answered on half the line.
        /// </summary>
        private static Entity? ExtendedByParity(Entity integrand, Entity forPositive, Entity.Variable x)
        {
            // In the generic case, as every rule answers: the conditions a simplification
            // attached on the way -- each denominator nonzero -- are not part of the answer.
            forPositive = Functions.PartialFractions.Bare(forPositive);
            var reflected = integrand.Substitute(x, -x);
            if (Functions.PartialFractions.HoldsAtSampledPoints(reflected, -integrand, x))
                return forPositive.Substitute(x, MathS.Abs(x));
            if (Functions.PartialFractions.HoldsAtSampledPoints(reflected, integrand, x))
                return MathS.Signum(x) * forPositive.Substitute(x, MathS.Abs(x));
            return null;
        }

        /// <summary>
        /// The rational function <paramref name="bracket"/> of <paramref name="x"/> written as
        /// one of <c>u = x + sign/x</c>, by undetermined coefficients on <c>P(u)/S(u)</c> and a
        /// check at sampled points; <see langword="false"/> where it is not one.
        /// </summary>
        private static bool TryWriteInTheReciprocalVariable(Entity bracket, Entity.Variable x, int sign, out Entity.Variable u, out Entity inU)
        {
            u = Variable.CreateUnique(bracket, "u_recip");
            inU = Number.Integer.Zero;
            var simplified = bracket.InnerSimplified;
            if (simplified is Providedf(var bare, _))
                simplified = bare;
            var (top, bottom) = Functions.SingleQuotient.Of(simplified);
            if (!TreeAnalyzer.TryGetPolynomial(top, x, out var topRead) || !TreeAnalyzer.TryGetPolynomial(bottom, x, out var bottomRead))
                return false;
            var degree = System.Math.Max(
                topRead.Count == 0 ? 0 : topRead.Keys.Max()!.ToInt32Checked(),
                bottomRead.Count == 0 ? 0 : bottomRead.Keys.Max()!.ToInt32Checked());
            // Cancelled by the polynomial gcd where the written bracket runs past the bound
            // but not far past it: the exponential substitution hands the quartic to a whole
            // power beside its root, and `(u^2 - 1)^2 (u^4 - 1) u^3/(u^5 Q (u^2 + 1))` is
            // degree eleven as written and `-(u^2 - 1)^3/(u^3 (u^2 + 1/u^2 - 6))` in lowest terms.
            if (degree > MaximumReciprocalDegree && degree <= 2 * MaximumReciprocalDegree
                && Functions.PolynomialGcd.TryCancel(top, bottom, out var byGcd) && byGcd is not null)
            {
                (top, bottom) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(byGcd));
                if (!TreeAnalyzer.TryGetPolynomial(top, x, out topRead) || !TreeAnalyzer.TryGetPolynomial(bottom, x, out bottomRead))
                    return false;
                degree = System.Math.Max(
                    topRead.Count == 0 ? 0 : topRead.Keys.Max()!.ToInt32Checked(),
                    bottomRead.Count == 0 ? 0 : bottomRead.Keys.Max()!.ToInt32Checked());
            }
            if (degree > MaximumReciprocalDegree)
                return false;

            // A(x) S(u) = B(x) P(u), multiplied through by x^m so that u^j is the polynomial
            // x^(m-j) (x^2 + s)^j: one linear identity in x per monomial, in the coefficients
            // of P and S. Homogeneous, so one coefficient of S is set to one -- each in turn,
            // since the right one is whichever S has.
            var m = degree;
            var powersOfU = new List<Entity>();
            for (var j = 0; j <= m; j++)
                powersOfU.Add(Functions.PartialFractions.Bare((MathS.Pow(x, m - j) * MathS.Pow(MathS.Sqr(x) + sign, j)).Expand()));
            var columns = new List<Dictionary<EInteger, Entity>>();
            // Expanding attaches the conditions it cleared denominators under; the columns are
            // polynomials and want none of them.
            for (var i = 0; i <= m; i++)
            {
                if (!TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare((-bottom * powersOfU[i]).Expand()), x, out var column)) return false;
                columns.Add(column);
            }
            for (var j = 0; j <= m; j++)
            {
                if (!TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare((top * powersOfU[j]).Expand()), x, out var column)) return false;
                columns.Add(column);
            }
            var monomials = columns.SelectMany(column => column.Keys).Distinct().OrderBy(k => k).ToList();
            for (var fixedS = 0; fixedS <= m; fixedS++)
            {
                var fixedColumn = m + 1 + fixedS;
                var unknowns = Enumerable.Range(0, 2 * (m + 1)).Where(k => k != fixedColumn).ToList();
                var matrix = new Entity[monomials.Count][];
                var rhs = new Entity[monomials.Count];
                for (var row = 0; row < monomials.Count; row++)
                {
                    matrix[row] = new Entity[unknowns.Count];
                    for (var k = 0; k < unknowns.Count; k++)
                        matrix[row][k] = columns[unknowns[k]].TryGetValue(monomials[row], out var entry) ? entry : Number.Integer.Zero;
                    rhs[row] = columns[fixedColumn].TryGetValue(monomials[row], out var fixedEntry) ? -fixedEntry : Number.Integer.Zero;
                }
                var solved = Functions.PartialFractions.TrySolveLinearWithSymbols(matrix, rhs, out var values);
                if (!solved || values is null)
                    continue;
                Entity p = Number.Integer.Zero;
                Entity q = Number.Integer.Zero;
                for (var k = 0; k < unknowns.Count; k++)
                {
                    var index = unknowns[k];
                    var value = values[k].InnerSimplified;
                    if (value.Evaled is Number.Complex { IsZero: true })
                        continue;
                    if (index <= m)
                        p += value * MathS.Pow(u, index);
                    else
                        q += value * MathS.Pow(u, index - m - 1);
                }
                q += MathS.Pow(u, fixedS);
                if (p.Evaled is Number.Complex { IsZero: true })
                    continue;
                var candidate = (p / q).InnerSimplified;
                if (candidate is Providedf(var inner, _))
                    candidate = inner;
                // Checked as a fact about the function, not the arithmetic.
                if (!Functions.PartialFractions.HoldsAtSampledPoints(bracket, candidate.Substitute(u, x + Number.Integer.Create(sign) / x), x))
                    continue;
                inU = candidate;
                return true;
            }
            return false;
        }

        /// <summary>The largest degree the reciprocal substitution rewrites; past it the system is not worth building.</summary>
        private const int MaximumReciprocalDegree = 6;

        /// <summary>
        /// The largest degree, in <c>t</c>, of the rational function
        /// <see cref="SolveByEulerSubstitution"/> hands to the rational integrator.
        /// </summary>
        private const int MaximumEulerDegree = 8;

        /// <summary>
        /// Whether <paramref name="expr"/> is <c>x^m sqrt(a + b x^2)^k</c> up to a constant --
        /// the shape the trigonometric substitution answers.
        /// </summary>
        private static bool TryReadAPowerTimesARadicalQuadratic(Entity expr, Entity.Variable x)
        {
            foreach (var (factor, _) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                    continue;
                if (factor == x || factor is Powf(var b1, Number.Integer) && b1 == x)
                    continue;
                if (factor is Powf(var b2, Number.Rational) && TreeAnalyzer.TryGetPolyQuadratic(b2, x, out _, out var linear, out _)
                    && linear.Evaled is Number.Complex { IsZero: true })
                    continue;
                return false;
            }
            return true;
        }

        /// <summary>
        /// A product of sines and cosines of <b>different</b> arguments, rewritten as a sum by the
        /// product-to-sum identities and then integrated term by term.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sin(A)sin(B) = (cos(A - B) - cos(A + B))/2</c>,
        /// <c>cos(A)cos(B) = (cos(A - B) + cos(A + B))/2</c>,
        /// <c>sin(A)cos(B) = (sin(A + B) + sin(A - B))/2</c>. Each application turns two factors
        /// into a sum of two single ones, and a sine or cosine of something linear in the variable
        /// is a rule the integrator already has — so the whole family comes out at once.
        /// <c>sin(x)sin(2x)</c>, <c>cos(x)cos(2x)</c>, <c>cos(3x)sin(2x)</c> and
        /// <c>sin(x)sin(2x)sin(3x)</c> had no antiderivative between them.
        /// </para>
        /// <para>
        /// <b>Why this rather than a substitution.</b> These are the shapes every substitution in
        /// the chain declines, and rightly: there is no inner function to substitute for. A
        /// product of trigonometric functions of unequal arguments is not a function of any one of
        /// them, which is what <see cref="SolveByHalfAngleSubstitution"/> notices when it finds an
        /// <c>x</c> left over after rewriting — <c>sin(2x)</c> is not <c>sin(x)</c>. The identity
        /// is the tool, not a change of variable.
        /// </para>
        /// <para>
        /// <b>It terminates.</b> Each rewrite replaces two trigonometric factors with a sum whose
        /// terms hold one each, so the number of such factors in any one product strictly
        /// decreases, and the recursion is over strictly simpler products. Arguments equal to each
        /// other are left alone, since <c>sin(A)^2</c> is a power rather than a product of two
        /// arguments and wants a reduction formula instead.
        /// </para>
        /// <para>
        /// <b>Nothing is assumed and no condition is owed.</b> These are identities on the whole
        /// complex plane, not rewrites that hold on an interval: both sides are entire, so unlike
        /// every substitution here the answer is an antiderivative everywhere the integrand is,
        /// with no branch to pick and no interval to be inside.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByProductToSum(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (RewriteOneProduct(expr, x) is not { } rewritten)
                return null;
            return Integration.ComputeIndefiniteIntegral(rewritten, x, integrateByParts);
        }

        /// <summary>
        /// The product with one pair of trigonometric factors replaced by the sum it equals, or
        /// <see langword="null"/> where there is no such pair.
        /// </summary>
        private static Entity? RewriteOneProduct(Entity expr, Entity.Variable x)
        {
            var factors = Mulf.LinearChildren(expr).ToList();
            if (factors.Count < 2)
                return null;

            // A whole power of a sine or a cosine is that many factors: Hearn's
            // `cos(x)^2 sin(2x + 3)` is `cos(x) (cos(x) sin(2x + 3))`, and one pair at a time
            // still leaves fewer trigonometric factors than it found.
            static (Entity Base, int Power) Unpowered(Entity factor)
                => factor is Powf(var @base, Number.Integer n) && @base is Sinf or Cosf && n.EInteger.Sign > 0 && n.EInteger.CanFitInInt32()
                    ? (@base, n.EInteger.ToInt32Checked())
                    : (factor, 1);
            for (var i = 0; i < factors.Count; i++)
                for (var j = i + 1; j < factors.Count; j++)
                {
                    var (first, firstPower) = Unpowered(factors[i]);
                    var (second, secondPower) = Unpowered(factors[j]);
                    // Both arguments have to mention the variable. A sine of a constant is a
                    // number as far as this integral is concerned, and pairing it with a real
                    // factor would turn one term into two for nothing.
                    var replacement = (first, second) switch
                    {
                        (Sinf(var a), Sinf(var b)) when a != b && a.ContainsNode(x) && b.ContainsNode(x)
                            => (MathS.Cos(a - b) - MathS.Cos(a + b)) / 2,
                        (Cosf(var a), Cosf(var b)) when a != b && a.ContainsNode(x) && b.ContainsNode(x)
                            => (MathS.Cos(a - b) + MathS.Cos(a + b)) / 2,
                        (Sinf(var a), Cosf(var b)) when a != b && a.ContainsNode(x) && b.ContainsNode(x)
                            => (MathS.Sin(a + b) + MathS.Sin(a - b)) / 2,
                        (Cosf(var a), Sinf(var b)) when a != b && a.ContainsNode(x) && b.ContainsNode(x)
                            => (MathS.Sin(b + a) + MathS.Sin(b - a)) / 2,
                        _ => (Entity?)null
                    };
                    if (replacement is null)
                        continue;

                    var product = replacement;
                    if (firstPower > 1)
                        product *= firstPower == 2 ? first : MathS.Pow(first, firstPower - 1);
                    if (secondPower > 1)
                        product *= secondPower == 2 ? second : MathS.Pow(second, secondPower - 1);
                    for (var k = 0; k < factors.Count; k++)
                        if (k != i && k != j)
                            product *= factors[k];
                    return product;
                }
            return null;
        }

        /// <summary>
        /// A rational function of <c>e^(k x)</c>, turned into a rational function of one variable
        /// by <c>u = e^(k x)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// With <c>u = e^(k x)</c> we have <c>dx = du/(k u)</c>, and every exponential in the
        /// integrand becomes a whole power of <c>u</c>, so a quotient built from them is a
        /// quotient of polynomials — which the rational integrator answers.
        /// </para>
        /// <para>
        /// <b>What was missing.</b> <c>1/(1 + e^x)</c> had no antiderivative, and neither did
        /// <c>1/(e^x + e^(-x))</c>. <c>e^x/(1 + e^x)</c> did, which is the shape of the gap: the
        /// general substitution answers an exponential integrand only when the numerator happens
        /// to be the derivative of something in it, and declines the rest for want of anything to
        /// substitute for.
        /// </para>
        /// <para>
        /// <b>It is also how the hyperbolic functions get integrated</b>, since they are not nodes
        /// here — <c>tanh(x)</c> is built as <c>(e^(2x) - 1)/(e^(2x) + 1)</c> and <c>sech(x)</c>
        /// as <c>2/(e^x + e^(-x))</c>, so both are rational functions of an exponential, and
        /// <c>tanh</c>, <c>coth</c>, <c>sech</c> and <c>csch</c> had no antiderivative at all.
        /// </para>
        /// <para>
        /// The answers come out in the exponential rather than as <c>ln(cosh(x))</c> or
        /// <c>2 arctan(e^x)</c>, and unfolded — the rational integrator writes a logarithm as
        /// <c>ln((2ax + b - D)/(2ax + b + D))</c> and leaves the arithmetic in the coefficients
        /// standing. That is its shape on plain rational integrands too, not something this
        /// rewrite introduces; <c>1/(x(x+1))</c> comes out as
        /// <c>ln((2x + 1 - 1)/(2x + 1 + 1))</c> with nothing exponential in sight.
        /// </para>
        /// <para>
        /// <b>One <c>k</c> for the whole integrand.</b> The exponents are read as linear in the
        /// variable and their slopes taken together by greatest common divisor, so <c>e^x</c>
        /// beside <c>e^(2x)</c> gives <c>u</c> and <c>u^2</c> under one substitution. A slope that
        /// is not a whole number, or an exponent that is not linear — <c>e^(x^2)</c>, whose
        /// integral is not elementary at all — is declined.
        /// </para>
        /// <para>
        /// <b>No condition is owed.</b> <c>e^(k x)</c> is positive for every real <c>x</c> and
        /// never zero, so the substitution is invertible on the whole line and introduces no
        /// interval of its own; <c>u</c> is a genuine change of variable rather than a branch.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        /// <summary>
        /// A quotient by an exponential, handed on as the product with its reciprocal:
        /// <c>N/b^(f(x))</c> as <c>N * b^(-f(x))</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sin(x) * e^(-x)</c> had an antiderivative and <c>sin(x)/e^x</c> did not. They are
        /// the same integrand, and the difference is only which node is on top: integration by
        /// parts matches a <c>Mulf</c> and nothing else, so a quotient never reached it. The
        /// simplifier does not turn one into the other — it keeps <c>sin(x)/e^x</c> as written —
        /// so nothing upstream closed the gap either.
        /// </para>
        /// <para>
        /// The family is wider than the trigonometric case that exposed it: <c>x/e^x</c>,
        /// <c>ln(x)/e^x</c> and <c>sin(x)/2^x</c> were all declined for the same reason, and each
        /// is answered once written as a product.
        /// </para>
        /// <para>
        /// <b>Only an exponential denominator</b> — a base free of the variable with the variable
        /// in the exponent. <c>x^n</c> in a denominator is a rational function and belongs to
        /// partial fractions, which reads it as written; turning that into a negative power would
        /// take it away from the rules that answer it. A numerator free of the variable is left
        /// alone too, since <see cref="SolveAsPolynomialTerm"/> already takes that one.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByDividingByAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not Divf(var numerator, var denominator))
                return null;
            if (!numerator.ContainsNode(x))
                return null;
            if (denominator is not Powf(var @base, var power))
                return null;
            if (@base.ContainsNode(x) || !power.ContainsNode(x))
                return null;

            return Integration.ComputeIndefiniteIntegral(
                numerator * MathS.Pow(@base, (-power).InnerSimplified), x, integrateByParts);
        }

        /// <summary>
        /// An exponential of a quadratic in the reciprocal of a linear, beside a whole power of
        /// the linear: <c>L^m F^(A/L^2 + B/L + C)</c> with <c>L = c + d x</c>. Under <c>u = 1/L</c>,
        /// <c>dx = -du/(d u^2)</c>, and it is <c>-(1/d) u^(-m - 2) F^(A u^2 + B u + C)</c>: the
        /// Gaussian beside a power, which the table's moments answer, written back with
        /// <c>u = 1/L</c>. Rubi's 2.3, <c>f^(a + b/x^2) x^m</c> and <c>F^(a + b/(c + d x)^2) (c + d x)^m</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// The exponent is rewritten into <c>u</c> a node at a time -- <c>b/L^k</c> is <c>b u^k</c> --
        /// rather than by substituting <c>x = (1/u - c)/d</c> and asking the simplifier to see
        /// that <c>1/(1/u)^2</c> is <c>u^2</c>.
        /// </remarks>
        internal static Entity? SolveAGaussianInAReciprocal(Entity expr, Entity.Variable x)
        {
            if (ReadAnExponentialInTheReciprocalOfALinear(expr, x) is not var (constant, @base, exponentInU, u, linear, slope, power)
                || !TreeAnalyzer.TryGetPolyQuadratic(exponentInU, u, out var square, out _, out _) || TreeAnalyzer.IsZero(square))
                return null;
            var powerInU = -power - EInteger.FromInt32(2);
            if (!powerInU.CanFitInInt32() || powerInU.Abs().CompareTo(EInteger.FromInt32(32)) > 0)
                return null;
            var gaussian = MathS.Pow(@base, exponentInU);
            var inU = powerInU.IsZero ? gaussian : MathS.Pow(u, Number.Integer.Create(powerInU)) * gaussian;
            if (IntegralPatterns.TryStandardIntegrals(inU, u) is not { } answerInU)
                return null;
            return (-constant / slope * answerInU.Substitute(u, 1 / linear)).InnerSimplified;
        }

        /// <summary>
        /// The same substitution where the exponent is not a Gaussian in <c>u = 1/L</c>:
        /// <c>L^m F^(a + b/L)</c> or <c>L^m F^(a + b/L^3)</c> is
        /// <c>-(1/d) u^(-m - 2) F^(a + b u)</c> or <c>F^(a + b u^3)</c>, an exponential beside a
        /// power, asked as a question in <c>u</c> and written back with <c>u = 1/L</c>.
        /// </summary>
        /// <remarks>
        /// Rubi's 2.3, <c>F^(a + b/(c + d x)) (c + d x)^2</c>, <c>F^(a + b/(c + d x))/(c + d x)</c>
        /// and <c>F^(a + b/(c + d x)^3)/(c + d x)</c>, were declined: the substitution was made only
        /// for a Gaussian, whose moments the table answers, and an exponential of a linear or a
        /// cube in <c>u</c> beside a power of it is the exponential integral's, or a power of the
        /// cube's argument under <c>w = u^3</c>, which the integrator answers when asked in
        /// <c>u</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAnExponentialInTheReciprocalOfALinear(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (ReadAnExponentialInTheReciprocalOfALinear(expr, x) is not var (constant, @base, exponentInU, u, linear, slope, power)
                || !TreeAnalyzer.TryGetPolynomial(exponentInU, u, out var monomials)
                || monomials.Keys.Any(k => k.Sign < 0 || k.CompareTo(EInteger.FromInt32(8)) > 0)
                || !monomials.Keys.Any(k => k.Sign > 0))
                return null;
            var powerInU = -power - EInteger.FromInt32(2);
            if (!powerInU.CanFitInInt32() || powerInU.Abs().CompareTo(EInteger.FromInt32(32)) > 0)
                return null;
            var exponential = MathS.Pow(@base, exponentInU);
            var inU = powerInU.IsZero ? exponential : MathS.Pow(u, Number.Integer.Create(powerInU)) * exponential;
            if (Integration.ComputeAsAQuestionOfItsOwn(inU, u, integrateByParts) is not { } answerInU
                || answerInU.Nodes.Any(node => node == MathS.NaN))
                return null;
            return (-constant / slope * answerInU.Substitute(u, 1 / linear)).InnerSimplified;
        }

        /// <summary>
        /// <paramref name="expr"/> read as a constant times <c>F^E</c> times a whole power of a
        /// linear <c>L</c>, with every <c>x</c> in <c>E</c> inside a reciprocal power of <c>L</c>:
        /// the constant, <c>F</c>, <c>E</c> written in <c>u = 1/L</c>, <c>u</c>, <c>L</c>, its slope
        /// and the power of <c>L</c>. The exponent is rewritten into <c>u</c> a node at a time --
        /// <c>b/L^k</c> is <c>b u^k</c> -- rather than by substituting <c>x = (1/u - c)/d</c> and
        /// asking the simplifier to see that <c>1/(1/u)^2</c> is <c>u^2</c>.
        /// </summary>
        private static (Entity Constant, Entity Base, Entity ExponentInU, Variable U, Entity Linear, Entity Slope, EInteger Power)?
            ReadAnExponentialInTheReciprocalOfALinear(Entity expr, Entity.Variable x)
        {
            Powf? exponential = null;
            Entity? linear = null;
            var power = EInteger.Zero;
            Entity constant = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (!underneath && exponential is null && factor is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x))
                {
                    exponential = (Powf)factor;
                    continue;
                }
                // The linear, or a whole power of it, above or below the bar.
                var (candidate, k) = factor is Powf(var b, Number.Integer n) && n.EInteger.CanFitInInt32() ? (b, n.EInteger) : (factor, EInteger.One);
                if (linear is not null && linear != candidate
                    || !TreeAnalyzer.TryGetPolyLinear(candidate, x, out var slopeOfIt, out _) || slopeOfIt is null || TreeAnalyzer.IsZero(slopeOfIt))
                    return null;
                linear = candidate;
                power = underneath ? power - k : power + k;
            }
            if (exponential is null)
                return null;
            linear ??= ALinearBelowABar(exponential.Exponent, x);
            if (linear is null || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out _) || slope is null || TreeAnalyzer.IsZero(slope))
                return null;
            var u = Variable.CreateUnique(expr, "u");
            var exponentInU = exponential.Exponent.Replace(node => node switch
            {
                Divf(var numerator, Powf(var below, Number.Integer k)) when below == linear => numerator * MathS.Pow(u, k),
                Divf(var numerator, var below) when below == linear => numerator * u,
                Powf(var below, Number.Integer { EInteger.Sign: < 0 } k) when below == linear => MathS.Pow(u, -k),
                _ => node
            });
            if (exponentInU.ContainsNode(x))
                return null;
            return (constant, exponential.Base, exponentInU, u, linear, slope, power);
        }

        /// <summary>
        /// Sines, cosines and the rest of a function of the reciprocal of a linear, beside a whole
        /// power of the linear: <c>L^m f(a + b/L^k)</c> with <c>L = c + d x</c>. Under <c>u = 1/L</c>,
        /// <c>dx = -du/(d u^2)</c>, and it is <c>-(1/d) u^(-m - 2) f(a + b u^k)</c>: a polynomial times
        /// the function for <c>m &lt;= -2</c>, which by parts is elementary for a sine or cosine of a
        /// linear. <c>sin(a + b/x)/x^3</c> is <c>-u sin(a + b u)</c>. Rubi's 4.1.12 and 4.2.12,
        /// <c>(e x)^m (a + b sin(c + d x^n))^p</c> for a negative <c>n</c>; the exponential's case is
        /// <see cref="SolveAGaussianInAReciprocal"/>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// Every factor with the variable in it is read: a trigonometric function of something of
        /// <c>L</c> with <c>1/L</c> in it, or a whole power of <c>L</c>; anything else and the rule
        /// declines, rather than write a polynomial of <c>x</c> in <c>u</c>. Only for <c>m &lt;= -3</c>:
        /// the other powers are answered as written, and asked here would come back respelled.
        /// </remarks>
        internal static Entity? SolveAFunctionOfTheReciprocalOfALinear(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            static bool IsATrigonometric(Entity node) => node is Sinf or Cosf or Tanf or Cotanf or Secantf or Cosecantf;
            // The linear a trigonometric argument divides by.
            Entity? linear = null;
            foreach (var node in expr.Nodes)
                if (IsATrigonometric(node) && node.DirectChildren.First() is var argument && argument.ContainsNode(x)
                    && ALinearBelowABar(argument, x) is { } below)
                {
                    linear = below;
                    break;
                }
            if (linear is null || !TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                return null;
            var u = Variable.CreateUnique(expr, "u_rec");
            Entity constant = Number.Integer.One;
            var power = EInteger.Zero;
            Entity inU = Number.Integer.One;
            var sawAFunction = false;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                var (candidate, k) = factor is Powf(var raised, Number.Integer n) ? (raised, n.EInteger) : (factor, EInteger.One);
                if (candidate == linear)
                {
                    power = underneath ? power.Subtract(k) : power.Add(k);
                    continue;
                }
                // A function of the reciprocal of the linear, read in u; a whole power of one as well.
                // Bottom-up, so that each quotient by the linear is met whole; the linear anywhere
                // else is left, and declines.
                if (!factor.Nodes.Any(IsATrigonometric))
                    return null;
                var rewritten = factor.Replace(node => node switch
                {
                    Divf(var numerator, Powf(var below, Number.Integer k)) when below == linear => numerator * MathS.Pow(u, k),
                    Divf(var numerator, var below) when below == linear => numerator * u,
                    Powf(var below, Number.Integer { EInteger.Sign: < 0 } k) when below == linear => MathS.Pow(u, -k),
                    _ => node
                }).InnerSimplified;
                if (rewritten.ContainsNode(x))
                    return null;
                sawAFunction = true;
                inU = underneath ? inU / rewritten : inU * rewritten;
            }
            // L^m dx = -u^(-m - 2) du/d. Only where that is a positive power of u: at m = -2 the
            // integrand is the derivative of its argument times a function of it, and above, a power
            // of u below the bar is the sine and cosine integrals', both answered as written.
            var inUPower = power.Negate().Subtract(EInteger.FromInt32(2));
            if (!sawAFunction || inUPower.Sign <= 0 || inUPower.CompareTo(EInteger.FromInt32(24)) > 0)
                return null;
            var question = -constant / slope * MathS.Pow(u, Number.Integer.Create(inUPower)) * inU;
            if (Integration.ComputeAsAQuestionOfItsOwn(question, u, integrateByParts) is not { } answer
                || answer.Nodes.Any(node => node is Integralf || node == MathS.NaN))
                return null;
            return answer.Substitute(u, 1 / linear);
        }

        /// <summary>
        /// The linear a node of <paramref name="exponent"/> divides by, <c>b/L^k</c> or <c>L^(-k)</c>,
        /// or <see langword="null"/>.
        /// </summary>
        private static Entity? ALinearBelowABar(Entity exponent, Entity.Variable x)
        {
            foreach (var node in exponent.Nodes)
            {
                var below = node switch
                {
                    Divf(_, Powf(var b, Number.Integer)) => b,
                    Divf(_, var b) => b,
                    Powf(var b, Number.Integer { EInteger.Sign: < 0 }) => b,
                    _ => null
                };
                if (below is { } && below.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(below, x, out var slope, out _) && slope is { } && !TreeAnalyzer.IsZero(slope))
                    return below;
            }
            return null;
        }

        /// <summary>
        /// A power of an exponential of <c>x</c> with a positive constant base, written as the
        /// exponential of the product: <c>(e^x)^(1/3)</c> is <c>e^(x/3)</c> and <c>(3^(3x))^(1/4)</c>
        /// is <c>3^(3x/4)</c>, exactly, since the base is positive; and it is only in that
        /// spelling that the exponential rules read them. Timofeev's
        /// <c>(cos(x/2) + sin(x/2))/(e^x)^(1/3)</c> and <c>cos(3x/2)/(3^(3x))^(1/4)</c>.
        /// </summary>
        internal static Entity? SolveByFlatteningAPowerOfAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var flattened = expr.Replace(node =>
                node is Powf(Powf(var @base, var inner), var outer)
                && !@base.ContainsNode(x) && inner.ContainsNode(x) && !outer.ContainsNode(x)
                && (@base == MathS.e || @base.Evaled is Number.Real { IsPositive: true })
                && outer.Evaled is Number.Real
                    ? MathS.Pow(@base, (outer * inner).InnerSimplified)
                    : node);
            // The same question in another spelling, asked as one of its own, so that the
            // closed rules that answer only at the top -- the exponential times a
            // trigonometric -- are consulted for it.
            return flattened == expr ? null : Integration.ComputeAsAQuestionOfItsOwn(flattened, x, integrateByParts);
        }

        /// <summary>
        /// A power of an exponential the flattening above leaves -- a symbol for the base or the
        /// power, <c>(F^(g (e + f x)))^n</c> -- beside a polynomial below the bar. Its logarithmic
        /// derivative is the constant <c>n g f ln F</c>, so it is <c>K e^(n g f ln(F) x)</c> with
        /// <c>K</c> constant wherever it is differentiable; with a symbol for <c>K</c> the integrand
        /// is one the exponential integral's rules read, and the answer is written back with
        /// <c>K = (F^(g (e + f x)))^n e^(-n g f ln(F) x)</c>. A whole power is the exponential of
        /// the product exactly, whatever the base, and is written so. Rubi's 2.2,
        /// <c>(a + b (F^(g (e + f x)))^n)^p/(c + d x)^m</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// <c>(F^u)^n</c> is <c>F^(n u)</c> only where <c>F^u</c> is on the principal branch, which
        /// it is for a positive <c>F</c> and need not be for a symbol; <c>K</c> carries the
        /// difference, and the answer holds for every <c>F</c>. Only beside a polynomial below the
        /// bar, where nothing else reads the power: above it, the rules for a polynomial times an
        /// exponential answer it as written.
        /// </remarks>
        internal static Entity? SolveByWritingAPowerOfAnExponentialAsAMultipleOfOne(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            bool IsAnExponential(Entity node) => node is Powf(var b, var p) && !b.ContainsNode(x) && p.ContainsNode(x);
            var powers = expr.Nodes.Where(node => node is Powf(Powf(var @base, var inner), var outer)
                    && !@base.ContainsNode(x) && inner.ContainsNode(x) && !outer.ContainsNode(x)
                    && !((@base == MathS.e || @base.Evaled is Number.Real { IsPositive: true }) && outer.Evaled is Number.Real))
                .Distinct().ToList();
            if (powers.Count == 0)
                return null;
            // A polynomial below the bar, or under a negative whole power.
            if (!FactorsOfTheIntegrand(expr).Any(pair =>
                    pair.Factor.ContainsNode(x) && !pair.Factor.Nodes.Any(IsAnExponential)
                    && (pair.Underneath || pair.Factor is Powf(_, Number.Integer { IsNegative: true }))
                    && TreeAnalyzer.TryGetPolynomial(pair.Factor is Powf(var raised, Number.Integer) ? raised : pair.Factor, x, out var read)
                    && read.Keys.All(degree => degree.Sign >= 0)))
                return null;
            var back = new List<(Entity.Variable Constant, Entity Value)>();
            var rewritten = expr;
            foreach (var node in powers)
            {
                if (node is not Powf(Powf(var @base, var inner), var outer)
                    || !TreeAnalyzer.TryGetPolyLinear(inner, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                    return null;
                Entity replacement;
                if (outer.Evaled is Number.Integer)
                    replacement = MathS.Pow(@base, (outer * inner).InnerSimplified);
                else
                {
                    var constant = Variable.CreateUnique(rewritten, "k_pow");
                    var rate = (outer * slope * (@base == MathS.e ? Number.Integer.One : MathS.Ln(@base))).InnerSimplified;
                    replacement = constant * MathS.Pow(MathS.e, rate * x);
                    back.Add((constant, node * MathS.Pow(MathS.e, -rate * x)));
                }
                rewritten = rewritten.Replace(inside => inside == node ? replacement : inside);
            }
            if (Integration.ComputeAsAQuestionOfItsOwn(rewritten, x, integrateByParts) is not { } answer || answer.Nodes.Any(inside => inside is Integralf))
                return null;
            foreach (var (constant, value) in back)
                answer = answer.Substitute(constant, value);
            return answer;
        }

        /// <summary>
        /// An exponential of a multiple of a logarithm is a power of the argument:
        /// <c>e^(k ln(q))</c> is <c>q^k</c>, since <c>e^(k ln q)</c> is the definition of the
        /// principal power for every complex <c>q</c> other than zero. That is the spelling the
        /// parser gives every inverse hyperbolic function -- <c>acoth(a x)</c> is
        /// <c>1/2 ln((a x + 1)/(a x - 1))</c> -- so <c>e^acoth(a x) x^3</c> arrives as
        /// <c>e^(1/2 ln((a x + 1)/(a x - 1))) x^3</c>, which no exponential rule reads, and is
        /// <c>x^3 sqrt((a x + 1)/(a x - 1))</c>, a root of a quotient of linears, which the
        /// radical substitution answers. Rubi's 7.4.2. The simplifier folds the same shape
        /// since #1430; the integrand is not simplified before the rules see it, so the fold
        /// is a rule here, asked as a question of its own so the closed rules meet it at the top.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByFoldingAnExponentialOfALogarithm(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var folded = expr.Replace(node =>
            {
                if (node is not Powf(var @base, var exponent) || @base != MathS.e || !exponent.ContainsNode(x))
                    return node;
                // The exponent read structurally, since `e^(u + v)` is `e^u e^v`, `e^(k u)` is
                // `(e^u)^k` and `e^(ln q)` is `q`: `a + b ln(c x^n)` -- a hyperbolic function of
                // a logarithm -- folds to `e^a (c x^n)^b`, and its negation, which the same
                // function writes below the bar, to the reciprocal of that.
                // One logarithm in the exponent: `a + b ln(c x^n)` is a hyperbolic function of
                // a logarithm, and `n acoth(a x)` written as a difference of two -- which folds
                // to a power of a quotient of quotients -- was a search of fifty seconds where
                // the unfolded form is declined in three.
                if (exponent.Nodes.Count(inner => inner is Logf(var logBase, _) && logBase == MathS.e) != 1)
                    return node;
                var folded = FoldTheExponent(exponent, x);
                return folded ?? node;
            });
            return folded == expr ? null : Integration.ComputeAsAQuestionOfItsOwn(folded, x, integrateByParts);
        }

        /// <summary>
        /// <c>e^(exponent)</c> written without the exponential wherever the exponent is built
        /// from logarithms and constants: <c>e^(u + v)</c> is <c>e^u e^v</c>, <c>e^(k u)</c> is
        /// <c>(e^u)^k</c> for an <paramref name="x"/>-free <c>k</c>, and <c>e^(ln q)</c> is
        /// <c>q</c>. <see langword="null"/> where a part mentioning <paramref name="x"/> is
        /// none of those, and where no logarithm was folded at all.
        /// </summary>
        private static Entity? FoldTheExponent(Entity exponent, Entity.Variable x)
        {
            var folded = Fold(exponent, out var found);
            return found ? folded : null;

            Entity? Fold(Entity exponent, out bool found)
            {
                found = false;
                switch (exponent)
                {
                    case Logf(var logBase, var inner) when logBase == MathS.e:
                        found = true;
                        return inner;
                    case Sumf(var left, var right):
                    {
                        var foldedLeft = Fold(left, out var leftFound);
                        var foldedRight = Fold(right, out var rightFound);
                        found = leftFound || rightFound;
                        return foldedLeft is null || foldedRight is null ? null : foldedLeft * foldedRight;
                    }
                    case Minusf(var left, var right):
                    {
                        var foldedLeft = Fold(left, out var leftFound);
                        var foldedRight = Fold(right, out var rightFound);
                        found = leftFound || rightFound;
                        return foldedLeft is null || foldedRight is null ? null : foldedLeft / foldedRight;
                    }
                    case Mulf(var left, var right) when !left.ContainsNode(x):
                        return Raised(Fold(right, out found), left);
                    case Mulf(var left, var right) when !right.ContainsNode(x):
                        return Raised(Fold(left, out found), right);
                    case Divf(var above, var below) when !below.ContainsNode(x):
                        return Raised(Fold(above, out found), (Number.Integer.One / below).InnerSimplified);
                    default:
                        // A part free of the variable stays an exponential of itself.
                        return exponent.ContainsNode(x) ? null : MathS.Pow(MathS.e, exponent);
                }
            }

            // The power of a power as one power: `n (1/2 ln q)` is `q^(n/2)` and not
            // `(sqrt(q))^n`, whose nesting the rules below read as a different question --
            // `e^(n acoth(a x))/(c - a^2 c x^2)^4` was a search of fifty seconds written that
            // way and is declined in three written flat.
            static Entity? Raised(Entity? folded, Entity power)
                => folded is null ? null
                    : folded is Powf(var @base, var inner) ? MathS.Pow(@base, (inner * power).InnerSimplified)
                    : MathS.Pow(folded, power);
        }

        /// <summary>
        /// A logarithm whose argument is a quotient in <paramref name="x"/> that cancels with
        /// the functions of <paramref name="x"/> in it taken for indeterminates, with the
        /// argument cancelled. That is the spelling the parser gives an inverse hyperbolic
        /// function of a hyperbolic one -- <c>atanh(tanh(u))</c> is
        /// <c>1/2 ln((1 + T)/(1 - T))</c> with <c>T = (E - 1)/(E + 1)</c> and <c>E = e^(2u)</c>,
        /// which as one quotient is <c>2E(E + 1)/(2(E + 1))</c>, and is <c>1/2 ln(E)</c>: an
        /// atom whose derivative is <c>u'</c>, which every rule downstream reads, where the
        /// nested quotient was read by none. <c>acoth(tanh(u))</c> is <c>1/2 ln(-E)</c> the
        /// same way. Kept as the logarithm rather than unwrapped to <c>u</c>, since
        /// <c>ln(e^(2u))</c> is <c>2u</c> only on a strip, and the logarithm is exact
        /// everywhere -- the answer carries it as Rubi's carries <c>atanh(tanh(u))</c>.
        /// Rubi's 7.3.7 and 7.4.1. Asked as a question of its own.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByCancellingInsideALogarithm(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var cancelled = expr.Replace(node =>
            {
                if (node is not Logf(var @base, var argument) || !argument.ContainsNode(x) || !argument.Nodes.Any(inner => inner is Divf))
                    return node;
                var (above, below) = Functions.SingleQuotient.Of(argument);
                if (below == Number.Integer.One)
                    return node;
                var (top, bottom) = CancelledWithFunctionsAsIndeterminates(above, below, x, argument);
                if (top == above && bottom == below)
                    return node;
                // Simplified rather than normalised: the cancellation leaves the numeric
                // content where it was, and `2E/2` is not the atom `E` until it is folded.
                var written = (bottom == Number.Integer.One ? top : top / bottom).Simplify();
                return written == argument ? node : new Logf(@base, written);
            });
            return cancelled == expr ? null : Integration.ComputeAsAQuestionOfItsOwn(cancelled, x, integrateByParts);
        }

        /// <summary>
        /// A logarithm of <paramref name="x"/> whose derivative in <paramref name="x"/> is a
        /// constant <c>k</c> is <c>k x + c</c> for a constant <c>c</c>, and is written so, with
        /// <c>c</c> a name standing for <c>ln(...) - k x</c>, which the answer substitutes back.
        /// <c>ln(e^(2(a + b x)))</c> -- which is what <c>atanh(tanh(a + b x))</c> is once its
        /// quotient is cancelled -- has derivative <c>2b</c>, and is <c>2b x + c</c>: with that
        /// name, <c>x^m atanh(tanh(a + b x))^3</c> is a polynomial times a power of a linear and
        /// <c>1/(x atanh(tanh(a + b x)))</c> a rational function, which the rules answer at once
        /// where the logarithm was an atom no rule read past the first power. The name is
        /// exact: <c>c</c> is <c>ln(...) - k x</c> by definition, and a constant in <c>x</c>
        /// because the derivative is. The logarithm is not unwrapped to its argument's
        /// exponent, which it equals only on a strip; Rubi's answers carry
        /// <c>b x - atanh(tanh(a + b x))</c> in the same way. Rubi's 7.3.7 and 7.4.1. Asked as
        /// a question of its own. https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByNamingALogarithmLinearInTheVariable(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            Logf? linear = null;
            Entity? slope = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not Logf(var logBase, var argument) log || logBase.ContainsNode(x) || !argument.ContainsNode(x))
                    continue;
                // The derivative of ln(prod f_i^(n_i)) is the sum of n_i f_i'/f_i, which for a
                // factor e^v is v': read off the factors rather than differentiated and
                // simplified, since the differentiation leaves E 2b / E as it is.
                var (above, below) = Functions.SingleQuotient.Of(argument);
                Entity sum = Number.Integer.Zero;
                var read = true;
                foreach (var (factor, sign) in Mulf.LinearChildren(above).Select(f => (f, 1)).Concat(Mulf.LinearChildren(below).Select(f => (f, -1))))
                {
                    if (!factor.ContainsNode(x))
                        continue;
                    if (factor is not Powf(var @base, var exponent) || @base.ContainsNode(x))
                    {
                        read = false;
                        break;
                    }
                    var rate = exponent.Differentiate(x);
                    if (rate.ContainsNode(x) || rate is Derivativef)
                    {
                        read = false;
                        break;
                    }
                    sum += sign * rate * (@base == MathS.e ? Number.Integer.One : MathS.Ln(@base));
                }
                if (!read)
                    continue;
                var derivative = sum.InnerSimplified;
                if (derivative == Number.Integer.Zero || derivative.ContainsNode(x))
                    continue;
                linear = log;
                slope = logBase == MathS.e ? derivative : derivative / MathS.Ln(logBase);
                break;
            }
            if (linear is null || slope is null)
                return null;
            var constant = Variable.CreateUnique(expr, "c");
            var named = expr.Substitute(linear, slope * x + constant);
            if (named == expr)
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(named, x, integrateByParts) is not { } answer)
                return null;
            var intercept = linear - slope * x;
            var generic = answer.Substitute(constant, intercept);
            // The answer is the generic case's, and where `c` is zero it can have no value:
            // `1/(x ln(e^x))` is `1/(x (x + c))`, whose answer divides by `c`. That is the case
            // wherever `ln(e^v)` is `v` -- on the strip `|Im v| < pi`, so on the whole real line
            // for a real `v` -- and for `ln(e^x) - x` it is everywhere the integrand is real,
            // where `ln(e^(2(a + b x))) - 2 b x` is `2a`. So where the answer has no value at
            // `c = 0` and `c` is zero at real points, `c = 0` is asked as well, and its answer is
            // the arm for it. https://github.com/asc-community/AngouriMath/issues/1666
            if (!answer.Substitute(constant, Number.Integer.Zero).InnerSimplified.Nodes.Any(node => node is Number.Complex { IsNaN: true })
                || Functions.PartialFractions.InLowestTermsOverTheSymbols(intercept) != Number.Integer.Zero)
                return generic;
            if (Integration.ComputeAsAQuestionOfItsOwn(named.Substitute(constant, Number.Integer.Zero), x, integrateByParts) is not { } whereZero)
                return null;
            return MathS.Piecewise(new[] { new Providedf(whereZero, intercept.EqualTo(Number.Integer.Zero)) }, generic);
        }

        /// <summary>
        /// The sign of a real-valued function of <paramref name="x"/> among the factors of the
        /// integrand is constant on every interval between its zeros, and goes in front of the
        /// antiderivative of the rest: <c>sgn(x) f(x)</c> is <c>sgn(x) F(x)</c> on each half-line,
        /// which is the generic case every rule answers in. The extension by parity writes the
        /// antiderivative of <c>x^2/sqrt(1/(a x)^2 - 1)</c> with a <c>sgn(x)</c> in front, and a
        /// step of parts against it -- <c>x^2 asech(a x)/sqrt(1/(a x)^2 - 1)</c>, the second step
        /// on <c>x^3 asech(a x)^2</c> -- leaves that sign beside the remainder, where no rule
        /// read past it. Only a sign whose argument is shown real: for a complex <c>g</c>,
        /// <c>sgn(g)</c> is <c>g/|g|</c> and is not constant anywhere. Asked as the same question.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByTakingASignOut(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator) && expr is Mulf)
                (numerator, denominator) = (expr, Number.Integer.One);
            else if (numerator is null)
                return null;
            var signs = new Dictionary<Entity, int>();
            Entity Without(Entity side)
            {
                Entity? rest = null;
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var (@base, times) = factor is Powf(var inner, Number.Integer whole) ? (inner, whole.EInteger) : (factor, EInteger.One);
                    if (@base is Signumf(var signed) && signed.ContainsNode(x) && TreeAnalyzer.IsRealValued(signed, x) && times.CanFitInInt32())
                    {
                        signs[signed] = (signs.TryGetValue(signed, out var seen) ? seen : 0) + times.ToInt32Unchecked();
                        continue;
                    }
                    rest = rest is null ? factor : rest * factor;
                }
                return rest ?? Number.Integer.One;
            }
            var above = Without(numerator);
            var below = Without(denominator);
            if (signs.Count == 0)
                return null;
            var rest = below == Number.Integer.One ? above : above / below;
            if (!rest.ContainsNode(x))
                return null;
            var answer = Integration.ComputeAsTheSameQuestion(rest, x, integrateByParts);
            if (answer is null)
                return null;
            foreach (var pair in signs)
                if (pair.Value % 2 != 0)
                    answer = MathS.Signum(pair.Key) * answer;
            return answer;
        }

        /// <summary>
        /// <c>x^(n - 1) g(x^n)</c> with a symbolic <c>n</c>, which is <c>g(u)/n</c> under
        /// <c>u = x^n</c>: the power in front is the derivative of the power inside up to the
        /// constant <c>n</c>, and the rest mentions <c>x</c> only as <c>x^n</c>. Rubi's 6.5.2 and
        /// 6.6.2 -- <c>(e x)^(n - 1) (a + b sech(c + d x^n))^p</c> -- write the power in front as
        /// <c>(e x)^(n - 1)</c>, which is <c>e^(n - 1) x^(n - 1)</c> for a positive <c>e</c>, and
        /// the answer says so. A concrete <c>n</c> is the general substitution's; a symbolic
        /// one was nobody's, and <c>x^(n - 1) e^(x^n)</c> was declined.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// <c>x^(k n - 1)</c> with <c>k</c> half an odd number is the same substitution by half
        /// the power: under <c>u = x^(n/2)</c>, <c>x^(k n - 1) dx</c> is <c>(2/n) u^(2k - 1) du</c>
        /// and <c>g(x^n)</c> is <c>g(u^2)</c>. Beside an exponential of <c>x^n</c> that is a moment
        /// of the Gaussian: Rubi's 2.3, <c>f^(a + b x^n) x^(-1 + 5n/2)</c>, and 6.1.3's
        /// <c>x^(-1 + n/2) sinh(a + b x^n)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </remarks>
        internal static Entity? SolveByAPowerOfTheVariableTimesAFunctionOfItsPower(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            Entity? inFront = null;
            Entity? scale = null;
            Entity? rest = null;
            Entity constant = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                // The power in front: x^m, or (e x)^m with e free of x, to a symbolic m.
                if (inFront is null && !underneath && factor is Powf(var @base, var exponent) && !exponent.ContainsNode(x)
                    && exponent.Evaled is not Number && exponent.Vars.Any()
                    && (@base == x || @base is Mulf(var l, var r) && (l == x && !r.ContainsNode(x) || r == x && !l.ContainsNode(x))))
                {
                    inFront = exponent;
                    scale = @base == x ? null : @base is Mulf(var l2, var r2) ? (l2 == x ? r2 : l2) : null;
                    continue;
                }
                var piece = underneath ? Number.Integer.One / factor : factor;
                rest = rest is null ? piece : rest * piece;
            }
            if (inFront is null || rest is null)
                return null;
            // The rest mentions x only as x^n, one n throughout.
            Entity? n = null;
            foreach (var node in rest.Nodes)
                if (node is Powf(var b, var e) && b == x && !e.ContainsNode(x))
                {
                    if (n is null)
                        n = e;
                    else if (n != e)
                        return null;
                }
            if (n is null || n.Evaled is Number)
                return null;
            // m + 1 = k n for a whole k >= 1: x^(k n - 1) g(x^n) is u^(k - 1) g(u)/n.
            // Bare: the simplification attaches `provided not n = 0` to the quotient it
            // cancelled, and the generic case is what every rule answers in.
            var timesN = Functions.PartialFractions.Bare(((inFront + Number.Integer.One) / n).InnerSimplified);
            if (!IsAWholeOrHalfOddMultiple(timesN))
                timesN = Functions.PartialFractions.Bare(((inFront + Number.Integer.One) / n).Simplify());
            if (!IsAWholeOrHalfOddMultiple(timesN))
                return null;
            // A half-odd k: the same by half the power, u = x^(n/2), where g(x^n) is g(u^2) and
            // x^(k n - 1) dx is (2/n) u^(2k - 1) du.
            var halved = timesN is not Number.Integer;
            var u = Variable.CreateUnique(expr, "u_pow");
            var inU = rest.Replace(node => node is Powf(var b, var e) && b == x && e == n ? (halved ? MathS.Sqr(u) : u) : node);
            if (inU.ContainsNode(x))
                return null;
            var powerOfU = halved ? (2 * timesN - 1).InnerSimplified : (timesN - Number.Integer.One).InnerSimplified;
            if (powerOfU != Number.Integer.Zero)
                inU = MathS.Pow(u, powerOfU) * inU;
            if (Integration.ComputeAsAQuestionOfItsOwn(inU, u, integrateByParts) is not { } inner)
                return null;
            Entity answer = halved
                ? constant * 2 * inner.Substitute(u, MathS.Pow(x, n / 2)) / n
                : constant * inner.Substitute(u, MathS.Pow(x, n)) / n;
            // (e x)^(n - 1) is e^(n - 1) x^(n - 1) for a positive e, which the answer states.
            if (scale is { })
            {
                answer = MathS.Pow(scale, inFront) * answer;
                if (scale.Evaled is not Number.Real { IsPositive: true })
                    answer = answer.Provided(new Greaterf(scale, Number.Integer.Zero));
            }
            return answer;
        }

        /// <summary>
        /// A whole <c>k >= 1</c>, or half an odd number of either sign: the multiples of the
        /// power inside that <see cref="SolveByAPowerOfTheVariableTimesAFunctionOfItsPower"/> takes.
        /// A whole one below 1 leaves <c>u^(k - 1) g(u)</c> with a negative power in front of an
        /// exponential of <c>u</c>, the exponential integral where it is <c>1/u</c>.
        /// </summary>
        private static bool IsAWholeOrHalfOddMultiple(Entity timesN)
            => timesN is Number.Integer { EInteger.Sign: > 0 }
               || timesN is Number.Rational half and not Number.Integer && half.ERational.Denominator.Equals(EInteger.FromInt32(2));

        /// <summary>
        /// Whether <c>b^2 - 4ac</c> is zero, which makes <c>a x^2 + b x + c</c> a perfect square.
        /// Symbolically as well as numerically: for <c>a^2 + 2 a b x + b^2 x^2</c> it is
        /// <c>4 a^2 b^2 - 4 a^2 b^2</c>, which <see cref="Entity.InnerSimplified"/> does not
        /// collect, so a guard that asks only what it evaluates to reads the square as an
        /// ordinary quadratic. Asked of every quadratic under a root the table meets, so the
        /// simplification is only for a discriminant that is zero with its symbols pinned.
        /// </summary>
        internal static bool IsAPerfectSquareDiscriminant(Entity a, Entity b, Entity c)
            => VanishesIdentically(b * b - Number.Integer.Create(4) * a * c);

        /// <summary>
        /// A square root of a perfect square in <paramref name="x"/> is the modulus:
        /// <c>sqrt(x^2)</c> is <c>|x|</c>, which for a real <c>x</c> is <c>sgn(x) x</c>, and
        /// <c>sqrt(a (x + h)^2)</c> is <c>sqrt(a) sgn(x + h) (x + h)</c> for a positive number
        /// <c>a</c>, and a square in a power of <c>x</c> the same way:
        /// <c>sqrt(a^2 + 2 a b x^2 + b^2 x^4)</c> is <c>sqrt(b^2) sgn(x^2 + a/b) (x^2 + a/b)</c>,
        /// the square Rubi's 1.2.2 and 1.2.3 write. Every rule that reads a root of a quadratic
        /// assumes it is not one:
        /// <c>1/sqrt(1 + csch(x)^2)</c> under <c>u = tanh(x)</c> is <c>sqrt(u^2)/(u^2 - 1)</c>,
        /// and the table rule for <c>sqrt(a w^2 + b w + c)</c> beside a linear, reached after the
        /// partial fractions and a reciprocal, answered it with a logarithm of zero.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// At every depth, unlike <see cref="SolveByTakingASquareFactorOutOfARoot"/>, since the
        /// misreading is at depth; and the square root only, not <c>(x^2 + 2x + 1)^(5/2)</c>,
        /// which that rule writes as <c>sgn(x + 1) (x + 1)^5</c> at the top. Below a
        /// substitution the variable is one whose sign the substitution knows, and a sign
        /// written for it is a factor the rest of the search has to carry:
        /// <c>tanh(x)/(a + b tanh(x)^2)^(5/2)</c> under <c>u = e^(2x)</c> holds
        /// <c>(1 + 2u + u^2)^(5/2)</c>, and with that rewritten the search ran past its budget
        /// where it had answered in twenty seconds. The one half-odd power taken beyond the
        /// square root is of the bare square, <c>(x^2)^(3/2)</c>, which is <c>sgn(x) x^3</c>:
        /// it is what a root of <c>(b + a u^2)/u^2</c> -- <c>a + b coth(x)^2</c> under
        /// <c>u = tanh(x)</c> -- leaves once the quotient is written apart, and nothing else
        /// reads it.
        /// </remarks>
        internal static Entity? SolveByTakingARootOfAPerfectSquare(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Asked of every integrand at every depth, so the radicand is read as a polynomial
            // only where it is small enough to be a written square: x^2, a x^2 + b x + c, or
            // the same quadratic in a power of x, a x^(2k) + b x^k + c.
            // At the top, any half-odd power of a perfect square is the power of the modulus;
            // below it the square root only, since a sign written for a substitution's variable
            // is a factor the rest of the search carries -- `(1 + 2u + u^2)^(5/2)` under
            // `u = e^(2x)` cost twenty seconds that way. A bare `x^2` is the exception at any
            // depth, nothing else reading `(x^2)^(3/2)`.
            var atTheTop = Integration.AnsweringTheQuestionAsked;
            // A whole power too, at the top, of a square with a symbol in it, and in an integrand
            // with x below the bar: `(a^2 + 2 a b x^2 + b^2 x^4)^(-2)` is `(b^2)^(-2) (x^2 + a/b)^(-4)`,
            // exact and with no sign, and the rational integrator reads a power of `x^2 + a/b`
            // where it declined the quartic. Not in a polynomial, which is answered as one already;
            // and read off the whole integrand, since `1/P^2` holds `P^2` with a positive exponent.
            // And only of a square written out as a sum: `((a + b - b u^2)^2)^(-1)`, what the
            // hyperbolic tangent makes of `coth(x)^2/(a + b sech(x)^2)^2`, is a square written as
            // one, and taken apart into `(u^2 - a/b - 1)^(-2)` it went from under a second to past
            // a minute.
            bool? xBelowTheBar = null;
            bool XIsBelowTheBar()
                => xBelowTheBar ??= Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr)).Denominator.ContainsNode(x);
            bool MayBeARootOfASquare(Entity node, Entity.Variable x)
                => node is Powf(var radicand, Number.Rational r)
                    && (r.ERational.Denominator.Equals(EInteger.FromInt32(2))
                            && (atTheTop || r.ERational.Equals(ERational.Create(1, 2))
                                || radicand is Powf(var @base, var degree) && @base == x && degree == Number.Integer.Create(2))
                            && radicand.Complexity <= (atTheTop ? 40 : 12)
                        || atTheTop && r is Number.Integer && r != Number.Integer.Zero && r != Number.Integer.One
                            && radicand is Sumf or Minusf
                            && radicand.Complexity <= 40 && radicand.Vars.Any(symbol => symbol != x) && XIsBelowTheBar())
                    && radicand.ContainsNode(x) && radicand.Nodes.Count(inner => inner == x) <= 2;
            if (!expr.Nodes.Any(node => MayBeARootOfASquare(node, x)))
                return null;
            var changed = false;
            Entity assumed = Entity.Boolean.True;
            Entity signs = Number.Integer.One;
            // A sign goes in front of the integral only from a factor of the integrand. Inside a
            // sum it is a factor of nothing: `1/(1 + (x^2)^(3/2))` is `1/(1 + x^3)` for a positive
            // x and `1/(1 - x^3)` for a negative one, and with the sign taken out in front the
            // answer was the first's for both. There the root is written with a sign of its own,
            // and the integrand is integrated with it 1 and with it -1, each on its side of the
            // linear's zero. One such linear only.
            var factors = FactorsOfTheIntegrand(expr).Select(pair => pair.Factor).ToList();
            var sign = Variable.CreateUnique(expr, "s_sgn");
            Entity? signedLinear = null;
            var signsOfMoreThanOneLinear = false;
            var written = expr.Replace(node =>
            {
                if (!MayBeARootOfASquare(node, x))
                    return node;
                var (radicand, exponent) = (Powf)node;
                var r = (Number.Rational)exponent;
                // A quadratic in a fractional power of x, `a^2 + 2 a b x^(-1/5) + b^2 x^(-2/5)`, is
                // read in `w = x^k`, exact for every x since each power of x is a whole power of w;
                // and real only for a positive x, which the answer then says.
                Entity wBase = x;
                if (!TreeAnalyzer.TryGetPolynomial(radicand, x, out var monomials) || monomials.Count == 0)
                {
                    if (!atTheTop || InAFractionalPowerOfX(radicand, x) is not var (inW, k))
                        return node;
                    monomials = inW;
                    wBase = MathS.Pow(x, k);
                    var positive = new Greaterf(x, Number.Integer.Zero);
                    assumed = assumed == Entity.Boolean.True ? positive : assumed & positive;
                }
                // A quadratic in w = x^k: a w^2 + b w + c, the square being of w + h. Beyond
                // k = 1 only with the constant term written, since `a x^(2k)` alone is a power
                // of a monomial, which another rule distributes.
                var degree = monomials.Keys.Max()!;
                if (degree.IsZero || !degree.IsEven || monomials.Keys.Any(k => k.Sign < 0))
                    return node;
                var half = degree / EInteger.FromInt32(2);
                if (monomials.Keys.Any(k => !k.IsZero && !k.Equals(half) && !k.Equals(degree))
                    || !half.Equals(EInteger.One) && !monomials.ContainsKey(EInteger.Zero))
                    return node;
                // A whole power of a square in x itself is a rational function the splits answer
                // already, in the form they give; in a power of x, `x^2 + a/b`, they did not.
                var whole = r is Number.Integer;
                if (whole && half.Equals(EInteger.One))
                    return node;
                var a = monomials[degree];
                var b = monomials.TryGetValue(half, out var b1) ? b1 : Number.Integer.Zero;
                var c = monomials.TryGetValue(EInteger.Zero, out var c0) ? c0 : Number.Integer.Zero;
                Entity w = half.Equals(EInteger.One) ? wBase : MathS.Pow(wBase, Number.Integer.Create(half));
                // A leading coefficient of known sign, since `sqrt(a (x + h)^2)` is
                // `sqrt(a) |x + h|` for either: a number, or one positive or negative for a real
                // parameter -- `b^2` is, and `a^2 + 2 a b x + b^2 x^2` is the square Rubi writes,
                // and `-b^2` is, whose square has an imaginary root -- whose condition travels
                // with the answer. The other two coefficients are real or symbolic, not a
                // number off the line, so that `(x + h)^2` is not negative.
                // A whole power needs no sign of anything: (a (w + h)^2)^n is a^n (w + h)^(2n).
                if (!whole && a.Evaled is not Number.Real { IsZero: false })
                {
                    if (!IsPositiveForARealParameter(a, x, out var leadingAssumed, assumed)
                        && !IsPositiveForARealParameter((-a).InnerSimplified, x, out leadingAssumed, assumed))
                        return node;
                    assumed = leadingAssumed;
                }
                var leading = a;
                if (b.Evaled is Number.Complex and not Number.Real || c.Evaled is Number.Complex and not Number.Real
                    || !IsAPerfectSquareDiscriminant(a, b, c))
                    return node;
                // a (w + h)^2 with h = b/(2a): (a (w + h)^2)^r is a^r |w + h|^(2r), and with 2r odd
                // (a rational is held in lowest terms) that is a^r sgn(w + h) (w + h)^(2r).
                var h = (b / (Number.Integer.Create(2) * a)).InnerSimplified;
                // `2 a b/(2 b^2)` is `a/b`, which the normalisation does not cancel.
                if (h.Vars.Any())
                    h = Functions.PartialFractions.Bare(h.Simplify());
                var linear = h == Number.Integer.Zero ? w : (w + h).InnerSimplified;
                var twoR = Number.Integer.Create(whole ? r.ERational.Numerator * EInteger.FromInt32(2) : r.ERational.Numerator);
                Entity power = twoR == Number.Integer.One ? linear : MathS.Pow(linear, twoR);
                // The sign in front of the integral rather than inside it: it is constant
                // between the linear factor's zeros, and a rule below that differentiates the
                // integrand cannot evaluate `derivative(sgn(...))` -- which is the exception
                // `sqrt(a^2 + 2abx + b^2x^2) sqrt(c + ex + dx^2)` threw with it left in place.
                // None where it is plainly one: an even power of x plus a positive number, or a
                // root of x of an even order plus one, `sqrt(x) + 1`.
                var modulus = leading == Number.Integer.One ? power : MathS.Pow(leading, r) * power;
                if (!whole && !((half.IsEven || wBase is Powf(_, Number.Rational { ERational.Denominator.IsEven: true }))
                                && h.Evaled is Number.Real { IsPositive: true }))
                {
                    // Each occurrence a factor, or the sign of none of them goes in front: the
                    // two cases are exact for a factor as well, and `(x^2)^(3/2)/(1 + (x^2)^(3/2))`
                    // holds the one root as a factor and inside the sum both.
                    if (factors.Count(factor => factor == node) < expr.Nodes.Count(inner => inner == node))
                    {
                        if (signedLinear is not null && signedLinear != linear)
                        {
                            signsOfMoreThanOneLinear = true;
                            return node;
                        }
                        signedLinear = linear;
                        changed = true;
                        return sign * modulus;
                    }
                    signs = signs * MathS.Signum(linear);
                }
                changed = true;
                return modulus;
            });
            if (!changed || signsOfMoreThanOneLinear)
                return null;
            Entity answer;
            if (signedLinear is null)
            {
                if (Integration.ComputeAsTheSameQuestion(written, x, integrateByParts) is not { } unsigned)
                    return null;
                answer = unsigned;
            }
            else
            {
                if (Integration.ComputeAsTheSameQuestion(written.Substitute(sign, Number.Integer.One).InnerSimplified, x, integrateByParts) is not { } above
                    || Integration.ComputeAsTheSameQuestion(written.Substitute(sign, Number.Integer.MinusOne).InnerSimplified, x, integrateByParts) is not { } below)
                    return null;
                answer = MathS.Piecewise(new[] { new Providedf(above, signedLinear > Number.Integer.Zero) }, below);
            }
            if (signs != Number.Integer.One)
                answer = signs * answer;
            return assumed == Entity.Boolean.True ? answer : answer.Provided(assumed);
        }

        /// <summary>
        /// A fractional power of a sum whose every term has x to a power in it,
        /// <c>(a x^j + b x^n)^p</c> with <c>0 &lt; j &lt; n</c>, as <c>K x^(j p) (a + b x^(n - j))^p</c>:
        /// the integral is <c>K</c> times the integral with <c>x^(j p) (a + b x^(n - j))^p</c> in its
        /// place, where <c>K = (a x^j + b x^n)^p / (x^(j p) (a + b x^(n - j))^p)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>K</c> is constant on every interval where x and the sum are not zero: with
        /// <c>S = x^j T</c>, its logarithmic derivative is <c>p (S'/S - j/x - T'/T)</c>, and
        /// <c>S'/S = j/x + T'/T</c>. So it goes in front of the integral, as the factor of a square
        /// does in <see cref="SolveByWritingAPowerOfASquareAsAPowerOfItsRoot"/>. For an even whole
        /// <c>j</c> and a whole <c>j p</c> it is <c>sgn(x)^(j p)</c>: <c>x^j</c> is not negative for a
        /// real x, so <c>(x^j T)^p</c> is <c>|x|^(j p) T^p</c>.
        /// </para>
        /// <para>
        /// Rubi's 1.1.4.2 and 1.1.4.3 write these by the hundred: <c>1/sqrt(a x^2 + b x^5)</c> and
        /// <c>1/(x sqrt(b x^(2/3) + a x))</c> were declined, the first since the factorization
        /// over the rationals does not read a symbol, and the second since nothing took the power
        /// of x out of the root. With it out, the binomial is what the rules for
        /// <c>x^m (a + b x^n)^p</c> read. At the top only, where the answer is the caller's.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByTakingAPowerOfXOutOfAFractionalPower(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // The sum as a factor of the integrand, above the bar or below it.
            var (above, below) = Functions.SingleQuotient.Of(expr);
            (Entity Sum, Entity Exponent, Number.Rational Lowest, Entity Quotient, bool Below)? found = null;
            foreach (var (side, isBelow) in new[] { (above, false), (below, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is not Powf(var sum, var power) || power is Number.Integer || power.ContainsNode(x)
                        || !sum.ContainsNode(x) || sum.Complexity > 60)
                        continue;
                    if ((OutOfASum(sum) ?? OutOfAProduct(sum)) is not var (lowest, rest))
                        continue;
                    // An odd whole power of x out of a sum of whole powers: the sum is real on both
                    // sides of 0 and x^(j p) is not, and the rules for the sum as written answer it
                    // on both. An even one comes out as its sign, and a fractional one is real for a
                    // positive x only, as the sum already was.
                    if (lowest is Number.Integer { EInteger.IsEven: false } && !sum.Nodes.Any(node => node is Powf(var @base, Number.Rational r) && @base == x && r is not Number.Integer))
                        continue;
                    // Two such would want two factors.
                    if (found is { })
                        return null;
                    found = (sum, power, lowest, rest, isBelow);
                }
            if (found is not var (theSum, exponentOfTheSum, j, theRest, sumIsBelow)
                || above.Nodes.Concat(below.Nodes).Count(node => node == theSum) != 1)
                return null;
            var outside = (j * exponentOfTheSum).InnerSimplified;
            Entity Without(Entity side)
            {
                Entity product = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(side))
                    if (!(factor is Powf(var sum, var power) && sum == theSum && power == exponentOfTheSum))
                        product = product == Number.Integer.One ? factor : product * factor;
                return product;
            }
            var replacement = MathS.Pow(x, outside) * MathS.Pow(theRest, exponentOfTheSum);
            var written = sumIsBelow ? Without(above) / (replacement * Without(below)) : replacement * Without(above) / below;
            if (Integration.ComputeIndefiniteIntegral(written.InnerSimplified, x, integrateByParts) is not { } integral)
                return null;
            // K: the sign of x to the power j p where that is all it is, which is its own reciprocal,
            // and the quotient otherwise.
            var aSign = j is Number.Integer { EInteger.IsEven: true } && outside is Number.Integer;
            Entity constant = aSign
                ? (((Number.Integer)outside).EInteger.IsEven ? Number.Integer.One : MathS.Signum(x))
                : MathS.Pow(theSum, exponentOfTheSum) / replacement;
            var answer = constant == Number.Integer.One ? integral : sumIsBelow && !aSign ? integral / constant : constant * integral;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;

            // A sum, each term a coefficient times a rational power of x: the lowest power, not 0,
            // and what is left with it taken out of every term.
            (Number.Rational, Entity)? OutOfASum(Entity sum)
            {
                if (sum is not (Sumf or Minusf))
                    return null;
                var terms = new List<(Entity Coefficient, Number.Rational Exponent)>();
                foreach (var term in Sumf.LinearChildren(sum))
                {
                    if (PowerOfX(term, x) is not { } read)
                        return null;
                    terms.Add(read);
                }
                if (terms.Count < 2)
                    return null;
                var lowest = terms.Select(term => term.Exponent).Aggregate((least, next) => next.ERational.CompareTo(least.ERational) < 0 ? next : least);
                if (lowest.ERational.IsZero)
                    return null;
                Entity rest = Number.Integer.Zero;
                foreach (var (coefficient, exponent) in terms)
                {
                    var shifted = Number.Rational.Create(exponent.ERational.Subtract(lowest.ERational));
                    rest += shifted is Number.Integer { EInteger.IsZero: true } ? coefficient
                        : coefficient * (shifted == Number.Integer.One ? x : MathS.Pow(x, shifted));
                }
                return (lowest, rest);
            }
            // A product or a quotient with powers of x among its factors and something else of x:
            // `x^2 (a + b x^3)`, `(a + b x^3)/x`.
            (Number.Rational, Entity)? OutOfAProduct(Entity product)
            {
                if (product is not (Mulf or Divf))
                    return null;
                var (numerator, denominator) = Functions.SingleQuotient.Of(product);
                var exponent = ERational.Zero;
                Entity rest = Number.Integer.One;
                foreach (var (side, sign) in new[] { (numerator, 1), (denominator, -1) })
                    foreach (var factor in Mulf.LinearChildren(side))
                    {
                        if (factor == x)
                            exponent = sign > 0 ? exponent.Add(ERational.One) : exponent.Subtract(ERational.One);
                        else if (factor is Powf(var @base, Number.Rational power) && @base == x)
                            exponent = sign > 0 ? exponent.Add(power.ERational) : exponent.Subtract(power.ERational);
                        else
                            rest = sign > 0 ? rest * factor : rest / factor;
                    }
                return exponent.IsZero || !rest.ContainsNode(x) ? null : (Number.Rational.Create(exponent), rest);
            }

            // A term as a coefficient free of x and a rational exponent of x, through products and
            // quotients.
            static (Entity Coefficient, Number.Rational Exponent)? PowerOfX(Entity term, Entity.Variable x)
            {
                if (!term.ContainsNode(x))
                    return (term, Number.Integer.Zero);
                switch (term)
                {
                    case Entity.Variable v when v == x:
                        return (Number.Integer.One, Number.Integer.One);
                    case Powf(var @base, Number.Rational power) when @base == x:
                        return (Number.Integer.One, power);
                    case Mulf(var left, var right):
                        if (PowerOfX(left, x) is not var (lc, le) || PowerOfX(right, x) is not var (rc, re))
                            return null;
                        return (lc * rc, Number.Rational.Create(le.ERational.Add(re.ERational)));
                    case Divf(var left, var right):
                        if (PowerOfX(left, x) is not var (nc, ne) || PowerOfX(right, x) is not var (dc, de))
                            return null;
                        return (nc / dc, Number.Rational.Create(ne.ERational.Subtract(de.ERational)));
                    default:
                        return null;
                }
            }
        }

        /// <summary>
        /// A power of a square written out, <c>(A + B w + C w^2)^p</c> with <c>B^2 = 4 A C</c> and
        /// <c>w = x^k</c>, as the power of its root, <c>L = w + B/(2 C)</c>: the integral is
        /// <c>F</c> times the integral with <c>L^(2p)</c> in its place, where
        /// <c>F = (A + B w + C w^2)^p / L^(2p)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The square is <c>C L^2</c>, and <c>F</c> is constant on every interval where <c>L</c> is
        /// not zero: its derivative is <c>2 p w' L^(2p-1) (C L^2 Q^(p-1) - Q^p) / L^(4p)</c>, and
        /// <c>Q^(p-1) Q = Q^p</c> wherever <c>Q</c> is not zero. So <c>F</c> goes in front of the
        /// integral, whatever <c>p</c> is: a symbol, <c>3/4</c>, or half an odd number with a
        /// leading coefficient of unknown sign. For a whole <c>p</c> it is <c>C^p</c>. The square
        /// is a factor of the integrand or nothing is read: below the bar <c>1/F</c> comes out,
        /// and out of a sum nothing does.
        /// </para>
        /// <para>
        /// After <see cref="SolveByTakingARootOfAPerfectSquare"/>, which answers half an odd power
        /// of a square in a whole power of x with the sign written out, and before which nothing
        /// read <c>k</c> as anything but a whole number. This reads <c>k</c> as any exponent, a
        /// fraction or a symbol: Rubi's 1.2.3.2 <c>x^2 (a^2 + 2 a b x^3 + b^2 x^6)^p</c>,
        /// <c>x sqrt(a^2 + 2 a b x^n + b^2 x^(2n))</c> and <c>(a^2 + 2 a b x^2 + b^2 x^4)^(3/4)</c>
        /// were declined. At the top only, where the answer is the caller's, as for the sign the
        /// rule above writes.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByWritingAPowerOfASquareAsAPowerOfItsRoot(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // The square as a factor of the integrand, above the bar or below it, and nowhere else:
            // the factor comes out of a product and not out of a sum, and below the bar it is its
            // reciprocal that comes out.
            var (above, below) = Functions.SingleQuotient.Of(expr);
            (Entity Square, Entity Exponent, Entity Root, Entity Leading, bool Below)? found = null;
            foreach (var (side, isBelow) in new[] { (above, false), (below, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (factor is not Powf(var radicand, var power) || !radicand.ContainsNode(x) || power.ContainsNode(x)
                        || radicand is not (Sumf or Minusf) || radicand.Complexity > 60
                        || TrinomialInAPowerOfX(radicand, x) is not var (a, b, c, w, k))
                        continue;
                    var whole = power is Number.Integer;
                    var halfOdd = power is Number.Rational half && half.ERational.Denominator.Equals(EInteger.FromInt32(2));
                    var kIsWhole = k is Number.Integer { EInteger.Sign: > 0 };
                    // What the rule above and the rational rules answer: half an odd power, or a
                    // whole one, of a square in a whole power of x.
                    if (kIsWhole && (whole || halfOdd))
                        continue;
                    if (!VanishesIdentically(b * b - 4 * a * c))
                        continue;
                    // Two squares would want two factors; one is what Rubi writes.
                    if (found is { })
                        return null;
                    var shift = Functions.PartialFractions.InLowestTermsOverTheSymbols(b / (2 * c));
                    found = (radicand, power, shift == Number.Integer.Zero ? w : w + shift, c, isBelow);
                }
            if (found is not var (square, exponent, root, leading, squareIsBelow)
                || above.Nodes.Concat(below.Nodes).Count(node => node == square) != 1)
                return null;
            var twice = (2 * exponent).InnerSimplified;
            // The root's power above the bar either way, with a negative exponent for the square
            // below it: `x (x + h)^(-2p)` is read below the top where `x/(x + h)^(2p)` was not.
            Entity Without(Entity side)
            {
                Entity product = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(side))
                    if (!(factor is Powf(var radicand, var power) && radicand == square && power == exponent))
                        product = product == Number.Integer.One ? factor : product * factor;
                return product;
            }
            var ofTheRoot = MathS.Pow(root, squareIsBelow ? (-twice).InnerSimplified : twice);
            var written = squareIsBelow
                ? ofTheRoot * above / Without(below)
                : ofTheRoot * Without(above) / below;
            if (Integration.ComputeIndefiniteIntegral(written, x, integrateByParts) is not { } integral)
                return null;
            // F: the leading coefficient's power where p is whole, and the quotient otherwise.
            var factorOfTheSquare = exponent is Number.Integer
                ? MathS.Pow(leading, exponent)
                : MathS.Pow(square, exponent) / MathS.Pow(root, twice);
            return (squareIsBelow ? integral / factorOfTheSquare : factorOfTheSquare * integral);

            // A + B x^k + C x^(2k), each term a coefficient times a power of x, with the three
            // exponents 0, k and 2k.
            static (Entity A, Entity B, Entity C, Entity W, Entity K)? TrinomialInAPowerOfX(Entity sum, Entity.Variable x)
            {
                var terms = new List<(Entity Coefficient, Entity Exponent)>();
                foreach (var term in Sumf.LinearChildren(sum))
                {
                    if (PowerOfX(term, x) is not { } read)
                        return null;
                    terms.Add(read);
                }
                if (terms.Count != 3)
                    return null;
                var constant = terms.Where(term => term.Exponent == Number.Integer.Zero).ToList();
                if (constant.Count != 1)
                    return null;
                var others = terms.Where(term => term.Exponent != Number.Integer.Zero).ToList();
                foreach (var (first, second) in new[] { (others[0], others[1]), (others[1], others[0]) })
                    if (VanishesIdentically(second.Exponent - 2 * first.Exponent) && !VanishesIdentically(first.Exponent))
                    {
                        var k = first.Exponent.InnerSimplified;
                        return (constant[0].Coefficient, first.Coefficient, second.Coefficient, MathS.Pow(x, k), k);
                    }
                return null;
            }

            // A term as a coefficient free of x and an exponent of x, through products and quotients.
            static (Entity Coefficient, Entity Exponent)? PowerOfX(Entity term, Entity.Variable x)
            {
                if (!term.ContainsNode(x))
                    return (term, Number.Integer.Zero);
                switch (term)
                {
                    case Entity.Variable v when v == x:
                        return (Number.Integer.One, Number.Integer.One);
                    case Powf(var @base, var power) when @base == x && !power.ContainsNode(x):
                        return (Number.Integer.One, power);
                    case Mulf(var left, var right):
                        if (PowerOfX(left, x) is not var (lc, le) || PowerOfX(right, x) is not var (rc, re))
                            return null;
                        return (lc * rc, (le + re).InnerSimplified);
                    case Divf(var above, var below):
                        if (PowerOfX(above, x) is not var (ac, ae) || PowerOfX(below, x) is not var (bc, be))
                            return null;
                        return (ac / bc, (ae - be).InnerSimplified);
                    default:
                        return null;
                }
            }
        }

        /// <summary>
        /// <paramref name="sum"/> as a polynomial in <c>w = x^k</c> for a rational <c>k</c> that is
        /// not whole, each of its terms a constant times a power of <paramref name="x"/> that is a
        /// whole, non-negative multiple of <c>k</c>; <see langword="null"/> otherwise.
        /// </summary>
        private static (Dictionary<EInteger, Entity> Monomials, Number.Rational K)? InAFractionalPowerOfX(Entity sum, Entity.Variable x)
        {
            var terms = new List<(ERational Power, Entity Coefficient)>();
            foreach (var term in Sumf.LinearChildren(sum))
            {
                var power = ERational.Zero;
                Entity coefficient = Number.Integer.One;
                foreach (var (factor, underneath) in FactorsOfTheIntegrand(term))
                {
                    if (!factor.ContainsNode(x))
                    {
                        coefficient = underneath ? coefficient / factor : coefficient * factor;
                        continue;
                    }
                    var exponent = factor == x ? ERational.One
                        : factor is Powf(var @base, Number.Rational q) && @base == x ? q.ERational
                        : (ERational?)null;
                    if (exponent is null)
                        return null;
                    power = underneath ? power.Subtract(exponent) : power.Add(exponent);
                }
                terms.Add((power, coefficient));
            }
            var powers = terms.Select(term => term.Power).Where(q => !q.IsZero).Distinct().ToList();
            if (powers.Count == 0 || powers.All(q => q.IsInteger()) || powers.Any(q => q.Sign > 0) && powers.Any(q => q.Sign < 0))
                return null;
            // k the greatest common divisor of the powers, with their sign.
            var numerators = EInteger.Zero;
            var denominators = EInteger.One;
            foreach (var q in powers)
            {
                numerators = numerators.Gcd(q.Numerator.Abs());
                denominators = denominators.Multiply(q.Denominator).Divide(denominators.Gcd(q.Denominator));
            }
            var k = ERational.Create(numerators, denominators);
            if (powers[0].Sign < 0)
                k = k.Negate();
            var monomials = new Dictionary<EInteger, Entity>();
            foreach (var (power, coefficient) in terms)
            {
                var degree = power.Divide(k);
                if (!degree.IsInteger() || degree.Sign < 0)
                    return null;
                var key = degree.ToEInteger();
                monomials[key] = monomials.TryGetValue(key, out var so) ? so + coefficient : coefficient;
            }
            return (monomials, Number.Rational.Create(k));
        }

        /// <summary>
        /// A power of a linear that is a constant multiple of a quadratic's derivative, beside a
        /// power of the quadratic, under the linear as the variable: with <c>t = λ (b + 2 c x)</c>
        /// the quadratic <c>a + b x + c x^2</c> is <c>(t^2/λ^2 - Δ)/(4 c)</c>, with
        /// <c>Δ = b^2 - 4 a c</c>, so <c>t^m Q^p</c> is a binomial in <c>t</c>. Rubi's 1.2.1.2,
        /// <c>(b d + 2 c d x)^m (a + b x + c x^2)^p</c>, which it substitutes the same way.
        /// </summary>
        /// <remarks>
        /// The substitution is affine, so the integrand in <c>t</c> is the integrand exactly. The
        /// quadratic is written in <c>t</c> from its coefficients rather than by substituting:
        /// substituted, it keeps a linear term that is zero as a value and not as written, and the
        /// rules for a binomial read <c>α + β t^2</c>. Only where a power is not whole: a rational
        /// function is the partial fractions'.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTheDerivativeOfAQuadraticAsTheVariable(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            Entity constant = Number.Integer.One;
            (Entity Base, Entity Exponent)? linear = null, quadratic = null;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                var (@base, exponent) = factor is Powf(var b, var e) && !e.ContainsNode(x) ? (b, e) : (factor, (Entity)Number.Integer.One);
                if (underneath)
                    exponent = (-exponent).InnerSimplified;
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var read) || read.Count == 0 || read.Keys.Any(k => k.Sign < 0)
                    || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                    return null;
                var degree = read.Keys.Max()!;
                if (degree.Equals(EInteger.One) && linear is null)
                    linear = (@base, exponent);
                else if (degree.Equals(EInteger.FromInt32(2)) && quadratic is null)
                    quadratic = (@base, exponent);
                else
                    return null;
            }
            if (linear is not var (l, m) || quadratic is not var (q, p) || m is Number.Integer && p is Number.Integer)
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(l, x, out var l1, out var l0)
                || !TreeAnalyzer.TryGetPolyQuadratic(q, x, out var c2, out var c1, out var c0)
                || VanishesIdentically(c2) || VanishesIdentically(l1)
                // With no linear term the integrand is a binomial in x already, and taken as one in
                // t it would be this question again with t scaled.
                || VanishesIdentically(c1)
                // The linear is a multiple of 2 c x + b where its root is the vertex's.
                || !VanishesIdentically(2 * c2 * l0 - c1 * l1))
                return null;
            var lambda = Reduced(l1 / (2 * c2));
            // Q = (t^2/λ^2 - Δ)/(4 c) = α + β t^2, each constant named by a symbol of its own where
            // it is a compound of the coefficients, and written back into the answer: the rules for
            // a binomial answer `t^(-7) sqrt(c t^2 + k)` in milliseconds, and with
            // `a - b^2/(4 c)` for `k` they ran out of time.
            var alpha = Reduced(-(c1 * c1 - 4 * c2 * c0) / (4 * c2));
            var beta = Reduced(1 / (4 * c2 * lambda * lambda));
            var t = Variable.CreateUnique(expr, "t_deriv");
            var named = new List<(Variable Name, Entity Value)>();
            Entity Named(Entity value)
            {
                if (value is Number or Variable || value is Mulf(Number, Variable) || value is Powf(Variable, Number))
                    return value;
                var name = Variable.CreateUnique(expr + t + named.Aggregate((Entity)Number.Integer.Zero, (sum, pair) => sum + pair.Name), "k_named");
                named.Add((name, value));
                return name;
            }
            var inT = Reduced(constant / l1) * MathS.Pow(t, m) * MathS.Pow(Named(alpha) + Named(beta) * MathS.Sqr(t), p);
            if (Integration.ComputeAsAQuestionOfItsOwn(inT, t, integrateByParts) is not { } answer
                || answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            foreach (var (name, value) in named)
                answer = answer.Substitute(name, value);
            return answer.Substitute(t, l);

            static Entity Reduced(Entity constant)
                => constant.Vars.Any() ? Functions.PartialFractions.InLowestTermsOverTheSymbols(constant) : constant.InnerSimplified;
        }

        /// <summary>
        /// A whole power of a product in which the variable stands beside a constant, written
        /// as the product of the powers: <c>(c x)^2</c> is <c>c^2 x^2</c>, exact for a whole
        /// power over the complex numbers. That is the spelling the parser gives the inverse
        /// hyperbolic secant and cosecant -- <c>acsch(c x)</c> is
        /// <c>ln(1/(c x) + sqrt(1/(c x)^2 + 1))</c> -- and every rule that reads a polynomial in
        /// <c>x</c> read <c>(c x)^2</c> as a power of something that is not one: <c>x acsch(c x)</c>
        /// was declined where <c>x acsch(2 x)</c> was answered, the numeric coefficient having
        /// been folded on the way. A symbolic constant beside the variable only: a numeric one
        /// is folded by the rules already, and rewriting for it re-asked every sub-integrand
        /// with a <c>(2 u)^3</c> in it -- Welz's 67 went from 4 s to 34. Asked as a question of
        /// its own. Rubi's 7.5.1 and 7.6.1.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByDistributingWholePowersOfProducts(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var distributed = expr.Replace(node =>
                node is Powf(Mulf(var l, var r) product, Number.Integer power) && product.ContainsNode(x)
                    && (!l.ContainsNode(x) && l.Vars.Any() || !r.ContainsNode(x) && r.Vars.Any())
                    ? MathS.Pow(l, power) * MathS.Pow(r, power)
                    : node);
            // The same question: `(c x)^2` and `c^2 x^2` are one integrand, and asked one
            // level down the remainder by parts leaves from `asech(c x)/(d + e x)^2` sat past
            // the rules scoped to the question asked or one below it, the power of a quotient
            // written apart among them, which is what answers it.
            return distributed == expr ? null : Integration.ComputeAsTheSameQuestion(distributed, x, integrateByParts);
        }

        /// <summary>
        /// A whole power of a quotient with a symbol in it, written as the quotient of the powers:
        /// <c>(c/(a + c u^2))^2</c> is <c>c^2/(a + c u^2)^2</c>, exact for a whole power. That is how
        /// the substitution <c>u = x^2</c> writes <c>x/(a + c x^4)^2</c>, having simplified
        /// <c>1/(a/c + u^2)^2</c>, and the table reads the quotient of the powers and not the power
        /// of the quotient: <c>c^2/(a + c x^2)^2</c> was answered in a few milliseconds where
        /// <c>(c/(a + c x^2))^2</c> went to parts and was declined after twenty-six seconds, and
        /// <c>x/(a + c x^4)^2</c> was answered after forty, by another route. With numbers only it
        /// is answered as it is already. Only a quotient of two polynomials in <paramref name="x"/>:
        /// the hyperbolic functions arrive as quotients of exponentials, and the imaginary tangent's
        /// sum as <c>A e^(i z)/cos(z)</c>, and written apart those went to slower routes --
        /// <c>cosh(c + d x)/(a + b tanh(c + d x)^2)</c> from 17 ms to past five seconds. And only with
        /// a monomial left above the bar, the table's <c>x^m/(a + b x^n)^p</c>: a sum there is
        /// multiplied out by the rational rules, and the folded <c>tanh(a + 2 ln(x))^2</c>,
        /// <c>((e^(2a) x^4 - 1)/(e^(2a) x^4 + 1))^2</c>, went from five seconds to forty-five that way.
        /// Asked as the same question.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        internal static Entity? SolveByDistributingWholePowersOfQuotients(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var distributed = expr.Replace(node =>
                node is Powf(Divf(var above, var below) quotient, Number.Integer power) && quotient.ContainsNode(x)
                    && quotient.Vars.Any(symbol => symbol != x)
                    && IsAPolynomialIn(above, x) && IsAPolynomialIn(below, x)
                    && IsAMonomialIn(power.EInteger.Sign > 0 ? above : below, x)
                    ? power.EInteger.Sign > 0
                        ? MathS.Pow(above, power) / MathS.Pow(below, power)
                        : MathS.Pow(below, Number.Integer.Create(power.EInteger.Negate())) / MathS.Pow(above, Number.Integer.Create(power.EInteger.Negate()))
                    : node);
            return distributed == expr ? null : Integration.ComputeAsTheSameQuestion(distributed, x, integrateByParts);

            static bool IsAPolynomialIn(Entity expr, Entity.Variable x)
                => TreeAnalyzer.TryGetPolynomial(expr, x, out var terms)
                   && terms.Keys.All(power => power.Sign >= 0) && terms.Values.All(coefficient => !coefficient.ContainsNode(x));
            static bool IsAMonomialIn(Entity expr, Entity.Variable x)
                => TreeAnalyzer.TryGetPolynomial(expr, x, out var terms) && terms.Count == 1;
        }

        /// <summary>
        /// A polynomial in <c>x</c> times a rational function of exponentials of <c>x</c>,
        /// by parts against the whole rational function: <c>x tanh(x)^2</c> is
        /// <c>x ((e^(2x) - 1)/(e^(2x) + 1))^2</c>, whose antiderivative under <c>u = e^(2x)</c> is
        /// <c>x - tanh(x)</c>, a polynomial and a rational function of the exponential again,
        /// and what parts leaves is <c>x - tanh(x)</c> itself, a degree lower in <c>x</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The general parts rule splits the sum <c>(x + x e^(4x))/(e^(2x) + 1)^2</c> and takes
        /// each term on its own, and each term's antiderivative in <c>u</c> holds a logarithm
        /// of <c>e^(2x) + 1</c> -- the two cancel in the sum and neither on its own -- so each
        /// leaves <c>x ln(e^(2x) + 1)</c> behind, a dilogarithm, and twenty-five seconds of
        /// search that found nothing. Here the rational function goes to the exponential
        /// substitution whole, and where its antiderivative keeps a logarithm of an
        /// exponential's sum the integrand is declined at once: <c>x/(e^x + 1)</c> is not
        /// elementary, and this says so in a millisecond.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPolynomialTimesARationalFunctionOfAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // The polynomial factors above the bar, and the rest, which holds x in exponents only.
            var (above, below) = Functions.SingleQuotient.Of(expr);
            Entity polynomial = Number.Integer.One;
            Entity restAbove = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(above))
            {
                if (factor.ContainsNode(x) && !factor.Nodes.Any(node => node is Powf(var b, var e) && b == MathS.e && e.ContainsNode(x))
                    && TreeAnalyzer.TryGetPolynomial(factor, x, out var read) && read.Keys.All(k => k.Sign >= 0) && read.Values.All(c => !c.ContainsNode(x)))
                    polynomial = polynomial * factor;
                else
                    restAbove = restAbove * factor;
            }
            if (!polynomial.ContainsNode(x))
                return null;
            var rest = (restAbove / below).InnerSimplified;
            // A rational function, with the exponential below the bar somewhere: a polynomial
            // times an exponential alone is parts', and keeps its form there.
            if (!rest.ContainsNode(x) || !rest.Nodes.Any(node => node is Divf(_, var d) && d.ContainsNode(x) || node is Powf(var b, Number.Integer { IsNegative: true }) && b.ContainsNode(x)))
                return null;
            var placeholder = Variable.CreateUnique(expr, "u_exp");
            var withoutExponentials = rest.Replace(node =>
                node is Powf(var b, var e) && b == MathS.e && e.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(e, x, out _, out _) ? placeholder : node);
            if (withoutExponentials.ContainsNode(x) || withoutExponentials.Nodes.Any(node => node is Powf(_, Number.Rational r) && r is not Number.Integer && node.ContainsNode(placeholder)))
                return null;

            if (SolveByExponentialSubstitution(rest, x, integrateByParts: false) is not { } antiderivative)
                return null;
            // ln(e^(k x)) is k x; any other logarithm of the exponential's sums makes the next
            // step a dilogarithm.
            antiderivative = Functions.PartialFractions.Bare(antiderivative.Replace(node =>
                node is Logf(var @base, var argument) && @base == MathS.e && argument is Powf(var b, var e) && b == MathS.e ? e : node));
            if (antiderivative.Nodes.Any(node => node is Logf && node.ContainsNode(x)))
                return null;
            var derivative = polynomial.Differentiate(x).InnerSimplified;
            if (derivative.Evaled is Number.Complex { IsZero: true })
                return polynomial * antiderivative;
            var remainder = Functions.PartialFractions.Bare((derivative * antiderivative).InnerSimplified);
            if (Integration.ComputeIndefiniteIntegral(remainder, x, integrateByParts) is not { } integrated)
                return null;
            var answer = polynomial * antiderivative - integrated;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        internal static Entity? SolveByExponentialSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Rational slopes, so that `e^(x/2)` beside `e^x` is read: the base is `e^(k x)` with
            // `k` the greatest common divisor of the slopes, and every exponential is a whole
            // power of it. `e^(x/2)/sqrt(e^x - 1)` is `2/sqrt(u^2 - 1)` that way, and was declined
            // for the half.
            // Any one base free of x, not only e: Timofeev's `1/sqrt(a^(2x) - 1)` is
            // `1/(u ln(a) sqrt(u^2 - 1))` under `u = a^x`, with `dx = du/(u ln a)`.
            // Numeric bases that are whole powers of one base are written in it first:
            // Rubi's `2^x/sqrt(a + b/4^x)` is `2^x/sqrt(a + b/2^(2x))`, and rational in `u = 2^x`.
            expr = WithNumericBasesUnified(expr, x);
            // And the slopes need only be rational multiples of one another: with a symbol
            // for the slope, `F^(c + d x)` beside `F^(2c + 2dx)`, the base is `F^(d x)` and
            // `dx = du/(d u ln F)`. Rubi's `F^(c + d x) x/(a + b F^(c + d x))^2`.
            var slopes = new List<ERational>();
            var offsets = new Dictionary<Entity, (ERational Slope, Entity Offset)>();
            var underARadical = new HashSet<Entity>();
            Entity? commonBase = null;
            Entity? slopeUnit = null;
            // The first exponential's slope and offset, and whether every other's offset is
            // in the same ratio to its slope: then every exponent is a multiple of one
            // `x + shift`, and u is a power of the base at that rather than at x. Rubi's
            // `csch(29/10 + 13/10 x)^3 (17/10 + 23/10 sech(29/10 + 13/10 x)^2)^3` is a
            // rational function of `u = e^(13/10 x + 29/10)` with numbers for its
            // coefficients, where `u = e^(13/10 x)` left `e^(29/10)` in every one of them,
            // a quadratic the rational rules do not factor over, and each term seconds.
            // Compared cross-multiplied, so that a symbolic slope is never divided by.
            (ERational Slope, Entity Offset)? first = null;
            var oneShift = true;
            foreach (var node in expr.Nodes)
            {
                if (node is Powf(_, Number.Rational fractional) && fractional is not Number.Integer)
                    foreach (var inside in node.Nodes)
                        underARadical.Add(inside);
                if (node is not Powf(var @base, var exponent) || @base.ContainsNode(x) || exponent is Number)
                    continue;
                if (!exponent.ContainsNode(x))
                    continue;
                if (commonBase is null)
                    commonBase = @base;
                else if (commonBase != @base)
                    return null;
                if (!TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out var offset))
                    return null;   // not linear in x, so not a power of one exponential
                ERational multiple;
                if (slope.Evaled is Number.Rational rational)
                {
                    if (rational.ERational.IsZero || slopeUnit is not null)
                        return null;
                    multiple = rational.ERational;
                }
                else
                {
                    if (slopes.Count > 0 && slopeUnit is null)
                        return null;
                    slopeUnit ??= slope;
                    if (Functions.PartialFractions.Bare((slope / slopeUnit).Simplify()).Evaled is not Number.Rational ratio || ratio.ERational.IsZero)
                        return null;
                    multiple = ratio.ERational;
                }
                slopes.Add(multiple);
                offsets[node] = (multiple, offset);
                if (first is null)
                    first = (multiple, offset);
                else if (oneShift && !IsTheZeroPolynomial(offset * Number.Rational.Create(first.Value.Slope) - first.Value.Offset * Number.Rational.Create(multiple)))
                    oneShift = false;
            }
            if (slopes.Count == 0 || commonBase is null)
                return null;
            if (commonBase != MathS.e && (commonBase.Evaled is Number.Complex and not Number.Real || commonBase.Evaled is Number.Real { IsNegative: true } || TreeAnalyzer.IsZero(commonBase)))
                return null;   // a base that is not a positive real is not an exponential of the kind substituted for
            var logarithmOfTheBase = commonBase == MathS.e ? Number.Integer.One : MathS.Ln(commonBase);
            if (slopeUnit is not null)
                logarithmOfTheBase = (logarithmOfTheBase * slopeUnit).InnerSimplified;

            var numerators = EInteger.Zero;
            var denominators = EInteger.One;
            foreach (var slope in slopes)
            {
                numerators = numerators.Gcd(slope.Numerator.Abs());
                denominators = denominators.Multiply(slope.Denominator).Divide(denominators.Gcd(slope.Denominator));
            }
            if (numerators.IsZero)
                return null;
            var k = ERational.Create(numerators, denominators);
            // The sign of the base is chosen for the radicals: with every exponential under a
            // root of negative slope, `u = e^(-x)` makes `sqrt(1 + e^(-x))` into `sqrt(1 + u)`,
            // where `u = e^x` would make it `sqrt(1 + 1/u)`, a root of a quotient that nothing
            // rationalises. `u` is positive either way, since it is an exponential.
            var slopesUnderRoots = offsets.Where(pair => underARadical.Contains(pair.Key)).Select(pair => pair.Value.Slope).ToList();
            if (slopesUnderRoots.Count > 0 && slopesUnderRoots.All(slope => slope.Sign < 0))
                k = k.Negate();

            var u = Variable.CreateUnique(expr, "u_exp");

            // e^(k_i x + m_i) is e^(m_i) times u^(k_i/k), and k_i/k is a whole number by
            // construction. Built directly rather than by substituting x and simplifying, for the
            // same reason as the radical substitutions: (u^(1/k))^(k_i) is not something the
            // simplifier will reduce, and is right not to.
            // With one shift, e^(k_i x + m_i) is u^(k_i/k) exactly for
            // u = e^(k x + k m_1/k_1), and no e^(m_i) is left in the coefficients.
            var shifted = oneShift && first is { } firstOne && !TreeAnalyzer.IsZero(firstOne.Offset) && !firstOne.Offset.ContainsNode(x);
            var shiftOfU = shifted ? (Number.Rational.Create(k.Divide(first!.Value.Slope)) * first.Value.Offset).InnerSimplified : Number.Integer.Zero;
            var rewritten = expr.Replace(node =>
                offsets.TryGetValue(node, out var found)
                    ? (shifted ? Number.Integer.One : MathS.Pow(commonBase, found.Offset))
                      * MathS.Pow(u, Number.Integer.Create(found.Slope.Divide(k).ToLowestTerms().Numerator))
                    : node);

            if (rewritten.ContainsNode(x))
                return null;

            // dx = du/(k u). Combined into one quotient and then simplified, in that order, and
            // the order decides four of these. Combine does not cancel, so 1/(e^x + e^(-x)) leaves
            // u/(u(u^2 + 1)) -- which the rational integrator declines although it answers
            // 1/(u^2 + 1) at once. Simplifying first instead leaves the nesting for Combine to
            // flatten and the common factor never meets a cancellation.
            // The logarithm of the base stays outside: simplified into the quotient,
            // `1/((a + b u)^2 ln F)` is a quadratic below the bar with `ln F` in every
            // coefficient, and the symbolic quadratic rule answers that as a piecewise on
            // whether `b^2 ln F` is zero, where `1/(a + b u)^2` is `-1/(b (a + b u))`.
            var integrand = Functions.SingleQuotient.Combine(
                rewritten / (Number.Rational.Create(k) * u)).Simplify();
            if (integrand is Providedf(var inner, _))
                integrand = inner;
            integrand = WithLogarithmArgumentsOverOneBar(integrand, u);
            // A whole power of a product is written as the product of the powers: the
            // simplifier writes `4a^2 u^2` as `(a u)^2 4`, and no rational reader sees the `u^2`
            // inside -- Timofeev's `1/(a^2 + b^2 cosh(x)^2)` was declined in that spelling and
            // is answered in the other.
            integrand = WithWholePowersOfProductsDistributed(integrand);
            // u is an exponential, so it is positive, and a root holding a power of it gives
            // that power up: `sqrt(1 + tanh(4x))` is a root of `2u/(1 + u)` here and nothing
            // rationalises that; as `sqrt(2) sqrt(u)/sqrt(1 + u)` it is one substitution more.
            integrand = FactorANonnegativeVariableOutOfRadicals(integrand, u);

            // What that leaves can be two square roots of linears in u -- `sqrt(u)/(u sqrt(1 + u))`
            // for `sqrt(1 + tanh(4x))` -- which the linear-radical substitution answers only
            // when told that u is not negative, as an exponential is; asked directly, so that
            // it is told.
            if (SolveByLinearRadicalSubstitution(integrand, u, integrateByParts, variableIsNonnegative: true) is { } byARoot)
                return Finished(byARoot);
            // The reciprocal substitution, told the same: a hyperbolic function under a root
            // is a palindromic quartic under it here, and `u - 1/u` is `2 sinh(x)`. Under a
            // root only: a rational function of u is the rational rules' below, in one closed
            // step, and `cosh/sinh^4` -- `8u (u^2 + 1)/(u^2 - 1)^4` -- came back from here as
            // a reduction over `1/(u^2 - 1)^k` with a logarithm at the bottom, which is
            // `-1/(3 sinh^3)` after four seconds of simplifying the product it stands in.
            if (HasARadicalOf(integrand, u) && SolveByReciprocalSubstitution(integrand, u, variableIsPositive: true) is { } byTheReciprocal)
                return Finished(byTheReciprocal);
            // The same question in u, not a step in the search for it: asked at the top when
            // this was, so the rules that answer only there -- the symbolic quadratic
            // denominator, a piecewise on its discriminant -- are consulted. Timofeev's
            // `1/(a^2 + b^2 cosh(x)^2)` is `4u/(4a^2 u^2 + b^2 (u^2 + 1)^2)`, answered at the top
            // and declined one level down.
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts) is not { } result)
                return null;
            return Finished(result);

            Entity? Finished(Entity result)
            {
                var rate = slopeUnit is null ? Number.Rational.Create(k)
                    : Functions.PartialFractions.Bare((Number.Rational.Create(k) * slopeUnit).Simplify());
                var answer = result.Substitute(u, MathS.Pow(commonBase, (shifted ? rate * x + shiftOfU : rate * x).InnerSimplified));
                if (logarithmOfTheBase != Number.Integer.One)
                    answer /= logarithmOfTheBase;
                return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
            }
        }

        /// <summary>
        /// <paramref name="expr"/> with every logarithm whose argument is a rational function
        /// of <paramref name="x"/> with a quotient nested inside it written over one bar in
        /// lowest terms, where that is smaller: <c>ln((1 + (u - 1)/(u + 1))/(1 - (u - 1)/(u + 1)))</c>
        /// is <c>ln(u)</c>.
        /// </summary>
        /// <remarks>
        /// The combining above reaches the quotient the integrand is and not one inside a
        /// function, and the simplifier combines nothing
        /// (https://github.com/asc-community/AngouriMath/issues/1239). <c>atanh(tanh(a + b x))</c>
        /// arrives as half that logarithm of <c>tanh</c> written in <c>e^(2(a + b x))</c>, and
        /// under <c>u</c> the substitution search compared its candidates against the nested
        /// spelling and never saw the <c>u</c> it is: <c>1/sqrt(atanh(tanh(a + b x)))</c> was
        /// answered before the substitution took a symbolic slope and not after.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity WithLogarithmArgumentsOverOneBar(Entity expr, Entity.Variable x)
            => expr.Replace(node =>
            {
                if (node is not Logf(var logBase, var argument) || logBase != MathS.e || !argument.ContainsNode(x) || !IsARationalFunction(argument, x)
                    || !argument.Nodes.Any(inner => inner is Divf && inner != argument))
                    return node;
                var (above, below) = Functions.SingleQuotient.Of(argument);
                var over = below == Number.Integer.One ? above.InnerSimplified
                    : Functions.PolynomialGcd.TryCancel(above.InnerSimplified, below.InnerSimplified, out var cancelled)
                        ? Functions.PartialFractions.Bare(cancelled).InnerSimplified
                        : (above / below).InnerSimplified;
                if (over.Complexity >= argument.Complexity)
                    return node;
                // Small by now, and `2u/2` is what the cancellation leaves of `(2u/(u + 1))/(2/(u + 1))`.
                over = Functions.PartialFractions.Bare(over.Simplify());
                return MathS.Ln(over);
            });

        /// <summary>
        /// A product with a whole negative power of a polynomial in <paramref name="x"/> of
        /// two or more terms among its factors, with every such power written below the bar
        /// and asked again as a question of its own: <c>u^2 (a u^2 + b)^(-3)</c> as
        /// <c>u^2/(a u^2 + b)^3</c>. The gathering of powers on the way into the chain writes
        /// <c>u^3/((a u^2 + b)^3 u)</c> -- the exponential substitution's quotient for Rubi's
        /// <c>1/(b/f^x + a f^x)^3</c> -- in the first spelling, a product with a power in it,
        /// which no rational rule reads, where the second is a quotient every one of them
        /// reads; the symbolic quadratic was declined for it. A power of the variable alone
        /// is left as it is, since that spelling is read, and <see cref="SolveAsPolynomialTerm"/>
        /// writes <c>1/x^n</c> back into it; and a lone power, <c>(a u^2 + b)^(-3)</c>, is the
        /// closed rules' as written. Where the quotient was the question one level up -- the
        /// constant-over-a-power branch of <see cref="SolveAsPolynomialTerm"/> asks the power
        /// -- the cycle guard declines it and the chain goes on. A rational function of
        /// <paramref name="x"/> only: the rewrite is another pass through the chain, and for
        /// anything else it was a search that found nothing the spelling had hidden.
        /// </summary>
        internal static Entity? SolveWithPolynomialPowersBelowTheBar(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not (Mulf or Divf) || !IsARationalFunction(expr, x))
                return null;
            var rewritten = WithPolynomialPowersBelowTheBar(expr, x);
            return rewritten == expr ? null : Integration.ComputeAsAQuestionOfItsOwn(rewritten, x, integrateByParts);
        }

        /// <summary>
        /// Powers of two linears beside a power of <c>A + B ln(K (L1/L2)^n)</c> in the same
        /// two linears, by the substitution <c>t = L1/L2</c>: with <c>L1 = a + b x</c> and
        /// <c>L2 = c + d x</c>, <c>L1 = D t/(b - d t)</c>, <c>L2 = D/(b - d t)</c> and
        /// <c>dx = D dt/(b - d t)^2</c> for <c>D = b c - a d</c>, so the integrand is a power
        /// of <c>t</c> times a power of <c>b - d t</c> times a power of <c>A + B ln(K t^n)</c>,
        /// which the rule above answers as a rational function beside a logarithm of
        /// <c>t</c>. Rubi's <c>(f + g x)^m (h + i x)^q (A + B ln(e ((a + b x)/(c + d x))^n))^p</c>
        /// with <c>f + g x</c> and <c>h + i x</c> proportional to the log's linears, which
        /// the rule above takes step by step and the substitution search spent its budget on:
        /// <c>(A + B ln(e (a + b x)/(c + d x)))/((a g + b g x)^2 (c j + d j x)^2)</c> is
        /// <c>(A + B ln(e t))(b - d t)^2/(g^2 j^2 D^3 t^2)</c>, which answers at once. The
        /// exponents may be symbols; <c>(g L1)^m</c> is taken as <c>g^m L1^m</c> and
        /// <c>K L1^n/L2^n</c> as <c>K t^n</c>, the generic case, and the answer is checked
        /// against the integrand at sampled points before it is given.
        /// </summary>
        internal static Entity? SolveByTheQuotientOfTheLogarithmsLinears(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            expr = WithNegativePowersOfProductsApart(expr);
            // The logarithm's argument: a product of constants and powers of two linears with
            // opposite exponents.
            Entity? logarithm = null;
            foreach (var node in expr.Nodes)
                if (node is Logf(var @base, var antilogarithm) && @base == MathS.e && antilogarithm.ContainsNode(x))
                {
                    if (logarithm is not null && logarithm != antilogarithm)
                        return null;
                    logarithm = antilogarithm;
                }
            if (logarithm is null)
                return null;
            var leaves = new List<(Entity Base, Entity Power)>();
            GatherPowers(logarithm, Number.Integer.One);
            Entity constant = Number.Integer.One;
            (Entity Slope, Entity Offset, Entity Linear)? first = null, second = null;
            Entity firstPower = Number.Integer.Zero, secondPower = Number.Integer.Zero;
            foreach (var (leaf, power) in leaves)
            {
                if (!leaf.ContainsNode(x))
                {
                    constant *= MathS.Pow(leaf, power);
                    continue;
                }
                if (!TryReadLinear(leaf, out var slope, out var offset))
                    return null;
                if (first is null)
                {
                    first = (slope, offset, leaf);
                    firstPower = power;
                }
                else if (ProportionalTo(slope, offset, first.Value) is { } ratio)
                {
                    constant *= MathS.Pow(ratio, power);
                    firstPower += power;
                }
                else if (second is null)
                {
                    second = (slope, offset, leaf);
                    secondPower = power;
                }
                else if (ProportionalTo(slope, offset, second.Value) is { } secondRatio)
                {
                    constant *= MathS.Pow(secondRatio, power);
                    secondPower += power;
                }
                else
                    return null;
            }
            if (first is not { } l1 || second is not { } l2)
                return null;
            var exponent = firstPower.InnerSimplified;
            if (exponent.Evaled is Number.Complex { IsZero: true } || !AreEqualAsPolynomials(exponent, (-secondPower).InnerSimplified))
                return null;
            var (a, b, c, d) = (l1.Offset, l1.Slope, l2.Offset, l2.Slope);
            var determinant = (b * c - a * d).InnerSimplified;
            if (determinant.Evaled is Number.Complex { IsZero: true } || AreProportionalAtSampledPoints(l1.Linear, l2.Linear, x))
                return null;

            // Every other factor holding x is a power of a linear proportional to one of the
            // two, or the logarithm's own factor. The powers of t and of b - d t are summed,
            // so that the integrand in t is one power of each over or under the bar: with
            // `(b - d t)^2` above and `(b - d t)^(-4)` below as they came, the rule for the
            // logarithm expanded its rational part to a page.
            var t = Variable.CreateUnique(expr, "u_quot");
            var denominatorInT = (b - d * t).InnerSimplified;
            Entity constantInFront = determinant;
            Entity powerOfT = Number.Integer.Zero;
            Entity powerOfDenominator = Number.Integer.Create(-2);   // dx = D dt/(b - d t)^2
            Entity? logarithmsFactor = null;
            // A polynomial beside the logarithm is by parts in x as it stands, one closed
            // step; in t it is a power of b - d t below the bar, which is the slower way.
            var aPolynomialBesideTheLogarithm = true;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constantInFront = underneath ? constantInFront / factor : constantInFront * factor;
                    continue;
                }
                var (@base, power) = factor is Powf(var pb, var pp) && !pp.ContainsNode(x) ? (pb, pp) : (factor, (Entity)Number.Integer.One);
                if (underneath)
                    power = (-power).InnerSimplified;
                if (!@base.ContainsNode(logarithm) && power.Evaled is not Number.Integer { EInteger.Sign: >= 0 })
                    aPolynomialBesideTheLogarithm = false;
                if (@base.ContainsNode(logarithm))
                {
                    if (logarithmsFactor is not null)
                        return null;
                    var inT = @base.Replace(node => node == logarithm ? constant * MathS.Pow(t, exponent) : node);
                    if (inT.ContainsNode(x))
                        return null;
                    logarithmsFactor = MathS.Pow(inT, power);
                    continue;
                }
                if (!TryReadLinear(@base, out var slope, out var offset))
                    return null;
                if (ProportionalTo(slope, offset, l1) is { } ratio1)
                {
                    constantInFront *= MathS.Pow(ratio1 * determinant, power);
                    powerOfT += power;
                    powerOfDenominator -= power;
                }
                else if (ProportionalTo(slope, offset, l2) is { } ratio2)
                {
                    constantInFront *= MathS.Pow(ratio2 * determinant, power);
                    powerOfDenominator -= power;
                }
                else
                    return null;
            }
            if (logarithmsFactor is null || aPolynomialBesideTheLogarithm)
                return null;
            Entity above = constantInFront * logarithmsFactor, below = Number.Integer.One;
            foreach (var (@base, power) in new[] { (t, Functions.PartialFractions.Bare(powerOfT.Simplify())), (denominatorInT, Functions.PartialFractions.Bare(powerOfDenominator.Simplify())) })
            {
                if (power.Evaled is Number.Complex { IsZero: true })
                    continue;
                if (power.Evaled is Number.Real { IsNegative: true })
                    below *= MathS.Pow(@base, (-power).InnerSimplified);
                else
                    above *= MathS.Pow(@base, power);
            }
            var rewritten = (below == Number.Integer.One ? above : above / below).InnerSimplified;
            if (rewritten.ContainsNode(x))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(rewritten, t, integrateByParts) is not { } integrated)
                return null;
            var answer = integrated.Substitute(t, l1.Linear / l2.Linear);
            if (answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            // The generic case holds where the linears' powers split as written. Past that it can
            // fail where the integrand is still real, a product of two imaginary factors. The
            // sampled check skips a point where the derivative has no value, and there the
            // derivative is a fractional power of a negative number, which the interval and decimal
            // evaluations decline. So it compared only where the generic case holds:
            // `e^artanh(a x) sqrt(c - a c x)`, as `e^(ln((1 + a x)/(1 - a x))/2)`, passed it and was
            // wrong by its sign past `a x = 1`. A point where the integrand is real and the
            // derivative is not is a difference too.
            // https://github.com/asc-community/AngouriMath/issues/1655
            var derivative = answer.Differentiate(x);
            if (!Functions.PartialFractions.HoldsAtSampledPoints(derivative, expr, x)
                || Functions.PartialFractions.DiffersWhereReal(derivative, expr, x))
                return null;
            return answer;

            void GatherPowers(Entity node, Entity power)
            {
                switch (node)
                {
                    case Mulf(var left, var right):
                        GatherPowers(left, power);
                        GatherPowers(right, power);
                        break;
                    case Divf(var numerator, var denominator):
                        GatherPowers(numerator, power);
                        GatherPowers(denominator, (-power).InnerSimplified);
                        break;
                    case Powf(var @base, var exponentOfPower) when !exponentOfPower.ContainsNode(x):
                        GatherPowers(@base, (power * exponentOfPower).InnerSimplified);
                        break;
                    default:
                        leaves.Add((node, power));
                        break;
                }
            }

            // Linear in x in whatever spelling the chain gave it: `a g^0 b^(-1) + x`, for
            // `(a g + b g x)` made monic, is not read as a polynomial, and is read by its
            // derivative.
            bool TryReadLinear(Entity linear, out Entity slope, out Entity offset)
            {
                if (TreeAnalyzer.TryGetPolyLinear(linear, x, out var readSlope, out var readOffset) && readSlope is { } && readOffset is { })
                {
                    (slope, offset) = (readSlope, readOffset);
                    return !TreeAnalyzer.IsZero(slope);
                }
                // Only a rational spelling is read by its derivative: a leaf with a function
                // of x in it is not a linear however it simplifies, and simplifying it costs.
                if (!IsARationalFunction(linear, x))
                {
                    (slope, offset) = (Number.Integer.Zero, Number.Integer.Zero);
                    return false;
                }
                slope = Functions.PartialFractions.Bare(linear.Differentiate(x).Simplify());
                offset = Functions.PartialFractions.Bare((linear - slope * x).Simplify());
                return !slope.ContainsNode(x) && !offset.ContainsNode(x) && !TreeAnalyzer.IsZero(slope)
                    && slope.Evaled is not Number.Complex { IsZero: true };
            }

            // The constant `slope/other.Slope` where the linear is that multiple of the
            // other, else null: cross-multiplied, so that no symbol is divided by.
            Entity? ProportionalTo(Entity slope, Entity offset, (Entity Slope, Entity Offset, Entity Linear) other)
            {
                // Decided at sampled points, since the linear arrives in whatever spelling the
                // chain gave it -- `a g^0 b^(-1) + x` for `(a g + b g x)` made monic -- and
                // then the ratio read exactly.
                if (!AreEqualAsPolynomials((offset * other.Slope).InnerSimplified, (other.Offset * slope).InnerSimplified)
                    && !AreProportionalAtSampledPoints(slope * x + offset, other.Linear, x))
                    return null;
                var ratio = Functions.PartialFractions.Bare((slope / other.Slope).Simplify());
                return ratio.Nodes.Any(node => node == MathS.NaN) || ratio.ContainsNode(x) ? null : ratio;
            }

            // Equal as polynomials in their symbols, exactly.
            static bool AreEqualAsPolynomials(Entity left, Entity right)
            {
                if (left == right)
                    return true;
                var difference = Functions.PartialFractions.Bare((left - right).Simplify());
                if (difference.Evaled is Number.Complex { IsZero: true })
                    return true;
                var symbols = difference.Vars.ToList();
                if (symbols.Count == 0)
                    return false;
                var indices = new Dictionary<Variable, int>();
                foreach (var symbol in symbols)
                    indices[symbol] = indices.Count;
                return Functions.MultivariatePolynomial.TryParse(difference, indices) is { IsZero: true };
            }
        }

        /// <summary>
        /// A rational function of <paramref name="x"/> times a whole power of a factor whose
        /// derivative is rational -- <c>A + B ln(R)</c> or <c>A + B arctan(R)</c> with <c>R</c>
        /// rational in <paramref name="x"/> -- by parts with the power differentiated:
        /// <c>F^p Q = (F^p int Q)' - p F^(p-1) F' int Q</c>, and the remainder is a rational
        /// function times the next lower power, rational outright for the first. Rubi's
        /// <c>(f + g x)^m (A + B ln(e ((a + b x)/(c + d x))^n))^p</c> for whole <c>m</c> and
        /// <c>p</c>, of which <c>(f + g x)(A + B ln(e (a + b x)^2/(c + d x)^2))</c> and
        /// <c>(A + B ln(e (a + b x)/(c + d x)))/(f + g x)^5</c> were a substitution search past
        /// its budget on the symbols, simplifying the integrand over each candidate's
        /// derivative, before the same step of parts was reached below it.
        /// </summary>
        /// <remarks>
        /// The step is exact and closed: what is integrated is rational, what is left is
        /// asked as a question of its own with the power one lower, and the power is what
        /// the recursion decreases on. At any depth where the rational function holds
        /// <c>x</c>, since the step is closed and its own remainder is two levels down once
        /// a constant has been taken out in front; against a constant alone it is by parts
        /// against one, asked at the top or one below it like the rest of by parts.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveARationalFunctionTimesAPowerOfALogarithm(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // A whole negative power of a product is the product of the powers: the constant
            // over a product is handed on as `((a + b x)(c + d x)(A + B ln(...)))^(-1)`, one
            // factor with everything in it.
            expr = WithNegativePowersOfProductsApart(expr);
            Entity? differentiated = null;
            Entity writtenPower = Number.Integer.One;
            Entity rational = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x) || IsARationalFunction(factor, x))
                {
                    rational = underneath ? rational / factor : rational * factor;
                    continue;
                }
                if (differentiated is not null)
                    return null;
                var (@base, exponent) = factor is Powf(var b, var p) && !p.ContainsNode(x) ? (b, p) : (factor, Number.Integer.One);
                if (!@base.Nodes.Any(node => node is Logf or Arctanf or Arccotanf && node.ContainsNode(x)))
                    return null;
                differentiated = @base;
                writtenPower = underneath ? (-exponent).InnerSimplified : exponent;
            }
            if (differentiated is null)
                return null;
            // Against a constant alone this is by parts against one, which is asked at the
            // top or one below and not volunteered: offered at every depth, `ln(x)^2` was
            // answered inside a by-parts search that its decline used to cut short, and
            // Bronstein's `(x^2 + 2x ln x + ln^2 x + (1 + x) sqrt(x + ln x))/(x (x + ln x)^2)`
            // went from a second to twelve.
            if (!rational.ContainsNode(x) && !Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            // Differentiated with each logarithm of a product written as the sum of the
            // logarithms of its factors, the constant dropped: the derivative of
            // `ln(e (a + b x)^2/(c + d x)^2)` is then `2b/(a + b x) - 2d/(c + d x)`, where the
            // quotient rule on the argument as written gives a quotient of quartics that the
            // partial fractions below spend their budget on.
            // And term by term, each term of the sum differentiated on its own: simplified
            // whole, `b/(a + b x) - d/(c + d x)` is brought over one bar, and the pieces below
            // then hold a quadratic with symbols in it.
            var derivativeTerms = new List<Entity>();
            foreach (var term in TermsDistributed(WithLogarithmsOfProductsApart(differentiated, x)))
            {
                var termDerivative = Functions.PartialFractions.Bare(term.Differentiate(x).InnerSimplified);
                if (termDerivative == Number.Integer.Zero || termDerivative.Evaled is Number.Complex { IsZero: true })
                    continue;
                if (!IsARationalFunction(termDerivative, x))
                    return null;
                derivativeTerms.AddRange(TermsDistributed(termDerivative));
            }
            if (derivativeTerms.Count == 0)
                return null;
            // The rational function a constant multiple of the derivative: `F^p F'` for any
            // power, `F^(p + 1)/(p + 1)`, or `ln F` for the reciprocal. Rubi's
            // `(A + B ln(e (a + b x)^n/(c + d x)^n))/((a + b x)(c + d x))` is
            // `(A + B ln(...))^2/(2 B n (b c - a d))`, which the substitution search spent its
            // budget simplifying towards. Decided at sampled points, then the constant read
            // exactly and the answer differentiated back.
            Entity derivative = Number.Integer.Zero;
            foreach (var term in derivativeTerms)
                derivative += term;
            if (AreProportionalAtSampledPoints(rational, derivative, x))
            {
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(rational / derivative).InnerSimplified);
                if (TryReadTheRatioOfBrackets(above, below, x, out var ratio) && !ratio.ContainsNode(x))
                {
                    var nextPower = (writtenPower + 1).InnerSimplified;
                    var reciprocal = nextPower.Evaled is Number.Complex { IsZero: true };
                    // Checked with the plain logarithm, whose derivative evaluates at the
                    // points; given with the modulus where the codomain asks for it, as
                    // the table gives `ln|f|` for `f'/f`.
                    var primitive = reciprocal ? ratio * MathS.Ln(differentiated) : ratio * MathS.Pow(differentiated, nextPower) / nextPower;
                    if (Functions.PartialFractions.HoldsAtSampledPoints(primitive.Differentiate(x), expr, x))
                        return (reciprocal ? ratio * IntegralPatterns.AntiderivativeLog(differentiated) : primitive).InnerSimplified;
                }
            }
            if (writtenPower is not Number.Integer { EInteger.Sign: > 0 } wholePower || wholePower.EInteger.CompareTo(EInteger.FromInt32(8)) > 0)
                return null;
            var power = wholePower.EInteger.ToInt32Checked();
            if (Integration.ComputeIndefiniteIntegral(rational, x, integrateByParts: false) is not { } integralOfTheRational)
                return null;
            integralOfTheRational = Functions.PartialFractions.Bare(integralOfTheRational.InnerSimplified);
            if (!IsARationalFunction(integralOfTheRational, x))
                return null;   // a logarithm from the rational part: the remainder would hold two
            // The antiderivative of the rational function is fixed up to a constant, and the
            // constant is chosen so that it vanishes at a pole of the derivative, which the
            // remainder then does not have: for `(A + B ln((a + b x)/(c + d x)))^2/(c + d x)^2`
            // the antiderivative of `1/(c + d x)^2` is `(a + b x)/((b c - a d)(c + d x))` and
            // not `-1/(d (c + d x))`, and the remainder is `(A + B ln(...))/(c + d x)^2`, one
            // step more of the same, where with the other constant it held
            // `(A + B ln(...))/(a + b x)`, which is a dilogarithm on its own. Rubi's constant.
            integralOfTheRational = MatchedToAPoleOf(integralOfTheRational, derivativeTerms, x);
            // Term by term over the sum the logarithmic derivative is, each term a rational
            // function over one factor: brought over one bar, `x (b c - a d)/((a + b x)(c + d x))`
            // was a quadratic below the bar with symbols in it, answered as a piecewise on
            // its discriminant, where `b x/(a + b x)` and `d x/(c + d x)` are each a line.
            // For a higher power the derivative stays whole: the pole the antiderivative was
            // matched to cancels only against the derivative as one fraction,
            // `n (b c - a d)/((a + b x)(c + d x))` times `(a + b x)/((b c - a d)(c + d x))`, and
            // the pieces of the split each keep a logarithm of their own.
            // Each piece as its partial fractions over the written linear factors, whole part
            // apart: the pole the antiderivative was matched to has a zero residue and drops
            // out, and every piece is a constant over one power of one factor, which is a
            // line to integrate beside the power of the logarithm. Combined and cancelled
            // instead, the product kept the pole's factor in the numerator, `-d^2 (a + b x)`
            // over `(a + b x)(c + d x)^2`, and sent the piece down the substitution search.
            // For a higher power the fractions of all the terms are collected first, like
            // over like: the `1/(c + d x)` fractions of the two terms cancel between them,
            // and each on its own beside the power of the logarithm is a dilogarithm.
            var remainders = new List<Entity>();
            if (power == 1)
                foreach (var term in derivativeTerms)
                    remainders.Add(AsPartialFractions(term * integralOfTheRational, x));
            else
            {
                // Keyed by the part of the denominator holding x; the constants go with the
                // coefficient, which is then a quotient of polynomials in the symbols and is
                // put in lowest terms -- `d^10 (a d - b c)^3` over `d^8 (a d - b c)^2` is
                // `d^2 (a d - b c)` -- since the pieces come from the derivatives at the roots
                // with nothing cancelled.
                var collected = new List<(Entity Below, Entity Above)>();
                foreach (var term in derivativeTerms)
                    foreach (var fraction in TermsDistributed(AsPartialFractions(term * integralOfTheRational, x)))
                    {
                        var (fractionAbove, fractionBelow) = Functions.SingleQuotient.Of(fraction);
                        Entity holdingX = Number.Integer.One, constantBelow = Number.Integer.One;
                        foreach (var factor in Mulf.LinearChildren(fractionBelow))
                            if (factor.ContainsNode(x))
                                holdingX = holdingX == Number.Integer.One ? factor : holdingX * factor;
                            else
                                constantBelow = constantBelow == Number.Integer.One ? factor : constantBelow * factor;
                        var coefficientPart = constantBelow == Number.Integer.One ? fractionAbove : fractionAbove / constantBelow;
                        var at = collected.FindIndex(pair => pair.Below == holdingX);
                        if (at >= 0)
                            collected[at] = (holdingX, collected[at].Above + coefficientPart);
                        else
                            collected.Add((holdingX, coefficientPart));
                    }
                foreach (var (fractionBelow, fractionAbove) in collected)
                {
                    var coefficient = Functions.PartialFractions.InLowestTermsOverTheSymbols(fractionAbove);
                    if (coefficient == Number.Integer.Zero || coefficient.Evaled is Number.Complex { IsZero: true })
                        continue;
                    var piece = fractionBelow == Number.Integer.One ? coefficient : coefficient / fractionBelow;
                    remainders.Add(Number.Integer.Create(power) * MathS.Pow(differentiated, power - 1) * piece);
                }
            }
            Entity? integratedRemainder = null;
            foreach (var remainder in remainders)
            {
                if (Integration.ComputeAsAQuestionOfItsOwn(remainder, x, integrateByParts) is not { } integratedPiece)
                    return null;
                integratedRemainder = integratedRemainder is null ? integratedPiece : integratedRemainder + integratedPiece;
            }
            if (integratedRemainder is null)
                return null;
            var answer = MathS.Pow(differentiated, power) * integralOfTheRational - integratedRemainder;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// <paramref name="expr"/> with every whole negative power of a product among its
        /// factors written as the product of the powers: <c>(X Y)^(-2)</c> is
        /// <c>X^(-2) Y^(-2)</c>.
        /// </summary>
        private static Entity WithNegativePowersOfProductsApart(Entity expr)
        {
            static Entity Distributed(Entity inner, Number.Integer exponent)
            {
                var (above, below) = Functions.SingleQuotient.Of(inner);
                Entity result = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(above))
                    result = result == Number.Integer.One ? MathS.Pow(factor, exponent) : result * MathS.Pow(factor, exponent);
                if (below != Number.Integer.One)
                    foreach (var factor in Mulf.LinearChildren(below))
                        result = result * MathS.Pow(factor, Number.Integer.Create(-exponent.EInteger));
                return result;
            }
            Entity Apart(Entity node) => node switch
            {
                Mulf(var left, var right) => Apart(left) * Apart(right),
                Divf(var above, var below) => Apart(above) / Apart(below),
                Powf(var inner, Number.Integer { EInteger.Sign: < 0 } exponent) when inner is Mulf or Divf => Distributed(inner, exponent),
                _ => node,
            };
            return Apart(expr);
        }

        /// <summary>
        /// <paramref name="product"/> brought over one bar and written as its whole part plus
        /// its partial fractions over the written linear factors of the denominator, the
        /// symbolic ones by the derivatives at the roots; <paramref name="product"/> over one
        /// bar as it came where the denominator is not such a product.
        /// </summary>
        private static Entity AsPartialFractions(Entity product, Entity.Variable x)
        {
            var combined = Functions.SingleQuotient.Combine(product).InnerSimplified;
            var (above, below) = Functions.SingleQuotient.Of(combined);
            if (below == Number.Integer.One || !below.ContainsNode(x))
                return combined;
            above = Functions.PartialFractions.Bare(above.Expand().InnerSimplified);
            if (!TreeAnalyzer.TryGetPolynomial(above, x, out var aboveRead) || !TreeAnalyzer.TryGetPolynomial(below, x, out var belowRead)
                || aboveRead.Count == 0 || belowRead.Count == 0)
                return combined;
            Entity whole = Number.Integer.Zero;
            var proper = above;
            if (aboveRead.Keys.Max()!.CompareTo(belowRead.Keys.Max()!) >= 0)
            {
                // The division hands back the remainder over the divisor already, as the
                // proper fraction it is.
                if (TreeAnalyzer.PolynomialLongDivision(above, below, genericCase: true, inTermsOf: x) is not var (divided, remainder))
                    return combined;
                whole = Functions.PartialFractions.Bare(divided.InnerSimplified);
                if (whole.Evaled is Number.Complex { IsZero: true })
                    whole = Number.Integer.Zero;
                (proper, below) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(remainder.InnerSimplified));
            }
            if (proper == Number.Integer.Zero || proper.Evaled is Number.Complex { IsZero: true })
                return whole;
            Entity fractions;
            if (below == Number.Integer.One)
                fractions = proper;
            else if (Functions.PartialFractions.TrySplitOverWrittenFactors(proper, below, x, out var decomposition))
            {
                // The decomposition comes as its sum over the denominator's constant; each
                // fraction over the constant on its own, so that the terms are read apart.
                fractions = decomposition is Divf(var sum, var constant) && sum is Sumf or Minusf
                    ? Sumf.LinearChildren(sum).Select(fraction => fraction / constant).Aggregate((so, next) => so + next)
                    : decomposition;
            }
            else
                fractions = proper / below;
            return whole == Number.Integer.Zero ? fractions : whole + fractions;
        }

        /// <summary>
        /// <paramref name="antiderivative"/> plus the constant that makes it vanish at a root
        /// of a linear factor below the bar of one of <paramref name="derivativeTerms"/>, the
        /// first such root at which it is finite; <paramref name="antiderivative"/> itself
        /// where there is none.
        /// </summary>
        private static Entity MatchedToAPoleOf(Entity antiderivative, List<Entity> derivativeTerms, Entity.Variable x)
        {
            var (_, ownDenominator) = Functions.SingleQuotient.Of(antiderivative);
            foreach (var term in derivativeTerms)
            {
                var (_, below) = Functions.SingleQuotient.Of(term);
                foreach (var factor in Mulf.LinearChildren(below))
                {
                    var linear = factor is Powf(var repeatedBase, Number.Integer) ? repeatedBase : factor;
                    if (!linear.ContainsNode(x))
                        continue;
                    if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out var offset) || slope.Evaled is Number.Complex { IsZero: true })
                    {
                        // A factor of higher degree, for a polynomial antiderivative: the
                        // constant is what the division leaves, so that the factor divides
                        // the antiderivative. Against `ln(1 + x^2)` the antiderivative of `x`
                        // is `(1 + x^2)/2`, and the remainder is then a polynomial.
                        if (!ownDenominator.ContainsNode(x) && TreeAnalyzer.TryGetPolynomial(linear, x, out _)
                            && TreeAnalyzer.PolynomialLongDivision(antiderivative, linear, genericCase: true, inTermsOf: x) is var (_, left)
                            && Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(left.InnerSimplified)) is var (leftAbove, _)
                            && !leftAbove.ContainsNode(x))
                        {
                            var constant = Functions.PartialFractions.Bare(leftAbove.InnerSimplified);
                            if (!constant.ContainsNode(x) && !constant.Nodes.Any(node => node == MathS.NaN)
                                && constant != Number.Integer.Zero && constant.Evaled is not Number.Complex { IsZero: true })
                                return antiderivative - constant;
                        }
                        continue;
                    }
                    var root = Functions.PartialFractions.Bare((-offset / slope).InnerSimplified);
                    // A pole the antiderivative shares is not one it can vanish at.
                    var ownValueBelow = Functions.PartialFractions.Bare(ownDenominator.Substitute(x, root).Simplify());
                    if (ownValueBelow.Evaled is Number.Complex { IsZero: true } || ownValueBelow == Number.Integer.Zero)
                        continue;
                    var value = Functions.PartialFractions.Bare(antiderivative.Substitute(x, root).Simplify());
                    if (value.Nodes.Any(node => node == MathS.NaN) || value.ContainsNode(x))
                        continue;
                    return value == Number.Integer.Zero || value.Evaled is Number.Complex { IsZero: true }
                        ? antiderivative
                        : antiderivative - value;
                }
            }
            return antiderivative;
        }

        /// <summary>
        /// The terms of <paramref name="expr"/> with every product distributed over the sums
        /// among its factors: <c>B (ln(a + b x) - ln(c + d x))</c> is two terms.
        /// </summary>
        private static List<Entity> TermsDistributed(Entity expr)
        {
            if (expr is Sumf or Minusf)
                return Sumf.LinearChildren(expr).SelectMany(TermsDistributed).ToList();
            if (expr is not Mulf)
                return new List<Entity> { expr };
            var terms = new List<Entity> { Number.Integer.One };
            foreach (var factor in Mulf.LinearChildren(expr))
            {
                var factorTerms = TermsDistributed(factor);
                var next = new List<Entity>();
                foreach (var so in terms)
                    foreach (var part in factorTerms)
                        next.Add(so == Number.Integer.One ? part : so * part);
                terms = next;
            }
            return terms;
        }

        /// <summary>
        /// <paramref name="expr"/> with every natural logarithm of a product of powers written
        /// as the sum of the logarithms of the factors holding <paramref name="x"/>, each
        /// times its power, and the constant factors dropped. Equal to the original up to a
        /// constant on each interval where both are defined, which is all a derivative sees.
        /// </summary>
        private static Entity WithLogarithmsOfProductsApart(Entity expr, Entity.Variable x)
            => expr.Replace(node =>
            {
                if (node is not Logf(var @base, var argument) || @base != MathS.e || !argument.ContainsNode(x) || argument is not (Mulf or Divf or Powf))
                    return node;
                Entity sum = Number.Integer.Zero;
                foreach (var (factor, underneath) in FactorsOfTheIntegrand(argument))
                {
                    if (!factor.ContainsNode(x))
                        continue;
                    var (inner, power) = factor is Powf(var b, var p) && !p.ContainsNode(x) ? (b, p) : (factor, (Entity)Number.Integer.One);
                    var term = power == Number.Integer.One ? MathS.Ln(inner) : power * MathS.Ln(inner);
                    sum = underneath ? sum - term : sum + term;
                }
                return sum;
            });

        /// <summary>
        /// A partial-fraction decomposition, a sum over a constant, integrated one term at a
        /// time as each is written, with the constant on the result.
        /// </summary>
        /// <remarks>
        /// Handed to the chain whole, the sum is split as written only while every term is
        /// small (<see cref="LargestTermTakenAsWritten"/>), and past that by the expanding
        /// gather, which combines a term's constant with its quotient: `D^(-1) (P + Q x)/(1 + x^2)`
        /// with `P`, `Q` polynomials in the symbols became `(P + Q x)/(D + D x^2)`, a quadratic
        /// with symbols in every coefficient, and was integrated as a piecewise on the sign of
        /// its discriminant. A decomposition's terms are already the shapes the rules read.
        /// </remarks>
        private static Entity? IntegratedTermByTerm(Entity decomposition, Entity.Variable x, bool integrateByParts)
        {
            var (terms, over) = decomposition is Divf(var sum, var constant) && !constant.ContainsNode(x)
                ? (sum, constant) : (decomposition, Number.Integer.One as Entity);
            Entity total = Number.Integer.Zero;
            foreach (var term in Sumf.LinearChildren(terms))
            {
                if (term.Evaled is Number.Complex { IsZero: true })
                    continue;
                if (Integration.ComputeIndefiniteIntegral(term, x, integrateByParts) is not { } integrated)
                    return null;
                total += integrated;
            }
            return over == Number.Integer.One ? total : total / over;
        }

        /// <summary>
        /// Whether <paramref name="denominator"/> is written as a product of two or more
        /// distinct factors in <paramref name="x"/>, each linear or quadratic and to a whole
        /// power, with a symbol in a coefficient somewhere -- and at least one of them linear,
        /// unless <paramref name="aLinearAmongThem"/> is false.
        /// </summary>
        /// <remarks>
        /// A quadratic beside the linears is allowed since the decomposition takes the linear
        /// blocks by their Taylor coefficients and the quadratic's numerator in the ring
        /// modulo the quadratic; with the gate asking for linears only,
        /// <c>u^4 (A + B u)/((a + b u)^4 (1 + u^2))</c> -- every rational function of the
        /// tangent with a power of a linear in it -- went to the Hermite reduction below,
        /// which answered in <c>a^63 b^10</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// The partial fractions ask it without a linear where a symbolic factor is repeated:
        /// quadratics alone are split by their residues just the same, and the half-angle
        /// tangent's <c>2 (1 - t^2)^6/((1 + t^2)^5 (a t^2 + 2 b t + a)^2)</c>, which is Rubi's
        /// <c>cos(x)^6/(a + b sin(x))^2</c>, has none. Where only a rational factor is repeated
        /// the Hermite reduction answers shorter: <c>sin(x)^2/(a + b cos(x))</c> by residues was
        /// 1864 characters for its 1109. The substitution search asks it with one, declining
        /// only what the split surely takes: over two symbolic quadratics <c>u = x^2</c> is often
        /// the shorter answer.
        /// </remarks>
        private static bool IsAProductOfSymbolicLinearFactors(Entity denominator, Entity.Variable x, bool aLinearAmongThem = true)
        {
            var linears = 0;
            var quadratics = 0;
            var symbolic = false;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                // A constant factor is not a coefficient: `a u (1 + u^2)^6 (1 + 2 u + u^2)`,
                // which taking the content out of `a (1 + u^2) + 2 a u` leaves, is a rational
                // denominator with `a` in front, and the refactoring over the rationals and
                // the Hermite reduction read it -- `(1 + u)^2` among them -- where the split
                // took it as symbolic and answered in twice the length.
                if (!factor.ContainsNode(x))
                    continue;
                var @base = factor is Powf(var b, Number.Integer { EInteger.Sign: > 0 }) ? b : factor;
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var read) || read.Count == 0
                    || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                    return false;
                if (read.Keys.Max()!.Equals(EInteger.One))
                    linears++;
                else if (read.Keys.Max()!.Equals(EInteger.FromInt32(2)))
                    quadratics++;
                else
                    return false;
                symbolic |= read.Values.Any(coefficient => coefficient.Vars.Any());
            }
            return (linears >= 1 || !aLinearAmongThem) && linears + quadratics >= 2 && symbolic;
        }

        /// <summary>
        /// Whether a written factor of <paramref name="denominator"/> with a symbol in it stands
        /// to a whole power of two or more: where the Hermite reduction's one solve takes those
        /// symbols through every row, and a split by residues does not.
        /// </summary>
        private static bool HoldsARepeatedSymbolicFactor(Entity denominator, Entity.Variable x)
            => Mulf.LinearChildren(denominator).Any(factor => factor is Powf(var @base, Number.Integer { EInteger.Sign: > 0 } power)
                && power != Number.Integer.One && @base.ContainsNode(x) && @base.Vars.Any(v => v != x));

        /// <summary>
        /// Whether both read as polynomials in <paramref name="x"/> with the numerator's
        /// degree below the denominator's; false where either does not read.
        /// </summary>
        private static bool IsProperByDegree(Entity numerator, Entity denominator, Entity.Variable x)
            => TreeAnalyzer.TryGetPolynomial(numerator, x, out var above) && above.Count > 0
               && TreeAnalyzer.TryGetPolynomial(denominator, x, out var below) && below.Count > 0
               && above.Keys.Max()!.CompareTo(below.Keys.Max()!) < 0;

        /// <summary>Whether every node of <paramref name="expr"/> holding <paramref name="x"/> is a sum, a product, a quotient or a whole power.</summary>
        private static bool IsARationalFunction(Entity expr, Entity.Variable x)
            => expr.Nodes.All(node => !node.ContainsNode(x) || node is Variable or Sumf or Minusf or Mulf or Divf || node is Powf(_, Number.Integer));

        /// <summary>
        /// <paramref name="expr"/> with every whole negative power of a polynomial in
        /// <paramref name="x"/> of two or more terms among its factors written below the bar,
        /// or <paramref name="expr"/> itself where there is none.
        /// </summary>
        private static Entity WithPolynomialPowersBelowTheBar(Entity expr, Entity.Variable x)
        {
            var (above, below) = expr is Divf(var over, var under) ? (over, under) : (expr, (Entity)Number.Integer.One);
            Entity kept = Number.Integer.One;
            var moved = false;
            foreach (var factor in Mulf.LinearChildren(above))
            {
                if (factor is Powf(var @base, Number.Integer { EInteger.Sign: < 0 } power) && @base.ContainsNode(x)
                    && TreeAnalyzer.TryGetPolynomial(@base, x, out var read) && read.Count >= 2)
                {
                    below = below == Number.Integer.One ? MathS.Pow(@base, -power) : below * MathS.Pow(@base, -power);
                    moved = true;
                }
                else
                    kept = kept == Number.Integer.One ? factor : kept * factor;
            }
            return moved ? kept / below : expr;
        }

        /// <summary>
        /// <paramref name="expr"/> with every exponential of <paramref name="x"/> whose base is a
        /// positive rational written in one base, where the bases are whole powers of one:
        /// <c>4^x</c> beside <c>2^x</c> is <c>2^(2x)</c>, and <c>2^x</c> beside <c>sqrt(2)^x</c>
        /// is <c>sqrt(2)^(2x)</c>. The common base is the smallest of them above one or a whole
        /// root of it; where no such base exists, or the bases are not all rationals,
        /// <paramref name="expr"/> as it came.
        /// </summary>
        private static Entity WithNumericBasesUnified(Entity expr, Entity.Variable x)
        {
            var bases = new List<ERational>();
            foreach (var node in expr.Nodes)
                if (node is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x) && exponent is not Number)
                {
                    if (@base.Evaled is not Number.Rational rational || rational.ERational.Sign <= 0 || rational.ERational.Equals(ERational.One))
                        return expr;
                    var written = rational.ERational.ToLowestTerms();
                    if (!bases.Contains(written))
                        bases.Add(written);
                }
            if (bases.Count < 2)
                return expr;
            // Every base above one, so that the powers are whole and positive where they exist.
            var aboveOne = bases.Select(b => b.CompareTo(ERational.One) < 0 ? ERational.One.Divide(b) : b).ToList();
            var smallest = aboveOne.OrderBy(b => b).First();
            Entity? common = null;
            var powers = new Dictionary<ERational, int>();
            for (var root = 1; root <= 4 && common is null; root++)
            {
                var candidate = MathS.Pow(Number.Rational.Create(smallest), Number.Rational.Create(1, root)).Evaled;
                if (candidate is not Number.Rational candidateRational)
                    continue;
                powers.Clear();
                var all = true;
                foreach (var @base in bases)
                {
                    var power = 0;
                    Entity accumulated = Number.Integer.One;
                    while (power < 64 && ((Number.Rational)accumulated).ERational.CompareTo(@base.CompareTo(ERational.One) < 0 ? ERational.One.Divide(@base) : @base) < 0)
                    {
                        accumulated = (accumulated * candidateRational).Evaled;
                        power++;
                    }
                    var matches = ((Number.Rational)accumulated).ERational.Equals(@base.CompareTo(ERational.One) < 0 ? ERational.One.Divide(@base) : @base);
                    if (!matches)
                    {
                        all = false;
                        break;
                    }
                    powers[@base] = @base.CompareTo(ERational.One) < 0 ? -power : power;
                }
                if (all)
                    common = candidateRational;
            }
            if (common is null)
                return expr;
            return expr.Replace(node =>
                node is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x) && exponent is not Number
                && @base.Evaled is Number.Rational rational && powers.TryGetValue(rational.ERational.ToLowestTerms(), out var power)
                    ? MathS.Pow(common, power == 1 ? exponent : (Number.Integer.Create(power) * exponent).InnerSimplified)
                    : node);
        }

        /// <summary>
        /// Whether <paramref name="exponent"/> is written as an even whole number times
        /// something, a minus sign in front allowed: <c>2 (c + d x)</c>, <c>-(2 x)</c>.
        /// </summary>
        private static bool WrittenWithAnEvenFactor(Entity exponent)
        {
            while (exponent is Mulf(Number.Integer { EInteger.IsEven: false } sign, var rest) && sign.EInteger.Abs().Equals(EInteger.One))
                exponent = rest;
            return exponent is Mulf(Number.Integer { EInteger.IsEven: true } factor, _) && !factor.EInteger.IsZero;
        }

        /// <summary>
        /// Every <c>x</c> of <paramref name="expr"/> in an exponential <c>e^(k y)</c> with
        /// <c>k</c> a whole number and <c>y</c> one linear form <c>c + d x</c> shared by all of
        /// them -- <c>coth(c + d x)</c> is written with <c>e^(2c + 2d x)</c> -- and in nothing
        /// else: each exponential node with its <c>k</c>, the form <c>y</c> scaled so that the
        /// <c>k</c> are whole and coprime -- or, with <paramref name="unitX"/> and a whole
        /// number for the slope, <c>y</c> as <c>x</c> itself plus the offset over the slope
        /// and each <c>k</c> the slope as written -- and <c>dx/dy</c>; <see langword="false"/>
        /// where the exponentials are of two forms, or an exponent is not linear in <c>x</c>.
        /// </summary>
        private static bool TryGatherExponentialsOfOneLinearForm(Entity expr, Entity.Variable x, bool unitX,
            out Dictionary<Entity, EInteger> exponentials, [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out Entity? y, [System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out Entity? dxOverDy)
        {
            exponentials = new Dictionary<Entity, EInteger>();
            y = null;
            dxOverDy = null;
            var multiples = new List<(Entity Node, Number.Rational Multiple)>();
            Entity? slopeOfY = null;
            Entity? offsetOfY = null;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var @base, var exponent) || !exponent.ContainsNode(x))
                    continue;
                if (@base != MathS.e || !TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out var offset) || TreeAnalyzer.IsZero(slope))
                    return false;
                if (slopeOfY is null)
                {
                    (slopeOfY, offsetOfY) = (slope, offset);
                    multiples.Add((node, Number.Integer.One));
                    continue;
                }
                if (multiples.Any(known => known.Node == node))
                    continue;
                // The same linear form, to a rational multiple: the slopes' ratio is a number
                // and the offsets stand in the same ratio.
                // Bare: `-d/d` simplifies to `-1 provided not d = 0`, and the generic case is
                // what every neighbouring rule answers.
                var ratio = (slope / slopeOfY).InnerSimplified;
                var multiple = ratio.Evaled as Number.Rational ?? Functions.PartialFractions.Bare(ratio.Simplify()).Evaled as Number.Rational;
                if (multiple is null || multiple.IsZero)
                    return false;
                var offsetDifference = (offset - multiple * offsetOfY!).InnerSimplified;
                if (!TreeAnalyzer.IsZero(offsetDifference) && !IsTheZeroPolynomial(offsetDifference))
                    return false;
                multiples.Add((node, multiple));
            }
            if (multiples.Count == 0 || slopeOfY is null || offsetOfY is null)
                return false;
            // y scaled so that every multiple is a whole number: the least common multiple of
            // the denominators over the greatest common divisor of the numerators.
            var denominators = EInteger.One;
            var numerators = EInteger.Zero;
            foreach (var (_, multiple) in multiples)
            {
                denominators = denominators.Lcm(multiple.ERational.Denominator);
                numerators = numerators.Gcd(multiple.ERational.Numerator);
            }
            var yScaleRational = ERational.Create(numerators, denominators);
            // With a whole number for the first slope, and asked to, y is x itself (plus the
            // offset over the slope) and each k the slope as written -- the substitution with
            // the root wants `coth(x)`, which is `e^(2x)`, as k = 2 and u = tanh(x), where the
            // scaling by the gcd would make y = 2x, k = 1 and u = tanh(2x), in which coth(x) is
            // a quotient with the root in it and not `1/u`; the rational route wants the
            // opposite, y as coarse as it comes, `coth(2x)` as tanh(2x) and not a quartic in
            // tanh(x). A symbolic slope has no unit to keep, and takes the gcd.
            if (unitX && slopeOfY.Evaled is Number.Integer wholeSlope && !wholeSlope.EInteger.IsZero
                && multiples.All(m => m.Multiple.ERational.Multiply(wholeSlope.EInteger).Denominator.Equals(EInteger.One)))
                yScaleRational = ERational.Create(EInteger.One, wholeSlope.EInteger);
            var yScale = Number.Rational.Create(yScaleRational);
            foreach (var (node, multiple) in multiples)
                exponentials[node] = multiple.ERational.Divide(yScaleRational).ToLowestTerms().Numerator;
            y = (yScale * (slopeOfY * x + offsetOfY)).InnerSimplified;
            dxOverDy = TreeAnalyzer.IsZero(offsetOfY) && slopeOfY == Number.Integer.One && yScale == Number.Integer.One
                ? Number.Integer.One
                : (1 / (yScale * slopeOfY)).InnerSimplified;
            return true;
        }

        // A polynomial with its like terms collected, as a polynomial over every symbol in
        // it: the synthetic division leaves each coefficient a sum of products that
        // nothing below reads as one number.
        private static Entity Collected(Entity polynomial)
        {
            var symbols = polynomial.Vars.ToList();
            if (symbols.Count == 0)
                return polynomial;
            var indices = new Dictionary<Variable, int>();
            foreach (var symbol in symbols)
                indices[symbol] = indices.Count;
            if (Functions.MultivariatePolynomial.TryParse(polynomial, indices) is not { } parsed || parsed.IsZero)
                return polynomial;
            // The numeric content in front of the primitive part -- `4a + 4b u^2` as
            // `4 (a + b u^2)` -- which the symbolic partial fractions want out of the way: a
            // symbolic quadratic to a power with a number in every coefficient made them a
            // page of `a^48 b^15`.
            var primitive = parsed.Normalized();
            var leading = parsed;
            var primitiveLeading = primitive;
            for (var variable = 0; variable < symbols.Count; variable++)
            {
                leading = leading.LeadingCoefficientIn(variable);
                primitiveLeading = primitiveLeading.LeadingCoefficientIn(variable);
            }
            if (leading.ToEntity(symbols).Evaled is not Number.Rational leadingValue || primitiveLeading.ToEntity(symbols).Evaled is not Number.Rational primitiveValue || primitiveValue.IsZero)
                return parsed.ToEntity(symbols);
            var content = leadingValue / primitiveValue;
            return content == Number.Integer.One ? primitive.ToEntity(symbols) : content * primitive.ToEntity(symbols);
        }
        // Zero as a polynomial in its symbols, exactly: a remainder with symbols in it is
        // a sum of products that the inner simplification does not collect.
        private static bool IsTheZeroPolynomial(Entity expr)
        {
            if (expr == Number.Integer.Zero || expr.Evaled is Number.Complex { IsZero: true })
                return true;
            var symbols = expr.Vars.ToList();
            if (symbols.Count == 0)
                return false;
            var indices = new Dictionary<Variable, int>();
            foreach (var symbol in symbols)
                indices[symbol] = indices.Count;
            return Functions.MultivariatePolynomial.TryParse(expr, indices) is { IsZero: true };
        }
        /// <summary>
        /// An integrand that is a rational function of <c>tanh(y)</c> -- of <c>e^(2y)</c>, that
        /// is, even as a function of <c>v = e^y</c> -- with a symbol among its coefficients,
        /// integrated by <c>u = tanh(y)</c>: <c>e^(2y)</c> is <c>(1 + u)/(1 - u)</c> exactly and
        /// <c>dx</c> is <c>du/((1 - u^2) d)</c>, so the integrand is a rational function of
        /// <c>u</c> with the written factors kept -- <c>a + b coth(y)^2</c> is
        /// <c>(b + a u^2)/u^2</c> -- and roots of such functions are admitted as they are.
        /// Failing evenness, the half of <c>y</c>: every <c>e^(k y)</c> is <c>v^(2k)</c> for
        /// <c>v = e^(y/2)</c>, and the substitution is <c>u = tanh(y/2)</c>, the hyperbolic
        /// half-angle.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Under <c>u = e^x</c>, Rubi's <c>1/(a + b coth(x)^2)^2</c> is a rational function of the
        /// palindromic quartic <c>(a + b) u^4 + 2(b - a) u^2 + (a + b)</c> squared, whose roots
        /// are what the budget went on -- fifty-seven of the four hundred and seventeen in the
        /// hyperbolic sample were this; here it is <c>u^4/((b + a u^2)^2 (1 - u^2))</c>, which
        /// the symbolic partial fractions answer. Rubi's route for the hyperbolic tangent,
        /// cotangent, secant and cosecant families. With rational coefficients the exponential
        /// substitution's quartics are factored over the rationals and answered, and are left
        /// to it. Before the substitution search, which with a symbolic slope spends the whole
        /// budget on <c>u = c + d x</c> and never returns here.
        /// </para>
        /// <para>
        /// <b>How the written factors survive.</b> Each maximal rational function of <c>v</c>
        /// among the factors, powers and radicands -- and not the whole quotient -- is read as
        /// <c>v^m R(s)</c> with <c>s = v^2</c> and <c>m</c> either 0 or 1, which every rational
        /// function even or odd in <c>v</c> is, and homogenised on its own: <c>P(s)/Q(s)</c> as
        /// the polynomials <c>sum p_i (1 + u)^i (1 - u)^(d - i)</c> over the same for <c>Q</c>,
        /// with the powers of <c>1 - u</c> and <c>1 + u</c> both share divided out; the
        /// conjugate that <see cref="SolveByHyperbolicTangentSubstitution"/> clears its root
        /// with squares every degree, and left this integrand a quotient of degree sixteen
        /// whose common factor only a gcd over the symbols would find. The stray <c>v</c>'s
        /// cancel in an even integrand -- <c>sech(x)^4</c> is <c>(2v/(s + 1))^4</c> -- and one
        /// left over at the top is an odd integrand, which the half of <c>y</c> takes.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveARationalFunctionOfTheHyperbolicTangent(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // An integrand that is a function of e^(2x) -- even as a function of v = e^x, node
            // by node -- is written in u with no root of 1 - u^2 to clear and nothing squared
            // by a conjugate: e^(2x) is (1 + u)/(1 - u) exactly, and `dx` is `du/(1 - u^2)`.
            // Each maximal rational function of v among the factors, powers and radicands --
            // `a + b coth(x)^2`, and not the whole quotient -- is read as v^m R(s) with s = v^2
            // and m either 0 or 1, which every rational function even or odd in v is, and
            // homogenised on its own: P(s)/Q(s) as the polynomials sum p_i (1 + u)^i (1 - u)^(d - i)
            // over the same for Q, with the powers of 1 - u and 1 + u that both share divided
            // out, so that `coth(x)` comes out as `1/u` and `a + b coth(x)^2` as
            // `(b + a u^2)/u^2`, and the written powers and products stand as they were. The
            // stray v's cancel in an even integrand -- `sech(x)^4` is `(2v/(s + 1))^4` -- and
            // one left over at the top is an odd integrand, not this route's. The rational
            // integrator then sees `u^4/((b + a u^2)^2 (1 - u^2))` and not the quotient of
            // degree sixteen the conjugates made of it.
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow || !expr.Vars.Any(symbol => symbol != x))
                return null;
            if (!TryGatherExponentialsOfOneLinearForm(expr, x, unitX: false, out var exponentials, out var y, out var dxOverDy))
                return null;
            {
                var t = Variable.CreateUnique(expr, "u_tanh");
                var vt = Variable.CreateUnique(expr, "v_tanh");
                var square = Variable.CreateUnique(expr, "s_tanh");
                // With v = e^y first, u = tanh(y), which asks the integrand to be even in v --
                // `coth(2y)` is `(v^2 + 1)/(v^2 - 1)`; failing that with v = e^(y/2) and
                // u = tanh(y/2), which asks nothing, since every e^(k y) is then v^(2k): the
                // half-angle, `sinh(y)` as `2u/(1 - u^2)`. The finer y where the coarser answers,
                // for the lower degrees and the answer in the argument as written. The half only
                // where every exponent is written with an even factor in front -- `coth(c + d x)`
                // is written with `e^(2 (c + d x))`, and `tanh(c + d x)` is its argument's
                // tangent, not the half-angle of `2(c + d x)` -- and with a root in the
                // integrand only where the half leaves every radicand over a power of u
                // (checked once the integrand is in u, below): `sinh(x)` writes `e^x`, the half
                // makes a root of `2u/(1 - u^2)` of `sqrt(sinh(x))`, and its `u = tanh(x/2)`
                // answers were what `u = e^x` answered in less, Timofeev's
                // `e^x/sqrt(e^(2x) + a^2)` among them, a root of a polynomial there.
                var hasARadical = HasARadicalOf(expr, x);
                var halfIsTheArgument = exponentials.Keys.All(node => node is Powf(_, var exponent) && WrittenWithAnEvenFactor(exponent));
                // And the half of a plain `e^y`, at the top only: the integrand asked about is
                // the one whose shape was read, where one below it is what another rule made.
                if (!halfIsTheArgument && !hasARadical && ASymbolStandsBelowTheBar())
                {
                    halfIsTheArgument = true;
                }
                foreach (var halved in new[] { false, true })
                {
                    if (halved && !halfIsTheArgument)
                        break;
                    var inV = expr.Replace(node =>
                        exponentials.TryGetValue(node, out var k)
                            ? MathS.Pow(vt, Number.Integer.Create(halved ? k.Multiply(2) : k))
                            : node);
                    if (inV.ContainsNode(x))
                        return null;
                    if (InTanh(inV) is not var (inT, parity) || parity != 0)
                        continue;
                    // With a root, the half only where every radicand comes out over a power
                    // of t -- `a + b coth(x)^2` is `(b + a t^2)/t^2`, Rubi's cotangent and
                    // cosecant families -- and not over `1 - t^2`, which is where the half
                    // makes a root of a quotient out of `sinh(x)`, and `u = e^x` answers in less.
                    if (halved && hasARadical && !inT.Nodes.All(node => node is not Powf(var radicand, Number.Rational root) || root is Number.Integer || !radicand.ContainsNode(t)
                        || Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(radicand)).Item2 is var below
                            && Mulf.LinearChildren(below).All(factor => !factor.ContainsNode(t) || factor == t || factor is Powf(var b, Number.Integer) && b == t)))
                        continue;
                    var rationalInT = WithThePowersOfOnePlusMinusTCollected(inT / (1 - MathS.Sqr(t)));
                    if (rationalInT.ContainsNode(square) || rationalInT.ContainsNode(vt) || rationalInT.Nodes.Any(node => node == MathS.NaN)
                        || Integration.ComputeAsAQuestionOfItsOwn(rationalInT, t, integrateByParts) is not { } evenResult)
                        return null;
                    // tanh(y/2) spelled with e^y, which is what the integrand was written with.
                    var evenAnswer = evenResult.Substitute(t, halved ? (MathS.Pow(MathS.e, y) - 1) / (MathS.Pow(MathS.e, y) + 1) : MathS.Hyperbolic.Tanh(y));
                    if (evenAnswer.Nodes.Any(node => node == MathS.NaN))
                        return null;
                    // dx is dy/d, and twice that in the half of y.
                    var scale = halved ? (2 * dxOverDy).InnerSimplified : dxOverDy;
                    var scaledAnswer = scale == Number.Integer.One ? evenAnswer : evenAnswer * scale;
                    // Checked, as every answer with symbols in it that is assembled from
                    // pieces is: a root of a rational function of u goes on to rules that
                    // have written one through the imaginary unit.
                    if (!Functions.PartialFractions.DerivativeHoldsAtSampledPoints(scaledAnswer, expr, x))
                        return null;
                    return scaledAnswer;
                }
                return null;

                // A symbol below the bar that the content does not account for: the half of a
                // plain `e^y` is worth taking for `csch(y)^2/(a + b sinh(y))^2`, whose
                // denominator under `u = e^y` is a symbolic quadratic nothing factors, and not
                // for `tanh(y)^6/(a + a sech(y))`, whose denominator is `a` times one the
                // rational integrator factors over the rationals -- there the exponential
                // substitution answers in a page less. Read as a polynomial in `v`, with every
                // coefficient divided by the first: a symbol surviving that is one the
                // denominator's shape depends on.
                bool ASymbolStandsBelowTheBar()
                {
                    var inVOfExpr = expr.Replace(node => exponentials.TryGetValue(node, out var k) ? MathS.Pow(vt, Number.Integer.Create(k)) : node);
                    var denominator = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(inVOfExpr)).Item2;
                    if (!denominator.Vars.Any(symbol => symbol != x && symbol != vt))
                        return false;
                    if (!TreeAnalyzer.TryGetPolynomial(denominator.Expand().InnerSimplified, vt, out var monomials) || monomials.Count == 0)
                        return true;
                    var first = monomials.OrderBy(pair => pair.Key).First().Value;
                    var symbolic = false;
                    foreach (var pair in monomials)
                    {
                        var ratio = (pair.Value / first).InnerSimplified;
                        if (ratio.Vars.Any(symbol => symbol != x && symbol != vt) && Functions.PartialFractions.Bare(ratio.Simplify()).Vars.Any(symbol => symbol != x && symbol != vt))
                            symbolic = true;
                    }
                    if (!symbolic)
                        return false;
                    // And two distinct factors of `v` below the bar, at least: one alone --
                    // `(v^2 - 2 a v - 1)^4`, what the inverse hyperbolic substitution leaves of
                    // `e^asinh(a + b x)/x^4` -- has roots the quadratic formula gives, and
                    // `u = e^y` answers it in a second where the half takes thirty; the pockets
                    // this is for have the written `sinh` beside the symbolic factor.
                    var bases = new List<Entity>();
                    foreach (var factor in Mulf.LinearChildren(denominator))
                    {
                        var factorBase = factor is Powf(var inner, Number.Integer) ? inner : factor;
                        // `v` itself is no factor: it is where an odd power of it was gathered.
                        if (factorBase.ContainsNode(vt) && factorBase != vt && !bases.Any(known => known == factorBase))
                            bases.Add(factorBase);
                    }
                    return bases.Count >= 2;
                }

                // The quotient with every factor that is a multiple of 1 + t or 1 - t, on either
                // side of the bar and to any whole power, gathered into one power of each: the
                // powers of s and the homogenisations each bring their own, `sech(x)^4` arrives
                // as `(1 - t)^4 (1 + t)^2/(1 - t)^2`, and the rational integrator would
                // otherwise meet them as separate factors that only the gcd cancels.
                Entity WithThePowersOfOnePlusMinusTCollected(Entity quotient)
                {
                    // A whole power of a product as the product of the powers, and of a
                    // quotient as the quotient of them, so that the factors are read one by one.
                    for (var round = 0; round < 8; round++)
                    {
                        var distributed = quotient.Replace(node => node switch
                        {
                            Powf(Mulf(var l, var r), Number.Integer power) => MathS.Pow(l, power) * MathS.Pow(r, power),
                            Powf(Divf(var l, var r), Number.Integer power) => MathS.Pow(l, power) / MathS.Pow(r, power),
                            _ => node
                        });
                        if (distributed == quotient)
                            break;
                        quotient = distributed;
                    }
                    var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(quotient));
                    var plus = 0;
                    var minus = 0;
                    Entity constant = Number.Integer.One;
                    Entity keptAbove = Number.Integer.One;
                    Entity keptBelow = Number.Integer.One;
                    foreach (var (side, isBelow) in new[] { (above, false), (below, true) })
                        foreach (var factor in Mulf.LinearChildren(side))
                        {
                            var (factorBase, power) = factor is Powf(var inner, Number.Integer whole) ? (inner, whole.EInteger.ToInt32Checked()) : (factor, 1);
                            if (AsAMultipleOfOnePlusMinusT(factorBase) is var (scale, ofPlus, ofMinus))
                            {
                                var signedPower = isBelow ? -power : power;
                                plus += ofPlus * signedPower;
                                minus += ofMinus * signedPower;
                                constant *= MathS.Pow(scale, Number.Integer.Create(signedPower));
                            }
                            else if (isBelow)
                                keptBelow *= factor;
                            else
                                keptAbove *= factor;
                        }
                    Entity result = keptAbove / keptBelow * constant;
                    // What the two share as a power of 1 - t^2, which the rational integrator
                    // reads as one factor; the rest as the linear ones.
                    var shared = System.Math.Sign(plus) == System.Math.Sign(minus) ? System.Math.Sign(plus) * System.Math.Min(System.Math.Abs(plus), System.Math.Abs(minus)) : 0;
                    if (shared != 0)
                        result *= MathS.Pow(1 - MathS.Sqr(t), Number.Integer.Create(shared));
                    if (plus - shared != 0)
                        result *= MathS.Pow(1 + t, Number.Integer.Create(plus - shared));
                    if (minus - shared != 0)
                        result *= MathS.Pow(1 - t, Number.Integer.Create(minus - shared));
                    return Functions.PartialFractions.Bare(result.InnerSimplified);
                }
                // c (1 + t) as (c, 1, 0), c (1 - t) as (c, 0, 1) and c (1 - t^2) as (c, 1, 1), for
                // a number c; null otherwise.
                (Entity, int, int)? AsAMultipleOfOnePlusMinusT(Entity factor)
                {
                    if (!factor.ContainsNode(t) || !TreeAnalyzer.TryGetPolynomial(factor, t, out var monomials) || monomials.Count != 2
                        || !monomials.TryGetValue(EInteger.Zero, out var c0) || c0.Evaled is not Number.Rational scale || scale.IsZero)
                        return null;
                    if (monomials.TryGetValue(EInteger.One, out var c1) && c1.Evaled is Number.Rational slope)
                        return slope == scale ? (scale, 1, 0) : slope == -scale ? (scale, 0, 1) : null;
                    if (monomials.TryGetValue(EInteger.FromInt32(2), out var c2) && c2.Evaled is Number.Rational curvature && curvature == -scale)
                        return (scale, 1, 1);
                    return null;
                }
                // The node as v^m R with R written in t, m being 0 or 1, with each maximal
                // rational function of v among its factors, powers and radicands read on its
                // own; null where something is not one, or a sum mixes the two parities.
                (Entity, int)? InTanh(Entity node)
                {
                    if (!node.ContainsNode(vt))
                        return (node, 0);
                    switch (node)
                    {
                        case Powf(var @base, var exponent) when !exponent.ContainsNode(vt) && exponent != Number.Integer.One:
                        {
                            if (InTanh(@base) is not var (baseInT, baseParity))
                                return null;
                            if (baseParity == 0)
                                return (MathS.Pow(baseInT, exponent), 0);
                            // (v R)^n is v^n R^n: for n whole, s^(n/2) R^n or v s^((n-1)/2) R^n.
                            if (exponent is not Number.Integer { EInteger: var n })
                                return null;
                            var half = n.IsEven ? n.Divide(2) : n.Subtract(1).Divide(2);
                            return (half.IsZero ? MathS.Pow(baseInT, exponent) : MathS.Pow(baseInT, exponent) * PowerOfS(half), n.IsEven ? 0 : 1);
                        }
                        case Mulf(var left, var right):
                            return InTanh(left) is var (l, lp) && InTanh(right) is var (r, rp) ? WithParity(l * r, lp + rp) : null;
                        case Divf(var above, var below):
                            return InTanh(above) is var (a, ap) && InTanh(below) is var (b, bp) ? WithParity(a / b, ap - bp) : null;
                    }
                    if (!IsARationalFunction(node, vt))
                        return null;
                    var (numerator, denominator) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(node));
                    if (AsPowerOfVTimesEvenPart(numerator) is not var (aboveInS, aboveParity) || AsPowerOfVTimesEvenPart(denominator) is not var (belowInS, belowParity))
                        return null;
                    // v^p P'/(v^q Q'): with p - q = -1, v P'/(s Q').
                    if (aboveParity - belowParity == -1)
                        belowInS *= square;
                    if (DegreeInS(aboveInS) is not { } aboveDegree || DegreeInS(belowInS) is not { } belowDegree)
                        return null;
                    var d = System.Math.Max(aboveDegree, belowDegree);
                    if (Homogenised(aboveInS, d) is not { } top || Homogenised(belowInS, d) is not { } bottom)
                        return null;
                    return (InLowestTerms(top, bottom), aboveParity == belowParity ? 0 : 1);
                }
                // v^(2k + m) as s^k v^m: a whole power of v folded into the even part.
                (Entity, int)? WithParity(Entity ofT, int power)
                {
                    var m = ((power % 2) + 2) % 2;
                    var k = (power - m) / 2;
                    if (k == 0)
                        return (ofT, m);
                    return (ofT * PowerOfS(EInteger.FromInt32(k)), m);
                }
                // A polynomial in v that is even or odd in v, as (P'(s), m) with P(v) = v^m P'(v^2).
                (Entity, int)? AsPowerOfVTimesEvenPart(Entity polynomial)
                {
                    if (!polynomial.ContainsNode(vt))
                        return (polynomial, 0);
                    if (!TreeAnalyzer.TryGetPolynomial(polynomial.Expand().InnerSimplified, vt, out var monomials))
                        return null;
                    var odd = monomials.Keys.Any(power => !power.IsEven);
                    if (odd && monomials.Keys.Any(power => power.IsEven))
                        return null;
                    Entity sum = Number.Integer.Zero;
                    foreach (var pair in monomials)
                    {
                        if (pair.Key.Sign < 0)
                            return null;
                        var half = (odd ? pair.Key.Subtract(1) : pair.Key).Divide(2);
                        sum += pair.Value * (half.IsZero ? Number.Integer.One : MathS.Pow(square, Number.Integer.Create(half)));
                    }
                    return (sum, odd ? 1 : 0);
                }
                // s^k in t: (1 + t)^k over (1 - t)^k, or the other way up for k negative.
                Entity PowerOfS(EInteger k)
                {
                    var whole = Number.Integer.Create(k.Abs());
                    return k.Sign < 0 ? MathS.Pow(1 - t, whole) / MathS.Pow(1 + t, whole) : MathS.Pow(1 + t, whole) / MathS.Pow(1 - t, whole);
                }
                int? DegreeInS(Entity polynomial)
                {
                    if (!polynomial.ContainsNode(square))
                        return 0;
                    if (!TreeAnalyzer.TryGetPolynomial(polynomial.Expand().InnerSimplified, square, out var monomials) || monomials.Keys.Max() is not { } degree
                        || !degree.CanFitInInt32() || monomials.Keys.Any(power => power.Sign < 0))
                        return null;
                    return degree.ToInt32Unchecked();
                }
                // P(s) with s = (1 + t)/(1 - t), times (1 - t)^d for the degree d of the
                // quotient it stands in: a polynomial in t.
                Entity? Homogenised(Entity polynomial, int d)
                {
                    if (!polynomial.ContainsNode(square))
                        return d == 0 ? polynomial : polynomial * MathS.Pow(1 - t, d);
                    if (!TreeAnalyzer.TryGetPolynomial(polynomial.Expand().InnerSimplified, square, out var monomials))
                        return null;
                    Entity sum = Number.Integer.Zero;
                    foreach (var pair in monomials)
                    {
                        if (pair.Key.Sign < 0)
                            return null;
                        var i = pair.Key.ToInt32Unchecked();
                        sum += pair.Value * MathS.Pow(1 + t, i) * MathS.Pow(1 - t, d - i);
                    }
                    return Functions.PartialFractions.Bare(sum.Expand().InnerSimplified);
                }
                // The quotient with the powers of 1 - t and 1 + t both sides share divided out,
                // synthetically -- a polynomial is divisible by t - r exactly when it vanishes at
                // r -- and the sides collected as polynomials over every symbol.
                Entity InLowestTerms(Entity above, Entity below)
                {
                    foreach (var root in new[] { Number.Integer.One, Number.Integer.MinusOne })
                        while (DividedByTMinus(above, root) is { } aboveQuotient && DividedByTMinus(below, root) is { } belowQuotient)
                            (above, below) = (aboveQuotient, belowQuotient);
                    var collectedAbove = Collected(above);
                    var collectedBelow = Collected(below);
                    return collectedBelow == Number.Integer.One ? collectedAbove : collectedAbove / collectedBelow;
                }
                Entity? DividedByTMinus(Entity polynomial, Number.Integer root)
                {
                    if (!TreeAnalyzer.TryGetPolynomial(polynomial, t, out var monomials) || monomials.Keys.Max() is not { } degree || degree.Sign <= 0)
                        return null;
                    var n = degree.ToInt32Checked();
                    var quotient = new Entity[n];
                    Entity carry = Number.Integer.Zero;
                    for (var k = n; k >= 1; k--)
                    {
                        var coefficient = monomials.TryGetValue(EInteger.FromInt32(k), out var c) ? c : Number.Integer.Zero;
                        carry = (coefficient + root * carry).InnerSimplified;
                        quotient[k - 1] = carry;
                    }
                    var constant = monomials.TryGetValue(EInteger.Zero, out var c0) ? c0 : Number.Integer.Zero;
                    if (!IsTheZeroPolynomial((constant + root * carry).InnerSimplified))
                        return null;
                    Entity sum = Number.Integer.Zero;
                    for (var k = 0; k < n; k++)
                        if (!TreeAnalyzer.IsZero(quotient[k]))
                            sum += quotient[k] * MathS.Pow(t, k);
                    return Functions.PartialFractions.Bare(sum.Expand().InnerSimplified);
                }
            }

        }

        /// <summary>
        /// An integrand that is a function of <c>e^x</c> with a root in it, integrated by the
        /// substitution <c>u = tanh(x)</c>, the hyperbolic counterpart of the tangent's.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The library writes the hyperbolic functions as exponentials, and a root of one of
        /// them -- Timofeev's <c>cosh(x)(tanh(x) - cosh(2x))/((sinh(x)^2 + sinh(2x)) sqrt(sinh(2x)))</c>
        /// -- is under <c>u = e^x</c> a root of <c>(u^4 - 1)/u^2</c>, a quartic that nothing
        /// rationalises, where its trigonometric twin is a rational function of the tangent
        /// with <c>sqrt(2u/(1 - u^2))</c> in it and is answered. Under <c>u = tanh(x)</c> the
        /// hyperbolic functions are the same shapes: <c>cosh(x)</c> is <c>(1 - u^2)^(-1/2)</c>
        /// and <c>sinh(x)</c> is <c>u (1 - u^2)^(-1/2)</c>, exactly and for every real <c>x</c>,
        /// since the hyperbolic cosine is positive -- no sign to carry, where the tangent
        /// substitution carries <c>sgn(cos(x))</c>. So <c>e^x</c> is <c>(1 + u)/w</c> and
        /// <c>e^-x</c> is <c>(1 - u)/w</c> for <c>w = sqrt(1 - u^2)</c>, the integrand is
        /// rational in <c>u</c> and <c>w</c> apart from its own roots, and <c>dx = du/(1 - u^2)</c>.
        /// Every quotient -- each radicand, and the whole -- is brought over one bar with
        /// <c>w^2 = 1 - u^2</c> reduced and the denominator cleared of <c>w</c> by its
        /// conjugate, and the polynomials cancelled by their greatest common divisor, so that
        /// <c>e^x + e^-x</c> comes out as <c>2/w</c> and <c>sinh(2x)</c> as <c>2u/(1 - u^2)</c>;
        /// a radicand over a power of <c>1 - u^2</c> gives that power up to <c>w</c>, where it
        /// meets the rest, and a radicand that is a power of <c>1 - u^2</c> and <c>w</c> alone
        /// is a root of <c>1 - u^2</c> of another index -- <c>sech(x)^(3/4)</c> is
        /// <c>(1 - u^2)^(3/8)</c>.
        /// </para>
        /// <para>
        /// With a root in the integrand whose radicand holds exponentials of both signs
        /// -- as a Laurent polynomial in <c>e^x</c>, a polynomial over a power with a power on
        /// either side of it, or a rational function over anything else -- which is where
        /// <c>u = e^x</c> leaves a root of a quartic or of a quotient; with one sign only,
        /// <c>sqrt(e^x - 1)</c> or <c>sqrt(1 + tanh(x))</c>, the exponential substitution answers
        /// with a root of a linear, and is left to. And, with a symbol among the coefficients,
        /// for an integrand that is a rational function of <c>tanh(x)</c> -- one in which
        /// <c>w</c> cancels out -- with its roots, if any, of rational functions of it too:
        /// <c>1/(a + b coth(x)^2)^2</c> is <c>u^4/((b + a u^2)^2 (1 - u^2))</c> here, where under
        /// <c>u = e^x</c> it is a rational function of a symbolic palindromic quartic
        /// <c>(a + b) u^4 + 2(b - a) u^2 + (a + b)</c> squared, whose roots are what the budget
        /// went on; Rubi's route for the hyperbolic tangent, cotangent, secant and cosecant
        /// families. With rational coefficients the exponential substitution's quartics are
        /// factored over the rationals and answered, and are left to it.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByHyperbolicTangentSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // At the top or one below it -- the terms of a sum split as written are one below --
            // since it lands on the chain: asked at every level by every rule that hands a
            // hyperbolic integrand on, it was a search at every depth.
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow || !HasARadicalOf(expr, x))
                return null;
            if (!TryGatherExponentialsOfOneLinearForm(expr, x, unitX: true, out var exponentials, out var y, out var dxOverDy))
                return null;
            // And a radicand that holds exponentials of both signs -- as a Laurent polynomial
            // in v = e^x, a polynomial over a power of v of lower degree -- which is where
            // `u = e^x` leaves a root of a quartic; with one sign only, `sqrt(e^x - 1)` or
            // `sqrt(1 + tanh(x))`, the exponential substitution after this rule answers with a
            // root of a linear.
            var v = Variable.CreateUnique(expr, "v_exp");
            var bothSigns = false;
            foreach (var node in expr.Nodes)
            {
                if (node is not Powf(var radicand, Number.Rational root) || root is Number.Integer || !radicand.ContainsNode(x))
                    continue;
                var inV = radicand.Replace(inner => exponentials.TryGetValue(inner, out var k) ? k.Equals(EInteger.One) ? v : MathS.Pow(v, Number.Integer.Create(k)) : inner);
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(inV));
                if (!TreeAnalyzer.TryGetPolynomial(above.Expand().InnerSimplified, v, out var aboveMonomials) || aboveMonomials.Keys.Max() is not { } aboveDegree
                    || !TreeAnalyzer.TryGetPolynomial(below.Expand().InnerSimplified, v, out var belowMonomials) || belowMonomials.Keys.Max() is not { } belowDegree
                    || belowDegree.Sign == 0)
                    continue;
                // Over a power of v, a Laurent polynomial: both signs where the numerator has
                // a power on either side of that one. Over anything else -- `sech(x)` is
                // `2v/(v^2 + 1)` -- a root of a rational function of v that `u = e^x` leaves a
                // root of a quotient.
                if (belowMonomials.Count != 1 || aboveDegree.CompareTo(belowDegree) > 0 && aboveMonomials.Keys.Min() is { } lowest && lowest.CompareTo(belowDegree) < 0)
                    bothSigns = true;
            }
            if (!bothSigns)
                return null;
            var u = Variable.CreateUnique(expr, "u_tanh");
            var w = Variable.CreateUnique(expr, "w_tanh");
            var oneMinusUSquared = 1 - MathS.Sqr(u);
            // e^(kx) is (1 + u)^k/w^k for k positive and (1 - u)^(-k)/w^(-k) for k negative, with
            // w for sqrt(1 - u^2): the integrand is then rational in u and w, and w^2 is
            // 1 - u^2. Every quotient -- each radicand, and the whole -- is brought over one
            // bar with its numerator and denominator reduced to A + B w, and the denominator
            // cleared of w by its conjugate, so that what is left is E/G + F w/G with E, F
            // and G polynomials in u; w is the root again at the end.
            var rewritten = expr.Replace(node =>
                exponentials.TryGetValue(node, out var k)
                    ? MathS.Pow(k.Sign > 0 ? 1 + u : 1 - u, Number.Integer.Create(k.Abs())) * MathS.Pow(w, Number.Integer.Create(k.Abs().Negate()))
                    : node);
            if (rewritten.ContainsNode(x))
                return null;
            Entity? Rationalized(Entity e)
            {
                var (top, bottom) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(e));
                if (Reduced(top) is not var (a, b) || Reduced(bottom) is not var (c, d))
                    return null;
                if (TreeAnalyzer.IsZero(d))
                    return Over(a, b, c);
                // (A + Bw)(C - Dw) over C^2 - D^2 w^2.
                return Over(Functions.PartialFractions.Bare((a * c - b * d * oneMinusUSquared).Expand().InnerSimplified),
                            Functions.PartialFractions.Bare((b * c - a * d).Expand().InnerSimplified),
                            Functions.PartialFractions.Bare((c * c - d * d * oneMinusUSquared).Expand().InnerSimplified));
            }
            // E/G + F w/G with the greatest common divisor of the three divided out: the
            // conjugate squares every degree, and `sinh(2x)` arrives as
            // `(4u - 4u^3)/(2 - 4u^2 + 2u^4)`, which is `2u/(1 - u^2)`. Over the rationals in
            // u alone, by Euclid; with a symbol in a coefficient the quotients are left as
            // they are.
            Entity Over(Entity e, Entity f, Entity g)
            {
                if (AsRationalPolynomial(e) is { } eP && AsRationalPolynomial(f) is { } fP && AsRationalPolynomial(g) is { } gP && !gP.IsZero)
                {
                    var divisor = Gcd(Gcd(eP, fP), gP);
                    if (!divisor.IsConstant)
                    {
                        eP = Quotient(eP, divisor);
                        fP = Quotient(fP, divisor);
                        gP = Quotient(gP, divisor);
                    }
                    // Monic below the bar.
                    var leading = gP.Leading;
                    var gEntity = gP.ScaleBy(ERational.One.Divide(leading)).ToEntity(u);
                    var rationalPart = eP.IsZero ? Number.Integer.Zero : eP.ScaleBy(ERational.One.Divide(leading)).ToEntity(u) / gEntity;
                    return fP.IsZero ? rationalPart : rationalPart + fP.ScaleBy(ERational.One.Divide(leading)).ToEntity(u) / gEntity * w;
                }
                var rational = TreeAnalyzer.IsZero(e) ? Number.Integer.Zero : e / g;
                return TreeAnalyzer.IsZero(f) ? rational : rational + f / g * w;
            }
            RationalPolynomial? AsRationalPolynomial(Entity polynomial)
            {
                if (TreeAnalyzer.IsZero(polynomial))
                    return RationalPolynomial.Zero;
                if (!TreeAnalyzer.TryGetPolynomial(polynomial, u, out var monomials) || monomials.Keys.Max() is not { } top)
                    return null;
                var coefficients = new ERational[top.ToInt32Checked() + 1];
                for (var i = 0; i < coefficients.Length; i++)
                    coefficients[i] = ERational.Zero;
                foreach (var pair in monomials)
                {
                    if (pair.Value.Evaled is not Number.Rational coefficient)
                        return null;
                    coefficients[pair.Key.ToInt32Checked()] = coefficient.ERational;
                }
                return RationalPolynomial.Create(coefficients);
            }
            static RationalPolynomial Gcd(RationalPolynomial left, RationalPolynomial right)
            {
                while (!right.IsZero)
                {
                    left.TryDivide(right, out _, out var remainder);
                    (left, right) = (right, remainder);
                }
                return left;
            }
            static RationalPolynomial Quotient(RationalPolynomial dividend, RationalPolynomial divisor)
                => dividend.TryDivide(divisor, out var quotient, out _) ? quotient : dividend;
            // A polynomial in u and w as A + B w, by w^2 = 1 - u^2.
            (Entity, Entity)? Reduced(Entity polynomial)
            {
                // Bare: the simplification attaches `provided not 1 - u^2 = 0` where a power of
                // w cancelled, and a condition is nothing a polynomial reader reads.
                var expanded = Functions.PartialFractions.Bare(polynomial.Expand().InnerSimplified);
                if (!expanded.ContainsNode(w))
                    return (expanded, Number.Integer.Zero);
                if (!TreeAnalyzer.TryGetPolynomial(expanded, w, out var byPowerOfW))
                    return null;
                Entity even = Number.Integer.Zero;
                Entity odd = Number.Integer.Zero;
                foreach (var pair in byPowerOfW)
                {
                    var power = pair.Key.ToInt32Checked();
                    var lifted = pair.Value * MathS.Pow(oneMinusUSquared, power / 2);
                    if (power % 2 == 0) even += lifted;
                    else odd += lifted;
                }
                return (Functions.PartialFractions.Bare(even.Expand().InnerSimplified), Functions.PartialFractions.Bare(odd.Expand().InnerSimplified));
            }
            // A polynomial in u that is a constant times a power of `1 - u^2`, coefficient by
            // coefficient; the power is zero for a constant.
            bool IsAConstantTimesAPowerOfOneMinusUSquared(Entity polynomial, out Entity constant, out int power)
            {
                constant = polynomial;
                power = 0;
                if (!polynomial.ContainsNode(u))
                    return true;
                if (!TreeAnalyzer.TryGetPolynomial(polynomial, u, out var monomials) || monomials.Keys.Max() is not { } degree || !degree.IsEven
                    || !TreeAnalyzer.TryGetPolynomial(MathS.Pow(oneMinusUSquared, degree.ToInt32Checked() / 2).Expand(), u, out var reference)
                    || reference.Count != monomials.Count)
                    return false;
                Entity? ratio = null;
                foreach (var pair in monomials)
                {
                    if (!reference.TryGetValue(pair.Key, out var expected))
                        return false;
                    var here = (pair.Value / expected).InnerSimplified;
                    if (ratio is null)
                        ratio = here;
                    else if (ratio != here)
                        return false;
                }
                if (ratio is null || ratio.ContainsNode(u))
                    return false;
                constant = ratio;
                power = degree.ToInt32Checked() / 2;
                return true;
            }
            // Each root, its radicand rationalised, stands as an atom of its own through the
            // polynomial work -- the gcd cancellation read `sqrt(2u/(1 - u^2))` as a
            // polynomial in u and answered `0 provided ...` -- and is put back at the end.
            // A radicand over a power of `1 - u^2` gives that power up to w, where it meets the
            // rest: `sqrt(sinh(2x))` is `sqrt(2u/(1 - u^2))`, which is `sqrt(2u)/w`, and beside
            // the `1/w` of the cosh in front the roots of `1 - u^2` cancel and `sqrt(2u)` is
            // all that is left -- a root of a polynomial, one substitution. And a radicand
            // that is a constant times a power of `1 - u^2` and of w outright -- `sech(x)` is
            // `w`, `cosh(x)` is `w/(1 - u^2)` -- is a root of `1 - u^2` of another index, an
            // atom of its own.
            var atoms = new Dictionary<Entity, Entity>();
            var combined = rewritten.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational root) || root is Number.Integer || !radicand.ContainsNode(u) && !radicand.ContainsNode(w)
                    || Rationalized(radicand) is not { } rationalRadicand)
                    return node;
                var atom = Variable.CreateUnique(expr, $"r{atoms.Count}_tanh");
                // Constant times w^k times a power of 1 - u^2: the whole radicand as one power.
                Entity? constantFactor = Number.Integer.One;
                var ofOneMinusUSquared = ERational.Zero;
                foreach (var factor in Mulf.LinearChildren(Functions.PartialFractions.Bare(rationalRadicand.InnerSimplified)))
                {
                    var (factorBase, factorPower) = factor is Powf(var inner, Number.Integer whole) ? (inner, whole.EInteger) : (factor, EInteger.One);
                    if (factorBase == w)
                        ofOneMinusUSquared = ofOneMinusUSquared.Add(ERational.Create(factorPower, EInteger.FromInt32(2)));
                    else if (!factorBase.ContainsNode(w) && IsAConstantTimesAPowerOfOneMinusUSquared(factorBase, out var constant, out var power))
                    {
                        ofOneMinusUSquared = ofOneMinusUSquared.Add(ERational.FromEInteger(factorPower.Multiply(EInteger.FromInt32(power))));
                        constantFactor = constantFactor * MathS.Pow(constant, Number.Integer.Create(factorPower));
                    }
                    else
                    {
                        constantFactor = null;
                        break;
                    }
                }
                if (constantFactor is not null)
                {
                    var exponent = Number.Rational.Create(ofOneMinusUSquared.Multiply(root.ERational).ToLowestTerms());
                    atoms[atom] = MathS.Pow(constantFactor.InnerSimplified, root) * (exponent == Number.Integer.Zero ? Number.Integer.One : MathS.Pow(oneMinusUSquared, exponent));
                    return atom;
                }
                var (radicandTop, radicandBottom) = Functions.SingleQuotient.Of(rationalRadicand);
                Entity ofW = Number.Integer.One;
                if (!radicandTop.ContainsNode(w) && !radicandBottom.ContainsNode(w)
                    && IsAConstantTimesAPowerOfOneMinusUSquared(radicandBottom, out var bottomConstant, out var m) && m > 0)
                {
                    var wPower = root.ERational.Multiply(ERational.FromInt32(-2 * m)).ToLowestTerms();
                    if (wPower.Denominator.Equals(EInteger.One))
                    {
                        rationalRadicand = bottomConstant.Evaled is Number.Rational number
                            ? (radicandTop * Number.Rational.Create(ERational.One.Divide(number.ERational))).InnerSimplified
                            : (radicandTop / bottomConstant).InnerSimplified;
                        ofW = MathS.Pow(w, Number.Integer.Create(wPower.Numerator));
                    }
                }
                atoms[atom] = rationalRadicand.ContainsNode(w)
                    ? MathS.Pow(rationalRadicand.Substitute(w, MathS.Sqrt(oneMinusUSquared)), root)
                    : MathS.Pow(rationalRadicand, root);
                return ofW == Number.Integer.One ? atom : atom * ofW;
            });
            // The atoms as factors of the whole, and the rest rationalised apart from them: an
            // atom inside a sum is declined, and an atom among the factors would otherwise be
            // squared by the conjugate and never reduced.
            var (wholeTop, wholeBottom) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(combined / oneMinusUSquared));
            Entity atomFactors = Number.Integer.One;
            Entity? restTop = null;
            Entity? restBottom = null;
            foreach (var (side, below) in new[] { (wholeTop, false), (wholeBottom, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var factorBase = factor is Powf(var inner, Number.Integer) ? inner : factor;
                    if (atoms.ContainsKey(factorBase))
                        atomFactors = below ? atomFactors / factor : atomFactors * factor;
                    else if (atoms.Keys.Any(factor.ContainsNode))
                        return null;
                    else if (below)
                        restBottom = restBottom is null ? factor : restBottom * factor;
                    else
                        restTop = restTop is null ? factor : restTop * factor;
                }
            if (Rationalized((restTop ?? Number.Integer.One) / (restBottom ?? Number.Integer.One)) is not { } rationalised)
                return null;
            var integrand = (rationalised * atomFactors).Substitute(w, MathS.Sqrt(oneMinusUSquared));
            foreach (var pair in atoms)
                integrand = integrand.Substitute(pair.Key, pair.Value);
            integrand = integrand.InnerSimplified;
            if (integrand.ContainsNode(x) || integrand.ContainsNode(w) || integrand.Nodes.Any(node => node == MathS.NaN))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts) is not { } result)
                return null;
            var answer = result.Substitute(u, MathS.Hyperbolic.Tanh(y));
            if (answer.Nodes.Any(node => node == MathS.NaN))
                return null;
            var scaled = dxOverDy == Number.Integer.One ? answer : answer * dxOverDy;
            // Checked where a symbol is involved: Rubi's `sqrt(a + b sech(x)) tanh(x)^5` came
            // back with `sqrt(a + i b sqrt(u^2 - 1))` in it, the root of `1 - u^2` written
            // through the imaginary unit by a rule below, and wrong on the reals.
            // https://github.com/asc-community/AngouriMath/issues/1370
            if (expr.Vars.Any(symbol => symbol != x) && !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(scaled, expr, x))
                return null;
            return scaled;
        }

        /// <summary>
        /// An integrand carrying one symbolic parameter, scaled by it — <c>x = c t</c> — so that
        /// what is left to integrate has the variable alone in it.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(a^3 + x^3)</c> had no antiderivative, and neither did <c>1/(a^4 - x^4)</c>,
        /// <c>1/(a^5 + x^5)</c> or any of the family <c>1/(x^k (a^n ± x^n))</c> — while
        /// <c>1/(8 + x^3)</c> and <c>1/(16 - x^4)</c> are answered at once. The parameter is the
        /// whole difference: the rational rules read a denominator as a polynomial <b>over the
        /// rationals</b>, and <c>a^3</c> is not a rational coefficient, so the factoring that
        /// answers <c>x^3 + 8</c> has nothing to work with on <c>x^3 + a^3</c>.
        /// </para>
        /// <para>
        /// <b>Scaling puts the parameter where it does no harm.</b> With <c>x = c t</c> and
        /// <c>dx = c dt</c>, a homogeneous integrand becomes <c>c^k</c> times a function of
        /// <c>t</c> alone: <c>1/(a^3 + x^3)</c> becomes <c>a^(-2) / (1 + t^3)</c>, whose
        /// denominator has integer coefficients again. The parameter comes back out as a constant
        /// factor and the answer is read at <c>t = x/c</c>.
        /// </para>
        /// <para>
        /// <b>Homogeneity is checked rather than assumed</b>, and it is what makes this
        /// terminate. The scaled integrand has to be exactly <c>c^k h(t)</c> for a whole
        /// <c>k</c>, which is verified by dividing it out; only <c>h</c> is handed on, so the
        /// sub-problem has one variable and cannot be scaled again. Without that check the rule
        /// would hand on something still carrying <c>c</c> and scale it once more at every level.
        /// </para>
        /// <para>
        /// <b>What it is not defined at.</b> <c>c = 0</c> is not a scaling, and the answer this
        /// produces is undefined there rather than wrong — <c>a^(-2) G(x/a)</c> has no value at
        /// <c>a = 0</c>, which is the honest report for a substitution that does not exist. The
        /// integrand itself is a different function there (<c>1/(a^3 + x^3)</c> is <c>1/x^3</c>),
        /// and is answered on its own if asked that way.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByScalingTheVariable(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // One parameter, and it is the scale. Two would each need their own and neither
            // clears the other; none means there is nothing in the way to begin with.
            Entity.Variable? scale = null;
            foreach (var variable in expr.Vars)
            {
                if (variable == x)
                    continue;
                if (scale is not null)
                    return null;
                scale = variable;
            }
            if (scale is null)
                return null;

            // dx = c dt.
            var t = Variable.CreateUnique(expr, "u_scale");
            // With the imaginary unit in the integrand the simplifier's search beside the symbol
            // does not end within any budget, and inner simplification separates what a whole
            // power of the scale does: `((1 + i a x)/(1 - i a x))^(-5/4)/x^2` under its radical's
            // substitution was minutes here before it was declined. Where the parts do not
            // separate so, the check below declines it.
            Entity Simplified(Entity e) => HoldsTheImaginaryUnit(expr) ? Functions.PartialFractions.Bare(e.InnerSimplified) : e.Simplify();
            var scaled = Simplified(expr.Substitute(x, scale * t) * scale);
            if (scaled.ContainsNode(x))
                return null;

            // c^k h(t), with h read off at c = 1 and k found by dividing it out. A scaled
            // integrand that is not of that shape is not homogeneous and is declined.
            // The integrand with the scale set to one is the candidate h(t), and what is left
            // over when the scaled integrand is divided by it is the candidate factor. Read off
            // rather than searched for: if the two do separate, the quotient *is* the factor.
            var withoutScale = Simplified(scaled.Substitute(scale, Number.Integer.One));
            if (withoutScale.ContainsNode(scale) || withoutScale == Number.Integer.Zero)
                return null;

            var factor = Simplified(scaled / withoutScale);
            // Collapsing the quotient attaches the condition that the denominator it cleared is
            // non-zero. That denominator is the integrand's own, so the condition says where the
            // integrand is defined and nothing about this rewrite; it is dropped for the same
            // reason the other rewrites drop theirs.
            if (factor is Providedf(var withoutCondition, _))
                factor = withoutCondition;

            // The whole of the homogeneity check. If the scale did not separate, what is left
            // still mentions t, and handing that on would carry the parameter into the
            // sub-problem -- which could then be scaled again, at every level, without end.
            if (factor.ContainsNode(t) || factor.ContainsNode(x))
                return null;

            if (Integration.ComputeIndefiniteIntegral(withoutScale, t, integrateByParts) is not { } result)
                return null;

            var answer = (factor * result).Substitute(t, x / scale);
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// A power whose base holds the variable, written out and integrated term by term.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>(2x + 3x^2)^3</c> had no antiderivative, and it is a polynomial. The rule for a
        /// power integrates <c>x^n</c> and asks that the base <em>be</em> the variable, so a base
        /// that merely contains it — any polynomial but a bare <c>x</c> — matched nothing, and
        /// nothing else in the chain writes a power out. <c>(1 + x)^3</c> was answered only
        /// because the linear substitution reads it.
        /// </para>
        /// <para>
        /// <b>It runs last</b>, after every rule that can answer a power in its own terms.
        /// Expanding throws away whatever structure the power had — <c>(1 + x^2)^2</c> is
        /// answered as a power, and writing it out first would replace that answer with a longer
        /// one saying the same thing.
        /// </para>
        /// <para>
        /// <b>Only a positive whole exponent</b>, where writing it out is a finite identity. A
        /// negative one is a quotient and belongs to partial fractions; a fractional one is a
        /// radical and does not expand at all.
        /// </para>
        /// <para>
        /// The expansion is bounded by <see cref="MathS.Settings.MaxExpansionTermCount"/> like
        /// every other, and the rule declines where the expansion is not a sum — nothing was
        /// written out, so handing it on would ask the same question again.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByExpandingAPower(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not Powf(var @base, Number.Integer power))
                return null;
            if (power.EInteger.CompareTo(EInteger.One) <= 0)
                return null;
            if (!@base.ContainsNode(x))
                return null;

            var written = expr.Expand();
            if (written is not Sumf and not Minusf)
                return null;

            return Integration.ComputeIndefiniteIntegral(written, x, integrateByParts);
        }

        /// <summary>
        /// A rational function with symbols in it beside a power that is not whole of a linear,
        /// <c>R(x) (a + b x)^q</c>, with two or more factors below the bar: split into partial
        /// fractions over the factors as written, each term beside the power is the question
        /// the rules for one factor answer. <c>1/(x (1 + x^2) sqrt(a + b x))</c> is
        /// <c>1/(x sqrt(a + b x)) - x/((1 + x^2) sqrt(a + b x))</c>, and was declined: under
        /// <c>v = sqrt(a + b x)</c> it is a rational function over a sextic with symbols in it,
        /// which nothing factors, where each term above is answered at once. It is what the
        /// tangent substitution makes of Rubi's 4.3.2.1, <c>cot(x)/sqrt(a + b tan(x))</c>.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// Late, so that whatever answers the integrand whole answers first, and only with a symbol
        /// in it: with numbers the substitution's rational function is split over the rationals.
        /// </remarks>
        internal static Entity? SolveARationalFunctionBesideARootOfALinearSplitFirst(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Vars.Any(symbol => symbol != x))
                return null;
            Entity? radicand = null;
            var exponent = ERational.Zero;
            Entity constant = Number.Integer.One;
            Entity above = Number.Integer.One;
            Entity below = Number.Integer.One;
            var belowFactors = 0;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                if (factor is Powf(var linear, Number.Rational power) && power is not Number.Integer
                    && TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out _) && !TreeAnalyzer.IsZero(slope))
                {
                    if (radicand is not null)
                        return null;
                    (radicand, exponent) = (linear, underneath ? power.ERational.Negate() : power.ERational);
                    continue;
                }
                // A polynomial, or a whole power of one.
                var (@base, whole) = factor is Powf(var raised, Number.Integer n) && n.EInteger.CanFitInInt32() ? (raised, n.EInteger.ToInt32Checked()) : (factor, 1);
                if (!TreeAnalyzer.TryGetPolynomial(@base, x, out var read) || read.Keys.Any(degree => degree.Sign < 0) || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                    return null;
                var written = System.Math.Abs(whole) == 1 ? @base : MathS.Pow(@base, System.Math.Abs(whole));
                if (underneath == whole > 0)
                {
                    below = below == Number.Integer.One ? written : below * written;
                    belowFactors++;
                }
                else
                    above = above == Number.Integer.One ? written : above * written;
            }
            if (radicand is null)
                return null;
            // The whole part of the power goes into the rational function, and what is left of it
            // is a root below the bar, `L^q = L^k / L^(k - q)` with `k` the least whole number past
            // `q`: `1/(x (1 + x^2) (a + b x)^(3/2))` is split with `a + b x` among the factors and
            // every term over `sqrt(a + b x)`, the shape the rules for one factor read.
            var (top, bottom) = (exponent.Numerator, exponent.Denominator);
            var wholePart = top.Sign > 0 ? top.Add(bottom).Subtract(EInteger.One).Divide(bottom) : top.Divide(bottom);
            if (wholePart.Sign > 0)
                above = above == Number.Integer.One ? MathS.Pow(radicand, Number.Integer.Create(wholePart)) : above * MathS.Pow(radicand, Number.Integer.Create(wholePart));
            else if (wholePart.Sign < 0)
            {
                var negated = wholePart.Negate();
                var power = negated.Equals(EInteger.One) ? radicand : MathS.Pow(radicand, Number.Integer.Create(negated));
                below = below == Number.Integer.One ? power : below * power;
                belowFactors++;
            }
            var root = MathS.Pow(radicand, Number.Rational.Create(ERational.FromEInteger(wholePart).Subtract(exponent)));
            if (belowFactors < 2
                || !Functions.PartialFractions.TrySplitOverWrittenFactors(above, below, x, out var decomposition))
                return null;
            // The split comes over the denominator's constant, which goes in front.
            if (decomposition is Divf(var split, var over) && !over.ContainsNode(x))
                (decomposition, constant) = (split, constant / over);
            var terms = Sumf.LinearChildren(decomposition).Where(term => !TreeAnalyzer.IsZero(term)).ToList();
            if (terms.Count < 2)
                return null;
            Entity sum = Number.Integer.Zero;
            foreach (var term in terms)
            {
                var question = term / root;
                if (Integration.ComputeIndefiniteIntegral(question, x, integrateByParts) is not { } integral
                    || integral.Nodes.Any(node => node is Integralf))
                    return null;
                sum += integral;
            }
            return constant * sum;
        }

        /// <summary>
        /// A rational function over one block quadratic in a power of x, <c>a + b x^n + c x^(2n)</c>
        /// with a symbol in it, split at the block's roots in <c>u = x^n</c>: the single block
        /// <see cref="IntegrateOverBlocksInAPowerOfX"/> leaves to this.
        /// </summary>
        /// <remarks>
        /// The roots are <c>(-b ± sqrt(b^2 - 4ac))/(2c)</c>, complex where <c>b^2 &lt; 4ac</c>, and
        /// every fraction after the split is over a binomial <c>x^n - r</c> with that root in it.
        /// Last, so that whatever answers the block whole answers first: a rule that branches on
        /// the sign of <c>r</c> has no branch for a complex one.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByOneBlockInAPowerOfXAtItsRoots(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var (numerator, denominator) = Functions.SingleQuotient.Of(expr);
            return denominator.ContainsNode(x) && !numerator.Nodes.Any(node => node is Powf(_, Number.Rational r) && r is not Number.Integer)
                ? IntegrateOverBlocksInAPowerOfX(numerator, denominator, x, integrateByParts, oneBlockAtItsRoots: true)
                : null;
        }

        /// <summary>
        /// A product of sums, of positive whole powers of sums and of powers of the variable,
        /// written out and integrated term by term.
        /// </summary>
        /// <remarks>
        /// <c>(a + b x^n)(c + d x^n)^3</c> had no antiderivative, and written out it is eight
        /// powers of x, each answered at once: no rule reads a power of x whose exponent is a
        /// symbol as a polynomial, and the rule above writes out one power and not a product of
        /// them. As late as that one, and for the same reason: a product that a rule answers in
        /// its own terms is not written out. Only where every factor with x in it is a sum of
        /// powers of x, a positive whole power of one, or a power of x itself, so that writing it
        /// out is a finite identity, bounded by <see cref="MathS.Settings.MaxExpansionTermCount"/>,
        /// whose terms are each answered at once; and only for the question asked, not for what a
        /// rule leaves over. A sum of exponentials is a sum too: integration by parts on
        /// <c>x^2 Shi(a + b x) sinh(a + b x)</c> leaves a run of them beside powers of x, and
        /// written out each term is a search of its own.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByExpandingAProductOfSums(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not Mulf || !Integration.AnsweringTheQuestionAsked)
                return null;
            var sums = 0;
            foreach (var factor in Mulf.LinearChildren(expr))
            {
                if (!factor.ContainsNode(x))
                    continue;
                switch (factor)
                {
                    case Sumf or Minusf when IsASumOfPowersOfX(factor, x):
                    case Powf((Sumf or Minusf) and var sum, Number.Integer power) when power.EInteger.CompareTo(EInteger.One) > 0 && IsASumOfPowersOfX(sum, x):
                        sums++;
                        break;
                    case Entity.Variable when factor == x:
                    case Powf(var @base, var exponent) when @base == x && !exponent.ContainsNode(x):
                        break;
                    default:
                        return null;
                }
            }
            if (sums == 0)
                return null;
            var written = expr.Expand();
            if (written is not Sumf and not Minusf)
                return null;
            return Integration.ComputeIndefiniteIntegral(written, x, integrateByParts);

            // Each term a constant times a power of x, the power's exponent free of x.
            static bool IsASumOfPowersOfX(Entity sum, Entity.Variable x)
                => Sumf.LinearChildren(sum).All(term => Mulf.LinearChildren(term).All(factor =>
                    !factor.ContainsNode(x) || factor == x || factor is Powf(var @base, var exponent) && @base == x && !exponent.ContainsNode(x)));
        }

        /// <summary>
        /// Several square roots of polynomials in the variable, written as one:
        /// <c>sqrt(1 + x^2) sqrt(1 - x^2)</c> is <c>sqrt(1 - x^4)</c>, and a root below the bar
        /// is a root above it over its own base, <c>1/sqrt(B) = sqrt(B)/B</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>x/(sqrt(1 + x^2) sqrt(1 - x^2))</c> had no antiderivative and <c>x/sqrt(1 - x^4)</c>
        /// is one substitution. Nothing reads two radicals: the substitution wants one subtree
        /// to replace, Euler's rule wants one root of one quadratic, and each rule looked at
        /// this integrand and saw two of what it takes one of. It is what by parts leaves from
        /// <c>arcsin(x)/(1 + x^2)^(3/2)</c> and from <c>ln(x + sqrt(1 + x^2))/(1 - x^2)^(3/2)</c>,
        /// and from every other pairing of an inverse function's radical with the one in
        /// the power it stands over.
        /// </para>
        /// <para>
        /// <b>When the identity holds.</b> On the principal branch, <c>sqrt(P) sqrt(Q) = sqrt(PQ)</c>
        /// whenever at most one of <c>P</c> and <c>Q</c> is negative: with both negative the
        /// left is <c>i sqrt|P| * i sqrt|Q| = -sqrt|PQ|</c> and the right is <c>+sqrt|PQ|</c>.
        /// For <c>k</c> roots the same count applies -- <c>i^k</c> against <c>i^(k mod 2)</c> --
        /// so the rule asks whether there is a real <c>x</c> at which two of the bases are
        /// negative, and only rewrites when there is not. The bases are polynomials with
        /// numeric coefficients; their real roots cut the line into intervals on each of which
        /// every base keeps its sign, so the count at one point of each interval is the count
        /// on the interval. Where the solver cannot give the roots, the rule declines.
        /// </para>
        /// <para>
        /// A rewriting rule, unscoped: what it hands on has strictly fewer radicals than what
        /// it was given, and it is asked one level down more often than at the top, since the
        /// two-radical shape is what a by-parts step produces.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        /// <summary>
        /// A square root of a polynomial with a repeated factor, the factor taken out of the
        /// root: <c>sqrt(9 + 3x - 5x^2 + x^3)</c> is <c>sqrt((x - 3)^2 (x + 1))</c>, which is
        /// <c>|x - 3| sqrt(x + 1)</c>, and the modulus is <c>sgn(x - 3) (x - 3)</c> -- a constant
        /// sign on each side of the root, carried through the integration as a symbol and
        /// written back as the sign. Timofeev's <c>1/sqrt(9 + 3x - 5x^2 + x^3)</c> is
        /// <c>sgn(x - 3) ln(...)</c> that way, where the radical of a cubic was elliptic to
        /// every rule that read it.
        /// </summary>
        /// <remarks>
        /// Square roots only: an odd root of a power is the power of the root on the reals
        /// with no sign to keep. The sign is a symbol to the integration, so a symbol's
        /// square is one and its odd powers the symbol, and the answer holds wherever the
        /// factor is not zero, where the integrand is singular anyway. At the top only: a
        /// substitution's own variable is one it knows the sign of.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTakingASquareFactorOutOfARoot(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // With a sign at the top only: a substitution's variable below is one the
            // substitution knows the sign of -- `u = (x + 1)^(1/6)` is not negative -- and a
            // sign written for it here is one nothing can differentiate. A factor positive for
            // every real x needs no sign and comes out at any depth: `sqrt((u^2 + 1)^2 u)` is
            // `(u^2 + 1) sqrt(u)`, what the tangent substitution makes of `sqrt(sin(x)/cos(x)^5)`.
            var atTheTop = Integration.AnsweringTheQuestionAsked;
            // The signs are constants, one on each side of a factor's root, so they come out
            // in front of the integral: the integrand is asked without them, and the answer
            // is the product of the signs to their powers, an even power being one. From a root
            // that is a factor of the integrand only: inside a sum the sign is a factor of
            // nothing, `x/(x + sqrt(x^6))` being `1/(1 + x^2)` for a positive x and `1/(1 - x^2)`
            // for a negative one. There the root is written with a sign of its own, and the
            // integrand is integrated with it 1 and with it -1, each on its side of the
            // factor's root; one such factor only.
            Entity signs = Number.Integer.One;
            var factorsOfTheIntegrand = FactorsOfTheIntegrand(expr).Select(pair => pair.Factor).ToList();
            var sign = Variable.CreateUnique(expr, "s_sgn");
            Entity? signedFactor = null;
            var signsOfMoreThanOneFactor = false;
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer
                    || !exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !radicand.ContainsNode(x))
                    return node;
                var asAFactor = factorsOfTheIntegrand.Count(factor => factor == node) == expr.Nodes.Count(inner => inner == node);
                var signsHere = new List<Entity>();
                if (Functions.PolynomialFactorization.FactorComplete(radicand, x) is not { } factorization
                    || factorization.Parts.All(part => part.Multiplicity < 2))
                    return node;
                if (factorization.Parts.Count > 6)
                    return node;
                // Out of the root: each factor to half its multiplicity, rounded down, with a
                // sign where that half is odd; under it: the constant and what is left.
                Entity outside = Number.Integer.One;
                Entity inside = Number.Rational.Create(factorization.Constant);
                var numerator = exponent.ERational.Numerator;
                foreach (var part in factorization.Parts)
                {
                    var factor = part.Factor.ToEntity(x);
                    var half = part.Multiplicity / 2;
                    if (half > 0)
                    {
                        // |f|^(half n) is f^(half n) sgn(f)^(half n).
                        var withASign = !numerator.Multiply(EInteger.FromInt32(half)).IsEven && !IsPositiveForReal(factor, x);
                        if (withASign && !atTheTop)
                        {
                            inside = inside * MathS.Pow(factor, 2 * half);
                            if (part.Multiplicity % 2 == 1)
                                inside = inside * factor;
                            continue;
                        }
                        outside = outside * (half == 1 ? factor : MathS.Pow(factor, half));
                        if (withASign)
                            signsHere.Add(factor);
                    }
                    if (part.Multiplicity % 2 == 1)
                        inside = inside * factor;
                }
                if (!outside.ContainsNode(x))
                    return node;
                var taken = MathS.Pow(outside, Number.Integer.Create(numerator)) * MathS.Pow(inside, exponent);
                if (signsHere.Count == 0)
                    return taken;
                if (asAFactor)
                {
                    foreach (var signed in signsHere)
                        signs = signs * MathS.Signum(signed);
                    return taken;
                }
                if (signsHere.Count > 1 || signedFactor is not null && signedFactor != signsHere[0])
                {
                    signsOfMoreThanOneFactor = true;
                    return node;
                }
                signedFactor = signsHere[0];
                return sign * taken;
            });
            if (rewritten == expr || signsOfMoreThanOneFactor)
                return null;
            Entity result;
            if (signedFactor is null)
            {
                if (Integration.ComputeAsAQuestionOfItsOwn(rewritten, x, integrateByParts) is not { } unsigned)
                    return null;
                result = unsigned;
            }
            else
            {
                if (Integration.ComputeAsAQuestionOfItsOwn(rewritten.Substitute(sign, Number.Integer.One).InnerSimplified, x, integrateByParts) is not { } above
                    || Integration.ComputeAsAQuestionOfItsOwn(rewritten.Substitute(sign, Number.Integer.MinusOne).InnerSimplified, x, integrateByParts) is not { } below)
                    return null;
                result = MathS.Piecewise(new[] { new Providedf(above, signedFactor > Number.Integer.Zero) }, below);
            }
            var answer = signs == Number.Integer.One ? result : signs * result;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// A rational function of a sine, or of a cosine, over a quadratic in it with a symbol
        /// among the coefficients: <c>sin(x)/(a + b sin(x) + c sin(x)^2)</c>, and the same with
        /// the other function to even powers, a cosecant or a secant beside. Written in
        /// <c>s = sin(x)</c> it is a rational function of <c>s</c>, divided down and split over
        /// the written factors as any is, and the piece over the quadratic is taken by the two
        /// roots: with <c>q = sqrt(b^2 - 4 a c)</c> and <c>r = (-b ± q)/(2c)</c>,
        /// <c>(d + e s)/(a + b s + c s^2)</c> is <c>(d + e r_1)/(q (s - r_1)) - (d + e r_2)/(q (s - r_2))</c>,
        /// and <c>1/(sin(x) - r)</c> is <c>-2 atan((r tan(x/2) - 1)/sqrt(r^2 - 1))/sqrt(r^2 - 1)</c>
        /// for any complex <c>r</c> but <c>±1</c>; <c>1/(cos(x) - r)</c> is
        /// <c>-2 atan(tan(x/2)/σ)/((1 + r) σ)</c> with <c>σ = sqrt((r - 1)/(r + 1))</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Under the half-angle the quadratic in the sine is a quartic in <c>t</c> with a symbol
        /// in every coefficient, which nothing factors, and the substitution <c>u = sin(x)</c>
        /// wants a cosine above the bar that an even power does not give; Rubi's
        /// <c>trig^m (a + b sin^n + c sin^(2n))^p</c> files lost every even numerator to that.
        /// The two closed forms are each checked by differentiation in the summary of the
        /// biquadratic rule's kind: <c>d/dx atan(u/s)/s</c> is <c>u'/(s^2 + u^2)</c> whatever
        /// <c>s</c> is, so neither asks the sign of a root, where a piecewise on it, as the
        /// quadratic rule writes for a symbolic root, has no value for the conjugate pair the
        /// ordinary case gives. On each interval between the poles of <c>tan(x/2)</c>, the
        /// standing property of the half-angle.
        /// </para>
        /// <para>
        /// Exact wherever the two roots differ, the generic case, with a root at <c>±1</c>
        /// taken as the square it makes under the half-angle; a discriminant that is zero as
        /// written declines.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveARationalFunctionOfASineOverASymbolicQuadratic(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            Entity? argument = null;
            foreach (var node in expr.Nodes)
            {
                if (TrigonometricArgument(node) is not { } thisArgument || !thisArgument.ContainsNode(x))
                    continue;
                if (argument is null)
                    argument = thisArgument;
                else if (argument != thisArgument)
                    return null;
            }
            if (argument is null || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out var offsetOfArgument)
                || rate.ContainsNode(x) || TreeAnalyzer.IsZero(rate))
                return null;
            if (!expr.Nodes.All(node => !node.ContainsNode(x)
                    || node is Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf or Secantf or Cosecantf or Tanf or Cotanf
                    || node is Powf(_, Number.Integer)))
                return null;
            var sine = MathS.Sin(argument);
            var cosine = MathS.Cos(argument);
            var inTheTwo = expr.Replace(node => node switch
            {
                Secantf(var a) when a == argument => 1 / cosine,
                Cosecantf(var a) when a == argument => 1 / sine,
                Tanf(var a) when a == argument => sine / cosine,
                Cotanf(var a) when a == argument => cosine / sine,
                _ => node,
            });
            var s = Variable.CreateUnique(inTheTwo, "s_trig");
            var w = Variable.CreateUnique(inTheTwo + s, "w_trig");
            foreach (var (function, other) in new[] { (sine, cosine), (cosine, sine) })
            {
                var inS = inTheTwo.Substitute(function, s).Substitute(other, w);
                if (inS.ContainsNode(x))
                    return null;
                if (OverASymbolicQuadraticInTheFunction(inS, s, w, function == sine, argument, rate, x, integrateByParts) is { } answer)
                    return answer;
            }
            return null;
        }

        /// <summary>
        /// The rule above in <paramref name="s"/>, for the function that <paramref name="s"/>
        /// stands for and <paramref name="w"/> its complement: null where the integrand is
        /// not a rational function of <paramref name="s"/> once the even powers of
        /// <paramref name="w"/> are <c>1 - s^2</c>, or its denominator's written factors are
        /// not powers of <paramref name="s"/>, of <paramref name="w"/> and of linears in
        /// <paramref name="s"/> beside one quadratic in <paramref name="s"/> with a symbol in it.
        /// </summary>
        private static Entity? OverASymbolicQuadraticInTheFunction(Entity inS, Variable s, Variable w, bool ofTheSine, Entity argument, Entity rate, Entity.Variable x, bool integrateByParts)
        {
            var combined = Functions.SingleQuotient.Combine(inS).InnerSimplified;
            if (combined is Providedf(var bare, _))
                combined = bare;
            var (numerator, denominator) = Functions.SingleQuotient.Of(combined);
            // The numerator as a polynomial in s, the complement's even powers written as
            // powers of 1 - s^2; an odd power is the substitution's, not this rule's.
            if (WithTheComplementSquared(numerator, s, w) is not { } above)
                return null;
            // The denominator's written factors: a constant, a power of s, a power of the
            // complement, a linear in s, and exactly one quadratic in s with a symbol in it.
            Entity constant = Number.Integer.One;
            Entity written = Number.Integer.One;
            Entity? quadratic = null;
            var degree = 0;
            var blocks = 0;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (!factor.ContainsNode(s) && !factor.ContainsNode(w))
                {
                    constant = constant * factor;
                    continue;
                }
                var (toRead, multiplicity) = factor is Powf(var repeatedBase, Number.Integer { EInteger.Sign: > 0 } repeated) && repeated.EInteger.CanFitInInt32()
                    ? (repeatedBase, repeated.EInteger.ToInt32Unchecked()) : (factor, 1);
                if (toRead == w)
                {
                    if (multiplicity % 2 != 0)
                        return null;
                    var half = multiplicity / 2;
                    written = written * (half == 1 ? 1 - s : MathS.Pow(1 - s, half)) * (half == 1 ? 1 + s : MathS.Pow(1 + s, half));
                    degree += multiplicity;
                    blocks += 2;
                    continue;
                }
                if (toRead.ContainsNode(w) || !TreeAnalyzer.TryGetPolynomial(toRead, s, out var read) || read.Count == 0
                    || read.Keys.Any(power => power.Sign < 0) || read.Values.Any(coefficient => coefficient.ContainsNode(s) || coefficient.ContainsNode(w)))
                    return null;
                var thisDegree = read.Keys.Max()!.ToInt32Checked();
                if (thisDegree == 2 && multiplicity == 1 && toRead.Vars.Any(v => v != s))
                {
                    if (quadratic is not null)
                        return null;
                    quadratic = toRead;
                }
                else if (thisDegree > 1)
                    return null;
                written = written * factor;
                degree += thisDegree * multiplicity;
                blocks++;
            }
            if (quadratic is null || !TreeAnalyzer.TryGetPolynomial(quadratic, s, out var coefficients))
                return null;
            var a = coefficients.TryGetValue(EInteger.Zero, out var a0) ? a0 : Number.Integer.Zero;
            var b = coefficients.TryGetValue(EInteger.One, out var b0) ? b0 : Number.Integer.Zero;
            var c = coefficients[EInteger.FromInt32(2)];
            var discriminant = Functions.PartialFractions.Bare((b * b - 4 * a * c).Simplify());
            if (discriminant == Number.Integer.Zero || discriminant.Evaled is Number.Complex { IsZero: true })
                return null;

            // Divided down where the numerator's degree reaches the denominator's; the whole
            // part is a polynomial in the function, the rules' own.
            Entity total = Number.Integer.Zero;
            var function = ofTheSine ? MathS.Sin(argument) : MathS.Cos(argument);
            if (TreeAnalyzer.TryGetPolynomial(above, s, out var aboveRead) && aboveRead.Count > 0 && aboveRead.Keys.Max()!.CompareTo(EInteger.FromInt32(degree)) >= 0)
            {
                var expandedBelow = (constant * written).Expand().InnerSimplified;
                if (TreeAnalyzer.PolynomialLongDivision(above, expandedBelow, genericCase: true, inTermsOf: s) is not var (whole, rest))
                    return null;
                if (Integration.ComputeIndefiniteIntegral(whole.InnerSimplified.Substitute(s, function), x, integrateByParts) is not { } wholePart)
                    return null;
                total += wholePart;
                above = (rest is Divf(var top, _) ? top : rest).InnerSimplified;
                if (above is Providedf(var bareRest, _))
                    above = bareRest;
                if (above.Evaled is Number.Complex { IsZero: true })
                    return total;
            }
            // Over the quadratic alone there is nothing to split; otherwise over the written
            // factors, the quadratic among them.
            var below = constant == Number.Integer.One ? quadratic : constant * quadratic;
            Entity? decomposition;
            if (blocks == 1)
                decomposition = above / below;
            else if (!Functions.PartialFractions.TrySplitOverWrittenFactors(above, constant == Number.Integer.One ? written : constant * written, s, out decomposition))
                return null;
            var (terms, over) = decomposition is Divf(var sum, var divisor) && !divisor.ContainsNode(s)
                ? (sum, divisor) : (decomposition, Number.Integer.One as Entity);
            var q = MathS.Sqrt(discriminant);
            var firstRoot = (-b + q) / (2 * c);
            var secondRoot = (-b - q) / (2 * c);
            var quadraticWritten = quadratic.InnerSimplified;
            Entity overTheFactors = Number.Integer.Zero;
            foreach (var term in Sumf.LinearChildren(terms))
            {
                if (term.Evaled is Number.Complex { IsZero: true })
                    continue;
                // The term over the quadratic, however the split wrote its constant: `P/Q`,
                // or `D^(-1) (P/Q)` with the coefficients' common denominator in front.
                var (termAbove, termBelow) = Functions.SingleQuotient.Of(term);
                Entity termConstant = Number.Integer.One;
                var overTheQuadratic = false;
                foreach (var divisorFactor in Mulf.LinearChildren(termBelow))
                {
                    if (divisorFactor.InnerSimplified == quadraticWritten && !overTheQuadratic)
                        overTheQuadratic = true;
                    else if (!divisorFactor.ContainsNode(s))
                        termConstant = termConstant * divisorFactor;
                    else
                    {
                        overTheQuadratic = false;
                        break;
                    }
                }
                if (overTheQuadratic
                    && TreeAnalyzer.TryGetPolynomial(termAbove, s, out var linear) && linear.Keys.All(power => power.Sign >= 0 && power.CompareTo(EInteger.One) <= 0)
                    && linear.Values.All(coefficient => !coefficient.ContainsNode(s)))
                {
                    var d = linear.TryGetValue(EInteger.Zero, out var d0) ? d0 : Number.Integer.Zero;
                    var e = linear.TryGetValue(EInteger.One, out var e0) ? e0 : Number.Integer.Zero;
                    foreach (var (root, sign) in new[] { (firstRoot, 1), (secondRoot, -1) })
                    {
                        var coefficient = ((d + e * root) / (q * termConstant)).InnerSimplified;
                        if (coefficient == Number.Integer.Zero)
                            continue;
                        var part = OverTheFunctionLessARoot(root, ofTheSine, argument, rate);
                        overTheFactors += sign == 1 ? coefficient * part : -coefficient * part;
                    }
                    continue;
                }
                if (Integration.ComputeIndefiniteIntegral(term.Substitute(s, function), x, integrateByParts) is not { } integrated)
                    return null;
                overTheFactors += integrated;
            }
            return total + (over == Number.Integer.One ? overTheFactors : overTheFactors / over);
        }

        /// <summary>
        /// <c>int dx/(sin(k x + m) - r)</c>, or the same of the cosine, for any complex
        /// <paramref name="root"/>: <c>-2 atan((r t - 1)/sqrt(r^2 - 1))/(k sqrt(r^2 - 1))</c>
        /// with <c>t = tan((k x + m)/2)</c>, and <c>-2 atan(t/σ)/(k (1 + r) σ)</c> with
        /// <c>σ = sqrt((r - 1)/(r + 1))</c>. Each differentiates back to the integrand for
        /// every value of the root but <c>±1</c>, the arctangent of an imaginary argument being
        /// the hyperbolic one with a constant imaginary part a derivative does not see; at
        /// <c>±1</c> the integral is rational in <c>t</c>.
        /// </summary>
        private static Entity OverTheFunctionLessARoot(Entity root, bool ofTheSine, Entity argument, Entity rate)
        {
            var t = MathS.Tan(argument / 2);
            // A root that is 1 or -1 -- `a - a sin(x)^2` has both, for every a -- leaves the
            // arctangent's spread zero, and the answer NaN wherever it was evaluated. There the
            // quadratic under the half-angle is a square, and the integral rational in t:
            // 2/(r t - 1) for the sine, and 1/t or t for the cosine at 1 and at -1.
            // https://github.com/asc-community/AngouriMath/issues/1588
            if (VanishesIdentically(root * root - 1))
                return ofTheSine
                    ? 2 / (rate * (root * t - 1))
                    : ((1 + root) / (2 * t) + (1 - root) * t / 2) / rate;
            if (ofTheSine)
            {
                var spread = MathS.Sqrt(root * root - 1);
                return -2 * MathS.Arctan((root * t - 1) / spread) / (rate * spread);
            }
            var sigma = MathS.Sqrt((root - 1) / (root + 1));
            return -2 * MathS.Arctan(t / sigma) / (rate * (1 + root) * sigma);
        }

        /// <summary>
        /// <paramref name="expr"/>, a polynomial in <paramref name="s"/> and <paramref name="w"/>,
        /// with every even power of <paramref name="w"/> written as the power of
        /// <c>1 - s^2</c>, expanded; null where an odd power of <paramref name="w"/> is in it
        /// or it is not such a polynomial.
        /// </summary>
        private static Entity? WithTheComplementSquared(Entity expr, Variable s, Variable w)
        {
            if (!TreeAnalyzer.TryGetPolynomial(expr, w, out var inW))
                return null;
            Entity sum = Number.Integer.Zero;
            var oneMinusSSquared = 1 - MathS.Sqr(s);
            foreach (var pair in inW)
            {
                if (pair.Key.Sign < 0 || !pair.Key.IsEven || !pair.Key.CanFitInInt32())
                    return null;
                var half = pair.Key.ToInt32Unchecked() / 2;
                sum += half == 0 ? pair.Value : half == 1 ? pair.Value * oneMinusSSquared : pair.Value * MathS.Pow(oneMinusSSquared, half);
            }
            var expanded = sum.Expand().InnerSimplified;
            if (expanded is Providedf(var bare, _))
                expanded = bare;
            return TreeAnalyzer.TryGetPolynomial(expanded, s, out var read) && read.Keys.All(power => power.Sign >= 0) && read.Values.All(v => !v.ContainsNode(s) && !v.ContainsNode(w))
                ? expanded : null;
        }

        /// <summary>
        /// A fractional power of a constant times an even power of a function of x, the
        /// function taken out of the power with its sign: <c>(a sin(x)^2)^(5/2)</c> is
        /// <c>a^(5/2) |sin(x)|^5</c>, which is <c>a^(5/2) sgn(sin(x)) sin(x)^5</c> -- the sign
        /// a constant between the sine's zeros, carried through the integration as a symbol
        /// and written back. Rubi's <c>x sqrt(sin(x)^2)</c> is <c>sgn(sin(x)) (sin(x) - x cos(x))</c>
        /// that way, and <c>1/(csc(x)^2)^(7/2)</c> is <c>sgn(csc(x))</c> times the seventh power
        /// of the sine, where the substitutions read the root of the square as a modulus and
        /// answered in powers of it.
        /// </summary>
        /// <remarks>
        /// An even power of a real function is not negative, so <c>(c q)^p = c^p q^p</c> holds
        /// for the principal powers whatever <c>c</c> is, and <c>(f^(2k))^p</c> is <c>|f|^(2kp)</c>.
        /// Whole products of the exponents only, so that what is handed on is a whole power of
        /// the function; a polynomial radicand is the rule above's, which comes first. At the
        /// top only, as there: a substitution's variable is one it knows the sign of, and a
        /// sign written for it is one nothing differentiates.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTakingAFunctionOutOfAPowerOfItsEvenPower(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            Entity signs = Number.Integer.One;
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(x))
                    return node;
                // The radicand read as a constant times even whole powers of functions of x,
                // each power whole once multiplied by the exponent; anything else is not this
                // rule's.
                Entity constant = Number.Integer.One;
                var functions = new List<(Entity function, EInteger power)>();
                var top = radicand;
                if (radicand is Divf(var above, var below) && !below.ContainsNode(x))
                {
                    constant = Number.Integer.One / below;
                    top = above;
                }
                foreach (var factor in Mulf.LinearChildren(top))
                {
                    if (!factor.ContainsNode(x))
                    {
                        constant = constant * factor;
                        continue;
                    }
                    // A real function: a fractional power of one is not, where its base is
                    // negative, and its even power is then not the square of a modulus.
                    if (factor is not Powf(var function, Number.Integer degree) || !degree.EInteger.IsEven || degree.EInteger.Sign <= 0
                        || TreeAnalyzer.TryGetPolynomial(function, x, out _) || function is Powf(_, not Number.Integer))
                        return node;
                    var product = exponent.ERational.Multiply(ERational.FromEInteger(degree.EInteger)).ToLowestTerms();
                    if (!product.Denominator.Equals(EInteger.One))
                        return node;
                    functions.Add((function, product.Numerator));
                }
                if (functions.Count == 0)
                    return node;
                Entity outside = constant == Number.Integer.One ? Number.Integer.One : MathS.Pow(constant, exponent);
                foreach (var (function, power) in functions)
                {
                    // |f|^n is f^n for an even n and sgn(f) f^n for an odd one.
                    if (!power.IsEven)
                        signs = signs * MathS.Signum(function);
                    outside = outside * MathS.Pow(function, Number.Integer.Create(power));
                }
                return outside;
            });
            if (rewritten == expr)
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(rewritten, x, integrateByParts) is not { } result)
                return null;
            var answer = signs == Number.Integer.One ? result : signs * result;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// A denominator factor that is a sum or difference of two square roots of
        /// polynomials, multiplied above and below by its conjugate:
        /// <c>(1 + x)/(sqrt(x^2 + 2x + 4) - sqrt(x^2 + x + 1))</c> is
        /// <c>(1 + x)(sqrt(x^2 + 2x + 4) + sqrt(x^2 + x + 1))/(x + 3)</c>, the product of the
        /// pair being the difference of the radicands -- and each of the two terms is then a
        /// root of a quadratic beside a rational function, Euler's. Timofeev's.
        /// </summary>
        /// <remarks>
        /// Two roots only: a polynomial beside one root, <c>x + sqrt(x^2 + 1)</c>, is Euler's
        /// substitution itself, and answered more shortly as that. The conjugate is nonzero
        /// wherever the factor is, and <c>(a - b)(a + b) = a^2 - b^2</c> holds for the
        /// principal roots as for any values, so nothing is assumed about signs. Once: the
        /// respelling has no such factor left.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByRationalisingASumOfRoots(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator) || !denominator.ContainsNode(x))
                return null;
            Entity? conjugate = null;
            Entity? product = null;
            Entity rest = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(denominator))
            {
                if (conjugate is null && factor is Sumf or Minusf && Sumf.LinearChildren(factor).ToList() is { Count: 2 } terms
                    && terms.All(term => IsARootOfAPolynomial(term)))
                {
                    // The conjugate flips the sign of the second term; the product is the
                    // difference of the squares, each square a polynomial.
                    var first = terms[0];
                    var second = terms[1];
                    conjugate = first - second;
                    product = (SquareOf(first) - SquareOf(second)).InnerSimplified;
                    // Not the same radicand twice: the difference is zero, the factor is zero
                    // or a multiple of one root, and neither is this rule's.
                    if (product.Evaled is Number.Complex { IsZero: true } || product.Simplify().Evaled is Number.Complex { IsZero: true })
                        return null;
                    continue;
                }
                rest = rest * factor;
            }
            if (conjugate is null || product is null)
                return null;
            var respelled = Functions.PartialFractions.Bare(numerator * conjugate / (product * rest));
            return Integration.ComputeAsAQuestionOfItsOwn(respelled, x, integrateByParts);

            // The radicand need not be a polynomial in x: Timofeev's
            // `cos(3x)/(sqrt(3 cos(x)^2 - sin(x)^2) - sqrt(8 cos(x)^2 - 1))` has the difference
            // of the radicands, `4 cos(x)^2` by Pythagoras, below once it is respelled, and
            // each root beside it is a root of a quadratic in the sine under `u = sin(x)`.
            bool IsARootOfAPolynomial(Entity term)
            {
                var (coefficient, root) = term is Mulf(var l, var r) && !l.ContainsNode(x) ? (l, r) : (Number.Integer.One as Entity, term);
                return root is Powf(var radicand, Number.Rational half) && half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                    && half.ERational.Numerator.Equals(EInteger.One) && radicand.ContainsNode(x)
                    && !coefficient.ContainsNode(x);
            }

            Entity SquareOf(Entity term)
            {
                var (coefficient, root) = term is Mulf(var l, var r) && !l.ContainsNode(x) ? (l, r) : (Number.Integer.One as Entity, term);
                return root is Powf(var radicand, Number.Rational half) && half.ERational.Numerator.Equals(EInteger.One) && half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                    ? MathS.Sqr(coefficient) * radicand
                    : MathS.Sqr(term);
            }
        }

        /// <summary>
        /// Two square roots of linears with one slope, <c>sqrt(L1)</c> and <c>sqrt(L2)</c> with
        /// <c>L1 - L2 = k</c> a constant, rationalised together by their sum
        /// <c>v = sqrt(L1) + sqrt(L2)</c>: their difference is <c>k/v</c>, so
        /// <c>sqrt(L1) = (v + k/v)/2</c>, <c>sqrt(L2) = (v - k/v)/2</c>, and
        /// <c>dx = (v^4 - k^2)/(2 m v^3) dv</c> for the slope <c>m</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Charlwood's <c>arcsin(sqrt(1 + x) - sqrt(x))</c> is <c>arcsin(1/v) (v^4 - 1)/(2 v^3)</c>,
        /// which parts closes. Asked as written, the remainder parts leaves in x is a nested root
        /// no rule reads, and it was declined after five seconds, and after sixty on a slow
        /// runner. Rubi's 5.3.7 has the arctangent's powers of x beside it.
        /// </para>
        /// <para>
        /// The identities hold for the principal roots wherever v is not zero: the sum times the
        /// difference is <c>L1 - L2</c> for any values of the two, so nothing is assumed about
        /// signs. At the question asked or one below it, since it lands on the chain in v.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveBySubstitutingTheSumOfTwoRootsOfLinears(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            // Exactly two radicands under half-odd powers, each linear, with one slope.
            var radicands = new List<Entity>();
            foreach (var node in expr.Nodes)
                if (node is Powf(var @base, Number.Rational power) && power is not Number.Integer && @base.ContainsNode(x))
                {
                    if (!power.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !power.ERational.Numerator.CanFitInInt32())
                        return null;
                    if (!radicands.Contains(@base))
                        radicands.Add(@base);
                }
            if (radicands.Count != 2
                || !TreeAnalyzer.TryGetPolyLinear(radicands[0], x, out var m1, out var n1)
                || !TreeAnalyzer.TryGetPolyLinear(radicands[1], x, out var m2, out var n2)
                || VanishesIdentically(m1) || !VanishesIdentically(m1 - m2) || VanishesIdentically(n1 - n2))
                return null;
            // Only where the sum or the difference of the two roots stands inside an inverse
            // trigonometric function or a logarithm, which nothing else reads. A rational function
            // of the roots is the radical rules' already: asked here first,
            // `x^2/(sqrt(a + b x) + sqrt(c + b x))` ran out its budget where the conjugate answers it
            // in 37 ms, and so did `sqrt(x - 1) sqrt(x + 1)/(1 + x - x^2)`, which the quotient of the
            // two roots answers in 244 ms, and Timofeev's `arccos(sqrt(x/(1 + x)))`, a quotient of
            // the two roots under the function.
            if (!expr.Nodes.Any(node => node is Arcsinf or Arccosf or Arctanf or Arccotanf or Arcsecantf or Arccosecantf or Logf
                    && node.Nodes.Any(inner => SignOfTheTwoRoots(inner, radicands) != (0, 0))))
                return null;
            var k = (n1 - n2).InnerSimplified;
            var v = Variable.CreateUnique(expr, "v_roots");
            var roots = new[] { (v + k / v) / 2, (v - k / v) / 2 };
            // The sum is v and the difference k/v, taken whole first so that the rules in v see
            // `arcsin(1/v)` rather than the difference of the two roots written in v.
            var inV = expr.Replace(node => SignOfTheTwoRoots(node, radicands) switch
            {
                (1, 1) => v,
                (1, -1) => k / v,
                (-1, 1) => -k / v,
                _ => node,
            });
            inV = inV.Replace(node => node is Powf(var @base, Number.Rational power) && power is not Number.Integer
                    && radicands.IndexOf(@base) is var index and >= 0
                ? MathS.Pow(roots[index], Number.Integer.Create(power.ERational.Numerator))
                : node);
            // Everything else in x through the second root: x = ((v - k/v)^2/4 - n2)/m.
            inV = (inV.Substitute(x, (MathS.Sqr(roots[1]) - n2) / m1) * (MathS.Pow(v, 4) - MathS.Sqr(k)) / (2 * m1 * MathS.Pow(v, 3))).InnerSimplified;
            if (inV.ContainsNode(x) || inV.Nodes.Any(node => node == MathS.NaN))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(inV, v, integrateByParts) is not { } inTermsOfV)
                return null;
            // v is positive wherever the integrand is real: a sum of two principal roots of
            // reals, not both zero since their squares differ. Its sign is one, and a reciprocal
            // of it is the difference over k, written back so.
            var sum = MathS.Sqrt(radicands[0]) + MathS.Sqrt(radicands[1]);
            var difference = (MathS.Sqrt(radicands[0]) - MathS.Sqrt(radicands[1])) / k;
            var answer = inTermsOfV.Replace(node => node switch
            {
                Signumf(var signed) when signed == v => Number.Integer.One,
                Absf(var measured) when measured == v => v,
                Divf(var above, var below) when below == v => above * difference,
                Powf(var @base, Number.Integer { EInteger.Sign: < 0 } power) when @base == v => MathS.Pow(difference, (-power).InnerSimplified),
                _ => node,
            }).Substitute(v, sum).InnerSimplified;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// (1, 1) where <paramref name="node"/> is the sum of the two roots, (1, -1) the first less
        /// the second, (-1, 1) the second less the first, and (0, 0) otherwise.
        /// </summary>
        private static (int, int) SignOfTheTwoRoots(Entity node, List<Entity> radicands)
        {
            if (node is not (Sumf or Minusf))
                return (0, 0);
            var terms = Sumf.LinearChildren(node).ToList();
            if (terms.Count != 2)
                return (0, 0);
            var signs = new int[2];
            foreach (var term in terms)
            {
                var (sign, root) = term switch
                {
                    Mulf(Number.Integer { EInteger: var minusOne }, var rest) when minusOne.Equals(EInteger.FromInt32(-1)) => (-1, rest),
                    _ => (1, term),
                };
                if (root is not Powf(var @base, Number.Rational half) || half != Number.Rational.Create(1, 2)
                    || radicands.IndexOf(@base) is not (var index and >= 0) || signs[index] != 0)
                    return (0, 0);
                signs[index] = sign;
            }
            return (signs[0], signs[1]);
        }

        internal static Entity? SolveByCombiningRadicals(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // A secant or cosecant under a root is the reciprocal of a cosine or sine there:
            // `sqrt(sec(x)^4 - 1)` is a root of `(1 - cos(x)^4)/cos(x)^4`, a quotient whose
            // denominator is an even power, and comes apart as `sqrt(1 - cos(x)^4)/cos(x)^2`;
            // as written it is a root of a sum of secants that no rule reads.
            if (expr.Nodes.Any(node => node is Powf(var radicalBase, Number.Rational r) && r is not Number.Integer
                    && radicalBase.Nodes.Any(inner => inner is Secantf or Cosecantf)))
                expr = expr.Replace(node => node switch
                {
                    Secantf(var argument) => 1 / MathS.Cos(argument),
                    Cosecantf(var argument) => 1 / MathS.Sin(argument),
                    _ => node,
                });
            // Two square roots holding the variable, or there is nothing to combine; counted
            // before any of the rewriting below is paid for, since this runs on every
            // sub-integrand of the chain.
            // A root of a quotient counts as the two roots it splits into -- a sum with a
            // quotient in it, `1/cos(x)^4 - 1`, being a quotient once combined.
            if (expr.Nodes.Sum(node => node is Powf(var @base, Number.Rational half)
                    && half is not Number.Integer && half.ERational.Denominator.Equals(EInteger.FromInt32(2))
                    && @base.ContainsNode(x)
                        ? (@base is Divf || Functions.SingleQuotient.Of(AsOneQuotient(@base)).Denominator != Number.Integer.One ? 2 : 1)
                        : 0) < 2)
                return null;
            var rewritten = CombineRadicalsIn(expr, x);
            // The rewriting is exact and the rewritten integrand is the question asked in
            // another spelling, so at the top it is asked as one: the rules scoped to the
            // question -- the parity extension under a substitution, for one, which
            // `sec(x)/sqrt(sec(x)^4 - 1)` needs after the secant is written as a cosine here --
            // answer it then and not one level down.
            if (rewritten != expr
                && (Integration.AnsweringTheQuestionAsked
                    ? Integration.ComputeAsAQuestionOfItsOwn(rewritten, x, integrateByParts)
                    : Integration.ComputeIndefiniteIntegral(rewritten, x, integrateByParts)) is { } answer)
                return answer;
            // Two roots that combine only up to a sign, `sqrt(x - 1) sqrt(x + 1)`: the sign is
            // a constant between the real roots of the bases and goes in front of the
            // integral, at the top, where the answer is the caller's. After the exact
            // rewriting has had its turn, since a quotient with those two roots below may be
            // answered by the cancellation alone -- Hearn's
            // `(5x^4 sqrt(1 + x^3) - 3x^2 sqrt(1 - 2x + x^5) - 2 sqrt(1 + x^3))/(2 sqrt(1 + x^3) sqrt(1 - 2x + x^5))`
            // is, and combined under one root with the sign in front it ran the budget out;
            // so only where the one root is the only one left.
            if (Integration.AnsweringTheQuestionAsked && expr is Mulf or Divf
                && CombineRadicalsInAQuotient(SplitRootsOfQuotientsIn(expr, x), x, out var sign, withASign: true) is { } signed
                && sign is not null
                && signed.Nodes.Where(node => node is Powf(var @base, Number.Rational r) && r is not Number.Integer && @base.ContainsNode(x))
                    .Select(node => ((Powf)node).Base).Distinct().Count() == 1
                && Integration.ComputeAsAQuestionOfItsOwn(signed, x, integrateByParts) is { } result
                && !result.Nodes.Any(node => node == MathS.NaN))
                return sign * result;
            return null;
        }

        /// <summary>
        /// Every product or quotient in <paramref name="expr"/> with its square roots of
        /// polynomials combined into one, innermost first; and a small power of a sum holding
        /// such a root written out first, since <c>(sqrt(1 - x) + sqrt(1 + x))^2</c> is
        /// <c>2 + 2 sqrt(1 - x) sqrt(1 + x)</c>, which combines, and is not a shape any rule
        /// reads as it stands.
        /// </summary>
        private static Entity CombineRadicalsIn(Entity expr, Entity.Variable x)
            => SplitRootsOfQuotientsIn(expr, x).Replace(node => node is Mulf or Divf ? CombineRadicalsInAQuotient(node, x, out _) ?? node : node);

        /// <summary>
        /// Every root of a quotient of polynomials in <paramref name="expr"/> written as a
        /// quotient of roots, where that is exact: <c>sqrt(P/Q) = sqrt(P)/sqrt(Q)</c> on the
        /// principal branch unless <c>Q &lt; 0 &lt; P</c>, where the left is <c>i sqrt(P/|Q|)</c>
        /// and the right <c>-i sqrt(P/|Q|)</c> -- with both negative the two <c>i</c>s cancel and
        /// with <c>P</c> negative alone they agree. So the rule asks whether there is a real
        /// <c>x</c> with <c>Q(x) &lt; 0 &lt; P(x)</c>, on one point of each interval between the
        /// real roots, and splits only where there is not.
        /// </summary>
        /// <remarks>
        /// Charlwood's <c>arcsin(x/sqrt(1 - x^2))</c> by parts against one leaves
        /// <c>x (1 - x^2)^(-3/2)/sqrt((1 - 2x^2)/(1 - x^2))</c>, a root of a quotient that no
        /// rule reads; split, it is <c>x/((1 - x^2) sqrt(1 - 2x^2))</c>, which Euler answers.
        /// <c>1 - x^2 &lt; 0</c> only past <c>1</c>, where <c>1 - 2x^2</c> is negative too.
        /// </remarks>
        private static Entity SplitRootsOfQuotientsIn(Entity expr, Entity.Variable x)
            => expr.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Rational power) || power is Number.Integer
                    || !power.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !@base.ContainsNode(x))
                    return node;
                var (above, below) = Functions.SingleQuotient.Of(AsOneQuotient(@base));
                if (below == Number.Integer.One || !below.ContainsNode(x))
                    return node;
                // A denominator that is an even power of anything real is not negative, so the
                // split is exact whatever the numerator, and the root of the denominator is a
                // whole power where the exponents allow: `sqrt(N/cos(x)^4)` is `sqrt(N)/cos(x)^2`.
                if (Mulf.LinearChildren(below).All(factor => !factor.ContainsNode(x)
                        || factor is Powf(_, Number.Integer even) && even.EInteger.IsEven && even.EInteger.Sign > 0)
                    && power.ERational.Numerator.CanFitInInt32())
                {
                    var p = power.ERational.Numerator.ToInt32Unchecked();
                    Entity rootOfBelow = Number.Integer.One;
                    var whole = true;
                    foreach (var factor in Mulf.LinearChildren(below))
                    {
                        if (!factor.ContainsNode(x))
                        {
                            rootOfBelow *= MathS.Pow(factor, power);
                            continue;
                        }
                        var (f, twoK) = ((Powf)factor).DirectChildren is var children ? (children[0], ((Number.Integer)children[1]).EInteger.ToInt32Unchecked()) : default;
                        // (f^(2k))^(p/2) = |f|^(k p), and f^(k p) only for an even k p.
                        if ((twoK / 2 * p) % 2 != 0)
                        {
                            whole = false;
                            break;
                        }
                        rootOfBelow *= MathS.Pow(f, twoK / 2 * p);
                    }
                    if (whole)
                        return MathS.Pow(above, power) / rootOfBelow;
                }
                if (!TreeAnalyzer.TryGetPolynomial(above, x, out var aboveRead) || !TreeAnalyzer.TryGetPolynomial(below, x, out var belowRead)
                    || above.Vars.Any(v => v != x) || below.Vars.Any(v => v != x))
                    return node;
                // Quadratics at most on either side: those are what the rules behind this read,
                // and a root of a sextic set free is a search that ends nowhere --
                // `sin(x)/sqrt(1 - sin(x)^6)` under the tangent is one, and went from a
                // twenty-millisecond decline to a twenty-second one.
                static int Degree(Dictionary<EInteger, Entity> read) => read.Count == 0 ? 0 : read.Keys.Max()!.ToInt32Checked();
                if (Degree(aboveRead) > 2 || Degree(belowRead) > 2)
                    return node;
                // Kept as written, so that the base of the root below matches the same base
                // written beside it as a whole power, for the gathering that follows.
                if (!OnEveryRealInterval(new List<Entity> { above, below }, x, signs => !(signs[1] < 0 && signs[0] > 0)))
                    return node;
                return MathS.Pow(above, power) / MathS.Pow(below, power);
            });

        /// <summary>
        /// <paramref name="expr"/> as one quotient where it is a sum with a quotient among its
        /// terms -- <c>1/cos(x)^4 - 1</c> is <c>(1 - cos(x)^4)/cos(x)^4</c> -- and as it is
        /// otherwise, so that the combining is paid for only where it changes anything.
        /// </summary>
        private static Entity AsOneQuotient(Entity expr)
        {
            if (expr is not (Sumf or Minusf) || !Sumf.LinearChildren(expr).Any(term => term is Divf || term is Powf(_, Number.Integer { IsNegative: true })))
                return expr;
            // The numerator the combining writes, `1 - (1 - u^2)` for `1/(1 - u^2) - 1`, as the
            // polynomial it is, `u^2`: the even power of u below is read as written, and was
            // not read there -- Timofeev's `(tan(x) tan(2x))^(3/2)` under the tangent.
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            return above.Expand().InnerSimplified / below;
        }

        /// <summary>
        /// A factor of a product that is a small power of a sum holding a square root of a
        /// polynomial, written out and combined; any other factor as it is. Only as a factor:
        /// the same power under a root, `sqrt(1 - (sqrt(1 + x) - sqrt(x))^2)`, written out is
        /// a root of a sum with a root in it, no better than before and a search of its own.
        /// </summary>
        private static Entity WriteOutAPowerOfASumOfRadicals(Entity factor, Entity.Variable x)
        {
            if (factor is not Powf(Sumf or Minusf, Number.Integer power) || !power.EInteger.CanFitInInt32())
                return factor;
            var n = power.EInteger.ToInt32Unchecked();
            if (n is < 2 or > 4)
                return factor;
            var sum = factor.DirectChildren.First();
            if (!sum.Nodes.Any(node => TryReadASquareRootOfAPolynomial(node, x, out _, out _)))
                return factor;
            return CombineRadicalsIn(MathS.Pow(sum, n).Expand().InnerSimplified, x);
        }

        /// <summary>
        /// The product or quotient <paramref name="expr"/> with its two or more square roots of
        /// polynomials written as one, or <see langword="null"/> where there are fewer than two
        /// or the identity does not hold for them.
        /// </summary>
        private static Entity? CombineRadicalsInAQuotient(Entity expr, Entity.Variable x, out Entity? signInFront, bool withASign = false)
        {
            signInFront = null;
            // As one quotient, with a negative half-power read as the root it is below the bar,
            // and a sum factor above the bar cancelled against the same sum below it. That is
            // the derivative of `ln(x + sqrt(x^2 - 1))` as differentiation writes it,
            // `(1 + x/sqrt(x^2 - 1))/(x + sqrt(x^2 - 1))`, brought to the `1/sqrt(x^2 - 1)` it
            // is; by parts left it in the first spelling and nothing read it.
            var asQuotient = expr.Replace(node =>
                node is Powf(var @base, Number.Rational power) && power is not Number.Integer && power.ERational.Sign < 0
                    ? Number.Integer.One / MathS.Pow(@base, Number.Rational.Create(power.ERational.Negate()))
                    : node);
            var (numerator, denominator) = Functions.SingleQuotient.Of(asQuotient);
            var writtenOut = false;
            Entity WrittenOut(Entity side)
            {
                Entity built = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var written = WriteOutAPowerOfASumOfRadicals(factor, x);
                    writtenOut |= written != factor;
                    built = built == Number.Integer.One ? written : built * written;
                }
                return built;
            }
            numerator = WrittenOut(numerator);
            denominator = WrittenOut(denominator);
            var cancelled = CancelEqualSumFactors(numerator, denominator, out numerator, out denominator) | writtenOut;

            // Every factor with an odd half-power of a polynomial base is a whole power of the
            // base times one square root of it; the square roots are what combine. A whole
            // power of the same base, written beside it, is gathered in first: `P * P^(-1/2)`
            // is `P^(1/2)` exactly, since a whole power combines with any principal power of
            // the same base -- `(1 - x^2) sqrt(1 - 2x^2)/sqrt(1 - x^2)` is
            // `sqrt(1 - x^2) sqrt(1 - 2x^2)`, and what a root of a quotient splits into is
            // often beside its own base that way.
            var bases = new List<Entity>();
            Entity above = Number.Integer.One;
            Entity below = Number.Integer.One;
            var halves = new Dictionary<Entity, int>();      // base -> exponent in halves
            var halfExponents = new Dictionary<Entity, int>();
            var others = new List<(Entity Factor, bool Below)>();
            var gathered = false;
            foreach (var (side, isBelow) in new[] { (numerator, false), (denominator, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var sign = isBelow ? -1 : 1;
                    if (TryReadASquareRootOfAPolynomial(factor, x, out var @base, out var wholePower))
                    {
                        gathered |= halves.ContainsKey(@base);
                        halves[@base] = halves.TryGetValue(@base, out var so) ? so + sign * (2 * wholePower + 1) : sign * (2 * wholePower + 1);
                    }
                    else if (factor is Powf(var b, Number.Integer k) && k.EInteger.CanFitInInt32() && halves.ContainsKey(b))
                    {
                        halves[b] += sign * 2 * k.EInteger.ToInt32Unchecked();
                        gathered = true;
                    }
                    else if (factor.ContainsNode(x) && halves.ContainsKey(factor))
                    {
                        halves[factor] += sign * 2;
                        gathered = true;
                    }
                    else
                        others.Add((factor, isBelow));
                }
            // A whole power read before its root came: gathered on a second pass.
            foreach (var (factor, isBelow) in others.ToList())
            {
                var sign = isBelow ? -1 : 1;
                if (factor is Powf(var b, Number.Integer k) && k.EInteger.CanFitInInt32() && halves.ContainsKey(b))
                {
                    halves[b] += sign * 2 * k.EInteger.ToInt32Unchecked();
                    others.Remove((factor, isBelow));
                    gathered = true;
                }
                else if (factor.ContainsNode(x) && halves.ContainsKey(factor))
                {
                    halves[factor] += sign * 2;
                    others.Remove((factor, isBelow));
                    gathered = true;
                }
            }
            // **Over the irreducible factors**, where that cancels something: `sqrt(1 - x^4)`
            // over `sqrt(1 - x^2)` -- what by parts leaves from `x^3 arcsin(x)/sqrt(1 - x^4)` --
            // is `sqrt(1 + x^2)`, and the two roots as written share nothing. Each base with
            // an odd exponent is factored over the rationals, with the constant folded into
            // the first factor so that no `sqrt(-1)` is set free, and the root split over the
            // factors where that is exact -- at most one of them negative anywhere on the
            // reals; the whole polynomial factors beside them are factored the same way. The
            // refinement is kept only where it leaves fewer roots than it found, since
            // otherwise it only respells the integrand.
            if (TryRefineOverIrreducibleFactors(halves, others, x) is var (refinedHalves, refinedOthers))
            {
                halves = refinedHalves;
                others = refinedOthers;
                gathered = true;
            }
            foreach (var (factor, isBelow) in others)
                if (isBelow) below = below * factor;
                else above = above * factor;
            foreach (var pair in halves)
            {
                var n = pair.Value;
                if (n % 2 == 0)
                {
                    // A whole power after all: no root left of this base.
                    var whole = n / 2;
                    if (whole > 0) above = above * MathS.Pow(pair.Key, whole);
                    else if (whole < 0) below = below * MathS.Pow(pair.Key, -whole);
                    continue;
                }
                bases.Add(pair.Key);
                halfExponents[pair.Key] = n;
            }
            // Roots above and below the bar that do not combine as a product may combine as
            // the quotient they are: `sqrt(x^4 - 1)/sqrt(x^2 - 1)` has two negative bases inside
            // the unit interval, where `sqrt(P) sqrt(Q)` is `-sqrt(PQ)`, and is `sqrt(x^2 + 1)`
            // there all the same, since the two `i`s cancel in a quotient. Taken only where the
            // quotient under the one root cancels to a polynomial, so that what is handed on
            // has strictly fewer roots than what came in.
            // The signs of the bases on the intervals between their real roots, found once
            // for both questions: the roots are a solve per base, and asking twice on every
            // sub-integrand of a search that declines was three seconds of one.
            var signTable = bases.Count >= 2 ? SignsOnEveryRealInterval(bases, x) : null;
            var combineAsAProduct = signTable is not null && signTable.All(signs => signs.Count(sign => sign < 0) <= 1);
            // Two roots whose bases are both negative somewhere: `sqrt(x - 1) sqrt(x + 1)` is
            // `sqrt(x^2 - 1)` past 1 and `-sqrt(x^2 - 1)` before -1, the two `i`s multiplying
            // to -1. So `sqrt(P) sqrt(Q)` is `s sqrt(P Q)` with `s = (1 + sgn P + sgn Q - sgn P sgn Q)/2`,
            // which is -1 where both are negative and 1 elsewhere -- exactly, on every real
            // x -- and the same `s` serves the reciprocals and the quotient, being its own
            // reciprocal. The sign is a constant between the real roots of the bases, so it
            // goes in front of the integral; at the top only, where the caller can put it
            // there.
            if (withASign && !combineAsAProduct && bases.Count == 2 && signTable is not null
                && signTable.Any(signs => signs.All(s => s < 0)))
            {
                var (first, second) = (MathS.Signum(bases[0]), MathS.Signum(bases[1]));
                signInFront = (1 + first + second - first * second) / 2;
                combineAsAProduct = true;
            }
            if (bases.Count >= 2 && signTable is not null && !combineAsAProduct
                && CombinedAsAQuotient(bases, halfExponents, signTable, x) is { } asOneRoot)
            {
                var (rootOfAPolynomial, rest) = asOneRoot;
                // One root of each base is in the quotient; n = 2q + 1 above and n = 2q - 1 below.
                foreach (var @base in bases)
                {
                    var n = halfExponents[@base];
                    var q = n > 0 ? (n - 1) / 2 : (n + 1) / 2;
                    if (q > 0) above = above * MathS.Pow(@base, q);
                    else if (q < 0) below = below * MathS.Pow(@base, -q);
                }
                return Functions.PartialFractions.Bare(Functions.PartialFractions.Bare(above * rootOfAPolynomial * rest) / Functions.PartialFractions.Bare(below));
            }
            if (bases.Count < 2 || !combineAsAProduct)
            {
                // Nothing to combine, or roots that must not be: what was cancelled or
                // gathered is still worth handing on, each root on its own -- as the one
                // power `P^(n/2)` it is, since `sqrt(P)/P` beside a logarithm of `x + sqrt(P)` is
                // not the `1/sqrt(P)` the substitution for that logarithm reads.
                if (!cancelled && !gathered)
                    return null;
                foreach (var @base in bases)
                {
                    var n = halfExponents[@base];
                    if (n > 0) above = above * MathS.Pow(@base, Number.Rational.Create(n, 2));
                    else below = below * MathS.Pow(@base, Number.Rational.Create(-n, 2));
                }
                bases.Clear();
            }
            else
                foreach (var @base in bases)
                {
                    // n = 2q + 1 for every odd n, negative ones included: -1 = 2(-1) + 1.
                    var q = (halfExponents[@base] - 1) / 2;
                    if (q > 0) above = above * MathS.Pow(@base, q);
                    else if (q < 0) below = below * MathS.Pow(@base, -q);
                }

            Entity radical = Number.Integer.One;
            if (bases.Count > 0)
            {
                Entity product = Number.Integer.One;
                foreach (var @base in bases)
                    product = product * @base;
                radical = MathS.Sqrt(product.Expand().InnerSimplified);
            }
            var rewritten = ((above * radical).InnerSimplified / below.InnerSimplified).InnerSimplified;
            return rewritten is Providedf(var inner, _) ? inner : rewritten;
        }

        /// <summary>
        /// The bases with an odd exponent in halves, and the whole polynomial factors beside
        /// them, taken into their irreducible factors over the rationals and gathered again
        /// by factor; <see langword="null"/> where that leaves no fewer roots than it found.
        /// </summary>
        private static (Dictionary<Entity, int> Halves, List<(Entity Factor, bool Below)> Others)? TryRefineOverIrreducibleFactors(
            Dictionary<Entity, int> halves, List<(Entity Factor, bool Below)> others, Entity.Variable x)
        {
            if (!halves.Values.Any(n => n % 2 != 0))
                return null;
            var refined = new Dictionary<Entity, int>();
            var keptOthers = new List<(Entity Factor, bool Below)>();
            void Add(Entity factor, int n) => refined[factor] = refined.TryGetValue(factor, out var so) ? so + n : n;
            foreach (var pair in halves)
            {
                // The constant goes into whichever factor lets the split be exact: `1 - x^4` is
                // `-(x + 1)(x - 1)(x^2 + 1)`, and with the sign on `x + 1` two factors are
                // negative inside the unit interval, where with it on `x - 1` -- `(1 - x)` --
                // at most one is anywhere.
                var placements = IrreducibleFactorsWithTheSignPlaced(pair.Key, x);
                List<Entity>? parts = null;
                if (placements is not null && placements.Count > 0 && placements[0].Count > 1)
                    parts = pair.Value % 2 == 0
                        ? placements[0]
                        : placements.FirstOrDefault(candidate => AtMostOneIsNegativeOnTheReals(candidate, x));
                if (parts is null)
                {
                    Add(pair.Key, pair.Value);
                    continue;
                }
                foreach (var part in parts)
                    Add(part, pair.Value);
            }
            foreach (var (factor, isBelow) in others)
            {
                var (@base, power) = factor is Powf(var b, Number.Integer e) && e.EInteger.CanFitInInt32() && e.EInteger.Sign > 0
                    ? (b, e.EInteger.ToInt32Unchecked()) : (factor, 1);
                // A whole factor splits freely; the sign goes where it meets a root already read.
                var placements = @base.ContainsNode(x) ? IrreducibleFactorsWithTheSignPlaced(@base, x) : null;
                var parts = placements?.FirstOrDefault(candidate => candidate.Count(refined.ContainsKey) == candidate.Count)
                            ?? placements?.FirstOrDefault(candidate => candidate.Any(refined.ContainsKey));
                if (parts is null)
                {
                    keptOthers.Add((factor, isBelow));
                    continue;
                }
                foreach (var part in parts)
                    Add(part, (isBelow ? -2 : 2) * power);
            }
            var rootsBefore = halves.Values.Count(n => n % 2 != 0);
            var rootsAfter = refined.Values.Count(n => n % 2 != 0);
            return rootsAfter < rootsBefore ? (refined, keptOthers) : null;
        }

        /// <summary>
        /// The irreducible factors over the rationals of the polynomial <paramref name="polynomial"/>
        /// in <paramref name="x"/>, each repeated by its multiplicity, with the constant of the
        /// factorization multiplied into one of them -- one list per choice of which, so that
        /// the product is the polynomial exactly and a negative constant is never a factor of
        /// its own. <see langword="null"/> where it is not such a polynomial.
        /// </summary>
        private static List<List<Entity>>? IrreducibleFactorsWithTheSignPlaced(Entity polynomial, Entity.Variable x)
        {
            if (polynomial.Vars.Any(v => v != x))
                return null;
            if (Functions.PolynomialFactorization.FactorComplete(polynomial, x) is not { } factorization || factorization.Parts.Count == 0)
                return null;
            var parts = new List<Entity>();
            foreach (var part in factorization.Parts)
                for (var i = 0; i < part.Multiplicity; i++)
                    parts.Add(part.Factor.ToEntity(x));
            if (factorization.Constant.CompareTo(ERational.One) == 0)
                return new List<List<Entity>> { parts };
            var constant = Number.Rational.Create(factorization.Constant);
            var placements = new List<List<Entity>>();
            for (var i = 0; i < parts.Count; i++)
            {
                var placed = new List<Entity>(parts);
                placed[i] = (constant * parts[i]).InnerSimplified;
                placements.Add(placed);
            }
            return placements;
        }

        /// <summary>
        /// A sum that is a factor of both sides, cancelled -- decided by the difference
        /// simplifying to zero, since the two spellings of one sum need not be equal as
        /// written: `x + sqrt(1 + x^2)` against `sqrt(x^2 + 1) + x` is not zero as written,
        /// and where the cheap normalisation leaves it, the full one is asked, a by-parts
        /// remainder that keeps such a pair uncancelled costing ten seconds of substitution
        /// candidates otherwise. <see langword="true"/> when anything was cancelled.
        /// </summary>
        private static bool CancelEqualSumFactors(Entity numerator, Entity denominator, out Entity above, out Entity below)
        {
            var aboveFactors = Mulf.LinearChildren(numerator).ToList();
            var belowFactors = Mulf.LinearChildren(denominator).ToList();
            var cancelled = false;
            for (var i = 0; i < aboveFactors.Count; i++)
            {
                if (aboveFactors[i] is not (Sumf or Minusf))
                    continue;
                for (var j = 0; j < belowFactors.Count; j++)
                {
                    if (belowFactors[j] is not (Sumf or Minusf))
                        continue;
                    if ((aboveFactors[i] - belowFactors[j]).InnerSimplified.Evaled is Number.Complex { IsZero: true }
                        || (aboveFactors[i] - belowFactors[j]).Simplify().Evaled is Number.Complex { IsZero: true })
                    {
                        aboveFactors.RemoveAt(i);
                        belowFactors.RemoveAt(j);
                        i--;
                        cancelled = true;
                        break;
                    }
                }
            }
            above = aboveFactors.Count == 0 ? Number.Integer.One : aboveFactors.Aggregate((l, r) => l * r);
            below = belowFactors.Count == 0 ? Number.Integer.One : belowFactors.Aggregate((l, r) => l * r);
            return cancelled;
        }

        /// <summary>
        /// <c>P^(n/2)</c> with <c>n</c> odd and <c>P</c> a polynomial in <paramref name="x"/>
        /// with numeric coefficients, as <c>P^wholePower * sqrt(P)</c>.
        /// </summary>
        private static bool TryReadASquareRootOfAPolynomial(Entity factor, Entity.Variable x, out Entity @base, out int wholePower)
        {
            @base = 0;
            wholePower = 0;
            if (!TryReadAHalfPower(factor, out var candidate, out var numerator) || numerator % 2 == 0)
                return false;
            if (!candidate.ContainsNode(x) || candidate.Vars.Any(v => v != x))
                return false;
            if (!TreeAnalyzer.TryGetPolynomial(candidate, x, out _))
                return false;
            @base = candidate;
            // n = 2p + 1 for every odd n, negative ones included: -1 = 2(-1) + 1.
            wholePower = (numerator - 1) / 2;
            return true;
        }

        /// <summary>
        /// Whether no real <paramref name="x"/> makes two of the <paramref name="bases"/>
        /// negative at once, decided on one point of each interval between their real roots.
        /// <see langword="false"/> where the roots cannot be had.
        /// </summary>
        private static bool AtMostOneIsNegativeOnTheReals(List<Entity> bases, Entity.Variable x)
            => OnEveryRealInterval(bases, x, signs => signs.Count(sign => sign < 0) <= 1);

        /// <summary>
        /// The square roots with the bases <paramref name="bases"/>, those with a positive
        /// exponent in <paramref name="halfExponents"/> above the bar and the others below,
        /// written as one square root of the quotient of their bases, where that is exact and
        /// the quotient cancels to a polynomial: the root of that polynomial, and the rational
        /// function the cancellation left beside it; <see langword="null"/> otherwise.
        /// </summary>
        /// <remarks>
        /// With <c>a</c> of the bases above negative and <c>b</c> of those below, the left side is
        /// <c>i^a (1/i)^b = i^(a - b)</c> times the root of the moduli and the right is
        /// <c>i^((a + b) mod 2)</c> times it, so the identity holds exactly where
        /// <c>a - b</c> and <c>(a + b) mod 2</c> agree modulo four -- one negative on each side,
        /// or none, or two above beside one below. Asked on every interval between the real
        /// roots, as the product rule asks its own question.
        /// </remarks>
        private static (Entity Root, Entity Beside)? CombinedAsAQuotient(List<Entity> bases, Dictionary<Entity, int> halfExponents, List<List<int>> signTable, Entity.Variable x)
        {
            var aboveBases = bases.Where(b => halfExponents[b] > 0).ToList();
            var belowBases = bases.Where(b => halfExponents[b] < 0).ToList();
            if (aboveBases.Count == 0 || belowBases.Count == 0)
                return null;
            foreach (var signs in signTable)
            {
                var a = 0;
                var b = 0;
                for (var i = 0; i < bases.Count; i++)
                    if (signs[i] < 0)
                    {
                        if (halfExponents[bases[i]] > 0) a++;
                        else b++;
                    }
                if (((a - b) % 4 + 4) % 4 != (a + b) % 2)
                    return null;
            }
            Entity top = Number.Integer.One;
            Entity bottom = Number.Integer.One;
            foreach (var @base in aboveBases) top = top * @base;
            foreach (var @base in belowBases) bottom = bottom * @base;
            if (!Functions.PolynomialGcd.TryCancel(top.Expand().InnerSimplified, bottom.Expand().InnerSimplified, out var cancelled) || cancelled is null)
                return null;
            var (polynomial, remaining) = Functions.SingleQuotient.Of(Functions.PartialFractions.Bare(cancelled));
            if (remaining.ContainsNode(x) || !TreeAnalyzer.TryGetPolynomial(polynomial, x, out _))
                return null;
            // sqrt(P/c) for a constant c is sqrt(P)/sqrt(c), exactly, for c > 0; a negative c
            // is left under the root with the polynomial.
            if (remaining.Evaled is Number.Real { IsPositive: true })
                return (MathS.Sqrt(polynomial.InnerSimplified), 1 / MathS.Sqrt(remaining));
            return (MathS.Sqrt((polynomial / remaining).InnerSimplified), Number.Integer.One);
        }

        /// <summary>
        /// Whether <paramref name="holds"/> is true of the signs of the polynomials
        /// <paramref name="bases"/> on every interval between their real roots -- one point of
        /// each interval decides it, since no base changes sign inside one. <see langword="false"/>
        /// where the roots cannot be had.
        /// </summary>
        private static bool OnEveryRealInterval(List<Entity> bases, Entity.Variable x, System.Func<List<int>, bool> holds)
            => SignsOnEveryRealInterval(bases, x) is { } table && table.All(holds);

        /// <summary>
        /// <see cref="OnEveryRealInterval"/>, with the point of each interval the signs were read at.
        /// </summary>
        private static bool OnEveryRealIntervalAt(List<Entity> bases, Entity.Variable x, System.Func<double, List<int>, bool> holds)
            => SamplesAndSignsOnEveryRealInterval(bases, x) is { } table && table.All(row => holds(row.At, row.Signs));

        /// <summary>
        /// Whether <paramref name="expr"/> is decidedly not real at <paramref name="at"/>: its
        /// imaginary part, in interval arithmetic, excludes zero with every other symbol pinned
        /// to a positive value, to a negative one, and to each sign in turn. Where it cannot be
        /// evaluated nothing is decided, and it is not.
        /// </summary>
        private static bool NotRealAt(Entity expr, Entity.Variable x, double at)
        {
            var value = expr.Substitute(x, at);
            var symbols = value.Vars;
            for (var pattern = 0; pattern < symbols.Count switch { 0 => 1, 1 => 2, _ => 4 }; pattern++)
            {
                var pinned = value;
                for (var i = 0; i < symbols.Count; i++)
                {
                    var negative = pattern == 1 || pattern == 2 && i % 2 == 1 || pattern == 3 && i % 2 == 0;
                    pinned = pinned.Substitute(symbols[i], (negative ? -1 : 1) * (1.37 + 0.61 * i));
                }
                if (Numerics.IntervalEvaluation.Of(pinned) is not { IsFinite: true } interval || interval.Im.ContainsZero)
                    return false;
            }
            return true;
        }

        /// <summary>
        /// The signs of the polynomials <paramref name="bases"/>, one list per interval between
        /// their real roots, in the order of <paramref name="bases"/>; <see langword="null"/>
        /// where the roots cannot be had.
        /// </summary>
        private static List<List<int>>? SignsOnEveryRealInterval(List<Entity> bases, Entity.Variable x)
            => SamplesAndSignsOnEveryRealInterval(bases, x)?.Select(row => row.Signs).ToList();

        /// <summary>
        /// <see cref="SignsOnEveryRealInterval"/>, with the point of each interval the signs were
        /// read at.
        /// </summary>
        private static List<(double At, List<int> Signs)>? SamplesAndSignsOnEveryRealInterval(List<Entity> bases, Entity.Variable x)
        {
            var roots = new List<double>();
            foreach (var @base in bases)
            {
                if (MathS.SolveEquation(@base, x) is not Set.FiniteSet solutions)
                    return null;
                foreach (var solution in solutions.Elements)
                {
                    if (solution.Evaled is not Number.Complex value || !value.IsFinite)
                        return null;
                    if (System.Math.Abs((double)value.ImaginaryPart) < 1e-9)
                        roots.Add((double)value.RealPart);
                }
            }
            roots.Sort();
            var samples = new List<double>();
            if (roots.Count == 0)
                samples.Add(0.37);
            else
            {
                samples.Add(roots[0] - 1);
                samples.Add(roots[roots.Count - 1] + 1);
                for (var i = 0; i + 1 < roots.Count; i++)
                    if (roots[i + 1] - roots[i] > 1e-9)
                        samples.Add((roots[i] + roots[i + 1]) / 2);
            }
            var table = new List<(double At, List<int> Signs)>();
            foreach (var at in samples)
            {
                var signs = new List<int>();
                foreach (var @base in bases)
                {
                    if (@base.Substitute(x, at).Evaled is not Number.Real value || !value.IsFinite)
                        return null;
                    signs.Add(value < 0 ? -1 : value > 0 ? 1 : 0);
                }
                table.Add((at, signs));
            }
            return table;
        }

        /// <summary>
        /// A fractional power of a quotient whose denominator is positive for every real
        /// <paramref name="x"/> is written as the power of the numerator over the power of the
        /// denominator, a power of an even power of <c>x</c> among them as a power of <c>x</c>
        /// for <c>x &gt; 0</c>, and the integrand so written is asked of the chain; where a
        /// power of <c>x</c> was taken so, the answer is extended to <c>x &lt; 0</c> by parity.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>(P/Q)^r = P^r/Q^r</c> whenever <c>Q</c> is a positive real, since then
        /// <c>arg(P/Q) = arg(P)</c>; a polynomial in <c>x^2</c> with positive coefficients is one
        /// at every real <c>x</c> but zero, where the quotient was undefined anyway. Timofeev's
        /// <c>((2 + x^2)/x^2)^(7/9)/(2 + x^2)^(3/2)</c> is nothing any rule reads as written, and
        /// <c>x^(-14/9) (2 + x^2)^(7/9 - 3/2)</c> once the quotient is written apart, a binomial
        /// differential under <c>u = x^(1/9)</c>. The simplifier is right not to write it so
        /// for an <c>x</c> it knows nothing about; the integrator knows its variable is real.
        /// </para>
        /// <para>
        /// <c>(x^2)^(-7/9)</c> is <c>|x|^(-14/9)</c>, and is written as <c>x^(-14/9)</c>: what comes
        /// out is an antiderivative for <c>x &gt; 0</c>, made one everywhere by parity, which is
        /// exact, or not at all. Asked at the top and one level below it, where the remainder
        /// by parts leaves is asked, and no deeper, since it lands on the open chain.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAPowerOfAQuotientApart(Entity expr, Entity.Variable x)
        {
            // At the top and one below it, where the remainder by parts leaves is asked --
            // Charlwood's `x^3 arcsec(x)/sqrt(x^4 - 1)` leaves a root of `1 - 1/x^2` there --
            // and no deeper: unscoped, it fed the search on `arcsin(sqrt(1 + x) - sqrt(x))`,
            // thirty levels of the same root written apart and combined again, five seconds
            // where declining takes one.
            // ...except where every root written apart stands over a monomial in x, which is
            // the derivative of asech(c x) and acsch(c x) as they are written -- `1/(c x)^2 - 1`
            // over `c^2 x^2` -- and is a rewriting that lands on the root of a quadratic beside
            // `|c| |x|` and nothing else: the second step of parts on `x^3 asech(a x)^2` asks
            // for `x^2/sqrt(1/(a x)^2 - 1)` three levels down, and declined it there.
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow && !EveryRootStandsOverAMonomial(expr, x))
                return null;
            var tookAPowerOfX = false;
            // Whether every power of x taken is a whole one, and whether their sum is odd:
            // |x|^m for a whole m is sgn(x)^m x^m, which stands in for the extension by parity
            // where the integrand has none -- `1/(x^2 (d + e x) sqrt(1/(c x)^2 - 1))`, the
            // remainder by parts leaves from `asech(c x)/(d + e x)^2`, is neither even nor odd,
            // and was declined for that after its antiderivative had been found.
            var wholePowersOfX = true;
            var oddPowersOfX = false;
            // ...and only where every such power came from a root that is a factor of the
            // integrand: a sign can go in front of the answer for `|x|` that multiplied the
            // integrand, and not for one inside a sum or a logarithm's argument.
            var everyPowerOfXFromAFactor = true;
            // A parameter's even power taken for positive -- `c^2 x^2` below the bar, which is
            // how `acsch(c x)` and `asech(c x)` arrive, is positive for a real `c` -- and the
            // answer says so: `provided c^2 > 0`, which holds exactly for a real non-zero `c`.
            Entity assumed = Entity.Boolean.True;
            // The signs of the polynomials taken out of an even power below the bar, see
            // below: each is constant on every interval the answer is asked on, and goes in
            // front of the answer rather than into the question.
            var signs = new Dictionary<Entity, int>();
            // The factors of the integrand, above and below the bar: a sign can be taken in
            // front of the answer only from a power that is one of them, and not from one
            // inside a logarithm or a sum, where it is not a factor of anything.
            var factors = new HashSet<Entity>(
                TryReadAsQuotient(expr, out var dividend, out var divisor) ? Mulf.LinearChildren(dividend).Concat(Mulf.LinearChildren(divisor))
                : expr is Mulf ? Mulf.LinearChildren(expr)
                : new[] { expr });
            // A root inside the argument of a logarithm is left as it is: the logarithm is an
            // atom to every rule, whatever its argument is written as, and writing the root of
            // `asech(c x)` apart re-asked `(a + b asech(c x))/(d + e x)^2` whole for a second
            // and a half of nothing.
            var underALogarithm = new HashSet<Entity>(expr.Nodes.Where(node => node is Logf).SelectMany(log => ((Logf)log).Antilogarithm.Nodes));
            var written = expr.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer || !@base.ContainsNode(x) || underALogarithm.Contains(node))
                    return node;
                // As one quotient where it is a sum with a quotient in it: `1 - 1/x^2` is
                // `(x^2 - 1)/x^2`, the derivative of the arcsecant as it is written.
                var (above, below) = Functions.SingleQuotient.Of(AsOneQuotient(@base));
                if (below != Number.Integer.One && below.ContainsNode(x) && OfModestDegree(above)
                    && (IsPositiveForReal(below, x) || IsPositiveForARealParameter(below, x, out assumed, assumed)))
                {
                    if (!factors.Contains(node))
                        everyPowerOfXFromAFactor = false;
                    return MathS.Pow(above, exponent) * PowerOfAPositive(below, -exponent);
                }
                // An even power of a polynomial below the bar is positive wherever the
                // polynomial is real and not zero, which the answer states: `(A/P^2)^(1/2)` is
                // `sqrt(A) |P|^(-1)`, and `|P|` is `sgn(P) P`, the sign taken out in front.
                // `sqrt(1/(a + b x)^2 - 1)` is how the derivative of `asech(a + b x)` is
                // written, and by parts leaves `1/(x (a + b x)^2 sqrt(1/(a + b x)^2 - 1))`,
                // which is `sgn(a + b x)/(x (a + b x) sqrt(1 - (a + b x)^2))`, a rational
                // function beside the root of a quadratic. The power of `x` alone is the case
                // above, with its extension by parity; a linear in `x` has no parity to extend
                // by, and the sign is what stands in for it. Only for a power that is a factor
                // of the integrand: the same root inside the logarithm of `asech(a + b x)`
                // itself carries its sign inside the logarithm, where it is no factor.
                if (factors.Contains(node)
                    && below is Powf(var squared, Number.Integer { EInteger.IsEven: true } twice) && twice.EInteger.Sign > 0
                    && squared.ContainsNode(x) && OfModestDegree(above) && OfModestDegree(squared)
                    && TreeAnalyzer.TryGetPolynomial(squared, x, out var read) && read.Count > 1
                    && (twice * exponent).InnerSimplified is Number.Integer wholeTimes)
                {
                    var positive = new Greaterf(below, Number.Integer.Zero);
                    assumed = assumed == Entity.Boolean.True ? positive : assumed & positive;
                    if (!wholeTimes.EInteger.IsEven)
                        signs[squared] = signs.TryGetValue(squared, out var times) ? times + 1 : 1;
                    return MathS.Pow(above, exponent) * MathS.Pow(squared, -wholeTimes);
                }
                // A polynomial with rational roots is the product of its linear factors, and
                // the product is what the splitting below reads: `(1 - x^2)^(1/4)` is
                // `((1 - x)(1 + x))^(1/4)`, which comes apart on `(-1, 1)` where the root is
                // real, and beside `sqrt(1 - x)` and `sqrt(1 + x)` -- Timofeev's 314 -- the
                // two linear radicals are then one rule's. Only there: only where every
                // factor found already stands under a fractional power of its own elsewhere
                // in the integrand, so that the splitting joins what is written apart. For a
                // root of a quadratic on its own, `sqrt(1 - x^2)`, Euler's substitution and
                // the trigonometric one are the answer, and written apart it went to the
                // rule for two linear radicals and its rational function of a higher degree:
                // six more of the suite's problems timed out, Charlwood's 41, 92, 152 and 155
                // among them.
                if (above is not Mulf && TreeAnalyzer.TryGetPolynomial(above, x, out _)
                    && Functions.PolynomialFactoring.TryFactor(above, x, out var factoredAbove)
                    && Mulf.LinearChildren(factoredAbove).Where(factor => factor.ContainsNode(x)).ToList() is { Count: >= 2 } linearFactors
                    && linearFactors.All(factor => StandsUnderAFractionalPowerElsewhere(factor is Powf(var g, Number.Integer) ? g : factor, node)))
                    above = WithANegativeConstantInsideAFactor(factoredAbove);
                // A denominator with an odd power in it is the even part times what is left,
                // and the even part is not negative: `sqrt(sin(x)/cos(x)^5)` is
                // `sqrt(sin(x)/cos(x)) sqrt(1/cos(x)^4)`, which is `sqrt(tan(x))/cos(x)^2`
                // exactly -- Timofeev's, and the binomial rule's from there.
                // The degree bound is on what is left under the root, and where every
                // polynomial factor comes out nothing polynomial is left.
                var oddRoot = !exponent.ERational.Denominator.IsEven;
                var onlyWhereTheRootIsReal = false;
                var everyFactorComesOut = oddRoot || AnEvenRootOfAProductSplits(above, below, exponent.ERational.Denominator, out onlyWhereTheRootIsReal);
                if (everyFactorComesOut || OfModestDegreeOrNotAPolynomial(above) && OfModestDegreeOrNotAPolynomial(below))
                {
                    // On either side of the bar: `sqrt(sin(x)^5/cos(x))` is `sin(x)^2 sqrt(sin(x)/cos(x))`.
                    Entity taken = Number.Integer.One;
                    Entity oddAbove = Number.Integer.One;
                    Entity oddBelow = Number.Integer.One;
                    foreach (var (side, underneath) in new[] { (above, false), (below, true) })
                        foreach (var factor in Mulf.LinearChildren(side))
                        {
                            // Under an odd root every real factor comes out as it is: the real
                            // root of a product is the product of the real roots, and that is
                            // the root a negative real has here -- `(-8)^(1/3)` is `-2`. So
                            // `((x - 1)^4 (x + 1)^2)^(1/3)` is `(x - 1)^(4/3) (x + 1)^(2/3)`
                            // for every real x, Timofeev's 318 as the rule for two linear
                            // radicals reads it. A polynomial factor, which is real; a root
                            // among the factors is complex somewhere, and there the roots of
                            // a product and the product of the roots part.
                            // And under an even root the same where the split has been checked
                            // to hold on every real interval, see AnEvenRootOfAProductSplits.
                            if (everyFactorComesOut && factor.ContainsNode(x)
                                && (factor is Powf(var polynomial, Number.Integer wholePower) && wholePower.EInteger.Sign > 0 ? (polynomial, wholePower.EInteger) : (factor, EInteger.One)) is var (realFactor, times)
                                && TreeAnalyzer.TryGetPolynomial(realFactor, x, out _))
                            {
                                taken = taken * MathS.Pow(realFactor, (Number.Integer.Create(underneath ? times.Negate() : times) * exponent).InnerSimplified);
                                continue;
                            }
                            // g^(2m r) is |g|^(2 m r): g itself where that power is even or g is
                            // positive, for x the answer for x > 0 extended by parity, and for a
                            // linear an odd whole power of it with its sign in front of the answer,
                            // `|g|` being `sgn(g) g` -- `sqrt(x/(1 + x)^3)` is
                            // `sgn(1 + x) sqrt(x/(1 + x))/(1 + x)`; only where the root is a factor
                            // of the integrand, as the sign goes in front of the answer. Otherwise
                            // the factor stays where it is.
                            if (factor is Powf(var g, Number.Integer n) && n.EInteger.CompareTo(EInteger.FromInt32(2)) >= 0 && g.ContainsNode(x)
                                && n.EInteger.Divide(EInteger.FromInt32(2)).Multiply(EInteger.FromInt32(2)) is var even
                                && (Number.Integer.Create(underneath ? even.Negate() : even) * exponent).InnerSimplified is var power
                                && (g == x || power is Number.Integer { EInteger.IsEven: true } || IsPositiveForReal(g, x)
                                    || power is Number.Integer && factors.Contains(node) && TreeAnalyzer.TryGetPolyLinear(g, x, out var slopeOfG, out _) && !TreeAnalyzer.IsZero(slopeOfG)))
                            {
                                var evenPower = MathS.Pow(g, Number.Integer.Create(even));
                                if (g == x && !factors.Contains(node))
                                    everyPowerOfXFromAFactor = false;
                                if (g != x && power is Number.Integer { EInteger.IsEven: false } && !IsPositiveForReal(g, x))
                                    signs[g] = signs.TryGetValue(g, out var timesTaken) ? timesTaken + 1 : 1;
                                taken = taken * (g == x ? PowerOfAPositive(evenPower, underneath ? -exponent : exponent)
                                    : power is Number.Integer ? MathS.Pow(g, power) : MathS.Pow(evenPower, underneath ? -exponent : exponent));
                                if (!n.EInteger.IsEven)
                                {
                                    if (underneath) oddBelow = oddBelow * g;
                                    else oddAbove = oddAbove * g;
                                }
                            }
                            else if (underneath)
                                oddBelow = oddBelow * factor;
                            else
                                oddAbove = oddAbove * factor;
                        }
                    if (taken.ContainsNode(x))
                    {
                        if (onlyWhereTheRootIsReal)
                        {
                            var real = new GreaterOrEqualf(@base, Number.Integer.Zero);
                            assumed = assumed == Entity.Boolean.True ? real : assumed & real;
                        }
                        return MathS.Pow(oddBelow == Number.Integer.One ? oddAbove : oddAbove / oddBelow, exponent) * taken;
                    }
                }
                // And a polynomial every monomial of which an even power of x divides: the root
                // of `x^4 + x^2` is `|x| sqrt(x^2 + 1)`, exactly, since `x^2` is not negative --
                // what the roots of Charlwood's `x^3 arcsec(x)/sqrt(x^4 - 1)` by parts combine to.
                if (TreeAnalyzer.TryGetPolynomial(@base, x, out var monomials) && monomials.Count > 1 && OfModestDegree(@base)
                    && monomials.Keys.Min() is { } lowest && lowest.CanFitInInt32() && lowest.ToInt32Unchecked() / 2 is var k and > 0)
                {
                    Entity rest = Number.Integer.Zero;
                    foreach (var pair in monomials.OrderBy(pair => pair.Key))
                    {
                        var degree = pair.Key.ToInt32Unchecked() - 2 * k;
                        Entity term = degree == 0 ? pair.Value : degree == 1 ? pair.Value * x : pair.Value * MathS.Pow(x, degree);
                        rest = rest == Number.Integer.Zero ? term : rest + term;
                    }
                    if (!factors.Contains(node))
                        everyPowerOfXFromAFactor = false;
                    return PowerOfAPositive(MathS.Pow(x, 2 * k), exponent) * MathS.Pow(rest.InnerSimplified, exponent);
                }
                return node;
            });
            if (written == expr)
                return null;
            // A quotient of a sine by the cosine of the same argument set free is the tangent,
            // which is what the tangent substitution reads.
            written = written.Replace(node => node is Divf(Sinf(var a), Cosf(var b)) && a == b ? MathS.Tan(a) : node);
            // Bare: the simplification attaches `provided not x = 0` where it cancels a power
            // of x, and a condition on the integrand is a shape no rule reads.
            var forPositive = Integration.ComputeIndefiniteIntegral(Functions.PartialFractions.Bare(written), x, integrateByParts: true);
            if (forPositive is null || forPositive.Nodes.Any(node => node == MathS.NaN))
                return null;
            // With the sign in front where every power of |x| taken is whole -- |x|^m is
            // sgn(x)^m x^m -- and by parity otherwise. The extension by parity writes the
            // answer in |x|, and an answer in |x| handed on by a step of parts -- the second
            // step on `asech(a x)^2/x^2` -- is a remainder in |x| and `(1 - (|x| a)^2)` that no
            // rule reads, where the same answer with `sgn(x)` in front is the answer in x
            // beside a factor the sign-out route takes.
            var extended = tookAPowerOfX
                ? (wholePowersOfX && everyPowerOfXFromAFactor
                    ? (oddPowersOfX ? MathS.Signum(x) * Functions.PartialFractions.Bare(forPositive) : Functions.PartialFractions.Bare(forPositive))
                    : ExtendedByParity(expr, forPositive, x))
                : forPositive;
            foreach (var pair in signs)
                if (pair.Value % 2 == 1 && extended is { })
                    extended = MathS.Signum(pair.Key) * extended;
            return extended?.Provided(assumed);

            // What is set free under the root is a polynomial of degree four at most: the
            // shapes the rules behind this read stop there, and a root of a sextic or a
            // twelfth-degree polynomial set free is a search that ends nowhere -- the
            // half-angle form of `cos(x)^2/sqrt(1 + cos(x)^2 + cos(x)^4)`, a root of a sum of
            // quotients by `(u^2 + 1)^6`, was fourteen seconds of one.
            bool OfModestDegree(Entity polynomial)
                => !polynomial.ContainsNode(x)
                   || TreeAnalyzer.TryGetPolynomial(polynomial, x, out var read) && read.Count > 0
                      && read.Keys.Max()!.CompareTo(EInteger.FromInt32(4)) <= 0;

            // ...and what is not a polynomial in x at all -- a sine -- is not a degree to bound.
            bool OfModestDegreeOrNotAPolynomial(Entity numerator)
                => !TreeAnalyzer.TryGetPolynomial(numerator, x, out _) || OfModestDegree(numerator);

            // Whether `linear`, or its negative, is the base of a fractional power somewhere
            // in the integrand other than `root` itself.
            bool StandsUnderAFractionalPowerElsewhere(Entity linear, Entity root)
            {
                var negated = (-linear).Expand();
                return expr.Nodes.Any(other => other != root && other is Powf(var b, Number.Rational r) && r is not Number.Integer
                                               && (b == linear || b == negated || (b - linear).Expand().Evaled is Number.Complex { IsZero: true } || (b + linear).Expand().Evaled is Number.Complex { IsZero: true }));
            }

            // `-(x - 1) (x + 1)`, which is how the factoring writes `1 - x^2`, as
            // `(1 - x) (x + 1)`: a negative constant multiplied into the first factor that is
            // not a power, since the splitting below asks the constant to be positive.
            Entity WithANegativeConstantInsideAFactor(Entity product)
            {
                Entity constant = Number.Integer.One;
                var factors = new List<Entity>();
                foreach (var factor in Mulf.LinearChildren(product))
                    if (factor.ContainsNode(x))
                        factors.Add(factor);
                    else
                        constant = constant * factor;
                if (constant.Evaled is not Number.Real { IsNegative: true })
                    return product;
                var bare = factors.FindIndex(factor => factor is not Powf);
                if (bare < 0)
                    return product;
                factors[bare] = (constant * factors[bare]).Expand();
                Entity rebuilt = factors[0];
                for (var i = 1; i < factors.Count; i++)
                    rebuilt = rebuilt * factors[i];
                return rebuilt;
            }

            // Whether `(c g_1^(n_1) ... g_k^(n_k))^(p/q)` with q even is `c^(p/q) g_1^(n_1 p/q) ...`
            // wherever the root is real: the polynomial factors are real, and on each interval
            // between their roots the product's argument is pi times the sum of the n_i of the
            // negative ones. Where that sum is odd the product is negative and its even root is
            // not real, so the integrand is not asked about there -- unless another factor is
            // imaginary there too and the integrand is real all the same. Then the root still
            // splits, and `onlyWhereTheRootIsReal` has the answer say it holds where the root is
            // real: `e^atanh(x) sqrt(1 - x)` is `sqrt((1 + x)/(1 - x)) sqrt(1 - x)`, real past
            // `x = 1`, where written apart it is `sqrt(1 + x)` with the other sign
            // (https://github.com/asc-community/AngouriMath/issues/1664). Where the sum is even
            // the root is real and positive, and the product of the principal powers agrees with
            // it exactly when their phases, pi n_i / q each, add up to a whole turn: the sum a
            // multiple of 2q. Not of q: `sqrt(t^2)` is `|t|`, and `t^(2/2)` is `t`, half a turn
            // out below zero -- which Timofeev's `sqrt(tan(x) tan(2x))` found. The constant must
            // be positive, since a negative one would take the phase the other way.
            // `((x - 1)^3 (x + 2)^5)^(1/4)` splits: above 1 both are positive, below -2 both
            // negative with 3 + 5 a multiple of 8, and between the product is negative. A factor
            // below the bar counts against those above it, its power being the negative of the
            // exponent: `sqrt((1 + x)/x^3)` below -1 has the phases of `sqrt(1 + x)` and of
            // `x^(-3/2)`, pi/2 and -3 pi/2, which add up to -pi, 1 - 3 = -2, and is
            // `-sqrt(1 + x) x^(-3/2)` there; counted as one sum, 1 + 3 = 4 split it, right for
            // x > 0 and wrong for every x < -1. The sum is still asked as well, so that only a
            // split taken before is taken: the difference alone splits `sqrt((1 + x)/x)` below
            // -1, rightly, and the rules after it answer `sqrt(1 + x)/sqrt(x)` for x > 0 only,
            // where the root whole is answered on both sides.
            bool AnEvenRootOfAProductSplits(Entity above, Entity below, EInteger q, out bool onlyWhereTheRootIsReal)
            {
                onlyWhereTheRootIsReal = false;
                var factors = new List<(Entity Polynomial, EInteger Times)>();
                foreach (var (side, underneath) in new[] { (above, false), (below, true) })
                    foreach (var factor in Mulf.LinearChildren(side))
                    {
                        if (!factor.ContainsNode(x))
                        {
                            if (factor.Evaled is not Number.Real { IsPositive: true })
                                return false;
                            continue;
                        }
                        var (polynomial, times) = factor is Powf(var g, Number.Integer n) && n.EInteger.Sign > 0 ? (g, n.EInteger) : (factor, EInteger.One);
                        if (!TreeAnalyzer.TryGetPolynomial(polynomial, x, out _))
                            return false;
                        factors.Add((polynomial, underneath ? times.Negate() : times));
                    }
                if (factors.Count < 2)
                    return false;
                var realBeyondTheRoot = false;
                var splits = OnEveryRealIntervalAt(factors.Select(f => f.Polynomial).ToList(), x, (at, signs) =>
                {
                    var negativeTimes = EInteger.Zero;
                    var negativeTimesUnsigned = EInteger.Zero;
                    for (var i = 0; i < signs.Count; i++)
                        if (signs[i] < 0)
                        {
                            negativeTimes = negativeTimes.Add(factors[i].Times);
                            negativeTimesUnsigned = negativeTimesUnsigned.Add(factors[i].Times.Abs());
                        }
                    if (negativeTimes.IsEven)
                        return negativeTimes.Remainder(q.ShiftLeft(1)).IsZero && negativeTimesUnsigned.Remainder(q.ShiftLeft(1)).IsZero;
                    if (!NotRealAt(expr, x, at))
                        realBeyondTheRoot = true;
                    return true;
                });
                onlyWhereTheRootIsReal = splits && realBeyondTheRoot;
                return splits;
            }

            // Q^r for a Q positive at every real x: a monomial `c x^(2k)` is `c^r x^(2kr)` for x > 0.
            Entity PowerOfAPositive(Entity positive, Number.Rational exponent)
            {
                if (TreeAnalyzer.TryGetPolynomial(positive, x, out var monomials) && monomials.Count == 1)
                {
                    var (degree, coefficient) = (monomials.Keys.First(), monomials.Values.First());
                    if (degree.Sign > 0)
                    {
                        tookAPowerOfX = true;
                        var powerOfX = (Number.Integer.Create(degree) * exponent).InnerSimplified;
                        if (powerOfX is Number.Integer wholePowerOfX)
                            oddPowersOfX ^= !wholePowerOfX.EInteger.IsEven;
                        else
                            wholePowersOfX = false;
                        var power = MathS.Pow(x, powerOfX);
                        // A parameter's even power to a fractional exponent is a power of its
                        // modulus, `(c^2)^(-1/2)` being `1/|c|`, which is one atom wherever it
                        // stands rather than two spellings of it.
                        var ofTheCoefficient = MathS.Pow(coefficient, exponent);
                        // The coefficient as the polynomial reader writes it, `1 * c^2 * 1^2`:
                        // its numeric factors together, its parameters' even powers as moduli.
                        Entity numeric = Number.Integer.One;
                        Entity symbolic = Number.Integer.One;
                        var readable = true;
                        foreach (var factor in Mulf.LinearChildren(coefficient))
                            if (factor.Evaled is Number.Real { IsPositive: true } value)
                                numeric = numeric * value;
                            else if (factor is Powf(Variable parameter, Number.Integer { EInteger.IsEven: true } even) && even.EInteger.Sign > 0)
                                symbolic = symbolic * MathS.Pow(MathS.Abs(parameter), (even * exponent).InnerSimplified);
                            else
                                readable = false;
                        if (readable && symbolic != Number.Integer.One)
                            ofTheCoefficient = (numeric.InnerSimplified == Number.Integer.One ? symbolic : MathS.Pow(numeric.InnerSimplified, exponent) * symbolic);
                        return coefficient.Evaled is Number.Integer { IsZero: false } one && one.EInteger.Equals(EInteger.One)
                            ? power
                            : ofTheCoefficient * power;
                    }
                }
                return MathS.Pow(positive, exponent);
            }
        }

        /// <summary>
        /// Whether the polynomial <paramref name="expr"/> in <paramref name="x"/> is positive at
        /// every real <paramref name="x"/> but possibly zero once its parameters are real: every
        /// monomial an even power, every coefficient a positive number or an even power of a
        /// symbol, or a product of those. The coefficients taken for positive are returned as
        /// the condition <c>c^2 &gt; 0 and ...</c>, conjoined with <paramref name="already"/>,
        /// which is exactly the statement that each such parameter is real and not zero.
        /// </summary>
        private static bool IsPositiveForARealParameter(Entity expr, Entity.Variable x, out Entity assumed, Entity already)
        {
            assumed = already;
            if (!TreeAnalyzer.TryGetPolynomial(expr, x, out var monomials) || monomials.Count == 0)
                return false;
            var conditions = new List<Entity>();
            foreach (var pair in monomials)
            {
                if (!pair.Key.IsEven)
                    return false;
                var symbolic = false;
                foreach (var factor in Mulf.LinearChildren(pair.Value))
                {
                    if (factor.Evaled is Number.Real { IsPositive: true })
                        continue;
                    if (factor is Powf(Variable, Number.Integer { EInteger.IsEven: true } n) && n.EInteger.Sign > 0)
                    {
                        symbolic = true;
                        continue;
                    }
                    return false;
                }
                if (symbolic)
                    conditions.Add(new Greaterf(pair.Value.InnerSimplified, Number.Integer.Zero));
            }
            if (conditions.Count == 0)
                return false;
            foreach (var condition in conditions.Distinct())
                assumed = assumed == Entity.Boolean.True ? condition : assumed & condition;
            return true;
        }

        /// <summary>
        /// Whether the polynomial <paramref name="expr"/> in <paramref name="x"/> is positive at
        /// every real <paramref name="x"/> but possibly zero, for the plain reason that every
        /// monomial is an even power with a positive coefficient.
        /// </summary>
        private static bool IsPositiveForReal(Entity expr, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(expr, x, out var monomials) || monomials.Count == 0)
                return false;
            return monomials.All(pair => pair.Key.IsEven && pair.Value.Evaled is Number.Real { IsPositive: true });
        }

        /// <summary>
        /// The radicals of <paramref name="expr"/> with every power of <paramref name="u"/>
        /// that a radical can hold taken out of it, for a <paramref name="u"/> that is not
        /// negative: <c>(u^2 (1 + u))^(1/2)</c> is <c>u sqrt(1 + u)</c>, and
        /// <c>(2u/(1 + u))^(1/2)</c> is <c>sqrt(2u)/sqrt(1 + u)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// For the substitutions whose variable is one by construction -- <c>u = e^(k x)</c>,
        /// <c>u = (a x + b)^(1/q)</c> with <c>q</c> even, <c>u = x^(1/q)</c> likewise -- and
        /// for no one else: the simplifier is right not to call <c>sqrt(u^2 (1 + u))</c>
        /// <c>u sqrt(1 + u)</c> for a <c>u</c> it knows nothing about, and the substitution
        /// knows exactly this about its own. Two identities, each exact for <c>u &gt;= 0</c>:
        /// <c>(a b)^r = a^r b^r</c> whenever <c>a</c> is a non-negative real, since then
        /// <c>arg(a b) = arg(b)</c>; and <c>(P/Q)^r = P^r/Q^r</c> whenever <c>Q</c> is a positive
        /// real, for the same reason -- which a polynomial in <c>u</c> with non-negative
        /// coefficients and a positive constant term is, at every <c>u &gt;= 0</c>.
        /// </para>
        /// <para>
        /// Without it <c>1/sqrt(t + t^(3/2))</c> under <c>u = sqrt(t)</c> is
        /// <c>2u/sqrt(u^2 + u^3)</c>, a root of a cubic, and with it <c>2/sqrt(1 + u)</c>;
        /// <c>sqrt(1 + tanh(4x))</c> under <c>u = e^(8x)</c> is a root of <c>2u/(1 + u)</c>,
        /// which nothing rationalises, and with it <c>sqrt(2) sqrt(u)/sqrt(1 + u)</c>.
        /// </para>
        /// </remarks>
        private static Entity FactorANonnegativeVariableOutOfRadicals(Entity expr, Entity.Variable u)
            => expr.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Rational exponent) || exponent is Number.Integer
                    || !@base.ContainsNode(u)
                    || !exponent.ERational.Denominator.CanFitInInt32() || !exponent.ERational.Numerator.CanFitInInt32())
                    return node;
                var p = exponent.ERational.Numerator.ToInt32Unchecked();
                var q = exponent.ERational.Denominator.ToInt32Unchecked();

                // A quotient whose denominator is positive at every u >= 0 comes apart first --
                // written as one quotient, since a sum with a quotient in it,
                // `1 - (u - 1/u)^2/4`, is `(4u^2 - (u^2 - 1)^2)/(4u^2)` and reads as nothing
                // until it is: `sinh(x)^2 sinh(2x)/(1 - sinh(x)^2)^(3/2)` under `u = e^x` is that
                // to the three halves, and is a palindromic quartic to the three halves over
                // `8u^3` once it is written out, which the reciprocal substitution answers.
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(@base));
                Entity result;
                if (below != Number.Integer.One && below.ContainsNode(u) && IsPositiveForNonnegative(below, u))
                    result = Factored(above, u, p, q) / Factored(below, u, p, q);
                else if (below == Number.Integer.One)
                    result = Factored(above, u, p, q);
                else
                    return node;
                return result;
            });

        /// <summary>
        /// <c>P^(p/q)</c> with the largest <c>u^(k q)</c> dividing the polynomial <c>P</c> taken
        /// out as <c>u^(k p)</c>; <c>P^(p/q)</c> as it is where <c>P</c> is not a polynomial in
        /// <paramref name="u"/> or holds no such power.
        /// </summary>
        private static Entity Factored(Entity polynomial, Entity.Variable u, int p, int q)
        {
            var exponent = Number.Rational.Create(p, q);
            if (!polynomial.ContainsNode(u) || !TreeAnalyzer.TryGetPolynomial(polynomial, u, out var monomials) || monomials.Count == 0)
                return MathS.Pow(polynomial, exponent);
            var lowest = monomials.Keys.Min()!;
            if (!lowest.CanFitInInt32())
                return MathS.Pow(polynomial, exponent);
            // Rebuilt from its monomials even where nothing comes out, so that a numerator a
            // quotient split left as `2(u + 1) - 2` is the `2u` the next rule reads.
            var k = System.Math.Max(0, lowest.ToInt32Unchecked() / q);
            Entity rest = Number.Integer.Zero;
            foreach (var pair in monomials.OrderBy(pair => pair.Key))
            {
                var degree = pair.Key.ToInt32Unchecked() - k * q;
                Entity term = degree == 0 ? pair.Value : degree == 1 ? pair.Value * u : pair.Value * MathS.Pow(u, degree);
                rest = rest == Number.Integer.Zero ? term : rest + term;
            }
            // `u` rather than `u^1`, which the substitution rule's power rewriting does not read
            // as a power of u: `1/(u^1 sqrt(3 - 3u^2 + u^4))` was refused the candidate `u^2`.
            Entity taken = k * p == 1 ? u : MathS.Pow(u, k * p);
            return k == 0 ? MathS.Pow(rest.InnerSimplified, exponent) : taken * MathS.Pow(rest.InnerSimplified, exponent);
        }

        /// <summary>
        /// Whether the polynomial <paramref name="expr"/> in <paramref name="u"/> is positive at
        /// every <c>u &gt; 0</c> for the plain reason that every coefficient is a positive
        /// number. Without a constant term it is zero at <c>u = 0</c>, where a quotient by it
        /// is undefined on both sides of the identity that asks this, so that costs nothing:
        /// <c>4u^2</c> is what the combined denominator of <c>1 - (u - 1/u)^2/4</c> is.
        /// </summary>
        private static bool IsPositiveForNonnegative(Entity expr, Entity.Variable u)
        {
            if (!TreeAnalyzer.TryGetPolynomial(expr, u, out var monomials) || monomials.Count == 0)
                return false;
            return monomials.Values.All(coefficient => coefficient.Evaled is Number.Real { IsPositive: true });
        }

        private static int Lcm(int a, int b)
        {
            var (x, y) = (a, b);
            while (y != 0) (x, y) = (y, x % y);
            return a / x * b;
        }


        /// <summary>
        /// Bioche's first two rules: a rational function of <c>sin(x)</c> and <c>cos(x)</c>
        /// that is odd in the sine is a rational function of <c>u = cos(x)</c> times
        /// <c>sin(x) dx = -du</c>, and one odd in the cosine the mirror of it; with radicals
        /// of polynomials in the two even in the function admitted as coefficients.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Bondarenko's <c>1/(cos(x) + cos(3x))^5</c> is <c>1/(4 cos(x)^3 - 2 cos(x))^5</c>, odd in
        /// the cosine, and under <c>u = sin(x)</c> it is <c>1/((1 - u^2)^3 (2 - 4u^2)^5)</c>, a
        /// rational function with a denominator of degree sixteen; the half-angle
        /// substitution, which answers any rational function of the two, makes one of
        /// degree thirty in the tangent of the half angle and did not return within the
        /// budget. The parity is read off the polynomials: with <c>N/D</c> the integrand over
        /// the two and <c>f</c> the function it is odd in, <c>N/(D f)</c> is even in <c>f</c>
        /// exactly when, after clearing <c>D</c> against <c>D(-f)</c> where <c>D</c> is neither
        /// even nor odd, every power of <c>f</c> above is odd and every one below is even --
        /// and then each <c>f^2</c> is <c>1 - u^2</c>. Exact, and the substitution is a
        /// bijection on each interval between the zeros of <c>f</c>, the standing caveat on
        /// every trigonometric substitution here.
        /// </para>
        /// <para>
        /// In front of the half-angle substitution, for the smaller rational function and
        /// the shorter answer -- <c>sin(x)/(1 + cos(x)^2)</c> is <c>-arctan(cos(x))</c> here and
        /// a page in the half-angle tangent -- and behind everything that answers a power
        /// product or a homogeneous quotient in its own terms.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByBiochesOddSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var sine = MathS.Sin(x);
            var cosine = MathS.Cos(x);
            if (!expr.Nodes.Any(node => node is Sinf or Cosf or Tanf or Cotanf or Secantf or Cosecantf && node.ContainsNode(x)))
                return null;
            var overTheTwo = expr.Replace(node => node switch
            {
                Tanf(var arg) when arg == x => sine / cosine,
                Cotanf(var arg) when arg == x => cosine / sine,
                Secantf(var arg) when arg == x => 1 / cosine,
                Cosecantf(var arg) when arg == x => 1 / sine,
                _ => node
            });
            // A radical of a polynomial in the two stands as a symbol while the parity is read:
            // Moses's `sqrt(A^2 + B^2 sin(x)^2)/sin(x)` is odd in the sine with the root even in
            // it, and under `u = cos(x)` the root is `sqrt(A^2 + B^2 (1 - u^2))`. The symbol
            // is a coefficient to the polynomials below, and is written in u with them.
            var s = Variable.CreateUnique(expr, "s_bioche");
            var c = Variable.CreateUnique(expr, "c_bioche");
            var radicals = new List<(Variable Symbol, Entity Base, Number.Rational Exponent)>();
            overTheTwo = overTheTwo.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(x))
                    return node;
                var symbol = Variable.CreateUnique(expr, "r_bioche" + radicals.Count);
                radicals.Add((symbol, radicand.Substitute(sine, s).Substitute(cosine, c), exponent));
                return symbol;
            });
            if (radicals.Any(radical => radical.Base.ContainsNode(x)
                                        || !TreeAnalyzer.TryGetPolynomial(radical.Base, s, out _) || !TreeAnalyzer.TryGetPolynomial(radical.Base, c, out _)))
                return null;
            if (overTheTwo.Nodes.Any(node => node.ContainsNode(x) && node is not (Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf)
                                              && !(node is Powf(_, Number.Integer))))
                return null;
            if (overTheTwo.Nodes.Any(node => node is Sinf(var arg) && arg != x || node is Cosf(var arg2) && arg2 != x))
                return null;
            var inTheTwo = Functions.SingleQuotient.Combine(overTheTwo.Substitute(sine, s).Substitute(cosine, c));
            if (inTheTwo.ContainsNode(x))
                return null;   // x bare beside the two is not this rule's
            var (above, below) = Functions.SingleQuotient.Of(inTheTwo);
            above = above.Expand();
            below = below.Expand();
            if (!TreeAnalyzer.TryGetPolynomial(above, s, out _) || !TreeAnalyzer.TryGetPolynomial(below, s, out _)
                || !TreeAnalyzer.TryGetPolynomial(above, c, out _) || !TreeAnalyzer.TryGetPolynomial(below, c, out _))
                return null;

            foreach (var (odd, even, back, sign) in new[] { (c, s, sine, 1), (s, c, cosine, -1) })
            {
                // Every radical even in f, or it is not a function of u.
                if (radicals.Any(radical => ParityIn(radical.Base, odd) != 1))
                    continue;
                // N/(D f) even in f: with D even, N is odd and one f comes out of it; with D
                // odd, N is even and D f is; with D neither, both are cleared against D(-f).
                var parityOfBelow = ParityIn(below, odd);
                Entity numerator;
                Entity denominator;
                bool oneFOutOfTheNumerator;
                if (parityOfBelow == 1)
                {
                    numerator = above;
                    denominator = below;
                    oneFOutOfTheNumerator = true;
                }
                else if (parityOfBelow == -1)
                {
                    numerator = above;
                    denominator = (below * odd).Expand();
                    oneFOutOfTheNumerator = false;
                }
                else
                {
                    var mirrored = below.Substitute(odd, -odd).Expand();
                    numerator = (above * mirrored).Expand();
                    denominator = (below * mirrored).Expand();
                    oneFOutOfTheNumerator = true;
                }
                if (ParityIn(numerator, odd) != (oneFOutOfTheNumerator ? -1 : 1) || ParityIn(denominator, odd) != 1)
                    continue;
                var u = Variable.CreateUnique(expr, "u_bioche");
                var oneMinusUSquared = 1 - MathS.Sqr(u);
                if (InU(numerator, odd, even, u, oneMinusUSquared, oneFOutOfTheNumerator) is not { } aboveInU
                    || InU(denominator, odd, even, u, oneMinusUSquared, dividedByOdd: false) is not { } belowInU)
                    continue;
                var radicalsInU = new List<(Variable Symbol, Entity InU)>();
                foreach (var (symbol, radicand, exponent) in radicals)
                {
                    if (InU(radicand, odd, even, u, oneMinusUSquared, dividedByOdd: false) is not { } radicandInU)
                        break;
                    radicalsInU.Add((symbol, MathS.Pow(radicandInU, exponent)));
                }
                if (radicalsInU.Count != radicals.Count)
                    continue;
                foreach (var (symbol, radical) in radicalsInU)
                {
                    aboveInU = aboveInU.Substitute(symbol, radical);
                    belowInU = belowInU.Substitute(symbol, radical);
                }
                var integrand = Functions.PartialFractions.Bare(aboveInU / belowInU);
                if (Integration.ComputeIndefiniteIntegral(integrand, u, integrateByParts) is not { } result
                    || result.Nodes.Any(node => node == MathS.NaN))
                    continue;
                var answer = result.Substitute(u, back);
                return sign == 1 ? answer : -answer;
            }
            return null;
        }

        /// <summary>1 for even in <paramref name="f"/>, -1 for odd, 0 for neither; a zero polynomial is both.</summary>
        private static int ParityIn(Entity polynomial, Entity.Variable f)
        {
            if (!TreeAnalyzer.TryGetPolynomial(polynomial, f, out var read))
                return 0;
            var evenPowers = read.Keys.Any(k => k.IsEven);
            var oddPowers = read.Keys.Any(k => !k.IsEven);
            return evenPowers && oddPowers ? 0 : oddPowers ? -1 : 1;
        }

        /// <summary>
        /// The polynomial with every <c>f^2</c> written as <paramref name="fSquared"/> -- <c>1 - u^2</c>
        /// for a sine or cosine beside the other as <c>u</c>, <c>u^2 - 1</c> for a hyperbolic sine
        /// beside the cosine, <c>u^2 + 1</c> the other way -- and the other function as <c>u</c>,
        /// one <c>f</c> divided out first where asked.
        /// </summary>
        private static Entity? InU(Entity polynomial, Entity.Variable f, Entity.Variable other, Entity.Variable u, Entity fSquared, bool dividedByOdd)
        {
            if (!TreeAnalyzer.TryGetPolynomial(polynomial, f, out var read))
                return null;
            Entity sum = Number.Integer.Zero;
            foreach (var pair in read)
            {
                if (pair.Key.Sign < 0 || !pair.Key.CanFitInInt32())
                    return null;
                var power = pair.Key.ToInt32Unchecked() - (dividedByOdd ? 1 : 0);
                if (power < 0 || power % 2 != 0)
                    return null;
                var half = power / 2;
                var term = pair.Value.Substitute(other, u) * (half == 0 ? Number.Integer.One : half == 1 ? fSquared : MathS.Pow(fSquared, half));
                sum = sum == Number.Integer.Zero ? term : sum + term;
            }
            return sum;
        }

        /// <summary>
        /// <paramref name="expr"/> with its hyperbolic functions of one linear argument read
        /// back from their exponential spellings as <paramref name="s"/> for the hyperbolic
        /// sine and <paramref name="c"/> for the cosine -- <c>tanh</c> as <c>s/c</c>,
        /// <c>sech</c> as <c>1/c</c> and so on -- and the argument they are of; null where
        /// the exponentials are not of one linear form or none spells one of the six.
        /// Anything else in <c>x</c> is left as it is, for the caller to decline.
        /// </summary>
        private static (Entity OverTheTwo, Entity Argument)? ReadTheHyperbolicFunctions(Entity expr, Entity.Variable x, Variable s, Variable c)
        {
            if (!TryGatherExponentialsOfOneLinearForm(expr, x, unitX: true, out var exponentials, out var y, out _))
                return null;
            // The six read by their spellings, each exponential by the multiple of y it is:
            // sinh(y) is (e^y - e^-y)/2, cosh(y) (e^y + e^-y)/2, tanh(y) (e^(2y) - 1)/(e^(2y) + 1),
            // coth(y) the reciprocal, sech(y) 1/cosh(y) and csch(y) 1/sinh(y). The argument is y,
            // or its half where `tanh(c + d x)` alone is written with e^(2(c + d x)) and the
            // gathering names that y: then the tangent's spelling carries e^y.
            Entity? argument = null;
            Entity overTheTwo = expr;
            foreach (var scale in new[] { 1, 2, -1 })
            {
                // y itself, its half (`tanh(c + d x)` alone is written with e^(2(c + d x)), and
                // the gathering names that y), and twice it (`cosh(2x + 1)` with the slope kept
                // whole is `cosh(2y)` for `y = x + 1/2`).
                var halved = scale == 2;
                var one = scale == 1 ? (EInteger?)EInteger.One : scale == 2 ? null : EInteger.FromInt32(2);
                var two = scale == 1 ? EInteger.FromInt32(2) : scale == 2 ? EInteger.One : EInteger.FromInt32(4);
                // With y named from an exponential of the other sign, e^-y is the k = 1 one:
                // sinh and tanh are odd, cosh even.
                Entity? ReadTheTwo(Entity node)
                {
                    switch (node)
                    {
                        case Divf(Minusf(var a, var b), Number.Integer { EInteger: var d }) when d.Equals(EInteger.FromInt32(2)) && Is(a, one) && Is(b, one?.Negate()):
                            return s;
                        case Divf(Minusf(var a, var b), Number.Integer { EInteger: var d }) when d.Equals(EInteger.FromInt32(2)) && Is(a, one?.Negate()) && Is(b, one):
                            return -s;
                        case Divf(Sumf(var a, var b), Number.Integer { EInteger: var d }) when d.Equals(EInteger.FromInt32(2)) && (Is(a, one) && Is(b, one?.Negate()) || Is(a, one?.Negate()) && Is(b, one)):
                            return c;
                        case Divf(Minusf(var a, Number.Integer { EInteger: var m }), Sumf(var b, Number.Integer { EInteger: var n })) when m.Equals(EInteger.One) && n.Equals(EInteger.One) && Is(a, two) && Is(b, two):
                            return s / c;
                        case Divf(Minusf(var a, Number.Integer { EInteger: var m }), Sumf(var b, Number.Integer { EInteger: var n })) when m.Equals(EInteger.One) && n.Equals(EInteger.One) && Is(a, two.Negate()) && Is(b, two.Negate()):
                            return -s / c;
                        case Divf(Sumf(var a, Number.Integer { EInteger: var m }), Minusf(var b, Number.Integer { EInteger: var n })) when m.Equals(EInteger.One) && n.Equals(EInteger.One) && Is(a, two) && Is(b, two):
                            return c / s;
                        case Divf(Sumf(var a, Number.Integer { EInteger: var m }), Minusf(var b, Number.Integer { EInteger: var n })) when m.Equals(EInteger.One) && n.Equals(EInteger.One) && Is(a, two.Negate()) && Is(b, two.Negate()):
                            return -c / s;
                        case Divf(Number.Integer { EInteger: var m }, var inner) when m.Equals(EInteger.One) && ReadTheTwo(inner) is { } read:
                            return 1 / read;
                    }
                    return null;
                }
                bool Is(Entity node, EInteger? k) => k is { } wanted && exponentials.TryGetValue(node, out var found) && found.Equals(wanted);
                var read = expr.Replace(node => node.ContainsNode(x) && ReadTheTwo(node) is { } inTheTwo ? inTheTwo : node);
                if (read.ContainsNode(s) || read.ContainsNode(c))
                {
                    argument = scale == 1 ? y : scale == 2 ? (y / 2).InnerSimplified : (2 * y).InnerSimplified;
                    overTheTwo = read;
                    break;
                }
            }
            if (argument is null)
                return null;
            return argument is null ? null : (overTheTwo, argument);
        }

        /// <summary>
        /// Fractional powers of <c>a ± a cosh(y)</c> beside anything in the hyperbolic functions
        /// of <c>y</c>, by the half angle at which they are squares: <c>1 + cosh(y)</c> is
        /// <c>2 cosh(y/2)^2</c> and <c>1 - cosh(y)</c> is <c>-2 sinh(y/2)^2</c>, so
        /// <c>sqrt(a + a cosh(y))</c> is <c>sqrt(2a) cosh(y/2)</c> -- no sign, the hyperbolic
        /// cosine being positive -- and <c>(a - a cosh(y))^(3/2)</c> is
        /// <c>(-2a)^(3/2) sgn(sinh(y/2)) sinh(y/2)^3</c>, the sign a constant between the zeros
        /// of the sine that comes out in front; <c>cosh(y)</c> and <c>sinh(y)</c> beside them are
        /// <c>2 cosh(y/2)^2 - 1</c> and <c>2 sinh(y/2) cosh(y/2)</c>, and the question is asked
        /// again in <c>x</c>. <see cref="SolveByTheHalfAngleWhereOnePlusASineIsASquare"/>'s
        /// identity for the hyperbolic cosine.
        /// </summary>
        /// <remarks>
        /// Rubi's <c>x^2 sqrt(a + a cosh(c + d x))</c>, <c>x (a + a cosh(x))^(3/2)</c>,
        /// <c>cosh(x)/sqrt(a - a cosh(x))</c> and <c>(A + B cosh(x))/(a - a cosh(x))^(5/2)</c>
        /// were declined or searches past the budget: no substitution rationalises a root of a
        /// hyperbolic function of <c>x</c> beside a power of <c>x</c>, and beside the sine and
        /// cosine of <c>y</c> the root is of a quotient under every one. Exact, for any
        /// <c>a</c>: <c>cosh(y/2)^2</c> and <c>sinh(y/2)^2</c> are not negative, so
        /// <c>(a q)^p = a^p q^p</c> for the principal powers whatever <c>a</c> is, with
        /// <c>2a</c> and <c>-2a</c> kept as the one constant they are; whole products <c>2p</c>
        /// only. At the top only, as every rule that writes a sign for a function.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTheHalfAngleWhereOnePlusAHyperbolicCosineIsASquare(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            var s = Variable.CreateUnique(expr, "s_hyp");
            var c = Variable.CreateUnique(expr, "c_hyp");
            if (ReadTheHyperbolicFunctions(expr, x, s, c) is not var (overTheTwo, argument))
                return null;
            var found = false;
            foreach (var node in overTheTwo.Nodes)
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(s) && !radicand.ContainsNode(c))
                    continue;
                if (ReadAsOnePlusMinusAFunction(radicand, s, c) is not var (_, _, isSine) || isSine
                    || !exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                    return null;
                found = true;
            }
            if (!found)
                return null;
            var half = (argument / 2).InnerSimplified;
            var sinhHalf = MathS.Hyperbolic.Sinh(half);
            var coshHalf = MathS.Hyperbolic.Cosh(half);
            Entity signs = Number.Integer.One;
            var rewritten = overTheTwo.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(s) && !radicand.ContainsNode(c))
                    return node;
                if (ReadAsOnePlusMinusAFunction(radicand, s, c) is not var (a, positive, _))
                    return node;
                var twoP = Number.Integer.Create(exponent.ERational.Numerator);
                // (a (1 + cosh y))^p = (2a)^p cosh(y/2)^(2p); (a (1 - cosh y))^p = (-2a)^p |sinh(y/2)|^(2p),
                // and 2p is odd.
                if (positive)
                    return MathS.Pow((2 * a).InnerSimplified, exponent) * MathS.Pow(coshHalf, twoP);
                signs = signs * MathS.Signum(sinhHalf);
                return MathS.Pow((-2 * a).InnerSimplified, exponent) * MathS.Pow(sinhHalf, twoP);
            });
            var inX = rewritten.Substitute(c, 2 * MathS.Sqr(coshHalf) - 1).Substitute(s, 2 * sinhHalf * coshHalf);
            if (inX.ContainsNode(s) || inX.ContainsNode(c))
                return null;
            if (Integration.ComputeAsTheSameQuestion(inX, x, integrateByParts) is not { } result)
                return null;
            var answer = signs == Number.Integer.One ? result : signs * result;
            return answer.Nodes.Any(node => node == MathS.NaN) ? null : answer;
        }

        /// <summary>
        /// A sum every term of which carries the same power of one linear form in
        /// <paramref name="x"/>, written as that power times the sum of the rest:
        /// <c>x cosh(x)^(3/2) - x sqrt(cosh(x))/3</c> is <c>x (cosh(x)^(3/2) - sqrt(cosh(x))/3)</c>,
        /// which parts answers and the split does not -- neither term of that pair has an
        /// elementary antiderivative, and only their combination has one.
        /// </summary>
        /// <remarks>
        /// After <see cref="SolveBySplittingSum"/>, which answers every sum whose terms are
        /// each integrable and gives the shorter answer for them; this is for the sums it
        /// declines. The same question, not one of its own: what is handed on is the integrand
        /// rewritten, and the rules below it -- parts among them -- see the product.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByGatheringACommonPolynomialFactorOfASum(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (TryTakeACommonLinearFactorOfASum(expr, x) is not var (factored, inside))
                return null;
            var written = (factored * inside).InnerSimplified;
            return written == expr ? null : Integration.ComputeAsTheSameQuestion(written, x, integrateByParts);
        }

        /// <summary>
        /// The sum with the highest power of one linear form in <paramref name="x"/> that every
        /// term carries taken out of it, as that power and what is left; <see langword="null"/>
        /// where the terms carry no such factor in common. Each term is rebuilt from the
        /// factors that are left rather than divided, so that taking it out is exact.
        /// </summary>
        private static (Entity Factor, Entity Inside)? TryTakeACommonLinearFactorOfASum(Entity expr, Entity.Variable x)
        {
            Entity? common = null;
            var power = int.MaxValue;
            var terms = new List<(Entity Above, Entity Below, int Power)>();
            foreach (var term in Sumf.LinearChildren(expr))
            {
                Entity? termCommon = null;
                var termPower = 0;
                // Above the bar: `x/sech(x)^(3/2)` is one quotient node, and the factor to
                // gather is in its numerator. The rest is kept as it stands, so that taking the
                // factor out is exact rather than a division nothing cancels.
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(term));
                Entity others = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(above))
                {
                    var (factorBase, factorPower) = factor is Powf(var inner, Number.Integer whole) && whole.EInteger.Sign > 0 && whole.EInteger.CanFitInInt32()
                        ? (inner, whole.EInteger.ToInt32Unchecked()) : (factor, 1);
                    if (factorBase.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(factorBase, x, out var slope, out _) && !TreeAnalyzer.IsZero(slope)
                        && (termCommon is null || termCommon == factorBase))
                    {
                        termCommon = factorBase;
                        termPower += factorPower;
                        continue;
                    }
                    others *= factor;
                }
                if (termCommon is null || termPower == 0)
                    return null;
                if (common is null)
                    common = termCommon;
                else if (common != termCommon)
                    return null;
                power = System.Math.Min(power, termPower);
                terms.Add((others, below, termPower));
            }
            if (common is null || terms.Count < 2 || power == int.MaxValue)
                return null;
            var factored = power == 1 ? common : MathS.Pow(common, Number.Integer.Create(power));
            Entity inside = Number.Integer.Zero;
            foreach (var (above, below, termPower) in terms)
            {
                var kept = termPower == power ? above
                    : above * (termPower - power == 1 ? common : MathS.Pow(common, Number.Integer.Create(termPower - power)));
                inside += below == Number.Integer.One ? kept : kept / below;
            }
            inside = inside.InnerSimplified;
            return (factored, inside);
        }

        /// <summary>
        /// A root of a quadratic in <c>tan(x)</c> with a linear term, rotated until it has none:
        /// <c>1/sqrt(a + b tan(x) + c tan(x)^2)</c> is <c>1/sqrt(A + C tan(y)^2)</c> under
        /// <c>x = y + arctan(m)</c>, and the tangent substitution then leaves
        /// <c>1/((1 + t^2) sqrt(A + C t^2))</c>, which is answered in closed form.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>tan(y + f)</c> is <c>(tan(y) + m)/(1 - m tan(y))</c> with <c>m = tan(f)</c>, which
        /// is the Möbius map that preserves <c>1 + tan^2</c> -- the factor the tangent
        /// substitution's <c>dx</c> brings. Under it the quadratic's linear coefficient becomes
        /// <c>b(1 - m^2) + 2(c - a)m</c>, zero for a root of <c>b m^2 + 2(a - c)m - b</c>, whose
        /// discriminant <c>4((a - c)^2 + b^2)</c> is never negative: the two roots are the
        /// quadratic form's two perpendicular directions and either will do.
        /// </para>
        /// <para>
        /// The radicand is <b>assembled</b> rather than substituted into. Writing
        /// <c>tan(x)</c> as the quotient inside the root leaves a nested quotient that nothing
        /// downstream reduces, so the substitution never sees the rotated quadratic; here the
        /// root becomes <c>N(S)^p (1 - m S)^(-2p)</c> with <c>N(S) = A + C S^2</c> computed in
        /// closed form, <c>A = a + b m + c m^2</c> and <c>C = a m^2 - b m + c</c>. For a half-odd
        /// power the modulus is what the root leaves -- <c>sqrt(N/(1 - mS)^2)</c> is
        /// <c>sqrt(N)/|1 - mS|</c> -- so a <c>sgn(1 - m tan(y))</c> comes out in front, constant
        /// between its zeros as every such sign in these rules is.
        /// </para>
        /// <para>
        /// The antiderivative is of the rotated integrand, so the answer is it at
        /// <c>x - arctan(m)</c>: a constant shift of the argument, which an antiderivative is
        /// free to have. Rubi's 4.3.9 and the cotangent shapes the tangent substitution rewrites
        /// into tangents on the way in.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByRotatingAwayTheLinearTermInTheTangent(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            var tangent = MathS.Tan(x);
            var written = expr.Replace(node => node is Cotanf(var cotangent) && cotangent == x ? 1 / tangent : node);
            if (!written.ContainsNode(tangent))
                return null;
            // A function of the tangent alone: anything else in x is another question.
            if (written.Replace(node => node == tangent ? Number.Integer.One : node).ContainsNode(x))
                return null;
            // One radicand, a quadratic in the tangent with a linear term, to a half-odd power.
            Entity? a = null, b = null, c = null;
            var roots = new List<(Entity Node, Number.Rational Power)>();
            foreach (var node in written.Nodes)
            {
                if (node is not Powf(var radicand, Number.Rational power) || power is Number.Integer || !radicand.ContainsNode(x))
                    continue;
                if (!power.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                    return null;
                var inT = radicand.Substitute(tangent, Variable.CreateVariableOrConstant("t_rot"));
                if (inT.ContainsNode(x)
                    || !TreeAnalyzer.TryGetPolynomial(inT, Variable.CreateVariableOrConstant("t_rot"), out var monomials) || monomials.Count == 0
                    || monomials.Keys.Any(k => k.Sign < 0 || k.CompareTo(EInteger.FromInt32(2)) > 0))
                    return null;
                var thisA = monomials.TryGetValue(EInteger.Zero, out var a0) ? a0 : Number.Integer.Zero;
                var thisB = monomials.TryGetValue(EInteger.One, out var b1) ? b1 : Number.Integer.Zero;
                var thisC = monomials.TryGetValue(EInteger.FromInt32(2), out var c2) ? c2 : Number.Integer.Zero;
                if (a is not null && (a != thisA || b != thisB || c != thisC))
                    return null;
                (a, b, c) = (thisA, thisB, thisC);
                roots.Add((node, power));
            }
            if (a is null || b is null || c is null || roots.Count == 0
                || TreeAnalyzer.IsZero(b) || b.Evaled is Number.Complex { IsZero: true })
                return null;

            // m = ((c - a) + sqrt((a - c)^2 + b^2))/b, a root of b m^2 + 2(a - c) m - b.
            var m = ((c - a + MathS.Sqrt((MathS.Sqr(a - c) + MathS.Sqr(b)).InnerSimplified)) / b).InnerSimplified;
            // A number: with symbolic coefficients `m` is a nested surd, the rotated quadratic's
            // are written in it, and what the substitution hands the rational integrator is a
            // quotient over that field -- two minutes and no answer, where the integrand is
            // declined in a tenth of a second unrotated. The rotation is exact for any real
            // coefficients and this is a bound on the work, not on the mathematics.
            if (m.Evaled is not Number.Real { IsFinite: true })
                return null;
            var rotatedTangent = ((tangent + m) / (1 - m * tangent)).InnerSimplified;
            var scale = (1 - m * tangent).InnerSimplified;
            var rotatedA = (a + b * m + c * MathS.Sqr(m)).InnerSimplified;
            var rotatedC = (a * MathS.Sqr(m) - b * m + c).InnerSimplified;
            var quadratic = (rotatedA + rotatedC * MathS.Sqr(tangent)).InnerSimplified;

            // Each root out of the way first, so that the tangents inside it are not rewritten
            // twice: the radicand's rotation is the closed form above, not the substitution.
            var placeholders = new List<(Variable Symbol, Entity Value)>();
            var skeleton = written;
            Entity signs = Number.Integer.One;
            foreach (var (node, power) in roots)
            {
                var symbol = Variable.CreateUnique(written, "r_rot" + placeholders.Count);
                skeleton = skeleton.Substitute(node, symbol);
                // (N/(1 - mS)^2)^(p/2) is N^(p/2) |1 - mS|^(-p), and |z|^(-p) is sgn(z)^p z^(-p).
                var numerator = Number.Integer.Create(power.ERational.Numerator);
                if (!numerator.EInteger.IsEven)
                    signs = signs * MathS.Signum(scale);
                placeholders.Add((symbol, MathS.Pow(quadratic, power) * MathS.Pow(scale, (-numerator).InnerSimplified)));
            }
            if (skeleton.ContainsNode(x) && !skeleton.ContainsNode(tangent))
                return null;
            var rotated = skeleton.Substitute(tangent, rotatedTangent);
            foreach (var (symbol, value) in placeholders)
                rotated = rotated.Substitute(symbol, value);
            rotated = rotated.InnerSimplified;
            if (rotated.ContainsNode(x) is false || rotated.Nodes.Any(node => node == MathS.NaN))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(rotated, x, integrateByParts) is not { } answer)
                return null;
            var shifted = (signs == Number.Integer.One ? answer : signs * answer).Substitute(x, (x - MathS.Arctan(m)).InnerSimplified);
            return shifted.Nodes.Any(node => node == MathS.NaN) ? null : shifted;
        }

        /// <summary>
        /// A power of the variable below the bar beside a root of a quadratic, by
        /// <c>x = 1/t</c>: <c>1/(x^n sqrt(q0 + q1 x + q2 x^2))</c> is
        /// <c>-sgn(t) t^(n - 1)/sqrt(q0 t^2 + q1 t + q2)</c>, a polynomial over the root of the
        /// quadratic with its coefficients reversed, which the rules for those answer.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>1/(x sqrt(1 - (a + b x)^2))</c> was answered and <c>1/(x^2 sqrt(...))</c> was not:
        /// the repeated factor is what nothing reads, and it is what a round of parts against
        /// <c>acos(a + b x)/x^4</c> leaves. <see cref="SolveByReciprocalSubstitution"/> is the
        /// same substitution for a different shape -- a palindromic quartic under the root, where
        /// the reciprocal maps the quartic to itself -- and reads nothing here.
        /// </para>
        /// <para>
        /// The radicand is assembled rather than substituted into: <c>Q(1/t)</c> is
        /// <c>R(t)/t^2</c> with <c>R</c> the reversed quadratic, so the root is
        /// <c>R^(p/2) |t|^(-p)</c>, and writing the quotient inside the root instead leaves a
        /// nesting nothing downstream reduces. The modulus is a <c>sgn(t)</c> in front for an odd
        /// <c>p</c>, constant between its zeros; with <c>t = 1/x</c> it is <c>sgn(x)</c>, which is
        /// what the answers of this family carry anyway.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveByTheReciprocalBesideARootOfAQuadratic(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            var (numerator, denominator) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            // A power of x, two or more, below the bar; one root of a quadratic; polynomials else.
            var powerOfX = 0;
            Entity? radicand = null;
            Number.Rational? rootPower = null;
            Entity rest = Number.Integer.One;
            foreach (var (side, isBelow) in new[] { (numerator, false), (denominator, true) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    if (!factor.ContainsNode(x))
                    {
                        rest = isBelow ? rest / factor : rest * factor;
                        continue;
                    }
                    switch (factor)
                    {
                        case Variable bare when bare == x && isBelow:
                            powerOfX += 1;
                            continue;
                        case Powf(Variable bare, Number.Integer whole) when bare == x && isBelow && whole.EInteger.Sign > 0 && whole.EInteger.CanFitInInt32():
                            powerOfX += whole.EInteger.ToInt32Unchecked();
                            continue;
                        case Powf(var inner, Number.Rational power) when power is not Number.Integer && radicand is null:
                            if (!power.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                                return null;
                            radicand = inner;
                            rootPower = isBelow ? Number.Rational.Create(power.ERational.Negate()) : power;
                            continue;
                        default:
                            if (!TreeAnalyzer.TryGetPolynomial(factor, x, out _))
                                return null;
                            rest = isBelow ? rest / factor : rest * factor;
                            continue;
                    }
                }
            if (powerOfX < 2 || radicand is null || rootPower is null)
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(radicand, x, out var monomials) || monomials.Count == 0
                || monomials.Keys.Any(k => k.Sign < 0 || k.CompareTo(EInteger.FromInt32(2)) > 0)
                || !monomials.ContainsKey(EInteger.FromInt32(2)))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(rest, x, out var restMonomials) || restMonomials.Keys.Any(k => k.Sign < 0))
                return null;

            var t = Variable.CreateUnique(expr, "u_recip");
            // Q(1/t) is R(t)/t^2 with R the quadratic read the other way round.
            var q0 = monomials.TryGetValue(EInteger.Zero, out var m0) ? m0 : Number.Integer.Zero;
            var q1 = monomials.TryGetValue(EInteger.One, out var m1) ? m1 : Number.Integer.Zero;
            var q2 = monomials[EInteger.FromInt32(2)];
            var reversed = (q0 * MathS.Sqr(t) + q1 * t + q2).InnerSimplified;
            if (q0.Evaled is Number.Complex { IsZero: true })
                return null;   // the reversed quadratic is linear, which is the substitution's own shape
            // The rest at 1/t, term by term, so that no quotient is left nested.
            Entity restInT = Number.Integer.Zero;
            foreach (var pair in restMonomials)
            {
                if (!pair.Key.CanFitInInt32())
                    return null;
                var degree = pair.Key.ToInt32Unchecked();
                restInT += degree == 0 ? pair.Value : pair.Value / MathS.Pow(t, Number.Integer.Create(degree));
            }
            // dx = -dt/t^2, x^(-n) = t^n, and the root is R^(p/2) |t|^(-p).
            var numeratorPower = Number.Integer.Create(rootPower.ERational.Numerator);
            Entity integrand = -restInT * MathS.Pow(t, Number.Integer.Create(powerOfX - 2))
                * MathS.Pow(reversed, rootPower) * MathS.Pow(t, (-numeratorPower).InnerSimplified);
            Entity signs = numeratorPower.EInteger.IsEven ? Number.Integer.One : MathS.Signum(t);
            // Bare: the reciprocal's own `t != 0` rides along as a condition -- it is `1/x`, so
            // it says what the integrand already says -- and a condition is not an integrand to
            // the rules below, which decline it.
            integrand = Functions.PartialFractions.Bare(integrand.InnerSimplified);
            if (integrand.ContainsNode(x) || integrand.Nodes.Any(node => node == MathS.NaN))
                return null;
            if (Integration.ComputeAsAQuestionOfItsOwn(integrand, t, integrateByParts) is not { } answer)
                return null;
            var back = (signs == Number.Integer.One ? answer : signs * answer).Substitute(t, (Number.Integer.One / x).InnerSimplified);
            return back.Nodes.Any(node => node == MathS.NaN) ? null : back;
        }

        /// <summary>
        /// A trigonometric function of <c>a + b ln(u)</c> with an imaginary <c>b</c>, written in
        /// exponentials: <c>e^(i (a + b ln(u)))</c> is <c>e^(i a)</c> times the real power
        /// <c>u^(i b)</c>, so the sine, cosine and the rest are sums and quotients of powers of
        /// <c>u</c>, which the rules for those answer.
        /// </summary>
        /// <remarks>
        /// <c>sin(a + ln(c x^2) sqrt(-1/4))</c> and <c>tan(a + i ln(x))</c> were declined: the closed
        /// form for a power of the variable times a sine or cosine of a logarithm divides by
        /// <c>(m + 1)^2 + B^2</c>, which an imaginary <c>B</c> makes zero, and Rubi's 4.7.5 has 62
        /// problems built on exactly that, with <c>b = sqrt(-(m + 1)^2/n^2)</c>. In exponentials the
        /// zero is a power of <c>x</c> that is <c>1/x</c>, and its integral a logarithm. Only for a
        /// number: a real <c>b</c> is the closed form's, after which this is asked, and a symbolic
        /// one, <c>sqrt(-1/n^2)</c>, makes the zero one that only a sign of <c>n</c> decides.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingATrigonometricFunctionOfAnImaginaryLogarithmInExponentials(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Logf && node.ContainsNode(x)))
                return null;
            var any = false;
            var rewritten = expr.Replace(node =>
            {
                var (argument, kind) = node switch
                {
                    Sinf(var of) => (of, 0),
                    Cosf(var of) => (of, 1),
                    Tanf(var of) => (of, 2),
                    Cotanf(var of) => (of, 3),
                    Secantf(var of) => (of, 4),
                    Cosecantf(var of) => (of, 5),
                    _ => ((Entity?)null, -1)
                };
                if (argument is null || !IsLinearInALogarithmWithAnImaginaryCoefficient(argument, x))
                    return node;
                any = true;
                var plus = MathS.Pow(MathS.e, MathS.i * argument);
                var minus = MathS.Pow(MathS.e, -MathS.i * argument);
                return kind switch
                {
                    0 => (plus - minus) / (2 * MathS.i),
                    1 => (plus + minus) / 2,
                    2 => (plus - minus) / (MathS.i * (plus + minus)),
                    3 => MathS.i * (plus + minus) / (plus - minus),
                    4 => 2 / (plus + minus),
                    _ => 2 * MathS.i / (plus - minus),
                };
            });
            if (!any)
                return null;
            // Beside its own derivative the logarithm is a substitution's: `tan(a + i ln(x))/x` is
            // `tan(a + i u)` in `u = ln(x)`, which the integrator answers in a closed form, where the
            // exponentials would answer it as a piecewise in `e^(i a)`.
            if (expr.Nodes.FirstOrDefault(node => node is Logf(var @base, var of) && @base == MathS.e && of.ContainsNode(x)) is { } logarithm)
            {
                Entity beside = Number.Integer.One;
                foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
                    if (!factor.ContainsNode(logarithm))
                        beside = underneath ? beside / factor : beside * factor;
                if (beside.ContainsNode(x) && AreProportionalAtSampledPoints(beside, logarithm.Differentiate(x), x))
                    return null;
            }
            return Integration.ComputeAsTheSameQuestion(rewritten, x, integrateByParts);
        }

        /// <summary>
        /// Whether <paramref name="argument"/> is <c>a + b ln(u)</c>, with <c>u</c> the only place the
        /// variable is and <c>b</c> an imaginary number.
        /// </summary>
        private static bool IsLinearInALogarithmWithAnImaginaryCoefficient(Entity argument, Entity.Variable x)
        {
            var logarithms = argument.Nodes
                .Where(node => node is Logf(var @base, var of) && @base == MathS.e && of.ContainsNode(x))
                .Distinct().ToList();
            if (logarithms.Count != 1)
                return false;
            var placeholder = Variable.CreateUnique(argument, "l_log");
            var inPlaceholder = argument.Replace(node => node == logarithms[0] ? placeholder : node);
            if (inPlaceholder.ContainsNode(x)
                || !TreeAnalyzer.TryGetPolyLinear(inPlaceholder, placeholder, out var coefficient, out _)
                || TreeAnalyzer.IsZero(coefficient))
                return false;
            // A number, and not a symbol's: with `b = sqrt(-1/n^2)` the power of the variable this
            // leaves is `1/x` for every positive n, which nothing reading `n` symbolically can know,
            // and the general power's formula comes back with a zero below its bar.
            return coefficient.Vars.Count() == 0 && coefficient.Evaled is Number.Complex number && number is not Number.Real
                && System.Math.Abs((double)number.RealPart) < 1e-12 * System.Math.Abs((double)number.ImaginaryPart);
        }

        /// <summary>
        /// A power of the variable times a sine or cosine of a logarithm, in closed form:
        /// <c>int x^m sin(L) dx</c> is <c>x^(m + 1)((m + 1) sin(L) - B cos(L))/((m + 1)^2 + B^2)</c>
        /// whenever <c>L' = B/x</c> for a constant <c>B</c>, which <c>a + b ln(c x^n)</c> is with
        /// <c>B = b n</c>; the cosine's is the same with <c>(m + 1) cos(L) + B sin(L)</c>.
        /// </summary>
        /// <remarks>
        /// Two rounds of parts close on the integrand -- the sine's remainder is the cosine's
        /// integral and the cosine's is the sine's -- and the pair is solved rather than
        /// iterated. Differentiating the answer is the whole proof: the cross terms cancel and
        /// what is left is <c>x^m sin(L)((m + 1)^2 + B^2)</c>. The hyperbolic twin needs no rule,
        /// the library writing <c>sinh</c> as exponentials that fold against the logarithm;
        /// the sine and cosine are nodes and fold against nothing. Rubi's 4.7.5.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPowerTimesATrigonometricOfALogarithm(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            Entity coefficient = Number.Integer.One;
            Entity? degree = null;
            Entity? argument = null;
            var isSine = false;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    coefficient = underneath ? coefficient / factor : coefficient * factor;
                    continue;
                }
                switch (factor)
                {
                    case Sinf(var inner) when argument is null && !underneath:
                        (argument, isSine) = (inner, true);
                        continue;
                    case Cosf(var inner) when argument is null && !underneath:
                        (argument, isSine) = (inner, false);
                        continue;
                    case Variable bare when bare == x && degree is null:
                        degree = underneath ? Number.Integer.Create(-1) : Number.Integer.One;
                        continue;
                    case Powf(Variable bare, var power) when bare == x && degree is null && !power.ContainsNode(x):
                        degree = underneath ? (-power).InnerSimplified : power;
                        continue;
                    default:
                        return null;
                }
            }
            if (argument is null || !argument.ContainsNode(x))
                return null;
            // L' x is the constant B, which is what makes the pair close.
            var b = (argument.Differentiate(x) * x).InnerSimplified;
            b = Functions.PartialFractions.Bare(b.Simplify());
            if (b.ContainsNode(x) || b.Evaled is Number.Complex { IsZero: true })
                return null;
            var m = degree ?? Number.Integer.Zero;
            var mPlusOne = (m + Number.Integer.One).InnerSimplified;
            // `(m + 1)^2 + B^2`, which the answer divides by. Symbolically as well as
            // numerically: for `B = n sqrt(-9/n^2)` and `m = 2` it is `9 + (n sqrt(-9/n^2))^2`,
            // which `InnerSimplified` leaves standing and `Simplify` folds to zero -- an
            // imaginary `B` of the right size makes the pair of parts circular rather than
            // closing, and the answer divided by nothing at all.
            var scale = (MathS.Sqr(mPlusOne) + MathS.Sqr(b)).InnerSimplified;
            if (scale.Evaled is Number.Complex { IsZero: true }
                || scale.Vars.Any() && Functions.PartialFractions.Bare(scale.Simplify()).Evaled is Number.Complex { IsZero: true })
                return null;
            var sine = MathS.Sin(argument);
            var cosine = MathS.Cos(argument);
            var bracket = isSine ? mPlusOne * sine - b * cosine : mPlusOne * cosine + b * sine;
            var answer = coefficient * MathS.Pow(x, mPlusOne) * bracket / scale;
            return answer.InnerSimplified;
        }

        /// <summary>
        /// A sum as the constant written in every one of its terms times the sum without it:
        /// <c>a - a sin(x)^2</c> is <c>a (1 - sin(x)^2)</c>, and <c>a + a sin(x)</c> is
        /// <c>a (1 + sin(x))</c>. A factor counts only where every term writes it, compared as
        /// written, so <c>2 + 4 sin(x)</c> keeps its <c>2</c>. Null where no factor is common.
        /// </summary>
        private static (Entity Content, Entity Remainder)? TakeTheConstantWrittenInEveryTermOut(Entity sum, Entity.Variable x)
        {
            var terms = Sumf.LinearChildren(sum);
            if (terms.Count < 2)
                return null;
            List<Entity>? common = null;
            foreach (var term in terms)
            {
                var constants = new List<Entity>();
                foreach (var factor in Mulf.LinearChildren(term))
                    if (!factor.ContainsNode(x) && factor != Number.Integer.One)
                        constants.Add(factor);
                if (common is null)
                    common = constants;
                else
                {
                    var kept = new List<Entity>();
                    foreach (var candidate in common)
                        if (constants.Remove(candidate))
                            kept.Add(candidate);
                    common = kept;
                }
                if (common.Count == 0)
                    return null;
            }
            Entity content = Number.Integer.One;
            foreach (var factor in common!)
                content = content == Number.Integer.One ? factor : content * factor;
            Entity rest = Number.Integer.Zero;
            foreach (var term in terms)
            {
                var factors = new List<Entity>(Mulf.LinearChildren(term));
                foreach (var factor in common)
                    factors.Remove(factor);
                Entity reduced = Number.Integer.One;
                foreach (var factor in factors)
                    reduced = reduced == Number.Integer.One ? factor : reduced * factor;
                rest = rest == Number.Integer.Zero ? reduced : rest + reduced;
            }
            return (content, rest);
        }

        /// <summary>
        /// Whether <paramref name="x"/> occurs in <paramref name="expr"/> at all, and then only
        /// inside a sine, cosine, tangent, cotangent, secant or cosecant: <c>1 + sin(x)</c> and
        /// <c>sec(2x)^3</c> are such, <c>e^x</c>, <c>x sin(x)</c> and a hyperbolic function --
        /// written as exponentials -- are not.
        /// </summary>
        private static bool EntersOnlyThroughTrigonometricFunctions(Entity expr, Entity.Variable x)
        {
            return expr.ContainsNode(x) && Through(expr, x);

            static bool Through(Entity node, Entity.Variable x)
            {
                if (node is Sinf or Cosf or Tanf or Cotanf or Secantf or Cosecantf || !node.ContainsNode(x))
                    return true;
                if (node is Variable)
                    return false;
                foreach (var child in node.DirectChildren)
                    if (!Through(child, x))
                        return false;
                return true;
            }
        }

        /// <summary>
        /// A power of a constant multiple of a radicand that a logarithm holds under a root,
        /// written over that radicand: <c>acosh(c x)</c> is <c>ln(c x + sqrt(c^2 x^2 - 1))</c>,
        /// and beside it <c>d - c^2 d x^2</c> is <c>-d (c^2 x^2 - 1)</c>. A whole power is the
        /// product of the powers; a root <c>(lambda M)^(k/2)</c> is <c>K^k M^(k/2)</c> with
        /// <c>K = sqrt(lambda M)/sqrt(M)</c>, which is constant wherever it is defined -- plus or
        /// minus <c>i</c>, or plus or minus <c>sqrt(lambda)</c> -- so it stands in front of the
        /// answer the way Rubi writes it.
        /// </summary>
        /// <remarks>
        /// The substitution <c>u = acosh(c x)</c> needs the root its derivative carries,
        /// <c>sqrt(c^2 x^2 - 1)</c>; written over <c>1 - c^2 x^2</c> the integrand is the same
        /// function times <c>i</c> and nothing reads it: <c>acosh(a x)^2/sqrt(1 - a^2 x^2)</c> ran
        /// out of time where <c>acosh(a x)^2/sqrt(a^2 x^2 - 1)</c> takes a third of a second, and
        /// <c>x (a + b acosh(c x))/(d - c^2 d x^2)^3</c> -- a whole power, no root at all -- the same.
        /// <c>K</c> is carried through the integration as a symbol: it is constant, so an
        /// antiderivative in it is one in <c>x</c> once it is written out, whatever the branches.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAConstantMultipleOfARadicandOverIt(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // At the question asked only. The inverse cosine is in the integrand as asked, and a
            // round of parts differentiates it away, so what is asked below holds no logarithm
            // this rule needs -- but the substitutions below write logarithms of their own, and
            // there the rule found a genuine multiple, rewrote it and asked a whole search again
            // that was going to decline anyway: `atan(c x/sqrt(a - c^2 x^2))^2/sqrt(d - c^2 d x^2/a)`,
            // with no logarithm in it as asked, took thirty-one seconds to decline where it took
            // seven, twelve of them in each of two such re-asks.
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // The radicands a logarithm holds under a square root.
            var references = new List<Entity>();
            foreach (var logarithm in expr.Nodes.OfType<Logf>())
                foreach (var node in logarithm.Nodes)
                    if (node is Powf(var radicand, Number.Rational { ERational: var half }) && half.Denominator.Equals(EInteger.FromInt32(2))
                        && radicand.ContainsNode(x) && TreeAnalyzer.TryGetPolynomial(radicand, x, out var read) && read.Keys.Max() >= EInteger.One
                        && !references.Contains(radicand))
                        references.Add(radicand);
            // And the radicand an inverse sine or cosine of a linear holds without writing it:
            // `arcsin(u)'` is `u'/sqrt(1 - u^2)`, so `(d + c d x)^(1/2) (f - c f x)^(3/2)` beside
            // `arcsin(c x)` is the same case as beside `arcosh`, with `1 - c^2 x^2` for the radicand.
            foreach (var node in expr.Nodes)
                if (node switch { Arcsinf(var inner) => inner, Arccosf(var inner) => inner, _ => null } is { } argument
                    && argument.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out _))
                {
                    var radicand = (1 - MathS.Sqr(argument)).Expand().InnerSimplified;
                    if (!references.Contains(radicand))
                        references.Add(radicand);
                }
            if (references.Count == 0)
                return null;
            var multiple = Variable.CreateUnique(expr, "k_rad");
            Entity? written = null, root = null, reference = null;
            var rewritten = expr.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Rational exponent) || !@base.ContainsNode(x) || references.Contains(@base))
                    return node;
                foreach (var candidate in references)
                {
                    if (TryReadAsAConstantMultiple(@base, candidate, x) is not { } lambda)
                        continue;
                    if (exponent is Number.Integer)
                        return MathS.Pow(lambda, exponent) * MathS.Pow(candidate, exponent);
                    if (!exponent.ERational.Denominator.Equals(EInteger.FromInt32(2)))
                        return node;
                    // Only one such root per integrand: K is `sqrt(base)/sqrt(candidate)`, and two
                    // different bases would each want their own.
                    if (written is not null && (written != @base || reference != candidate))
                        return node;
                    (written, reference) = (@base, candidate);
                    var numeratorOfExponent = Number.Integer.Create(exponent.ERational.Numerator);
                    return MathS.Pow(multiple, numeratorOfExponent) * MathS.Pow(candidate, exponent);
                }
                return node;
            });
            if (written is not null && reference is not null)
                root = MathS.Sqrt(written) / MathS.Sqrt(reference);
            // And the radicand written as two linear factors, when no single base was its multiple.
            if (rewritten == expr && TryWriteAPairOfLinearsOverARadicand(expr, x, references, multiple, out var paired, out var pairRoot))
                (rewritten, root) = (paired, pairRoot);
            if (rewritten == expr)
                return null;
            var simplified = rewritten.InnerSimplified;
            if (simplified == expr || simplified == expr.InnerSimplified)
                return null;
            if (Integration.ComputeAsTheSameQuestion(simplified, x, integrateByParts) is not { } answer)
                return null;
            if (root is not null)
                answer = answer.Substitute(multiple, root);
            return answer.ContainsNode(multiple) ? null : answer;
        }

        /// <summary>
        /// Two linear factors whose product is a constant multiple of a radicand a logarithm holds,
        /// written as that radicand: `d + i c d x` and `f - i c f x` beside `arsinh(c x)`, whose
        /// product is `d f (1 + c^2 x^2)`. `L1^p L2^q` is `L1^(p - q) L1^q L2^q` where `p - q` is
        /// whole, and `L1^q L2^q` is `lambda^q M^q` for a whole `q` and `K^k M^(k/2)` for
        /// `q = k/2`, with `K = sqrt(L1) sqrt(L2)/sqrt(M)` constant wherever it is defined -- the
        /// same factor the single base is written with. Rubi's 7.1.4 states seventy-two of its
        /// rows this way; `(d + i c d x)^(5/2) sqrt(f - i c f x) (a + b arsinh(c x))` ran past
        /// seventy seconds where the same thing over `1 + c^2 x^2` takes two thirds of one.
        /// </summary>
        private static bool TryWriteAPairOfLinearsOverARadicand(Entity expr, Entity.Variable x, List<Entity> references,
            Entity.Variable multiple, out Entity rewritten, out Entity? root)
        {
            rewritten = expr;
            root = null;
            // The factors on both sides of the bar, as powers: a nested power read through, and a
            // factor below the bar with its exponent negated.
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            var factors = new List<(Entity Base, Entity Exponent)>();
            foreach (var factor in Mulf.LinearChildren(above))
                factors.Add(AsAPower(factor));
            foreach (var factor in Mulf.LinearChildren(below))
            {
                var (@base, exponent) = AsAPower(factor);
                factors.Add((@base, (-exponent).InnerSimplified));
            }
            for (var i = 0; i < factors.Count; i++)
                for (var j = 0; j < factors.Count; j++)
                {
                    if (i == j)
                        continue;
                    var (first, p) = factors[i];
                    var (second, q) = factors[j];
                    if (!first.ContainsNode(x) || !second.ContainsNode(x)
                        || !TreeAnalyzer.TryGetPolyLinear(first, x, out _, out _) || !TreeAnalyzer.TryGetPolyLinear(second, x, out _, out _)
                        || (p - q).Evaled is not Number.Integer || q.Evaled is not Number.Rational half)
                        continue;
                    var twice = (2 * half).Evaled;
                    if (half is not Number.Integer && twice is not Number.Integer)
                        continue;
                    var product = (first * second).Expand();
                    foreach (var candidate in references)
                    {
                        // A multiple of one counts here, where it does not for a single base: two
                        // factors whose product *is* the radicand -- `sqrt(1 + c x) sqrt(1 - c x)`
                        // beside `arcsin(c x)` -- still want writing as its one root.
                        if (TryReadAsAConstantMultiple(product, candidate, x, allowOne: true) is not { } lambda)
                            continue;
                        Entity together;
                        if (half is Number.Integer)
                            together = MathS.Pow(lambda, half) * MathS.Pow(candidate, half);
                        else
                        {
                            together = MathS.Pow(multiple, twice) * MathS.Pow(candidate, half);
                            root = MathS.Sqrt(first) * MathS.Sqrt(second) / MathS.Sqrt(candidate);
                        }
                        Entity result = MathS.Pow(first, (p - q).InnerSimplified) * together;
                        for (var k = 0; k < factors.Count; k++)
                            if (k != i && k != j)
                                result = result * MathS.Pow(factors[k].Base, factors[k].Exponent);
                        rewritten = result;
                        return true;
                    }
                }
            return false;

            static (Entity Base, Entity Exponent) AsAPower(Entity factor)
                => factor switch
                {
                    Powf(Powf(var inner, var innerExponent), var outerExponent) => (inner, (innerExponent * outerExponent).InnerSimplified),
                    Powf(var @base, var exponent) => (@base, exponent),
                    _ => (factor, Number.Integer.One),
                };
        }

        /// <summary>Set while <see cref="SolveByWritingEachLinearOnce"/> asks its product.</summary>
        [System.ThreadStatic] private static bool writingEachLinearOnce;

        /// <summary>
        /// A product of powers of quotients of polynomials in <paramref name="x"/> whose roots
        /// are rational in the symbols, where one root stands in two of the bases, written over
        /// each linear once: <c>K (x - r_1)^(e_1) ... (x - r_k)^(e_k)</c>, with <c>e_i</c> the sum
        /// of the exponents <c>r_i</c> has in the bases. <c>K</c> is the integrand over that
        /// product, and its logarithmic derivative is zero -- each base is its leading coefficient
        /// times its linears, so both sides have the same <c>sum e_i/(x - r_i)</c> -- so it is
        /// constant wherever it is defined and stands in front of the answer, the way Rubi writes
        /// <c>x^p (c + d/x)^p/(1 + c x/d)^p</c> in front of its.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>e^atanh(a x) sqrt(c - c/(a x))</c> is <c>sqrt((1 + a x)/(1 - a x)) sqrt(c (a x - 1)/(a x))</c>,
        /// and the root <c>1/a</c> stands in both bases, with exponents <c>-1/2</c> and <c>1/2</c>.
        /// Written once it is gone: the integrand is <c>K sqrt(a x + 1)/sqrt(x)</c>, which the
        /// rule for two linear radicals answers in milliseconds, where the substitution search ran
        /// out of time. Rubi's 7.3.6 and 7.4.2. https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// <para>
        /// Only where it helps: a root stands in two bases under powers that are not whole --
        /// <c>sqrt(c - a c x)/sqrt(1 - a x)</c> -- or in a root of a quotient with x below the bar,
        /// <c>sqrt(c - c/(a x))</c>, and in another base; and at most two linears are left under a
        /// power that is not whole, which is what the rule for two linear radicals reads. A root
        /// beside a whole power of one of its linears -- <c>sqrt(x)/(x (x + 1))</c>, and
        /// <c>(1 - a^2 x^2)^(3/2)/((1 - a x)^2 (c + d x))</c>, which the rules behind this one write
        /// over the radicand -- is read by the rules as it is written, and is answered without a
        /// <c>K</c>.
        /// </para>
        /// </remarks>
        internal static Entity? SolveByWritingEachLinearOnce(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Not while answering its own product, see below; and only where something of x is
            // under a power that is not whole, or is the exponential of a logarithm -- looked for
            // before anything is read, since this is the first rule every question is asked of.
            if (writingEachLinearOnce || !Integration.AnsweringTheQuestionAsked
                || !expr.Nodes.Any(node => node is Powf(var @base, var exponent) && @base.ContainsNode(x) && exponent is Number.Rational and not Number.Integer
                                           || node is Powf(var e, var power) && e == MathS.e && power.Nodes.Any(inner => inner is Logf)))
                return null;
            // Each root, with the sum of its exponents, the bases it stands in, and whether one of
            // them is under a power that is not whole; and each base, with its roots, whether it
            // is under such a power, and whether it is a quotient with x below the bar.
            var roots = new List<(Entity Root, Number.Rational Exponent, HashSet<int> Bases, bool UnderARoot)>();
            var bases = new List<(HashSet<int> Roots, bool UnderARoot, bool AQuotient)>();
            // The roots of the linears written under a power that is not whole, which a quadratic
            // beside them may share: `a d e + (c d^2 + a e^2) x + c d e x^2` is
            // `(d + e x)(a e + c d x)`. Beside a whole power of the linear, `(d + e x)^3 sqrt(a d e
            // + ...)`, the quadratic is under a root beside a polynomial, which the rules for one
            // answer as it is written.
            var writtenRoots = new List<Entity>();
            foreach (var node in expr.Nodes)
                if (node is Powf((Sumf or Minusf) and var linear, Number.Rational power) && power is not Number.Integer
                    && linear.ContainsNode(x) && TreeAnalyzer.TryGetPolyLinear(linear, x, out var writtenSlope, out var writtenIntercept)
                    && !writtenSlope.ContainsNode(x) && !writtenIntercept.ContainsNode(x) && writtenSlope.Evaled is not Number.Complex { IsZero: true })
                {
                    var writtenRoot = Reduced(-writtenIntercept / writtenSlope);
                    if (!writtenRoots.Contains(writtenRoot))
                        writtenRoots.Add(writtenRoot);
                }
            // Set where a quadratic under a power that is not whole came apart only through a root
            // it shares, which no other rule reads it as.
            var splitThroughAShare = false;
            if (!Read(expr, Number.Integer.One))
                return null;
            // With every power whole the integrand is a rational function, and a root of a quotient
            // shared with another base is the same help: `e^(2 acoth(a x))/(c - c/(a^2 x^2))^2` is
            // `K x^4/((a x + 1)(a x - 1)^3)`, which the partial fractions answer at once, where
            // as written it ran out of time; and `K` is a constant there, with no arms to it.
            // And a quadratic that came apart through a root it shares is help on its own where it
            // leaves two linears or fewer, a product the rules for two linears answer: the linear
            // it shares stands under a root too, and the two roots of it are one power that is
            // whole. `(d + e x)^(7/2)/(a d e + (c d^2 + a e^2) x + c d e x^2)^(3/2)` is
            // `K (d + e x)^2/(a e + c d x)^(3/2)`, where as written it was declined. Beside a
            // third, as in `(a d e + ...)^(3/2)/(x^5 (d + e x))`, it is a product of three, which
            // those rules do not answer, and the quadratic is left to the rules that read it whole.
            var wholePowersOnly = !bases.Any(written => written.UnderARoot);
            if (!(splitThroughAShare && roots.Count(root => root.Exponent != Number.Integer.Zero) <= 2
                  || roots.Any(root => root.Bases.Count(which => bases[which].UnderARoot) >= 2
                                       || root.Bases.Any(which => (bases[which].UnderARoot || wholePowersOnly) && bases[which].AQuotient) && root.Bases.Count >= 2))
                || roots.Count(root => root.Exponent is not Number.Integer) > 2)
                return null;
            // Each linear with the root's denominator for its leading coefficient: `a x + 1` for
            // the root `-1/a`, as the integrand writes it, where `x + 1/a` is the same up to `K`.
            // Every root's, those whose exponents add up to zero too: the integrand changes there.
            var linears = new List<(Entity Linear, Number.Rational Exponent)>();
            foreach (var (root, exponent, _, _) in roots)
            {
                var (above, below) = Functions.SingleQuotient.Of(root);
                var linear = root == Number.Integer.Zero ? x
                    : (above is Number.Real { IsNegative: true } negative ? below * x + (-negative).InnerSimplified : below * x - above).InnerSimplified;
                linears.Add((linear, exponent));
            }
            // And with the sign that is positive on an interval where the integrand is real: there
            // the product is real too, `K` taking the imaginary unit the other sign would leave,
            // and the rules answer a product of linears where it is real. `e^atanh(a x) sqrt(c - c/(a x))`
            // is real between `-1/a` and 0 for a positive `c`, where `sqrt(a x + 1)/sqrt(x)` has
            // no value in the answer the rules give and `sqrt(a x + 1)/sqrt(-x)` has one; and for
            // a negative `c` it is real between 0 and `1/a`, where `sqrt(a x + 1)/sqrt(x)` is the
            // one. Each such sign is an arm, saying where it holds -- where every linear under a
            // power that is not whole is not negative, which is where its product is real, and
            // where its answer holds whatever the symbols are -- and the arms are found with the
            // other symbols pinned to either sign.
            var arms = new List<Providedf>();
            var tried = new HashSet<string>();
            foreach (var (found, pinned, low, high) in IntervalsWhereItIsReal(expr, linears.Select(written => written.Linear).ToList(), x))
            {
                var signs = wholePowersOnly ? linears.Select(_ => 1).ToArray() : found;
                if (!tried.Add(string.Join(",", linears.Select((written, i) => written.Exponent == Number.Integer.Zero ? 0 : signs[i]))))
                    continue;
                // As a quotient, the negative powers below the bar, which is how the rules read it:
                // `(a x + 1)^(-1/2) (1 - a x)^(-1) x^(3/2)` was declined where
                // `x^(3/2)/(sqrt(a x + 1) (1 - a x))` is answered.
                Entity above = Number.Integer.One, below = Number.Integer.One;
                Entity holdsWhere = Entity.Boolean.True;
                for (var i = 0; i < linears.Count; i++)
                {
                    var (linear, exponent) = linears[i];
                    if (exponent == Number.Integer.Zero)
                        continue;
                    if (signs[i] < 0)
                        linear = linear is Variable ? -linear
                            : TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out var intercept) ? ((-intercept).InnerSimplified - slope * x).InnerSimplified
                            : (-linear).InnerSimplified;
                    if (exponent is Number.Rational { ERational.Sign: < 0 })
                    {
                        var positive = (Number.Rational)(-exponent);
                        below = below == Number.Integer.One ? (positive == Number.Integer.One ? linear : MathS.Pow(linear, positive))
                            : below * (positive == Number.Integer.One ? linear : MathS.Pow(linear, positive));
                    }
                    else
                        above = above == Number.Integer.One ? (exponent == Number.Integer.One ? linear : MathS.Pow(linear, exponent))
                            : above * (exponent == Number.Integer.One ? linear : MathS.Pow(linear, exponent));
                    if (exponent is not Number.Integer)
                    {
                        var notNegative = new GreaterOrEqualf(linear, Number.Integer.Zero);
                        holdsWhere = holdsWhere == Entity.Boolean.True ? notNegative : holdsWhere & notNegative;
                    }
                }
                var product = below == Number.Integer.One ? above : above / below;
                // The product is asked with this rule out of the way: the rules in front of it write
                // `sqrt(x + 1)/x^(5/2)` as `sqrt(x^2 + x)/x^3`, a root of a product beside a power
                // of one of its linears, and asked of this rule again that was its own question with
                // arms of its own, one fewer each time.
                // Where the arm is for negative x, in t = -x, with the power of x a power of t: the
                // rules read `x^(1/2)` and not `(-x)^(1/2)`, and `sqrt(-x) (1 - a x)^2/(1 + a x)^(3/2)`
                // ran out of time where `sqrt(t) (1 + a t)^2/(1 - a t)^(3/2)` takes milliseconds.
                var reflected = linears.Any(written => written.Linear == x && written.Exponent != Number.Integer.Zero)
                    && signs[linears.FindIndex(written => written.Linear == x)] < 0;
                var t = reflected ? Variable.CreateUnique(expr, "t") : x;
                Entity? integrated;
                writingEachLinearOnce = true;
                try
                {
                    integrated = Integration.ComputeAsAQuestionOfItsOwn(reflected ? product.Substitute(x, -t).InnerSimplified : product, t, integrateByParts);
                }
                finally
                {
                    writingEachLinearOnce = false;
                }
                if (reflected && integrated is not null)
                    integrated = -integrated.Substitute(t, -x);
                // Every arm or none: an interval left without one would have no answer where the
                // rules behind this one may give one.
                if (integrated is null || integrated.Nodes.Any(node => node == MathS.NaN))
                    return null;
                var arm = expr / product * integrated;
                // Checked at two points of that interval, with the symbols pinned as they were there.
                var inside = new[] { low + (high - low) / 3, low + 2 * (high - low) / 3 }
                    .Select(at => at.ToString("R", System.Globalization.CultureInfo.InvariantCulture)).ToArray();
                if (!Functions.PartialFractions.HoldsAtSampledPoints(pinned(arm.Differentiate(x)), pinned(expr), x, inside))
                    return null;
                arms.Add(new Providedf(arm, holdsWhere));
            }
            return arms.Count switch
            {
                0 => null,
                1 => arms[0],
                _ => MathS.Piecewise(arms),
            };

            // A constant in lowest terms: numbers by their arithmetic, which is exact and cheap, and
            // quotients in the symbols by the polynomial gcd. This rule is the first every
            // question is asked of, and most constants it meets are numbers.
            static Entity Reduced(Entity constant)
                => constant.Vars.Any() ? Functions.PartialFractions.InLowestTermsOverTheSymbols(constant) : constant.InnerSimplified;

            // `factor` to the power `times`, read into the table through products, quotients and
            // powers of them, the power of a product taken as the product of the powers and the
            // exponential of a multiple of a logarithm as the power it is, `e^(1/2 ln q)` as
            // `q^(1/2)` -- which is how the inverse hyperbolic functions under an exponential
            // arrive. Each of those has the logarithmic derivative it is read with, whatever the
            // branches, and `K` takes what the branches make of it. False where a factor of x is
            // anything else.
            bool Read(Entity factor, Number.Rational times)
            {
                if (!factor.ContainsNode(x))
                    return true;
                switch (factor)
                {
                    case Mulf:
                        return Mulf.LinearChildren(factor).All(child => Read(child, times));
                    case Divf(var above, var below):
                        return Read(above, times) && Read(below, (Number.Rational)(-times));
                    case Powf(var @base, Number.Rational exponent):
                        return Read(@base, (Number.Rational)(times * exponent));
                    case Powf(var @base, var exponent) when @base == MathS.e && AMultipleOfALogarithm(exponent) is var (multiple, argument):
                        return Read(argument, (Number.Rational)(times * multiple));
                    case Variable or Sumf or Minusf:
                        var index = bases.Count;
                        var underARoot = times is not Number.Integer;
                        var (top, bottom) = Functions.SingleQuotient.Of(AsOneQuotient(factor));
                        bases.Add((new HashSet<int>(), underARoot, bottom.ContainsNode(x)));
                        return WithItsRoots(top, times, index, underARoot) && WithItsRoots(bottom, (Number.Rational)(-times), index, underARoot);
                    default:
                        return false;
                }
            }

            // `c ln(q)` as `(c, q)` for a rational `c` -- a product of rationals and one natural
            // logarithm -- and null otherwise.
            (Number.Rational Multiple, Entity Argument)? AMultipleOfALogarithm(Entity exponent)
            {
                Number.Rational multiple = Number.Integer.One;
                Entity? argument = null;
                foreach (var factor in Mulf.LinearChildren(exponent))
                    switch (factor)
                    {
                        case Number.Rational rational:
                            multiple = (Number.Rational)(multiple * rational);
                            break;
                        case Logf(var logarithmBase, var antilogarithm) when logarithmBase == MathS.e && argument is null:
                            argument = antilogarithm;
                            break;
                        default:
                            return null;
                    }
                return argument is null ? null : (multiple, argument);
            }

            // The roots of a polynomial in x, each its multiplicity times `exponent` into the
            // table: a power of x, a linear, and a quadratic with no linear term whose roots are
            // a monomial and its negative. False for anything else.
            bool WithItsRoots(Entity polynomial, Number.Rational exponent, int @base, bool underARoot)
            {
                if (!polynomial.ContainsNode(x))
                    return true;
                if (!TreeAnalyzer.TryGetPolynomial(polynomial, x, out var read) || read.Count == 0
                    || read.Values.Any(coefficient => coefficient.ContainsNode(x)))
                    return false;
                var lowest = read.Keys.Min()!;
                var highest = read.Keys.Max()!;
                if (lowest.Sign < 0)
                    return false;
                Entity CoefficientOf(EInteger power) => read.TryGetValue(power, out var coefficient) ? coefficient : Number.Integer.Zero;
                if (lowest.Sign > 0)
                    Add(Number.Integer.Zero, (Number.Rational)(exponent * Number.Integer.Create(lowest)));
                var degree = highest.Subtract(lowest);
                if (degree.IsZero)
                    return true;
                if (degree.Equals(EInteger.One))
                {
                    Add(Reduced(-CoefficientOf(lowest) / CoefficientOf(highest)), exponent);
                    return true;
                }
                if (degree.Equals(EInteger.FromInt32(2))
                    && Reduced(CoefficientOf(lowest.Add(EInteger.One))) == Number.Integer.Zero
                    && AMonomialSquareRoot(-CoefficientOf(lowest) / CoefficientOf(highest)) is { } root)
                {
                    Add(root, exponent);
                    Add(Reduced(-root), exponent);
                    return true;
                }
                if (degree.Equals(EInteger.FromInt32(2)))
                {
                    var (c2, c1, c0) = (CoefficientOf(highest), CoefficientOf(lowest.Add(EInteger.One)), CoefficientOf(lowest));
                    // A root of a linear written beside it, and the other root by their sum.
                    foreach (var shared in writtenRoots)
                        if (Reduced(c2 * shared * shared + c1 * shared + c0) == Number.Integer.Zero)
                        {
                            Add(shared, exponent);
                            Add(Reduced(-c1 / c2 - shared), exponent);
                            splitThroughAShare |= underARoot;
                            return true;
                        }
                }
                return false;

                void Add(Entity root, Number.Rational times)
                {
                    for (var i = 0; i < roots.Count; i++)
                        if (roots[i].Root == root || Reduced(roots[i].Root - root) == Number.Integer.Zero)
                        {
                            roots[i].Bases.Add(@base);
                            roots[i] = (roots[i].Root, (Number.Rational)(roots[i].Exponent + times), roots[i].Bases, roots[i].UnderARoot || underARoot);
                            bases[@base].Roots.Add(i);
                            return;
                        }
                    roots.Add((root, times, new HashSet<int> { @base }, underARoot));
                    bases[@base].Roots.Add(roots.Count - 1);
                }
            }

            // For each way of pinning the other symbols -- all positive, all negative, and each
            // sign in turn -- the signs of `linears` on every interval between their roots where
            // `expr` may be real, with the pinning and that interval, the outer ones a unit wide.
            static IEnumerable<(int[] Signs, System.Func<Entity, Entity> Pinned, double Low, double High)> IntervalsWhereItIsReal(Entity expr, List<Entity> linears, Entity.Variable x)
            {
                static double? ValueOf(Entity e)
                    => Numerics.IntervalEvaluation.Of(e) is { IsFinite: true, Im.IsZero: true } value ? (value.Re.Low + value.Re.High) / 2 : null;
                var symbols = expr.Vars.Where(symbol => symbol != x).ToList();
                for (var pattern = 0; pattern < (symbols.Count switch { 0 => 1, 1 => 2, _ => 4 }); pattern++)
                {
                    var pins = new Dictionary<Variable, Entity>();
                    for (var i = 0; i < symbols.Count; i++)
                    {
                        var negative = pattern == 1 || pattern == 2 && i % 2 == 1 || pattern == 3 && i % 2 == 0;
                        pins[symbols[i]] = (negative ? -1 : 1) * (1.37 + 0.61 * i);
                    }
                    System.Func<Entity, Entity> pinned = e => pins.Count == 0 ? e : e.Substitute(pins);
                    var pinnedLinears = linears.Select(pinned).ToList();
                    var places = new List<double>();
                    foreach (var linear in pinnedLinears)
                    {
                        if (!TreeAnalyzer.TryGetPolyLinear(linear, x, out var slope, out var intercept)
                            || ValueOf(slope) is not { } a || a == 0 || ValueOf(intercept) is not { } b)
                            yield break;
                        places.Add(-b / a);
                    }
                    places = places.Distinct().OrderBy(place => place).ToList();
                    var bounds = new List<double> { places[0] - 1 };
                    bounds.AddRange(places);
                    bounds.Add(places[^1] + 1);
                    var integrand = pinned(expr);
                    for (var i = 0; i + 1 < bounds.Count; i++)
                    {
                        var (low, high) = (bounds[i], bounds[i + 1]);
                        if (high - low < 1e-9)
                            continue;
                        var at = (low + high) / 2;
                        if (Numerics.IntervalEvaluation.Of(integrand.Substitute(x, at)) is not { IsFinite: true } value || !value.Im.ContainsZero)
                            continue;
                        var signs = new int[linears.Count];
                        var read = true;
                        for (var j = 0; j < linears.Count && read; j++)
                            if (ValueOf(pinnedLinears[j].Substitute(x, at)) is { } sign && sign != 0)
                                signs[j] = System.Math.Sign(sign);
                            else
                                read = false;
                        if (read)
                            yield return (signs, pinned, low, high);
                    }
                }
            }

            // The square root of a quotient of monomials in the symbols with a positive square
            // rational coefficient and even powers -- `1/a^2` is `(1/a)^2` -- and null otherwise.
            static Entity? AMonomialSquareRoot(Entity constant)
            {
                var (above, below) = Functions.SingleQuotient.Of(Functions.PartialFractions.InLowestTermsOverTheSymbols(constant));
                return RootOf(above) is { } top && RootOf(below) is { } bottom ? top / bottom : null;

                static Entity? RootOf(Entity monomial)
                {
                    Entity root = Number.Integer.One;
                    foreach (var factor in Mulf.LinearChildren(monomial))
                        switch (factor)
                        {
                            case Number.Integer { EInteger: var whole } when whole.Sign > 0 && whole.Sqrt() is var floor && floor.Multiply(floor).Equals(whole):
                                root *= Number.Integer.Create(floor);
                                break;
                            case Powf(Variable symbol, Number.Integer { EInteger: var power }) when power.Sign > 0 && power.IsEven:
                                root *= MathS.Pow(symbol, Number.Integer.Create(power.Divide(EInteger.FromInt32(2))));
                                break;
                            default:
                                return null;
                        }
                    return root;
                }
            }
        }

        /// <summary>
        /// Whether <paramref name="expr"/> over <paramref name="derivative"/> takes two values at
        /// two points where <paramref name="candidate"/>, a sine, cosine, tangent, cotangent,
        /// secant or cosecant of a linear, takes one -- every other symbol pinned -- which no
        /// function of the candidate does. False for any other candidate, and wherever a value
        /// cannot be had or the candidate itself does not repeat there.
        /// </summary>
        private static bool TheQuotientDisagreesWhereTheCandidateRepeats(Entity expr, Entity derivative, Entity candidate, Entity.Variable x)
        {
            Entity? argument = candidate switch
            {
                Sinf(var a) => a, Cosf(var a) => a, Tanf(var a) => a,
                Cotanf(var a) => a, Secantf(var a) => a, Cosecantf(var a) => a,
                _ => null,
            };
            if (argument is null || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var intercept)
                || slope.Evaled is Number.Complex { IsZero: true })
                return false;
            Entity first = Number.Real.Create(EDecimal.FromString("0.37"));
            Entity second = candidate switch
            {
                Sinf or Cosecantf => (MathS.pi - 2 * intercept) / slope - first,
                Cosf or Secantf => -2 * intercept / slope - first,
                _ => first + MathS.pi / slope,
            };
            var pinned = new Dictionary<Variable, Entity>();
            var values = new[] { "1.37", "0.61", "2.23", "1.91", "0.83", "1.13" };
            var index = 0;
            foreach (var symbol in expr.Vars.Concat(derivative.Vars).Concat(candidate.Vars).Distinct())
                if (symbol != x)
                    pinned[symbol] = Number.Real.Create(EDecimal.FromString(values[index++ % values.Length]));
            Number.Complex? At(Entity function, Entity point)
            {
                var value = function.Substitute(x, point);
                foreach (var pair in pinned)
                    value = value.Substitute(pair.Key, pair.Value);
                return value.Evaled is Number.Complex { IsNaN: false } number && number.IsFinite ? number : null;
            }
            static bool Close(Number.Complex left, Number.Complex right, double tolerance)
            {
                var scale = System.Math.Max(1.0, ((Number.Real)left.Abs()).EDecimal.ToDouble());
                return ((Number.Real)(left - right).Abs()).EDecimal.ToDouble() <= tolerance * scale;
            }
            if (At(candidate, first) is not { } candidateFirst || At(candidate, second) is not { } candidateSecond
                || !Close(candidateFirst, candidateSecond, 1e-9))
                return false;
            var quotient = expr / derivative;
            return At(quotient, first) is { } quotientFirst && At(quotient, second) is { } quotientSecond
                && !Close(quotientFirst, quotientSecond, 1e-6);
        }

        /// <summary>
        /// <paramref name="integrandInU"/> with the part of it still in <paramref name="x"/> written
        /// in <paramref name="uSub"/>, where that part is a constant times a power of the candidate
        /// <paramref name="u"/>, from <c>-2</c> to <c>2</c>; or <see langword="null"/>.
        /// </summary>
        /// <remarks>
        /// What the two are made of, compared without evaluating, and then the ratio at three points,
        /// every other symbol pinned, screen each power cheaply, and only one that passes is worked
        /// out: over one bar, with a negative fractional power written as a quotient by the
        /// positive one, which it is on every branch, and simplified. That is what puts the
        /// derivative of <c>sqrt(1 - a x)/sqrt(1 + a x)</c>, a sum of two quotients of roots, over
        /// one bar, and takes what is left beside <c>u^(-1)</c> to <c>-1/(2 a)</c>. A constant that
        /// keeps an x is no constant, and the candidate stays refused.
        /// </remarks>
        private static Entity? WithTheCandidatesPowerLeftInX(Entity integrandInU, Entity u, Variable uSub, Entity.Variable x)
        {
            // Not for a linear candidate: what is left of x beside `u = f x` is always a power of u,
            // and taking the change of scale here asks the same question again in u, ahead of the
            // rules that answer it. `(c + d x)^2/(a + i a tan(e + f x))^3` is answered in 33 s,
            // and with the change of scale taken here, not in 70. A quadratic is another matter:
            // beside `u = a + b x + c x^2`, what `F^(1/u) (b + 2 c x)/u^2` leaves is `1/u^2`
            // spelled otherwise, and read as one it is `-F^(1/u)/ln(F)` at once.
            if (IsWrittenAsAPolynomial(u, x) && TreeAnalyzer.TryGetPolynomial(u, x, out var asAPolynomial)
                && asAPolynomial.Keys.Max()!.CompareTo(EInteger.One) <= 0)
                return null;
            Entity inX = Number.Integer.One;
            Entity rest = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(integrandInU))
                if (factor.ContainsNode(x))
                {
                    if (factor.ContainsNode(uSub))
                        return null;
                    inX = underneath ? inX / factor : inX * factor;
                }
                else
                    rest = underneath ? rest / factor : rest * factor;
            // A constant times a power of the candidate is made of what the candidate is made of:
            // its functions of x, its radicands, the bases of its powers with x in the exponent.
            // Checked first, since it costs no evaluation: a decline spends a thousand candidates
            // here, and a polynomial left beside `erfc(a + b x)` is none of them.
            if (!TheBuildingBlocks(inX, x).SetEquals(TheBuildingBlocks(u, x)))
                return null;
            foreach (var power in ThePowersTheRatioAgreesFor(inX, u, x))
            {
                var ofTheCandidate = MathS.Pow(u, power);
                var overRoots = (inX / ofTheCandidate).Replace(node =>
                    node is Powf(var radicand, Number.Rational { IsNegative: true } negative) && negative is not Number.Integer
                        ? Number.Integer.One / MathS.Pow(radicand, -negative)
                        : node);
                var constant = Functions.PartialFractions.Bare(Functions.SingleQuotient.Combine(overRoots).Simplify());
                // Where the simplification leaves x, over one bar the two halves may be polynomials
                // in x, one a constant multiple of the other: `f (d^2 - e^2 x^2)` over
                // `2 d e f (d^2 - e^2 x^2)` is `1/(2 d e)`.
                if (constant.ContainsNode(x)
                    && Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(constant)) is var (above, below)
                    && TheConstantRatioOf(above, below, x) is { } ratio)
                    constant = ratio;
                if (constant.ContainsNode(x) || constant.Nodes.Any(node => node == MathS.NaN)
                    || constant.Evaled is Number.Complex { IsZero: true })
                    continue;
                // One quotient, which is what the rules for `F^(k u)/u` read.
                return Functions.SingleQuotient.Combine(rest * constant * MathS.Pow(uSub, power)).InnerSimplified;
            }
            return null;
        }

        /// <summary>
        /// <paramref name="above"/>/<paramref name="below"/>, two polynomials in <paramref name="x"/>,
        /// as a constant, or <see langword="null"/> where one is not a constant multiple of the
        /// other. Read off the coefficients, expanded so that a term such as <c>f (d e - d e) x</c>
        /// the simplification leaves standing is not counted: with leading coefficients <c>p</c> and
        /// <c>q</c>, every pair <c>a_k</c>, <c>b_k</c> has <c>a_k q - b_k p</c> expand to zero, which
        /// asks no division by a symbol, and the ratio is <c>p/q</c> in lowest terms. The
        /// simplifier would not cancel <c>e^5 f/e^3</c> against <c>e^2 f</c>, for want of knowing
        /// <c>e</c> is not zero.
        /// </summary>
        private static Entity? TheConstantRatioOf(Entity above, Entity below, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare(above.Expand()), x, out var top)
                || !TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare(below.Expand()), x, out var bottom))
                return null;
            static bool IsZero(Entity coefficient)
                => Functions.PartialFractions.Bare(coefficient.Expand()) is var expanded
                   && (expanded == Number.Integer.Zero || expanded.Evaled is Number.Complex { IsZero: true });
            var topTerms = top.Where(term => !IsZero(term.Value)).ToDictionary(term => term.Key, term => term.Value);
            var bottomTerms = bottom.Where(term => !IsZero(term.Value)).ToDictionary(term => term.Key, term => term.Value);
            if (bottomTerms.Count == 0 || topTerms.Count != bottomTerms.Count || topTerms.Keys.Any(degree => !bottomTerms.ContainsKey(degree))
                || topTerms.Values.Concat(bottomTerms.Values).Any(coefficient => coefficient.ContainsNode(x)))
                return null;
            var degree = bottomTerms.Keys.Max()!;
            var (p, q) = (topTerms[degree], bottomTerms[degree]);
            foreach (var term in bottomTerms)
                if (!IsZero(topTerms[term.Key] * q - term.Value * p))
                    return null;
            return Functions.PartialFractions.InLowestTermsOverTheSymbols(p / q);
        }

        /// <summary>
        /// The powers <c>k</c>, of <c>-1</c>, <c>1</c>, <c>-2</c> and <c>2</c>, for which
        /// <paramref name="expr"/>/<paramref name="candidate"/>^k is one nonzero number at three
        /// points, every other symbol pinned, agreeing to nine digits relative to its size. Each side
        /// is evaluated once a point. A point where either cannot be evaluated admits no power: the
        /// screen is all that keeps <see cref="WithTheCandidatesPowerLeftInX"/> from simplifying. And
        /// no ratio near zero, where two tiny values agree to any absolute tolerance:
        /// <c>x erfc(a + b x)^2</c> is 1e-9 at one pinned point and 1e-28 at the next.
        /// </summary>
        private static IEnumerable<int> ThePowersTheRatioAgreesFor(Entity expr, Entity candidate, Entity.Variable x)
        {
            var pinned = new Dictionary<Variable, Entity>();
            var values = new[] { 1.37, 0.61, 2.23, 1.91, 0.83, 1.13 };
            var index = 0;
            foreach (var symbol in expr.Vars.Concat(candidate.Vars).Distinct())
                if (symbol != x)
                    pinned[symbol] = values[index++ % values.Length];
            Number.Complex? At(Entity function, double point)
            {
                var value = function.Substitute(x, point);
                foreach (var pair in pinned)
                    value = value.Substitute(pair.Key, pair.Value);
                return value.Evaled is Number.Complex { IsNaN: false } number && number.IsFinite && !number.IsZero ? number : null;
            }
            var powers = new List<int> { -1, 1, -2, 2 };
            var first = new Dictionary<int, Number.Complex>();
            foreach (var point in new[] { 0.37, 1.71, -0.83 })
            {
                if (At(expr, point) is not { } above || At(candidate, point) is not { } below)
                    return System.Array.Empty<int>();
                foreach (var power in powers.ToList())
                {
                    var ofTheCandidate = power switch { -1 => 1 / below, 1 => below, -2 => 1 / (below * below), _ => below * below };
                    var ratio = (Number.Complex)(above / ofTheCandidate);
                    var size = ((Number.Real)ratio.Abs()).EDecimal.ToDouble();
                    if (!(size > 1e-12 && size < 1e12)
                        || first.TryGetValue(power, out var earlier) && ((Number.Real)(ratio - earlier).Abs()).EDecimal.ToDouble() > 1e-9 * size)
                        powers.Remove(power);
                    else if (!first.ContainsKey(power))
                        first[power] = ratio;
                }
                if (powers.Count == 0)
                    break;
            }
            return powers;
        }

        /// <summary>
        /// Whether <paramref name="expr"/> is written as a polynomial in <paramref name="x"/>: x in
        /// sums, products and whole powers that are not negative only, and nowhere below a bar.
        /// Read off the tree, with nothing expanded, since the substitution search asks it of every
        /// candidate.
        /// </summary>
        private static bool IsWrittenAsAPolynomial(Entity expr, Entity.Variable x)
            => expr.ContainsNode(x) && expr.Nodes.All(node => !node.ContainsNode(x)
                || node is Variable or Sumf or Minusf or Mulf
                || node is Powf(_, Number.Integer { EInteger.Sign: >= 0 })
                || node is Divf(_, var below) && !below.ContainsNode(x));

        /// <summary>
        /// What <paramref name="expr"/> is made of in <paramref name="x"/> beyond sums, products,
        /// quotients and whole powers: each function of x, each root's radicand, and the base of
        /// each power with x in its exponent.
        /// </summary>
        private static HashSet<Entity> TheBuildingBlocks(Entity expr, Entity.Variable x)
        {
            var blocks = new HashSet<Entity>();
            foreach (var node in expr.Nodes)
                switch (node)
                {
                    case Variable or Number or Sumf or Minusf or Mulf or Divf:
                        break;
                    case Powf(_, var exponent) when !exponent.ContainsNode(x) && exponent is Number.Integer:
                        break;
                    case Powf(var @base, _):
                        if (node.ContainsNode(x))
                            blocks.Add(@base);
                        break;
                    default:
                        if (node.ContainsNode(x))
                            blocks.Add(node);
                        break;
                }
            return blocks;
        }

        /// <summary>
        /// Whether <paramref name="expr"/>/<paramref name="reference"/> takes the same value at two
        /// points, every other symbol pinned to a fixed value -- a necessary condition for a
        /// constant ratio, and a cheap one. Where either side cannot be evaluated the question is
        /// left to the symbolic check.
        /// </summary>
        private static bool HasTheSameRatioAtTwoPoints(Entity expr, Entity reference, Entity.Variable x)
        {
            var pinned = new Dictionary<Variable, Entity>();
            var values = new[] { 1.37, 0.61, 2.23, 1.91, 0.83, 1.13 };
            var index = 0;
            foreach (var symbol in expr.Vars.Concat(reference.Vars).Distinct())
                if (symbol != x)
                    pinned[symbol] = values[index++ % values.Length];
            Number.Complex? RatioAt(double at)
            {
                var top = expr.Substitute(x, at);
                var bottom = reference.Substitute(x, at);
                foreach (var pair in pinned)
                {
                    top = top.Substitute(pair.Key, pair.Value);
                    bottom = bottom.Substitute(pair.Key, pair.Value);
                }
                return top.Evaled is Number.Complex a && bottom.Evaled is Number.Complex b && !b.IsZero
                    ? (Number.Complex)(a / b) : null;
            }
            if (RatioAt(0.37) is not { } first || RatioAt(1.71) is not { } second)
                return true;
            var difference = (first - second).Abs() as Number.Real;
            var scale = System.Math.Max(1.0, (double)((Number.Real)first.Abs()).EDecimal.ToDouble());
            return difference is null || (double)difference.EDecimal.ToDouble() <= 1e-9 * scale;
        }

        /// <summary>
        /// <paramref name="expr"/> as a constant times <paramref name="reference"/>, both
        /// polynomials in <paramref name="x"/> of the same degree: the ratio of the leading
        /// coefficients, where every other coefficient agrees with it once simplified.
        /// </summary>
        private static Entity? TryReadAsAConstantMultiple(Entity expr, Entity reference, Entity.Variable x, bool allowOne = false)
        {
            // Read as written, or simplified first: the normalisation makes a power of a
            // polynomial with a symbolic leading coefficient monic and writes the constant term as
            // `d^0 (-1)^(-1) c^(-2)`, which the polynomial reader does not take -- and that is the
            // spelling `(d - c^2 d x^2)^3` below the bar arrives in. Bare, because `d^0` simplifies
            // to `1 provided not d = 0`, and a condition is not a polynomial either.
            if (!TreeAnalyzer.TryGetPolynomial(expr, x, out var mine)
                && !TreeAnalyzer.TryGetPolynomial(Functions.PartialFractions.Bare(expr.InnerSimplified), x, out mine))
                return null;
            if (!TreeAnalyzer.TryGetPolynomial(reference, x, out var theirs)
                || mine.Count != theirs.Count || mine.Values.Any(c => c.ContainsNode(x)) || theirs.Values.Any(c => c.ContainsNode(x)))
                return null;
            var top = theirs.Keys.Max()!;
            if (!mine.TryGetValue(top, out var leading) || theirs[top].Evaled is Number.Complex { IsZero: true })
                return null;
            // A constant multiple has the same ratio everywhere, so two points settle most pairs
            // before anything is simplified: the check below simplifies symbolic differences, and
            // asked of every power in a by-parts remainder of `atan(c x/sqrt(a - c^2 x^2))^2/
            // sqrt(d - c^2 d x^2/a)` -- two hundred of them -- it took twenty-five seconds.
            if (!HasTheSameRatioAtTwoPoints(expr, reference, x))
                return null;
            // Simplified where it holds symbols: the ratio of the leading coefficients of
            // `d - c^2 d x^2` and `c^2 x^2 - 1` is `-c^2 d/c^2` to the inner simplification, and
            // written into a whole power that way it cost the integrand its time -- `-d` is
            // what the rules below want to see.
            var lambda = (leading / theirs[top]).InnerSimplified;
            if (lambda.Vars.Any())
                lambda = Functions.PartialFractions.Bare(lambda.Simplify());
            if (lambda.Evaled is Number.Complex { IsZero: true } || lambda == Number.Integer.One && !allowOne)
                return null;
            foreach (var pair in theirs)
            {
                if (!mine.TryGetValue(pair.Key, out var own))
                    return null;
                var difference = (own - lambda * pair.Value).InnerSimplified;
                if (difference.Evaled is Number.Complex { IsZero: true })
                    continue;
                if (!difference.Vars.Any() || Functions.PartialFractions.Bare(difference.Simplify()).Evaled is not Number.Complex { IsZero: true })
                    return null;
            }
            return lambda;
        }

        /// <summary>
        /// A fractional or symbolic power of a monomial, distributed: <c>(c x^n)^b</c> is
        /// <c>c^b x^(n b)</c> for a positive <c>c</c> and a <c>n</c> that is not whole.
        /// </summary>
        internal static Entity? SolveByDistributingAPowerOfAMonomial(Entity expr, Entity.Variable x, bool integrateByParts)
            => DistributeAFractionalPower(expr, x, integrateByParts, constantAlone: false);

        /// <summary>
        /// A constant taken out of a fractional power of a factor in which <c>x</c> enters only
        /// through trigonometric functions: <c>sqrt(b sec(x))</c> is <c>sqrt(b) sqrt(sec(x))</c>
        /// and <c>sqrt(a - a sin(x)^2)</c> is <c>sqrt(a) sqrt(1 - sin(x)^2)</c>, for a positive
        /// constant, which the answer says where the constant is a symbol.
        /// </summary>
        internal static Entity? SolveByTakingAConstantOutOfAFractionalPower(Entity expr, Entity.Variable x, bool integrateByParts)
            => DistributeAFractionalPower(expr, x, integrateByParts, constantAlone: true);

        /// <summary>
        /// A constant taken out of a fractional power, and a power of the variable split off
        /// with it: <c>(c g)^b</c> is <c>c^b g^b</c> for a positive <c>c</c>, and <c>(c x^n)^b</c>
        /// is <c>c^b x^(n b)</c> where <c>n</c> is not whole. <c>sqrt(b sec(y))/sec(y)^(7/2)</c>
        /// is <c>sqrt(b) cos(y)^3</c> and was read by nothing; <c>x^2 sin(a + b ln(c x^n))</c>
        /// folds to a power of <c>c x^n</c> and stopped there.
        /// </summary>
        /// <remarks>
        /// Exact on the domain the integrand has. With a symbolic <c>n</c>, <c>x^n</c> is real
        /// only for a positive <c>x</c> -- at a negative one it is a complex number or nothing --
        /// so the integrand is defined there and nowhere else, and on <c>x &gt; 0</c> the
        /// identity holds for a positive <c>c</c>. That condition travels with the answer as
        /// <c>provided c &gt; 0</c>, unless <c>c</c> is a positive number already; the
        /// <c>(e x)^(n - 1)</c> of Rubi's 6.5.2 carries the same one. A whole exponent is
        /// <see cref="SolveByDistributingWholePowersOfProducts"/>'s, and needs no condition.
        /// The two are asked from two places: the monomial where it always was, and the constant
        /// alone after the rules that answer its shapes for any real constant, since this one
        /// owes <c>provided c &gt; 0</c> and, asked first, answered them weaker.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        private static Entity? DistributeAFractionalPower(Entity expr, Entity.Variable x, bool integrateByParts, bool constantAlone)
        {
            Entity assumed = Entity.Boolean.True;
            var changed = false;
            var written = expr.Replace(node =>
            {
                if (node is not Powf(var @base, var exponent) || exponent.ContainsNode(x) || exponent is Number.Integer
                    || !@base.ContainsNode(x))
                    return node;
                // The base as a constant times the rest: `(c g)^b` is `c^b g^b` for a positive
                // real `c` and any `g`, on the principal branch and with nothing assumed about
                // `g` -- both sides pick up the same phase where `g` is negative. The rest is
                // read as `x^n` where it is one, since `(x^n)^b` is `x^(n b)` under the
                // condition below and that is what makes the power rule answer it.
                Entity constant = Number.Integer.One;
                Entity rest = Number.Integer.One;
                Entity? degree = null;
                Entity? single = null;
                var restFactors = 0;
                // Each product starts at its first factor rather than at `1 * factor`: a
                // quotient `1/s` arrives as the factors `1` and `s^(-1)`, and a constant built as
                // `1 * 1` is not `1` as a tree, so the rule would take out nothing, believe it had
                // taken something, and ask the same question again.
                foreach (var factor in Mulf.LinearChildren(@base))
                {
                    if (!factor.ContainsNode(x))
                    {
                        if (factor != Number.Integer.One)
                            constant = constant == Number.Integer.One ? factor : constant * factor;
                        continue;
                    }
                    rest = rest == Number.Integer.One ? factor : rest * factor;
                    restFactors++;
                    single = factor;
                    if (degree is not null)
                    {
                        degree = null;
                        continue;
                    }
                    switch (factor)
                    {
                        case Variable bare when bare == x:
                            degree = Number.Integer.One;
                            break;
                        case Powf(Variable bare, var power) when bare == x && !power.ContainsNode(x):
                            degree = power;
                            break;
                    }
                }
                if (rest == Number.Integer.One)
                    return node;
                // A sum is read for the constant written in every one of its terms: `a - a sin(x)^2`
                // is `a (1 - sin(x)^2)`. The substitution for a linear argument happens to write it
                // so, and without this `sqrt(a - a sin(c + d x)^2)` came out where
                // `sqrt(a - a sin(x)^2)` did not.
                if (constantAlone && restFactors == 1 && single is Sumf or Minusf
                    && TakeTheConstantWrittenInEveryTermOut(single, x) is var (content, withoutIt))
                {
                    constant = constant == Number.Integer.One ? content : constant * content;
                    single = withoutIt;
                    rest = withoutIt;
                    degree = null;
                }
                // The power of `x` is split only where `n` is not whole: for a negative `x`,
                // `x^n` is a real number when `n` is whole, and `(x^n)^b` is then `|x|`'s power,
                // not `x`'s -- `(2 u^3)^(3/2)` is `2^(3/2) sgn(u) u^(9/2)`, and splitting it
                // without the sign is a wrong answer where `u < 0`, which the rules for a root
                // of an even power answer correctly and this must leave to them. With a
                // fractional or symbolic `n` the integrand is real only for a positive `x`, and
                // there the split is exact. The constant comes out either way.
                // An even whole power of a function is not this rule's: `(a sin(x)^2)^(5/2)` is
                // `a^(5/2) sgn(sin x) sin(x)^5` for *any* real `a`, because an even power is
                // never negative, and the rule that takes the function out of it with its sign
                // says so unconditionally -- at the top, where it is asked first; below the top
                // it is not asked, and taking the constant out here would answer the same shape
                // `provided a > 0` and carry that up. Read through the nesting and past the
                // sign: `1/sqrt(a cot(x)^2)` arrives at this rule, below the tangent
                // substitution, as `(a/u^2)^(-1/2)`,
                // whose factor is `(u^2)^(-1)` -- an outer exponent of `-1` over an even one,
                // and no less non-negative for either.
                var evenness = EInteger.One;
                for (var peeled = single; peeled is Powf(var peeledBase, Number.Integer step); peeled = peeledBase)
                    evenness = evenness.Multiply(step.EInteger);
                if (evenness.IsEven && !evenness.IsZero)
                    return node;
                var split = degree is not null && degree is not Number.Integer && degree.Evaled is not Number.Integer;
                // Each entry point does one of the two: the power of `x` is split where the
                // monomial rule is asked, and a constant alone taken out where this one is -- after
                // the rules that answer its shapes for any real constant.
                if (split == constantAlone)
                    return node;
                // Taking the constant out rewrites the question, and the rewritten question is
                // asked at the same depth, so the rewrite has to be one that brings the answer
                // closer or it multiplies the search at every level. It does where the rest is a
                // single factor in which `x` enters only through trigonometric functions: `(c f)^b`
                // then becomes a power of `f` that can meet another power of `f` beside it --
                // `sqrt(b sec x)/sec(x)^(7/2)` -- or a root the half-angle rules read, as
                // `sqrt(a + a sin x)` is `sqrt(a) sqrt(1 + sin x)`. Over a product it is no easier:
                // `(cos(x)^11 sin(x)^13)^(-1/4)` went from 10 to 47 seconds. And the hyperbolic
                // functions are written as exponentials, where the same rewrite finds a `2` in
                // `csch(x) = 1/((e^x - e^(-x))/2)` under every substitution below it:
                // `x/csch(x)^(3/2)`, declined in seven seconds, was not declined in ninety. Below a
                // substitution the trigonometric functions are gone, so this also keeps the
                // rewrite to the levels where it was measured.
                if (constantAlone && (constant == Number.Integer.One || restFactors > 1
                    || !EntersOnlyThroughTrigonometricFunctions(single!, x)))
                    return node;
                if (constant != Number.Integer.One && constant.Evaled is not Number.Real { IsPositive: true })
                {
                    if (constant.Vars.Any() is false)
                        return node;
                    var positive = new Greaterf(constant, Number.Integer.Zero);
                    assumed = assumed == Entity.Boolean.True ? positive : assumed & positive;
                }
                changed = true;
                var distributed = split ? MathS.Pow(x, (degree! * exponent).InnerSimplified) : MathS.Pow(rest, exponent);
                return constant == Number.Integer.One ? distributed : MathS.Pow(constant, exponent) * distributed;
            });
            if (!changed)
                return null;
            // A rewrite of the same question has to change the question. The question is asked
            // again without consuming depth, so an integrand rewritten into itself -- which is
            // what `(1/s)^b` was, read as `1^b (1/s)^b` -- is asked again at every level of the
            // search below it, without bound: `x/csch(x)^(3/2)` declined in seven seconds before
            // this rule and did not come back at all with it.
            var rewritten = written.InnerSimplified;
            if (rewritten == expr || rewritten == expr.InnerSimplified)
                return null;
            if (Integration.ComputeAsTheSameQuestion(rewritten, x, integrateByParts) is not { } answer)
                return null;
            return assumed == Entity.Boolean.True ? answer : answer.Provided(assumed);
        }

        /// <summary>
        /// A pair of hyperbolic powers two apart whose coefficients kill the reduction's
        /// residual: <c>cosh(y)^p - (p - 1)/p cosh(y)^(p - 2)</c> is
        /// <c>sinh(y) cosh(y)^(p - 1)/p</c>, and <c>sinh(y)^p + (p - 1)/p sinh(y)^(p - 2)</c> is
        /// <c>cosh(y) sinh(y)^(p - 1)/p</c>. Neither power has an elementary antiderivative on
        /// its own for a fractional <c>p</c>, and the combination does, which is why the terms
        /// must not be split apart before this is asked.
        /// </summary>
        /// <remarks>
        /// From the reduction <c>int cosh^p = sinh cosh^(p - 1)/p + (p - 1)/p int cosh^(p - 2)</c>,
        /// with the coefficient of the lower power chosen so that what is left to integrate is
        /// nothing; differentiating the answer through <c>sinh^2 = cosh^2 - 1</c> is the whole
        /// proof. Rubi's 6.5.1 and 6.6.1 -- <c>x/sech(x)^(3/2) - x sqrt(sech(x))/3</c> is <c>x</c>
        /// times such a pair -- meet it beside a polynomial, which the common factor of a sum
        /// gathers and parts then separates.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveAPairOfHyperbolicPowersTwoApart(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var s = Variable.CreateUnique(expr, "s_hyp");
            var c = Variable.CreateUnique(expr, "c_hyp");
            if (ReadTheHyperbolicFunctions(expr, x, s, c) is not var (readBack, argument))
            {
                return null;
            }
            // One linear factor in front, at most: `(c + d x)(A f^p + B f^(p - 2))` is
            // `(c + d x) F - d int F` with `F` the pair's antiderivative, and `int F` is
            // `A f^p/(p^2 a^2)` -- both closed, where a second power of `x` would need
            // `int f^p` itself, which is elliptic.
            Entity? inFront = null;
            var overTheTwo = readBack;
            // A sum every term of which carries the factor -- `x A f^p + x B f^(p - 2)` -- is
            // that factor times the pair, and the gathering has not happened yet: this rule
            // runs before the split, which would hand each elliptic term to the whole chain.
            if (readBack.ContainsNode(x) && readBack is Sumf or Minusf
                && TryTakeACommonLinearFactorOfASum(readBack, x) is var (gathered, insideOfSum)
                && !insideOfSum.ContainsNode(x))
            {
                inFront = gathered;
                overTheTwo = insideOfSum;
            }
            else if (readBack.ContainsNode(x))
            {
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(readBack));
                Entity others = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(above))
                {
                    if (factor.ContainsNode(x) && inFront is null
                        && TreeAnalyzer.TryGetPolyLinear(factor, x, out var factorSlope, out _) && !TreeAnalyzer.IsZero(factorSlope))
                        inFront = factor;
                    else
                        others *= factor;
                }
                if (inFront is null)
                    return null;
                overTheTwo = (below == Number.Integer.One ? others : others / below).InnerSimplified;
                if (overTheTwo.ContainsNode(x))
                    return null;
            }
            // Each term over its own bar, and each factor read with the exponent it stands at:
            // `1/sech(y)^(5/2)` arrives as `(c^(-5/2))^(-1)` or as `1/(1/c)^(5/2)` depending on
            // what rewrote it, and both are `c^(5/2)`. A power of a power multiplies.
            var terms = new List<(Entity Coefficient, Variable Function, Number.Rational Exponent)>();
            foreach (var term in Sumf.LinearChildren(overTheTwo))
            {
                Entity coefficient = Number.Integer.One;
                Variable? termFunction = null;
                ERational termExponent = ERational.Zero;
                var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(term));
                foreach (var (side, sign) in new[] { (above, 1), (below, -1) })
                    foreach (var factor in Mulf.LinearChildren(side))
                    {
                        if (!factor.ContainsNode(s) && !factor.ContainsNode(c))
                        {
                            coefficient = sign == 1 ? coefficient * factor : coefficient / factor;
                            continue;
                        }
                        // f, f^p, or (f^p)^q, to any depth of powers.
                        var node = factor;
                        var exponent = ERational.One;
                        while (true)
                        {
                            if (node is Powf(var inner, Number.Rational power))
                            {
                                exponent = exponent.Multiply(power.ERational);
                                node = inner;
                                continue;
                            }
                            // A reciprocal inside the power: `sech(y)^(5/2)` is `(1/c)^(5/2)`,
                            // which is `c^(-5/2)`.
                            if (node is Divf(Number.Integer { EInteger.IsZero: false } one, var reciprocal) && one.EInteger.Equals(EInteger.One))
                            {
                                exponent = exponent.Negate();
                                node = reciprocal;
                                continue;
                            }
                            break;
                        }
                        if (node is not Variable read || read != s && read != c)
                            return null;
                        if (termFunction is not null && termFunction != read)
                            return null;
                        termFunction = read;
                        termExponent = termExponent.Add(sign == 1 ? exponent : exponent.Negate());
                    }
                if (termFunction is null)
                    return null;
                terms.Add((coefficient.InnerSimplified, termFunction, Number.Rational.Create(termExponent)));
            }
            if (terms.Count < 2 || terms.Any(term => term.Function != terms[0].Function))
                return null;
            var function = terms[0].Function;
            // The exponents are one class two apart, so the reduction walks from the highest
            // down; a gap is a term with coefficient zero.
            var highest = terms[0].Exponent.ERational;
            var lowest = terms[0].Exponent.ERational;
            foreach (var term in terms)
            {
                if (term.Exponent.ERational.CompareTo(highest) > 0)
                    highest = term.Exponent.ERational;
                if (term.Exponent.ERational.CompareTo(lowest) < 0)
                    lowest = term.Exponent.ERational;
            }
            static bool IsAWholeNumberOfSteps(ERational difference)
            {
                // ToLowestTerms: a difference of two halves comes back as `8/2` unreduced.
                var reduced = difference.ToLowestTerms();
                return reduced.Denominator.Equals(EInteger.One) && reduced.Numerator.Remainder(EInteger.FromInt32(2)).IsZero;
            }
            if (terms.Any(term => !IsAWholeNumberOfSteps(highest.Subtract(term.Exponent.ERational))))
                return null;
            var steps = highest.Subtract(lowest).ToLowestTerms().Numerator.Divide(EInteger.FromInt32(2));
            if (steps.CompareTo(EInteger.FromInt32(8)) > 0)
                return null;
            if (terms.All(term => term.Exponent is Number.Integer))
                return null;
            if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                return null;

            // int f^e = g f^(e - 1)/(e a) + s (e - 1)/e int f^(e - 2), with g the other function,
            // s = +1 for the hyperbolic cosine (sinh^2 = cosh^2 - 1) and -1 for the sine
            // (cosh^2 = sinh^2 + 1), and a the argument's slope. Walking down from the highest
            // exponent, each term's coefficient is its own plus what the step above carried; the
            // sum is elementary exactly when nothing is carried past the lowest.
            var other = function == c ? MathS.Hyperbolic.Sinh(argument) : MathS.Hyperbolic.Cosh(argument);
            var self = function == c ? MathS.Hyperbolic.Cosh(argument) : MathS.Hyperbolic.Sinh(argument);
            var reductionSign = function == c ? Number.Integer.One : Number.Integer.Create(-1);
            Entity antiderivative = Number.Integer.Zero;
            Entity integralOfAntiderivative = Number.Integer.Zero;
            Entity carried = Number.Integer.Zero;
            for (var at = highest; at.CompareTo(lowest) >= 0; at = at.Subtract(ERational.FromInt32(2)))
            {
                Entity written = Number.Rational.Create(at);
                Entity coefficient = carried;
                foreach (var term in terms)
                    if (term.Exponent.ERational.Equals(at))
                        coefficient += term.Coefficient;
                coefficient = Functions.PartialFractions.Bare(coefficient.InnerSimplified);
                if (at.IsZero || coefficient == Number.Integer.Zero)
                {
                    carried = Number.Integer.Zero;
                    if (!at.IsZero)
                        continue;
                    return null;
                }
                // g f^(e - 1)/(e a), and its own antiderivative f^e/(e^2 a^2), which is what a
                // linear factor in front needs.
                var below = (written - Number.Integer.One).InnerSimplified;
                antiderivative += coefficient * other * MathS.Pow(self, below) / (written * slope);
                integralOfAntiderivative += coefficient * MathS.Pow(self, written) / (written * written * slope * slope);
                carried = Functions.PartialFractions.Bare((reductionSign * coefficient * (written - Number.Integer.One) / written).InnerSimplified);
            }
            if (carried != Number.Integer.Zero && Functions.PartialFractions.Bare(carried.Simplify()) != Number.Integer.Zero)
                return null;
            if (inFront is null)
                return antiderivative.InnerSimplified;
            if (!TreeAnalyzer.TryGetPolyLinear(inFront, x, out var frontSlope, out _))
                return null;
            return (inFront * antiderivative - frontSlope * integralOfAntiderivative).InnerSimplified;
        }

        /// <summary>
        /// A sine or cosine of a linear form with a phase, beside an exponential, expanded by the
        /// angle-sum identity so that both are of the same bare multiple of the variable:
        /// <c>cos(f x + p)</c> is <c>cos(p) cos(f x) - sin(p) sin(f x)</c>. The closed rule for a
        /// polynomial times an exponential times a trigonometric reads one frequency and no
        /// phase -- an exponential's own offset is a constant factor, a trigonometric's is not --
        /// and a phase is what every row of Rubi's 4.3.10 and 4.4.10 carries once
        /// <c>A + i A tan(pe + f x)</c> is written as an exponential over a cosine.
        /// </summary>
        /// <remarks>
        /// Only beside an exponential of the variable, which is the shape that rule answers: the
        /// expansion doubles the terms of every sine and cosine it touches, and the sum split
        /// would then answer `sin(a + b x)` as two integrals where one closed rule answers it as
        /// one. Once: the expanded form has no phase left.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByExpandingATrigonometricPhaseBesideAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAsked)
                return null;
            // An exponential of the variable among the factors, and a phase to expand.
            if (!expr.Nodes.Any(node => node is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x)))
                return null;
            var expanded = expr.Replace(node =>
            {
                Entity argument;
                bool isSine;
                switch (node)
                {
                    case Sinf(var inner): (argument, isSine) = (inner, true); break;
                    case Cosf(var inner): (argument, isSine) = (inner, false); break;
                    default: return node;
                }
                if (!argument.ContainsNode(x) || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out var offset)
                    || TreeAnalyzer.IsZero(slope) || offset.ContainsNode(x) || TreeAnalyzer.IsZero(offset)
                    || offset.Evaled is Number.Integer(0))
                    return node;
                var bare = (slope * x).InnerSimplified;
                return isSine
                    ? MathS.Sin(offset) * MathS.Cos(bare) + MathS.Cos(offset) * MathS.Sin(bare)
                    : MathS.Cos(offset) * MathS.Cos(bare) - MathS.Sin(offset) * MathS.Sin(bare);
            });
            if (expanded == expr)
                return null;
            return Integration.ComputeAsAQuestionOfItsOwn(expanded.Expand().InnerSimplified, x, integrateByParts);
        }

        /// <summary>
        /// <c>A + i A tan(z)</c> is <c>A e^(i z)/cos(z)</c>, and <c>A + i A cot(z)</c> is
        /// <c>i A e^(-i z)/sin(z)</c> -- exactly, wherever the tangent is defined, since
        /// <c>cos(z) + i sin(z)</c> is <c>e^(i z)</c>. A power of one of them below the bar is
        /// then a power of the cosine times an exponential, and beside a polynomial that is a
        /// shape the closed rules answer: <c>(c + d x)^2/(a + i a tan(pe + f x))^2</c> is a
        /// search past the budget as written and a second once rewritten.
        /// </summary>
        /// <remarks>
        /// The four signs are the four identities: <c>A - i A tan(z)</c> is
        /// <c>A e^(-i z)/cos(z)</c> and <c>A - i A cot(z)</c> is <c>-i A e^(i z)/sin(z)</c>.
        /// Rubi's 4.3.10 and 4.4.10, where every such row carries the imaginary unit in the
        /// coefficient and nothing else reads it. The same question, not one of its own: what is
        /// handed on is the integrand in another spelling.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAnImaginaryTangentAsAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // Below the bar only: `(A + i A tan(z))^3` above it is a polynomial in the tangent,
            // which the rules for those answer in the tangent and more shortly, where the
            // reciprocal is what nothing reads.
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            if (!below.ContainsNode(x))
                return null;
            var arguments = new List<Entity>();
            var rewritten = below.Replace(node =>
            {
                if (node is not Sumf and not Minusf || !node.ContainsNode(x))
                    return node;
                Entity constant = Number.Integer.Zero;
                Entity? coefficient = null;
                Entity? argument = null;
                var isTangent = false;
                foreach (var term in Sumf.LinearChildren(node))
                {
                    if (!term.ContainsNode(x))
                    {
                        constant += term;
                        continue;
                    }
                    if (coefficient is not null)
                        return node;
                    Entity factors = Number.Integer.One;
                    foreach (var factor in Mulf.LinearChildren(term))
                        switch (factor)
                        {
                            case Tanf(var inner) when argument is null:
                                (argument, isTangent) = (inner, true);
                                break;
                            case Cotanf(var inner) when argument is null:
                                (argument, isTangent) = (inner, false);
                                break;
                            default:
                                if (factor.ContainsNode(x))
                                    return node;
                                factors *= factor;
                                break;
                        }
                    if (argument is null)
                        return node;
                    coefficient = factors;
                }
                if (coefficient is null || argument is null || constant == Number.Integer.Zero)
                    return node;
                // The ratio is the imaginary unit one way or the other, and nothing else.
                // Bare: `i a/a` simplifies to `i provided not a = 0`, and a condition is not a
                // number to compare against.
                var ratio = Functions.PartialFractions.Bare((coefficient / constant).InnerSimplified);
                if (ratio.Evaled is not Number.Complex)
                    ratio = Functions.PartialFractions.Bare(ratio.Simplify());
                var plus = ratio.Evaled == MathS.i.Evaled;
                if (!plus && ratio.Evaled != (-MathS.i).Evaled)
                    return node;
                var exponential = MathS.Pow(MathS.e, ((plus == isTangent ? MathS.i : -MathS.i) * argument).InnerSimplified);
                arguments.Add(argument);
                // A + i A tan(z) is A e^(iz)/cos(z); A + i A cot(z) is i A e^(-iz)/sin(z).
                return isTangent
                    ? constant * exponential / MathS.Cos(argument)
                    : (plus ? MathS.i : -MathS.i) * constant * exponential / MathS.Sin(argument);
            });
            if (rewritten == below)
                return null;
            // A tangent or a cotangent of the same argument above the bar in sines and cosines, so that
            // the cosine or sine the identity puts below cancels it: `tan(z)/(A + i A tan(z))` is
            // `sin(z) e^(-i z)/A`, an exponential times a sine, where `tan(z) cos(z) e^(-i z)/A` was
            // a search past the budget with `z = c + d x`.
            var inSinesAndCosines = above.Replace(node => node switch
            {
                Tanf(var inner) when arguments.Contains(inner) => MathS.Sin(inner) / MathS.Cos(inner),
                Cotanf(var inner) when arguments.Contains(inner) => MathS.Cos(inner) / MathS.Sin(inner),
                _ => node,
            });
            var (numerator, denominator) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(inSinesAndCosines / rewritten));
            var (top, bottom) = CancelledWithFunctionsAsIndeterminates(numerator, denominator, x, expr);
            // Only where what is left is made of those sines and cosines, exponentials of linears and
            // polynomials in x: a secant or a root beside them, `sec(z)^8/(A + i A tan(z))^4`, is read
            // through the tangent as written, and rewritten it was a search of minutes.
            bool Plain(Entity node) => node switch
            {
                _ when !node.ContainsNode(x) => true,
                Entity.Variable => true,
                Sinf(var sineOf) => arguments.Contains(sineOf),
                Cosf(var cosineOf) => arguments.Contains(cosineOf),
                Powf(var @base, Number.Integer) => Plain(@base),
                Powf(var @base, var exponent) => @base == MathS.e && TreeAnalyzer.TryGetPolyLinear(exponent, x, out _, out _),
                Mulf or Divf or Sumf or Minusf => node.DirectChildren.All(Plain),
                _ => false,
            };
            if (!Plain(top) || !Plain(bottom))
                return Integration.ComputeAsTheSameQuestion((above / rewritten).InnerSimplified, x, integrateByParts);
            // And what sines and cosines of it are left, as the exponentials they are, so that the whole is
            // a rational function of `e^(i z)`: `tan(z)^2/(A + i A tan(z))` leaves `sin(z)^2/(A cos(z) e^(i z))`.
            var inExponentials = (top / bottom).Replace(node => node switch
            {
                Sinf(var inner) when arguments.Contains(inner)
                    => (MathS.Pow(MathS.e, MathS.i * inner) - MathS.Pow(MathS.e, -MathS.i * inner)) / (2 * MathS.i),
                Cosf(var inner) when arguments.Contains(inner)
                    => (MathS.Pow(MathS.e, MathS.i * inner) + MathS.Pow(MathS.e, -MathS.i * inner)) / 2,
                _ => node,
            });
            return Integration.ComputeAsTheSameQuestion(inExponentials.InnerSimplified, x, integrateByParts);
        }

        /// <summary>
        /// A power of <c>A + i A tan(z)</c> beside a power of the secant of the same argument, one
        /// of them not whole and the two adding up to a whole number <c>k</c>, integrated as the
        /// exponential it is: <c>A + i A tan(z)</c> is <c>A sec(z) e^(i z)</c> on the real line, so
        /// <c>(A + i A tan(z))^n (c sec(z))^m</c> is a constant on every interval where it is
        /// continuous times <c>sec(z)^k e^(i n z)</c>, which in <c>w = e^(i z)</c> is
        /// <c>(2 w/(w^2 + 1))^k w^n</c>, and <c>dz</c> is <c>dw/(i w)</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sqrt(a + i a tan(x))/sqrt(c sec(x))</c> is <c>sqrt(a/c) e^(i x/2)</c> wherever the
        /// cosine is positive, and was declined, with every other power of the pair whose exponents
        /// add up to a whole number: a root of a sum with the imaginary unit in it beside a root of the
        /// secant is read by no rule, and <c>e^(i x/2)/cos(x)</c>, what the positive sums leave, is
        /// declined as well. Rubi's 4.3.1.2.
        /// </para>
        /// <para>
        /// The constant is not written: the answer is the integrand times the antiderivative in
        /// <c>w</c> over what that antiderivative differentiates back to, <c>sec(z)^k (e^(i z))^n</c>
        /// times <c>i</c> and the slope, a quotient whose logarithmic derivative is zero -- both
        /// halves have <c>n (tan(z) + i) z'</c> -- so it is constant wherever it is continuous, and
        /// the answer holds on every interval where the integrand is.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// </remarks>
        internal static Entity? SolveAPowerOfAnImaginaryTangentBesideAPowerOfTheSecant(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Secantf) || !expr.Nodes.Any(node => node is Tanf))
                return null;
            Entity? argument = null;
            var plus = false;
            Number.Rational? tangentPower = null, secantPower = null;
            Entity constant = Number.Integer.One;
            Entity varying = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!factor.ContainsNode(x))
                {
                    constant = underneath ? constant / factor : constant * factor;
                    continue;
                }
                varying = underneath ? varying / factor : varying * factor;
                var (@base, power) = factor is Powf(var b, var p) && p.Evaled is Number.Rational r
                    ? (b, r)
                    : (factor, (Number.Rational)Number.Integer.One);
                if (underneath)
                    power = (Number.Rational)(-power);
                if (TryReadAnImaginaryTangent(@base, x, out var tangentOf, out var isPlus))
                {
                    if (tangentPower is not null || argument is not null && argument != tangentOf)
                        return null;
                    (tangentPower, argument, plus) = (power, tangentOf, isPlus);
                    continue;
                }
                var secant = @base switch
                {
                    Secantf => @base,
                    Mulf(var left, Secantf right) when !left.ContainsNode(x) => right,
                    Mulf(Secantf left, var right) when !right.ContainsNode(x) => left,
                    _ => null
                };
                if (secant is not Secantf(var secantOf) || secantPower is not null || argument is not null && argument != secantOf)
                    return null;
                (secantPower, argument) = (power, secantOf);
            }
            if (tangentPower is null || secantPower is null || argument is null
                || tangentPower is Number.Integer && secantPower is Number.Integer
                || (tangentPower + secantPower) is not Number.Integer { EInteger: var whole } || !whole.CanFitInInt32()
                || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                return null;
            var k = whole.ToInt32Checked();
            var phase = plus ? tangentPower : (Number.Rational)(-tangentPower);
            // In w = e^(i z): sec(z)^k e^(i n z) dz is (2 w)^k (w^2 + 1)^(-k) w^(n - 1) dw / i.
            var w = Variable.CreateUnique(expr, "w_exp");
            var inW = k >= 0
                ? MathS.Pow(2, k) * MathS.Pow(w, (phase + k - 1).InnerSimplified) / MathS.Pow(MathS.Sqr(w) + 1, k)
                : MathS.Pow(2, k) * MathS.Pow(MathS.Sqr(w) + 1, -k) * MathS.Pow(w, (phase + k - 1).InnerSimplified);
            if (Integration.ComputeAsAQuestionOfItsOwn(inW.InnerSimplified, w, integrateByParts) is not { } inWAnswer
                || inWAnswer.Nodes.Any(node => node == MathS.NaN))
                return null;
            var exponential = MathS.Pow(MathS.e, MathS.i * argument);
            var differentiatesBackTo = MathS.Pow(MathS.Sec(argument), k) * MathS.Pow(exponential, phase);
            return constant * varying * inWAnswer.Substitute(w, exponential) / (MathS.i * slope * differentiatesBackTo);
        }

        /// <summary>
        /// <c>A + i A tan(z)</c> or <c>A - i A tan(z)</c>, with a constant <c>A</c>: the argument,
        /// and whether the imaginary unit comes with a plus.
        /// </summary>
        private static bool TryReadAnImaginaryTangent(Entity sum, Entity.Variable x, out Entity argument, out bool plus)
        {
            (argument, plus) = (Number.Integer.Zero, false);
            if (sum is not Sumf and not Minusf || !sum.ContainsNode(x))
                return false;
            Entity free = Number.Integer.Zero;
            Entity? coefficient = null;
            Entity? tangentOf = null;
            foreach (var term in Sumf.LinearChildren(sum))
            {
                if (!term.ContainsNode(x))
                {
                    free += term;
                    continue;
                }
                if (coefficient is not null)
                    return false;
                Entity factors = Number.Integer.One;
                foreach (var factor in Mulf.LinearChildren(term))
                    if (factor is Tanf(var inner) && tangentOf is null)
                        tangentOf = inner;
                    else if (factor.ContainsNode(x))
                        return false;
                    else
                        factors *= factor;
                if (tangentOf is null)
                    return false;
                coefficient = factors;
            }
            if (coefficient is null || tangentOf is null || free == Number.Integer.Zero)
                return false;
            var ratio = Functions.PartialFractions.Bare((coefficient / free).InnerSimplified);
            if (ratio.Evaled is not Number.Complex)
                ratio = Functions.PartialFractions.Bare(ratio.Simplify());
            plus = ratio.Evaled == MathS.i.Evaled;
            if (!plus && ratio.Evaled != (-MathS.i).Evaled)
                return false;
            argument = tangentOf;
            return true;
        }

        /// <summary>
        /// <c>A cos(y) + i A sin(y)</c> below the bar, written as the exponential it is:
        /// <c>A e^(i y)</c>, and <c>A cos(y) - i A sin(y)</c> as <c>A e^(-i y)</c>. Beside a power
        /// of the cosine above the bar that is an exponential times a power of a cosine, which
        /// the closed rules answer at once; as written it is a sum of a cosine and a sine whose
        /// coefficients have no real rotation -- <c>A^2 + (i A)^2</c> is zero -- and
        /// <c>cos(x)^2/(a cos(x) + i a sin(x))^3</c> was declined after twelve seconds.
        /// </summary>
        /// <remarks>
        /// The sibling of <see cref="SolveByWritingAnImaginaryTangentAsAnExponential"/>, which reads
        /// <c>A + i A tan(y)</c>; below the bar only, for the same reason.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAnImaginarySumOfACosineAndASineAsAnExponential(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr));
            if (!below.ContainsNode(x))
                return null;
            var rewritten = below.Replace(node =>
            {
                if (node is not (Sumf or Minusf) || !node.ContainsNode(x)
                    || !TryReadACosineAndASine(node, x, out var cosineCoefficient, out var sineCoefficient, out var argument))
                    return node;
                // The ratio is the imaginary unit one way or the other, and nothing else. Bare:
                // `i a/a` simplifies to `i provided not a = 0`, and a condition is not a number
                // to compare against.
                var ratio = Functions.PartialFractions.Bare((sineCoefficient / cosineCoefficient).InnerSimplified);
                if (ratio.Evaled is not Number.Complex)
                    ratio = Functions.PartialFractions.Bare(ratio.Simplify());
                var plus = ratio.Evaled == MathS.i.Evaled;
                if (!plus && ratio.Evaled != (-MathS.i).Evaled)
                    return node;
                return cosineCoefficient * MathS.Pow(MathS.e, ((plus ? MathS.i : -MathS.i) * argument).InnerSimplified);
            });
            if (rewritten == below)
                return null;
            // And a whole power of what was written split, `(A e^(i y))^n` as `A^n e^(i n y)`, so
            // that the exponential stands on its own for the rules that read one: the rule that
            // distributes such powers takes a constant with a symbol in it and leaves a number,
            // and `cos(x)^2/(2 e^(i x))^3` was declined where `cos(x)^2/(a e^(i x))^3` was not.
            rewritten = rewritten.Replace(node =>
                node is Powf(Mulf(var left, var right), Number.Integer power)
                && (left is Powf(var leftBase, _) && leftBase == MathS.e || right is Powf(var rightBase, _) && rightBase == MathS.e)
                    ? MathS.Pow(left, power) * MathS.Pow(right, power)
                    : node);
            return Integration.ComputeAsTheSameQuestion((above / rewritten).InnerSimplified, x, integrateByParts);
        }

        /// <summary>
        /// Bioche's first two rules for the hyperbolic functions: a rational function of
        /// <c>sinh(y)</c> and <c>cosh(y)</c> that is odd in the hyperbolic sine is a rational
        /// function of <c>u = cosh(y)</c> times <c>sinh(y) dy = du</c>, with <c>sinh^2</c> as
        /// <c>u^2 - 1</c>; one odd in the hyperbolic cosine is one of <c>u = sinh(y)</c> times
        /// <c>cosh(y) dy = du</c>, with <c>cosh^2</c> as <c>u^2 + 1</c>. Radicals of polynomials
        /// in the two even in the function are admitted as coefficients, as in
        /// <see cref="SolveByBiochesOddSubstitution"/>.
        /// </summary>
        /// <remarks>
        /// The hyperbolic functions are not nodes: the library writes <c>sinh(y)</c> as
        /// <c>(e^y - e^-y)/2</c> and <c>tanh(y)</c> as <c>(e^(2y) - 1)/(e^(2y) + 1)</c>, so the
        /// six are read back by their spellings, for the argument each exponential names, and
        /// nothing else in <c>x</c> may remain. Rubi's <c>sinh(x)^3/(a + b cosh(x)^2)</c> is
        /// <c>(u^2 - 1)/(a + b u^2)</c> here, where under <c>u = e^x</c> it is a rational
        /// function of a symbolic palindromic quartic and under <c>u = tanh(x/2)</c> of one of
        /// degree eight, and both were searches past the budget; <c>cosh(x)/(a + b tanh(x)^2)</c>,
        /// <c>sech(x)/(a + b sinh(x)^2)^(3/2)</c> and <c>csch(x)^5/(a + b cosh(x)^2)</c> likewise.
        /// In front of the substitution search, which with a symbolic coefficient spends the
        /// budget on <c>u = e^x</c>. Exact: <c>cosh</c> is positive, so <c>u = sinh(y)</c> is a
        /// bijection of the line, and <c>u = cosh(y)</c> one on each side of zero.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByBiochesOddHyperbolicSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!Integration.AnsweringTheQuestionAskedOrOneBelow)
                return null;
            var s = Variable.CreateUnique(expr, "s_hyp");
            var c = Variable.CreateUnique(expr, "c_hyp");
            if (ReadTheHyperbolicFunctions(expr, x, s, c) is not var (overTheTwo, argument))
                return null;
            var radicals = new List<(Variable Symbol, Entity Base, Number.Rational Exponent)>();
            overTheTwo = overTheTwo.Replace(node =>
            {
                if (node is not Powf(var radicand, Number.Rational exponent) || exponent is Number.Integer || !radicand.ContainsNode(s) && !radicand.ContainsNode(c))
                    return node;
                var symbol = Variable.CreateUnique(expr, "r_hyp" + radicals.Count);
                var combined = Functions.SingleQuotient.Combine(radicand);
                radicals.Add((symbol, combined, exponent));
                return symbol;
            });
            if (overTheTwo.ContainsNode(x))
                return null;
            // A radicand that is a polynomial in the two, and not a Laurent one: `a + b sech(x)`
            // is `a + b/c`, whose root under u = cosh(x) is a root of `a + b/u`, and the search
            // that follows it is longer than the exponential substitution's.
            if (radicals.Any(radical => radical.Base.ContainsNode(x) || !IsAPolynomialInBoth(radical.Base)))
                return null;
            // The quotient factor by factor, each factor a polynomial in the two, so that a
            // written power -- `(a + b sech(x)^2)^2` -- is handed on as the power it is and not
            // expanded into a symbolic quartic for the rational integrator to factor again.
            var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(overTheTwo));
            var factors = new List<(Entity Base, int Power)>();
            foreach (var (side, sign) in new[] { (above, 1), (below, -1) })
                foreach (var factor in Mulf.LinearChildren(side))
                {
                    var (factorBase, power) = factor is Powf(var inner, Number.Integer whole) && whole.EInteger.CanFitInInt32() ? (inner, whole.EInteger.ToInt32Unchecked()) : (factor, 1);
                    factorBase = factorBase.Expand();
                    if (!IsAPolynomialInBoth(factorBase))
                        return null;
                    factors.Add((factorBase, sign * power));
                }
            bool IsAPolynomialInBoth(Entity polynomial)
                => TreeAnalyzer.TryGetPolynomial(polynomial, s, out var inS) && inS.Keys.All(k => k.Sign >= 0)
                    && TreeAnalyzer.TryGetPolynomial(polynomial, c, out var inC) && inC.Keys.All(k => k.Sign >= 0);

            var u = Variable.CreateUnique(expr, "u_hyp");
            foreach (var (odd, even, fSquared, back) in new[]
            {
                (s, c, MathS.Sqr(u) - 1, MathS.Hyperbolic.Cosh(argument)),
                (c, s, MathS.Sqr(u) + 1, MathS.Hyperbolic.Sinh(argument)),
            })
            {
                if (radicals.Any(radical => ParityIn(radical.Base, odd) != 1))
                    continue;
                // An odd factor is f times an even one, and the powers of f are counted, one
                // of them being dx's. A factor neither even nor odd in f -- `1 + sinh(x)` --
                // sends the two sides expanded and cleared against the mirror, as
                // SolveByBiochesOddSubstitution does, since its mirror is in u only beside it.
                Entity numerator = Number.Integer.One;
                Entity denominator = Number.Integer.One;
                var powerOfF = -1;
                var readable = true;
                if (factors.All(factor => ParityIn(factor.Base, odd) != 0))
                {
                    foreach (var (factorBase, power) in factors)
                    {
                        var parity = ParityIn(factorBase, odd);
                        if (InU(factorBase, odd, even, u, fSquared, dividedByOdd: parity == -1) is not { } inU)
                        {
                            readable = false;
                            break;
                        }
                        if (parity == -1)
                            powerOfF += power;
                        var powered = MathS.Pow(inU, Number.Integer.Create(System.Math.Abs(power)));
                        if (power > 0) numerator *= powered; else denominator *= powered;
                    }
                    if (!readable || powerOfF % 2 != 0)
                        continue;
                    var half = powerOfF / 2;
                    if (half > 0)
                        numerator *= MathS.Pow(fSquared, Number.Integer.Create(half));
                    else if (half < 0)
                        denominator *= MathS.Pow(fSquared, Number.Integer.Create(-half));
                }
                else
                {
                    var aboveExpanded = above.Expand();
                    var belowExpanded = below.Expand();
                    var parityOfBelow = ParityIn(belowExpanded, odd);
                    Entity top;
                    Entity bottom;
                    bool oneFOutOfTheNumerator;
                    if (parityOfBelow == 1)
                    {
                        top = aboveExpanded;
                        bottom = belowExpanded;
                        oneFOutOfTheNumerator = true;
                    }
                    else if (parityOfBelow == -1)
                    {
                        top = aboveExpanded;
                        bottom = (belowExpanded * odd).Expand();
                        oneFOutOfTheNumerator = false;
                    }
                    else
                    {
                        var mirrored = belowExpanded.Substitute(odd, -odd).Expand();
                        top = (aboveExpanded * mirrored).Expand();
                        bottom = (belowExpanded * mirrored).Expand();
                        oneFOutOfTheNumerator = true;
                    }
                    if (ParityIn(top, odd) != (oneFOutOfTheNumerator ? -1 : 1) || ParityIn(bottom, odd) != 1)
                        continue;
                    if (InU(top, odd, even, u, fSquared, oneFOutOfTheNumerator) is not { } topInU
                        || InU(bottom, odd, even, u, fSquared, dividedByOdd: false) is not { } bottomInU)
                        continue;
                    numerator = topInU;
                    denominator = bottomInU;
                }
                var radicalsInU = new List<(Variable Symbol, Entity InU)>();
                foreach (var (symbol, radicand, exponent) in radicals)
                {
                    if (InU(radicand, odd, even, u, fSquared, dividedByOdd: false) is not { } radicandInU)
                        break;
                    radicalsInU.Add((symbol, MathS.Pow(radicandInU, exponent)));
                }
                if (radicalsInU.Count != radicals.Count)
                    continue;
                foreach (var (symbol, radical) in radicalsInU)
                {
                    numerator = numerator.Substitute(symbol, radical);
                    denominator = denominator.Substitute(symbol, radical);
                }
                var integrand = Functions.PartialFractions.Bare((numerator / denominator).InnerSimplified);
                if (Integration.ComputeAsAQuestionOfItsOwn(integrand, u, integrateByParts) is not { } result
                    || result.Nodes.Any(node => node == MathS.NaN))
                    continue;
                var answer = result.Substitute(u, back);
                // dx is dy/d for the argument y = c + d x.
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out var slope, out _) || TreeAnalyzer.IsZero(slope))
                    return null;
                var scaled = slope == Number.Integer.One ? answer : answer / slope;
                // Checked where a symbol is involved, as every answer assembled from pieces is.
                if (expr.Vars.Any(symbol => symbol != x) && !Functions.PartialFractions.DerivativeHoldsAtSampledPoints(scaled, expr, x))
                    return null;
                return scaled;
            }
            return null;
        }

        /// <summary>
        /// A half-odd power of the secant or the cosecant, in an integrand with the cosine or the
        /// sine of the same argument in it, written as a power of the cosine or the sine:
        /// <c>sec(z)^p = K/cos(z)^p</c> with <c>K = sec(z)^p cos(z)^p</c>, which is 1 wherever the
        /// cosine is positive and -1 wherever it is negative, so it stands in front of the answer.
        /// </summary>
        /// <remarks>
        /// <para>
        /// <c>sec(x)^(3/2)/sqrt(1 + cos(x))</c> was declined while
        /// <c>1/(cos(x)^(3/2) sqrt(1 + cos(x)))</c>, which it is wherever the cosine is positive,
        /// was answered: the substitutions that read a function of the cosine read the secant as
        /// <c>1/cos</c> to a whole power only. Only beside the cosine, so that a power of the
        /// secant with no cosine keeps the rules for the secant. Rubi's 4.2.2.1, 4.2.3.1 and
        /// 4.2.4.2.
        /// </para>
        /// <para>
        /// Only a half-odd power of the secant itself, because that is what keeps <c>K</c> real:
        /// the integrand is then real exactly where the rewritten one is, and an answer for the
        /// rewritten one, which holds where it is real, holds where the integrand is. A constant
        /// inside the power, <c>sqrt(b sec(x))</c>, or a quarter makes <c>K</c> imaginary on one
        /// side, and the integrand real where the rewritten one is not: for a negative <c>b</c>,
        /// <c>sqrt(b sec(x))</c> is real where the cosine is negative and <c>1/sqrt(cos(x))</c>
        /// is not, and nothing about an answer for the second says anything there.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByWritingAPowerOfTheSecantInTheCosine(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (!expr.Nodes.Any(node => node is Secantf or Cosecantf))
                return null;
            var factors = FactorsOfTheIntegrand(expr);
            var index = -1;
            Entity? reciprocal = null;
            Number.Rational? exponent = null;
            for (var k = 0; k < factors.Count; k++)
            {
                if (factors[k].Factor is not Powf((Secantf or Cosecantf) and var found, var power)
                    || power.Evaled is not Number.Rational fraction || fraction is Number.Integer
                    || !fraction.ERational.Denominator.Equals(EInteger.FromInt32(2)) || !found.ContainsNode(x))
                    continue;
                if (index >= 0)
                    return null;
                (index, reciprocal, exponent) = (k, found, fraction);
            }
            if (index < 0 || reciprocal is null || exponent is null)
                return null;
            var function = reciprocal is Secantf(var argument) ? MathS.Cos(argument) : MathS.Sin(((Cosecantf)reciprocal).Argument);
            // The reciprocal nowhere else and the function somewhere: the power is then all of
            // the secant there is, and the rest of the integrand a function of the cosine.
            if (expr.Nodes.Count(node => node == reciprocal) != 1 || !expr.ContainsNode(function))
                return null;
            var (written, underneath) = factors[index];
            // The power is K/cos^p above the bar and cos^p/K below it. The cosine's power goes to
            // the side where it is positive, so that the rest is one quotient as the rules read it.
            var negative = exponent.ERational.IsNegative;
            var raised = MathS.Pow(function, negative ? -exponent : exponent);
            var raisedAbove = underneath != negative;
            Entity? above = null;
            Entity? below = null;
            for (var k = 0; k < factors.Count; k++)
            {
                var (factor, side) = k == index ? (raised, !raisedAbove) : factors[k];
                if (factor == Number.Integer.One)
                    continue;
                if (side)
                    below = below is null ? factor : below * factor;
                else
                    above = above is null ? factor : above * factor;
            }
            var numerator = above ?? Number.Integer.One;
            var rewritten = below is null ? numerator : numerator / below;
            var constant = written * MathS.Pow(function, exponent);
            return Integration.ComputeAsTheSameQuestion(rewritten, x, integrateByParts)
                ?.Pipe(answer => underneath ? answer / constant : answer * constant);
        }

        /// <summary>
        /// A rational function of <c>sin(x)</c> and <c>cos(x)</c>, turned into a rational function
        /// of one variable by the half-angle substitution <c>t = tan(x/2)</c> and handed to the
        /// machinery for those.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The Weierstrass substitution. Under <c>t = tan(x/2)</c>,
        /// <c>sin(x) = 2t/(1 + t^2)</c>, <c>cos(x) = (1 - t^2)/(1 + t^2)</c> and
        /// <c>dx = 2/(1 + t^2) dt</c>, so anything built from sines and cosines by the field
        /// operations becomes a quotient of polynomials — which partial fractions already answers.
        /// </para>
        /// <para>
        /// <b>What it is for.</b> A family of first-year integrals had no antiderivative at all:
        /// <c>1/(1 + cos(x))</c>, <c>1/(1 - sin(x))</c>, <c>1/(1 + cos(x)/2)</c>,
        /// <c>1/(b cos(x) + a sin(x))</c>. Measured against Rubi's suite, the integrals it rates
        /// as a single table lookup were the *worst*-served difficulty band we had, and this
        /// family is a large part of why.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </para>
        /// <para>
        /// <b>The test is the rewrite itself</b>, as for the tangent above: replace every
        /// <c>sin(x)</c> and <c>cos(x)</c> and see whether an <c>x</c> survives. That declines
        /// <c>sin(x) + x</c>, and it declines <c>sin(x) * sin(2x)</c> as well — <c>sin(2x)</c> is
        /// not <c>sin(x)</c>, so an <c>x</c> is left behind. The second is the right answer for
        /// the wrong-looking reason: a product of sines is a sum by the product-to-sum identity
        /// and wants that rather than a rational function in <c>t</c>.
        /// </para>
        /// <para>
        /// <b>It runs after the tangent substitution</b>, which is the more specific tool: an
        /// integrand that is rational in <c>tan(x)</c> comes out of that one in terms of the
        /// tangent, where this one would answer it in terms of the half-angle and be right but
        /// unrecognisable.
        /// </para>
        /// <para>
        /// <b>The condition the answer inherits.</b> <c>tan(x/2)</c> is undefined at odd
        /// multiples of pi, so the antiderivative this produces is an antiderivative on each
        /// interval between them rather than across one — the constant may differ from one
        /// interval to the next. That is the standing property of this substitution and is the
        /// same one <see cref="SolveByTangentSubstitution"/> already carries; it is not a claim
        /// this rule makes and does not make the value wrong where it is defined.
        /// </para>
        /// </remarks>
        internal static Entity? SolveByHalfAngleSubstitution(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // One argument linear in x for every trigonometric function of x, `a x + b` as
            // well as `x`: with `t = tan((a x + b)/2)`, `dx` is `2 dt/(a (1 + t^2))`. Hearn's
            // `sin(a x)/(b + c sin(a x))^2` was declined for the `a`, with the scaling of the
            // variable, the rule for it, at the end of the chain and refusing three symbols.
            Entity? argument = null;
            foreach (var node in expr.Nodes)
            {
                if (TrigonometricArgument(node) is not { } thisArgument || !thisArgument.ContainsNode(x))
                    continue;
                if (argument is null)
                    argument = thisArgument;
                else if (argument != thisArgument)
                    return null;
            }
            if (argument is null || !TreeAnalyzer.TryGetPolyLinear(argument, x, out var rate, out var offsetOfArgument)
                || rate.ContainsNode(x) || TreeAnalyzer.IsZero(rate))
                return null;
            var sine = MathS.Sin(argument);
            var cosine = MathS.Cos(argument);
            // The other four functions of x as quotients of the two, wherever either is
            // defined: Timofeev's `1/(3 + 2 sec(x))` is `cos(x)/(3 cos(x) + 2)`, and with the
            // secant left standing it had no sine or cosine for the substitution to read.
            // Only where one of the four is a term of a sum and the whole is rational in the
            // two, which is the shape this rule is for; a product of their powers is the power
            // rules' after this one has declined it, and read here `sec(x)^3 tan(x)^2` was
            // answered in the half-angle tangent, a page long, where the reduction gives it
            // in three terms -- and `tan(x)/(a^3 + b^3 tan(x)^2)^(1/3)` spent three seconds
            // on a cube root of a rational function of t before declining.
            static bool IsOneOfTheFour(Entity node, Entity argument)
                => node is Secantf(var a) && a == argument || node is Cosecantf(var b) && b == argument
                   || node is Tanf(var c) && c == argument || node is Cotanf(var d) && d == argument;
            // And where a sum holds the sine or the cosine to the first power instead:
            // `sec(x)^2/(a + b sin(x))` is no product of powers, and with the secant left standing
            // it was declined at once. Not a power of them: `csc(x)/(a + b sin(x)^2)^2` is even in
            // the sine, a quartic squared in the half-angle tangent, and written in it ran past a
            // minute where with the cosecant standing it is declined in 44 ms.
            if (expr.Nodes.Any(node => node is Sumf or Minusf && node.DirectChildren.Any(term => term.Nodes.Any(inner => IsOneOfTheFour(inner, argument))
                        || Mulf.LinearChildren(term).Any(factor => factor is Sinf(var s) && s == argument || factor is Cosf(var c) && c == argument)))
                && expr.Nodes.All(node => !node.ContainsNode(x)
                    || node is Variable or Sumf or Minusf or Mulf or Divf or Sinf or Cosf or Secantf or Cosecantf or Tanf or Cotanf
                    || node is Powf(_, Number.Integer)))
                expr = expr.Replace(node => node switch
                {
                    Secantf(var a) when a == argument => 1 / cosine,
                    Cosecantf(var a) when a == argument => 1 / sine,
                    Tanf(var a) when a == argument => sine / cosine,
                    Cotanf(var a) when a == argument => cosine / sine,
                    _ => node,
                });
            if (!expr.ContainsNode(sine) && !expr.ContainsNode(cosine))
                return null;

            var t = Variable.CreateUnique(expr, "u_half");
            var tSquared = MathS.Sqr(t);
            var inT = expr
                .Substitute(sine, 2 * t / (1 + tSquared))
                .Substitute(cosine, (1 - tSquared) / (1 + tSquared));
            if (inT.ContainsNode(x))
                return null;

            // Simplify rather than InnerSimplified, and that is not a preference. The rewrite
            // puts a quotient inside a quotient -- 1/cos(x) becomes 1 / ((1 - t^2)/(1 + t^2))
            // times 2/(1 + t^2) -- and partial fractions wants a single Divf of two polynomials.
            // InnerSimplified leaves the nesting alone, so every one of these was handed on in a
            // shape nothing downstream could read and came back unevaluated.
            // Combined into one quotient first, because the rewrite puts a quotient inside a
            // quotient and everything downstream wants a single Divf of two polynomials. Simplify
            // alone does not do it — it never puts a sum over a common denominator, so
            // 1/(1 - sin(x)) rewrote to 2/((t^2 + 1)(1 + (-2)t/(t^2 + 1))) and stopped there, one
            // distribution short of 2/(t^2 - 2t + 1), which is integrated at once.
            // https://github.com/asc-community/AngouriMath/issues/1239
            // Once combined, a quotient with a symbol in its coefficients is not simplified: the
            // simplifier's search grows with the symbols, and `sec(x)^2/(a + b cos(x))^3` spent 43 s
            // in it where integrating what it returned took a tenth of a second. Two things the
            // simplifier did are done here, since what follows reads them. Whole powers of
            // products are written as products of powers: `((1 + t^2)(1 - t^2))^6` keeps the
            // `1 + t^2` the division below takes off as a factor out of its sight, and
            // `tan(x)^6/(a + b sec(x))` was declined that way. And a base of a lower degree than it
            // is written in is written as its polynomial: `a (1 + t^2) + a (1 - t^2)` is `2 a`, and
            // read as a quadratic its leading coefficient is zero as a value only. Only for a
            // rational function of t: under a root the simplifier's writing of the radicand is
            // what the radical rules read, and `1/(b cos(x) + c sin(x) - sqrt(b^2 + c^2))^(3/2)`
            // went from a decline in three seconds to a search past two minutes without it.
            var combined = Functions.SingleQuotient.Combine(inT * 2 / (rate * (1 + tSquared)));
            Entity integrand;
            if (combined.Vars.Any(symbol => symbol != t)
                && !combined.Nodes.Any(node => node is Powf(var radicand, var power) && radicand.ContainsNode(t) && power.Evaled is not Number.Integer))
            {
                var (combinedAbove, combinedBelow) = Functions.SingleQuotient.Of(combined.InnerSimplified);
                integrand = (WithDegenerateBasesLowered(WithWholePowersDistributed(combinedAbove), t)
                    / WithDegenerateBasesLowered(WithWholePowersDistributed(combinedBelow), t)).InnerSimplified;
            }
            else
                integrand = combined.Simplify();

            // Collapsing the nesting attaches a condition saying the denominator it cleared is
            // non-zero, and that denominator is 1 + t^2 -- so 1/(1 + cos(x)) comes out as
            // `1 provided not 1 + t^2 = 0`, which is the answer with a guard on it. The guard is
            // dropped, and it is worth being exact about why rather than calling it vacuous:
            // 1 + t^2 is at least 1 for every *real* t and vanishes at t = +-i, so the condition
            // is not vacuous over the complex plane, which is this library's default codomain.
            //
            // It is sound to drop here because of what t is. The substitution is t = tan(x/2),
            // which this rule only reaches by rewriting a real trigonometric integrand; the
            // excluded points are not reachable values of it, and they do not appear in the
            // answer, which is written back in terms of x. The same strip is made for the same
            // reason in SolveBySubstitution.
            //
            // What this does *not* do is assume a condition away in general: the answer is still
            // an antiderivative on each interval between the poles of tan(x/2), which is the
            // standing caveat on this substitution and is recorded in the summary above.
            if (integrand is Providedf(var inner, _))
                integrand = inner;

            // Every sine and cosine brought its own `1 + t^2` below the bar, and clearing them
            // puts the same power of it above and below -- where the simplifier does not see
            // it once the denominator is a sum, `(1 + t^2)(1 - t^2 + 2t) + sqrt(2)(1 + t^2)^2`
            // for `1/(cos(x) + sin(x) + sqrt(2))`. Divided out by long division, as many times
            // as both sides allow: what is left is `2/((sqrt(2) - 1)t^2 + 2t + 1 + sqrt(2))`, a
            // quadratic below the bar, which was a quartic nothing split.
            var (numerator, denominator) = Functions.SingleQuotient.Of(integrand);
            var divided = false;
            // The remainder comes back over the divisor, `0/(1 + t^2)` when there is none.
            static bool NoRemainder(Entity rest)
                => rest is Divf(var top, _) ? NoRemainder(top) : rest.Evaled is Number.Complex { IsZero: true };
            // Below the bar a power of 1 + t^2 that stands as a factor loses one power, rather
            // than the whole product being divided and multiplied out: `sin(x)^2/(a + b cos(x))`
            // is `8 t^2 (1 + t^2)/((1 + t^2)^3 (a (1 + t^2) + b (1 - t^2)))`, and divided as a whole
            // its denominator was a sextic with a symbol in every coefficient, which nothing splits.
            // Not with the imaginary unit below the bar: `sec(x)^3/(a + i a tan(x))^8` has
            // `(1 + i t)^16` there, and kept whole the partial fractions ground on it past a
            // minute, where multiplied out, as before, it is answered in 5 s.
            var keepFactored = !HoldsTheImaginaryUnit(denominator);
            while (TreeAnalyzer.PolynomialLongDivision(numerator, 1 + tSquared, inTermsOf: t) is var (aboveQuotient, aboveRest)
                   && NoRemainder(aboveRest)
                   && ((keepFactored ? WithOneFactorOfOnePlusTSquaredFewer(denominator, t) : null)
                       ?? (TreeAnalyzer.PolynomialLongDivision(denominator, 1 + tSquared, inTermsOf: t) is var (belowQuotient, belowRest)
                           && NoRemainder(belowRest) ? belowQuotient : null)) is { } reduced)
            {
                numerator = aboveQuotient.InnerSimplified;
                denominator = reduced.InnerSimplified;
                divided = true;
            }
            if (divided)
                integrand = (numerator / denominator).InnerSimplified;

            return Integration.ComputeIndefiniteIntegral(integrand, t, integrateByParts) is { } result
                ? result.Substitute(t, MathS.Tan(argument / 2))
                : null;
        }

        /// <summary>
        /// <paramref name="product"/> with each whole power of a product written as the product
        /// of the powers, the rest as written: <c>((1 + t^2)(1 - t^2))^6</c> is
        /// <c>(1 + t^2)^6 (1 - t^2)^6</c>.
        /// </summary>
        private static Entity WithWholePowersDistributed(Entity product)
        {
            Entity written = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(product))
            {
                if (factor is Powf(Mulf inner, Number.Integer { EInteger.Sign: > 0 } power))
                    foreach (var innerFactor in Mulf.LinearChildren(WithWholePowersDistributed(inner)))
                        written *= innerFactor is Powf(var @base, Number.Integer exponent)
                            ? MathS.Pow(@base, Number.Integer.Create(exponent.EInteger.Multiply(power.EInteger)))
                            : MathS.Pow(innerFactor, power);
                else
                    written *= factor;
            }
            return written;
        }

        /// <summary>
        /// <paramref name="product"/> with each base that is a sum written as its polynomial in
        /// <paramref name="t"/> where that is of a lower degree than the base is written in, and
        /// as written otherwise: <c>a (1 + t^2) + a (1 - t^2)</c> is <c>2 a</c>.
        /// </summary>
        private static Entity WithDegenerateBasesLowered(Entity product, Entity.Variable t)
        {
            Entity written = Number.Integer.One;
            foreach (var factor in Mulf.LinearChildren(product))
            {
                var (@base, power) = factor is Powf(var raised, Number.Integer exponent) ? (raised, (Entity)exponent) : (factor, Number.Integer.One);
                if (@base is Sumf or Minusf && @base.ContainsNode(t) && TreeAnalyzer.TryGetPolynomial(@base, t, out var terms)
                    && terms.Count > 0 && terms.All(term => term.Key.Sign >= 0 && !term.Value.ContainsNode(t)))
                {
                    var writtenDegree = @base.Nodes.Select(node => node is Powf(var raised, Number.Integer exponent) && raised == t ? exponent.EInteger
                        : node == t ? EInteger.One : EInteger.Zero).Max()!;
                    var kept = terms.Where(term => !Functions.PartialFractions.IsZeroAsAValue(term.Value)).ToList();
                    var degree = kept.Select(term => term.Key).DefaultIfEmpty(EInteger.Zero).Max()!;
                    if (degree.CompareTo(writtenDegree) < 0)
                    {
                        Entity polynomial = Number.Integer.Zero;
                        foreach (var term in kept.OrderByDescending(term => term.Key))
                        {
                            var coefficient = term.Value.InnerSimplified;
                            polynomial += term.Key.IsZero ? coefficient : coefficient * MathS.Pow(t, Number.Integer.Create(term.Key));
                        }
                        @base = polynomial.InnerSimplified;
                    }
                }
                written *= power == Number.Integer.One ? @base : MathS.Pow(@base, power);
            }
            return written;
        }

        /// <summary>
        /// <paramref name="denominator"/> with one power fewer of a factor that is
        /// <c>1 + t^2</c>, the rest of the product as written; null where no factor is.
        /// </summary>
        private static Entity? WithOneFactorOfOnePlusTSquaredFewer(Entity denominator, Entity.Variable t)
        {
            var factors = Mulf.LinearChildren(denominator).ToList();
            for (var i = 0; i < factors.Count; i++)
            {
                var (@base, power) = factors[i] is Powf(var raised, Number.Integer { EInteger.Sign: > 0 } whole) && whole.EInteger.CanFitInInt32()
                    ? (raised, whole.EInteger.ToInt32Unchecked()) : (factors[i], 1);
                if (!@base.ContainsNode(t) || !TreeAnalyzer.TryGetPolyQuadratic(@base, t, out var a, out var b, out var c)
                    || a.Evaled is not Number.Complex { IsZero: false } leading || leading != Number.Integer.One
                    || b.Evaled is not Number.Complex { IsZero: true } || c.Evaled is not Number.Complex { IsZero: false } constant || constant != Number.Integer.One)
                    continue;
                factors[i] = power == 1 ? Number.Integer.One : power == 2 ? @base : MathS.Pow(@base, Number.Integer.Create(power - 1));
                return factors.Aggregate((Entity)Number.Integer.One, (product, factor) => product * factor);
            }
            return null;
        }

        /// <summary>
        /// Whether <paramref name="expr"/> is built from exponentials <c>b^(k x + c)</c>, with
        /// <c>b</c> free of x, by the field operations and whole powers, with at least one such
        /// exponential and nothing else of x.
        /// </summary>
        private static bool IsARationalFunctionOfExponentials(Entity expr, Entity.Variable x)
        {
            var anExponential = false;
            foreach (var node in expr.Nodes)
            {
                if (!node.ContainsNode(x))
                    continue;
                switch (node)
                {
                    case Variable or Sumf or Minusf or Mulf or Divf:
                    case Powf(_, Number.Integer):
                        continue;
                    // With a rational slope, as the exponential substitution requires: with a
                    // symbol for the slope that substitution declines, and this search is
                    // what answers `1/(a + b e^(p x))^2`.
                    case Powf(var @base, var exponent) when !@base.ContainsNode(x)
                        && TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out _) && slope.Evaled is Number.Rational:
                        anExponential = true;
                        continue;
                    default:
                        return false;
                }
            }
            // A bare x outside every exponential is a polynomial factor, which is by parts'
            // and not the exponential substitution's: `x e^x` keeps its search.
            if (!anExponential)
                return false;
            var stripped = expr.Replace(node => node is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x) ? Number.Integer.One : node);
            return !stripped.ContainsNode(x);
        }

        /// <summary>
        /// A quotient whose numerator is a constant multiple of its denominator's derivative,
        /// with a symbolic exponent about: <c>c ln(D)</c>, the constant read off the terms.
        /// </summary>
        /// <remarks>
        /// The general substitution answers <c>(x^2 - 1)/(x^3 - 3x)</c> under <c>u = x^3 - 3x</c>,
        /// where the one-level simplification of the quotient by <c>du/dx</c> divides the two
        /// polynomials; with a symbol in the exponent -- Timofeev's
        /// <c>(x^(n - 1) - 1)/(x^n - n x)</c> -- the derivative is written <c>x^n n / x - n</c>,
        /// and neither that quotient nor <c>(x^(n-1) - 1)/(n x^(n-1) - n)</c> is anything the
        /// simplifier reduces. So the numerator and the derivative are read term by term as
        /// a coefficient times a power of <c>x</c>, the powers of <c>x</c> in a term merged
        /// into one, the terms matched by exponent, and the coefficients' quotients asked to
        /// be one constant. https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveALogarithmicDerivativeWithASymbolicExponent(Entity expr, Entity.Variable x)
        {
            if (!TryReadAsQuotient(expr, out var numerator, out var denominator) || !denominator.ContainsNode(x))
                return null;
            if (!expr.Nodes.Any(node => node is Powf(var @base, var exponent) && @base.ContainsNode(x) && !exponent.ContainsNode(x) && exponent.Vars.Any()))
                return null;
            // Over a whole power of the denominator, `c D' / D^k`, the answer is a power too.
            var wholePower = 1;
            if (denominator is Powf(var powered, Number.Integer { EInteger.Sign: > 0 } k) && k.EInteger.CanFitInInt32() && k != Number.Integer.One)
            {
                denominator = powered;
                wholePower = k.EInteger.ToInt32Checked();
            }
            var above = TermsAsPowersOfX(numerator, x);
            var derivative = TermsAsPowersOfX(denominator.Differentiate(x), x);
            if (above is null || derivative is null || above.Count != derivative.Count)
                return null;
            Entity? constant = null;
            foreach (var (coefficient, exponent) in above)
            {
                var matching = derivative.Where(term => Bare((term.Exponent - exponent).Simplify()) == Number.Integer.Zero).ToList();
                if (matching.Count != 1)
                    return null;
                var ratio = Bare((coefficient / matching[0].Coefficient).Simplify());
                if (ratio.ContainsNode(x) || ratio.Nodes.Any(node => node == MathS.NaN))
                    return null;
                if (constant is null)
                    constant = ratio;
                else if (Bare((constant - ratio).Simplify()) != Number.Integer.Zero)
                    return null;
            }
            if (constant is null)
                return null;
            return wholePower == 1
                ? constant * MathS.Ln(denominator)
                : constant / (1 - wholePower) * MathS.Pow(denominator, 1 - wholePower);

            // A quotient of symbols simplifies under `provided not n = 0`, the integrand's
            // own condition; the value is what is compared.
            static Entity Bare(Entity simplified) => simplified is Providedf(var inner, _) ? inner : simplified;

            // Each term of a sum as a coefficient free of x times one power of x, the powers
            // of x in the term merged; null where a term holds x elsewhere.
            static List<(Entity Coefficient, Entity Exponent)>? TermsAsPowersOfX(Entity expr, Entity.Variable x)
            {
                // The derivative arrives under `provided not x = 0`, a condition of the
                // integrand's own domain, and the terms are read beneath it.
                if (expr is Providedf(var bare, _))
                    expr = bare;
                var terms = new List<(Entity, Entity)>();
                foreach (var term in Sumf.LinearChildren(expr))
                {
                    var (numerator, denominator) = Functions.SingleQuotient.Of(term);
                    Entity exponent = Number.Integer.Zero;
                    Entity coefficient = Number.Integer.One;
                    foreach (var (side, underneath) in new[] { (numerator, false), (denominator, true) })
                        foreach (var factor in Mulf.LinearChildren(side))
                        {
                            Entity? power = factor == x ? Number.Integer.One : factor is Powf(var @base, var e) && @base == x ? e : null;
                            if (power is null)
                            {
                                if (factor.ContainsNode(x))
                                    return null;
                                coefficient = underneath ? coefficient / factor : coefficient * factor;
                            }
                            else
                                exponent = underneath ? exponent - power : exponent + power;
                        }
                    terms.Add((coefficient, exponent.InnerSimplified));
                }
                return terms;
            }
        }

        /// <summary>
        /// An exponential of a polynomial beside the polynomial's derivative, with the rest a
        /// function of the polynomial: <c>G^P k P' f(P)</c> is <c>k G^u f(u)</c> under <c>u = P</c>.
        /// Rubi's 2.3, <c>e^(a + b x + c x^2) (b + 2 c x) (a + b x + c x^2)^(n/2)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        /// <remarks>
        /// <see cref="SolveBySubstitution"/> reads this <c>u</c> and does not reach it: for its
        /// own search it writes an exponential of a sum as a product of exponentials, so that
        /// <c>e^(e^x) e^x</c> is <c>e^u du</c>, and <c>e^(a + b x + c x^2)</c> is then
        /// <c>e^a e^(b x) e^(c x^2)</c>, with no <c>P</c> left in it to replace. Declining took
        /// it 24 s. Only a polynomial of degree two or more, whose derivative is a factor of its
        /// own: an exponential of a linear is the table's.
        /// </remarks>
        internal static Entity? SolveByTheExponentAsTheVariable(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            if (expr is not (Mulf or Divf) || AnExponentialOfAPolynomial(expr, x) is not { } exponential)
                return null;
            var polynomial = exponential.Exponent;
            var derivative = polynomial.Differentiate(x);
            Entity? scale = null;
            Entity rest = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                // The derivative, up to a constant, above the bar: a sum, as it is written.
                if (scale is null && !underneath && factor is Sumf or Minusf && factor.ContainsNode(x)
                    && Functions.PartialFractions.Bare((factor / derivative).Simplify()) is var ratio && !ratio.ContainsNode(x)
                    && ratio.Evaled is not Number.Complex { IsZero: true })
                {
                    scale = ratio;
                    continue;
                }
                rest = underneath ? rest / factor : rest * factor;
            }
            if (scale is null)
                return null;
            var u = Variable.CreateUnique(expr, "u");
            var inU = (scale * rest.Replace(node => node == polynomial ? u : node)).InnerSimplified;
            if (inU.ContainsNode(x))
                return null;
            return Integration.ComputeAsAQuestionOfItsOwn(inU, u, integrateByParts)?.Substitute(u, polynomial);
        }

        /// <summary>
        /// An exponential of a multiple of a hyperbolic sine or cosine of a linear, beside a function
        /// of the exponentials of the linear whose quotient by the derivative of that sine or cosine
        /// is a rational function of it: under <c>u = e^L + s e^(-L)</c>, twice the cosine or the
        /// sine, <c>e^(n sinh(L)) cosh(L)</c> is <c>e^(n u/2)/2</c>, <c>e^(n cosh(L)) tanh(L)</c> is
        /// <c>e^(n u/2)/u</c>, onto the exponential integral, and <c>e^(n sinh(L)) sinh(2L)</c> is
        /// <c>u e^(n u/2)/2</c>. The substitution answers the trigonometric ones written as nodes --
        /// <c>e^(n cos(x)) tan(x)</c> is <c>-Ei(n cos(x))</c> -- while a hyperbolic function arrives as
        /// exponentials, and no rule read the sine or cosine in them. Rubi's 6.7.1.
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </summary>
        /// <remarks>
        /// Every exponential of the variable but the outer one is a whole power of <c>w = e^L</c>, with
        /// <c>L</c> the linear their exponents are whole multiples of, compared as polynomials and not
        /// as written; the quotient is written in <c>u = w + s/w</c> by undetermined coefficients and a
        /// check at points, or the rule declines.
        /// </remarks>
        internal static Entity? SolveAnExponentialOfAHyperbolicFunctionBesideItsDerivative(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            bool IsAnExponential(Entity node) => node is Powf(var b, var p) && !b.ContainsNode(x) && p.ContainsNode(x);
            // The outer exponential, above the bar, with exponentials of the variable in its exponent.
            Powf? outer = null;
            Entity rest = Number.Integer.One;
            foreach (var (factor, underneath) in FactorsOfTheIntegrand(expr))
            {
                if (!underneath && outer is null && factor is Powf(var @base, var exponent) && @base == MathS.e && exponent.Nodes.Any(IsAnExponential))
                {
                    outer = (Powf)factor;
                    continue;
                }
                rest = underneath ? rest / factor : rest * factor;
            }
            if (outer is null)
                return null;
            // The exponentials inside it and beside it, each `e^(k L)` with one linear L.
            var multiples = new Dictionary<Entity, ERational>();
            Entity? unitSlope = null, unitOffset = null, unit = null;
            foreach (var node in expr.Nodes)
            {
                if (node == outer || !IsAnExponential(node) || multiples.ContainsKey(node))
                    continue;
                if (node is not Powf(var @base, var exponent) || @base != MathS.e
                    || !TreeAnalyzer.TryGetPolyLinear(exponent, x, out var slope, out var offset) || TreeAnalyzer.IsZero(slope))
                    return null;
                if (unit is null)
                {
                    (unit, unitSlope, unitOffset) = (exponent, slope, offset);
                    multiples[node] = ERational.One;
                    continue;
                }
                if (Functions.PartialFractions.Bare((slope / unitSlope!).Simplify()).Evaled is not Number.Rational ratio || ratio.ERational.IsZero
                    || !IsTheZeroPolynomial((offset - ratio * unitOffset!).InnerSimplified))
                    return null;
                multiples[node] = ratio.ERational;
            }
            if (unit is null || unitSlope is null)
                return null;
            var numerators = EInteger.Zero;
            var denominators = EInteger.One;
            foreach (var multiple in multiples.Values)
            {
                numerators = numerators.Gcd(multiple.Numerator.Abs());
                denominators = denominators.Multiply(multiple.Denominator).Divide(denominators.Gcd(multiple.Denominator));
            }
            var step = ERational.Create(numerators, denominators);
            if (multiples.Values.Any(multiple => multiple.Divide(step).ToLowestTerms().Numerator.Abs().CompareTo(EInteger.FromInt32(8)) > 0))
                return null;
            var w = Variable.CreateUnique(expr, "w_hyp");
            Entity InW(Entity e) => e.Replace(node =>
                node != outer && multiples.TryGetValue(node, out var multiple) ? MathS.Pow(w, Number.Integer.Create(multiple.Divide(step).ToLowestTerms().Numerator)) : node);
            // The exponent `c (w + s/w) + d`: a multiple of the sine or the cosine in w and nothing else.
            if (!TreeAnalyzer.TryGetPolynomial(InW(outer.Exponent), w, out var exponentRead)
                || exponentRead.Keys.Any(degree => degree.Abs().CompareTo(EInteger.One) > 0)
                || exponentRead.Values.Any(coefficient => coefficient.ContainsNode(x))
                || !exponentRead.TryGetValue(EInteger.One, out var c) || !exponentRead.TryGetValue(EInteger.FromInt32(-1), out var cBelow))
                return null;
            int sign;
            if (IsTheZeroPolynomial((cBelow - c).InnerSimplified))
                sign = 1;
            else if (IsTheZeroPolynomial((cBelow + c).InnerSimplified))
                sign = -1;
            else
                return null;
            var d = exponentRead.TryGetValue(EInteger.Zero, out var constantTerm) ? constantTerm : Number.Integer.Zero;
            // du = slope (w - s/w) dx, with u = w + s/w and the slope that of the unit, step L.
            var restInW = InW(rest);
            if (restInW.ContainsNode(x))
                return null;
            var slopeOfW = (Number.Rational.Create(step) * unitSlope).InnerSimplified;
            if (!TryWriteInTheReciprocalVariable(restInW / (slopeOfW * (w - Number.Integer.Create(sign) / w)), w, sign, out var u, out var inU))
                return null;
            var question = (MathS.Pow(MathS.e, c * u + d) * inU).InnerSimplified;
            if (Integration.ComputeAsAQuestionOfItsOwn(question, u, integrateByParts) is not { } answer || answer.Nodes.Any(node => node is Integralf))
                return null;
            var exponentOfW = (Number.Rational.Create(step) * unit).InnerSimplified;
            return Functions.PartialFractions.Bare(answer.InnerSimplified)
                .Substitute(u, MathS.Pow(MathS.e, exponentOfW) + Number.Integer.Create(sign) * MathS.Pow(MathS.e, -exponentOfW));
        }

        /// <summary>
        /// A factor of <paramref name="expr"/>, read through products and quotients, that is a
        /// constant to a polynomial in <paramref name="x"/> of degree two or more, or <see langword="null"/>.
        /// </summary>
        private static Powf? AnExponentialOfAPolynomial(Entity expr, Entity.Variable x) => expr switch
        {
            Mulf(var left, var right) => AnExponentialOfAPolynomial(left, x) ?? AnExponentialOfAPolynomial(right, x),
            Divf(var numerator, var denominator) => AnExponentialOfAPolynomial(numerator, x) ?? AnExponentialOfAPolynomial(denominator, x),
            Powf(var @base, Sumf or Minusf) power when !@base.ContainsNode(x) && power.Exponent.ContainsNode(x)
                && TreeAnalyzer.TryGetPolynomial(power.Exponent, x, out var monomials)
                && monomials.Keys.All(degree => degree.Sign >= 0) && monomials.Keys.Any(degree => degree.CompareTo(EInteger.One) > 0) => power,
            _ => null
        };

        /// <summary>Whether a number with an imaginary part is written in <paramref name="expr"/>.</summary>
        private static bool HoldsTheImaginaryUnit(Entity expr)
            => expr.Nodes.Any(node => node is Number.Complex number && !number.ImaginaryPart.EDecimal.IsZero);

        /// <summary>
        /// A candidate's integrand in its variable simplified one level, or as it is written where
        /// that would bring in the imaginary unit which neither it nor <paramref name="integrand"/>
        /// holds. The one level writes <c>sqrt(-u)</c> as <c>i sqrt(u)</c>, the other root wherever
        /// <c>u</c> is negative, and a candidate is negative on the whole line as often as not:
        /// <c>tanh(x)^2 - 1</c> is, and <c>sqrt(a + b sech(x)) tanh(x)^3</c> under it was
        /// <c>sqrt(a + i b sqrt(u))</c>, where the root written as it was is answered by the
        /// search in <c>u</c>. https://github.com/asc-community/AngouriMath/issues/1370
        /// </summary>
        private static Entity SimplifiedWithoutTheImaginaryUnit(Entity written, Entity integrand)
        {
            var simplified = written.Simplify(1);
            if (simplified is Providedf(var inner, _)) simplified = inner; // TODO: singularities ignored but not handled properly
            return HoldsTheImaginaryUnit(simplified) && !HoldsTheImaginaryUnit(written) && !HoldsTheImaginaryUnit(integrand)
                ? written
                : simplified;
        }

        /// <summary>
        /// Attempts to solve an integral using u-substitution.
        /// Looks for patterns where f(g(x)) * g'(x) can be integrated as F(g(x)).
        /// </summary>
        /// <summary>
        /// Whether <paramref name="expr"/> holds an even root of something in <paramref name="x"/>
        /// other than <paramref name="radicand"/>: the only way it can be real where the radicand is
        /// negative and its own root imaginary.
        /// </summary>
        private static bool HoldsAnEvenRootBesides(Entity expr, Entity radicand, Entity.Variable x)
        {
            foreach (var node in expr.Nodes)
                if (node is Powf(var @base, Number.Rational power) && power.ERational.Denominator.IsEven
                    && @base != radicand && @base.ContainsNode(x))
                    return true;
            return false;
        }

        /// <summary>
        /// Whether every function of <paramref name="u"/> in <paramref name="expr"/> is its tangent
        /// or its cotangent: sums, products, quotients and powers of those, and of anything free of
        /// <paramref name="u"/>.
        /// </summary>
        private static bool IsAFunctionOfTheTangentAlone(Entity expr, Entity.Variable u)
            => expr.Nodes.All(node => node is Sumf or Minusf or Mulf or Divf or Powf or Number or Variable
                || !node.ContainsNode(u)
                || node is Tanf(var argument) && argument == u
                || node is Cotanf(var cotangentArgument) && cotangentArgument == u);

        internal static Entity? SolveBySubstitution(Entity expr, Entity.Variable x, bool integrateByParts = true)
        {
            // A rational function over written linear factors with symbols in their
            // coefficients is the partial fractions', which read the coefficients off the
            // roots: `x^2/((a + b x)(c + d x)(f + g x)^2)` under `u = f/g + x` here was a
            // page of piecewise on the discriminant of the quadratic the other two make.
            if (IsARationalFunction(expr, x) && TryReadAsQuotient(expr, out _, out var writtenBelow) && IsAProductOfSymbolicLinearFactors(writtenBelow, x))
                return null;
            // A rational function of exponentials of linears in x with a whole power of a
            // sum of them in it is the exponential substitution's, exactly and at once, and
            // this search is not the tool for it: `tanh(x)^5/sech(x)^4` arrives as a fifth
            // power of a quotient of sums of `e^(2x)` over a fourth of one of `e^(-x)`, every sum a
            // candidate, and the search spent twenty-two seconds simplifying the quotient of
            // the integrand by each candidate's derivative to decline them all, where
            // `u = e^x` answers it in two. Without such a power -- `e^x/(1 + e^x)` -- the
            // search is quick and its answer, `ln(1 + e^x)`, the one to give.
            if (IsARationalFunctionOfExponentials(expr, x)
                && expr.Nodes.Any(node => node is Powf(var sum, Number.Integer power) && sum is Sumf or Minusf or Mulf or Divf && sum.ContainsNode(x)
                                          && power.EInteger.Abs().CompareTo(EInteger.FromInt32(2)) >= 0))
                return null;
            // And a function of exponentials with a root in it, past a modest size, the same:
            // Timofeev's `cosh(x)(tanh(x) - cosh(2x))/((sinh(x)^2 + sinh(2x)) sqrt(sinh(2x)))`
            // is a dozen sums of exponentials, each a candidate, and a minute of simplifying
            // to decline them all; `u = e^x` and the hyperbolic tangent are the substitutions
            // for it, and they follow this rule.
            if (expr.Complexity > LargestSymbolicIntegrandCollected && HasARadicalOf(expr, x)
                && !expr.Replace(node => node is Powf(var @base, var exponent) && !@base.ContainsNode(x) && exponent.ContainsNode(x) ? Number.Integer.One : node).ContainsNode(x))
                return null;
            // An exponential of a sum is the product of the exponentials, for this search
            // only: `e^(e^x) e^x` arrives as `e^(e^x + x)`, in which `e^x` is a candidate whose
            // derivative divides nothing, and written apart it is `e^u du`. Where two or more
            // terms of the exponent hold x; a constant term is left where it is.
            expr = expr.Replace(node =>
            {
                if (node is not Powf(var @base, var exponent) || exponent is not (Sumf or Minusf) || @base.ContainsNode(x)
                    || Sumf.LinearChildren(exponent).Count(term => term.ContainsNode(x)) < 2)
                    return node;
                Entity product = Number.Integer.One;
                foreach (var term in Sumf.LinearChildren(exponent))
                    product = product == Number.Integer.One ? MathS.Pow(@base, term) : product * MathS.Pow(@base, term);
                return product;
            });
            // Try to find a suitable substitution u = g(x)
            // We need to identify a composite function and check if du/dx appears in the integrand
            var candidates = FindSubstitutionCandidates(expr, x).ToList();
            // Every candidate as written first, and only then the sines and cosines again
            // with the even powers of their complement written in u: `cos(x)/sin(x)` under
            // `u = cos(x)` that way is `ln(1 - cos(x)^2)/2`, and under the sine it is written
            // with, `ln(sin(x))`, which is the answer to give.
            var firstPass = new Dictionary<Entity, Entity>();
            foreach (var complementEvenPowers in new[] { false, true })
            foreach (var u in candidates)
            {
                if (complementEvenPowers && !firstPass.ContainsKey(u))
                    continue;
                var duDx = u.Differentiate(x).InnerSimplified;

                // Under u = x^k the rewriting below takes x^m to u^(m/k) where that is whole
                // and leaves it where it is not, so a polynomial under a root with a power of
                // x that k does not divide keeps its x whatever else happens, and the
                // candidate is refused before its quotient is collected and simplified:
                // Hearn's `(2x^6 + ...)/((2x^2 - 1)^2 sqrt(x^4 + 4x^3 + 2x^2 + 1))` paid a
                // second each for x^3, x^4, x^5 and x^6 to be told so.
                if (u is Powf(var xOfPower, Number.Integer { EInteger.Sign: > 0 } k) && xOfPower == x && k != Number.Integer.One
                    && ARadicandHasAPowerNotDivisibleBy(expr, x, k.EInteger))
                    continue;
                // A sum that stands nowhere but inside a longer sum is a node of the tree
                // and not a subexpression anyone wrote: `1 + 2x^2` and `1 + 2x^2 + 4x^3` are
                // the left-nested partial sums of Hearn's radicand `1 + 2x^2 + 4x^3 + x^4`,
                // and each was half a second of rewriting and simplifying to be refused.
                if (u is Sumf && IsOnlyAPartialSum(expr, u))
                    continue;

                // A candidate that does not vary with x is no substitution at all, and its
                // derivative is zero: dividing the integrand by it gives NaN, which then
                // contains no x and so passes the test below and is returned as the answer.
                // `ln(e)`, picked up as a logarithm anywhere in the integrand, was enough --
                // it is how the antiderivative of x * ln(x) came back holding a NaN.
                if (!u.ContainsNode(x) || duDx.Evaled == 0)
                    continue;

                // A candidate that takes one value at two points, where the quotient by its
                // derivative takes two, is no substitution, whatever the simplifier makes of it:
                // a function of u agrees wherever u does. A sine repeats at pi - theta, a cosine at
                // -theta, a tangent a period on; two pinned evaluations settle it where writing the
                // quotient in u and simplifying it is milliseconds per candidate, and the
                // complement pass below is the same function spelled otherwise. The problems of
                // Rubi's 4.7.2, 4.3.10 and 4.4.10 the integrator answers took a fifth less time.
                if (!complementEvenPowers && TheQuotientDisagreesWhereTheCandidateRepeats(expr, duDx, u, x))
                    continue;

                // Try to express expr as h(u) * du/dx
                // If successful, integral becomes ∫h(u)du
                var uSub = Variable.CreateUnique(expr, "u_sub");

                // Try to divide expr by duDx and check if result is independent of x
                // Replace all occurrences of u's expression with a temporary variable
                // For a power of x, the quotient is collected before the powers of x are
                // rewritten: the rewriting reads written powers, and `1/(x sqrt(P))` over `2x`
                // holds two bare x's that are `x^2` only once collected -- and a bare x is not
                // a power of x^2, so the candidate was refused.
                // Under u = cos(a), an even power of sin(a) is a power of 1 - u^2, and the odd
                // ones are a sine times one; the same the other way round. Written so after the
                // division by du/dx has taken one sine out of `sin(x)/sqrt(1 - sin(x)^6)`, since
                // that is where the sixth power becomes a polynomial in u.
                Entity integrandInU;
                if (complementEvenPowers)
                {
                    // From what the first pass computed, not computed again.
                    var complemented = WithTheComplementInEvenPowers(firstPass[u], u, uSub);
                    if (complemented == firstPass[u])
                        continue;   // nothing the first pass did not see
                    integrandInU = SimplifiedWithoutTheImaginaryUnit(complemented, expr);
                }
                else
                {
                    // For a whole power of x of an integrand of modest size, from the quotient
                    // written as one with its powers of x collected. Modest only, and for one
                    // with symbols in it small: a symbolic partial fraction written as one
                    // quotient is a page, and its simplification took twelve minutes of one
                    // test, where Hearn's `1/(r sqrt(-alpha^2 - epsilon^2 + 2h r^2 - 2k r^4))`
                    // is a line and `u = r^2` is its substitution. Whole only: `x^(-1/2)`
                    // collected the same way admitted a substitution the by-parts remainder of
                    // `arcsin(sqrt(1 + x) - sqrt(x))` was refused before, and a minute of search
                    // below it.
                    // Under a sine or a cosine, the cotangent, tangent, secant and cosecant of
                    // the same argument are written in the two: `cot(x) sin(x)^9` under `u = sin(x)`
                    // is `cos(x) sin(x)^8`, and the cotangent as written is nothing the
                    // rewriting reads.
                    // Outside a root only: `sqrt(4 sec(x)^2 + 5 tan(x)^2)` written in the cosine
                    // is a root of a quotient by `cos(x)^2`, which the simplification below takes
                    // as a quotient by `cos(x)`, its value on half the line.
                    var trigonometricArgument = u is Sinf or Cosf ? u.DirectChildren.First() : null;
                    var underARoot = new HashSet<Entity>();
                    if (trigonometricArgument is not null)
                        foreach (var node in expr.Nodes)
                            if (node is Powf(_, Number.Rational r) && r is not Number.Integer)
                                foreach (var inside in node.Nodes)
                                    underARoot.Add(inside);
                    var source = trigonometricArgument is null ? expr : expr.Replace(node => underARoot.Contains(node) ? node : node switch
                    {
                        Cotanf(var a) when a == trigonometricArgument => MathS.Cos(a) / MathS.Sin(a),
                        Tanf(var a) when a == trigonometricArgument => MathS.Sin(a) / MathS.Cos(a),
                        Secantf(var a) when a == trigonometricArgument => 1 / MathS.Cos(a),
                        Cosecantf(var a) when a == trigonometricArgument => 1 / MathS.Sin(a),
                        _ => node,
                    });
                    var quotient = u is Powf(var powerOfX, Number.Integer { EInteger.Sign: > 0 } wholePower) && powerOfX == x && wholePower != Number.Integer.One
                        && expr.Complexity <= (expr.Vars.Any(v => v != x) ? LargestSymbolicIntegrandCollected : LargestIntegrandOfferedSums)
                        ? WithThePowersOfXCollected(Functions.SingleQuotient.Combine(expr / duDx), x)
                        : source / duDx;
                    // Under a linear candidate the quotient is the integrand with its argument
                    // renamed, over a constant, and where it is a function of the tangent alone
                    // there is nothing in it for the simplifier to find:
                    // `(a + b tan(e + f x))(A + B tan(e + f x) + C tan(e + f x)^2)/(c + d tan(e + f x))^2`
                    // under `u = e + f x` spent 28 of its 32 s being simplified, nine symbols and
                    // nothing to cancel. Only there: beside a sine, a secant, a logarithm or the
                    // imaginary unit the simplified form is what the rules after this read, and
                    // `cot(c + d x)^8/(a + a sin(c + d x))` went from one second to seventy without it.
                    var inTermsOfU = InTermsOf(quotient, u, uSub, x);
                    integrandInU = !inTermsOfU.ContainsNode(x)
                        && TreeAnalyzer.TryGetPolyLinear(u, x, out var slope, out var offset) && !slope.ContainsNode(x) && !offset.ContainsNode(x)
                        && IsAFunctionOfTheTangentAlone(inTermsOfU, uSub) && !HoldsTheImaginaryUnit(inTermsOfU)
                        ? Functions.PartialFractions.Bare(inTermsOfU.InnerSimplified)
                        : SimplifiedWithoutTheImaginaryUnit(inTermsOfU, expr);
                    // A factor written on both sides of the bar cancelled, where x survived:
                    // the one-level simplification leaves `u/((a w + b)^2 p u)` as it is, and
                    // the candidate was refused for the u it did not cancel.
                    if (integrandInU.ContainsNode(x))
                    {
                        var (top, bottom) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(integrandInU));
                        var cancelled = CancelCommonFactors(top, bottom);
                        if (cancelled != integrandInU && !cancelled.ContainsNode(x))
                        {
                            integrandInU = SimplifiedWithoutTheImaginaryUnit(cancelled, expr);
                        }
                    }
                    // Powers of one base on the two sides of the bar: `e^(c - b^2 x^2)` over the
                    // `e^(-b^2 x^2)` of du/dx is `e^c`, which the one-level simplification leaves as
                    // written, and `e^(c - b^2 x^2) erf(b x)` was refused under `u = erf(b x)` for
                    // the x in it, where `e^(-b^2 x^2) erf(b x)` was answered.
                    // https://github.com/asc-community/AngouriMath/issues/1501
                    // The divisor's factors are spread first, each to the power -1: gathered as it
                    // stands, the whole divisor `2 e^(-(b x)^2) b` is one factor below the bar, with
                    // a base of its own.
                    // For a special function only, which is where the constant in the exponent comes
                    // from: done for every candidate that left an x, it gathered the exponentials of
                    // `1/((c + d x)^3 (a + a tanh(e + f x)))` and simplified them for every one, and
                    // a decline in a third of a second became a timeout.
                    if (integrandInU.ContainsNode(x) && IsASpecialFunction(u))
                    {
                        var (above, below) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(integrandInU));
                        var spread = above;
                        foreach (var factor in Mulf.LinearChildren(below))
                            spread *= MathS.Pow(factor, -1);
                        // Simplified a level, not only inner-simplified, since the gathered exponent
                        // `c - (b x)^2 + (b x)^2` is left standing by the inner simplification -- and
                        // only where a base was gathered at all. Simplified for every candidate that
                        // left an x, it took `x cosh(a + b x) Shi(a + b x)` from a second to a timeout.
                        var gatheredRaw = Patterns.GatherPowersOfOneBase(spread);
                        if (!ReferenceEquals(gatheredRaw, spread)
                            && SimplifiedWithoutTheImaginaryUnit(gatheredRaw, expr) is var gathered && !gathered.ContainsNode(x))
                            integrandInU = gathered;
                    }
                    // A polynomial in x left over under a candidate that is itself a polynomial
                    // is written in the candidate where it is one in it: `(1 - x)^2` is
                    // `1 - 2x + x^2`, and that is `u` for Apostol's `(1 - 2x + x^2)^(1/5)/(1 - x)`,
                    // whose quotient by du/dx is `-u^(1/5)/(2 (1 - x)^2)` and was refused for
                    // the square that is not spelled as the candidate.
                    // For a quotient of modest size: Welz's `1/((3 - 2x)^(41/2) (1 + x + 2x^2)^20)`
                    // offers its quadratic, and expanding the twentieth power to be told it
                    // is not a polynomial in the other was twenty seconds.
                    if (integrandInU.ContainsNode(x) && u is Sumf or Minusf && integrandInU.Complexity <= LargestSymbolicIntegrandCollected
                        && TreeAnalyzer.TryGetPolynomial(u, x, out var candidateMonomials) && candidateMonomials.Keys.Max() is { } candidateDegree
                        && candidateDegree.CompareTo(EInteger.FromInt32(2)) >= 0)
                    {
                        // Over one bar, so that `(1 - x)(2x - 2)` is one polynomial and not two
                        // linears on either side of a nested division.
                        var (aboveTheBar, belowTheBar) = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(integrandInU));
                        var inTheCandidate = WithPolynomialsInTheCandidate(aboveTheBar, u, uSub, x) / WithPolynomialsInTheCandidate(belowTheBar, u, uSub, x);
                        if (inTheCandidate.ContainsNode(x) == false || inTheCandidate != aboveTheBar / belowTheBar)
                        {
                            integrandInU = SimplifiedWithoutTheImaginaryUnit(inTheCandidate, expr);
                        }
                    }
                    // The candidate itself, left over in x as a power of it: under
                    // `u = sqrt(1 - a x)/sqrt(1 + a x)` the quotient of `F^(k u)/(1 - a^2 x^2)` by
                    // du/dx is `F^(k u)` times `-sqrt(1 + a x)/(a sqrt(1 - a x))`, which is
                    // `-1/(a u)` and holds no u as written, and the candidate was refused where the
                    // integral is `-Ei(k ln(F) u)/a`, Rubi's 2.3.
                    // https://github.com/asc-community/AngouriMath/issues/718
                    if (integrandInU.ContainsNode(x) && WithTheCandidatesPowerLeftInX(integrandInU, u, uSub, x) is { } inPowersOfTheCandidate)
                        integrandInU = inPowersOfTheCandidate;
                    if (u is Sinf or Cosf && integrandInU.ContainsNode(x))
                        firstPass[u] = integrandInU;
                }

                // If the result doesn't contain x anymore, we found a valid substitution
                // and we can integrate with respect to u (treating u as a variable)
                // Dividing by a derivative that is zero gives NaN, and NaN contains no x,
                // so it passes the test below and is handed back as the answer. The check
                // on duDx above catches the cases where that is visible without work;
                // this catches the rest, where the derivative is only zero after
                // simplification -- d/dx (sin(x)^2 + cos(x)^2) is written as
                // 2sin(x)cos(x) - 2cos(x)sin(x), which Evaled cannot reduce with x still
                // symbolic. That is how the integral of sin(x)^2 + cos(x)^2 came back as
                // NaN * (sin(x)^2 + cos(x)^2).
                if (integrandInU.Nodes.Any(node => node == MathS.NaN))
                    continue;
                // And a candidate whose integrand holds the imaginary unit where the integrand did
                // not is not taken, whichever step wrote it: `i sqrt(u)` for `sqrt(-u)` is the other
                // root wherever u is negative -- as `tanh(x)^2 - 1` is everywhere, which is how
                // `sqrt(a + b sech(x)) tanh(x)^5` was answered through `i` and was off at every
                // real point. https://github.com/asc-community/AngouriMath/issues/1370
                if (HoldsTheImaginaryUnit(integrandInU) && !HoldsTheImaginaryUnit(expr))
                    continue;

                if (integrandInU.ContainsNode(x))
                    continue;
                if (Integration.ComputeIndefiniteIntegral(integrandInU, uSub, integrateByParts) is { } resultInU)
                {
                    // An even root is not negative wherever it is real, so a sign or a modulus
                    // of it that a rule below put in -- the answer for u > 0 extended by parity
                    // -- is the root itself: `sqrt(x)/sqrt(x + x^2)` under `u = sqrt(x)` is
                    // `2u^2/sqrt(u^2 + u^4)`, answered as `2 sgn(u) sqrt(1 + |u|^2)`, and
                    // `sgn(sqrt(x))` is a sign nothing differentiates.
                    if (u is Powf(var rootOf, Number.Rational evenRoot) && evenRoot.ERational.Denominator.IsEven)
                    {
                        var asTheRoot = resultInU.Replace(node => node switch
                        {
                            Signumf(var argument) when argument == uSub => Number.Integer.One,
                            Absf(var argument) when argument == uSub => uSub,
                            _ => node,
                        });
                        // Only where the root is real, though: the answer below read the sign of
                        // a real u, and where the radicand is negative u is imaginary while the
                        // integrand can still be real, a product of two imaginary factors.
                        // `(1 + sec(x))^(5/2) sqrt(cos(x))` under `t = cos(x)` and `u = sqrt(t)` is
                        // `-2 u^2 (1 + 1/u^2)^(5/2)/sqrt(1 - u^4)`, whose power of a quotient was
                        // taken apart as `(1 + u^2)^(5/2)/|u|^5`, and was answered wrongly
                        // wherever the cosine is negative. So the answer is conditioned on the
                        // radicand, as the factoring below conditions its own.
                        if (asTheRoot != resultInU)
                            return Functions.PartialFractions.Bare(asTheRoot).Substitute(uSub, u).Provided(rootOf >= Number.Integer.Zero);
                        // And a rule below can take u real without reading its sign: `sqrt(u^4)`
                        // written as `u^2` is the other root wherever u is imaginary. That matters
                        // only where the integrand is real with the radicand negative, which takes
                        // a second even root imaginary beside this one, so there the answer is
                        // checked where the integrand is real: `sqrt(cos(x))/sqrt(1 + sec(x))` under
                        // `t = cos(x)` and `u = sqrt(t)` came back negated wherever the cosine is
                        // negative. https://github.com/asc-community/AngouriMath/issues/1581
                        var answer = resultInU.Substitute(uSub, u);
                        if (HoldsAnEvenRootBesides(expr, rootOf, x) && Functions.PartialFractions.DerivativeDiffersWhereReal(answer, expr, x))
                            return Functions.PartialFractions.Bare(answer).Provided(rootOf >= Number.Integer.Zero);
                        return answer;
                    }
                    // Substitute back: replace u with g(x)
                    return resultInU.Substitute(uSub, u);
                }

                // A power of u under a root -- `1/sqrt(u^2 (3 - 3u^2 + u^4))`, which is
                // `sin(x)/sqrt(1 - sin(x)^6)` under `u = cos(x)` -- comes out of the root as
                // `|u|`, and the rule for that takes `|u| = u`: what it answers holds for
                // `u > 0`, and is extended to `u < 0` by parity where the integrand has one, as
                // the reciprocal substitution extends its own. Nothing is known of the sign
                // of a cosine, and this is what makes that not matter.
                // Asked, not volunteered: the factored form is a second search per candidate,
                // and one level down the by-parts remainder of `arcsin(sqrt(1 + x) - sqrt(x))`
                // spent a minute in them.
                if (!Integration.AnsweringTheQuestionAsked)
                    continue;
                var factored = FactorANonnegativeVariableOutOfRadicals(integrandInU, uSub);
                if (factored != integrandInU && !factored.ContainsNode(x)
                    && Integration.ComputeIndefiniteIntegral(factored, uSub, integrateByParts) is { } forPositiveU
                    && !forPositiveU.Nodes.Any(node => node == MathS.NaN))
                {
                    // An even root is not negative where it is real, and what holds for u > 0
                    // is the answer as it stands there; `sqrt(x^(1/3))` under
                    // `1/(sqrt(x) - x^(-1/3))` was extended by parity it did not need, to an
                    // answer with a sign function in it. Where the radicand is negative the root
                    // is imaginary and the identities the factoring used do not hold, so the
                    // answer is conditioned on the radicand, as the linear-radical substitution
                    // conditions its own. https://github.com/asc-community/AngouriMath/issues/718
                    if (u is Powf(var radicand, Number.Rational root) && root.ERational.Denominator.IsEven)
                        return Functions.PartialFractions.Bare(forPositiveU).Substitute(uSub, u)
                            .Provided(radicand >= Number.Integer.Zero);
                    if (ExtendedByParity(integrandInU, forPositiveU, uSub) is { } onBothSides)
                        return onBothSides.Substitute(uSub, u);
                }
            }

            return null;
        }

        /// <summary>
        /// Every product in <paramref name="expr"/> with its powers of <paramref name="x"/>
        /// gathered into one: <c>x sqrt(P) 2 x</c> is <c>2 x^2 sqrt(P)</c>. The power rewriting
        /// of a substitution <c>u = x^r</c> reads written powers, and the quotient of an
        /// integrand by <c>du/dx</c> writes the differential's power beside the integrand's,
        /// where neither alone is a power of <c>u</c>.
        /// </summary>
        private static Entity WithThePowersOfXCollected(Entity expr, Entity.Variable x)
            => expr.Replace(node =>
            {
                // Across the bar of a quotient too: `x^9 sqrt(1 + x^5 + x^10)/(5x^4)` is
                // `x^5 sqrt(...)/5`, and `u = x^5` reads the collected power where it did not
                // read the two.
                if (node is Divf(var top, var bottom))
                {
                    var (topPower, topRest, topPowers) = Split(top);
                    var (bottomPower, bottomRest, bottomPowers) = Split(bottom);
                    if (topPowers + bottomPowers < 2 || bottomPowers == 0)
                        return node;
                    var net = (topPower - bottomPower).InnerSimplified;
                    if (net.Evaled is Number.Real { IsNegative: true })
                        return topRest / (MathS.Pow(x, (-net).InnerSimplified) * bottomRest);
                    if (net.Evaled is Number.Complex { IsZero: true })
                        return topRest / bottomRest;
                    return (net == Number.Integer.One ? x : MathS.Pow(x, net)) * topRest / bottomRest;
                }
                if (node is not Mulf)
                    return node;
                var (total, product, powers) = Split(node);
                if (powers < 2)
                    return node;
                var collected = total.InnerSimplified;
                return (collected == Number.Integer.One ? x : MathS.Pow(x, collected)) * product;

                // The total power of x among the written factors, the product of the rest,
                // and how many factors were powers of x.
                (Entity Power, Entity Remaining, int Count) Split(Entity product)
                {
                    Entity total = Number.Integer.Zero;
                    Entity rest = Number.Integer.One;
                    var count = 0;
                    foreach (var factor in Mulf.LinearChildren(product))
                    {
                        if (factor == x)
                        {
                            total += 1;
                            count++;
                        }
                        else if (factor is Powf(var @base, Number.Rational exponent) && @base == x)
                        {
                            total += exponent;
                            count++;
                        }
                        else
                            rest = rest == Number.Integer.One ? factor : rest * factor;
                    }
                    return (total, rest, count);
                }
            });

        /// <summary>
        /// For <paramref name="u"/> a sine or a cosine, every even power of the other function
        /// of the same argument in <paramref name="expr"/> written as a power of
        /// <c>1 - uSub^2</c>, and every odd one as the function times such a power; the
        /// expression itself where there is nothing to write.
        /// </summary>
        private static Entity WithTheComplementInEvenPowers(Entity expr, Entity u, Entity.Variable uSub)
        {
            Entity argument;
            Entity complement;
            switch (u)
            {
                case Sinf(var a):
                    argument = a;
                    complement = MathS.Cos(a);
                    break;
                case Cosf(var a):
                    argument = a;
                    complement = MathS.Sin(a);
                    break;
                default:
                    return expr;
            }
            // The other four functions of the argument as quotients of the sine and cosine
            // first, and the substituted function as u again where that has written it anew:
            // `sin(x)/sqrt(sec(x) - 1)` under `u = cos(x)` is `-1/sqrt(1/u - 1)`, and with the
            // secant left standing it kept its x.
            var written = expr.Replace(node => node switch
            {
                Secantf(var a) when a == argument => 1 / MathS.Cos(a),
                Cosecantf(var a) when a == argument => 1 / MathS.Sin(a),
                Tanf(var a) when a == argument => MathS.Sin(a) / MathS.Cos(a),
                Cotanf(var a) when a == argument => MathS.Cos(a) / MathS.Sin(a),
                _ => node,
            }).Substitute(u, uSub);
            // Not where that has put the complement under a root: `sqrt(4/cos(x)^2 + ...)`
            // under `u = sin(x)` is a root of a quotient by `cos(x)^2`, and the simplification
            // the substitution runs takes that root as `.../cos(x)`, which is its value where
            // the cosine is positive and its negative elsewhere -- Timofeev's
            // `(sec(x)^2 - 3 sqrt(4 sec(x)^2 + 5 tan(x)^2) tan(x))/(sin(x)^2 (...)^(3/2))` was
            // answered wrongly on half the line that way.
            var oneMinusSquare = 1 - MathS.Sqr(uSub);
            var rewritten = written.Replace(node =>
            {
                if (node is not Powf(var @base, Number.Integer power) || @base != complement
                    || !power.EInteger.CanFitInInt32() || power.EInteger.ToInt32Unchecked() is var n && n < 2)
                    return node;
                var half = n / 2;
                Entity even = half == 1 ? oneMinusSquare : MathS.Pow(oneMinusSquare, half);
                return n % 2 == 0 ? even : complement * even;
            });
            // An even power of the complement under a root is gone by now; one still there is
            // odd, and is refused rather than left to the simplification.
            return rewritten.Nodes.Any(node => node is Powf(var radicalBase, Number.Rational r) && r is not Number.Integer && radicalBase.ContainsNode(complement))
                ? expr
                : rewritten;
        }

        /// <summary>
        /// The substitution <c>u = sin(a)</c> or <c>u = cos(a)</c> where an odd power of the
        /// complement is left standing after the division by <c>du/dx</c>: that power is the
        /// sign of the complement times a power of <c>sqrt(1 - u^2)</c>, and the sign is a
        /// constant on every interval between the zeros of the complement, so the integrand
        /// is that constant times an algebraic function of <c>u</c>, which is integrated, and
        /// the sign goes back in as <c>sgn(cos(a))</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Charlwood's <c>ln(sin(x)) sqrt(1 + sin(x))</c> by parts leaves
        /// <c>-2 cos(x)^2/(sin(x) sqrt(1 + sin(x)))</c>, which under the sine is
        /// <c>-2 cos(x)/(u sqrt(1 + u)) du</c>, a cosine over: it is <c>-2 sgn(cos(x)) sqrt(1 - u)/u</c>,
        /// whose integral is <c>-4 sqrt(1 - u) + 4 atanh(sqrt(1 - u))</c> times the sign. And
        /// Charlwood's <c>cos(x)^2/sqrt(1 + cos(x)^2 + cos(x)^4)</c> under the cosine is
        /// <c>-u^2/(sin(x) sqrt(1 + u^2 + u^4))</c>, which is <c>-sgn(sin(x)) u^2/sqrt(1 - u^6)</c>
        /// once the roots combine, and <c>-sgn(sin(x)) arcsin(u^3)/3</c>. Exact wherever the
        /// complement is not zero, the generic case.
        /// </para>
        /// <para>
        /// A rule of its own and late, after the half-angle substitution: inside the general
        /// substitution it answered <c>1/(1 + sin(x))</c> as a sign times a root where the
        /// half-angle substitution gives the tangent of the half angle, and the remainder by
        /// parts left beside that root was nine seconds of search for
        /// <c>ln(sin(x))/(1 + sin(x))</c>, which the tangent answers in a moment. Only where
        /// the complement is a factor of the product and what is left is algebraic in
        /// <c>u</c>: inside a sum, <c>1/(cos(x) + sin(x))</c>, or beside a logarithm of <c>u</c>,
        /// the search with the sign in it ended nowhere.
        /// </para>
        /// https://github.com/asc-community/AngouriMath/issues/718
        /// </remarks>
        internal static Entity? SolveByTheSignOfTheComplement(Entity expr, Entity.Variable x, bool integrateByParts)
        {
            // For an integrand with a root in it: a rational function of the sine and cosine
            // is the half-angle substitution's, answered before this, and Jeffrey's
            // `(-1 + 4 cos(x) + 5 cos(x)^2)/(-1 - 4 cos(x) - 3 cos(x)^2 + 4 cos(x)^3)` paid half
            // a second here on the way to it.
            if (!HasARadicalOf(expr, x))
                return null;
            foreach (var u in expr.Nodes.Where(node => node is Sinf or Cosf && node.ContainsNode(x)).Distinct().ToList())
            {
                var argument = u is Sinf(var sa) ? sa : ((Cosf)u).Argument;
                if (!TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out _))
                    continue;
                var complement = u is Sinf ? MathS.Cos(argument) : MathS.Sin(argument);
                var duDx = u.Differentiate(x).InnerSimplified;
                if (duDx.Evaled == 0)
                    continue;
                var uSub = Variable.CreateUnique(expr, "u_sgn");
                var inU = WithTheComplementInEvenPowers(InTermsOf(expr / duDx, u, uSub, x).Simplify(1), u, uSub);
                if (inU is Providedf(var bare, _)) inU = bare;
                if (!inU.ContainsNode(complement))
                    continue;
                // The complement as a factor of the product only, and what is left algebraic.
                var (top, bottom) = Functions.SingleQuotient.Of(inU);
                if (!Mulf.LinearChildren(top).Concat(Mulf.LinearChildren(bottom))
                        .All(factor => !factor.ContainsNode(complement) || factor == complement || factor is Powf(var oddBase, Number.Integer) && oddBase == complement))
                    continue;
                var sign = Variable.CreateUnique(inU, "sgn_c");
                var withTheSign = inU.Replace(node => node == complement ? sign * MathS.Sqrt(1 - MathS.Sqr(uSub)) : node);
                if (withTheSign.ContainsNode(x) || !IsAlgebraicIn(withTheSign, uSub))
                    continue;
                withTheSign = withTheSign.Simplify(1);
                if (withTheSign is Providedf(var innerSigned, _)) withTheSign = innerSigned;
                if (withTheSign.ContainsNode(x) || withTheSign.Nodes.Any(node => node == MathS.NaN))
                    continue;
                if (Integration.ComputeIndefiniteIntegral(withTheSign, uSub, integrateByParts) is { } signedInU
                    && !signedInU.Nodes.Any(node => node == MathS.NaN))
                    return signedInU.Substitute(sign, MathS.Signum(complement)).Substitute(uSub, u);
            }
            return null;
        }

        /// <summary>
        /// Whether every occurrence of the sum <paramref name="u"/> in <paramref name="expr"/>
        /// is as a summand of a longer sum.
        /// </summary>
        private static bool IsOnlyAPartialSum(Entity expr, Entity u)
        {
            if (expr == u)
                return false;
            foreach (var node in expr.Nodes)
                if (node is not Sumf && node.DirectChildren.Any(child => child == u))
                    return false;
            return true;
        }

        /// <summary>
        /// Whether a polynomial in <paramref name="x"/> of degree at least two under a
        /// fractional power has a power of <paramref name="x"/> that <paramref name="k"/>
        /// does not divide.
        /// </summary>
        private static bool ARadicandHasAPowerNotDivisibleBy(Entity expr, Entity.Variable x, PeterO.Numbers.EInteger k)
        {
            foreach (var node in expr.Nodes)
                if (node is Powf(var radicand, Number.Rational exponent) && exponent is not Number.Integer && radicand.ContainsNode(x)
                    && TreeAnalyzer.TryGetPolynomial(radicand, x, out var monomials) && monomials.Count >= 2)
                    foreach (var power in monomials.Keys)
                        if (!power.Remainder(k).IsZero)
                            return true;
            return false;
        }

        /// <summary>
        /// <paramref name="expr"/> written in terms of <paramref name="uSub"/>, where that stands
        /// for <paramref name="u"/>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Ordinarily that is a plain substitution: the candidate occurs in the integrand, and
        /// replacing it is all that is wanted.
        /// </para>
        /// <para>
        /// <b>A power of the variable is the exception, and it is the one that mattered.</b>
        /// Substituting <c>u = x^2</c> into <c>x / (x^4 + 1)</c> replaces nothing, because
        /// <c>x^4</c> is not written as <c>(x^2)^2</c> and a substitution matches what is
        /// written. So the integrand kept its <c>x</c>, the candidate was rejected, and
        /// <c>int x / (x^4 + 1)</c> came back unevaluated while <c>int x^3 / (x^4 + 1)</c> —
        /// whose substitution does occur — did not.
        /// <a href="https://github.com/asc-community/AngouriMath/issues/233">#233</a>
        /// </para>
        /// <para>
        /// So a power substitution rewrites the other powers of the variable into powers of
        /// itself. For <c>u = x^r</c> the identity is <c>x^n = u^(n/r)</c>, and the rewrite is
        /// made wherever <c>n/r</c> is a whole number — which for a whole <c>r</c> means
        /// <c>r</c> divides <c>n</c>, and is the only case this covered at first.
        /// </para>
        /// <para>
        /// <b>A fractional <c>r</c> is the case that reaches the other way</b>, and it is what
        /// <c>int sqrt(x)/(1 + x^2)</c> needs. There <c>u = sqrt(x)</c>, so <c>r</c> is
        /// <c>1/2</c> and <c>n/r</c> is <c>2n</c> — a whole number for every <c>n</c>, including
        /// the bare <c>x</c> that a whole <c>r</c> can never rewrite. The integrand becomes
        /// <c>2u^2/(1 + u^4)</c>, which is answered.
        /// </para>
        /// <para>
        /// Nothing is assumed by it: the caller still checks that no <c>x</c> survives, so a
        /// rewrite that does not clear the variable leaves the candidate rejected as before.
        /// </para>
        /// </remarks>
        private static Entity InTermsOf(Entity expr, Entity u, Entity.Variable uSub, Entity.Variable x)
        {
            if (u is not Powf(var powerBase, Number.Rational exponent) || powerBase != x)
                return expr.Substitute(u, uSub);
            var r = exponent.ERational;
            if (r.IsZero)
                return expr.Substitute(u, uSub);
            // The written powers of x first, and only then a bare x that is left over. Both in
            // one pass does not work, because Replace rewrites from the leaves up: the x inside
            // sqrt(x) is reached before the sqrt(x) node is, so with u = sqrt(x) it becomes
            // sqrt(u^2) rather than u, and the integrand ends up free of x and no more
            // integrable than it started.
            //
            // The exponent is read as a rational rather than a whole number because the
            // candidate is itself one of these nodes: with u = sqrt(x) the integrand still holds
            // a sqrt(x), and leaving it alone leaves an x that rejects the candidate. Anything
            // else -- x inside a function, or a base that is not x -- is left for the caller's
            // check on whether x survives.
            var written = expr.Replace(node =>
                node is Powf(var otherBase, Number.Rational otherExponent)
                && otherBase == x
                && Rewritten(otherExponent.ERational) is { } power
                    ? power
                    : node);
            return written.Replace(node =>
                node == x && Rewritten(PeterO.Numbers.ERational.One) is { } bare ? bare : node);

            // u^(n/r), where that is a whole power, and null where it is not. Done on the four
            // integers rather than by dividing the rationals and asking whether the result is
            // whole: an ERational quotient is not reduced, so 4/2 answers that question with a
            // denominator of two and every whole r would be refused.
            //
            // The ceiling is against a tiny r turning a modest power of x into an enormous one,
            // rather than against anything mathematical.
            Entity? Rewritten(PeterO.Numbers.ERational n)
            {
                var scaled = n.Numerator.Multiply(r.Denominator);
                var by = n.Denominator.Multiply(r.Numerator);
                if (by.IsZero || !scaled.Remainder(by).IsZero)
                    return null;
                var whole = scaled.Divide(by);
                if (whole.IsZero || whole.Abs().CompareTo(PeterO.Numbers.EInteger.FromInt32(64)) > 0)
                    return null;
                return whole.Equals(PeterO.Numbers.EInteger.One)
                    ? uSub
                    : MathS.Pow(uSub, Number.Integer.Create(whole));
            }
        }

        /// <summary>
        /// Every polynomial in <paramref name="x"/> in <paramref name="expr"/> of degree at least
        /// that of the polynomial <paramref name="u"/> that is a polynomial in <paramref name="u"/>
        /// with constant coefficients, written as that polynomial in <paramref name="uSub"/>:
        /// <c>F = r_0 + r_1 u + r_2 u^2 + ...</c> by repeated division, taken where every
        /// remainder is a constant.
        /// </summary>
        private static Entity WithPolynomialsInTheCandidate(Entity expr, Entity u, Entity.Variable uSub, Entity.Variable x)
        {
            if (!TreeAnalyzer.TryGetPolynomial(u, x, out var candidateMonomials) || candidateMonomials.Keys.Max() is not { } candidateDegree)
                return expr;
            var degree = candidateDegree.ToInt32Checked();
            return expr.Replace(node =>
            {
                // Small powers only: a written power is expanded to be read, and a large one
                // is a large polynomial to divide for nothing.
                if (node == x || !node.ContainsNode(x)
                    || node.Nodes.Any(inner => inner is Powf(_, var exponent) && (exponent is not Number.Integer wholePower || wholePower.EInteger.Abs().CompareTo(EInteger.FromInt32(4)) > 0))
                    || !TreeAnalyzer.TryGetPolynomial(node, x, out var monomials)
                    || monomials.Keys.Max() is not { } top || top.ToInt32Checked() < degree || top.ToInt32Checked() > 4 * degree)
                    return node;
                Entity? written = null;
                var rest = node;
                for (var power = 0; ; power++)
                {
                    if (!rest.ContainsNode(x))
                    {
                        var last = rest.InnerSimplified;
                        if (!TreeAnalyzer.IsZero(last))
                            written = Term(written, last, power);
                        return written ?? Number.Integer.Zero;
                    }
                    if (TreeAnalyzer.PolynomialLongDivision(rest, u, genericCase: true, inTermsOf: x) is not var (quotient, _))
                        return node;
                    var divided = quotient.Expand().InnerSimplified;
                    var remainder = (rest - divided * u).Expand().InnerSimplified;
                    if (remainder.ContainsNode(x))
                        return node;
                    if (!TreeAnalyzer.IsZero(remainder))
                        written = Term(written, remainder, power);
                    rest = divided;
                }
            });

            Entity Term(Entity? sum, Entity coefficient, int power)
            {
                Entity term = power == 0 ? coefficient
                    : coefficient == Number.Integer.One ? MathS.Pow(uSub, power)
                    : coefficient * MathS.Pow(uSub, power);
                return sum is null ? term : sum + term;
            }
        }

        /// <summary>The largest integrand the substitution rule offers its sums as candidates for.</summary>
        private const int LargestIntegrandOfferedSums = 120;

        /// <summary>
        /// The largest integrand with symbols in it whose quotient by <c>du/dx</c> is written
        /// as one with its powers of <c>x</c> collected, for <c>u</c> a power of <c>x</c>.
        /// </summary>
        private const int LargestSymbolicIntegrandCollected = 40;

        /// <summary>The largest sum the substitution rule offers as a candidate.</summary>
        private const int LargestSumOffered = 30;

        /// <summary>
        /// Finds potential substitution candidates u = g(x) from the expression.
        /// For example, common patterns to try:
        /// 1. f(ax + b) * a  ->  u = ax + b
        /// 2. f(x^n) * x^(n-1)  ->  u = x^n
        /// 3. f(g(x)) * g'(x)  ->  u = g(x)
        /// </summary>
        /// <summary>
        /// The special functions of
        /// <a href="https://github.com/asc-community/AngouriMath/issues/1501">#1501</a>: the error
        /// functions and the exponential, logarithmic, sine, cosine and hyperbolic integrals.
        /// </summary>
        /// <summary>
        /// Set while the terms of a remainder after a special function are asked as questions of
        /// their own, so that the asking is not nested; see <c>TryIntegrateByPartsOnce</c>.
        /// </summary>
        [System.ThreadStatic] private static bool askingTheTermsOfARemainder;

        private static bool IsASpecialFunction(Entity node)
            => node is Entity.Erff or Entity.Erfcf or Entity.Erfif or Entity.Eif or Entity.Lif
                or Entity.Sif or Entity.Cif or Entity.Shif or Entity.Chif;

        /// <summary>
        /// A special function of a linear argument, as <see cref="IsASpecialFunctionOfALinear"/>
        /// reads one, or a positive whole power of one: <c>Si(b x)^2</c>.
        /// </summary>
        private static bool IsASpecialFunctionOfALinearOrAPowerOfOne(Entity factor, Variable x)
            => IsASpecialFunctionOfALinear(factor, x)
                || factor is Powf(var @base, Number.Integer power) && power.EInteger.Sign > 0 && IsASpecialFunctionOfALinear(@base, x);

        /// <summary>
        /// Whether the remainder after differentiating <paramref name="v"/>, a special function of
        /// a linear argument or a power of one, against <paramref name="u"/> is asked term by term
        /// when nothing answers it whole. Of a multiple of <paramref name="x"/>, always. Of
        /// <c>a + b x</c>, where the function's derivative divides by its argument -- <c>Ei</c>,
        /// <c>Si</c>, <c>Ci</c>, <c>Shi</c>, <c>Chi</c> -- since the constant of the factor
        /// integrated beside it is then matched to the linear and the terms are the case without
        /// the offset; and where the function is integrated against itself, the square alone.
        /// Not an error function of <c>a + b x</c> beside anything else: its derivative is a
        /// Gaussian of the shifted argument rather than a quotient by it, a polynomial beside it
        /// stays in every term, and asking them took the decline of <c>(c + d x) erf(a + b x)^2</c>
        /// from six seconds to twenty-four, answering nothing.
        /// https://github.com/asc-community/AngouriMath/issues/1501
        /// </summary>
        private static bool TheRemainderIsAskedTermByTerm(Entity v, Entity u, Variable x)
        {
            var special = v is Powf(var @base, _) ? @base : v;
            if (special.DirectChildren.FirstOrDefault() is not { } argument
                || !TreeAnalyzer.TryGetPolyLinear(argument, x, out _, out var offset))
                return false;
            return TreeAnalyzer.IsZero(offset)
                || special is not (Entity.Erff or Entity.Erfcf or Entity.Erfif)
                || u == special;
        }

        /// <summary>
        /// <paramref name="expr"/> as a constant times <c>ln(x)</c>, the coefficient and
        /// <see langword="true"/>, or <see langword="false"/> where it is not one.
        /// </summary>
        private static (Entity Coefficient, bool IsOne) TheLogarithmOfTheVariable(Entity expr, Variable x)
        {
            static bool IsTheLogarithm(Entity factor, Variable x) => factor is Logf(var logBase, var argument) && logBase == MathS.e && argument == x;
            if (IsTheLogarithm(expr, x))
                return (Number.Integer.One, true);
            if (expr is Mulf(var left, var right))
            {
                if (IsTheLogarithm(right, x) && !left.ContainsNode(x))
                    return (left, true);
                if (IsTheLogarithm(left, x) && !right.ContainsNode(x))
                    return (right, true);
            }
            return (Number.Integer.Zero, false);
        }

        /// <summary>
        /// <paramref name="expr"/> as a polynomial in <paramref name="x"/>, none of whose degrees is
        /// negative, or <see langword="null"/>. <see cref="MathS.TryPolynomial"/> reads <c>x^(-1)</c>
        /// as a monomial as well, and integration by parts against a polynomial differentiates it
        /// until it vanishes, which a negative power never does: each derivative of <c>x^(-1)</c> was
        /// a larger tree than the last, and <c>e^(2x) x^(-1)</c> ran the process out of memory, where
        /// <c>e^(2x)/x</c> is <c>Ei(2x)</c>.
        /// https://github.com/asc-community/AngouriMath/issues/1646
        /// </summary>
        private static Entity? ThePolynomialIn(Entity expr, Variable x)
            => TreeAnalyzer.TryGetPolynomial(expr, x, out var monomials) && monomials.Keys.All(degree => degree.Sign >= 0)
                ? Simplificator.BuildPoly(monomials, x)
                : null;

        /// <summary>
        /// The factors of <paramref name="expr"/> that are polynomials in <paramref name="x"/> of
        /// positive degree, against the rest: <c>x sin(b x)</c> is <c>x</c> and <c>sin(b x)</c>.
        /// Both halves <see langword="null"/> where either would be empty.
        /// </summary>
        private static (Entity? Polynomial, Entity? Others) ThePolynomialFactor(Entity expr, Variable x)
        {
            Entity? polynomial = null;
            Entity? rest = null;
            foreach (var factor in Mulf.LinearChildren(expr))
                if (factor.ContainsNode(x) && ThePolynomialIn(factor, x) is not null)
                    polynomial = polynomial is null ? factor : polynomial * factor;
                else
                    rest = rest is null ? factor : rest * factor;
            return polynomial is null || rest is null || !rest.ContainsNode(x) ? (null, null) : (polynomial, rest);
        }

        /// <summary>
        /// Whether <paramref name="expr"/> has what the derivative of the special function
        /// <paramref name="special"/> is made of: an exponential of a quadratic in
        /// <paramref name="x"/> for the error functions, something in <paramref name="x"/> below the
        /// bar for the exponential, trigonometric and hyperbolic integrals, whose derivatives
        /// divide by their argument, and a logarithm below the bar for the logarithmic integral.
        /// </summary>
        private static bool TheDifferentialCanBeThere(Entity special, Entity expr, Entity.Variable x)
        {
            var below = Functions.SingleQuotient.Of(Functions.SingleQuotient.Combine(expr)).Denominator;
            return special switch
            {
                Entity.Erff or Entity.Erfcf or Entity.Erfif => expr.Nodes.Any(node => node is Powf(var @base, var exponent)
                    && !@base.ContainsNode(x) && TreeAnalyzer.TryGetPolyQuadratic(exponent, x, out var square, out _, out _) && !TreeAnalyzer.IsZero(square)),
                Entity.Lif => below.Nodes.Any(node => node is Logf(_, var antilogarithm) && antilogarithm.ContainsNode(x)),
                _ => below.ContainsNode(x),
            };
        }

        private static IEnumerable<Entity> FindSubstitutionCandidates(Entity expr, Entity.Variable x)
        {
            var candidates = new List<Entity>();
            var complements = new List<Entity>();
            // A sum is no candidate for a rational function: whatever `u = g(x)` with `g` a
            // polynomial would find in one, partial fractions find without it, and each
            // candidate costs one simplification of the quotient -- which, with an irrational
            // constant in the coefficients, is where `(1 + t^2)/((sqrt(2) - 1) t^2 + 2t + 1 + sqrt(2))`
            // spent eight seconds being declined by this rule before the rational integrator
            // answered it in a few milliseconds. The base of a written power stays a candidate
            // for a *polynomial*, since `x (x^2 + 1)^3` is answered as a power that way and as
            // a degree-eight polynomial otherwise; for a quotient it goes the way of the sums --
            // `(t^2 + t + 1)^2` below the bar is one more simplification of a rational function
            // for nothing, and Timofeev's `(1 + x^4)/((1 + x + x^2) sqrt(2 + x + x^2))` spent
            // thirteen of its fourteen seconds on those, over the rational functions Euler's
            // substitution and by parts handed down.
            var rational = IsRationalIn(expr, x);
            var polynomial = rational && TreeAnalyzer.TryGetPolynomial(expr, x, out _);
            // Nor a sum past a certain size: each sum candidate is one simplification of the
            // quotient, and the sums in the hundred-node remainders a by-parts step hands
            // down -- `x^3 + 3x^2 sqrt(x^2 + 1) + 3x (x^2 + 1) + (x^2 + 1)^(3/2)` was one -- are
            // seconds apiece for nothing; one such remainder of
            // `x ln(1 + x^2) ln(x + sqrt(1 + x^2))/sqrt(1 + x^2)` spent twelve seconds here.
            var large = expr.Complexity > LargestIntegrandOfferedSums;
            // For a rational function `u = x^k` is exact only when every exponent below the bar
            // is a multiple of k and every one above is k - 1 more than one -- the x^(k-1) of
            // du -- so the candidate is read off the exponents before the quotient is
            // simplified for it. Each simplification it saves is one to two seconds on the
            // degree-eight rational functions Euler's substitution hands down.
            HashSet<int>? exponentsAbove = null, exponentsBelow = null;
            if (rational && TryReadAsQuotient(expr, out var aboveForPowers, out var belowForPowers)
                && TreeAnalyzer.TryGetPolynomial(aboveForPowers, x, out var aboveRead)
                && TreeAnalyzer.TryGetPolynomial(belowForPowers, x, out var belowRead))
            {
                exponentsAbove = new HashSet<int>(aboveRead.Keys.Where(k => k.CanFitInInt32()).Select(k => k.ToInt32Unchecked()));
                exponentsBelow = new HashSet<int>(belowRead.Keys.Where(k => k.CanFitInInt32()).Select(k => k.ToInt32Unchecked()));
            }
            bool APowerCanBeExact(int k)
                => exponentsAbove is null || exponentsBelow is null
                   || (exponentsBelow.All(e => e % k == 0) && exponentsAbove.All(e => e % k == k - 1));
            // The reciprocal, where it is under a root: `sqrt(1/x + sqrt(1 + 1/x))` is
            // `sqrt(u + sqrt(1 + u))` over `-u^2` under `u = 1/x`, a nested radical of something
            // linear, and `1/x` is written as a quotient that no power candidate reads. Under a
            // root only -- offered for every `/x`, it opened a search on `(x^2 - 10)^(5/2)/x` and
            // `x ln(x)/sqrt(1 + x^2)` that did not return, where each is a second's work
            // without it. And not beside a root of a polynomial in the variable: under the
            // reciprocal that root becomes a root of a reciprocal, which offers the reciprocal
            // back, and `x^(-1/2)` is a candidate of its own that leads the same way -- on the
            // by-parts remainder of `arcsin(sqrt(1 + x) - sqrt(x))` the two alternated to the
            // depth limit, forty seconds where declining takes three.
            var besideARootOfAPolynomial = expr.Nodes.Any(node => node is Powf(var polynomialBase, Number.Rational rootPower) && rootPower is not Number.Integer
                    && polynomialBase.ContainsNode(x) && TreeAnalyzer.TryGetPolynomial(polynomialBase, x, out var radicand)
                    && radicand.Keys.Any(degree => degree.Sign > 0));
            if (!rational && expr.Nodes.Any(node => node is Powf(var radicalBase, Number.Rational radicalPower) && radicalPower is not Number.Integer
                    && radicalBase.Nodes.Any(inner => inner is Divf(_, var divisor) && (divisor == x || divisor is Powf(var pb, Number.Integer) && pb == x)))
                && !besideARootOfAPolynomial)
                candidates.Add(MathS.Pow(x, -1));
            foreach (var node in expr.Nodes) // Look for composite functions (functions of functions)
                switch (node)
                {
                    case TrigonometricFunction:
                        candidates.Add(node); // Trigonometric function itself (for cases like sin(x)*cos(x))
                        if (node.DirectChildren[0] != x && node.DirectChildren[0].ContainsNode(x))
                            candidates.Add(node.DirectChildren[0]); // Trigonometric functions with non-trivial arguments
                        // And the other of the pair, which need not be written to be the
                        // substitution: `sin(x)/sqrt(1 - sin(x)^6)` wants `u = cos(x)`, under
                        // which the sine that is left is the differential and the even powers
                        // of it are `1 - u^2`. Only for a sine or cosine, whose complement is
                        // reached through even powers alone; and after everything written,
                        // since `cos(x)/sin(x)` under `u = cos(x)` is `ln(1 - cos(x)^2)/2`, and
                        // under the sine it is written with, `ln(sin(x))`.
                        if (node is Sinf(var sineArgument) && sineArgument.ContainsNode(x))
                            complements.Add(MathS.Cos(sineArgument));
                        else if (node is Cosf(var cosineArgument) && cosineArgument.ContainsNode(x))
                            complements.Add(MathS.Sin(cosineArgument));
                        break;
                    case Powf(var @base, var exp):
                        // A whole negative power beside a root of a polynomial in the variable
                        // is the reciprocal that the guard above declines, and for its reason:
                        // as a power candidate `x^(-1)` took `sqrt(u - 1)/(u sqrt(u^2 - u))` to
                        // `sqrt(1/u - 1)/(u sqrt(1/u^2 - 1/u))` and back, sixteen levels of
                        // `1/(1/(1/x))` in the answer to Timofeev's `arccsc(x)/(x^2 (x^2 - 1)^(5/2))`.
                        // Beside a root of anything else it stays: Bronstein's
                        // `(5x^2 + 3(e^x + x)^(1/3) + e^x (3x + 2x^2))/(x (e^x + x)^(1/3))` is answered
                        // through it.
                        if (@base == x && (exp is not Number.Integer whole || !whole.EInteger.CanFitInInt32()
                                           || (whole.EInteger.Sign > 0 || !besideARootOfAPolynomial) && APowerCanBeExact(whole.EInteger.ToInt32Unchecked())))
                            candidates.Add(node); // Power expressions x^n
                        // And the roots of that power, which need not occur anywhere to be the
                        // right substitution: `int x / (x^4 + 1)` wants u = x^2, and x^2 appears
                        // nowhere in it. A divisor of the exponent is the condition for the
                        // rewrite to be exact -- see InTermsOf -- so the candidates are exactly
                        // the divisors, and each is still tested by whether it clears the
                        // variable. https://github.com/asc-community/AngouriMath/issues/233
                        if (@base == x
                            && exp is Number.Integer power
                            && power.EInteger.CanFitInInt32()
                            && power.EInteger.ToInt32Checked() is var n
                            && n > 2)
                            for (var divisor = 2; divisor + divisor <= n; divisor++)
                                if (n % divisor == 0 && APowerCanBeExact(divisor))
                                    candidates.Add(MathS.Pow(x, divisor));
                        // Exponential with non-trivial argument
                        if (@base != x && @base.ContainsNode(x) && (!rational || polynomial)) candidates.Add(@base);
                        if (exp != x && exp.ContainsNode(x)) candidates.Add(exp);
                        break;
                    case Logf(_, var antilog):
                        candidates.Add(node); // Logarithm itself (for cases like 1/(x*ln(x)))
                        if (antilog != x && antilog.ContainsNode(x)) candidates.Add(antilog); // Also add the argument if it's not just x
                        break;
                    // A special function itself, as the logarithm is: each has an elementary
                    // derivative, so beside a power of it that derivative is the differential.
                    // `e^(c - b^2 x^2) erf(b x)^n` is `sqrt(pi) e^c/(2b) u^n` under `u = erf(b x)`.
                    // https://github.com/asc-community/AngouriMath/issues/1501
                    // Only where that derivative can be there: an exponential of a quadratic for
                    // the error functions, a divisor in x for the u below the bar of e^u/u, sin(u)/u
                    // and the others, a logarithm below the bar for li. Offered beside anything,
                    // `x cosh(a + b x) Shi(a + b x)` went from a second to ten, simplifying quotients
                    // of exponentials that were never going to lose their x.
                    case var special when IsASpecialFunction(special) && TheDifferentialCanBeThere(special, expr, x):
                        candidates.Add(node);
                        break;
                    case Sumf(var aug, var add) when !rational && !large && node.Complexity <= LargestSumOffered:
                        if (aug.ContainsNode(x) || add.ContainsNode(x)) candidates.Add(node); // Linear expressions ax + b
                        break;
                }
            // Sort by complexity - try simpler substitutions first
            var ordered = candidates.OrderBy(c => c.Complexity).Distinct().ToList();
            foreach (var complement in complements)
                if (!ordered.Contains(complement))
                    ordered.Add(complement);
            return ordered;
        }
    }
}